    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET',
      'status', 400,
      'message', 'Target support rows require exact UUID, version, modified_at, and payload snapshots'
    );
  end if;

  v_target_flowproperty_id := (p_batch#>>'{target,flowproperty,id}')::uuid;
  v_target_flowproperty_version := p_batch#>>'{target,flowproperty,version}';
  v_target_flowproperty_expected_json_ordered :=
    p_batch#>'{target,flowproperty,expected_json_ordered}';
  v_target_unitgroup_id := (p_batch#>>'{target,unitgroup,id}')::uuid;
  v_target_unitgroup_version := p_batch#>>'{target,unitgroup,version}';
  v_target_unitgroup_expected_json_ordered :=
    p_batch#>'{target,unitgroup,expected_json_ordered}';
  v_source_unitgroup_id := (p_batch#>>'{target,source_unitgroup,id}')::uuid;
  v_source_unitgroup_version := p_batch#>>'{target,source_unitgroup,version}';
  v_source_unitgroup_expected_json_ordered :=
    p_batch#>'{target,source_unitgroup,expected_json_ordered}';

  if v_source_unitgroup_id = v_target_unitgroup_id
    and v_source_unitgroup_version = v_target_unitgroup_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET',
      'status', 400,
      'message', 'Source and target unit group row keys must differ'
    );
  end if;

  if v_target_flowproperty_expected_json_ordered
      #>> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:UUID}'
      is distinct from v_target_flowproperty_id::text
    or v_target_flowproperty_expected_json_ordered
      #>> '{flowPropertyDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_target_flowproperty_version
    or v_target_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:UUID}'
      is distinct from v_target_unitgroup_id::text
    or v_target_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_target_unitgroup_version
    or v_source_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:UUID}'
      is distinct from v_source_unitgroup_id::text
    or v_source_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_source_unitgroup_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET',
      'status', 400,
      'message', 'Target support payload roots and embedded UUID/version identities must match their row keys'
    );
  end if;

  begin
    v_target_flowproperty_expected_modified_at :=
      (p_batch#>>'{target,flowproperty,expected_modified_at}')::timestamptz;
    v_target_unitgroup_expected_modified_at :=
      (p_batch#>>'{target,unitgroup,expected_modified_at}')::timestamptz;
    v_source_unitgroup_expected_modified_at :=
      (p_batch#>>'{target,source_unitgroup,expected_modified_at}')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_TARGET',
        'status', 400,
        'message', 'Target expected_modified_at values must be valid timestamps'
      );
  end;

  if jsonb_typeof(p_batch->'actions') is distinct from 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_ACTIONS',
      'status', 400,
      'message', 'actions must be an array'
    );
  end if;

  v_action_count := jsonb_array_length(p_batch->'actions');

  for v_action in
    select action_item.value
    from jsonb_array_elements(p_batch->'actions') as action_item(value)
  loop
    if jsonb_typeof(v_action) is distinct from 'object'
      or not (v_action ?& array[
        'action_id',
        'action',
        'table',
        'id',
        'version',
        'expected_state_code',
        'expected_modified_at',
        'expected_json_ordered',
        'desired_json_ordered',
        'mutation'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_action) as action_key(key)
        where action_key.key <> all (array[
          'action_id',
          'action',
          'table',
          'id',
          'version',
          'expected_state_code',
          'expected_modified_at',
          'expected_json_ordered',
          'desired_json_ordered',
          'mutation'
        ])
      )
      or jsonb_typeof(v_action->'action_id') is distinct from 'string'
      or nullif(btrim(v_action->>'action_id'), '') is null
      or octet_length(v_action->>'action_id') > 512
      or jsonb_typeof(v_action->'action') is distinct from 'string'
      or v_action->>'action' <> 'update_json_ordered'
      or jsonb_typeof(v_action->'table') is distinct from 'string'
      or v_action->>'table' not in ('flowproperties', 'flows', 'processes')
      or jsonb_typeof(v_action->'id') is distinct from 'string'
      or (v_action->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(v_action->'version') is distinct from 'string'
      or (v_action->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
      or jsonb_typeof(v_action->'expected_state_code') is distinct from 'number'
      or v_action->>'expected_state_code' <> '0'
      or jsonb_typeof(v_action->'expected_modified_at') is distinct from 'string'
      or jsonb_typeof(v_action->'expected_json_ordered') is distinct from 'object'
      or jsonb_typeof(v_action->'desired_json_ordered') is distinct from 'object'
      or jsonb_typeof(v_action->'mutation') is distinct from 'object'
      or pg_column_size(v_action->'expected_json_ordered') > 16777216
      or pg_column_size(v_action->'desired_json_ordered') > 16777216
      or pg_column_size(v_action->'mutation') > 1048576
      or v_action->'expected_json_ordered' = v_action->'desired_json_ordered' then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_ACTION',
        'status', 400,
        'message', 'Every action must be an exact allowed draft JSON update'
      );
    end if;

    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_expected_root := case v_action_table
      when 'flowproperties' then 'flowPropertyDataSet'
      when 'flows' then 'flowDataSet'
      when 'processes' then 'processDataSet'
    end;
    v_expected_uuid_path := case v_action_table
      when 'flowproperties' then array[
        'flowPropertyDataSet',
        'flowPropertiesInformation',
        'dataSetInformation',
        'common:UUID'
      ]
      when 'flows' then array[
        'flowDataSet',
        'flowInformation',
        'dataSetInformation',
        'common:UUID'
      ]
      when 'processes' then array[
        'processDataSet',
        'processInformation',
        'dataSetInformation',
        'common:UUID'
      ]
    end;

    if not ((v_action->'expected_json_ordered') ? v_expected_root)
      or not ((v_action->'desired_json_ordered') ? v_expected_root)
      or (v_action->'expected_json_ordered') #>> v_expected_uuid_path
        is distinct from v_action_uuid::text
      or (v_action->'desired_json_ordered') #>> v_expected_uuid_path
        is distinct from v_action_uuid::text
      or (v_action->'expected_json_ordered') #>> array[
        v_expected_root,
        'administrativeInformation',
        'publicationAndOwnership',
        'common:dataSetVersion'
      ] is distinct from v_action_version
      or (v_action->'desired_json_ordered') #>> array[
        v_expected_root,
        'administrativeInformation',
        'publicationAndOwnership',
        'common:dataSetVersion'
      ] is distinct from v_action_version then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_ACTION',
        'status', 400,
        'message', 'Action payload root and embedded UUID/version identity must match its table and row key',
        'details', jsonb_build_object('action_id', v_action->>'action_id')
      );
    end if;

    begin
      perform (v_action->>'expected_modified_at')::timestamptz;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_ACTION',
          'status', 400,
          'message', 'expected_modified_at must be a valid timestamp',
          'details', jsonb_build_object('action_id', v_action->>'action_id')
        );
    end;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(p_batch->'actions') as duplicate_action(value)
    group by duplicate_action.value->>'action_id'
    having count(*) <> 1
  ) or exists (
    select 1
    from jsonb_array_elements(p_batch->'actions') as duplicate_row(value)
    group by
      duplicate_row.value->>'table',
      duplicate_row.value->>'id',
      duplicate_row.value->>'version'
    having count(*) <> 1
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DUPLICATE_ACTION',
      'status', 400,
      'message', 'action_id and table/id/version row keys must be unique'
    );
  end if;

  select
    count(*) filter (where action_item.value->>'table' = 'flowproperties'),
    count(*) filter (where action_item.value->>'table' = 'flows'),
    count(*) filter (where action_item.value->>'table' = 'processes')
  into v_flowproperty_count, v_flow_count, v_process_count
  from jsonb_array_elements(p_batch->'actions') as action_item(value);

  if (v_dimension = 'time' and (
      v_action_count <> 25
      or v_flowproperty_count <> 1
      or v_flow_count <> 10
      or v_process_count <> 14
    ))
    or (v_dimension = 'length_time' and (
      v_action_count <> 27
      or v_flowproperty_count <> 1
      or v_flow_count <> 13
      or v_process_count <> 13
    )) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_COUNTS',
      'status', 400,
      'message', 'Action counts do not match the frozen dimension scope',
      'details', jsonb_build_object(
        'action_count', v_action_count,
        'flowproperty_count', v_flowproperty_count,
        'flow_count', v_flow_count,
        'process_count', v_process_count
      )
    );
  end if;

  select
    (source_action.value->>'id')::uuid,
    source_action.value->>'version',
    source_action.value->'expected_json_ordered'
  into
    v_source_flowproperty_id,
    v_source_flowproperty_version,
    v_source_flowproperty_expected_json_ordered
  from jsonb_array_elements(p_batch->'actions') as source_action(value)
  where source_action.value->>'table' = 'flowproperties';

  select name_item.value->>'#text'
  into v_source_flowproperty_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_source_flowproperty_expected_json_ordered
        #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_source_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_source_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  select name_item.value->>'#text'
  into v_target_flowproperty_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_target_flowproperty_expected_json_ordered
        #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_target_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_target_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  select name_item.value->>'#text'
  into v_source_unitgroup_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_source_unitgroup_expected_json_ordered
        #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_source_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_source_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  select name_item.value->>'#text'
  into v_target_unitgroup_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_target_unitgroup_expected_json_ordered
        #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_target_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_target_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  if nullif(v_source_flowproperty_name, '') is null
    or nullif(v_target_flowproperty_name, '') is null
    or nullif(v_source_unitgroup_name, '') is null
    or nullif(v_target_unitgroup_name, '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Source and target support snapshots require English names'
    );
  end if;

  v_expected_reference := jsonb_build_object(
    '@refObjectId', v_target_unitgroup_id,
    '@type', 'unit group data set',
    '@uri', '../unitgroups/' || v_target_unitgroup_id::text || '.json',
    '@version', v_target_unitgroup_version,
    'common:shortDescription', jsonb_build_object(
      '#text', v_target_unitgroup_name,
      '@xml:lang', 'en'
    )
  );

  if v_target_flowproperty_expected_json_ordered
      #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}'
      is distinct from v_expected_reference then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Target flow property must reference the exact frozen target unit group'
    );
  end if;

  if v_source_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,unitGroupInformation,quantitativeReference,referenceToReferenceUnit}'
      is distinct from '1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Source unit group must retain reference unit internal ID 1'
    );
  end if;

  v_units := v_source_unitgroup_expected_json_ordered
    #> '{unitGroupDataSet,units,unit}';
  v_units := case jsonb_typeof(v_units)
    when 'array' then v_units
    when 'object' then jsonb_build_array(v_units)
    else '[]'::jsonb
  end;

  if jsonb_array_length(v_units) <> 1
    or jsonb_typeof(v_units->0) is distinct from 'object'
    or v_units#>>'{0,@dataSetInternalID}' is distinct from '1'
    or v_units#>>'{0,meanValue}' is distinct from '1.0'
    or v_units#>>'{0,name}' is distinct from
      (case v_dimension when 'time' then 'hr' else 'kmy' end) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Source unit group does not match the frozen conversion unit definition'
    );
  end if;

  v_units := v_target_unitgroup_expected_json_ordered
    #> '{unitGroupDataSet,units,unit}';
  v_units := case jsonb_typeof(v_units)
    when 'array' then v_units
    when 'object' then jsonb_build_array(v_units)
    else '[]'::jsonb
  end;
  v_unit_count := 0;

  for v_unit in
    select unit_item.value
    from jsonb_array_elements(v_units) as unit_item(value)
    where unit_item.value->>'name' =
      (case v_dimension when 'time' then 'hr' else 'kmy' end)
  loop
    v_unit_count := v_unit_count + 1;
    if v_unit->>'@dataSetInternalID' is distinct from '4'
      or jsonb_typeof(v_unit->'meanValue') is distinct from 'string'
      or octet_length(v_unit->>'meanValue') > 128
      or v_unit->>'meanValue' !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
      then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
        'status', 400,
        'message', 'Target unit group conversion unit does not match the frozen factor'
      );
    end if;

    begin
      if (v_unit->>'meanValue')::numeric is distinct from v_factor::numeric then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
          'status', 400,
          'message', 'Target unit group conversion unit does not match the frozen factor'
        );
      end if;
    exception
      when numeric_value_out_of_range or invalid_text_representation then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
          'status', 400,
          'message', 'Target unit group conversion unit must be a finite numeric'
        );
    end;
  end loop;

  if v_unit_count <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Target unit group must contain exactly one frozen conversion unit'
    );
  end if;

  v_exchange_count := 0;

  for v_action in
    select action_item.value
    from jsonb_array_elements(p_batch->'actions') as action_item(value)
  loop
    v_action_id := v_action->>'action_id';
    v_action_table := v_action->>'table';
    v_expected_json_ordered := v_action->'expected_json_ordered';
    v_desired_json_ordered := v_action->'desired_json_ordered';
    v_mutation := v_action->'mutation';
    v_mutation_kind := v_mutation->>'kind';

    if v_action_table = 'flowproperties' then
      if not (v_mutation ?& array['kind'])
        or exists (
          select 1
          from jsonb_object_keys(v_mutation) as mutation_key(key)
          where mutation_key.key <> 'kind'
        )
        or jsonb_typeof(v_mutation->'kind') is distinct from 'string'
        or v_mutation_kind <> 'flowproperty_unitgroup_reference' then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Flow property action requires the exact unit-group-reference mutation contract',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      v_before_reference := v_expected_json_ordered #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}';
      v_after_reference := v_desired_json_ordered #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}';
      v_expected_reference := jsonb_build_object(
        '@refObjectId', v_source_unitgroup_id,
        '@type', 'unit group data set',
        '@uri', '../unitgroups/' || v_source_unitgroup_id::text || '.json',
        '@version', v_source_unitgroup_version,
        'common:shortDescription', jsonb_build_object(
          '#text', v_source_unitgroup_name,
          '@xml:lang', 'en'
        )
      );

      if jsonb_typeof(v_before_reference) is distinct from 'object'
        or jsonb_typeof(v_after_reference) is distinct from 'object'
        or v_before_reference is distinct from v_expected_reference
        or v_after_reference->>'@refObjectId' is distinct from v_target_unitgroup_id::text
        or v_after_reference->>'@version' is distinct from v_target_unitgroup_version
        or v_after_reference is distinct from
          v_target_flowproperty_expected_json_ordered
            #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}'
        or v_expected_json_ordered #- '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}'
          is distinct from
          v_desired_json_ordered #- '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}' then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
          'status', 400,
          'message', 'Flow property desired payload may replace only its exact source unit group reference with the target reference',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

    elsif v_action_table = 'flows' then
      if not (v_mutation ?& array[
          'kind',
          'flow_property_internal_id',
          'source_flowproperty_id',
          'source_flowproperty_version'
        ])
        or exists (
          select 1
          from jsonb_object_keys(v_mutation) as mutation_key(key)
          where mutation_key.key <> all (array[
            'kind',
            'flow_property_internal_id',
            'source_flowproperty_id',
            'source_flowproperty_version'
          ])
        )
        or jsonb_typeof(v_mutation->'kind') is distinct from 'string'
        or v_mutation_kind <> 'flow_flowproperty_reference'
        or jsonb_typeof(v_mutation->'flow_property_internal_id') is distinct from 'string'
        or v_mutation->>'flow_property_internal_id' <> '1'
        or jsonb_typeof(v_mutation->'source_flowproperty_id') is distinct from 'string'
        or (v_mutation->>'source_flowproperty_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(v_mutation->'source_flowproperty_version') is distinct from 'string'
        or v_mutation->>'source_flowproperty_id' is distinct from v_source_flowproperty_id::text
        or v_mutation->>'source_flowproperty_version' is distinct from v_source_flowproperty_version then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Flow action requires one exact indexed alias flow-property reference mutation',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      v_mutation_internal_id := v_mutation->>'flow_property_internal_id';
      v_exchange_path := array[
        'flowDataSet',
        'flowProperties',
        'flowProperty'
      ];
      v_before_exchange := v_expected_json_ordered #> v_exchange_path;
      v_after_exchange := v_desired_json_ordered #> v_exchange_path;
      v_before_reference := v_before_exchange->'referenceToFlowPropertyDataSet';
      v_after_reference := v_after_exchange->'referenceToFlowPropertyDataSet';
      v_expected_reference := jsonb_build_object(
        '@refObjectId', v_source_flowproperty_id,
        '@type', 'flow property data set',
        '@uri', '../flowproperties/' || v_source_flowproperty_id::text || '.json',
        '@version', v_source_flowproperty_version,
        'common:shortDescription', jsonb_build_object(
          '#text', v_source_flowproperty_name,
          '@xml:lang', 'en'
        )
      );

      if jsonb_typeof(v_before_exchange) is distinct from 'object'
        or jsonb_typeof(v_after_exchange) is distinct from 'object'
        or v_before_exchange->>'@dataSetInternalID' is distinct from v_mutation_internal_id
        or v_after_exchange->>'@dataSetInternalID' is distinct from v_mutation_internal_id
        or v_before_exchange->>'meanValue' is null
        or v_after_exchange->>'meanValue' is null
        or octet_length(v_before_exchange->>'meanValue') > 128
        or octet_length(v_after_exchange->>'meanValue') > 128
        or v_before_exchange->>'meanValue' !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$'
        or v_after_exchange->>'meanValue' !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$'
        or jsonb_typeof(v_before_reference) is distinct from 'object'
        or jsonb_typeof(v_after_reference) is distinct from 'object'
        or v_before_reference is distinct from v_expected_reference
        or v_after_reference is distinct from jsonb_build_object(
          '@refObjectId', v_target_flowproperty_id,
          '@type', 'flow property data set',
          '@uri', '../flowproperties/' || v_target_flowproperty_id::text || '.json',
          '@version', v_target_flowproperty_version,
          'common:shortDescription', jsonb_build_object(
            '#text', v_target_flowproperty_name,
            '@xml:lang', 'en'
          )
        )
        or jsonb_set(
          v_desired_json_ordered,
          array_append(v_exchange_path, 'referenceToFlowPropertyDataSet'),
          v_before_reference,
          false
        ) is distinct from v_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
          'status', 400,
          'message', 'Flow desired payload may replace only the indexed alias flow-property reference',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      begin
        if (v_before_exchange->>'meanValue')::numeric <> 1::numeric
          or (v_after_exchange->>'meanValue')::numeric <> 1::numeric then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
            'status', 400,
            'message', 'Singleton flow property references must retain meanValue=1',
            'details', jsonb_build_object('action_id', v_action_id)
          );
        end if;
      exception
        when numeric_value_out_of_range or invalid_text_representation then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
            'status', 400,
            'message', 'Singleton flow property meanValue must be a finite numeric',
            'details', jsonb_build_object('action_id', v_action_id)
          );
      end;

    elsif v_action_table = 'processes' then
      if not (v_mutation ?& array['kind', 'exchanges'])
        or exists (
          select 1
          from jsonb_object_keys(v_mutation) as mutation_key(key)
          where mutation_key.key <> all (array['kind', 'exchanges'])
        )
        or jsonb_typeof(v_mutation->'kind') is distinct from 'string'
        or v_mutation_kind <> 'process_exchange_amounts'
        or jsonb_typeof(v_mutation->'exchanges') is distinct from 'array'
        or jsonb_array_length(v_mutation->'exchanges') = 0 then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Process action requires a non-empty exact exchange mutation list',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      if exists (
        select 1
        from jsonb_array_elements(v_mutation->'exchanges') as duplicate_exchange(value)
        group by duplicate_exchange.value->>'index'
        having count(*) <> 1
      ) or exists (
        select 1
        from jsonb_array_elements(v_mutation->'exchanges') as duplicate_exchange(value)
        group by duplicate_exchange.value->>'internal_id'
        having count(*) <> 1
      ) then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Process exchange indexes and internal IDs must be unique within an action',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      v_normalized_desired := v_desired_json_ordered;

      for v_mutation_exchange in
        select exchange_item.value
        from jsonb_array_elements(v_mutation->'exchanges') as exchange_item(value)
      loop
        if jsonb_typeof(v_mutation_exchange) is distinct from 'object'
          or not (v_mutation_exchange ?& array[
            'index',
            'internal_id',
            'flow_id',
            'flow_version',
            'direction',
            'before_exchange_sha256'
          ])
          or exists (
            select 1
            from jsonb_object_keys(v_mutation_exchange) as exchange_key(key)
            where exchange_key.key <> all (array[
              'index',
              'internal_id',
              'flow_id',
              'flow_version',
              'direction',
              'before_exchange_sha256'
            ])
          )
          or jsonb_typeof(v_mutation_exchange->'index') is distinct from 'number'
          or (v_mutation_exchange->>'index') !~ '^(0|[1-9][0-9]*)$'
          or octet_length(v_mutation_exchange->>'index') > 6
          or jsonb_typeof(v_mutation_exchange->'internal_id') is distinct from 'string'
          or nullif(v_mutation_exchange->>'internal_id', '') is null
          or octet_length(v_mutation_exchange->>'internal_id') > 128
          or jsonb_typeof(v_mutation_exchange->'flow_id') is distinct from 'string'
          or (v_mutation_exchange->>'flow_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or jsonb_typeof(v_mutation_exchange->'flow_version') is distinct from 'string'
          or (v_mutation_exchange->>'flow_version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
          or jsonb_typeof(v_mutation_exchange->'direction') is distinct from 'string'
          or v_mutation_exchange->>'direction' not in ('Input', 'Output')
          or jsonb_typeof(v_mutation_exchange->'before_exchange_sha256') is distinct from 'string'
          or (v_mutation_exchange->>'before_exchange_sha256') !~ '^[a-f0-9]{64}$'
          or not exists (
            select 1
            from jsonb_array_elements(p_batch->'actions') as flow_action(value)
            where flow_action.value->>'table' = 'flows'
              and flow_action.value->>'id' = v_mutation_exchange->>'flow_id'
              and flow_action.value->>'version' = v_mutation_exchange->>'flow_version'
          ) then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_INVALID_MUTATION',
            'status', 400,
            'message', 'Every process exchange locator must be exact and reference a flow action in this batch',
            'details', jsonb_build_object('action_id', v_action_id)
          );
        end if;

        v_mutation_index := (v_mutation_exchange->>'index')::integer;
        v_exchange_path := array[
          'processDataSet',
          'exchanges',
          'exchange',
          v_mutation_index::text
        ];
        v_before_exchange := v_expected_json_ordered #> v_exchange_path;
        v_after_exchange := v_desired_json_ordered #> v_exchange_path;

        if jsonb_typeof(v_before_exchange) is distinct from 'object'
          or jsonb_typeof(v_after_exchange) is distinct from 'object'
          or v_before_exchange->>'@dataSetInternalID' is distinct from v_mutation_exchange->>'internal_id'
          or v_after_exchange->>'@dataSetInternalID' is distinct from v_mutation_exchange->>'internal_id'
          or v_before_exchange#>>'{referenceToFlowDataSet,@refObjectId}' is distinct from v_mutation_exchange->>'flow_id'
          or v_before_exchange#>>'{referenceToFlowDataSet,@version}' is distinct from v_mutation_exchange->>'flow_version'
          or v_after_exchange#>>'{referenceToFlowDataSet,@refObjectId}' is distinct from v_mutation_exchange->>'flow_id'
          or v_after_exchange#>>'{referenceToFlowDataSet,@version}' is distinct from v_mutation_exchange->>'flow_version'
          or v_before_exchange->>'exchangeDirection' is distinct from v_mutation_exchange->>'direction'
          or v_after_exchange->>'exchangeDirection' is distinct from v_mutation_exchange->>'direction'
          or encode(
            extensions.digest(
              convert_to(
                private.dataset_alias_canonical_jsonb_v1(v_before_exchange),
                'UTF8'
              ),
              'sha256'
            ),
            'hex'
          ) is distinct from v_mutation_exchange->>'before_exchange_sha256' then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_MUTATION_EVIDENCE_MISMATCH',
            'status', 400,
            'message', 'Process exchange locator or canonical before hash does not match the expected payload',
            'details', jsonb_build_object(
              'action_id', v_action_id,
              'exchange_index', v_mutation_index
            )
          );
        end if;

        v_before_mean_text := v_before_exchange->>'meanAmount';
        v_after_mean_text := v_after_exchange->>'meanAmount';
        v_before_resulting_text := v_before_exchange->>'resultingAmount';
        v_after_resulting_text := v_after_exchange->>'resultingAmount';

        if jsonb_typeof(v_before_exchange->'meanAmount') is distinct from 'string'
          or jsonb_typeof(v_after_exchange->'meanAmount') is distinct from 'string'
          or jsonb_typeof(v_before_exchange->'resultingAmount') is distinct from 'string'
          or jsonb_typeof(v_after_exchange->'resultingAmount') is distinct from 'string'
          or octet_length(v_before_mean_text) > 128
          or octet_length(v_after_mean_text) > 128
          or octet_length(v_before_resulting_text) > 128
          or octet_length(v_after_resulting_text) > 128
          or v_before_mean_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_after_mean_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_before_resulting_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_after_resulting_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_before_mean_text is distinct from v_before_resulting_text
          or v_after_mean_text is distinct from v_after_resulting_text then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_INVALID_AMOUNT',
            'status', 400,
            'message', 'Listed process exchanges require numeric meanAmount and resultingAmount values',
            'details', jsonb_build_object(
              'action_id', v_action_id,
              'exchange_index', v_mutation_index
            )
          );
        end if;

        begin
          if v_after_mean_text::numeric
              is distinct from v_before_mean_text::numeric * v_factor::numeric
            or v_after_resulting_text::numeric
              is distinct from v_before_resulting_text::numeric * v_factor::numeric then
            return jsonb_build_object(
              'ok', false,
              'code', 'ALIAS_BATCH_INVALID_AMOUNT',
              'status', 400,
              'message', 'Listed process exchange amounts must use the exact frozen factor',
              'details', jsonb_build_object(
                'action_id', v_action_id,
                'exchange_index', v_mutation_index
              )
            );
          end if;
        exception
          when numeric_value_out_of_range or invalid_text_representation then
            return jsonb_build_object(
              'ok', false,
              'code', 'ALIAS_BATCH_INVALID_AMOUNT',
              'status', 400,
              'message', 'Listed process exchange amounts must be finite PostgreSQL numerics',
              'details', jsonb_build_object(
                'action_id', v_action_id,
                'exchange_index', v_mutation_index
              )
            );
        end;

        v_normalized_desired := jsonb_set(
          v_normalized_desired,
          array_append(v_exchange_path, 'meanAmount'),
          v_before_exchange->'meanAmount',
          false
        );
        v_normalized_desired := jsonb_set(
          v_normalized_desired,
          array_append(v_exchange_path, 'resultingAmount'),
          v_before_exchange->'resultingAmount',
          false
        );
        v_exchange_count := v_exchange_count + 1;
      end loop;

      if v_normalized_desired is distinct from v_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
          'status', 400,
          'message', 'Process desired payload may change only listed meanAmount and resultingAmount fields',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;
    end if;
  end loop;

  if (v_dimension = 'time' and v_exchange_count <> 20)
    or (v_dimension = 'length_time' and v_exchange_count <> 39) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_EXCHANGE_COUNT',
      'status', 400,
      'message', 'Listed exchange count does not match the frozen dimension scope',
      'details', jsonb_build_object('exchange_count', v_exchange_count)
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_batch->'actions') as batch_flow(value)
    where batch_flow.value->>'table' = 'flows'
      and not exists (
        select 1
        from jsonb_array_elements(p_batch->'actions') as batch_process(value)
        cross join lateral jsonb_array_elements(
          batch_process.value#>'{mutation,exchanges}'
        ) as process_exchange(value)
        where batch_process.value->>'table' = 'processes'
          and process_exchange.value->>'flow_id' = batch_flow.value->>'id'
          and process_exchange.value->>'flow_version' = batch_flow.value->>'version'
      )
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_MUTATION',
      'status', 400,
      'message', 'Every flow action must be referenced by at least one listed process exchange'
    );
  end if;

  v_request_sha256 := encode(
    extensions.digest(convert_to(p_batch::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_target_flowproperty_sha256 := encode(
    extensions.digest(
      convert_to(v_target_flowproperty_expected_json_ordered::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_target_unitgroup_sha256 := encode(
    extensions.digest(
      convert_to(v_target_unitgroup_expected_json_ordered::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_source_unitgroup_sha256 := encode(
    extensions.digest(
      convert_to(v_source_unitgroup_expected_json_ordered::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  -- Stable table-level write locks close the phantom window between the
  -- support-parent and exact flow/process closure scans and the batch commit.
  -- This internal dimension executor holds these locks only inside the public
  -- full-plan call, whose exception subtransaction covers both dimensions. The
  -- lock wait remains capped at 5 seconds.
  lock table public.flowproperties, public.flows, public.processes
    in share row exclusive mode;

  v_current_row := null;
  v_target_actual_modified_at := null;
  v_target_actual_json_ordered := null;

  select
    target_fp.modified_at,
    target_fp.json_ordered::jsonb,
    to_jsonb(target_fp)
  into
    v_target_actual_modified_at,
    v_target_actual_json_ordered,
    v_current_row
  from public.flowproperties as target_fp
  where target_fp.id = v_target_flowproperty_id
    and target_fp.version = v_target_flowproperty_version
    and target_fp.user_id = v_actor
    and target_fp.state_code = 0
  for share of target_fp;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  if v_target_actual_modified_at is distinct from v_target_flowproperty_expected_modified_at
    or v_target_actual_json_ordered is distinct from v_target_flowproperty_expected_json_ordered then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_TARGET_PRECONDITION_FAILED',
      'status', 409,
      'message', 'Target flow property changed after the alias batch was planned',
      'details', jsonb_build_object('target', 'flowproperty')
    );
  end if;

  v_target_found := false;
  v_source_found := false;

  for v_current_row in
    select to_jsonb(support_ug)
    from public.unitgroups as support_ug
    where support_ug.user_id = v_actor
      and support_ug.state_code = 0
      and (
        (
          support_ug.id = v_target_unitgroup_id
          and support_ug.version = v_target_unitgroup_version
        ) or (
          support_ug.id = v_source_unitgroup_id
          and support_ug.version = v_source_unitgroup_version
        )
      )
    order by support_ug.id, support_ug.version
    for share of support_ug
  loop
    if (v_current_row->>'id')::uuid = v_target_unitgroup_id
      and btrim(v_current_row->>'version') = v_target_unitgroup_version then
      v_target_found := true;
      if (v_current_row->>'modified_at')::timestamptz
          is distinct from v_target_unitgroup_expected_modified_at
        or v_current_row->'json_ordered'
          is distinct from v_target_unitgroup_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_TARGET_PRECONDITION_FAILED',
          'status', 409,
          'message', 'Target unit group changed after the alias batch was planned',
          'details', jsonb_build_object('target', 'unitgroup')
        );
      end if;
    elsif (v_current_row->>'id')::uuid = v_source_unitgroup_id
      and btrim(v_current_row->>'version') = v_source_unitgroup_version then
      v_source_found := true;
      if (v_current_row->>'modified_at')::timestamptz
          is distinct from v_source_unitgroup_expected_modified_at
        or v_current_row->'json_ordered'
          is distinct from v_source_unitgroup_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_SOURCE_SUPPORT_PRECONDITION_FAILED',
          'status', 409,
          'message', 'Source unit group changed after the alias batch was planned'
        );
      end if;
    end if;
  end loop;

  if not v_target_found then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  if not v_source_found then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  for v_action in
    select action_item.value
    from jsonb_array_elements(p_batch->'actions') as action_item(value)
    order by
      case action_item.value->>'table'
        when 'flowproperties' then 1
        when 'flows' then 2
        when 'processes' then 3
      end,
      (action_item.value->>'id')::uuid,
      action_item.value->>'version'
  loop
    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_current_row := null;
    v_actual_state_code := null;
    v_actual_modified_at := null;
    v_actual_json_ordered := null;

    execute format(
      'select t.state_code,
              t.modified_at,
              t.json_ordered::jsonb,
              to_jsonb(t)
         from public.%I as t
        where t.id = $1
          and t.version = $2
          and t.user_id = $3
          and t.state_code = 0
        for update of t',
      v_action_table
    )
      into
        v_actual_state_code,
        v_actual_modified_at,
        v_actual_json_ordered,
        v_current_row
      using v_action_uuid, v_action_version, v_actor;

    if v_current_row is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
        'status', 404,
        'message', 'Dataset not found',
        'details', jsonb_build_object('action_id', v_action->>'action_id')
      );
    end if;

    v_locked_actions := v_locked_actions || jsonb_build_array(
      v_action || jsonb_build_object(
        '_actual_state_code', v_actual_state_code,
        '_actual_modified_at', v_actual_modified_at,
        '_actual_json_ordered', v_actual_json_ordered
      )
    );
  end loop;

  -- A private support row must not already participate in a public, foreign,
  -- or otherwise non-draft parent closure. The source flow-property closure
  -- is checked exactly below because those flows are rewritten. Target-FP and
  -- source/target-UG parents may include additional same-owner draft rows that
  -- are outside this mutation, but no mixed-visibility parent is allowed.
  with support_references as (
    select *
    from (values
      (v_source_flowproperty_id::text, v_source_flowproperty_version),
      (v_target_flowproperty_id::text, v_target_flowproperty_version)
    ) as support_reference(id, version)
  ),
  support_parent_flow_keys as materialized (
    select distinct candidate_flow.id, candidate_flow.version
    from support_references as support_reference
    cross join lateral (
      select dataset_flow.id, dataset_flow.version
      from public.flows as dataset_flow
      where private.dataset_alias_jsonb_array_v1(
          dataset_flow.json_ordered::jsonb
            #> '{flowDataSet,flowProperties,flowProperty}'
        ) @> jsonb_build_array(jsonb_build_object(
          'referenceToFlowPropertyDataSet',
          jsonb_build_object(
            '@refObjectId', support_reference.id,
            '@version', support_reference.version
          )
        ))
    ) as candidate_flow
  )
  select
    exists (
      select 1
      from support_parent_flow_keys
      cross join lateral (
        select
          candidate_parent.json_ordered,
          candidate_parent.user_id,
          candidate_parent.state_code
        from public.flows as candidate_parent
        where candidate_parent.id = support_parent_flow_keys.id
          and candidate_parent.version = support_parent_flow_keys.version
        limit 1
      ) as support_parent_flow
      cross join lateral jsonb_array_elements(
        private.dataset_alias_jsonb_array_v1(
          support_parent_flow.json_ordered::jsonb
            #> '{flowDataSet,flowProperties,flowProperty}'
        )
      ) as support_parent_property(value)
      join support_references as support_reference
        on support_reference.id = support_parent_property.value
          #>> '{referenceToFlowPropertyDataSet,@refObjectId}'
        and support_reference.version = support_parent_property.value
          #>> '{referenceToFlowPropertyDataSet,@version}'
      where (
          support_parent_flow.user_id is distinct from v_actor
          or support_parent_flow.state_code is distinct from 0
        )
    ) or exists (
      select 1
      from public.flowproperties as support_parent_fp
      where (
          (
            support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@refObjectId}' =
              v_source_unitgroup_id::text
            and support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@version}' =
              v_source_unitgroup_version
          ) or (
            support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@refObjectId}' =
              v_target_unitgroup_id::text
            and support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@version}' =
              v_target_unitgroup_version
          )
        )
        and (
          support_parent_fp.user_id is distinct from v_actor
          or support_parent_fp.state_code is distinct from 0
        )
    )
  into v_forbidden_closure_exists;

  if v_forbidden_closure_exists then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_CLOSURE_MISMATCH',
      'status', 409,
      'message', 'Live owner-draft closure does not match the exact submitted batch'
    );
  end if;

  with submitted_flows as materialized (
    select
      (flow_action.value->>'id')::uuid as id,
      flow_action.value->>'version' as version,
      flow_action.value#>>'{mutation,flow_property_internal_id}' as internal_id
    from jsonb_array_elements(p_batch->'actions') as flow_action(value)
    where flow_action.value->>'table' = 'flows'
  ),
  candidate_flow_keys as materialized (
    select dataset_flow.id, dataset_flow.version
    from public.flows as dataset_flow
    where private.dataset_alias_jsonb_array_v1(
        dataset_flow.json_ordered::jsonb
          #> '{flowDataSet,flowProperties,flowProperty}'
      ) @> jsonb_build_array(jsonb_build_object(
        'referenceToFlowPropertyDataSet',
        jsonb_build_object(
          '@refObjectId', v_source_flowproperty_id::text,
          '@version', v_source_flowproperty_version
        )
      ))
  ),
  live_flows as (
    select
      dataset_flow.id,
      btrim(dataset_flow.version::text) as version,
      dataset_flow.user_id,
      dataset_flow.state_code,
      flow_property.value->>'@dataSetInternalID' as internal_id
    from candidate_flow_keys
    cross join lateral (
      -- LIMIT 1 is lossless because (id, version) is the primary key and
      -- keeps the exact recheck as candidate-driven primary-key lookups.
      select
        candidate_flow.id,
        candidate_flow.version,
        candidate_flow.json_ordered,
        candidate_flow.user_id,
        candidate_flow.state_code
      from public.flows as candidate_flow
      where candidate_flow.id = candidate_flow_keys.id
        and candidate_flow.version = candidate_flow_keys.version
      limit 1
    ) as dataset_flow
    cross join lateral jsonb_array_elements(
      private.dataset_alias_jsonb_array_v1(
        dataset_flow.json_ordered::jsonb
          #> '{flowDataSet,flowProperties,flowProperty}'
      )
    ) as flow_property(value)
    where flow_property.value
        #>> '{referenceToFlowPropertyDataSet,@refObjectId}' =
        v_source_flowproperty_id::text
      and flow_property.value
        #>> '{referenceToFlowPropertyDataSet,@version}' =
        v_source_flowproperty_version
  )
  select
    count(*) filter (
      where live_flows.user_id = v_actor
        and live_flows.state_code = 0
    ),
    coalesce(bool_and(
      case
        when live_flows.user_id = v_actor
          and live_flows.state_code = 0 then exists (
            select 1
            from submitted_flows
            where submitted_flows.id = live_flows.id
              and submitted_flows.version = live_flows.version
              and submitted_flows.internal_id = live_flows.internal_id
          )
        else true
      end
    ), true),
    coalesce(bool_or(
      live_flows.user_id is distinct from v_actor
        or live_flows.state_code is distinct from 0
    ), false)
  into
    v_live_flow_closure_count,
    v_closure_exact,
    v_forbidden_closure_exists
  from live_flows;

  if v_forbidden_closure_exists
    or v_live_flow_closure_count not in (0, v_flow_count)
    or not v_closure_exact then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_CLOSURE_MISMATCH',
      'status', 409,
      'message', 'Live owner-draft closure does not match the exact submitted batch'
    );
  end if;

  with submitted_flows as materialized (
    select
      flow_action.value->>'id' as id,
      flow_action.value->>'version' as version
    from jsonb_array_elements(p_batch->'actions') as flow_action(value)
    where flow_action.value->>'table' = 'flows'
  ),
  candidate_process_keys as materialized (
    select distinct candidate_process.id, candidate_process.version
    from submitted_flows
    cross join lateral (
      select dataset_process.id, dataset_process.version
      from public.processes as dataset_process
      where private.dataset_alias_jsonb_array_v1(
          dataset_process.json_ordered::jsonb
            #> '{processDataSet,exchanges,exchange}'
        ) @> jsonb_build_array(jsonb_build_object(
          'referenceToFlowDataSet',
          jsonb_build_object(
            '@refObjectId', submitted_flows.id,
            '@version', submitted_flows.version
          )
        ))
    ) as candidate_process
  ),
  live_exchanges as (
    select
      dataset_process.id as process_id,
      btrim(dataset_process.version::text) as process_version,
      exchange_item.ordinality - 1 as exchange_index,
      exchange_item.value->>'@dataSetInternalID' as internal_id,
      exchange_item.value#>>'{referenceToFlowDataSet,@refObjectId}' as flow_id,
      exchange_item.value#>>'{referenceToFlowDataSet,@version}' as flow_version,
      exchange_item.value->>'exchangeDirection' as direction,
      dataset_process.user_id,
      dataset_process.state_code
    from candidate_process_keys
    cross join lateral (
      -- LIMIT 1 is lossless because (id, version) is the primary key and
      -- prevents a candidate estimate from choosing a full wide-row hash scan.
      select
        candidate_process.id,
        candidate_process.version,
        candidate_process.json_ordered,
        candidate_process.user_id,
        candidate_process.state_code
      from public.processes as candidate_process
      where candidate_process.id = candidate_process_keys.id
        and candidate_process.version = candidate_process_keys.version
      limit 1
    ) as dataset_process
    cross join lateral jsonb_array_elements(
      private.dataset_alias_jsonb_array_v1(
        dataset_process.json_ordered::jsonb
          #> '{processDataSet,exchanges,exchange}'
      )
    ) with ordinality as exchange_item(value, ordinality)
    join submitted_flows
      on submitted_flows.id =
        exchange_item.value#>>'{referenceToFlowDataSet,@refObjectId}'
      and submitted_flows.version =
        exchange_item.value#>>'{referenceToFlowDataSet,@version}'
  )
  select
    count(distinct (
      live_exchanges.process_id,
      live_exchanges.process_version
    )) filter (
      where live_exchanges.user_id = v_actor
        and live_exchanges.state_code = 0
    ),
    count(*) filter (
      where live_exchanges.user_id = v_actor
        and live_exchanges.state_code = 0
    ),
    coalesce(bool_and(
      case
        when live_exchanges.user_id = v_actor
          and live_exchanges.state_code = 0 then exists (
            select 1
            from jsonb_array_elements(p_batch->'actions') as process_action(value)
            cross join lateral jsonb_array_elements(
              process_action.value#>'{mutation,exchanges}'
            ) as submitted_exchange(value)
            where process_action.value->>'table' = 'processes'
              and process_action.value->>'id' = live_exchanges.process_id::text
              and process_action.value->>'version' = live_exchanges.process_version
              and (submitted_exchange.value->>'index')::integer = live_exchanges.exchange_index
              and submitted_exchange.value->>'internal_id' = live_exchanges.internal_id
              and submitted_exchange.value->>'flow_id' = live_exchanges.flow_id
              and submitted_exchange.value->>'flow_version' = live_exchanges.flow_version
              and submitted_exchange.value->>'direction' = live_exchanges.direction
          )
        else true
      end
    ), true),
    coalesce(bool_or(
      live_exchanges.user_id is distinct from v_actor
        or live_exchanges.state_code is distinct from 0
    ), false)
  into
    v_live_process_closure_count,
    v_live_exchange_closure_count,
    v_closure_exact,
    v_forbidden_closure_exists
  from live_exchanges;

  if v_forbidden_closure_exists
    or v_live_process_closure_count <> v_process_count
    or v_live_exchange_closure_count <> v_exchange_count
    or not v_closure_exact then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_CLOSURE_MISMATCH',
      'status', 409,
      'message', 'Live owner-draft closure does not match the exact submitted batch'
    );
  end if;

  for v_action in
    select locked_item.value
    from jsonb_array_elements(v_locked_actions) as locked_item(value)
  loop
    v_action_id := v_action->>'action_id';
    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_expected_state_code := (v_action->>'expected_state_code')::integer;
    v_expected_modified_at := (v_action->>'expected_modified_at')::timestamptz;
    v_expected_json_ordered := v_action->'expected_json_ordered';
    v_desired_json_ordered := v_action->'desired_json_ordered';
    v_actual_state_code := (v_action->>'_actual_state_code')::integer;
    v_actual_modified_at := (v_action->>'_actual_modified_at')::timestamptz;
    v_actual_json_ordered := v_action->'_actual_json_ordered';
    v_before_sha256 := encode(
      extensions.digest(convert_to(v_expected_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_after_sha256 := encode(
      extensions.digest(convert_to(v_desired_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_prior_audit_id := null;

    select audit_log.id
    into v_prior_audit_id
    from public.command_audit_log as audit_log
    where audit_log.command = v_command
      and audit_log.actor_user_id = v_actor
      and audit_log.target_table = v_action_table
      and audit_log.target_id = v_action_uuid
      and audit_log.target_version = v_action_version
      and audit_log.payload->>'record_type' = 'row'
      and audit_log.payload->>'schema_version' = v_schema_version
      and audit_log.payload->>'plan_sha256' = v_plan_sha256
      and audit_log.payload->>'operation_id' = v_operation_id
      and audit_log.payload->>'batch_id' = v_batch_id
      and audit_log.payload->>'dimension' = v_dimension
      and audit_log.payload->>'factor' = v_factor
      and audit_log.payload->>'target_visibility' = v_target_visibility
      and audit_log.payload->>'batch_request_sha256' = v_request_sha256
      and audit_log.payload->>'hash_algorithm' = 'postgres-jsonb-text-sha256'
      and audit_log.payload->>'exchange_evidence_hash_algorithm' = 'sorted-key-compact-json-v1-sha256'
      and audit_log.payload->>'action_id' = v_action_id
      and audit_log.payload->>'expected_state_code' = v_expected_state_code::text
      and audit_log.payload->'expected_modified_at' = to_jsonb(v_expected_modified_at)
      and audit_log.payload->>'expected_json_ordered_sha256' = v_before_sha256
      and audit_log.payload->>'desired_json_ordered_sha256' = v_after_sha256
      and audit_log.payload->>'mutation_sha256' = encode(
        extensions.digest(convert_to((v_action->'mutation')::text, 'UTF8'), 'sha256'),
        'hex'
      )
      and audit_log.payload->'committed_modified_at' = to_jsonb(v_actual_modified_at)
    order by audit_log.id desc
    limit 1;

    if v_actual_state_code = v_expected_state_code
      and v_actual_modified_at is not distinct from v_expected_modified_at
      and v_actual_json_ordered = v_expected_json_ordered then
      if v_prior_audit_id is not null then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_AUDIT_STATE_CONFLICT',
          'status', 409,
          'message', 'A matching committed audit exists while a row is still at its before state',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;
      v_fresh_count := v_fresh_count + 1;
    elsif v_actual_state_code = v_expected_state_code
      and v_actual_json_ordered = v_desired_json_ordered then
      if v_prior_audit_id is null then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_REPLAY_UNPROVEN',
          'status', 409,
          'message', 'A desired-state row has no exact committed batch audit proof',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;
      v_replay_count := v_replay_count + 1;
      v_audit_rows := v_audit_rows || jsonb_build_array(jsonb_build_object(
        'action_id', v_action_id,
        'table', v_action_table,
        'id', v_action_uuid,
        'version', v_action_version,
        'audit_id', v_prior_audit_id::text
      ));
    else
      v_mismatches := array[]::text[];
      if v_actual_state_code is distinct from v_expected_state_code then
        v_mismatches := array_append(v_mismatches, 'state_code');
      end if;
      if v_actual_modified_at is distinct from v_expected_modified_at then
        v_mismatches := array_append(v_mismatches, 'modified_at');
      end if;
      if v_actual_json_ordered is distinct from v_expected_json_ordered then
        v_mismatches := array_append(v_mismatches, 'json_ordered');
      end if;

      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_PRECONDITION_FAILED',
        'status', 409,
        'message', 'A dataset changed after the alias batch was planned',
        'details', jsonb_build_object(
          'action_id', v_action_id,
          'mismatches', to_jsonb(v_mismatches)
        )
      );
    end if;
  end loop;

  v_summary_audit_id := null;

  select audit_log.id
  into v_summary_audit_id
  from public.command_audit_log as audit_log
  where audit_log.command = v_command
    and audit_log.actor_user_id = v_actor
    and audit_log.target_table is null
    and audit_log.target_id is null
    and audit_log.target_version is null
    and audit_log.payload->>'record_type' = 'batch_summary'
    and audit_log.payload->>'schema_version' = v_schema_version
    and audit_log.payload->>'plan_sha256' = v_plan_sha256
    and audit_log.payload->>'operation_id' = v_operation_id
    and audit_log.payload->>'batch_id' = v_batch_id
    and audit_log.payload->>'dimension' = v_dimension
    and audit_log.payload->>'factor' = v_factor
    and audit_log.payload->>'target_visibility' = v_target_visibility
    and audit_log.payload->>'batch_request_sha256' = v_request_sha256
    and audit_log.payload->>'hash_algorithm' = 'postgres-jsonb-text-sha256'
    and audit_log.payload->>'exchange_evidence_hash_algorithm' = 'sorted-key-compact-json-v1-sha256'
    and audit_log.payload->>'batch_action_count' = v_action_count::text
    and audit_log.payload->>'exchange_count' = v_exchange_count::text
    and audit_log.payload->>'target_flowproperty_sha256' = v_target_flowproperty_sha256
    and audit_log.payload->>'target_unitgroup_sha256' = v_target_unitgroup_sha256
    and audit_log.payload->>'source_unitgroup_sha256' = v_source_unitgroup_sha256
    and audit_log.payload->>'target_flowproperty_expected_state_code' = '0'
    and audit_log.payload->>'target_unitgroup_expected_state_code' = '0'
    and audit_log.payload->>'source_unitgroup_expected_state_code' = '0'
    and audit_log.payload->>'support_owner_user_id' = v_actor::text
  order by audit_log.id desc
  limit 1;

  select count(*)
  into v_existing_audit_count
  from public.command_audit_log as audit_log
  where audit_log.command = v_command
    and audit_log.actor_user_id = v_actor
    and audit_log.payload->>'batch_request_sha256' = v_request_sha256;

  if v_replay_count = v_action_count then
    if v_summary_audit_id is null
      or v_existing_audit_count <> v_action_count + 1 then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_REPLAY_UNPROVEN',
        'status', 409,
        'message', 'Committed audit cardinality does not match the exact batch'
      );
    end if;

    return jsonb_build_object(
      'ok', true,
      'command', v_command,
      'dimension', v_dimension,
      'target_visibility', v_target_visibility,
      'batch_id', v_batch_id,
      'batch_request_sha256', v_request_sha256,
      'row_count', v_action_count,
      'exchange_count', v_exchange_count,
      'summary_audit_id', v_summary_audit_id::text,
      'audit', v_audit_rows,
      'idempotent_replay', true
    );
  end if;

  if v_fresh_count <> v_action_count then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_PARTIAL_STATE',
      'status', 409,
      'message', 'Batch rows are split between before and committed states'
    );
  end if;

  if v_existing_audit_count <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_AUDIT_STATE_CONFLICT',
      'status', 409,
      'message', 'Audit rows already exist for a batch whose datasets remain at the before state'
    );
  end if;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    v_command,
    v_actor,
    null,
    null,
    null,
    jsonb_build_object(
      'record_type', 'batch_summary',
      'schema_version', v_schema_version,
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id,
      'batch_id', v_batch_id,
      'dimension', v_dimension,
      'factor', v_factor,
      'target_visibility', v_target_visibility,
      'batch_request_sha256', v_request_sha256,
      'hash_algorithm', 'postgres-jsonb-text-sha256',
      'exchange_evidence_hash_algorithm', 'sorted-key-compact-json-v1-sha256',
      'batch_action_count', v_action_count,
      'flowproperty_count', v_flowproperty_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count,
      'exchange_count', v_exchange_count,
      'target_flowproperty_id', v_target_flowproperty_id,
      'target_flowproperty_version', v_target_flowproperty_version,
      'target_flowproperty_expected_modified_at', v_target_flowproperty_expected_modified_at,
      'target_flowproperty_expected_state_code', 0,
      'target_flowproperty_sha256', v_target_flowproperty_sha256,
      'target_unitgroup_id', v_target_unitgroup_id,
      'target_unitgroup_version', v_target_unitgroup_version,
      'target_unitgroup_expected_modified_at', v_target_unitgroup_expected_modified_at,
      'target_unitgroup_expected_state_code', 0,
      'target_unitgroup_sha256', v_target_unitgroup_sha256,
      'source_unitgroup_id', v_source_unitgroup_id,
      'source_unitgroup_version', v_source_unitgroup_version,
      'source_unitgroup_expected_modified_at', v_source_unitgroup_expected_modified_at,
      'source_unitgroup_expected_state_code', 0,
      'source_unitgroup_sha256', v_source_unitgroup_sha256,
      'support_owner_user_id', v_actor
    )
  )
  returning id into v_summary_audit_id;

  for v_action in
    select locked_item.value
    from jsonb_array_elements(v_locked_actions) as locked_item(value)
  loop
    v_action_id := v_action->>'action_id';
    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_expected_state_code := (v_action->>'expected_state_code')::integer;
    v_expected_modified_at := (v_action->>'expected_modified_at')::timestamptz;
    v_expected_json_ordered := v_action->'expected_json_ordered';
    v_desired_json_ordered := v_action->'desired_json_ordered';
    v_before_sha256 := encode(
      extensions.digest(convert_to(v_expected_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_after_sha256 := encode(
      extensions.digest(convert_to(v_desired_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_committed_modified_at := null;
    v_committed_json_ordered := null;
    v_committed_version := null;

    execute format(
      'update public.%I as t
          set json_ordered = $1::json,
              modified_at = now()
        where t.id = $2
          and t.version = $3
          and t.user_id = $4
          and t.state_code = $5
          and t.modified_at is not distinct from $6
          and t.json_ordered::jsonb is not distinct from $7
      returning t.modified_at, t.json_ordered::jsonb, t.version::text',
      v_action_table
    )
      into
        v_committed_modified_at,
        v_committed_json_ordered,
        v_committed_version
      using
        v_desired_json_ordered,
        v_action_uuid,
        v_action_version,
        v_actor,
        v_expected_state_code,
        v_expected_modified_at,
        v_expected_json_ordered;

    if v_committed_modified_at is null
      or v_committed_json_ordered is distinct from v_desired_json_ordered
      or v_committed_version is distinct from v_action_version then
      raise exception using
        errcode = 'P0001',
        message = format(
          'Guarded alias batch lost its locked update precondition for action %s',
          v_action_id
        );
    end if;

    insert into public.command_audit_log (
      command,
      actor_user_id,
      target_table,
      target_id,
      target_version,
      payload
    )
    values (
      v_command,
      v_actor,
      v_action_table,
      v_action_uuid,
      v_action_version,
      jsonb_build_object(
        'record_type', 'row',
        'schema_version', v_schema_version,
        'plan_sha256', v_plan_sha256,
        'operation_id', v_operation_id,
        'batch_id', v_batch_id,
        'dimension', v_dimension,
        'factor', v_factor,
        'target_visibility', v_target_visibility,
        'batch_request_sha256', v_request_sha256,
        'hash_algorithm', 'postgres-jsonb-text-sha256',
        'exchange_evidence_hash_algorithm', 'sorted-key-compact-json-v1-sha256',
        'batch_action_count', v_action_count,
        'target_flowproperty_id', v_target_flowproperty_id,
        'target_flowproperty_version', v_target_flowproperty_version,
        'target_unitgroup_id', v_target_unitgroup_id,
        'target_unitgroup_version', v_target_unitgroup_version,
        'source_unitgroup_id', v_source_unitgroup_id,
        'source_unitgroup_version', v_source_unitgroup_version,
        'action_id', v_action_id,
        'action', 'update_json_ordered',
        'mutation_sha256', encode(
          extensions.digest(convert_to((v_action->'mutation')::text, 'UTF8'), 'sha256'),
          'hex'
        ),
        'expected_state_code', v_expected_state_code,
        'expected_modified_at', v_expected_modified_at,
        'expected_json_ordered_sha256', v_before_sha256,
        'desired_json_ordered_sha256', v_after_sha256,
        'committed_modified_at', v_committed_modified_at
      )
    )
    returning id into v_audit_id;

    v_audit_rows := v_audit_rows || jsonb_build_array(jsonb_build_object(
      'action_id', v_action_id,
      'table', v_action_table,
      'id', v_action_uuid,
      'version', v_action_version,
      'audit_id', v_audit_id::text
    ));
  end loop;

  select count(*)
  into v_existing_audit_count
  from public.command_audit_log as audit_log
  where audit_log.command = v_command
    and audit_log.actor_user_id = v_actor
    and audit_log.payload->>'batch_request_sha256' = v_request_sha256;

  if v_existing_audit_count <> v_action_count + 1 then
    raise exception using
      errcode = 'P0001',
      message = 'Guarded alias batch committed an incomplete audit set';
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'dimension', v_dimension,
    'target_visibility', v_target_visibility,
    'batch_id', v_batch_id,
    'batch_request_sha256', v_request_sha256,
    'row_count', v_action_count,
    'exchange_count', v_exchange_count,
    'summary_audit_id', v_summary_audit_id::text,
    'audit', v_audit_rows,
    'idempotent_replay', false
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_alias_batch_guarded(p_batch jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_batch_guarded(p_batch jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_batch_guarded(p_batch jsonb) IS 'Internal owner-draft dimension executor used only by the guarded full-plan RPC. Direct API execution is revoked so time and length_time cannot commit independently; the executor retains exact actor, state, closure, hash, audit, and replay checks for its dimension.';


--
-- Name: cmd_dataset_alias_execution_admit_guarded(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_alias_execution_admit_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '10s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_schema_version constant text := 'dataset-alias-execution-admit.v1';
  v_request_id uuid;
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_token text;
  v_gate_results jsonb;
  v_gate jsonb;
  v_gate_receipt util.dataset_alias_execution_gate_receipts%rowtype;
  v_gate_name text;
  v_expectation_name text;
  v_captured_at timestamp with time zone;
  v_now timestamp with time zone;
  v_gate_results_sha256 text;
  v_admission_request_sha256 text;
  v_nonce text;
  v_nonce_sha256 text;
  v_service_key text;
  v_net_request_id bigint;
  v_dispatch_error jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request is not null and pg_column_size(p_request) > 65536 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ADMISSION_TOO_LARGE',
      'status', 413,
      'message', 'Protected admission request exceeds 64 KiB'
    );
  end if;

  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array[
      'schema_version',
      'request_id',
      'preflight_token',
      'preflight_proof_sha256',
      'gate_results'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_request) as request_key(key)
      where request_key.key <> all (array[
        'schema_version',
        'request_id',
        'preflight_token',
        'preflight_proof_sha256',
        'gate_results'
      ])
    )
    or p_request->>'schema_version' is distinct from v_schema_version
    or jsonb_typeof(p_request->'request_id') is distinct from 'string'
    or (p_request->>'request_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(p_request->'preflight_token') is distinct from 'string'
    or (p_request->>'preflight_token') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_request->'preflight_proof_sha256') is distinct from 'string'
    or (p_request->>'preflight_proof_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_request->'gate_results') is distinct from 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ADMISSION_INVALID_REQUEST',
      'status', 400,
      'message', 'Admission request must match dataset-alias-execution-admit.v1 exactly'
    );
  end if;

  v_request_id := (p_request->>'request_id')::uuid;
  v_token := p_request->>'preflight_token';
  v_gate_results := p_request->'gate_results';

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || v_request_id::text, 0)
  );

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = v_request_id
    and preflight.actor_user_id = v_actor
  for update;

  if v_preflight.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_NOT_FOUND',
      'status', 404,
      'message', 'No actor-owned protected preflight exists for this request ID'
    );
  end if;

  v_now := pg_catalog.clock_timestamp();

  if v_preflight.consumed_at is not null
    or exists (
      select 1
      from util.dataset_alias_execution_requests as request
      where request.id = v_request_id
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
      'status', 409,
      'message', 'The protected attempt was already consumed; use status/readback only'
    );
  end if;

  if v_now > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_EXPIRED',
      'status', 409,
      'message', 'The 180-second server preflight window expired before admission'
    );
  end if;

  if util.dataset_alias_execution_sha256(v_token)
      is distinct from v_preflight.token_sha256
    or p_request->>'preflight_proof_sha256'
      is distinct from v_preflight.preflight_proof_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_PROOF_MISMATCH',
      'status', 409,
      'message', 'Preflight token or proof does not match the durable server record'
    );
  end if;

  if not (v_gate_results ?& array[
      'primary_support_plan',
      'execution_unused',
      'derivative_quiescence'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_gate_results) as gate_key(key)
      where gate_key.key <> all (array[
        'primary_support_plan',
        'execution_unused',
        'derivative_quiescence'
      ])
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_SET_MISMATCH',
      'status', 400,
      'message', 'Exactly three protected gate results are required'
    );
  end if;

  for v_gate_name, v_expectation_name in
    select *
    from (values
      ('primary_support_plan'::text, 'primary_support_plan_sha256'::text),
      ('execution_unused'::text, 'execution_unused_sha256'::text),
      ('derivative_quiescence'::text, 'derivative_quiescence_sha256'::text)
    ) as gate_map(gate_name, expectation_name)
  loop
    v_gate := v_gate_results->v_gate_name;
    v_gate_receipt := null;

    select receipt.*
    into v_gate_receipt
    from util.dataset_alias_execution_gate_receipts as receipt
    where receipt.preflight_id = v_request_id
      and receipt.actor_user_id = v_actor
      and receipt.gate_name = v_gate_name;

    if jsonb_typeof(v_gate) is distinct from 'object'
      or not (v_gate ?& array[
        'expected_sha256',
        'observed_sha256',
        'status',
        'captured_at'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_gate) as gate_field(key)
        where gate_field.key <> all (array[
          'expected_sha256',
          'observed_sha256',
          'status',
          'captured_at'
        ])
      )
      or v_gate_receipt.preflight_id is null
      or v_gate->>'expected_sha256'
        is distinct from v_gate_receipt.expected_sha256
      or v_gate->>'observed_sha256'
        is distinct from v_gate_receipt.observed_sha256
      or v_gate->>'status' is distinct from v_gate_receipt.status
      or v_gate_receipt.expected_sha256
        is distinct from v_preflight.gate_expectations->>v_expectation_name
      or jsonb_typeof(v_gate->'captured_at') is distinct from 'string' then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_GATE_FAILED',
        'status', 409,
        'message', 'A protected gate is missing, failed, or bound to the wrong digest',
        'gate', v_gate_name
      );
    end if;

    begin
      v_captured_at := (v_gate->>'captured_at')::timestamp with time zone;
    exception
      when others then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_EXECUTION_GATE_TIMESTAMP_INVALID',
          'status', 400,
          'message', 'A protected gate timestamp is invalid',
          'gate', v_gate_name
        );
    end;

    if v_captured_at is distinct from v_gate_receipt.captured_at
      or v_captured_at < v_preflight.completed_at
      or v_captured_at > v_now + interval '5 seconds'
      or v_captured_at > v_preflight.expires_at then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_GATE_OUTSIDE_WINDOW',
        'status', 409,
        'message', 'All gate evidence must be captured inside the server preflight window',
        'gate', v_gate_name
      );
    end if;
  end loop;

  if pg_catalog.clock_timestamp() > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_EXPIRED',
      'status', 409,
      'message', 'The 180-second server preflight window expired during admission validation'
    );
  end if;

  v_gate_results_sha256 :=
    util.dataset_alias_execution_sha256(v_gate_results::text);
  v_admission_request_sha256 :=
    util.dataset_alias_execution_sha256(p_request::text);
  v_nonce := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_nonce_sha256 := util.dataset_alias_execution_sha256(v_nonce);

  insert into util.dataset_alias_execution_requests (
    id,
    actor_user_id,
    plan_sha256,
    operation_id,
    plan_request_sha256,
    freeze_sha256,
    approval_identity_sha256,
    approval_text_sha256,
    derivative_target_set_sha256,
    preflight_proof_sha256,
    admission_request_sha256,
    gate_results,
    gate_results_sha256,
    nonce_sha256,
    attempt_count,
    dispatch_count,
    status,
    admitted_at
  ) values (
    v_request_id,
    v_actor,
    v_preflight.plan_sha256,
    v_preflight.operation_id,
    v_preflight.plan_request_sha256,
    v_preflight.bindings->>'freeze_sha256',
    v_preflight.bindings->>'approval_identity_sha256',
    v_preflight.bindings->>'approval_text_sha256',
    v_preflight.bindings->>'derivative_target_set_sha256',
    v_preflight.preflight_proof_sha256,
    v_admission_request_sha256,
    v_gate_results,
    v_gate_results_sha256,
    v_nonce_sha256,
    1,
    0,
    'dispatching',
    v_now
  );

  update util.dataset_alias_execution_preflights
  set consumed_at = v_now
  where id = v_request_id;

  begin
    v_service_key := util.project_secret_key();
    v_net_request_id := net.http_post(
      url => util.project_url()
        || '/rest/v1/rpc/cmd_dataset_alias_execution_execute',
      headers => jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_key,
        'apikey', v_service_key
      ),
      body => jsonb_build_object(
        'p_request_id', v_request_id,
        'p_nonce', v_nonce
      ),
      timeout_milliseconds => 70000
    );

    if v_net_request_id is null then
      raise exception using
        errcode = 'P0001',
        message = 'pg_net returned no request ID';
    end if;

    update util.dataset_alias_execution_requests
    set
      dispatch_count = 1,
      net_request_id = v_net_request_id,
      status = 'dispatched',
      dispatched_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
    where id = v_request_id;
  exception
    when others then
      v_dispatch_error := jsonb_build_object(
        'phase', 'dispatch',
        'code', 'ALIAS_EXECUTION_DISPATCH_FAILED',
        'sqlstate', sqlstate,
        'message', sqlerrm
      );

      update util.dataset_alias_execution_requests
      set
        status = 'failed',
        terminal_at = pg_catalog.clock_timestamp(),
        last_error = v_dispatch_error,
        updated_at = pg_catalog.clock_timestamp()
      where id = v_request_id;
  end;

  if v_dispatch_error is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_DISPATCH_FAILED',
      'status', 'failed',
      'request_id', v_request_id,
      'attempt_count', 1,
      'dispatch_count', 0,
      'attempt_consumed', true,
      'retry_allowed', false,
      'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
      'admission_request_sha256', v_admission_request_sha256,
      'gate_results_sha256', v_gate_results_sha256
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_admit_guarded',
    'schema_version', v_schema_version,
    'request_id', v_request_id,
    'plan_sha256', v_preflight.plan_sha256,
    'operation_id', v_preflight.operation_id,
    'plan_request_sha256', v_preflight.plan_request_sha256,
    'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
    'admission_request_sha256', v_admission_request_sha256,
    'gate_results_sha256', v_gate_results_sha256,
    'attempt_count', 1,
    'dispatch_count', 1,
    'net_request_id', v_net_request_id::text,
    'status', 'dispatched',
    'attempt_consumed', true,
    'retry_allowed', false
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ADMISSION_LOCK_BUSY',
      'status', 409,
      'message', 'Protected admission could not acquire its bounded lock'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
      'status', 409,
      'message', 'The request or sealed approval identity already consumed its only attempt'
    );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_alias_execution_admit_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_admit_guarded(p_request jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_execution_admit_guarded(p_request jsonb) IS 'Consumes one actor-owned unexpired preflight token, binds three passed gate digests, persists attempt_count=1, and enqueues at most one service executor request. Repeated admission is rejected and status/readback never redispatches.';


--
-- Name: cmd_dataset_alias_execution_execute(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '60s'
    AS $_$
declare
  v_request util.dataset_alias_execution_requests%rowtype;
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_alias_result jsonb;
  v_primary_closure jsonb;
  v_batch_result jsonb;
  v_alias_audit_count integer;
  v_failure jsonb;
  v_committed_at timestamp with time zone;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  if p_request_id is null
    or p_nonce is null
    or p_nonce !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_INVALID_SERVICE_REQUEST',
      'status', 400,
      'message', 'Exact request ID and executor nonce are required'
    );
  end if;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
  for update;

  if v_request.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_REQUEST_NOT_FOUND',
      'status', 404,
      'message', 'Protected execution request not found'
    );
  end if;

  if util.dataset_alias_execution_sha256(p_nonce)
      is distinct from v_request.nonce_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_NONCE_MISMATCH',
      'status', 403,
      'message', 'Executor nonce does not match the admitted request'
    );
  end if;

  if v_request.status is distinct from 'dispatched'
    or v_request.dispatch_count <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ALREADY_STARTED',
      'status', 409,
      'message', 'The one-shot executor may start only once',
      'request_status', v_request.status,
      'retry_allowed', false
    );
  end if;

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = p_request_id
    and preflight.actor_user_id = v_request.actor_user_id;

  if v_preflight.id is null
    or v_preflight.consumed_at is null
    or v_preflight.preflight_proof_sha256
      is distinct from v_request.preflight_proof_sha256 then
    update util.dataset_alias_execution_requests
    set
      status = 'indeterminate',
      terminal_at = pg_catalog.clock_timestamp(),
      last_error = jsonb_build_object(
        'phase', 'executor_precondition',
        'code', 'ALIAS_EXECUTION_PREFLIGHT_LEDGER_MISMATCH'
      ),
      updated_at = pg_catalog.clock_timestamp()
    where id = p_request_id;

    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_LEDGER_MISMATCH',
      'status', 'indeterminate',
      'retry_allowed', false
    );
  end if;

  update util.dataset_alias_execution_requests
  set
    status = 'running',
    started_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where id = p_request_id;

  -- The service request remains authenticated by its secret headers.  Only
  -- auth.uid()/auth.email() are rebound so the existing owner-draft alias
  -- validators execute against the originally admitted actor.
  perform pg_catalog.set_config(
    'request.jwt.claim.sub',
    v_request.actor_user_id::text,
    true
  );
  perform pg_catalog.set_config(
    'request.jwt.claim.email',
    v_preflight.actor_email,
    true
  );

  begin
    v_alias_result := public.cmd_dataset_alias_plan_guarded(v_preflight.plan);

    if coalesce((v_alias_result->>'ok')::boolean, false) is not true
      or coalesce((v_alias_result->>'idempotent_replay')::boolean, true)
      or v_alias_result->>'plan_sha256' is distinct from v_request.plan_sha256
      or v_alias_result->>'operation_id' is distinct from v_request.operation_id
      or v_alias_result->>'plan_request_sha256'
        is distinct from v_request.plan_request_sha256
      or v_alias_result->>'row_count' is distinct from '52'
      or v_alias_result->>'exchange_count' is distinct from '59' then
      v_failure := jsonb_build_object(
        'phase', 'alias',
        'code', 'ALIAS_EXECUTION_PRIMARY_REJECTED',
        'result', coalesce(v_alias_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected primary alias execution rejected';
    end if;

    select count(*)
    into v_alias_audit_count
    from public.command_audit_log as audit
    where audit.actor_user_id = v_request.actor_user_id
      and (
        (
          audit.command = 'cmd_dataset_alias_batch_guarded'
          and audit.payload->>'plan_sha256' = v_request.plan_sha256
          and audit.payload->>'operation_id' = v_request.operation_id
          and audit.payload->>'record_type' in ('row', 'batch_summary')
        )
        or (
          audit.command = 'cmd_dataset_alias_plan_guarded'
          and audit.payload->>'plan_request_sha256' = v_request.plan_request_sha256
          and audit.payload->>'record_type' = 'plan_summary'
        )
      );

    if v_alias_audit_count <> 55 then
      v_failure := jsonb_build_object(
        'phase', 'alias_audit',
        'code', 'ALIAS_EXECUTION_AUDIT_COUNT_MISMATCH',
        'expected', 55,
        'observed', v_alias_audit_count
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected alias audit set is incomplete';
    end if;

    v_primary_closure :=
      util.read_dataset_alias_execution_primary_closure(
        v_request.actor_user_id,
        v_preflight.plan
      );

    if coalesce(
        (v_primary_closure->>'live_closure_proof')::boolean,
        false
      ) is not true
      or v_primary_closure->>'row_count' is distinct from '52'
      or v_primary_closure->>'exchange_count' is distinct from '59'
      or v_primary_closure->>'support_reference_count' is distinct from '6'
      or v_primary_closure->>'invalid_action_count' is distinct from '0'
      or v_primary_closure->>'invalid_support_count' is distinct from '0' then
      v_failure := jsonb_build_object(
        'phase', 'primary_closure',
        'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_MISMATCH',
        'proof', coalesce(v_primary_closure, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected primary/support live closure is incomplete';
    end if;

    v_batch_result := util.admit_dataset_derivative_rebuild_batch(
      v_request.actor_user_id,
      v_request.id,
      v_request.plan_sha256,
      v_request.operation_id,
      'PROTECTED_ALIAS_DERIVATIVE_CLOSURE',
      v_preflight.derivative_targets
    );

    if coalesce((v_batch_result->>'ok')::boolean, false) is not true
      or v_batch_result->>'target_count' is distinct from '50'
      or coalesce(v_batch_result->>'flow_count', v_batch_result->>'flows')
        is distinct from '23'
      or coalesce(v_batch_result->>'process_count', v_batch_result->>'processes')
        is distinct from '27' then
      v_failure := jsonb_build_object(
        'phase', 'derivative_batch',
        'code', 'ALIAS_EXECUTION_DERIVATIVE_ADMISSION_MISMATCH',
        'result', coalesce(v_batch_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected derivative batch admission rejected';
    end if;

    v_committed_at := pg_catalog.clock_timestamp();

    update util.dataset_alias_execution_requests
    set
      status = 'derivatives_pending',
      primary_committed_at = v_committed_at,
      alias_result = v_alias_result || jsonb_build_object(
        'primary_closure', v_primary_closure
      ),
      derivative_admission = v_batch_result,
      updated_at = v_committed_at
    where id = p_request_id;
  exception
    when others then
      if v_failure is null then
        v_failure := jsonb_build_object(
          'phase', 'executor',
          'code', 'ALIAS_EXECUTION_TRANSACTION_FAILED',
          'sqlstate', sqlstate,
          'message', sqlerrm
        );
      end if;
  end;

  if v_failure is not null then
    update util.dataset_alias_execution_requests
    set
      status = 'failed',
      terminal_at = pg_catalog.clock_timestamp(),
      last_error = v_failure,
      updated_at = pg_catalog.clock_timestamp()
    where id = p_request_id;

    return jsonb_build_object(
      'ok', false,
      'command', 'cmd_dataset_alias_execution_execute',
      'request_id', p_request_id,
      'status', 'failed',
      'primary_rolled_back', true,
      'retry_allowed', false,
      'error', v_failure
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_execute',
    'request_id', p_request_id,
    'status', 'derivatives_pending',
    'plan_sha256', v_request.plan_sha256,
    'operation_id', v_request.operation_id,
    'plan_request_sha256', v_request.plan_request_sha256,
    'primary_committed_at', v_committed_at,
    'row_count', 52,
    'exchange_count', 59,
    'alias_audit_count', 55,
    'primary_closure', v_primary_closure,
    'derivative_target_count', 50,
    'retry_allowed', false
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text) IS 'Service-only, nonce-bound, non-replayable executor. It commits either the exact 52 alias rows/59 exchanges/55 alias audits plus all 50 derivative child requests in one transaction, or none of those business effects.';


--
-- Name: cmd_dataset_alias_execution_gate_guarded(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '55s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_expected_name text;
  v_expected_sha256 text;
  v_material jsonb;
  v_observed_sha256 text;
  v_receipt_material jsonb;
  v_receipt_sha256 text;
  v_captured_at timestamp with time zone;
  v_alias_result jsonb;
  v_batch_result jsonb;
  v_simulation_passed boolean := false;
  v_execution_count integer := 0;
  v_alias_audit_count integer := 0;
  v_derivative_child_count integer := 0;
  v_snapshot_drift_count integer := 0;
  v_active_rebuild_count integer := 0;
  v_http_count integer := 0;
  v_extraction_count integer := 0;
  v_embedding_count integer := 0;
  v_pending_count integer := 0;
  v_failure_material jsonb;
  v_failure_sha256 text;
  v_target jsonb;
  v_snapshot jsonb;
  v_existing_gate_count integer := 0;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request_id is null
    or p_preflight_token is null
    or p_preflight_token !~ '^[a-f0-9]{64}$'
    or p_gate_name not in (
      'primary_support_plan',
      'execution_unused',
      'derivative_quiescence'
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_INVALID_REQUEST',
      'status', 400,
      'message', 'Exact request ID, preflight token, and known gate name are required'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor::text || ':' || p_request_id::text || ':' || p_gate_name,
      0
    )
  );

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = p_request_id
    and preflight.actor_user_id = v_actor
  for update;

  if v_preflight.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_NOT_FOUND',
      'status', 404,
      'message', 'No actor-owned protected preflight exists for this request ID'
    );
  end if;

  if v_preflight.consumed_at is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
      'status', 409,
      'message', 'Admission already consumed this preflight; gates are read-only history now'
    );
  end if;

  if pg_catalog.clock_timestamp() > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_EXPIRED',
      'status', 409,
      'message', 'The 180-second server preflight window expired before all gates completed'
    );
  end if;

  if util.dataset_alias_execution_sha256(p_preflight_token)
      is distinct from v_preflight.token_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TOKEN_MISMATCH',
      'status', 403,
      'message', 'Preflight token does not match the durable server record'
    );
  end if;

  if exists (
    select 1
    from util.dataset_alias_execution_gate_receipts as receipt
    where receipt.preflight_id = p_request_id
      and receipt.gate_name = p_gate_name
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_ALREADY_CAPTURED',
      'status', 409,
      'message', 'Each live gate is captured at most once; freeze again after a lost gate response'
    );
  end if;

  select count(*)::integer
  into v_existing_gate_count
  from util.dataset_alias_execution_gate_receipts as receipt
  where receipt.preflight_id = p_request_id
    and receipt.actor_user_id = v_actor;

  if (
      p_gate_name = 'primary_support_plan'
      and v_existing_gate_count <> 0
    ) or (
      p_gate_name = 'execution_unused'
      and (
        v_existing_gate_count <> 1
        or not exists (
          select 1
          from util.dataset_alias_execution_gate_receipts as receipt
          where receipt.preflight_id = p_request_id
            and receipt.actor_user_id = v_actor
            and receipt.gate_name = 'primary_support_plan'
        )
      )
    ) or (
      p_gate_name = 'derivative_quiescence'
      and (
        v_existing_gate_count <> 2
        or not exists (
          select 1
          from util.dataset_alias_execution_gate_receipts as receipt
          where receipt.preflight_id = p_request_id
            and receipt.actor_user_id = v_actor
            and receipt.gate_name = 'primary_support_plan'
        )
        or not exists (
          select 1
          from util.dataset_alias_execution_gate_receipts as receipt
          where receipt.preflight_id = p_request_id
            and receipt.actor_user_id = v_actor
            and receipt.gate_name = 'execution_unused'
        )
      )
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_ORDER_MISMATCH',
      'status', 409,
      'message', 'Live gates must be captured exactly once in primary/support, execution-unused, derivative-quiescence order'
    );
  end if;

  v_expected_name := case p_gate_name
    when 'primary_support_plan' then 'primary_support_plan_sha256'
    when 'execution_unused' then 'execution_unused_sha256'
    when 'derivative_quiescence' then 'derivative_quiescence_sha256'
  end;
  v_expected_sha256 := v_preflight.gate_expectations->>v_expected_name;

  if p_gate_name = 'primary_support_plan' then
    begin
      v_alias_result := public.cmd_dataset_alias_plan_guarded(v_preflight.plan);
      if coalesce((v_alias_result->>'ok')::boolean, false) is not true
        or coalesce((v_alias_result->>'idempotent_replay')::boolean, true)
        or v_alias_result->>'row_count' is distinct from '52'
        or v_alias_result->>'exchange_count' is distinct from '59' then
        raise exception using
          errcode = 'P0001',
          message = 'Primary/support simulation rejected';
      end if;

      v_batch_result := util.admit_dataset_derivative_rebuild_batch(
        v_actor,
        p_request_id,
        v_preflight.plan_sha256,
        v_preflight.operation_id,
        'PROTECTED_ALIAS_DERIVATIVE_CLOSURE',
        v_preflight.derivative_targets
      );

      if coalesce((v_batch_result->>'ok')::boolean, false) is not true
        or v_batch_result->>'target_count' is distinct from '50'
        or coalesce(v_batch_result->>'flow_count', v_batch_result->>'flows')
          is distinct from '23'
        or coalesce(v_batch_result->>'process_count', v_batch_result->>'processes')
          is distinct from '27' then
        raise exception using
          errcode = 'P0001',
          message = 'Derivative batch simulation rejected';
      end if;

      raise exception using
        errcode = 'P0002',
        message = 'Protected primary/support gate rollback';
    exception
      when sqlstate 'P0002' then
        v_simulation_passed := true;
      when others then
        v_simulation_passed := false;
    end;

    if not v_simulation_passed then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_PRIMARY_SUPPORT_GATE_FAILED',
        'status', 409,
        'message', 'Primary/support plan drifted after preflight'
      );
    end if;

    v_material := jsonb_build_object(
      'schema_version', 'dataset-alias-execution-gate-material.v1',
      'gate', p_gate_name,
      'request_id', p_request_id,
      'actor_user_id', v_actor,
      'plan_request_sha256', v_preflight.plan_request_sha256,
      'derivative_targets_sha256', v_preflight.derivative_targets_sha256,
      'plan_rows', 52,
      'plan_exchanges', 59,
      'alias_audits', 55,
      'derivative_targets', 50,
      'rollback_simulation_passed', true
    );
  elsif p_gate_name = 'execution_unused' then
    select count(*)::integer
    into v_execution_count
    from util.dataset_alias_execution_requests as request
    where request.actor_user_id = v_actor
      and request.approval_identity_sha256 =
        v_preflight.bindings->>'approval_identity_sha256';

    select count(*)::integer
    into v_alias_audit_count
    from public.command_audit_log as audit
    where audit.actor_user_id = v_actor
      and (
        (
          audit.command = 'cmd_dataset_alias_batch_guarded'
          and audit.payload->>'plan_sha256' = v_preflight.plan_sha256
          and audit.payload->>'operation_id' = v_preflight.operation_id
        )
        or (
          audit.command = 'cmd_dataset_alias_plan_guarded'
          and audit.payload->>'plan_request_sha256' =
            v_preflight.plan_request_sha256
        )
      );

    select count(*)::integer
    into v_derivative_child_count
    from util.dataset_derivative_rebuild_requests as request
    where request.actor_user_id = v_actor
      and request.batch_id = p_request_id;

    if v_execution_count <> 0
      or v_alias_audit_count <> 0
      or v_derivative_child_count <> 0 then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_UNUSED_GATE_FAILED',
        'status', 409,
        'message', 'The sealed execution identity already has durable effects'
      );
    end if;

    v_material := jsonb_build_object(
      'schema_version', 'dataset-alias-execution-gate-material.v1',
      'gate', p_gate_name,
      'request_id', p_request_id,
      'actor_user_id', v_actor,
      'plan_request_sha256', v_preflight.plan_request_sha256,
      'sealed_execution_rows', v_execution_count,
      'alias_audit_rows', v_alias_audit_count,
      'derivative_child_rows', v_derivative_child_count
    );
  else
    for v_target in
      select target_item.value
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
    loop
      begin
        v_snapshot := util.dataset_derivative_rebuild_snapshot(
          v_target->>'table',
          (v_target->>'id')::uuid,
          v_target->>'version'
        );
      exception
        when others then
          v_snapshot := null;
      end;

      if v_snapshot is null
        or v_snapshot->>'user_id' is distinct from v_actor::text
        or v_snapshot->>'state_code' is distinct from '0'
        or v_snapshot->>'snapshot_sha256'
          is distinct from v_target->>'baseline_snapshot_sha256' then
        v_snapshot_drift_count := v_snapshot_drift_count + 1;
      end if;
    end loop;

    select count(*)::integer
    into v_active_rebuild_count
    from util.dataset_derivative_rebuild_requests as request
    where request.status not in ('completed', 'stale', 'failed')
      and exists (
        select 1
        from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
        where request.target_table = target_item.value->>'table'
          and request.target_id = (target_item.value->>'id')::uuid
          and request.target_version = target_item.value->>'version'
      );

    select count(*)::integer
    into v_http_count
    from net.http_request_queue as request
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where util.dataset_derivative_rebuild_http_body_matches(
        request.body,
        target_item.value->>'table',
        (target_item.value->>'id')::uuid,
        target_item.value->>'version'
      )
    );

    select count(*)::integer
    into v_extraction_count
    from pgmq.q_dataset_extraction_jobs as job
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where job.message->>'schema' = 'public'
        and job.message->>'table' = target_item.value->>'table'
        and job.message->>'id' = target_item.value->>'id'
        and btrim(job.message->>'version') = target_item.value->>'version'
    );

    select count(*)::integer
    into v_embedding_count
    from pgmq.q_embedding_jobs as job
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where job.message->>'schema' = 'public'
        and job.message->>'table' = target_item.value->>'table'
        and job.message->>'id' = target_item.value->>'id'
        and btrim(job.message->>'version') = target_item.value->>'version'
        and job.message->>'embeddingColumn' = 'embedding_ft'
    );

    select count(*)::integer
    into v_pending_count
    from util.pending_embedding_jobs as pending
    where pending.schema_name = 'public'
      and pending.embedding_column = 'embedding_ft'
      and pending.status = 'pending'
      and exists (
        select 1
        from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
        where pending.table_name = target_item.value->>'table'
          and pending.record_id = target_item.value->>'id'
          and btrim(pending.record_version) = target_item.value->>'version'
      );

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', failure.id,
          'queue_name', failure.queue_name,
          'msg_id', failure.msg_id,
          'read_count', failure.read_count,
          'reason', failure.reason,
          'message', failure.message,
          'failed_at', failure.failed_at
        ) order by failure.id
      ),
      '[]'::jsonb
    )
    into v_failure_material
    from util.embedding_job_failures as failure
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where failure.message->>'table' = target_item.value->>'table'
        and failure.message->>'id' = target_item.value->>'id'
        and btrim(failure.message->>'version') = target_item.value->>'version'
    );
    v_failure_sha256 :=
      util.dataset_alias_execution_sha256(v_failure_material::text);

    if v_snapshot_drift_count <> 0
      or v_active_rebuild_count <> 0
      or v_http_count <> 0
      or v_extraction_count <> 0
      or v_embedding_count <> 0
      or v_pending_count <> 0
      or v_failure_sha256 is distinct from v_preflight.failure_baseline_sha256 then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_DERIVATIVE_QUIESCENCE_GATE_FAILED',
        'status', 409,
        'message', 'Derivative baselines, queues, fences, or failure ledger drifted after preflight'
      );
    end if;

    v_material := jsonb_build_object(
      'schema_version', 'dataset-alias-execution-gate-material.v1',
      'gate', p_gate_name,
      'request_id', p_request_id,
      'actor_user_id', v_actor,
      'derivative_targets_sha256', v_preflight.derivative_targets_sha256,
      'snapshot_drift_count', v_snapshot_drift_count,
      'active_rebuild_count', v_active_rebuild_count,
      'http_request_count', v_http_count,
      'extraction_job_count', v_extraction_count,
      'embedding_job_count', v_embedding_count,
      'pending_embedding_count', v_pending_count,
      'failure_baseline_sha256', v_failure_sha256
    );
  end if;

  v_captured_at := pg_catalog.clock_timestamp();
  if v_captured_at > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_WINDOW_EXPIRED',
      'status', 409,
      'message', 'The live gate completed after the 180-second server window'
    );
  end if;

  v_observed_sha256 := util.dataset_alias_execution_sha256(v_material::text);
  if v_observed_sha256 is distinct from v_expected_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_EVIDENCE_MISMATCH',
      'status', 409,
      'message', 'The live gate evidence does not match the server-owned preflight expectation'
    );
  end if;

  v_receipt_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-receipt.v1',
    'request_id', p_request_id,
    'actor_user_id', v_actor,
    'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
    'gate', p_gate_name,
    'expected_sha256', v_expected_sha256,
    'observed_sha256', v_observed_sha256,
    'status', 'passed',
    'captured_at', v_captured_at
  );
  v_receipt_sha256 :=
    util.dataset_alias_execution_sha256(v_receipt_material::text);

  insert into util.dataset_alias_execution_gate_receipts (
    preflight_id,
    actor_user_id,
    gate_name,
    expected_sha256,
    observed_sha256,
    material,
    status,
    captured_at,
    receipt_sha256
  ) values (
    p_request_id,
    v_actor,
    p_gate_name,
    v_expected_sha256,
    v_observed_sha256,
    v_material,
    'passed',
    v_captured_at,
    v_receipt_sha256
  );

  return v_receipt_material || jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_gate_guarded',
    'receipt_sha256', v_receipt_sha256
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_LOCK_BUSY',
      'status', 409,
      'message', 'Protected live gate could not acquire its bounded locks'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_ALREADY_CAPTURED',
      'status', 409,
      'message', 'A concurrent call already captured this live gate'
    );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text) IS 'Captures one of exactly three actor-owned post-preflight live gates. Primary/support is rollback-simulated again; unused execution and derivative quiescence are read directly. Each passed receipt is persisted once inside the same 180-second server window.';


--
-- Name: cmd_dataset_alias_execution_preflight_guarded(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_alias_execution_preflight_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '60s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_actor_email text := auth.email();
  v_schema_version constant text := 'dataset-alias-execution-preflight.v1';
  v_request_id uuid;
  v_environment text;
  v_project_ref text;
  v_server_context jsonb;
  v_request_actor jsonb;
  v_plan jsonb;
  v_freeze jsonb;
  v_approval jsonb;
  v_expected_freeze jsonb;
  v_expected_approval jsonb;
  v_bindings jsonb;
  v_expected jsonb;
  v_input_targets jsonb;
  v_targets jsonb;
  v_sorted_targets jsonb;
  v_gate_expectations jsonb;
  v_primary_gate_material jsonb;
  v_unused_gate_material jsonb;
  v_quiescence_gate_material jsonb;
  v_plan_sha256 text;
  v_operation_id text;
  v_plan_request_sha256 text;
  v_alias_plan_request_sha256 text;
  v_derivative_target_set_sha256 text;
  v_derivative_baseline_set_sha256 text;
  v_bindings_sha256 text;
  v_expected_sha256 text;
  v_targets_sha256 text;
  v_gate_expectations_sha256 text;
  v_failure_baseline_material jsonb;
  v_failure_baseline_sha256 text;
  v_request_sha256 text;
  v_token text;
  v_token_sha256 text;
  v_proof_material jsonb;
  v_proof_sha256 text;
  v_completed_at timestamp with time zone;
  v_expires_at timestamp with time zone;
  v_target jsonb;
  v_snapshot jsonb;
  v_alias_result jsonb;
  v_batch_result jsonb;
  v_simulation_passed boolean := false;
  v_simulation_error jsonb;
  v_existing_id uuid;
  v_execution_count integer := 0;
  v_alias_audit_count integer := 0;
  v_derivative_child_count integer := 0;
  v_snapshot_drift_count integer := 0;
  v_active_rebuild_count integer := 0;
  v_http_count integer := 0;
  v_extraction_count integer := 0;
  v_embedding_count integer := 0;
  v_pending_count integer := 0;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if nullif(v_actor_email, '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_EMAIL_REQUIRED',
      'status', 401,
      'message', 'Authenticated email claim is required'
    );
  end if;

  if p_request is not null and pg_column_size(p_request) > 67108864 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TOO_LARGE',
      'status', 413,
      'message', 'Protected preflight request exceeds 64 MiB'
    );
  end if;

  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array[
      'schema_version',
      'request_id',
      'environment',
      'project_ref',
      'actor',
      'target_visibility',
      'plan',
      'freeze',
      'approval',
      'bindings',
      'expected',
      'derivative_targets'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_request) as request_key(key)
      where request_key.key <> all (array[
        'schema_version',
        'request_id',
        'environment',
        'project_ref',
        'actor',
        'target_visibility',
        'plan',
        'freeze',
        'approval',
        'bindings',
        'expected',
        'derivative_targets'
      ])
    )
    or p_request->>'schema_version' is distinct from v_schema_version
    or jsonb_typeof(p_request->'request_id') is distinct from 'string'
    or (p_request->>'request_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_request->>'environment' not in ('production', 'preview', 'local')
    or jsonb_typeof(p_request->'project_ref') is distinct from 'string'
    or nullif(btrim(p_request->>'project_ref'), '') is null
    or octet_length(p_request->>'project_ref') > 128
    or p_request->>'target_visibility' is distinct from 'owner_draft'
    or jsonb_typeof(p_request->'actor') is distinct from 'object'
    or jsonb_typeof(p_request->'plan') is distinct from 'object'
    or jsonb_typeof(p_request->'freeze') is distinct from 'object'
    or jsonb_typeof(p_request->'approval') is distinct from 'object'
    or jsonb_typeof(p_request->'bindings') is distinct from 'object'
    or jsonb_typeof(p_request->'expected') is distinct from 'object'
    or jsonb_typeof(p_request->'derivative_targets') is distinct from 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_REQUEST',
      'status', 400,
      'message', 'Preflight request must match dataset-alias-execution-preflight.v1 exactly'
    );
  end if;

  v_request_id := (p_request->>'request_id')::uuid;
  v_environment := p_request->>'environment';
  v_project_ref := btrim(p_request->>'project_ref');
  v_request_actor := p_request->'actor';
  v_plan := p_request->'plan';
  v_freeze := p_request->'freeze';
  v_approval := p_request->'approval';
  v_bindings := p_request->'bindings';
  v_expected := p_request->'expected';
  v_input_targets := p_request->'derivative_targets';

  begin
    v_server_context := util.dataset_alias_execution_server_context();
  exception
    when others then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_SERVER_CONTEXT_UNAVAILABLE',
        'status', 409,
        'message', 'Branch-local project identity could not be derived from trusted server configuration'
      );
  end;

  if v_environment is distinct from v_server_context->>'environment'
    or v_project_ref is distinct from v_server_context->>'project_ref' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_SERVER_CONTEXT_MISMATCH',
      'status', 409,
      'message', 'Requested environment and project_ref do not match the connected database'
    );
  end if;

  if not (v_request_actor ?& array['user_id', 'email'])
    or exists (
      select 1
      from jsonb_object_keys(v_request_actor) as actor_key(key)
      where actor_key.key <> all (array['user_id', 'email'])
    )
    or jsonb_typeof(v_request_actor->'user_id') is distinct from 'string'
    or v_request_actor->>'user_id' is distinct from v_actor::text
    or jsonb_typeof(v_request_actor->'email') is distinct from 'string'
    or lower(btrim(v_request_actor->>'email'))
      is distinct from lower(btrim(v_actor_email))
    or octet_length(v_request_actor->>'email') > 320 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_ACTOR_MISMATCH',
      'status', 403,
      'message', 'Preflight actor must match the authenticated user and email'
    );
  end if;

  if not (v_bindings ?& array[
      'plan_file_sha256',
      'freeze_file_sha256',
      'freeze_sha256',
      'approval_file_sha256',
      'approval_identity_sha256',
      'approval_text_sha256',
      'alias_plan_request_sha256',
      'before_hash_set_sha256',
      'desired_hash_set_sha256',
      'exchange_rewrite_set_sha256',
      'support_snapshot_set_sha256',
      'derivative_baseline_set_sha256',
      'derivative_target_set_sha256',
      'toolchain_evidence_sha256'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_bindings) as binding_key(key)
      where binding_key.key <> all (array[
        'plan_file_sha256',
        'freeze_file_sha256',
        'freeze_sha256',
        'approval_file_sha256',
        'approval_identity_sha256',
        'approval_text_sha256',
        'alias_plan_request_sha256',
        'before_hash_set_sha256',
        'desired_hash_set_sha256',
        'exchange_rewrite_set_sha256',
        'support_snapshot_set_sha256',
        'derivative_baseline_set_sha256',
        'derivative_target_set_sha256',
        'toolchain_evidence_sha256'
      ])
    )
    or exists (
      select 1
      from jsonb_each(v_bindings) as binding_item(key, value)
      where jsonb_typeof(binding_item.value) is distinct from 'string'
        or (binding_item.value #>> '{}') !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_BINDINGS',
      'status', 400,
      'message', 'All protected artifact bindings must be exact SHA-256 values'
    );
  end if;

  if not (v_expected ?& array[
      'action_count',
      'batch_count',
      'exchange_count',
      'amount_field_count',
      'unrelated_exchange_count',
      'audit_count',
      'flowproperty_count',
      'flow_count',
      'process_count',
      'derivative_target_count'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_expected) as expected_key(key)
      where expected_key.key <> all (array[
        'action_count',
        'batch_count',
        'exchange_count',
        'amount_field_count',
        'unrelated_exchange_count',
        'audit_count',
        'flowproperty_count',
        'flow_count',
        'process_count',
        'derivative_target_count'
      ])
    )
    or v_expected is distinct from jsonb_build_object(
      'action_count', 52,
      'batch_count', 2,
      'exchange_count', 59,
      'amount_field_count', 118,
      'unrelated_exchange_count', 309,
      'audit_count', 55,
      'flowproperty_count', 2,
      'flow_count', 23,
      'process_count', 27,
      'derivative_target_count', 50
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_COUNTS',
      'status', 400,
      'message', 'Protected profile requires exact 52/59/118/309/55 and 2/23/27/50 counts'
    );
  end if;

  if jsonb_array_length(v_input_targets) <> 50
    or exists (
      select 1
      from jsonb_array_elements(v_input_targets) as target_item(value)
      where jsonb_typeof(target_item.value) is distinct from 'object'
        or not (target_item.value ?& array[
          'table',
          'id',
          'version',
          'user_id',
          'state_code',
          'baseline_snapshot_sha256'
        ])
        or exists (
          select 1
          from jsonb_object_keys(target_item.value) as target_key(key)
          where target_key.key <> all (array[
            'table',
            'id',
            'version',
            'user_id',
            'state_code',
            'baseline_snapshot_sha256'
          ])
        )
        or target_item.value->>'table' not in ('flows', 'processes')
        or jsonb_typeof(target_item.value->'table') is distinct from 'string'
        or jsonb_typeof(target_item.value->'id') is distinct from 'string'
        or (target_item.value->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(target_item.value->'version') is distinct from 'string'
        or (target_item.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or jsonb_typeof(target_item.value->'user_id') is distinct from 'string'
        or target_item.value->>'user_id' is distinct from v_actor::text
        or jsonb_typeof(target_item.value->'state_code') is distinct from 'number'
        or target_item.value->>'state_code' is distinct from '0'
        or jsonb_typeof(target_item.value->'baseline_snapshot_sha256')
          is distinct from 'string'
        or (target_item.value->>'baseline_snapshot_sha256') !~ '^[a-f0-9]{64}$'
    )
    or (
      select count(*)
      from jsonb_array_elements(v_input_targets) as target_item(value)
      where target_item.value->>'table' = 'flows'
    ) <> 23
    or (
      select count(*)
      from jsonb_array_elements(v_input_targets) as target_item(value)
      where target_item.value->>'table' = 'processes'
    ) <> 27
    or (
      select count(distinct (
        target_item.value->>'table',
        target_item.value->>'id',
        target_item.value->>'version'
      ))
      from jsonb_array_elements(v_input_targets) as target_item(value)
    ) <> 50 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_TARGETS',
      'status', 400,
      'message', 'Derivative targets must be 23 unique flows and 27 unique processes owned by the actor at state_code 0'
    );
  end if;

  select jsonb_agg(target_item.value order by
    target_item.value->>'table',
    target_item.value->>'id',
    target_item.value->>'version'
  )
  into v_sorted_targets
  from jsonb_array_elements(v_input_targets) as target_item(value);

  if v_input_targets is distinct from v_sorted_targets then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TARGET_ORDER',
      'status', 400,
      'message', 'Derivative targets must use stable table/id/version order'
    );
  end if;

  if v_plan->>'schema_version' is distinct from 'dataset-alias-plan.v1'
    or v_plan->>'target_visibility' is distinct from 'owner_draft'
    or (v_plan->>'plan_sha256') !~ '^[a-f0-9]{64}$'
    or nullif(btrim(v_plan->>'operation_id'), '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_PLAN',
      'status', 400,
      'message', 'Protected preflight requires one owner-draft dataset-alias-plan.v1 request'
    );
  end if;

  v_plan_sha256 := v_plan->>'plan_sha256';
  v_operation_id := btrim(v_plan->>'operation_id');

  select jsonb_agg(
    jsonb_build_object(
      'table', target_item.value->>'table',
      'id', target_item.value->>'id',
      'version', target_item.value->>'version',
      'expected_json_ordered_sha256',
        util.dataset_alias_execution_sha256(
          (action_item.value->'desired_json_ordered')::text
        ),
      'baseline_snapshot_sha256',
        target_item.value->>'baseline_snapshot_sha256'
    ) order by
      target_item.value->>'table',
      target_item.value->>'id',
      target_item.value->>'version'
  )
  into v_targets
  from jsonb_array_elements(v_plan->'batches') as batch_item(value)
  cross join lateral jsonb_array_elements(
    batch_item.value->'actions'
  ) as action_item(value)
  join jsonb_array_elements(v_input_targets) as target_item(value)
    on target_item.value->>'table' = action_item.value->>'table'
   and target_item.value->>'id' = action_item.value->>'id'
   and target_item.value->>'version' = action_item.value->>'version'
  where action_item.value->>'table' in ('flows', 'processes');

  if jsonb_typeof(v_targets) is distinct from 'array'
    or jsonb_array_length(v_targets) <> 50 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TARGET_PLAN_MISMATCH',
      'status', 409,
      'message', 'Derivative target identities must exactly match the 50 flow/process plan actions'
    );
  end if;

  v_alias_plan_request_sha256 :=
    util.dataset_alias_execution_artifact_sha256(v_plan);

  select util.dataset_alias_execution_artifact_sha256(
    jsonb_agg(
      jsonb_build_object(
        'table', target_item.value->>'table',
        'id', target_item.value->>'id',
        'version', target_item.value->>'version',
        'user_id', target_item.value->>'user_id',
        'state_code', 0
      ) order by
        target_item.value->>'table',
        target_item.value->>'id',
        target_item.value->>'version'
    )
  )
  into v_derivative_target_set_sha256
  from jsonb_array_elements(v_input_targets) as target_item(value);

  select util.dataset_alias_execution_artifact_sha256(
    jsonb_agg(
      jsonb_build_object(
        'table', target_item.value->>'table',
        'id', target_item.value->>'id',
        'version', target_item.value->>'version',
        'baseline_snapshot_sha256',
          target_item.value->>'baseline_snapshot_sha256'
      ) order by
        target_item.value->>'table',
        target_item.value->>'id',
        target_item.value->>'version'
    )
  )
  into v_derivative_baseline_set_sha256
  from jsonb_array_elements(v_input_targets) as target_item(value);

  if v_bindings->>'alias_plan_request_sha256'
      is distinct from v_alias_plan_request_sha256
    or v_bindings->>'derivative_target_set_sha256'
      is distinct from v_derivative_target_set_sha256
    or v_bindings->>'derivative_baseline_set_sha256'
      is distinct from v_derivative_baseline_set_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_ARTIFACT_SET_MISMATCH',
      'status', 409,
      'message', 'The approved alias request or derivative target sets do not match server recomputation'
    );
  end if;

  v_expected_freeze := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-freeze.v1',
    'environment', v_environment,
    'project_ref', v_project_ref,
    'account', v_request_actor,
    'target_visibility', 'owner_draft',
    'plan', jsonb_build_object(
      'plan_file_sha256', v_bindings->>'plan_file_sha256',
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id
    ),
    'sets', jsonb_build_object(
      'alias_plan_request_sha256',
        v_bindings->>'alias_plan_request_sha256',
      'before_hash_set_sha256',
        v_bindings->>'before_hash_set_sha256',
      'desired_hash_set_sha256',
        v_bindings->>'desired_hash_set_sha256',
      'exchange_rewrite_set_sha256',
        v_bindings->>'exchange_rewrite_set_sha256',
      'support_snapshot_set_sha256',
        v_bindings->>'support_snapshot_set_sha256',
      'derivative_baseline_set_sha256',
        v_bindings->>'derivative_baseline_set_sha256',
      'derivative_target_set_sha256',
        v_bindings->>'derivative_target_set_sha256',
      'toolchain_evidence_sha256',
        v_bindings->>'toolchain_evidence_sha256'
    ),
    'expected', v_expected,
    'derivative_targets', v_input_targets,
    'policy', jsonb_build_object(
      'state_code_changes', 0,
      'save_draft', 0,
      'deletes', 0,
      'rebuild_derivatives', 0,
      'unitgroup_actions', 0,
      'person_distance_actions', 0,
      'max_admit_posts', 1,
      'automatic_retry', false
    ),
    'freeze_sha256', v_bindings->>'freeze_sha256'
  );

  if v_freeze is distinct from v_expected_freeze
    or util.dataset_alias_execution_artifact_sha256(
      jsonb_set(v_freeze, '{freeze_sha256}', '""'::jsonb, false)
    ) is distinct from v_bindings->>'freeze_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_FREEZE_MISMATCH',
      'status', 409,
      'message', 'The production freeze envelope or canonical freeze hash is invalid'
    );
  end if;

  begin
    perform (v_approval->>'approved_at_utc')::timestamp with time zone;
  exception
    when others then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_MISMATCH',
        'status', 409,
        'message', 'The exact approval timestamp is invalid'
      );
  end;

  v_expected_approval := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-approval.v1',
    'approved_at_utc', v_approval->>'approved_at_utc',
    'environment', v_environment,
    'project_ref', v_project_ref,
    'account', v_request_actor,
    'target_visibility', 'owner_draft',
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'plan_file_sha256', v_bindings->>'plan_file_sha256',
    'freeze_file_sha256', v_bindings->>'freeze_file_sha256',
    'freeze_sha256', v_bindings->>'freeze_sha256',
    'approval_text_sha256', v_bindings->>'approval_text_sha256',
    'max_admit_posts', 1,
    'automatic_retry', false,
    'approval_identity_sha256', v_bindings->>'approval_identity_sha256'
  );

  if v_approval is distinct from v_expected_approval
    or util.dataset_alias_execution_artifact_sha256(
      jsonb_set(
        v_approval,
        '{approval_identity_sha256}',
        '""'::jsonb,
        false
      )
    ) is distinct from v_bindings->>'approval_identity_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_MISMATCH',
      'status', 409,
      'message', 'The approval identity does not bind this exact production freeze and alias request'
    );
  end if;

  select preflight.id
  into v_existing_id
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = v_request_id
     or (
       preflight.actor_user_id = v_actor
       and preflight.approval_identity_sha256 =
         v_bindings->>'approval_identity_sha256'
     )
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_ALREADY_USED',
      'status', 409,
      'message', 'This request ID or exact approval identity already created a protected preflight; freeze and approve again'
    );
  end if;

  for v_target in
    select target_item.value
    from jsonb_array_elements(v_targets) as target_item(value)
  loop
    begin
      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_target->>'table',
        (v_target->>'id')::uuid,
        v_target->>'version'
      );
    exception
      when others then
        v_snapshot := null;
    end;

    if v_snapshot is null
      or v_snapshot->>'user_id' is distinct from v_actor::text
      or v_snapshot->>'state_code' is distinct from '0'
      or v_snapshot->>'json_sha256' is distinct from v_snapshot->>'json_ordered_sha256'
      or v_snapshot->>'snapshot_sha256'
        is distinct from v_target->>'baseline_snapshot_sha256' then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_PREFLIGHT_BASELINE_DRIFT',
        'status', 409,
        'message', 'A derivative target no longer matches its owner-draft baseline snapshot'
      );
    end if;
  end loop;

  v_plan_request_sha256 := util.dataset_alias_execution_sha256(v_plan::text);
  v_bindings_sha256 := util.dataset_alias_execution_sha256(v_bindings::text);
  v_expected_sha256 := util.dataset_alias_execution_sha256(v_expected::text);
  v_targets_sha256 := util.dataset_alias_execution_sha256(v_targets::text);
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', failure.id,
        'queue_name', failure.queue_name,
        'msg_id', failure.msg_id,
        'read_count', failure.read_count,
        'reason', failure.reason,
        'message', failure.message,
        'failed_at', failure.failed_at
      ) order by failure.id
    ),
    '[]'::jsonb
  )
  into v_failure_baseline_material
  from util.embedding_job_failures as failure
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where failure.message->>'table' = target_item.value->>'table'
      and failure.message->>'id' = target_item.value->>'id'
      and btrim(failure.message->>'version') = target_item.value->>'version'
  );
  v_failure_baseline_sha256 :=
    util.dataset_alias_execution_sha256(v_failure_baseline_material::text);
  v_request_sha256 := util.dataset_alias_execution_sha256(p_request::text);

  -- The simulation creates all normal alias writes, audits, webhook work, and
  -- derivative fences inside this exception block.  The controlled P0002
  -- exception always rolls those effects back before a durable token exists.
  begin
    v_alias_result := public.cmd_dataset_alias_plan_guarded(v_plan);
    if coalesce((v_alias_result->>'ok')::boolean, false) is not true
      or coalesce((v_alias_result->>'idempotent_replay')::boolean, true)
      or v_alias_result->>'row_count' is distinct from '52'
      or v_alias_result->>'exchange_count' is distinct from '59' then
      v_simulation_error := jsonb_build_object(
        'phase', 'alias',
        'result', coalesce(v_alias_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected alias simulation rejected';
    end if;

    v_batch_result := util.admit_dataset_derivative_rebuild_batch(
      v_actor,
      v_request_id,
      v_plan_sha256,
      v_operation_id,
      'PROTECTED_ALIAS_DERIVATIVE_CLOSURE',
      v_targets
    );

    if coalesce((v_batch_result->>'ok')::boolean, false) is not true
      or v_batch_result->>'target_count' is distinct from '50'
      or v_batch_result->>'flow_count' is distinct from '23'
      or v_batch_result->>'process_count' is distinct from '27' then
      v_simulation_error := jsonb_build_object(
        'phase', 'derivative_batch',
        'result', coalesce(v_batch_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected derivative batch simulation rejected';
    end if;

    raise exception using
      errcode = 'P0002',
      message = 'Protected execution preflight simulation rollback';
  exception
    when sqlstate 'P0002' then
      v_simulation_passed := true;
    when others then
      v_simulation_passed := false;
      if v_simulation_error is null then
        v_simulation_error := jsonb_build_object(
          'phase', 'unexpected',
          'sqlstate', sqlstate,
          'message', sqlerrm
        );
      end if;
  end;

  if not v_simulation_passed then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_SIMULATION_FAILED',
      'status', 409,
      'message', 'The exact protected plan failed rollback-only server simulation',
      'evidence', v_simulation_error
    );
  end if;

  select count(*)::integer
  into v_execution_count
  from util.dataset_alias_execution_requests as request
  where request.actor_user_id = v_actor
    and request.approval_identity_sha256 =
      v_bindings->>'approval_identity_sha256';

  select count(*)::integer
  into v_alias_audit_count
  from public.command_audit_log as audit
  where audit.actor_user_id = v_actor
    and (
      (
        audit.command = 'cmd_dataset_alias_batch_guarded'
        and audit.payload->>'plan_sha256' = v_plan_sha256
        and audit.payload->>'operation_id' = v_operation_id
      )
      or (
        audit.command = 'cmd_dataset_alias_plan_guarded'
        and audit.payload->>'plan_request_sha256' = v_plan_request_sha256
      )
    );

  select count(*)::integer
  into v_derivative_child_count
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = v_actor
    and request.batch_id = v_request_id;

  for v_target in
    select target_item.value
    from jsonb_array_elements(v_targets) as target_item(value)
  loop
    begin
      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_target->>'table',
        (v_target->>'id')::uuid,
        v_target->>'version'
      );
    exception
      when others then
        v_snapshot := null;
    end;

    if v_snapshot is null
      or v_snapshot->>'user_id' is distinct from v_actor::text
      or v_snapshot->>'state_code' is distinct from '0'
      or v_snapshot->>'snapshot_sha256'
        is distinct from v_target->>'baseline_snapshot_sha256' then
      v_snapshot_drift_count := v_snapshot_drift_count + 1;
    end if;
  end loop;

  select count(*)::integer
  into v_active_rebuild_count
  from util.dataset_derivative_rebuild_requests as request
  where request.status not in ('completed', 'stale', 'failed')
    and exists (
      select 1
      from jsonb_array_elements(v_targets) as target_item(value)
      where request.target_table = target_item.value->>'table'
        and request.target_id = (target_item.value->>'id')::uuid
        and request.target_version = target_item.value->>'version'
    );

  select count(*)::integer
  into v_http_count
  from net.http_request_queue as request
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where util.dataset_derivative_rebuild_http_body_matches(
      request.body,
      target_item.value->>'table',
      (target_item.value->>'id')::uuid,
      target_item.value->>'version'
    )
  );

  select count(*)::integer
  into v_extraction_count
  from pgmq.q_dataset_extraction_jobs as job
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where job.message->>'schema' = 'public'
      and job.message->>'table' = target_item.value->>'table'
      and job.message->>'id' = target_item.value->>'id'
      and btrim(job.message->>'version') = target_item.value->>'version'
  );

  select count(*)::integer
  into v_embedding_count
  from pgmq.q_embedding_jobs as job
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where job.message->>'schema' = 'public'
      and job.message->>'table' = target_item.value->>'table'
      and job.message->>'id' = target_item.value->>'id'
      and btrim(job.message->>'version') = target_item.value->>'version'
      and job.message->>'embeddingColumn' = 'embedding_ft'
  );

  select count(*)::integer
  into v_pending_count
  from util.pending_embedding_jobs as pending
  where pending.schema_name = 'public'
    and pending.embedding_column = 'embedding_ft'
    and pending.status = 'pending'
    and exists (
      select 1
      from jsonb_array_elements(v_targets) as target_item(value)
      where pending.table_name = target_item.value->>'table'
        and pending.record_id = target_item.value->>'id'
        and btrim(pending.record_version) = target_item.value->>'version'
    );

  if v_execution_count <> 0
    or v_alias_audit_count <> 0
    or v_derivative_child_count <> 0
    or v_snapshot_drift_count <> 0
    or v_active_rebuild_count <> 0
    or v_http_count <> 0
    or v_extraction_count <> 0
    or v_embedding_count <> 0
    or v_pending_count <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_NOT_QUIESCENT',
      'status', 409,
      'message', 'The exact approval identity, targets, or derivative queues are not unused and quiescent'
    );
  end if;

  v_primary_gate_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-material.v1',
    'gate', 'primary_support_plan',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'plan_request_sha256', v_plan_request_sha256,
    'derivative_targets_sha256', v_targets_sha256,
    'plan_rows', 52,
    'plan_exchanges', 59,
    'alias_audits', 55,
    'derivative_targets', 50,
    'rollback_simulation_passed', true
  );
  v_unused_gate_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-material.v1',
    'gate', 'execution_unused',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'plan_request_sha256', v_plan_request_sha256,
    'sealed_execution_rows', v_execution_count,
    'alias_audit_rows', v_alias_audit_count,
    'derivative_child_rows', v_derivative_child_count
  );
  v_quiescence_gate_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-material.v1',
    'gate', 'derivative_quiescence',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'derivative_targets_sha256', v_targets_sha256,
    'snapshot_drift_count', v_snapshot_drift_count,
    'active_rebuild_count', v_active_rebuild_count,
    'http_request_count', v_http_count,
    'extraction_job_count', v_extraction_count,
    'embedding_job_count', v_embedding_count,
    'pending_embedding_count', v_pending_count,
    'failure_baseline_sha256', v_failure_baseline_sha256
  );
  v_gate_expectations := jsonb_build_object(
    'primary_support_plan_sha256',
      util.dataset_alias_execution_sha256(v_primary_gate_material::text),
    'execution_unused_sha256',
      util.dataset_alias_execution_sha256(v_unused_gate_material::text),
    'derivative_quiescence_sha256',
      util.dataset_alias_execution_sha256(v_quiescence_gate_material::text)
  );
  v_gate_expectations_sha256 :=
    util.dataset_alias_execution_sha256(v_gate_expectations::text);

  select preflight.id
  into v_existing_id
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = v_request_id
     or (
       preflight.actor_user_id = v_actor
       and preflight.preflight_request_sha256 = v_request_sha256
     )
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_ALREADY_EXISTS',
      'status', 409,
      'message', 'A preflight request ID or exact request was already used; tokens are never replayed'
    );
  end if;

  v_completed_at := pg_catalog.clock_timestamp();
  v_expires_at := v_completed_at + interval '180 seconds';
  v_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_token_sha256 := util.dataset_alias_execution_sha256(v_token);
  v_proof_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-preflight-proof.v1',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'environment', v_environment,
    'project_ref', v_project_ref,
    'server_context_sha256',
      util.dataset_alias_execution_sha256(v_server_context::text),
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'alias_plan_request_sha256', v_alias_plan_request_sha256,
    'freeze_sha256', v_bindings->>'freeze_sha256',
    'approval_identity_sha256',
      v_bindings->>'approval_identity_sha256',
    'plan_request_sha256', v_plan_request_sha256,
    'bindings_sha256', v_bindings_sha256,
    'expected_sha256', v_expected_sha256,
    'derivative_targets_sha256', v_targets_sha256,
    'gate_expectations', v_gate_expectations,
    'gate_expectations_sha256', v_gate_expectations_sha256,
    'failure_baseline_sha256', v_failure_baseline_sha256,
    'preflight_request_sha256', v_request_sha256,
    'completed_at', v_completed_at,
    'expires_at', v_expires_at
  );
  v_proof_sha256 := util.dataset_alias_execution_sha256(v_proof_material::text);

  insert into util.dataset_alias_execution_preflights (
    id,
    actor_user_id,
    actor_email,
    environment,
    project_ref,
    target_visibility,
    plan,
    freeze_envelope,
    approval_envelope,
    plan_sha256,
    operation_id,
    plan_request_sha256,
    bindings,
    bindings_sha256,
    expected,
    expected_sha256,
    derivative_targets,
    derivative_targets_sha256,
    gate_expectations,
    gate_expectations_sha256,
    failure_baseline_sha256,
    preflight_request_sha256,
    preflight_proof_sha256,
    freeze_sha256,
    approval_identity_sha256,
    token_sha256,
    completed_at,
    expires_at
  ) values (
    v_request_id,
    v_actor,
    lower(btrim(v_actor_email)),
    v_environment,
    v_project_ref,
    'owner_draft',
    v_plan,
    v_freeze,
    v_approval,
    v_plan_sha256,
    v_operation_id,
    v_plan_request_sha256,
    v_bindings,
    v_bindings_sha256,
    v_expected,
    v_expected_sha256,
    v_targets,
    v_targets_sha256,
    v_gate_expectations,
    v_gate_expectations_sha256,
    v_failure_baseline_sha256,
    v_request_sha256,
    v_proof_sha256,
    v_bindings->>'freeze_sha256',
    v_bindings->>'approval_identity_sha256',
    v_token_sha256,
    v_completed_at,
    v_expires_at
  );

  return v_proof_material || jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_preflight_guarded',
    'preflight_token', v_token,
    'preflight_proof_sha256', v_proof_sha256,
    'simulation', jsonb_build_object(
      'plan_rows', 52,
      'plan_exchanges', 59,
      'alias_audits', 55,
      'derivative_targets', 50,
      'rolled_back', true
    )
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_LOCK_BUSY',
      'status', 409,
      'message', 'Protected preflight could not acquire its bounded locks'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_CONCURRENT_CONFLICT',
      'status', 409,
      'message', 'A concurrent preflight consumed the same request identity'
    );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_alias_execution_preflight_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_preflight_guarded(p_request jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_execution_preflight_guarded(p_request jsonb) IS 'Rollback-only server validation for the exact owner-draft 52-row/59-exchange alias plan plus its sorted 23-flow/27-process derivative closure. A successful call persists one non-replayable token that expires 180 seconds after simulation completes.';


--
-- Name: cmd_dataset_alias_execution_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_alias_execution_read(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_request util.dataset_alias_execution_requests%rowtype;
  v_gate_receipts jsonb := '[]'::jsonb;
  v_gate_count integer := 0;
  v_alias_audit_count integer := 0;
  v_derivative_child_count integer := 0;
  v_derivative_flow_count integer := 0;
  v_derivative_process_count integer := 0;
  v_primary_closure jsonb;
  v_primary_closure_ok boolean := false;
  v_active_dispatch_grace boolean := false;
  v_initial_request_status text;
  v_initial_request_updated_at timestamp with time zone;
  v_proof_request_status text;
  v_proof_request_updated_at timestamp with time zone;
  v_request_changed_during_read boolean := false;
  v_batch_proof_read boolean := false;
  v_terminal_update_count integer := 0;
  v_terminal_update_status text;
  v_batch_proof jsonb;
  v_category text;
  v_now timestamp with time zone := pg_catalog.clock_timestamp();
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_READ_INVALID_REQUEST',
      'status', 400,
      'message', 'Exact protected execution request ID is required'
    );
  end if;

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = p_request_id
    and preflight.actor_user_id = v_actor;

  if v_preflight.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_REQUEST_NOT_FOUND',
      'status', 404,
      'message', 'No actor-owned protected preflight or execution exists'
    );
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'gate', receipt.gate_name,
          'expected_sha256', receipt.expected_sha256,
          'observed_sha256', receipt.observed_sha256,
          'status', receipt.status,
          'captured_at', receipt.captured_at,
          'receipt_sha256', receipt.receipt_sha256
        ) order by receipt.captured_at, receipt.gate_name
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into v_gate_receipts, v_gate_count
  from util.dataset_alias_execution_gate_receipts as receipt
  where receipt.preflight_id = p_request_id
    and receipt.actor_user_id = v_actor;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  if v_request.id is null then
    return jsonb_build_object(
      'ok', true,
      'command', 'cmd_dataset_alias_execution_read',
      'schema_version', 'dataset-alias-execution-status.v1',
      'request_id', p_request_id,
      'status', 'indeterminate',
      'execution_status', 'not_admitted',
      'code', case
        when v_preflight.consumed_at is null
          then 'ALIAS_EXECUTION_NOT_ADMITTED'
        else 'ALIAS_EXECUTION_ADMISSION_LEDGER_MISSING'
      end,
      'retry_allowed', false,
      'actor_user_id', v_actor,
      'environment', v_preflight.environment,
      'project_ref', v_preflight.project_ref,
      'plan_sha256', v_preflight.plan_sha256,
      'operation_id', v_preflight.operation_id,
      'plan_request_sha256', v_preflight.plan_request_sha256,
      'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
      'preflight_completed_at', v_preflight.completed_at,
      'preflight_expires_at', v_preflight.expires_at,
      'preflight_consumed_at', v_preflight.consumed_at,
      'gate_count', v_gate_count,
      'gates', v_gate_receipts
    );
  end if;

  v_initial_request_status := v_request.status;
  v_initial_request_updated_at := v_request.updated_at;

  v_active_dispatch_grace :=
    v_request.status in ('dispatching', 'dispatched', 'running')
    and v_now <= v_request.admitted_at + interval '120 seconds';

  if v_active_dispatch_grace then
    -- Do not run the heavyweight live closure while the one-shot executor may
    -- be committing.  Apart from wasting work, a status lock/readback race
    -- must never delay or misclassify the only authorized mutation attempt.
    v_primary_closure := jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-alias-primary-closure.v1',
      'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_PENDING',
      'live_closure_proof', false
    );
  else

  select count(*)::integer
  into v_alias_audit_count
  from public.command_audit_log as audit
  where audit.actor_user_id = v_actor
    and (
      (
        audit.command = 'cmd_dataset_alias_batch_guarded'
        and audit.payload->>'plan_sha256' = v_request.plan_sha256
        and audit.payload->>'operation_id' = v_request.operation_id
        and audit.payload->>'record_type' in ('row', 'batch_summary')
      )
      or (
        audit.command = 'cmd_dataset_alias_plan_guarded'
        and audit.payload->>'plan_request_sha256' =
          v_request.plan_request_sha256
        and audit.payload->>'record_type' = 'plan_summary'
      )
    );

  select
    count(*)::integer,
    count(*) filter (where target_table = 'flows')::integer,
    count(*) filter (where target_table = 'processes')::integer
  into
    v_derivative_child_count,
    v_derivative_flow_count,
    v_derivative_process_count
  from util.dataset_derivative_rebuild_requests as child
  where child.actor_user_id = v_actor
    and child.batch_id = p_request_id;

  v_primary_closure :=
    util.read_dataset_alias_execution_primary_closure(
      v_actor,
      v_preflight.plan
    );
  v_primary_closure_ok := coalesce(
    (v_primary_closure->>'live_closure_proof')::boolean,
    false
  );

  if v_request.status in ('dispatching', 'dispatched', 'running') then
    if v_alias_audit_count = 55
      and v_derivative_child_count = 50
      and v_derivative_flow_count = 23
      and v_derivative_process_count = 27
      and v_primary_closure_ok then
      update util.dataset_alias_execution_requests
      set
        status = 'derivatives_pending',
        primary_committed_at = coalesce(primary_committed_at, updated_at),
        updated_at = v_now
      where id = p_request_id
        and status in ('dispatching', 'dispatched', 'running');
    elsif (
        v_alias_audit_count > 0
        or v_derivative_child_count > 0
      ) and not v_primary_closure_ok then
      update util.dataset_alias_execution_requests
      set
        status = 'indeterminate',
        terminal_at = v_now,
        last_error = jsonb_build_object(
          'phase', 'reconcile',
          'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_MISMATCH',
          'primary_closure', v_primary_closure,
          'retry_allowed', false
        ),
        updated_at = v_now
      where id = p_request_id
        and status in ('dispatching', 'dispatched', 'running');
    elsif v_now > v_request.admitted_at + interval '120 seconds' then
      update util.dataset_alias_execution_requests
      set
        status = 'indeterminate',
        terminal_at = v_now,
        last_error = jsonb_build_object(
          'phase', 'reconcile',
          'code', 'ALIAS_EXECUTION_DISPATCH_OUTCOME_INDETERMINATE',
          'alias_audit_count', v_alias_audit_count,
          'derivative_child_count', v_derivative_child_count,
          'retry_allowed', false
        ),
        updated_at = v_now
      where id = p_request_id
        and status in ('dispatching', 'dispatched', 'running');
    end if;
  end if;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  v_request_changed_during_read :=
    v_request.status is distinct from v_initial_request_status
    or v_request.updated_at is distinct from v_initial_request_updated_at;

  if v_request_changed_during_read then
    -- VOLATILE PL/pgSQL statements can observe different READ COMMITTED
    -- snapshots.  If the executor or this reconciliation pass advanced the
    -- ledger after the first read, none of the evidence cached above is safe
    -- to use for another monotonic classification.  Return an explicit
    -- read-only conflict so the caller can poll again from the new state;
    -- execution admission and dispatch remain permanently non-retryable.
    return jsonb_build_object(
      'ok', false,
      'command', 'cmd_dataset_alias_execution_read',
      'schema_version', 'dataset-alias-execution-status.v1',
      'request_id', p_request_id,
      'code', 'ALIAS_EXECUTION_READ_STATE_CHANGED',
      'status', 409,
      'execution_status', v_request.status,
      'retry_allowed', false,
      'read_retry_allowed', true,
      'message', 'Execution state changed during readback; poll status again without redispatching'
    );
  end if;

  v_proof_request_status := v_request.status;
  v_proof_request_updated_at := v_request.updated_at;

  if v_derivative_child_count > 0
    or v_request.status in ('derivatives_pending', 'completed') then
    v_batch_proof_read := true;
    v_batch_proof := util.read_dataset_derivative_rebuild_batch(
      v_actor,
      p_request_id
    );

    select request.*
    into v_request
    from util.dataset_alias_execution_requests as request
    where request.id = p_request_id
      and request.actor_user_id = v_actor;

    if v_request.status is distinct from v_proof_request_status
      or v_request.updated_at is distinct from v_proof_request_updated_at then
      -- The derivative proof can be substantially more expensive than the
      -- parent-ledger read.  A different reader or the executor may classify
      -- the request while that proof is being assembled, so the cached proof
      -- must not be applied to the newly visible parent state.
      return jsonb_build_object(
        'ok', false,
        'command', 'cmd_dataset_alias_execution_read',
        'schema_version', 'dataset-alias-execution-status.v1',
        'request_id', p_request_id,
        'code', 'ALIAS_EXECUTION_READ_STATE_CHANGED',
        'status', 409,
        'execution_status', v_request.status,
        'retry_allowed', false,
        'read_retry_allowed', true,
        'message', 'Execution state changed during readback; poll status again without redispatching'
      );
    end if;
  end if;

  if v_request.status = 'derivatives_pending' then
    if v_alias_audit_count <> 55
      or v_derivative_child_count <> 50
      or v_derivative_flow_count <> 23
      or v_derivative_process_count <> 27
      or not v_primary_closure_ok then
      update util.dataset_alias_execution_requests
      set
        status = 'indeterminate',
        terminal_at = v_now,
        terminal_proof = jsonb_build_object(
          'primary_closure', v_primary_closure,
          'derivative_closure', v_batch_proof
        ),
        last_error = jsonb_build_object(
          'phase', 'readback',
          'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_MISMATCH',
          'alias_audit_count', v_alias_audit_count,
          'derivative_child_count', v_derivative_child_count,
          'primary_closure', v_primary_closure
        ),
        updated_at = v_now
      where id = p_request_id
        and status = 'derivatives_pending';
      get diagnostics v_terminal_update_count = row_count;
      if v_terminal_update_count = 1 then
        v_terminal_update_status := 'indeterminate';
      end if;
    elsif v_batch_proof->>'status' = 'completed'
      and coalesce((v_batch_proof->>'causal_terminal_proof')::boolean, false) then
      update util.dataset_alias_execution_requests
      set
        status = 'completed',
        terminal_at = v_now,
        terminal_proof = jsonb_build_object(
          'primary_closure', v_primary_closure,
          'derivative_closure', v_batch_proof
        ),
        updated_at = v_now
      where id = p_request_id
        and status = 'derivatives_pending';
      get diagnostics v_terminal_update_count = row_count;
      if v_terminal_update_count = 1 then
        v_terminal_update_status := 'completed';
      end if;
    elsif v_batch_proof->>'status' = 'failed' then
      update util.dataset_alias_execution_requests
      set
        status = 'failed',
        terminal_at = v_now,
        terminal_proof = jsonb_build_object(
          'primary_closure', v_primary_closure,
          'derivative_closure', v_batch_proof
        ),
        last_error = jsonb_build_object(
          'phase', 'derivative_readback',
          'code', coalesce(
            v_batch_proof->>'code',
            'ALIAS_EXECUTION_DERIVATIVE_CLOSURE_FAILED'
          )
        ),
        updated_at = v_now
      where id = p_request_id
        and status = 'derivatives_pending';
      get diagnostics v_terminal_update_count = row_count;
      if v_terminal_update_count = 1 then
        v_terminal_update_status := 'failed';
      end if;
    end if;
  end if;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  if v_batch_proof_read
    and (
      v_request.status is distinct from v_proof_request_status
      or v_request.updated_at is distinct from v_proof_request_updated_at
    )
    and not (
      v_terminal_update_count = 1
      and v_request.status is not distinct from v_terminal_update_status
      and v_request.updated_at is not distinct from v_now
    ) then
    -- A conditional terminal update with ROW_COUNT = 1 is this invocation's
    -- own monotonic classification.  Any other parent transition invalidates
    -- the cached derivative proof and must be retried as read-only polling.
    return jsonb_build_object(
      'ok', false,
      'command', 'cmd_dataset_alias_execution_read',
      'schema_version', 'dataset-alias-execution-status.v1',
      'request_id', p_request_id,
      'code', 'ALIAS_EXECUTION_READ_STATE_CHANGED',
      'status', 409,
      'execution_status', v_request.status,
      'retry_allowed', false,
      'read_retry_allowed', true,
      'message', 'Execution state changed during readback; poll status again without redispatching'
    );
  end if;

  end if;

  v_category := case v_request.status
    when 'completed' then 'passed'
    when 'failed' then 'failed'
    when 'indeterminate' then 'indeterminate'
    else 'pending'
  end;

  -- A stored completion is not allowed to hide later live-state drift during
  -- an independent readback.  The immutable ledger remains completed, but the
  -- fresh response fails closed if its current causal proof no longer passes.
  if v_request.status = 'completed'
    and (
      not v_primary_closure_ok
      or v_batch_proof is null
      or v_batch_proof->>'status' is distinct from 'completed'
      or coalesce((v_batch_proof->>'causal_terminal_proof')::boolean, false)
        is not true
    ) then
    v_category := 'failed';
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_read',
    'schema_version', 'dataset-alias-execution-status.v1',
    'request_id', p_request_id,
    'status', v_category,
    'execution_status', v_request.status,
    'retry_allowed', false,
    'actor_user_id', v_actor,
    'environment', v_preflight.environment,
    'project_ref', v_preflight.project_ref,
    'target_visibility', v_preflight.target_visibility,
    'plan_sha256', v_request.plan_sha256,
    'operation_id', v_request.operation_id,
    'plan_request_sha256', v_request.plan_request_sha256,
    'freeze_sha256', v_request.freeze_sha256,
    'approval_identity_sha256', v_request.approval_identity_sha256,
    'approval_text_sha256', v_request.approval_text_sha256,
    'derivative_target_set_sha256', v_request.derivative_target_set_sha256,
    'server_derivative_targets_sha256',
      v_preflight.derivative_targets_sha256,
    'preflight_proof_sha256', v_request.preflight_proof_sha256,
    'admission_request_sha256', v_request.admission_request_sha256,
    'gate_results_sha256', v_request.gate_results_sha256,
    'attempt_count', v_request.attempt_count,
    'dispatch_count', v_request.dispatch_count,
    'net_request_id', v_request.net_request_id::text,
    'preflight_completed_at', v_preflight.completed_at,
    'preflight_expires_at', v_preflight.expires_at,
    'preflight_consumed_at', v_preflight.consumed_at,
    'admitted_at', v_request.admitted_at,
    'dispatched_at', v_request.dispatched_at,
    'started_at', v_request.started_at,
    'primary_committed_at', v_request.primary_committed_at,
    'terminal_at', v_request.terminal_at,
    'gate_count', v_gate_count,
    'gates', v_gate_receipts,
    'primary_readback', jsonb_build_object(
      'row_count', case
        when v_alias_audit_count = 55 and v_primary_closure_ok then 52
        else null
      end,
      'exchange_count', case
        when v_alias_audit_count = 55 and v_primary_closure_ok then 59
        else null
      end,
      'alias_audit_count', v_alias_audit_count,
      'live_closure_proof', v_primary_closure_ok,
      'closure', v_primary_closure
    ),
    'derivative_readback', coalesce(
      v_batch_proof,
      jsonb_build_object(
        'schema_version', 'dataset-derivative-rebuild-batch-status.v1',
        'batch_id', p_request_id,
        'status', 'not_started',
        'code', 'DERIVATIVE_BATCH_NOT_STARTED',
        'proof_level', 'none',
        'proof_deferred', false,
        'target_count', v_derivative_child_count,
        'flow_count', v_derivative_flow_count,
        'process_count', v_derivative_process_count,
        'completed_count', 0,
        'nonterminal_count', 0,
        'failed_count', 0,
        'invalid_proof_count', null,
        'causal_terminal_proof', false,
        'targets', '[]'::jsonb
      )
    ),
    'error', v_request.last_error
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_READ_LOCK_BUSY',
      'status', 'indeterminate',
      'message', 'Protected execution status row is busy; readback did not retry or redispatch'
    );
end;
$$;


ALTER FUNCTION public.cmd_dataset_alias_execution_read(p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_read(p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_execution_read(p_request_id uuid) IS 'Actor-only status and reconciliation for one protected attempt. It may monotonically classify durable evidence as derivatives_pending/completed/failed/indeterminate, but it never dispatches, retries, replays, or changes dataset rows.';


--
-- Name: cmd_dataset_alias_plan_guarded(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_alias_plan_guarded(p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '45s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_schema_version constant text := 'dataset-alias-plan.v1';
  v_batch_schema_version constant text := 'dataset-alias-batch.v1';
  v_command constant text := 'cmd_dataset_alias_plan_guarded';
  v_plan_sha256 text;
  v_operation_id text;
  v_target_visibility text;
  v_batches jsonb;
  v_time_batch jsonb;
  v_length_time_batch jsonb;
  v_batch jsonb;
  v_dimension text;
  v_expected_dimension text;
  v_expected_factor text;
  v_expected_action_count integer;
  v_action_count integer;
  v_owned_action_count integer;
  v_action_distinct_count integer;
  v_batch_request_sha256 text;
  v_time_batch_request_sha256 text;
  v_length_time_batch_request_sha256 text;
  v_plan_request_sha256 text;
  v_time_result jsonb;
  v_length_time_result jsonb;
  v_batch_result jsonb;
  v_failure_result jsonb;
  v_failed_dimension text;
  v_time_replay boolean;
  v_length_time_replay boolean;
  v_time_summary_audit_id bigint;
  v_length_time_summary_audit_id bigint;
  v_plan_summary_audit_id bigint;
  v_existing_plan_audit_count integer;
  v_batch_proof_count integer;
  v_support_owned boolean;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_plan is not null and pg_column_size(p_plan) > 268435456 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_REQUEST_TOO_LARGE',
      'status', 413,
      'message', 'Alias plan request exceeds the 256 MiB database limit'
    );
  end if;

  if jsonb_typeof(p_plan) is distinct from 'object'
    or not (p_plan ?& array[
      'schema_version',
      'plan_sha256',
      'operation_id',
      'target_visibility',
      'batches'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_plan) as plan_key(key)
      where plan_key.key <> all (array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'target_visibility',
        'batches'
      ])
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_REQUEST',
      'status', 400,
      'message', 'Plan request must match dataset-alias-plan.v1 exactly'
    );
  end if;

  if jsonb_typeof(p_plan->'schema_version') is distinct from 'string'
    or p_plan->>'schema_version' <> v_schema_version
    or jsonb_typeof(p_plan->'plan_sha256') is distinct from 'string'
    or (p_plan->>'plan_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_plan->'operation_id') is distinct from 'string'
    or nullif(btrim(p_plan->>'operation_id'), '') is null
    or octet_length(p_plan->>'operation_id') > 512
    or jsonb_typeof(p_plan->'target_visibility') is distinct from 'string'
    or p_plan->>'target_visibility' <> 'owner_draft'
    or jsonb_typeof(p_plan->'batches') is distinct from 'array'
    or jsonb_array_length(p_plan->'batches') <> 2 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_REQUEST',
      'status', 400,
      'message', 'Plan identity, owner_draft visibility, and exactly two batches are required'
    );
  end if;

  v_plan_sha256 := p_plan->>'plan_sha256';
  v_operation_id := btrim(p_plan->>'operation_id');
  v_target_visibility := p_plan->>'target_visibility';
  v_batches := p_plan->'batches';
  v_time_batch := v_batches->0;
  v_length_time_batch := v_batches->1;

  -- Requiring a stable order makes the whole-plan request hash deterministic
  -- and prevents callers from substituting two copies of one dimension.
  if jsonb_typeof(v_time_batch) is distinct from 'object'
    or jsonb_typeof(v_length_time_batch) is distinct from 'object'
    or v_time_batch->>'dimension' is distinct from 'time'
    or v_length_time_batch->>'dimension' is distinct from 'length_time' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_BATCH_SET',
      'status', 400,
      'message', 'batches must contain time followed by length_time exactly once'
    );
  end if;

  -- Validate enough of both batch envelopes to perform a safe, non-locking
  -- ownership preflight.  The internal executor repeats the complete semantic,
  -- payload, closure, hash, and locked-row validation after the broad locks.
  for v_batch, v_expected_dimension, v_expected_factor, v_expected_action_count in
    select *
    from (values
      (v_time_batch, 'time'::text, '0.00011415525114155251'::text, 25),
      (v_length_time_batch, 'length_time'::text, '1000'::text, 27)
    ) as expected(batch, dimension, factor, action_count)
  loop
    if not (v_batch ?& array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'batch_id',
        'dimension',
        'factor',
        'target_visibility',
        'target',
        'actions'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_batch) as batch_key(key)
        where batch_key.key <> all (array[
          'schema_version',
          'plan_sha256',
          'operation_id',
          'batch_id',
          'dimension',
          'factor',
          'target_visibility',
          'target',
          'actions'
        ])
      )
      or jsonb_typeof(v_batch->'schema_version') is distinct from 'string'
      or v_batch->>'schema_version' <> v_batch_schema_version
      or jsonb_typeof(v_batch->'plan_sha256') is distinct from 'string'
      or v_batch->>'plan_sha256' is distinct from v_plan_sha256
      or jsonb_typeof(v_batch->'operation_id') is distinct from 'string'
      or btrim(v_batch->>'operation_id') is distinct from v_operation_id
      or jsonb_typeof(v_batch->'batch_id') is distinct from 'string'
      or nullif(btrim(v_batch->>'batch_id'), '') is null
      or octet_length(v_batch->>'batch_id') > 512
      or jsonb_typeof(v_batch->'dimension') is distinct from 'string'
      or v_batch->>'dimension' is distinct from v_expected_dimension
      or jsonb_typeof(v_batch->'factor') is distinct from 'string'
      or v_batch->>'factor' is distinct from v_expected_factor
      or jsonb_typeof(v_batch->'target_visibility') is distinct from 'string'
      or v_batch->>'target_visibility' is distinct from v_target_visibility
      or jsonb_typeof(v_batch->'target') is distinct from 'object'
      or not ((v_batch->'target') ?& array[
        'flowproperty',
        'unitgroup',
        'source_unitgroup'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_batch->'target') as target_key(key)
        where target_key.key <> all (array[
          'flowproperty',
          'unitgroup',
          'source_unitgroup'
        ])
      )
      or jsonb_typeof(v_batch->'actions') is distinct from 'array'
      or jsonb_array_length(v_batch->'actions') <> v_expected_action_count
      or exists (
        select 1
        from jsonb_array_elements(v_batch->'actions') as action_item(value)
        where jsonb_typeof(action_item.value) is distinct from 'object'
          or jsonb_typeof(action_item.value->'table') is distinct from 'string'
          or action_item.value->>'table' not in (
            'flowproperties', 'flows', 'processes'
          )
          or jsonb_typeof(action_item.value->'id') is distinct from 'string'
          or (action_item.value->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or jsonb_typeof(action_item.value->'version') is distinct from 'string'
          or (action_item.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
          or jsonb_typeof(action_item.value->'expected_state_code') is distinct from 'number'
          or action_item.value->>'expected_state_code' <> '0'
      ) then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_INVALID_BATCH',
        'status', 400,
        'message', 'Both batch envelopes must match the frozen full-plan contract'
      );
    end if;

    if exists (
      select 1
      from (values
        (v_batch#>'{target,flowproperty}'),
        (v_batch#>'{target,unitgroup}'),
        (v_batch#>'{target,source_unitgroup}')
      ) as support_item(value)
      where jsonb_typeof(support_item.value) is distinct from 'object'
        or jsonb_typeof(support_item.value->'id') is distinct from 'string'
        or (support_item.value->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(support_item.value->'version') is distinct from 'string'
        or (support_item.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    ) then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_INVALID_BATCH',
        'status', 400,
        'message', 'Both batch envelopes must carry valid support row keys'
      );
    end if;

    -- This preflight intentionally happens before either dimension can reach
    -- the internal executor's SHARE ROW EXCLUSIVE locks.  It is non-locking,
    -- uniform, and non-disclosing; the executor rechecks after taking locks.
    select
      exists (
        select 1
        from public.flowproperties as target_fp
        where target_fp.id = (v_batch#>>'{target,flowproperty,id}')::uuid
          and target_fp.version::text = v_batch#>>'{target,flowproperty,version}'
          and target_fp.user_id = v_actor
          and target_fp.state_code = 0
      )
      and exists (
        select 1
        from public.unitgroups as target_ug
        where target_ug.id = (v_batch#>>'{target,unitgroup,id}')::uuid
          and target_ug.version::text = v_batch#>>'{target,unitgroup,version}'
          and target_ug.user_id = v_actor
          and target_ug.state_code = 0
      )
      and exists (
        select 1
        from public.unitgroups as source_ug
        where source_ug.id = (v_batch#>>'{target,source_unitgroup,id}')::uuid
          and source_ug.version::text = v_batch#>>'{target,source_unitgroup,version}'
          and source_ug.user_id = v_actor
          and source_ug.state_code = 0
      )
    into v_support_owned;

    select count(*)
    into v_owned_action_count
    from jsonb_array_elements(v_batch->'actions') as action_item(value)
    where (
      action_item.value->>'table' = 'flowproperties'
      and exists (
        select 1
        from public.flowproperties as dataset_row
        where dataset_row.id = (action_item.value->>'id')::uuid
          and dataset_row.version::text = action_item.value->>'version'
          and dataset_row.user_id = v_actor
          and dataset_row.state_code = 0
      )
    ) or (
      action_item.value->>'table' = 'flows'
      and exists (
        select 1
        from public.flows as dataset_row
        where dataset_row.id = (action_item.value->>'id')::uuid
          and dataset_row.version::text = action_item.value->>'version'
          and dataset_row.user_id = v_actor
          and dataset_row.state_code = 0
      )
    ) or (
      action_item.value->>'table' = 'processes'
      and exists (
        select 1
        from public.processes as dataset_row
        where dataset_row.id = (action_item.value->>'id')::uuid
          and dataset_row.version::text = action_item.value->>'version'
          and dataset_row.user_id = v_actor
          and dataset_row.state_code = 0
      )
    );

    if not v_support_owned
      or v_owned_action_count <> v_expected_action_count then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_SCOPE_MISMATCH',
        'status', 409,
        'message', 'Full-plan owner-draft scope does not match the authenticated actor'
      );
    end if;
  end loop;

  if v_time_batch->>'batch_id' = v_length_time_batch->>'batch_id' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_BATCH_SET',
      'status', 400,
      'message', 'Batch IDs must be distinct'
    );
  end if;

  select count(distinct (
    action_item.value->>'table',
    action_item.value->>'id',
    action_item.value->>'version'
  ))
  into v_action_distinct_count
  from jsonb_array_elements(v_batches) as batch_item(value)
  cross join lateral jsonb_array_elements(
    batch_item.value->'actions'
  ) as action_item(value);

  if v_action_distinct_count <> 52
    or (v_time_batch#>>'{target,flowproperty,id}') =
      (v_length_time_batch#>>'{target,flowproperty,id}')
    or (v_time_batch#>>'{target,flowproperty,id}') in (
      select action_item.value->>'id'
      from jsonb_array_elements(v_batches) as batch_item(value)
      cross join lateral jsonb_array_elements(
        batch_item.value->'actions'
      ) as action_item(value)
      where action_item.value->>'table' = 'flowproperties'
    )
    or (v_length_time_batch#>>'{target,flowproperty,id}') in (
      select action_item.value->>'id'
      from jsonb_array_elements(v_batches) as batch_item(value)
      cross join lateral jsonb_array_elements(
        batch_item.value->'actions'
      ) as action_item(value)
      where action_item.value->>'table' = 'flowproperties'
    )
    or (
      select count(distinct support_ug.id)
      from (values
        (v_time_batch#>>'{target,unitgroup,id}'),
        (v_time_batch#>>'{target,source_unitgroup,id}'),
        (v_length_time_batch#>>'{target,unitgroup,id}'),
        (v_length_time_batch#>>'{target,source_unitgroup,id}')
      ) as support_ug(id)
    ) <> 4 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_OVERLAPPING_BATCHES',
      'status', 400,
      'message', 'The two frozen dimensions must use 52 distinct action rows and disjoint support rows'
    );
  end if;

  v_time_batch_request_sha256 := encode(
    extensions.digest(convert_to(v_time_batch::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_length_time_batch_request_sha256 := encode(
    extensions.digest(convert_to(v_length_time_batch::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_plan_request_sha256 := encode(
    extensions.digest(convert_to(p_plan::text, 'UTF8'), 'sha256'),
    'hex'
  );

  -- PL/pgSQL exception blocks are subtransactions.  Any returned batch error
  -- or unexpected second-dimension exception is raised inside this block,
  -- caught outside it, and therefore rolls back the first dimension's rows and
  -- audits before a structured plan failure is returned.
  begin
    v_failed_dimension := 'time';
    v_time_result := public.cmd_dataset_alias_batch_guarded(v_time_batch);
    if coalesce((v_time_result->>'ok')::boolean, false) is not true then
      v_failure_result := v_time_result;
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias time batch rejected';
    end if;

    v_failed_dimension := 'length_time';
    v_length_time_result :=
      public.cmd_dataset_alias_batch_guarded(v_length_time_batch);
    if coalesce((v_length_time_result->>'ok')::boolean, false) is not true then
      v_failure_result := v_length_time_result;
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias length_time batch rejected';
    end if;

    if v_time_result->>'dimension' is distinct from 'time'
      or v_time_result->>'target_visibility' is distinct from 'owner_draft'
      or v_time_result->>'batch_request_sha256'
        is distinct from v_time_batch_request_sha256
      or v_time_result->>'row_count' is distinct from '25'
      or v_time_result->>'exchange_count' is distinct from '20'
      or (v_time_result->>'summary_audit_id') !~ '^[0-9]+$'
      or jsonb_typeof(v_time_result->'audit') is distinct from 'array'
      or jsonb_array_length(v_time_result->'audit') <> 25
      or v_length_time_result->>'dimension' is distinct from 'length_time'
      or v_length_time_result->>'target_visibility' is distinct from 'owner_draft'
      or v_length_time_result->>'batch_request_sha256'
        is distinct from v_length_time_batch_request_sha256
      or v_length_time_result->>'row_count' is distinct from '27'
      or v_length_time_result->>'exchange_count' is distinct from '39'
      or (v_length_time_result->>'summary_audit_id') !~ '^[0-9]+$'
      or jsonb_typeof(v_length_time_result->'audit') is distinct from 'array'
      or jsonb_array_length(v_length_time_result->'audit') <> 27 then
      v_failure_result := jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_BATCH_PROOF_MISMATCH',
        'status', 409,
        'message', 'A dimension result did not prove the exact frozen batch'
      );
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias dimension proof mismatch';
    end if;

    v_time_replay := (v_time_result->>'idempotent_replay')::boolean;
    v_length_time_replay :=
      (v_length_time_result->>'idempotent_replay')::boolean;
    v_time_summary_audit_id :=
      (v_time_result->>'summary_audit_id')::bigint;
    v_length_time_summary_audit_id :=
      (v_length_time_result->>'summary_audit_id')::bigint;

    if v_time_replay is distinct from v_length_time_replay then
      v_failure_result := jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_PARTIAL_STATE',
        'status', 409,
        'message', 'The two dimensions are split between fresh and replay states'
      );
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias plan partial state';
    end if;

    select count(*)
    into v_batch_proof_count
    from public.command_audit_log as batch_audit
    where batch_audit.id in (
        v_time_summary_audit_id,
        v_length_time_summary_audit_id
      )
      and batch_audit.command = 'cmd_dataset_alias_batch_guarded'
      and batch_audit.actor_user_id = v_actor
      and batch_audit.target_table is null
      and batch_audit.payload->>'record_type' = 'batch_summary'
      and (
        (
          batch_audit.id = v_time_summary_audit_id
          and batch_audit.payload->>'dimension' = 'time'
          and batch_audit.payload->>'batch_request_sha256' =
            v_time_batch_request_sha256
        ) or (
          batch_audit.id = v_length_time_summary_audit_id
          and batch_audit.payload->>'dimension' = 'length_time'
          and batch_audit.payload->>'batch_request_sha256' =
            v_length_time_batch_request_sha256
        )
      );

    if v_batch_proof_count <> 2 then
      v_failure_result := jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_BATCH_PROOF_MISMATCH',
        'status', 409,
        'message', 'Dimension audit proofs do not match the exact full plan'
      );
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias dimension audits mismatch';
    end if;

    select count(*)
    into v_existing_plan_audit_count
    from public.command_audit_log as plan_audit
    where plan_audit.command = v_command
      and plan_audit.actor_user_id = v_actor
      and plan_audit.payload->>'plan_request_sha256' = v_plan_request_sha256;

    v_plan_summary_audit_id := null;
    select plan_audit.id
    into v_plan_summary_audit_id
    from public.command_audit_log as plan_audit
    where plan_audit.command = v_command
      and plan_audit.actor_user_id = v_actor
      and plan_audit.target_table is null
      and plan_audit.target_id is null
      and plan_audit.target_version is null
      and plan_audit.payload->>'record_type' = 'plan_summary'
      and plan_audit.payload->>'schema_version' = v_schema_version
      and plan_audit.payload->>'plan_sha256' = v_plan_sha256
      and plan_audit.payload->>'operation_id' = v_operation_id
      and plan_audit.payload->>'target_visibility' = v_target_visibility
      and plan_audit.payload->>'plan_request_sha256' = v_plan_request_sha256
      and plan_audit.payload->>'hash_algorithm' = 'postgres-jsonb-text-sha256'
      and plan_audit.payload->>'time_batch_request_sha256' =
        v_time_batch_request_sha256
      and plan_audit.payload->>'length_time_batch_request_sha256' =
        v_length_time_batch_request_sha256
      and plan_audit.payload->>'time_batch_summary_audit_id' =
        v_time_summary_audit_id::text
      and plan_audit.payload->>'length_time_batch_summary_audit_id' =
        v_length_time_summary_audit_id::text
      and plan_audit.payload->>'batch_count' = '2'
      and plan_audit.payload->>'row_count' = '52'
      and plan_audit.payload->>'exchange_count' = '59'
      and plan_audit.payload->>'support_owner_user_id' = v_actor::text
    order by plan_audit.id desc
    limit 1;

    if v_time_replay then
      if v_existing_plan_audit_count <> 1
        or v_plan_summary_audit_id is null then
        v_failure_result := jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_PLAN_REPLAY_UNPROVEN',
          'status', 409,
          'message', 'Committed dimensions have no exact full-plan audit proof'
        );
        raise exception using
          errcode = 'P0001',
          message = 'Guarded alias plan replay unproven';
      end if;
    else
      if v_existing_plan_audit_count <> 0
        or v_plan_summary_audit_id is not null then
        v_failure_result := jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_PLAN_AUDIT_STATE_CONFLICT',
          'status', 409,
          'message', 'A plan audit exists while both dimensions are fresh'
        );
        raise exception using
          errcode = 'P0001',
          message = 'Guarded alias plan audit state conflict';
      end if;

      insert into public.command_audit_log (
        command,
        actor_user_id,
        target_table,
        target_id,
        target_version,
        payload
      )
      values (
        v_command,
        v_actor,
        null,
        null,
        null,
        jsonb_build_object(
          'record_type', 'plan_summary',
          'schema_version', v_schema_version,
          'plan_sha256', v_plan_sha256,
          'operation_id', v_operation_id,
          'target_visibility', v_target_visibility,
          'plan_request_sha256', v_plan_request_sha256,
          'hash_algorithm', 'postgres-jsonb-text-sha256',
          'time_batch_request_sha256', v_time_batch_request_sha256,
          'length_time_batch_request_sha256',
            v_length_time_batch_request_sha256,
          'time_batch_summary_audit_id', v_time_summary_audit_id::text,
          'length_time_batch_summary_audit_id',
            v_length_time_summary_audit_id::text,
          'batch_count', 2,
          'row_count', 52,
          'exchange_count', 59,
          'support_owner_user_id', v_actor
        )
      )
      returning id into v_plan_summary_audit_id;
    end if;
  exception
    when others then
      if v_failure_result is null then
        v_failure_result := jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_PLAN_EXECUTION_FAILED',
          'status', 409,
          'message', 'The full owner-draft plan failed and was rolled back'
        );
      end if;
  end;

  if v_failure_result is not null then
    return v_failure_result || jsonb_build_object(
      'failed_dimension', v_failed_dimension,
      'plan_rolled_back', true
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'schema_version', v_schema_version,
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'target_visibility', v_target_visibility,
    'plan_request_sha256', v_plan_request_sha256,
    'batch_count', 2,
    'row_count', 52,
    'exchange_count', 59,
    'summary_audit_id', v_plan_summary_audit_id::text,
    'batches', jsonb_build_array(v_time_result, v_length_time_result),
    'idempotent_replay', v_time_replay
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_alias_plan_guarded(p_plan jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_plan_guarded(p_plan jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_alias_plan_guarded(p_plan jsonb) IS 'Internal owner-draft alias transaction used by the protected one-shot executor and rollback-only preflight. Direct authenticated/service-role API execution is revoked because this legacy function supports idempotent replay.';


--
-- Name: cmd_dataset_assert_review_submit_gate_passed(text, uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_assert_review_submit_gate_passed(p_table text, p_id uuid, p_version text, p_gate_run_id uuid DEFAULT NULL::uuid, p_revision_checksum text DEFAULT NULL::text, p_policy_profile text DEFAULT 'review_submit_fast.v1'::text, p_report_schema_version text DEFAULT 'review_submit_gate_report.v1'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_dataset_row jsonb;
  v_owner_id uuid;
  v_run public.dataset_review_submit_gate_runs%rowtype;
  v_worker_job public.worker_jobs%rowtype;
  v_payload jsonb;
  v_result_checksum text;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table <> 'processes' then
    return jsonb_build_object('ok', true);
  end if;

  v_dataset_row := public.cmd_review_get_dataset_row(p_table, p_id, p_version, false);

  if v_dataset_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_dataset_row->>'user_id', '')::uuid;

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can submit review'
    );
  end if;

  if p_gate_run_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_REQUIRED',
      'status', 400,
      'message', 'A passed review-submit gate run is required before process review submission'
    );
  end if;

  if coalesce(p_revision_checksum, '') !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVISION_CHECKSUM_REQUIRED',
      'status', 400,
      'message', 'revisionChecksum must be a lowercase SHA-256 hex digest'
    );
  end if;

  select *
    into v_run
  from public.dataset_review_submit_gate_runs
  where id = p_gate_run_id;

  if v_run.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
      'status', 404,
      'message', 'Review-submit gate run not found'
    );
  end if;

  v_payload := public.cmd_dataset_review_submit_gate_payload(v_run);

  if v_run.dataset_table <> p_table
    or v_run.dataset_id <> p_id
    or v_run.dataset_version <> p_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_DATASET_MISMATCH',
      'status', 409,
      'message', 'Review-submit gate run belongs to a different dataset revision'
    );
  end if;

  if v_run.revision_checksum <> p_revision_checksum then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_STALE',
      'status', 409,
      'message', 'Review-submit gate run is stale for the submitted dataset revision',
      'details', public.cmd_dataset_review_submit_gate_payload(v_run, 'stale')
    );
  end if;

  if v_run.policy_profile <> coalesce(p_policy_profile, '') then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_POLICY_MISMATCH',
      'status', 409,
      'message', 'Review-submit gate run used a different policy profile',
      'details', jsonb_build_object(
        'expected', p_policy_profile,
        'actual', v_run.policy_profile
      )
    );
  end if;

  if v_run.report_schema_version <> coalesce(p_report_schema_version, '') then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_SCHEMA_MISMATCH',
      'status', 409,
      'message', 'Review-submit gate run used a different report schema version',
      'details', jsonb_build_object(
        'expected', p_report_schema_version,
        'actual', v_run.report_schema_version
      )
    );
  end if;

  if v_run.worker_job_id is not null then
    select *
      into v_worker_job
    from public.worker_jobs
    where id = v_run.worker_job_id;

    if v_worker_job.id is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
        'status', 404,
        'message', 'Review-submit gate worker job not found',
        'details', v_payload
      );
    end if;

    if v_worker_job.job_kind <> 'review_submit.gate'
      or v_worker_job.subject_type <> v_run.dataset_table
      or v_worker_job.subject_id <> v_run.dataset_id
      or v_worker_job.subject_version <> v_run.dataset_version
      or v_worker_job.requested_by is distinct from v_run.requested_by
      or v_worker_job.payload_json #>> '{datasetRevision,revisionChecksum}' is distinct from v_run.revision_checksum
      or v_worker_job.payload_json #>> '{policy,profile}' is distinct from v_run.policy_profile
      or v_worker_job.payload_json #>> '{policy,reportSchemaVersion}' is distinct from v_run.report_schema_version then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_DATASET_MISMATCH',
        'status', 409,
        'message', 'Review-submit gate worker job does not match this gate run',
        'details', v_payload
      );
    end if;

    if v_worker_job.status in ('queued', 'running', 'waiting', 'stale') then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_NOT_READY',
        'status', 409,
        'message', 'Review-submit gate has not passed yet',
        'details', v_payload
      );
    end if;

    if v_worker_job.status = 'blocked' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_BLOCKED',
        'status', 409,
        'message', 'Review-submit gate blocked this dataset revision',
        'details', v_payload
      );
    end if;

    if v_worker_job.status <> 'completed' then
      return jsonb_build_object(
        'ok', false,
        'code', coalesce(v_worker_job.error_code, 'REVIEW_SUBMIT_GATE_ERROR'),
        'status', 502,
        'message', coalesce(v_worker_job.error_message, 'Review-submit gate failed before review submission'),
        'details', v_payload
      );
    end if;

    if coalesce(v_worker_job.result_json->>'status', '') <> 'passed' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_ERROR',
        'status', 502,
        'message', 'Review-submit gate worker job completed without a passed result',
        'details', v_payload
      );
    end if;

    v_result_checksum := v_worker_job.result_json #>> '{datasetRevision,revisionChecksum}';
    if v_result_checksum is not null and v_result_checksum <> p_revision_checksum then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_STALE',
        'status', 409,
        'message', 'Review-submit gate worker result is stale for the submitted dataset revision',
        'details', public.cmd_dataset_review_submit_gate_payload(v_run, 'stale')
      );
    end if;

    return jsonb_build_object(
      'ok', true,
      'data', v_payload
    );
  end if;

  case v_run.status
    when 'passed' then
      return jsonb_build_object(
        'ok', true,
        'data', v_payload
      );
    when 'blocked' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_BLOCKED',
        'status', 409,
        'message', 'Review-submit gate blocked this dataset revision',
        'details', v_payload
      );
    when 'queued', 'running' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_NOT_READY',
        'status', 409,
        'message', 'Review-submit gate has not passed yet',
        'details', v_payload
      );
    when 'error' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_ERROR',
        'status', 502,
        'message', 'Review-submit gate failed before review submission',
        'details', v_payload
      );
    else
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_STALE',
        'status', 409,
        'message', 'Review-submit gate run is stale for the submitted dataset revision',
        'details', public.cmd_dataset_review_submit_gate_payload(v_run, 'stale')
      );
  end case;
end;
$_$;


ALTER FUNCTION public.cmd_dataset_assert_review_submit_gate_passed(p_table text, p_id uuid, p_version text, p_gate_run_id uuid, p_revision_checksum text, p_policy_profile text, p_report_schema_version text) OWNER TO postgres;

--
-- Name: cmd_dataset_assign_team(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_assign_team(p_table text, p_id uuid, p_version text, p_team_id uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
  v_actor_has_team_role boolean;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can change dataset team ownership'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 403,
      'message', 'Published data cannot be reassigned to another team',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 403,
      'message', 'Data is under review and cannot be reassigned',
      'details', jsonb_build_object(
        'state_code', 20,
        'review_state_code', v_state_code
      )
    );
  end if;

  select exists (
    select 1
    from public.roles r
    where r.user_id = v_actor
      and r.team_id = p_team_id
      and r.role not in ('is_invited', 'rejected')
  )
    into v_actor_has_team_role;

  if not v_actor_has_team_role then
    return jsonb_build_object(
      'ok', false,
      'code', 'TEAM_MEMBERSHIP_REQUIRED',
      'status', 403,
      'message', 'You must belong to the target team before assigning dataset ownership'
    );
  end if;

  execute format(
    'update public.%I as t
        set team_id = $1,
            modified_at = now()
      where t.id = $2
        and t.version = $3
    returning to_jsonb(t)',
    p_table
  )
    into v_updated_row
    using p_team_id, p_id, p_version;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_assign_team',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_assign_team(p_table text, p_id uuid, p_version text, p_team_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_create(text, uuid, jsonb, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_create(p_table text, p_id uuid, p_json_ordered jsonb, p_model_id uuid DEFAULT NULL::uuid, p_rule_verification boolean DEFAULT NULL::boolean, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_created_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table = 'lifecyclemodels' then
    return jsonb_build_object(
      'ok', false,
      'code', 'LIFECYCLEMODEL_BUNDLE_REQUIRED',
      'status', 400,
      'message', 'Lifecycle models must use bundle create and delete commands'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  if p_json_ordered is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'JSON_ORDERED_REQUIRED',
      'status', 400,
      'message', 'jsonOrdered is required'
    );
  end if;

  if p_table <> 'processes' and p_model_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_NOT_ALLOWED',
      'status', 400,
      'message', 'modelId is only allowed for process dataset creation'
    );
  end if;

  if p_table = 'flows' then
    perform set_config('lock_timeout', '2s', true);
    perform set_config('statement_timeout', '8s', true);
  end if;

  begin
    if p_table = 'processes' then
      execute format(
        'insert into public.%I as t (id, json_ordered, model_id, rule_verification)
         values ($1, $2::json, $3, $4)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', t.model_id,
           ''rule_verification'', t.rule_verification
         )',
        p_table
      )
        into v_created_row
        using p_id, p_json_ordered, p_model_id, p_rule_verification;
    else
      execute format(
        'insert into public.%I as t (id, json_ordered, rule_verification)
         values ($1, $2::json, $3)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', null,
           ''rule_verification'', t.rule_verification
         )',
        p_table
      )
        into v_created_row
        using p_id, p_json_ordered, p_rule_verification;
    end if;
  exception
    when lock_not_available then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_LOCK_TIMEOUT',
        'status', 503,
        'message', 'Dataset creation is temporarily blocked by concurrent database work'
      );
    when query_canceled then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_TIMEOUT',
        'status', 503,
        'message', 'Dataset creation exceeded the database timeout'
      );
    when unique_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23505',
        'status', 409,
        'message', 'Dataset with the same id and version already exists'
      );
    when not_null_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23502',
        'status', 400,
        'message', 'Dataset creation requires a valid id, version, and jsonOrdered payload'
      );
    when check_violation then
      return jsonb_build_object(
        'ok', false,
        'code', sqlstate,
        'status', 400,
        'message', sqlerrm
      );
  end;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_create',
    v_actor,
    p_table,
    p_id,
    nullif(v_created_row->>'version', ''),
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_created_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_create(p_table text, p_id uuid, p_json_ordered jsonb, p_model_id uuid, p_rule_verification boolean, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_create_version(text, uuid, text, jsonb, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_create_version(p_table text, p_id uuid, p_source_version text, p_json_ordered jsonb, p_model_id uuid DEFAULT NULL::uuid, p_rule_verification boolean DEFAULT NULL::boolean, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_root_key text;
  v_uri_slug text;
  v_source_exists boolean := false;
  v_source_version text := nullif(btrim(coalesce(p_source_version, '')), '');
  v_highest_version text;
  v_parts integer[];
  v_next_version text;
  v_next_uri text;
  v_payload jsonb;
  v_dataset jsonb;
  v_admin jsonb;
  v_pub jsonb;
  v_created_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  case p_table
    when 'contacts' then
      v_root_key := 'contactDataSet';
      v_uri_slug := 'contact';
    when 'sources' then
      v_root_key := 'sourceDataSet';
      v_uri_slug := 'source';
    when 'unitgroups' then
      v_root_key := 'unitGroupDataSet';
      v_uri_slug := 'unitgroup';
    when 'flowproperties' then
      v_root_key := 'flowPropertyDataSet';
      v_uri_slug := 'flowproperty';
    when 'flows' then
      v_root_key := 'flowDataSet';
      v_uri_slug := 'productFlow';
    when 'processes' then
      v_root_key := 'processDataSet';
      v_uri_slug := 'process';
    when 'lifecyclemodels' then
      return jsonb_build_object(
        'ok', false,
        'code', 'LIFECYCLEMODEL_BUNDLE_REQUIRED',
        'status', 400,
        'message', 'Lifecycle models must use bundle create-version commands'
      );
    else
      return jsonb_build_object(
        'ok', false,
        'code', 'INVALID_DATASET_TABLE',
        'status', 400,
        'message', 'Unsupported dataset table'
      );
  end case;

  if p_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_ID_REQUIRED',
      'status', 400,
      'message', 'id is required'
    );
  end if;

  if p_json_ordered is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'JSON_ORDERED_REQUIRED',
      'status', 400,
      'message', 'jsonOrdered is required'
    );
  end if;

  if v_source_version is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_SOURCE_VERSION_REQUIRED',
      'status', 400,
      'message', 'sourceVersion is required'
    );
  end if;

  if p_table <> 'processes' and p_model_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_NOT_ALLOWED',
      'status', 400,
      'message', 'modelId is only allowed for process dataset version creation'
    );
  end if;

  perform set_config('lock_timeout', '2s', true);
  perform set_config('statement_timeout', '8s', true);

  begin
    perform pg_advisory_xact_lock(
      hashtext('cmd_dataset_create_version:' || p_table),
      hashtext(p_id::text)
    );

    execute format(
      'select exists(
         select 1
           from public.%I d
          where d.id = $1
            and d.version = $2
            and (
              d.state_code >= 100
              or d.user_id = $3
              or exists (
                select 1
                  from public.roles r
                 where r.team_id = d.team_id
                   and r.user_id = $3
                   and r.role::text = any(array[''admin'', ''member'', ''owner''])
              )
            )
       )',
      p_table
    )
      into v_source_exists
      using p_id, v_source_version, v_actor;

    if not v_source_exists then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_SOURCE_NOT_FOUND',
        'status', 404,
        'message', 'Source dataset version not found'
      );
    end if;

    execute format(
      'select version::text
         from public.%I
        where id = $1
          and version::text ~ ''^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$''
        order by split_part(version::text, ''.'', 1)::integer desc,
                 split_part(version::text, ''.'', 2)::integer desc,
                 split_part(version::text, ''.'', 3)::integer desc
        limit 1',
      p_table
    )
      into v_highest_version
      using p_id;

    if v_highest_version is null then
      v_parts := array[0, 0, -1];
    else
      v_parts := array[
        split_part(v_highest_version, '.', 1)::integer,
        split_part(v_highest_version, '.', 2)::integer,
        split_part(v_highest_version, '.', 3)::integer
      ];
    end if;

    v_parts[3] := v_parts[3] + 1;

    if v_parts[3] > 999 then
      v_parts[3] := 0;
      v_parts[2] := v_parts[2] + 1;
    end if;

    if v_parts[2] > 99 then
      v_parts[2] := 0;
      v_parts[1] := v_parts[1] + 1;
    end if;

    v_next_version := lpad(v_parts[1]::text, 2, '0')
      || '.'
      || lpad(v_parts[2]::text, 2, '0')
      || '.'
      || lpad(v_parts[3]::text, 3, '0');
    v_next_uri := 'https://lcdn.tiangong.earth/datasetdetail/'
      || v_uri_slug
      || '.xhtml?uuid='
      || p_id::text
      || '&version='
      || v_next_version;

    v_payload := p_json_ordered;
    v_dataset := coalesce(v_payload->v_root_key, '{}'::jsonb);
    v_admin := coalesce(v_dataset->'administrativeInformation', '{}'::jsonb);
    v_pub := coalesce(v_admin->'publicationAndOwnership', '{}'::jsonb);
    v_pub := jsonb_set(v_pub, '{common:dataSetVersion}', to_jsonb(v_next_version), true);
    v_pub := jsonb_set(v_pub, '{common:permanentDataSetURI}', to_jsonb(v_next_uri), true);
    v_admin := jsonb_set(v_admin, '{publicationAndOwnership}', v_pub, true);
    v_dataset := jsonb_set(v_dataset, '{administrativeInformation}', v_admin, true);
    v_payload := jsonb_set(v_payload, array[v_root_key], v_dataset, true);

    if p_table = 'processes' then
      execute format(
        'insert into public.%I as t (id, json_ordered, model_id, rule_verification)
         values ($1, $2::json, $3, $4)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', t.model_id,
           ''rule_verification'', t.rule_verification,
           ''json_ordered'', t.json_ordered::jsonb
         )',
        p_table
      )
        into v_created_row
        using p_id, v_payload, p_model_id, p_rule_verification;
    else
      execute format(
        'insert into public.%I as t (id, json_ordered, rule_verification)
         values ($1, $2::json, $3)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', null,
           ''rule_verification'', t.rule_verification,
           ''json_ordered'', t.json_ordered::jsonb
         )',
        p_table
      )
        into v_created_row
        using p_id, v_payload, p_rule_verification;
    end if;
  exception
    when lock_not_available then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_VERSION_LOCK_TIMEOUT',
        'status', 503,
        'message', 'Dataset version creation is temporarily blocked by concurrent database work'
      );
    when query_canceled then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_VERSION_TIMEOUT',
        'status', 503,
        'message', 'Dataset version creation exceeded the database timeout'
      );
    when unique_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23505',
        'status', 409,
        'message', 'Dataset with the same id and version already exists'
      );
    when not_null_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23502',
        'status', 400,
        'message', 'Dataset version creation requires a valid id, version, and jsonOrdered payload'
      );
    when check_violation then
      return jsonb_build_object(
        'ok', false,
        'code', sqlstate,
        'status', 400,
        'message', sqlerrm
      );
  end;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_create_version',
    v_actor,
    p_table,
    p_id,
    nullif(v_created_row->>'version', ''),
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_created_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_create_version(p_table text, p_id uuid, p_source_version text, p_json_ordered jsonb, p_model_id uuid, p_rule_verification boolean, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_delete(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_delete(p_table text, p_id uuid, p_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_deleted_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table = 'lifecyclemodels' then
    return jsonb_build_object(
      'ok', false,
      'code', 'LIFECYCLEMODEL_BUNDLE_REQUIRED',
      'status', 400,
      'message', 'Lifecycle models must use bundle create and delete commands'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can delete this dataset'
    );
  end if;

  if v_state_code <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_DELETE_REQUIRES_DRAFT',
      'status', 403,
      'message', 'Only draft datasets can be deleted',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  execute format(
    'delete from public.%I as t
      where t.id = $1
        and t.version = $2
      returning to_jsonb(t)',
    p_table
  )
    into v_deleted_row
    using p_id, p_version;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_delete',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_deleted_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_delete(p_table text, p_id uuid, p_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_derivative_rebuild_plan_guarded(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_command constant text := 'cmd_dataset_derivative_rebuild_plan_guarded';
  v_schema_version constant text := 'dataset-derivative-rebuild-plan.v1';
  v_plan_sha256 text;
  v_operation_id text;
  v_action jsonb;
  v_action_id text;
  v_target_id uuid;
  v_target_version text;
  v_expected_snapshot_sha256 text;
  v_reason_code text;
  v_plan_request_sha256 text;
  v_action_request_sha256 text;
  v_existing util.dataset_derivative_rebuild_requests%rowtype;
  v_active_request_id uuid;
  v_process public.processes%rowtype;
  v_snapshot jsonb;
  v_quarantine jsonb;
  v_request_id uuid := pg_catalog.gen_random_uuid();
  v_action_audit_id bigint;
  v_summary_audit_id bigint;
  v_now timestamp with time zone := pg_catalog.clock_timestamp();
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_plan is not null and pg_column_size(p_plan) > 65536 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_REQUEST_TOO_LARGE',
      'status', 413,
      'message', 'Derivative rebuild plan exceeds 64 KiB'
    );
  end if;

  if jsonb_typeof(p_plan) is distinct from 'object'
    or not (p_plan ?& array[
      'schema_version',
      'plan_sha256',
      'operation_id',
      'target_visibility',
      'actions'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_plan) as plan_key(key)
      where plan_key.key <> all (array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'target_visibility',
        'actions'
      ])
    )
    or p_plan->>'schema_version' is distinct from v_schema_version
    or jsonb_typeof(p_plan->'plan_sha256') is distinct from 'string'
    or (p_plan->>'plan_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_plan->'operation_id') is distinct from 'string'
    or nullif(btrim(p_plan->>'operation_id'), '') is null
    or octet_length(p_plan->>'operation_id') > 512
    or p_plan->>'target_visibility' is distinct from 'owner_draft'
    or jsonb_typeof(p_plan->'actions') is distinct from 'array'
    or jsonb_array_length(p_plan->'actions') <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_INVALID_REQUEST',
      'status', 400,
      'message', 'Plan must match dataset-derivative-rebuild-plan.v1 exactly'
    );
  end if;

  v_plan_sha256 := p_plan->>'plan_sha256';
  v_operation_id := btrim(p_plan->>'operation_id');
  v_action := p_plan->'actions'->0;

  if jsonb_typeof(v_action) is distinct from 'object'
    or not (v_action ?& array[
      'action_id',
      'action',
      'table',
      'id',
      'version',
      'expected_state_code',
      'expected_snapshot_sha256',
      'components',
      'reason_code'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_action) as action_key(key)
      where action_key.key <> all (array[
        'action_id',
        'action',
        'table',
        'id',
        'version',
        'expected_state_code',
        'expected_snapshot_sha256',
        'components',
        'reason_code'
      ])
    )
    or jsonb_typeof(v_action->'action_id') is distinct from 'string'
    or nullif(btrim(v_action->>'action_id'), '') is null
    or octet_length(v_action->>'action_id') > 512
    or v_action->>'action' is distinct from 'rebuild_derivatives'
    or v_action->>'table' is distinct from 'processes'
    or jsonb_typeof(v_action->'id') is distinct from 'string'
    or (v_action->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(v_action->'version') is distinct from 'string'
    or (v_action->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or jsonb_typeof(v_action->'expected_state_code') is distinct from 'number'
    or v_action->>'expected_state_code' <> '0'
    or jsonb_typeof(v_action->'expected_snapshot_sha256') is distinct from 'string'
    or (v_action->>'expected_snapshot_sha256') !~ '^[a-f0-9]{64}$'
    or v_action->'components'
      is distinct from '["extracted_md", "embedding_ft"]'::jsonb
    or jsonb_typeof(v_action->'reason_code') is distinct from 'string'
    or nullif(btrim(v_action->>'reason_code'), '') is null
    or octet_length(v_action->>'reason_code') > 512 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_INVALID_ACTION',
      'status', 400,
      'message', 'Exactly one owner-draft process rebuild action is required'
    );
  end if;

  v_action_id := btrim(v_action->>'action_id');
  v_target_id := (v_action->>'id')::uuid;
  v_target_version := btrim(v_action->>'version');
  v_expected_snapshot_sha256 := v_action->>'expected_snapshot_sha256';
  v_reason_code := btrim(v_action->>'reason_code');
  v_plan_request_sha256 := util.dataset_derivative_rebuild_sha256(p_plan::text);
  v_action_request_sha256 := util.dataset_derivative_rebuild_sha256(v_action::text);

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor::text || ':' || v_plan_request_sha256,
      0
    )
  );

  select request.*
  into v_existing
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = v_actor
    and request.plan_request_sha256 = v_plan_request_sha256;

  if v_existing.id is not null then
    if v_existing.plan_sha256 is distinct from v_plan_sha256
      or v_existing.operation_id is distinct from v_operation_id
      or v_existing.action_id is distinct from v_action_id
      or v_existing.target_id is distinct from v_target_id
      or v_existing.target_version is distinct from v_target_version
      or v_existing.expected_snapshot_sha256
        is distinct from v_expected_snapshot_sha256
      or v_existing.action_request_sha256
        is distinct from v_action_request_sha256 then
      return jsonb_build_object(
        'ok', false,
        'code', 'DERIVATIVE_PLAN_REPLAY_CONFLICT',
        'status', 409,
        'message', 'Existing admission does not match the exact plan'
      );
    end if;

    return jsonb_build_object(
      'ok', true,
      'command', v_command,
      'schema_version', v_schema_version,
      'plan_sha256', v_existing.plan_sha256,
      'operation_id', v_existing.operation_id,
      'target_visibility', v_existing.target_visibility,
      'plan_request_sha256', v_existing.plan_request_sha256,
      'action_count', 1,
      'accepted_count', 1,
      'summary_audit_id', v_existing.summary_audit_id::text,
      'request_id', v_existing.id::text,
      'status', 'queued',
      'action_request_sha256', v_existing.action_request_sha256,
      'database_audit_id', v_existing.action_audit_id::text,
      'idempotent_replay', true
    );
  end if;

  -- SHARE ROW EXCLUSIVE serializes statement snapshots around fence creation.
  -- A process writer either finishes before this frozen snapshot or begins
  -- after the nonterminal request/fence is committed and visible.
  lock table public.processes in share row exclusive mode;

  select process.*
  into v_process
  from public.processes as process
  where process.id = v_target_id
    and btrim(process.version::text) = v_target_version
    and process.user_id = v_actor
    and process.state_code = 0
  for update;

  if v_process.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_SCOPE_MISMATCH',
      'status', 409,
      'message', 'Action does not identify an exact current-owner draft process'
    );
  end if;

  begin
    v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
  exception
    when others then
      return jsonb_build_object(
        'ok', false,
        'code', 'DERIVATIVE_PLAN_PRIMARY_NOT_READY',
        'status', 409,
        'message', 'Owner-draft process primary snapshot is incomplete'
      );
  end;

  if v_snapshot->>'json_sha256'
      is distinct from v_snapshot->>'json_ordered_sha256'
    or v_snapshot->>'snapshot_sha256'
      is distinct from v_expected_snapshot_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_SNAPSHOT_DRIFT',
      'status', 409,
      'message', 'Action snapshot changed before admission'
    );
  end if;

  select request.id
  into v_active_request_id
  from util.dataset_derivative_rebuild_requests as request
  where request.target_table = 'processes'
    and request.target_id = v_target_id
    and request.target_version = v_target_version
    and request.status not in ('completed', 'stale', 'failed')
  limit 1;

  if v_active_request_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_TARGET_BUSY',
      'status', 409,
      'message', 'Another derivative rebuild already fences this process'
    );
  end if;

  v_quarantine := util.quarantine_dataset_derivative_rebuild_target(
    v_target_id,
    v_target_version
  );

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  ) values (
    v_command,
    v_actor,
    'processes',
    v_target_id,
    v_target_version,
    jsonb_build_object(
      'record_type', 'action',
      'schema_version', v_schema_version,
      'request_id', v_request_id,
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id,
      'action_id', v_action_id,
      'target_visibility', 'owner_draft',
      'expected_snapshot_sha256', v_expected_snapshot_sha256,
      'plan_request_sha256', v_plan_request_sha256,
      'action_request_sha256', v_action_request_sha256,
      'reason_code', v_reason_code,
      'components', jsonb_build_array('extracted_md', 'embedding_ft'),
      'hash_algorithm', 'postgres-jsonb-text-sha256'
    )
  )
  returning id into v_action_audit_id;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  ) values (
    v_command,
    v_actor,
    null,
    null,
    null,
    jsonb_build_object(
      'record_type', 'plan_summary',
      'schema_version', v_schema_version,
      'request_id', v_request_id,
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id,
      'target_visibility', 'owner_draft',
      'plan_request_sha256', v_plan_request_sha256,
      'action_request_sha256', v_action_request_sha256,
      'action_count', 1,
      'accepted_count', 1,
      'action_audit_id', v_action_audit_id::text,
      'hash_algorithm', 'postgres-jsonb-text-sha256'
    )
  )
  returning id into v_summary_audit_id;

  insert into util.dataset_derivative_rebuild_requests (
    id,
    actor_user_id,
    plan_sha256,
    operation_id,
    action_id,
    target_id,
    target_version,
    expected_snapshot_sha256,
    expected_modified_at,
    expected_json_sha256,
    expected_json_ordered_sha256,
    before_extracted_md_sha256,
    before_embedding_ft_sha256,
    before_embedding_ft_at,
    plan_request_sha256,
    action_request_sha256,
    reason_code,
    status,
    phase,
    admitted_at,
    drain_not_before,
    action_audit_id,
    summary_audit_id,
    quarantined_http_requests,
    quarantined_embedding_jobs,
    quarantined_pending_jobs
  ) values (
    v_request_id,
    v_actor,
    v_plan_sha256,
    v_operation_id,
    v_action_id,
    v_target_id,
    v_target_version,
    v_expected_snapshot_sha256,
    (v_snapshot->>'modified_at')::timestamp with time zone,
    v_snapshot->>'json_sha256',
    v_snapshot->>'json_ordered_sha256',
    v_snapshot->>'extracted_md_sha256',
    v_snapshot->>'embedding_ft_sha256',
    (v_snapshot->>'embedding_ft_at')::timestamp with time zone,
    v_plan_request_sha256,
    v_action_request_sha256,
    v_reason_code,
    'queued',
    'admitted',
    v_now,
    v_now + interval '420 seconds',
    v_action_audit_id,
    v_summary_audit_id,
    coalesce((v_quarantine->>'http_requests')::integer, 0),
    coalesce((v_quarantine->>'embedding_jobs')::integer, 0),
    coalesce((v_quarantine->>'pending_jobs')::integer, 0)
  );

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'schema_version', v_schema_version,
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'target_visibility', 'owner_draft',
    'plan_request_sha256', v_plan_request_sha256,
    'action_count', 1,
    'accepted_count', 1,
    'summary_audit_id', v_summary_audit_id::text,
    'request_id', v_request_id::text,
    'status', 'queued',
    'action_request_sha256', v_action_request_sha256,
    'database_audit_id', v_action_audit_id::text,
    'idempotent_replay', false
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_LOCK_BUSY',
      'status', 409,
      'message', 'Process write fence could not be acquired'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_CONCURRENT_CONFLICT',
      'status', 409,
      'message', 'A concurrent admission won the exact plan or target'
    );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb) IS 'Exactly-once admission for one immutable current-owner state_code=0 process derivative rebuild. It creates the audit/fence atomically, quarantines visible old work, and returns queued admission only; completion is asynchronous.';


--
-- Name: cmd_dataset_derivative_rebuild_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_derivative_rebuild_read(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request util.dataset_derivative_rebuild_requests%rowtype;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_REQUEST_INVALID',
      'status', 400,
      'message', 'request id is required'
    );
  end if;

  select request.*
  into v_request
  from util.dataset_derivative_rebuild_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  if v_request.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_REQUEST_NOT_AVAILABLE',
      'status', 404,
      'message', 'Derivative rebuild request is not available'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_derivative_rebuild_read',
    'schema_version', 'dataset-derivative-rebuild-status.v1',
    'request_id', v_request.id::text,
    'plan_sha256', v_request.plan_sha256,
    'operation_id', v_request.operation_id,
    'action_id', v_request.action_id,
    'table', v_request.target_table,
    'id', v_request.target_id::text,
    'version', v_request.target_version,
    'status', v_request.status,
    'phase', v_request.phase,
    'fence_active',
      v_request.status not in ('completed', 'stale', 'failed'),
    'plan_request_sha256', v_request.plan_request_sha256,
    'action_request_sha256', v_request.action_request_sha256,
    'database_audit_id', v_request.action_audit_id::text,
    'summary_audit_id', v_request.summary_audit_id::text,
    'completed_snapshot_sha256', v_request.completed_snapshot_sha256,
    'completed_at', v_request.completed_at,
    'terminal_at', v_request.terminal_at,
    'drained_at', v_request.drained_at,
    'error', v_request.last_error,
    'expected', jsonb_build_object(
      'snapshot_sha256', v_request.expected_snapshot_sha256,
      'modified_at', v_request.expected_modified_at,
      'json_sha256', v_request.expected_json_sha256,
      'json_ordered_sha256', v_request.expected_json_ordered_sha256,
      'before_extracted_md_sha256',
        v_request.before_extracted_md_sha256,
      'before_embedding_ft_sha256',
        v_request.before_embedding_ft_sha256,
      'before_embedding_ft_at', v_request.before_embedding_ft_at
    ),
    'quarantine', jsonb_build_object(
      'drain_not_before', v_request.drain_not_before,
      'failure_release_not_before',
        v_request.failure_release_not_before,
      'http_requests', v_request.quarantined_http_requests,
      'embedding_jobs', v_request.quarantined_embedding_jobs,
      'pending_jobs', v_request.quarantined_pending_jobs
    ),
    'markdown', jsonb_build_object(
      'request_id', case
        when v_request.markdown_request_id is null then null
        else v_request.markdown_request_id::text
      end,
      'dispatched_at', v_request.markdown_dispatched_at,
      'response_status', v_request.markdown_response_status,
      'response_received_at', v_request.markdown_response_received_at,
      'proposal_id', case
        when v_request.markdown_proposal_id is null then null
        else v_request.markdown_proposal_id::text
      end,
      'accepted_sha256', v_request.accepted_extracted_md_sha256
    ),
    'embedding', jsonb_build_object(
      'pending_job_id', case
        when v_request.embedding_pending_job_id is null then null
        else v_request.embedding_pending_job_id::text
      end,
      'queue_msg_id', case
        when v_request.embedding_queue_msg_id is null then null
        else v_request.embedding_queue_msg_id::text
      end,
      'queued_at', v_request.embedding_queued_at,
      'proposal_id', case
        when v_request.embedding_proposal_id is null then null
        else v_request.embedding_proposal_id::text
      end
    )
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_derivative_rebuild_read(p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_derivative_rebuild_read(p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_derivative_rebuild_read(p_request_id uuid) IS 'Owner-only, mutation-free readback for one durable derivative rebuild request. Pending drain/fence state is explicit and cannot be presented as completion.';


--
-- Name: cmd_dataset_derivative_rebuild_snapshot(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_flow public.flows%rowtype;
  v_process public.processes%rowtype;
  v_snapshot jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table is null
    or p_table not in ('flows', 'processes')
    or p_id is null
    or p_version is null
    or btrim(p_version) !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_INVALID_REQUEST',
      'status', 400,
      'message', 'A flows or processes id and canonical version are required'
    );
  end if;

  if p_table = 'flows' then
    select flow.*
    into v_flow
    from public.flows as flow
    where flow.id = p_id
      and btrim(flow.version::text) = btrim(p_version)
      and flow.user_id = v_actor
      and flow.state_code = 0;
    if v_flow.id is not null then
      begin
        v_snapshot := util.dataset_derivative_rebuild_snapshot(v_flow);
      exception
        when others then
          v_snapshot := null;
      end;
    end if;
  else
    select process.*
    into v_process
    from public.processes as process
    where process.id = p_id
      and btrim(process.version::text) = btrim(p_version)
      and process.user_id = v_actor
      and process.state_code = 0;
    if v_process.id is not null then
      begin
        v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
      exception
        when others then
          v_snapshot := null;
      end;
    end if;
  end if;

  if (p_table = 'flows' and v_flow.id is null)
    or (p_table = 'processes' and v_process.id is null) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_NOT_AVAILABLE',
      'status', 404,
      'message', 'Owner-draft dataset snapshot is not available'
    );
  end if;

  if v_snapshot is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_NOT_READY',
      'status', 409,
      'message', 'Owner-draft dataset primary snapshot is incomplete'
    );
  end if;

  if v_snapshot->>'json_sha256'
    is distinct from v_snapshot->>'json_ordered_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_PRIMARY_MISMATCH',
      'status', 409,
      'message', 'json and json_ordered are not synchronized'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_derivative_rebuild_snapshot'
  ) || v_snapshot;
end;
$_$;


ALTER FUNCTION public.cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) IS 'Returns one current-actor state_code=0 flow or process primary/derivative fingerprint. The original one-process v1 request remains compatible.';


--
-- Name: cmd_dataset_extraction_ack(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_extraction_ack(p_msg_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted jsonb := '[]'::jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  if coalesce(array_length(p_msg_ids, 1), 0) = 0 then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object('deleted_msg_ids', v_deleted));
  end if;

  select coalesce(jsonb_agg(deleted_msg_id order by deleted_msg_id), '[]'::jsonb)
  into v_deleted
  from pgmq.delete('dataset_extraction_jobs', p_msg_ids) as deleted_msg_id;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object('deleted_msg_ids', v_deleted)
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_extraction_ack(p_msg_ids bigint[]) OWNER TO postgres;

--
-- Name: cmd_dataset_extraction_claim(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_extraction_claim(p_qty integer DEFAULT 10, p_vt_seconds integer DEFAULT 300, p_max_read_count integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qty integer;
  v_vt_seconds integer;
  v_max_read_count integer;
  v_jobs jsonb := '[]'::jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  v_qty := least(greatest(coalesce(p_qty, 10), 1), 50);
  v_vt_seconds := least(greatest(coalesce(p_vt_seconds, 300), 1), 3600);
  v_max_read_count := least(greatest(coalesce(p_max_read_count, 5), 1), 100);

  with expired_jobs as (
    select
      q.msg_id,
      q.message,
      q.read_ct
    from pgmq.q_dataset_extraction_jobs q
    where q.vt <= clock_timestamp()
      and q.read_ct >= v_max_read_count
    order by q.msg_id
    limit greatest(v_qty, 100)
  ),
  recorded_failures as (
    insert into util.dataset_extraction_job_failures (
      queue_name,
      msg_id,
      read_count,
      reason,
      message
    )
    select
      'dataset_extraction_jobs',
      e.msg_id,
      e.read_ct,
      format('read_ct reached retry cap %s', v_max_read_count),
      e.message
    from expired_jobs e
    on conflict (queue_name, msg_id) do update
    set
      read_count = excluded.read_count,
      reason = excluded.reason,
      message = excluded.message,
      created_at = now()
    returning msg_id
  )
  delete from pgmq.q_dataset_extraction_jobs q
  using recorded_failures f
  where q.msg_id = f.msg_id;

  with claimed_jobs as (
    select *
    from pgmq.read('dataset_extraction_jobs', v_vt_seconds, v_qty)
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'msg_id', msg_id,
        'read_ct', read_ct,
        'enqueued_at', enqueued_at,
        'vt', vt,
        'message', message
      )
      order by msg_id
    ),
    '[]'::jsonb
  )
  into v_jobs
  from claimed_jobs;

  return jsonb_build_object(
    'ok', true,
    'data', v_jobs
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_extraction_claim(p_qty integer, p_vt_seconds integer, p_max_read_count integer) OWNER TO postgres;

--
-- Name: cmd_dataset_extraction_record_failure(bigint, integer, text, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_extraction_record_failure(p_msg_id bigint, p_read_count integer, p_reason text, p_message jsonb, p_last_error text DEFAULT NULL::text, p_delete boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  insert into util.dataset_extraction_job_failures (
    queue_name,
    msg_id,
    read_count,
    reason,
    message,
    last_error
  )
  values (
    'dataset_extraction_jobs',
    p_msg_id,
    coalesce(p_read_count, 0),
    coalesce(nullif(p_reason, ''), 'worker failure'),
    coalesce(p_message, '{}'::jsonb),
    p_last_error
  )
  on conflict (queue_name, msg_id) do update
  set
    read_count = excluded.read_count,
    reason = excluded.reason,
    message = excluded.message,
    last_error = excluded.last_error,
    created_at = now();

  if coalesce(p_delete, true) then
    perform pgmq.delete('dataset_extraction_jobs', p_msg_id);
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION public.cmd_dataset_extraction_record_failure(p_msg_id bigint, p_read_count integer, p_reason text, p_message jsonb, p_last_error text, p_delete boolean) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_capture_attest_guarded(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_capture_attest_guarded';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_request_sha256 text;
  v_context jsonb;
  v_existing util.dataset_flow_identity_capture_receipts%rowtype;
  v_receipt_id uuid := gen_random_uuid();
  v_captured_at timestamp with time zone := clock_timestamp();
  v_expires_at timestamp with time zone;
  v_mapping_intent jsonb;
  v_mapping jsonb;
  v_mapping_body jsonb;
  v_mappings jsonb := '[]'::jsonb;
  v_mapping_index jsonb;
  v_source_guard jsonb;
  v_target_guard jsonb;
  v_source_records jsonb := '[]'::jsonb;
  v_target_records jsonb := '[]'::jsonb;
  v_source_ordinal integer := 0;
  v_partition text;
  v_protected_entry jsonb;
  v_protected jsonb;
  v_supports jsonb;
  v_process_records jsonb := '[]'::jsonb;
  v_processes jsonb := '[]'::jsonb;
  v_source_universe jsonb;
  v_source_guard_set_sha256 text;
  v_target_guard_set_sha256 text;
  v_mapping_guard_set_sha256 text;
  v_process_intent_set_sha256 text;
  v_support_set_sha256 text;
  v_protected_sha256 text;
  v_source_universe_sha256 text;
  v_mapping_set_sha256 text;
  v_process_manifest_sha256 text;
  v_receipt_proof_sha256 text;
  v_whole_scope_proof_sha256 text;
  v_rewrite_count integer;
  v_validation jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if v_request is null
    or pg_column_size(v_request) > 134217728
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'environment', 'project_ref', 'actor',
      'target_visibility', 'operation_id', 'compatibility_policy',
      'artifact_evidence', 'mappings', 'process_intents', 'protected_closure'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-capture-attest.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}'))
      is distinct from v_actor_email
    or not private.dataset_flow_identity_exact_keys(
      v_request->'artifact_evidence', array[
        'review_ledger_sha256', 'live_capture_artifact_sha256',
        'toolchain_evidence_sha256'
      ]
    )
    or exists (
      select 1 from unnest(array[
        'review_ledger_sha256', 'live_capture_artifact_sha256',
        'toolchain_evidence_sha256'
      ]) as field(name)
      where v_request->'artifact_evidence'->>field.name
        !~ '^[a-f0-9]{64}$'
    )
    or jsonb_typeof(v_request->'mappings') <> 'array'
    or jsonb_array_length(v_request->'mappings') not between 1 and 305
    or jsonb_typeof(v_request->'process_intents') <> 'array'
    or jsonb_array_length(v_request->'process_intents') not between 1 and 12000
    or not private.dataset_flow_identity_exact_keys(
      v_request->'compatibility_policy', array[
        'schema_version', 'policy_sha256', 'evidence_resolution_sha256',
        'approved_at_utc', 'approval_text_sha256'
      ]
    )
    or v_request #>> '{compatibility_policy,schema_version}'
      <> 'dataset-flow-identity-compatibility-policy.v1'
    or exists (
      select 1 from unnest(array[
        'policy_sha256', 'evidence_resolution_sha256', 'approval_text_sha256'
      ]) as field(name)
      where v_request->'compatibility_policy'->>field.name
        !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CAPTURE_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 capture request schema or safe-JSON domain mismatch'
    );
  end if;
  begin
    perform (v_request #>>
      '{compatibility_policy,approved_at_utc}')::timestamp with time zone;
  exception when others then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CAPTURE_POLICY_TIME_INVALID', 'status', 400,
      'message', 'Compatibility policy approval time is invalid'
    );
  end;
  v_context := util.dataset_alias_execution_server_context();
  if v_request->>'environment' is distinct from v_context->>'environment'
    or v_request->>'project_ref' is distinct from v_context->>'project_ref' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CAPTURE_ENVIRONMENT_MISMATCH', 'status', 409,
      'message', 'Capture does not target this database branch'
    );
  end if;
  -- Capture and every owner-row trigger share this actor fence.  No process
  -- or elementary-flow write can straddle the final receipt attestation.
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  v_request_sha256 := util.dataset_flow_identity_restricted_sha256_v2(v_request);
  select receipt.* into v_existing
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.actor_user_id = v_actor
    and receipt.request_id = (v_request->>'request_id')::uuid;
  if v_existing.id is not null then
    if v_existing.capture_request_sha256 is distinct from v_request_sha256 then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CAPTURE_REQUEST_REUSE_MISMATCH', 'status', 409,
        'message', 'Capture request ID is already bound differently'
      );
    elsif v_existing.expires_at <= clock_timestamp() then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CAPTURE_RECEIPT_EXPIRED', 'status', 409,
        'message', 'Capture receipt expired; create a fresh request ID'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', 'dataset-flow-identity-capture-attest-result.v2',
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'receipt_id', v_existing.id,
      'receipt_proof_sha256', v_existing.receipt_proof_sha256,
      'operation_id', v_existing.operation_id,
      'environment', v_existing.environment,
      'project_ref', v_existing.project_ref,
      'captured_at', v_existing.captured_at,
      'expires_at', v_existing.expires_at,
      'source_guard_set_sha256', v_existing.source_guard_set_sha256,
      'support_guard_set_sha256', v_existing.support_snapshot_set_sha256,
      'target_guard_set_sha256', v_existing.target_guard_set_sha256,
      'mapping_guard_set_sha256', v_existing.mapping_guard_set_sha256,
      'process_intent_set_sha256', v_existing.process_intent_set_sha256,
      'protected_closure_sha256', v_existing.protected_closure_sha256,
      'whole_scope_proof_sha256', v_existing.whole_scope_proof_sha256,
      'policy_sha256', v_existing.compatibility_policy->>'policy_sha256',
      'policy_approval_text_sha256',
        v_existing.policy_approval_text_sha256,
      'source_count', v_existing.source_count,
      'target_count', v_existing.target_count,
      'support_count', v_existing.support_count,
      'mapping_count', v_existing.mapping_count,
      'process_count', v_existing.process_count,
      'rewrite_count', v_existing.rewrite_count,
      'capture_request_sha256', v_existing.capture_request_sha256,
      'replay', true
    );
  end if;

  v_protected := private.dataset_flow_identity_build_protected_v2(
    v_actor, v_request->'protected_closure'
  );
  v_protected_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_protected);

  for v_mapping_intent in
    select item.value
    from jsonb_array_elements(v_request->'mappings')
      with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    if not private.dataset_flow_identity_exact_keys(v_mapping_intent, array[
        'ordinal', 'source', 'target', 'compatibility'
      ])
      or jsonb_typeof(v_mapping_intent->'ordinal') <> 'number'
      or (v_mapping_intent->>'ordinal')::integer
        <> jsonb_array_length(v_mappings) + 1
      or not private.dataset_flow_identity_exact_keys(
        v_mapping_intent->'compatibility', array[
          'policy_sha256', 'mode', 'confidence',
          'flow_property_compatible', 'unit_group_compatible',
          'direction_compatible', 'compartment_compatible',
          'conversion_factor', 'evidence_sha256', 'flow_schema',
          'process_schema_required'
        ]
      )
      or v_mapping_intent #>> '{compatibility,policy_sha256}'
        is distinct from v_request #>> '{compatibility_policy,policy_sha256}'
      or v_mapping_intent #>> '{compatibility,mode}' <> 'identity'
      or v_mapping_intent #>> '{compatibility,confidence}' <> 'approved'
      or v_mapping_intent #>> '{compatibility,conversion_factor}' <> '1'
      or v_mapping_intent #>> '{compatibility,evidence_sha256}'
        !~ '^[a-f0-9]{64}$'
      or v_mapping_intent #>> '{compatibility,process_schema_required}'
        <> 'pass'
      or not private.dataset_flow_identity_exact_keys(
        v_mapping_intent #> '{compatibility,flow_schema}',
        array['status', 'warning_set_sha256']
      )
      or v_mapping_intent #>> '{compatibility,flow_schema,status}'
        not in ('pass', 'legacy_warning')
      or v_mapping_intent #>>
        '{compatibility,flow_schema,warning_set_sha256}'
        !~ '^[a-f0-9]{64}$'
      or exists (
        select 1 from unnest(array[
          'flow_property_compatible', 'unit_group_compatible',
          'direction_compatible', 'compartment_compatible'
        ]) as field(name)
        where v_mapping_intent->'compatibility'->>field.name <> 'true'
      ) then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_MAPPING_INTENT_MISMATCH';
    end if;
    v_source_guard := private.dataset_flow_identity_build_flow_guard_v2(
      v_actor, v_mapping_intent->'source', false
    );
    v_target_guard := private.dataset_flow_identity_build_flow_guard_v2(
      v_actor, v_mapping_intent->'target', true
    );
    if v_source_guard->>'flow_property_id'
        is distinct from v_target_guard->>'flow_property_id'
      or v_source_guard->>'flow_property_version'
        is distinct from v_target_guard->>'flow_property_version'
      or v_source_guard->>'unit_group_id'
        is distinct from v_target_guard->>'unit_group_id'
      or v_source_guard->>'unit_group_version'
        is distinct from v_target_guard->>'unit_group_version' then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_MAPPING_NOT_IDENTITY_ONLY';
    end if;
    v_mapping_body := jsonb_build_object(
      'source', v_source_guard,
      'target', v_target_guard,
      'compatibility', v_mapping_intent->'compatibility'
    );
    v_mapping := jsonb_build_object(
      'ordinal', v_mapping_intent->'ordinal',
      'mapping_id',
        util.dataset_flow_identity_restricted_sha256_v2(v_mapping_body)
    ) || v_mapping_body;
    v_mappings := v_mappings || jsonb_build_array(v_mapping);
    v_source_ordinal := v_source_ordinal + 1;
    v_source_records := v_source_records || jsonb_build_array(
      jsonb_build_object(
        'ordinal', v_source_ordinal, 'disposition', 'mapped',
        'source_id', v_source_guard->>'id',
        'source_version', v_source_guard->>'version',
        'guard', v_source_guard,
        'evidence_sha256', v_source_guard->>'source_trace_sha256'
      )
    );
  end loop;

  foreach v_partition in array array['pending', 'blockers', 'orphans'] loop
    for v_protected_entry in
      select item.value
      from jsonb_array_elements(v_request->'protected_closure'->v_partition)
        with ordinality as item(value, ordinality)
      order by item.ordinality
    loop
      v_source_guard := private.dataset_flow_identity_build_flow_guard_v2(
        v_actor,
        jsonb_build_object(
          'id', v_protected_entry->>'source_id',
          'version', v_protected_entry->>'source_version',
          'source_trace_sha256', v_protected_entry->>'evidence_sha256'
        ),
        false
      );
      v_source_ordinal := v_source_ordinal + 1;
      v_source_records := v_source_records || jsonb_build_array(
        jsonb_build_object(
          'ordinal', v_source_ordinal,
          'disposition', case v_partition
            when 'blockers' then 'blocker'
            when 'orphans' then 'orphan'
            else 'pending' end,
          'source_id', v_source_guard->>'id',
          'source_version', v_source_guard->>'version',
          'guard', v_source_guard,
          'evidence_sha256', v_protected_entry->>'evidence_sha256'
        )
      );
    end loop;
  end loop;
  if jsonb_array_length(v_source_records) <> 305
    or (select count(distinct (item.value->>'source_id') || '@'
          || (item.value->>'source_version'))
        from jsonb_array_elements(v_source_records) as item(value)) <> 305 then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_SOURCE_CLOSURE_MISMATCH';
  end if;

  select coalesce(jsonb_agg(target order by target_id, target_version), '[]'::jsonb)
  into v_target_records
  from (
    select distinct on (
      item.value #>> '{target,id}', item.value #>> '{target,version}'
    )
      item.value #>> '{target,id}' as target_id,
      item.value #>> '{target,version}' as target_version,
      item.value->'target' as target
    from jsonb_array_elements(v_mappings) as item(value)
    order by item.value #>> '{target,id}', item.value #>> '{target,version}'
  ) as distinct_target;
  v_target_records := coalesce((
    select jsonb_agg(jsonb_build_object(
      'ordinal', item.ordinality,
      'target_id', item.value->>'id',
      'target_version', item.value->>'version',
      'guard', item.value
    ) order by item.ordinality)
    from jsonb_array_elements(v_target_records)
      with ordinality as item(value, ordinality)
  ), '[]'::jsonb);

  v_supports := private.dataset_flow_identity_build_support_set_v2(
    v_actor, v_mappings
  );
  for v_mapping in select item.value
    from jsonb_array_elements(v_mappings) as item(value)
  loop
    v_validation := util.dataset_flow_identity_validate_mapping(
      v_actor, v_mapping, v_request->'compatibility_policy', v_supports,
      (v_mapping->>'ordinal')::integer
    );
    if coalesce((v_validation->>'ok')::boolean, false) is false then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_MAPPING_LIVE_MISMATCH';
    end if;
  end loop;
  v_mapping_index :=
    private.dataset_flow_identity_mapping_index_v2(v_mappings);

  if exists (
    select 1
    from jsonb_array_elements(v_request->'process_intents')
      with ordinality as item(value, ordinality)
    where case when jsonb_typeof(item.value->'ordinal') = 'number'
      then (item.value->>'ordinal')::numeric = item.ordinality::numeric
      else false end is not true
  ) then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_ORDINAL_MISMATCH';
  end if;
  with built as materialized (
    select item.ordinality::integer as ordinal,
      private.dataset_flow_identity_build_process_v2(
        v_actor, item.value, v_mapping_index,
        v_request->'compatibility_policy', v_supports, v_protected_sha256
      ) as manifest
    from jsonb_array_elements(v_request->'process_intents')
      with ordinality as item(value, ordinality)
  )
  select
    coalesce(jsonb_agg(built.manifest order by built.ordinal), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', built.manifest->'ordinal',
      'process_id', built.manifest->>'id',
      'process_version', built.manifest->>'version',
      'intent_proof_sha256',
        util.dataset_flow_identity_restricted_sha256_v2(built.manifest),
      'manifest', built.manifest
    ) order by built.ordinal), '[]'::jsonb),
    coalesce(sum((built.manifest->>'rewrite_count')::integer), 0)::integer
  into v_processes, v_process_records, v_rewrite_count
  from built;
  if v_rewrite_count <= 0 then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_CLOSURE_EMPTY';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id', (item.value->>'source_id')::uuid,
    'version', item.value->>'source_version',
    'user_id', v_actor,
    'state_code', 0,
    'flow_type', 'Elementary flow'
  ) order by item.value->>'source_id', item.value->>'source_version')
  into v_source_universe
  from jsonb_array_elements(v_source_records) as item(value);
  v_source_universe_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_source_universe);
  v_validation := util.dataset_flow_identity_source_universe(
    v_actor, v_source_universe, v_source_universe_sha256
  );
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_SOURCE_UNIVERSE_LIVE_MISMATCH';
  end if;

  v_source_guard_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_source_records);
  v_target_guard_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_target_records);
  v_mapping_guard_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_mappings);
  v_process_intent_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_process_records);
  v_support_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_supports);
  v_mapping_set_sha256 := v_mapping_guard_set_sha256;
  v_process_manifest_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_processes);
  v_expires_at := v_captured_at + interval '7 days';
  v_whole_scope_proof_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
      'schema_version', 'dataset-flow-identity-capture-whole-scope.v2',
      'receipt_id', v_receipt_id,
      'actor_user_id', v_actor,
      'environment', v_request->>'environment',
      'project_ref', v_request->>'project_ref',
      'operation_id', v_request->>'operation_id',
      'capture_request_sha256', v_request_sha256,
      'source_guard_set_sha256', v_source_guard_set_sha256,
      'support_guard_set_sha256', v_support_set_sha256,
      'target_guard_set_sha256', v_target_guard_set_sha256,
      'mapping_guard_set_sha256', v_mapping_guard_set_sha256,
      'process_intent_set_sha256', v_process_intent_set_sha256,
      'protected_closure_sha256', v_protected_sha256,
      'captured_at', v_captured_at,
      'expires_at', v_expires_at
    ));
  v_receipt_proof_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'receipt_id', v_receipt_id,
      'whole_scope_proof_sha256', v_whole_scope_proof_sha256,
      'policy_sha256',
        v_request #>> '{compatibility_policy,policy_sha256}',
      'policy_approval_text_sha256',
        v_request #>> '{compatibility_policy,approval_text_sha256}'
    ));

  insert into util.dataset_flow_identity_capture_receipts (
    id, actor_user_id, actor_email, request_id, environment, project_ref,
    target_visibility, operation_id, compatibility_policy,
    policy_approval_text_sha256, artifact_evidence, protected_closure,
    protected_closure_sha256, source_universe, source_universe_sha256,
    support_snapshot_set_sha256, source_guard_set_sha256,
    target_guard_set_sha256, mapping_guard_set_sha256,
    process_intent_set_sha256, mapping_set_sha256,
    process_manifest_sha256, capture_request_sha256, receipt_proof_sha256,
    whole_scope_proof_sha256, source_count, target_count, support_count,
    mapping_count, process_count, rewrite_count, captured_at, expires_at
  ) values (
    v_receipt_id, v_actor, v_actor_email, (v_request->>'request_id')::uuid,
    v_request->>'environment', v_request->>'project_ref',
    'owner_draft', v_request->>'operation_id',
    v_request->'compatibility_policy',
    v_request #>> '{compatibility_policy,approval_text_sha256}',
    v_request->'artifact_evidence', v_protected, v_protected_sha256,
    v_source_universe, v_source_universe_sha256, v_support_set_sha256,
    v_source_guard_set_sha256, v_target_guard_set_sha256,
    v_mapping_guard_set_sha256, v_process_intent_set_sha256,
    v_mapping_set_sha256, v_process_manifest_sha256, v_request_sha256,
    v_receipt_proof_sha256, v_whole_scope_proof_sha256, 305,
    jsonb_array_length(v_target_records), jsonb_array_length(v_supports),
    jsonb_array_length(v_mappings), jsonb_array_length(v_processes),
    v_rewrite_count, v_captured_at, v_expires_at
  );
  insert into util.dataset_flow_identity_capture_source_guards (
    receipt_id, ordinal, disposition, source_id, source_version,
    guard, evidence_sha256
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      item.value->>'disposition', (item.value->>'source_id')::uuid,
      item.value->>'source_version', item.value->'guard',
      item.value->>'evidence_sha256'
    from jsonb_array_elements(v_source_records) as item(value);
  insert into util.dataset_flow_identity_capture_target_guards (
    receipt_id, ordinal, target_id, target_version, guard
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      (item.value->>'target_id')::uuid, item.value->>'target_version',
      item.value->'guard'
    from jsonb_array_elements(v_target_records) as item(value);
  insert into util.dataset_flow_identity_capture_support_guards (
    receipt_id, ordinal, support_table, support_id, support_version, guard
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      item.value->>'table', (item.value->>'id')::uuid,
      item.value->>'version', item.value
    from jsonb_array_elements(v_supports) as item(value);
  insert into util.dataset_flow_identity_capture_mapping_guards (
    receipt_id, ordinal, mapping_id, source_id, source_version,
    target_id, target_version, mapping
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      item.value->>'mapping_id', (item.value #>> '{source,id}')::uuid,
      item.value #>> '{source,version}',
      (item.value #>> '{target,id}')::uuid,
      item.value #>> '{target,version}', item.value
    from jsonb_array_elements(v_mappings) as item(value);
  insert into util.dataset_flow_identity_capture_process_intents (
    receipt_id, ordinal, process_id, process_version,
    intent_proof_sha256, manifest
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      (item.value->>'process_id')::uuid, item.value->>'process_version',
      item.value->>'intent_proof_sha256', item.value->'manifest'
    from jsonb_array_elements(v_process_records) as item(value);

  -- The helper is declared later in this migration, so use runtime resolution
  -- here.  It locks and revalidates all 305 sources, every support/target,
  -- every protected occurrence, and every intended process after the receipt
  -- relation has been fully inserted but before this transaction can return.
  execute
    'select private.dataset_flow_identity_whole_scope_proof_v2($1,$2,null,true)'
    into v_validation using v_actor, v_receipt_id;
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '40001',
      message = 'FLOW_IDENTITY_CAPTURE_FINAL_WHOLE_SCOPE_DRIFT';
  end if;

  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-capture-attest-result.v2',
    'proof_domain', 'dataset-flow-identity-db-proof.v2',
    'receipt_id', v_receipt_id,
    'receipt_proof_sha256', v_receipt_proof_sha256,
    'operation_id', v_request->>'operation_id',
    'environment', v_request->>'environment',
    'project_ref', v_request->>'project_ref',
    'captured_at', v_captured_at, 'expires_at', v_expires_at,
    'source_guard_set_sha256', v_source_guard_set_sha256,
    'support_guard_set_sha256', v_support_set_sha256,
    'target_guard_set_sha256', v_target_guard_set_sha256,
    'mapping_guard_set_sha256', v_mapping_guard_set_sha256,
    'process_intent_set_sha256', v_process_intent_set_sha256,
    'protected_closure_sha256', v_protected_sha256,
    'whole_scope_proof_sha256', v_whole_scope_proof_sha256,
    'policy_sha256',
      v_request #>> '{compatibility_policy,policy_sha256}',
    'policy_approval_text_sha256',
      v_request #>> '{compatibility_policy,approval_text_sha256}',
    'source_count', 305,
    'target_count', jsonb_array_length(v_target_records),
    'support_count', jsonb_array_length(v_supports),
    'mapping_count', jsonb_array_length(v_mappings),
    'process_count', jsonb_array_length(v_processes),
    'rewrite_count', v_rewrite_count,
    'capture_request_sha256', v_request_sha256,
    'replay', false
  );
exception when others then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', case when sqlstate = '55P03'
      then 'FLOW_IDENTITY_CAPTURE_LOCK_BUSY'
      else 'FLOW_IDENTITY_CAPTURE_FAILED' end,
    'status', case when sqlstate = '55P03' then 409 else 400 end,
    'message', sqlerrm, 'sqlstate', sqlstate
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb) IS 'Authenticated Step 3 v2 read-only capture attestation. It accepts typed semantic intent plus opaque artifact evidence, computes every live/before/desired/category/row hash in PostgreSQL, and persists an immutable relation-shaped receipt without mutating LCA datasets.';


--
-- Name: cmd_dataset_flow_identity_process_rewrite_guarded(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_process_rewrite_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '90s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_process_rewrite_guarded';
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_request_sha256 text;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_ledger util.dataset_flow_identity_process_ledger%rowtype;
  v_internal jsonb;
  v_internal_sha256 text;
  v_core_result jsonb;
  v_live jsonb;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
  v_completed_process_count integer;
  v_next_ordinal integer;
  v_primary_complete boolean;
  v_invocation_id uuid;
  v_invocation util.dataset_flow_identity_wrapper_invocations%rowtype;
  v_execution_permit jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'scope_proof_sha256', 'ordinal',
      'process_intent_proof_sha256', 'process_request_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-process-rewrite.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'scope_proof_sha256' !~ '^[a-f0-9]{64}$'
    or v_request->>'process_intent_proof_sha256' !~ '^[a-f0-9]{64}$'
    or v_request->>'process_request_sha256' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(v_request->'ordinal') <> 'number'
    or (v_request->>'ordinal')::numeric <= 0
    or (v_request->>'ordinal')::numeric > 2147483647 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 thin process request schema mismatch'
    );
  end if;
  v_request_sha256 := util.dataset_flow_identity_restricted_sha256_v2(
    v_request - 'process_request_sha256'
  );
  if v_request_sha256 is distinct from
    v_request->>'process_request_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_REQUEST_HASH_MISMATCH',
      'status', 409, 'message', 'Thin process request hash mismatch'
    );
  end if;

  -- Active execution is O(1): the owner fence precedes the scope fence.
  -- The full public target/support activation set is acquired only once by
  -- fresh preflight; repeating it for every ordinal would be O(P^2).
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_SCOPE_BUSY', 'status', 409,
      'message', 'Another process transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null
    or v_scope.scope_proof_sha256
      is distinct from v_request->>'scope_proof_sha256'
    or v_scope.status in ('failed', 'cancelled') then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Scope proof is invalid or scope is not executable'
    );
  end if;
  v_invocation_id := private.dataset_flow_identity_validate_wrapper_permit_v1(
    v_actor, p_scope_id, p_authorization, 'process'
  );
  if v_invocation_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_WRAPPER_PERMIT_REQUIRED', 'status', 409,
      'message', 'A fresh one-wrapper execution permit is required'
    );
  end if;
  select invocation.* into strict v_invocation
  from util.dataset_flow_identity_wrapper_invocations as invocation
  where invocation.id = v_invocation_id
    and invocation.scope_id = v_scope.id
    and invocation.actor_user_id = v_actor
  for update;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_scope.receipt_proof_sha256 then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  select ledger.* into v_ledger
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id
    and ledger.ordinal = (v_request->>'ordinal')::integer
  for update;
  if v_ledger.scope_id is null
    or v_ledger.process_intent_proof_sha256
      is distinct from v_request->>'process_intent_proof_sha256' then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_INTENT_PROOF_MISMATCH', 'status', 409,
      'message', 'Thin request does not bind the receipt process intent'
    );
  end if;
  if v_ledger.status = 'completed' then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_ALREADY_COMPLETED_READ_SCOPE',
      'status', 409,
      'message', 'Completed process proof is available only through scope read'
    );
  end if;
  -- Full-scope reproof is reserved for ambiguous replay/recovery.  A normal
  -- pending ordinal is protected by the active row fences and is revalidated
  -- against its exact process/mapping/support guards inside the private core.
  if v_ledger.status = 'completed' then
    v_live := private.dataset_flow_identity_whole_scope_proof_v2(
      v_actor, v_scope.receipt_id, v_scope.id, true
    );
    if coalesce((v_live->>'ok')::boolean, false) is false then
      perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
        v_invocation_id
      );
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
        'message', 'Whole-scope replay proof drifted'
      );
    end if;
  end if;

  v_internal := jsonb_build_object(
    'schema_version', 'dataset-flow-identity-process-rewrite.v1',
    'request_id', v_request->>'request_id',
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'ordinal', v_ledger.ordinal,
    'process', v_ledger.manifest,
    'rewrites', v_ledger.manifest->'rewrites',
    'collision_ledger', v_ledger.manifest->'collision_ledger',
    'collision_ledger_sha256',
      v_ledger.manifest->>'collision_ledger_sha256',
    'process_request_sha256', ''
  );
  v_internal_sha256 := util.dataset_flow_identity_restricted_sha256_v2(
    v_internal - 'process_request_sha256'
  );
  v_internal := jsonb_set(
    v_internal, '{process_request_sha256}', to_jsonb(v_internal_sha256), false
  );
  perform set_config(
    'app.dataset_flow_identity_v2_process_request_sha256',
    v_request_sha256, true
  );
  v_core_result := private.dataset_flow_identity_process_rewrite_core_v1(
    p_scope_id, v_internal
  );
  if coalesce((v_core_result->>'ok')::boolean, false) is false then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return v_core_result;
  end if;
  update util.dataset_flow_identity_process_ledger as ledger
  set wrapper_invocation_id = v_invocation.id,
    permit_generation_before = v_invocation.generation
  where ledger.scope_id = v_scope.id
    and ledger.ordinal = (v_request->>'ordinal')::integer
    and ledger.wrapper_invocation_id is null
    and ledger.permit_generation_before is null
  returning ledger.* into v_ledger;
  if not found then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PROCESS_INVOCATION_BINDING_FAILED';
  end if;
  if v_ledger.status <> 'completed'
    or v_ledger.process_request_sha256 is distinct from v_request_sha256
    or v_ledger.after_payload_sha256
      is distinct from v_ledger.manifest->>'desired_payload_sha256'
    or v_ledger.after_exchange_set_sha256
      is distinct from v_ledger.manifest->>'desired_exchange_set_sha256'
    or v_ledger.audit_id is null or v_ledger.derivative_batch_id is null then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PROCESS_POST_CORE_PROOF_MISMATCH';
  end if;
  select audit.payload into v_audit_payload
  from public.command_audit_log as audit
  where audit.id = v_ledger.audit_id and audit.actor_user_id = v_actor
    and audit.command = v_command and audit.target_table = 'processes'
    and audit.target_id = v_ledger.process_id
    and audit.target_version = v_ledger.process_version;
  if v_audit_payload is null then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PROCESS_V2_AUDIT_MISSING';
  end if;
  v_expected_audit_payload := jsonb_build_object(
      'record_type', 'process_rewrite',
      'schema_version', 'dataset-flow-identity-process-rewrite.v2',
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'scope_id', v_scope.id,
      'receipt_id', v_receipt.id,
      'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
      'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
      'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'wrapper_invocation_id', v_invocation.id,
      'wrapper_approval_kind', v_invocation.approval_kind,
      'wrapper_approval_identity_sha256',
        v_invocation.approval_identity_sha256,
      'wrapper_admission_request_sha256',
        v_invocation.admission_request_sha256,
      'permit_generation_before', v_invocation.generation,
      'ordinal', v_ledger.ordinal,
      'process_intent_proof_sha256',
        v_ledger.process_intent_proof_sha256,
      'process_request_sha256', v_ledger.process_request_sha256,
      'process_template_sha256', v_ledger.process_template_sha256,
      'rewrite_set_sha256', v_ledger.manifest->>'rewrite_set_sha256',
      'collision_ledger_sha256',
        v_ledger.manifest->>'collision_ledger_sha256',
      'before_payload_sha256', v_ledger.before_payload_sha256,
      'before_exchange_set_sha256',
        v_ledger.manifest->>'before_exchange_set_sha256',
      'desired_payload_sha256',
        v_ledger.manifest->>'desired_payload_sha256',
      'desired_exchange_set_sha256',
        v_ledger.manifest->>'desired_exchange_set_sha256',
      'after_payload_sha256', v_ledger.after_payload_sha256,
      'after_exchange_set_sha256', v_ledger.after_exchange_set_sha256,
      'rewrite_count', v_ledger.rewrite_count,
      'derivative_batch_id', v_ledger.derivative_batch_id,
      'derivative_reason_code', 'FLOW_IDENTITY_SCOPE:'
        || v_scope.id::text || ':' || v_ledger.ordinal::text,
      'hash_algorithm', 'restricted-safe-json-v2-sha256'
    );
  if coalesce((v_core_result->>'replay')::boolean, false) is false then
    update public.command_audit_log
    set payload = v_expected_audit_payload
    where id = v_ledger.audit_id and actor_user_id = v_actor
      and command = v_command and target_table = 'processes'
    returning payload into v_audit_payload;
    if v_audit_payload is distinct from v_expected_audit_payload then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PROCESS_V2_AUDIT_PROMOTION_FAILED';
    end if;
  elsif v_audit_payload is distinct from v_expected_audit_payload then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_V2_AUDIT_DRIFT', 'status', 409,
      'message', 'The authoritative v2 process audit drifted'
    );
  end if;
  if coalesce((v_core_result->>'replay')::boolean, false) then
    select
      count(*) filter (where ledger.status = 'completed')::integer,
      min(ledger.ordinal) filter (where ledger.status = 'pending')::integer
    into v_completed_process_count, v_next_ordinal
    from util.dataset_flow_identity_process_ledger as ledger
    where ledger.scope_id = v_scope.id;
  else
    v_completed_process_count := v_ledger.ordinal;
    v_next_ordinal := case when v_ledger.ordinal < v_scope.process_count
      then v_ledger.ordinal + 1 else null end;
  end if;
  v_primary_complete := v_next_ordinal is null
    and v_completed_process_count = v_scope.process_count;
  v_execution_permit :=
    private.dataset_flow_identity_rotate_wrapper_permit_v1(
      v_invocation_id, 'process', false
    );
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-process-rewrite-result.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_scope.receipt_id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'invocation_id', v_invocation.id,
    'permit_generation_before', v_invocation.generation,
    'ordinal', v_ledger.ordinal,
    'process_id', v_ledger.process_id,
    'process_version', v_ledger.process_version,
    'process_request_sha256', v_ledger.process_request_sha256,
    'process_intent_proof_sha256',
      v_ledger.process_intent_proof_sha256,
    'before_payload_sha256', v_ledger.before_payload_sha256,
    'before_exchange_set_sha256',
      v_ledger.manifest->>'before_exchange_set_sha256',
    'desired_payload_sha256',
      v_ledger.manifest->>'desired_payload_sha256',
    'desired_exchange_set_sha256',
      v_ledger.manifest->>'desired_exchange_set_sha256',
    'after_payload_sha256', v_ledger.after_payload_sha256,
    'after_exchange_set_sha256', v_ledger.after_exchange_set_sha256,
    'rewrite_count', v_ledger.rewrite_count,
    'audit_id', v_ledger.audit_id::text,
    'derivative_batch_id', v_ledger.derivative_batch_id,
    'completed_process_count', v_completed_process_count,
    'next_ordinal', v_next_ordinal,
    'primary_complete', v_primary_complete,
    'status', v_ledger.status,
    'replay', coalesce((v_core_result->>'replay')::boolean, false),
    'execution_permit', v_execution_permit
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_PROCESS_LOCK_BUSY', 'status', 409,
    'message', 'Process transaction could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_process_rewrite_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_cancel_guarded(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '30s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_cancel_guarded';
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_request_sha256 text;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_ledger_count integer;
  v_completed_count integer;
  v_nonpending_count integer;
  v_inactive_count integer;
  v_primary_proof_count integer;
  v_process_audit_count integer;
  v_permit_count integer;
  v_audit_id bigint;
  v_audit_count integer;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'receipt_id', 'receipt_proof_sha256',
      'operation_id', 'plan_sha256', 'scope_proof_sha256', 'reason',
      'evidence_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-cancel.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'receipt_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or nullif(btrim(v_request->>'reason'), '') is null
    or octet_length(v_request->>'reason') > 512
    or exists (
      select 1 from unnest(array[
        'receipt_proof_sha256', 'plan_sha256', 'scope_proof_sha256',
        'evidence_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 cancel request schema mismatch'
    );
  end if;
  v_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);

  -- Match the v2 execution lock order.  The owner fence excludes direct
  -- owner-row writes while the scope lock excludes a concurrent ordinal.
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_SCOPE_BUSY', 'status', 409,
      'message', 'Another transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.id::text is distinct from v_request->>'receipt_id'
    or v_receipt.receipt_proof_sha256
      is distinct from v_request->>'receipt_proof_sha256'
    or v_scope.receipt_proof_sha256
      is distinct from v_request->>'receipt_proof_sha256'
    or v_scope.operation_id is distinct from v_request->>'operation_id'
    or v_scope.plan_sha256 is distinct from v_request->>'plan_sha256'
    or v_scope.scope_proof_sha256
      is distinct from v_request->>'scope_proof_sha256'
    or v_scope.target_visibility <> 'owner_draft' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Cancel request does not bind the actor scope and receipt'
    );
  end if;

  v_expected_audit_payload := jsonb_build_object(
    'record_type', 'scope_cancel',
    'schema_version', 'dataset-flow-identity-scope-cancel.v2',
    'proof_domain', 'dataset-flow-identity-db-proof.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'cancel_request_sha256', v_request_sha256,
    'reason', btrim(v_request->>'reason'),
    'evidence_sha256', v_request->>'evidence_sha256',
    'completed_process_count', 0,
    'process_count', v_scope.process_count,
    'rewrite_count', v_scope.rewrite_count,
    'hash_algorithm', 'restricted-safe-json-v2-sha256'
  );
  if v_scope.status = 'cancelled' then
    if v_scope.cancel_request_sha256 is distinct from v_request_sha256 then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CANCEL_REPLAY_MISMATCH', 'status', 409,
        'message', 'Cancelled scope is bound to a different request'
      );
    end if;
    select count(*)::integer,
      jsonb_agg(audit.payload order by audit.id)->0,
      min(audit.id)
    into v_audit_count, v_audit_payload, v_audit_id
    from public.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
      and audit.payload->>'cancel_request_sha256' = v_request_sha256;
    if v_audit_count <> 1
      or v_audit_payload is distinct from v_expected_audit_payload then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CANCEL_AUDIT_DRIFT', 'status', 409,
        'message', 'The authoritative v2 cancel audit is missing or drifted'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', 'dataset-flow-identity-scope-cancel-result.v2',
      'scope_id', v_scope.id, 'receipt_id', v_receipt.id,
      'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
      'operation_id', v_scope.operation_id, 'plan_sha256', v_scope.plan_sha256,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'cancel_request_sha256', v_request_sha256,
      'status', 'cancelled', 'completed_process_count', 0,
      'audit_id', v_audit_id::text, 'replay', true
    );
  end if;
  if v_scope.status <> 'sealed' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_REQUIRES_ZERO_WRITE_SEAL', 'status', 409,
      'message', 'Only an untouched sealed scope can be cancelled',
      'scope_status', v_scope.status, 'automatic_retry', false
    );
  end if;

  select count(*)::integer,
    count(*) filter (where ledger.status = 'completed')::integer,
    count(*) filter (where ledger.status <> 'pending')::integer,
    count(*) filter (where not ledger.active)::integer,
    count(*) filter (
      where ledger.audit_id is not null
        or ledger.after_payload_sha256 is not null
        or ledger.after_exchange_set_sha256 is not null
        or ledger.derivative_batch_id is not null
        or ledger.process_request_sha256 is not null
        or ledger.completed_at is not null
    )::integer
  into v_ledger_count, v_completed_count, v_nonpending_count,
    v_inactive_count, v_primary_proof_count
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  select count(*)::integer into v_process_audit_count
  from public.command_audit_log as audit
  where audit.command = 'cmd_dataset_flow_identity_process_rewrite_guarded'
    and audit.actor_user_id = v_actor
    and audit.target_table = 'processes'
    and audit.payload->>'scope_id' = v_scope.id::text;
  select count(*)::integer into v_permit_count
  from util.dataset_flow_identity_mutation_permits as permit
  where permit.scope_id = v_scope.id;
  if v_ledger_count <> v_scope.process_count
    or v_completed_count <> 0 or v_nonpending_count <> 0
    or v_inactive_count <> 0 or v_primary_proof_count <> 0
    or v_process_audit_count <> 0 or v_permit_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_PRIMARY_WRITE_PROOF_EXISTS', 'status', 409,
      'message', 'Scope ledger or audit proves a primary write attempt',
      'completed_process_count', v_completed_count,
      'automatic_retry', false
    );
  end if;

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    v_command, v_actor, null, null, null, v_expected_audit_payload
  ) returning id into v_audit_id;
  update util.dataset_flow_identity_process_ledger
  set active = false where scope_id = v_scope.id;
  update util.dataset_flow_identity_scopes
  set status = 'cancelled', cancel_request_sha256 = v_request_sha256,
    last_error = jsonb_build_object(
      'code', 'FLOW_IDENTITY_SCOPE_CANCELLED',
      'schema_version', 'dataset-flow-identity-scope-cancel.v2',
      'cancel_request_sha256', v_request_sha256,
      'reason', btrim(v_request->>'reason'),
      'evidence_sha256', v_request->>'evidence_sha256'
    ), updated_at = clock_timestamp()
  where id = v_scope.id;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-cancel-result.v2',
    'scope_id', v_scope.id, 'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'operation_id', v_scope.operation_id, 'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'cancel_request_sha256', v_request_sha256,
    'status', 'cancelled', 'completed_process_count', 0,
    'audit_id', v_audit_id::text, 'replay', false
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_CANCEL_LOCK_BUSY', 'status', 409,
    'message', 'Cancellation could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb) IS 'Actor-only v2 Step 3 abandon path. Exact replay is read-only; a fresh cancel releases active fences only for an untouched sealed scope whose ledger, audit, derivative, and mutation-permit proof all show zero primary writes.';


--
-- Name: cmd_dataset_flow_identity_scope_finalize_guarded(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_scope_finalize_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_finalize_guarded';
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_request_sha256 text;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_whole_result jsonb;
  v_whole jsonb;
  v_internal jsonb;
  v_core jsonb;
  v_derivative_targets jsonb;
  v_derivative_target_set_sha256 text;
  v_terminal_proof_sha256 text;
  v_final_audit_id bigint;
  v_final_audit_payload jsonb;
  v_expected_final_audit_payload jsonb;
  v_live_drift boolean;
  v_live_guard_current boolean;
  v_was_completed boolean;
  v_result jsonb;
  v_invocation_id uuid;
  v_invocation util.dataset_flow_identity_wrapper_invocations%rowtype;
  v_execution_permit jsonb;
  v_permit_consumed boolean := false;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'scope_proof_sha256', 'expected'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-finalize.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'scope_proof_sha256' !~ '^[a-f0-9]{64}$'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'expected', array[
        'process_count', 'rewrite_count', 'completed_process_count'
      ]
    )
    or exists (
      select 1 from unnest(array[
        'process_count', 'rewrite_count', 'completed_process_count'
      ]) as field(name)
      where jsonb_typeof(v_request->'expected'->field.name) <> 'number'
        or (v_request->'expected'->>field.name)::numeric <= 0
        or (v_request->'expected'->>field.name)::numeric > 2147483647
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 thin finalize request schema mismatch'
    );
  end if;
  v_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_SCOPE_BUSY', 'status', 409,
      'message', 'Another transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null
    or v_scope.scope_proof_sha256
      is distinct from v_request->>'scope_proof_sha256'
    or v_scope.status in ('failed', 'cancelled')
    or (v_request #>> '{expected,process_count}')::integer
      <> v_scope.process_count
    or (v_request #>> '{expected,rewrite_count}')::integer
      <> v_scope.rewrite_count
    or (v_request #>> '{expected,completed_process_count}')::integer
      <> v_scope.process_count then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Finalize request does not bind the actor scope and counts'
    );
  end if;
  v_invocation_id := private.dataset_flow_identity_validate_wrapper_permit_v1(
    v_actor, p_scope_id, p_authorization, 'finalize'
  );
  if v_invocation_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_WRAPPER_PERMIT_REQUIRED', 'status', 409,
      'message', 'A fresh one-wrapper execution permit is required'
    );
  end if;
  select invocation.* into strict v_invocation
  from util.dataset_flow_identity_wrapper_invocations as invocation
  where invocation.id = v_invocation_id
    and invocation.scope_id = v_scope.id
    and invocation.actor_user_id = v_actor
  for update;
  v_was_completed := v_scope.status = 'completed';
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_scope.receipt_proof_sha256 then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, true
  );
  v_whole := v_whole_result->'whole_scope_proof';
  v_live_drift := coalesce((v_whole_result->>'ok')::boolean, false) is false;
  v_live_guard_current := coalesce(
      (v_whole->>'audit_current')::boolean, false
    ) and coalesce((v_whole->>'source_guards_current')::boolean, false
    ) and coalesce((v_whole->>'support_guards_current')::boolean, false)
    and coalesce((v_whole->>'target_guards_current')::boolean, false)
    and coalesce((v_whole->>'protected_closure_current')::boolean, false)
    and coalesce((v_whole->>'occurrence_closure_current')::boolean, false);
  select coalesce(jsonb_agg(jsonb_build_object(
    'ordinal', ledger.ordinal,
    'id', ledger.process_id,
    'version', ledger.process_version,
    'desired_json_ordered_sha256',
      ledger.manifest->>'desired_payload_sha256',
    'baseline_snapshot_sha256',
      ledger.manifest->>'derivative_baseline_snapshot_sha256'
  ) order by ledger.ordinal), '[]'::jsonb)
  into v_derivative_targets
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  v_derivative_target_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_derivative_targets);
  if not v_live_drift then
    v_internal := jsonb_build_object(
      'schema_version', 'dataset-flow-identity-scope-finalize.v1',
      'request_id', v_request->>'request_id',
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'expected', jsonb_build_object(
        'process_count', v_scope.process_count,
        'rewrite_count', v_scope.rewrite_count,
        'completed_process_count', v_scope.process_count,
        'primary_closure_sha256', v_whole->>'primary_closure_sha256',
        'protected_closure_sha256', v_scope.protected_closure_sha256,
        'derivative_target_set_sha256', v_derivative_target_set_sha256
      )
    );
    perform set_config(
      'app.dataset_flow_identity_v2_finalize_request_sha256',
      v_request_sha256, true
    );
    v_core := private.dataset_flow_identity_scope_finalize_core_v1(
      p_scope_id, v_internal
    );
    if v_core->>'status' not in ('derivatives_pending', 'completed') then
      v_core := jsonb_build_object(
        'ok', false,
        'status', 'failed',
        'code', 'FLOW_IDENTITY_FINALIZE_FAILED',
        'compensation_required', false,
        'compensation_targets', '[]'::jsonb
      );
    end if;
    select scope.* into v_scope
    from util.dataset_flow_identity_scopes as scope
    where scope.id = p_scope_id and scope.actor_user_id = v_actor
    for update;
    -- A fresh completion is promoted using the already current pre-core proof.
    -- Re-entering whole-scope proof before the v2 terminal audit exists would
    -- deterministically mark audit_current false.  Pending and replay paths do
    -- not have that transitional state and are re-read immediately.
    if v_core->>'status' <> 'completed' or v_was_completed then
      v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
        v_actor, v_receipt.id, v_scope.id, true
      );
      v_whole := v_whole_result->'whole_scope_proof';
      v_live_drift :=
        coalesce((v_whole_result->>'ok')::boolean, false) is false;
      v_live_guard_current := coalesce(
          (v_whole->>'audit_current')::boolean, false
        ) and coalesce((v_whole->>'source_guards_current')::boolean, false
        ) and coalesce((v_whole->>'support_guards_current')::boolean, false)
        and coalesce((v_whole->>'target_guards_current')::boolean, false)
        and coalesce((v_whole->>'protected_closure_current')::boolean, false)
        and coalesce((v_whole->>'occurrence_closure_current')::boolean, false);
    end if;
  end if;
  -- Completed replay is dynamic, not a trust in the stored scope status.  A
  -- stale/failed derivative downgrades to pending/compensation and must never
  -- rewrite the terminal proof or terminal audit.
  if not v_live_drift and v_core->>'status' = 'completed'
    and (
      coalesce((v_whole->>'derivatives_current')::boolean, false) is false
      or coalesce((v_whole->>'causal_terminal_proof')::boolean, false) is false
    ) then
    v_core := jsonb_build_object(
      'ok', coalesce((v_whole_result #>>
        '{derivative_set_proof,failed_count}')::integer, 0) = 0,
      'status', 'derivatives_pending',
      'code', case when coalesce((v_whole_result #>>
          '{derivative_set_proof,failed_count}')::integer, 0) > 0
        then 'FLOW_IDENTITY_DERIVATIVE_COMPENSATION_REQUIRED'
        else 'FLOW_IDENTITY_DERIVATIVES_PENDING' end,
      'compensation_required', coalesce((v_whole_result #>>
        '{derivative_set_proof,failed_count}')::integer, 0) > 0,
      'compensation_targets', coalesce(
        v_whole_result #> '{derivative_set_proof,compensation_targets}',
        '[]'::jsonb
      )
    );
  end if;
  if not v_live_drift and v_core->>'status' = 'completed'
      and not v_was_completed then
    v_terminal_proof_sha256 :=
      util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
        'schema_version', 'dataset-flow-identity-terminal-proof.v2',
        'scope_id', v_scope.id,
        'receipt_id', v_receipt.id,
        'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
        'scope_proof_sha256', v_scope.scope_proof_sha256,
        'plan_sha256', v_scope.plan_sha256,
        'final_request_sha256', v_request_sha256,
        'wrapper_invocation_id', v_invocation.id,
        'wrapper_approval_kind', v_invocation.approval_kind,
        'wrapper_approval_identity_sha256',
          v_invocation.approval_identity_sha256,
        'wrapper_admission_request_sha256',
          v_invocation.admission_request_sha256,
        'permit_generation_before', v_invocation.generation,
        'whole_scope_proof_sha256',
          v_whole_result->>'whole_scope_proof_sha256',
        'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
        'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
        'protected_closure_sha256', v_receipt.protected_closure_sha256,
        'derivative_target_set_sha256', v_derivative_target_set_sha256,
        'derivative_proof_set_sha256',
          v_whole->>'derivative_proof_set_sha256'
      ));
    update util.dataset_flow_identity_scopes
    set terminal_proof_sha256 = v_terminal_proof_sha256,
      final_wrapper_invocation_id = v_invocation.id,
      final_permit_generation_before = v_invocation.generation,
      updated_at = clock_timestamp()
    where id = v_scope.id;
    v_scope.terminal_proof_sha256 := v_terminal_proof_sha256;
    select audit.id, audit.payload
    into v_final_audit_id, v_final_audit_payload
    from public.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
    order by audit.id desc limit 1;
    if v_final_audit_id is null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_FINALIZE_V2_AUDIT_MISSING';
    end if;
    v_expected_final_audit_payload := jsonb_build_object(
        'record_type', 'scope_terminal',
        'schema_version', 'dataset-flow-identity-scope-finalize.v2',
        'proof_domain', 'dataset-flow-identity-db-proof.v2',
        'scope_id', v_scope.id,
        'receipt_id', v_receipt.id,
        'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
        'operation_id', v_scope.operation_id,
        'plan_sha256', v_scope.plan_sha256,
        'scope_proof_sha256', v_scope.scope_proof_sha256,
        'final_request_sha256', v_request_sha256,
        'wrapper_invocation_id', v_invocation.id,
        'wrapper_approval_kind', v_invocation.approval_kind,
        'wrapper_approval_identity_sha256',
          v_invocation.approval_identity_sha256,
        'wrapper_admission_request_sha256',
          v_invocation.admission_request_sha256,
        'permit_generation_before', v_invocation.generation,
        'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
        'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
        'protected_closure_sha256', v_receipt.protected_closure_sha256,
        'primary_closure_sha256', v_whole->>'primary_closure_sha256',
        'derivative_target_set_sha256', v_derivative_target_set_sha256,
        'derivative_proof_set_sha256',
          v_whole->>'derivative_proof_set_sha256',
        'whole_scope_proof_sha256',
          v_whole_result->>'whole_scope_proof_sha256',
        'terminal_proof_sha256', v_terminal_proof_sha256,
        'process_count', v_scope.process_count,
        'rewrite_count', v_scope.rewrite_count,
        'hash_algorithm', 'restricted-safe-json-v2-sha256'
      );
    update public.command_audit_log
    set payload = v_expected_final_audit_payload
    where id = v_final_audit_id and actor_user_id = v_actor
      and command = v_command and target_table is null
    returning payload into v_final_audit_payload;
    if v_final_audit_payload
        is distinct from v_expected_final_audit_payload then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_FINALIZE_V2_AUDIT_PROMOTION_FAILED';
    end if;
    -- Terminal consumption is part of the same transaction and precedes the
    -- durable post-promotion proof.  The proof therefore requires the exact
    -- N -> N+1 terminal rotation and one successful finalize post.
    v_execution_permit :=
      private.dataset_flow_identity_rotate_wrapper_permit_v1(
        v_invocation_id, 'finalize', true
      );
    v_permit_consumed := true;
    v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
      v_actor, v_receipt.id, v_scope.id, true
    );
    v_whole := v_whole_result->'whole_scope_proof';
    v_live_drift :=
      coalesce((v_whole_result->>'ok')::boolean, false) is false;
    v_live_guard_current := coalesce(
        (v_whole->>'audit_current')::boolean, false
      ) and coalesce((v_whole->>'source_guards_current')::boolean, false
      ) and coalesce((v_whole->>'support_guards_current')::boolean, false)
      and coalesce((v_whole->>'target_guards_current')::boolean, false)
      and coalesce((v_whole->>'protected_closure_current')::boolean, false)
      and coalesce((v_whole->>'occurrence_closure_current')::boolean, false);
    if v_live_drift then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_FINALIZE_POST_PROMOTION_DRIFT';
    end if;
  else
    select audit.id into v_final_audit_id
    from public.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
    order by audit.id desc limit 1;
  end if;
  v_result := jsonb_build_object(
    'ok', not v_live_drift
      and coalesce(v_core->>'status', '') <> 'failed'
      and coalesce((v_core->>'compensation_required')::boolean, false) is false,
    'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-finalize-result.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'invocation_id', v_invocation.id,
    'permit_generation_before', v_invocation.generation,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', case when v_live_drift then 'live_drift'
      else v_core->>'status' end,
    'process_count', v_scope.process_count,
    'completed_process_count',
      (v_request #>> '{expected,completed_process_count}')::integer,
    'rewrite_count', v_scope.rewrite_count,
    'primary_closure_sha256', v_whole->>'primary_closure_sha256',
    'protected_closure_sha256', v_receipt.protected_closure_sha256,
    'derivative_target_set_sha256', v_derivative_target_set_sha256,
    'derivative_proof_set_sha256',
      v_whole->>'derivative_proof_set_sha256',
    'primary_current', (v_whole->>'primary_current')::boolean,
    'live_guard_current', v_live_guard_current,
    'derivatives_current', case when v_live_drift then false
      else (v_whole->>'derivatives_current')::boolean end,
    'terminal_proof_sha256', case
      when not v_live_drift and v_core->>'status' = 'completed'
      then v_scope.terminal_proof_sha256 else null end,
    'whole_scope_proof', v_whole,
    'whole_scope_proof_sha256',
      v_whole_result->>'whole_scope_proof_sha256',
    'audit_id', case when v_final_audit_id is null
      then null else v_final_audit_id::text end,
    'replay', v_was_completed
  );
  if coalesce((v_result->>'ok')::boolean, false) then
    if not v_permit_consumed then
      v_execution_permit :=
        private.dataset_flow_identity_rotate_wrapper_permit_v1(
          v_invocation_id, 'finalize', false
        );
    end if;
    v_result := v_result || jsonb_build_object(
      'execution_permit', v_execution_permit
    );
  else
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
  end if;
  if v_live_drift then
    return v_result || jsonb_build_object(
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT',
      'compensation_required', false,
      'automatic_retry', false,
      'compensation_targets', '[]'::jsonb
    );
  elsif v_core->>'status' = 'derivatives_pending' then
    return v_result || jsonb_build_object(
      'code', v_core->>'code',
      'compensation_required',
        coalesce((v_core->>'compensation_required')::boolean, false),
      'automatic_retry', false,
      'compensation_targets',
        coalesce(v_core->'compensation_targets', '[]'::jsonb)
    );
  elsif v_core->>'status' = 'failed' then
    return v_result || jsonb_build_object(
      'code', 'FLOW_IDENTITY_FINALIZE_FAILED',
      'compensation_required', false,
      'automatic_retry', false,
      'compensation_targets', '[]'::jsonb
    );
  end if;
  return v_result;
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_FINALIZE_LOCK_BUSY', 'status', 409,
    'message', 'Finalization could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_scope_finalize_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_lookup(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_scope_lookup(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text := 'cmd_dataset_flow_identity_scope_lookup';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_whole_result jsonb;
  v_audit_id bigint;
  v_next_ordinal integer;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if v_request is null or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'receipt_id', 'receipt_proof_sha256',
      'environment', 'project_ref', 'actor', 'target_visibility',
      'user_state_claim', 'operation_id', 'plan_sha256', 'freeze_sha256',
      'policy_approval_text_sha256', 'execution_approval_request_sha256',
      'execution_approval_text_sha256',
      'execution_approval_identity_sha256', 'toolchain_evidence_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-lookup.v1'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'receipt_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or v_request->>'user_state_claim'
      <> 'authenticated_actor_state_100_plus_own_state_0'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}')) is distinct from v_actor_email
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or exists (
      select 1 from unnest(array[
        'receipt_proof_sha256', 'plan_sha256', 'freeze_sha256',
        'policy_approval_text_sha256', 'execution_approval_request_sha256',
        'execution_approval_text_sha256',
        'execution_approval_identity_sha256', 'toolchain_evidence_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_INVALID_REQUEST', 'status', 400,
      'message', 'Scope lookup request schema mismatch'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.actor_user_id = v_actor
    and scope.request_id = (v_request->>'request_id')::uuid
    and scope.receipt_id = (v_request->>'receipt_id')::uuid
    and scope.receipt_proof_sha256 = v_request->>'receipt_proof_sha256'
    and scope.environment = v_request->>'environment'
    and scope.project_ref = v_request->>'project_ref'
    and scope.target_visibility = v_request->>'target_visibility'
    and scope.user_state_claim = v_request->>'user_state_claim'
    and scope.operation_id = v_request->>'operation_id'
    and scope.plan_sha256 = v_request->>'plan_sha256'
    and scope.freeze_sha256 = v_request->>'freeze_sha256'
    and scope.policy_approval_text_sha256 =
      v_request->>'policy_approval_text_sha256'
    and scope.execution_approval_request_sha256 =
      v_request->>'execution_approval_request_sha256'
    and scope.approval_text_sha256 =
      v_request->>'execution_approval_text_sha256'
    and scope.approval_identity_sha256 =
      v_request->>'execution_approval_identity_sha256'
    and scope.toolchain_evidence_sha256 =
      v_request->>'toolchain_evidence_sha256';
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_NOT_FOUND', 'status', 404,
      'message', 'No exactly bound actor-owned Step 3 scope exists'
    );
  end if;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor
    and receipt.receipt_proof_sha256 = v_scope.receipt_proof_sha256;
  if v_receipt.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, false
  );
  if coalesce((v_whole_result->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
      'message', 'Located scope no longer matches live database state'
    );
  end if;
  select audit.id into v_audit_id
  from public.command_audit_log as audit
  where audit.command = 'cmd_dataset_flow_identity_scope_preflight_guarded'
    and audit.actor_user_id = v_actor and audit.target_table is null
    and audit.payload->>'scope_id' = v_scope.id::text;
  if v_audit_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_AUDIT_DRIFT', 'status', 409,
      'message', 'Authoritative scope-seal audit is missing'
    );
  end if;
  select coalesce(min(ledger.ordinal) filter (
    where ledger.status = 'pending'
  ), v_scope.process_count + 1)
  into v_next_ordinal
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-lookup-result.v1',
    'read_only', true,
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_scope.status,
    'process_count', v_scope.process_count,
    'mapping_count', v_scope.mapping_count,
    'support_snapshot_count', v_receipt.support_count,
    'source_universe_count', 305,
    'rewrite_count', v_scope.rewrite_count,
    'next_ordinal', v_next_ordinal,
    'audit_id', v_audit_id::text,
    'whole_scope_proof_sha256',
      v_whole_result->>'whole_scope_proof_sha256',
    'execution_permit', null
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_scope_lookup(p_request jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_preflight_guarded(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_scope_preflight_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_preflight_guarded';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_request_sha256 text;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_internal jsonb;
  v_core_result jsonb;
  v_live jsonb;
  v_mappings jsonb;
  v_supports jsonb;
  v_processes jsonb;
  v_scope_proof_sha256 text;
  v_audit_id bigint;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
  v_invocation_id uuid;
  v_permit_token text;
  v_execution_permit jsonb := null;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'receipt_id', 'receipt_proof_sha256',
      'environment', 'project_ref', 'actor', 'target_visibility',
      'user_state_claim',
      'operation_id', 'plan_sha256', 'freeze_sha256',
      'policy_approval_text_sha256', 'execution_approval_request_sha256',
      'execution_approval_text_sha256',
      'execution_approval_identity_sha256', 'toolchain_evidence_sha256',
      'maximum_wrapper_invocations', 'maximum_process_posts',
      'maximum_finalize_posts', 'maximum_cli_apply_spawns',
      'approval_reusable', 'automatic_retry'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-preflight.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'receipt_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or v_request->>'user_state_claim'
      <> 'authenticated_actor_state_100_plus_own_state_0'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}'))
      is distinct from v_actor_email
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or jsonb_typeof(v_request->'maximum_wrapper_invocations') <> 'number'
    or (v_request->>'maximum_wrapper_invocations')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_process_posts') <> 'number'
    or (v_request->>'maximum_process_posts')::numeric <= 0
    or (v_request->>'maximum_process_posts')::numeric > 2147483647
    or jsonb_typeof(v_request->'maximum_finalize_posts') <> 'number'
    or (v_request->>'maximum_finalize_posts')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_cli_apply_spawns') <> 'number'
    or (v_request->>'maximum_cli_apply_spawns')::numeric <> 1
    or v_request->'approval_reusable' is distinct from 'false'::jsonb
    or v_request->'automatic_retry' is distinct from 'false'::jsonb
    or exists (
      select 1 from unnest(array[
        'receipt_proof_sha256', 'plan_sha256', 'freeze_sha256',
        'policy_approval_text_sha256', 'execution_approval_request_sha256',
        'execution_approval_text_sha256',
        'execution_approval_identity_sha256', 'toolchain_evidence_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    )
    or (
      select count(distinct value)
      from unnest(array[
        v_request->>'policy_approval_text_sha256',
        v_request->>'execution_approval_request_sha256',
        v_request->>'execution_approval_text_sha256',
        v_request->>'execution_approval_identity_sha256'
      ]) as approval(value)
    ) <> 4 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 preflight request schema mismatch'
    );
  end if;
  v_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);

  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = (v_request->>'receipt_id')::uuid
    and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_request->>'receipt_proof_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_RECEIPT_INVALID', 'status', 409,
      'message', 'Capture receipt is missing, foreign, or forged'
    );
  end if;
  if v_receipt.environment is distinct from v_request->>'environment'
    or v_receipt.project_ref is distinct from v_request->>'project_ref'
    or v_receipt.target_visibility
      is distinct from v_request->>'target_visibility'
    or v_receipt.operation_id is distinct from v_request->>'operation_id'
    or v_receipt.policy_approval_text_sha256
      is distinct from v_request->>'policy_approval_text_sha256'
    or v_receipt.artifact_evidence->>'toolchain_evidence_sha256'
      is distinct from v_request->>'toolchain_evidence_sha256'
    or (v_request->>'maximum_process_posts')::integer
      is distinct from v_receipt.process_count then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_RECEIPT_BINDING_MISMATCH',
      'status', 409,
      'message', 'Preflight identity does not exactly bind the receipt'
    );
  end if;
  -- The owner fence is held through activation.  A concurrent row UPDATE
  -- blocked by the deterministic FOR SHARE proof resumes into this VOLATILE
  -- BEFORE trigger under READ COMMITTED, where the trigger's SQL sees the
  -- newly committed active scope and rejects the write.
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));

  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.actor_user_id = v_actor
    and scope.operation_id = v_receipt.operation_id;
  if v_scope.id is not null then
    if v_scope.receipt_id is distinct from v_receipt.id
      or v_scope.preflight_request_sha256 is distinct from v_request_sha256 then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_OPERATION_REUSE_MISMATCH',
        'status', 409, 'message', 'Operation is already sealed differently'
      );
    end if;
    if v_scope.status in ('cancelled', 'failed') then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_SCOPE_TERMINAL_CONFLICT',
        'status', 409, 'scope_status', v_scope.status,
        'message', 'A cancelled or failed scope cannot be replayed as v2'
      );
    end if;
  else
    if exists (
      select 1
      from util.dataset_flow_identity_wrapper_invocations as invocation
      where invocation.actor_user_id = v_actor
        and array[
          v_request->>'execution_approval_request_sha256',
          v_request->>'execution_approval_text_sha256',
          v_request->>'execution_approval_identity_sha256'
        ] && array[
          invocation.approval_request_sha256,
          invocation.approval_text_sha256,
          invocation.approval_identity_sha256
        ]
    ) then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_APPROVAL_REUSE_MISMATCH',
        'status', 409,
        'message', 'Execution approval hash was already consumed'
      );
    end if;
    if v_receipt.expires_at <= clock_timestamp() then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_RECEIPT_EXPIRED', 'status', 409,
        'message', 'Capture receipt expired before first consumption'
      );
    end if;
    v_live := private.dataset_flow_identity_whole_scope_proof_v2(
      v_actor, v_receipt.id, null, true
    );
    if coalesce((v_live->>'ok')::boolean, false) is false then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_LIVE_DRIFT', 'status', 409,
        'message', 'Receipt baselines drifted before scope sealing'
      );
    end if;

    select coalesce(jsonb_agg(guard.mapping order by guard.ordinal), '[]'::jsonb)
    into v_mappings
    from util.dataset_flow_identity_capture_mapping_guards as guard
    where guard.receipt_id = v_receipt.id;
    select coalesce(jsonb_agg(guard.guard order by guard.ordinal), '[]'::jsonb)
    into v_supports
    from util.dataset_flow_identity_capture_support_guards as guard
    where guard.receipt_id = v_receipt.id;
    select coalesce(jsonb_agg(intent.manifest order by intent.ordinal), '[]'::jsonb)
    into v_processes
    from util.dataset_flow_identity_capture_process_intents as intent
    where intent.receipt_id = v_receipt.id;

    v_internal := jsonb_build_object(
      'schema_version', 'dataset-flow-identity-scope-preflight.v1',
      'request_id', v_request->>'request_id',
      'environment', v_receipt.environment,
      'project_ref', v_receipt.project_ref,
      'actor', jsonb_build_object(
        'user_id', v_actor, 'email', v_actor_email
      ),
      'target_visibility', 'owner_draft',
      'operation_id', v_receipt.operation_id,
      'plan_sha256', v_request->>'plan_sha256',
      'freeze_sha256', v_request->>'freeze_sha256',
      'approval_identity_sha256',
        v_request->>'execution_approval_identity_sha256',
      'approval_text_sha256',
        v_request->>'execution_approval_text_sha256',
      'toolchain_evidence_sha256',
        v_request->>'toolchain_evidence_sha256',
      'compatibility_policy', v_receipt.compatibility_policy,
      'support_snapshot_set_sha256',
        v_receipt.support_snapshot_set_sha256,
      'support_snapshots', v_supports,
      'source_universe_sha256', v_receipt.source_universe_sha256,
      'source_universe_count', 305,
      'mapping_set_sha256', v_receipt.mapping_set_sha256,
      'process_manifest_sha256', v_receipt.process_manifest_sha256,
      'protected_closure_sha256', v_receipt.protected_closure_sha256,
      'mappings', v_mappings,
      'processes', v_processes,
      'protected_closure', v_receipt.protected_closure
    );
    perform set_config(
      'app.dataset_flow_identity_receipt_id', v_receipt.id::text, true
    );
    perform set_config(
      'app.dataset_flow_identity_receipt_proof_sha256',
      v_receipt.receipt_proof_sha256, true
    );
    perform set_config(
      'app.dataset_flow_identity_policy_approval_sha256',
      v_receipt.policy_approval_text_sha256, true
    );
    perform set_config(
      'app.dataset_flow_identity_execution_request_sha256',
      v_request->>'execution_approval_request_sha256', true
    );
    perform set_config(
      'app.dataset_flow_identity_preflight_request_sha256',
      v_request_sha256, true
    );
    v_core_result :=
      private.dataset_flow_identity_scope_preflight_core_v1(v_internal);
    if coalesce((v_core_result->>'ok')::boolean, false) is false then
      return v_core_result;
    end if;
    select scope.* into v_scope
    from util.dataset_flow_identity_scopes as scope
    where scope.id = (v_core_result->>'scope_id')::uuid
      and scope.actor_user_id = v_actor;
    if v_scope.id is null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PREFLIGHT_SCOPE_MISSING_AFTER_CORE';
    end if;
    v_scope_proof_sha256 :=
      util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
        'schema_version', 'dataset-flow-identity-scope-proof.v2',
        'scope_id', v_scope.id,
        'receipt_id', v_receipt.id,
        'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
        'actor_user_id', v_actor,
        'environment', v_scope.environment,
        'project_ref', v_scope.project_ref,
        'operation_id', v_scope.operation_id,
        'plan_sha256', v_scope.plan_sha256,
        'freeze_sha256', v_scope.freeze_sha256,
        'policy_approval_text_sha256',
          v_scope.policy_approval_text_sha256,
        'execution_approval_request_sha256',
          v_scope.execution_approval_request_sha256,
        'execution_approval_text_sha256', v_scope.approval_text_sha256,
        'execution_approval_identity_sha256',
          v_scope.approval_identity_sha256,
        'toolchain_evidence_sha256', v_scope.toolchain_evidence_sha256,
        'preflight_request_sha256', v_scope.preflight_request_sha256,
        'capture_whole_scope_proof_sha256',
          v_receipt.whole_scope_proof_sha256
      ));
    update util.dataset_flow_identity_scopes
    set scope_proof_sha256 = v_scope_proof_sha256,
      updated_at = clock_timestamp()
    where id = v_scope.id;
    v_scope.scope_proof_sha256 := v_scope_proof_sha256;
  end if;

  select audit.id, audit.payload into v_audit_id, v_audit_payload
  from public.command_audit_log as audit
  where audit.command = v_command and audit.actor_user_id = v_actor
    and audit.target_table is null
    and audit.payload->>'scope_id' = v_scope.id::text
  order by audit.id desc limit 1;
  if v_audit_id is null then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PREFLIGHT_V2_AUDIT_MISSING';
  end if;
  v_expected_audit_payload := jsonb_build_object(
      'record_type', 'scope_seal',
      'schema_version', 'dataset-flow-identity-scope-preflight.v2',
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'scope_id', v_scope.id,
      'receipt_id', v_receipt.id,
      'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'freeze_sha256', v_scope.freeze_sha256,
      'capture_request_sha256', v_receipt.capture_request_sha256,
      'capture_whole_scope_proof_sha256',
        v_receipt.whole_scope_proof_sha256,
      'source_guard_set_sha256', v_receipt.source_guard_set_sha256,
      'support_guard_set_sha256', v_receipt.support_snapshot_set_sha256,
      'target_guard_set_sha256', v_receipt.target_guard_set_sha256,
      'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
      'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
      'protected_closure_sha256', v_receipt.protected_closure_sha256,
      'policy_sha256', v_receipt.compatibility_policy->>'policy_sha256',
      'policy_approval_text_sha256',
        v_scope.policy_approval_text_sha256,
      'execution_approval_request_sha256',
        v_scope.execution_approval_request_sha256,
      'execution_approval_text_sha256', v_scope.approval_text_sha256,
      'execution_approval_identity_sha256',
        v_scope.approval_identity_sha256,
      'toolchain_evidence_sha256', v_scope.toolchain_evidence_sha256,
      'user_state_claim', v_scope.user_state_claim,
      'maximum_wrapper_invocations', 1,
      'maximum_process_posts', v_scope.process_count,
      'maximum_finalize_posts', 1,
      'maximum_cli_apply_spawns', 1,
      'approval_reusable', false,
      'automatic_retry', false,
      'preflight_request_sha256', v_scope.preflight_request_sha256,
      'scope_request_sha256', v_scope.scope_request_sha256,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'source_universe_count', 305,
      'mapping_count', v_scope.mapping_count,
      'process_count', v_scope.process_count,
      'rewrite_count', v_scope.rewrite_count,
      'hash_algorithm', 'restricted-safe-json-v2-sha256'
    );
  if v_core_result is not null then
    update public.command_audit_log
    set payload = v_expected_audit_payload
    where id = v_audit_id and actor_user_id = v_actor
      and command = v_command and target_table is null
    returning payload into v_audit_payload;
  end if;
  -- Fresh execution promotes the core's v1 row first; replay never mutates it.
  -- In both cases an exact reread/compare precedes whole-scope proof so that
  -- audit_current cannot deterministically reject a just-created scope.
  if v_audit_payload is distinct from v_expected_audit_payload then
    if v_core_result is not null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PREFLIGHT_V2_AUDIT_PROMOTION_FAILED';
    end if;
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_V2_AUDIT_DRIFT', 'status', 409,
      'message', 'The authoritative v2 scope audit is missing or drifted'
    );
  end if;
  v_live := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, true
  );
  if coalesce((v_live->>'ok')::boolean, false) is false then
    if v_core_result is not null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PREFLIGHT_POST_SEAL_DRIFT';
    end if;
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
      'message', 'Sealed scope no longer matches live database state'
    );
  end if;
  if v_core_result is not null then
    v_permit_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
    insert into util.dataset_flow_identity_wrapper_invocations (
      scope_id, actor_user_id, approval_kind,
      approval_request_sha256, approval_text_sha256,
      approval_identity_sha256, admission_request_sha256,
      baseline_whole_scope_proof_sha256,
      token_sha256, maximum_process_posts, maximum_finalize_posts
    ) values (
      v_scope.id, v_actor, 'initial',
      v_scope.execution_approval_request_sha256,
      v_scope.approval_text_sha256,
      v_scope.approval_identity_sha256,
      v_scope.preflight_request_sha256,
      v_live->>'whole_scope_proof_sha256',
      private.dataset_flow_identity_permit_token_sha256_v1(v_permit_token),
      v_scope.process_count, 1
    ) returning id into v_invocation_id;
    v_execution_permit := jsonb_build_object(
      'schema_version', 'dataset-flow-identity-execution-permit.v1',
      'invocation_id', v_invocation_id,
      'generation', 0,
      'token', v_permit_token
    );
  end if;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-preflight-result.v2',
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'scope_id', v_scope.id,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_scope.status,
    'process_count', v_scope.process_count,
    'mapping_count', v_scope.mapping_count,
    'support_snapshot_count', v_receipt.support_count,
    'source_universe_count', 305,
    'rewrite_count', v_scope.rewrite_count,
    'next_ordinal', coalesce((
      select min(ledger.ordinal)
      from util.dataset_flow_identity_process_ledger as ledger
      where ledger.scope_id = v_scope.id and ledger.status = 'pending'
    ), v_scope.process_count + 1),
    'audit_id', v_audit_id::text,
    'replay', v_core_result is null,
    'execution_permit', v_execution_permit
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_PREFLIGHT_LOCK_BUSY', 'status', 409,
    'message', 'Scope seal could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_scope_preflight_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_scope_read(p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '90s'
    AS $$
declare
  v_command constant text := 'cmd_dataset_flow_identity_scope_read';
  v_actor uuid := auth.uid();
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_core jsonb;
  v_whole_result jsonb;
  v_whole jsonb;
  v_processes jsonb;
  v_status text;
  v_live_drift boolean;
  v_terminal_conflict boolean;
  v_compensation_required boolean;
  v_result jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  if p_scope_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_READ_INVALID_REQUEST', 'status', 400,
      'message', 'Scope ID is required'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor;
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_scope.receipt_proof_sha256 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  v_core := private.dataset_flow_identity_scope_read_core_v1(p_scope_id);
  if v_core->>'code' in ('AUTH_REQUIRED', 'FLOW_IDENTITY_SCOPE_NOT_FOUND') then
    return v_core;
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, false
  );
  v_whole := v_whole_result->'whole_scope_proof';
  if v_whole is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
      'message', 'Whole-scope proof could not be constructed'
    );
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'ordinal', ledger.ordinal,
    'id', ledger.process_id,
    'version', ledger.process_version,
    'status', ledger.status,
    'process_request_sha256', ledger.process_request_sha256,
    'process_intent_proof_sha256', ledger.process_intent_proof_sha256,
    'rewrite_count', ledger.rewrite_count,
    'audit_id', case when ledger.audit_id is null
      then null else ledger.audit_id::text end,
    'before_payload_sha256', ledger.before_payload_sha256,
    'before_exchange_set_sha256',
      ledger.manifest->>'before_exchange_set_sha256',
    'desired_payload_sha256', ledger.manifest->>'desired_payload_sha256',
    'desired_exchange_set_sha256',
      ledger.manifest->>'desired_exchange_set_sha256',
    'after_payload_sha256', ledger.after_payload_sha256,
    'after_exchange_set_sha256', ledger.after_exchange_set_sha256,
    'derivative_batch_id', ledger.derivative_batch_id,
    'derivative_request_id', child.id,
    'derivative_status', case when ledger.derivative_batch_id is null
      then null else coalesce(child.status, 'missing') end,
    'causal_terminal_proof', false,
    'completed_at', ledger.completed_at,
    'last_error', coalesce(ledger.last_error, child.last_error)
  ) order by ledger.ordinal), '[]'::jsonb)
  into v_processes
  from util.dataset_flow_identity_process_ledger as ledger
  left join util.dataset_derivative_rebuild_requests as child
    on child.actor_user_id = v_actor
    and child.batch_id = ledger.derivative_batch_id
    and child.target_table = 'processes'
    and child.target_id = ledger.process_id
    and child.target_version = ledger.process_version
  where ledger.scope_id = p_scope_id;
  v_terminal_conflict := v_scope.status in ('cancelled', 'failed');
  v_live_drift := v_terminal_conflict
    or coalesce((v_whole_result->>'ok')::boolean, false) is false;
  v_status := case when v_live_drift then 'live_drift'
    else v_core->>'status' end;
  v_compensation_required := not v_live_drift
    and coalesce((v_core->>'derivative_failed_count')::integer, 0) > 0;
  v_result := jsonb_build_object(
    'ok', v_status not in ('failed', 'live_drift')
      and not v_compensation_required,
    'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-status.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_status,
    'process_count', (v_core->>'process_count')::integer,
    'completed_process_count',
      (v_core->>'completed_process_count')::integer,
    'pending_process_count', (v_core->>'pending_process_count')::integer,
    'failed_process_count', (v_core->>'failed_process_count')::integer,
    'next_ordinal', (v_core->>'next_ordinal')::integer,
    'rewrite_count', (v_core->>'rewrite_count')::integer,
    'completed_rewrite_count',
      (v_core->>'completed_rewrite_count')::integer,
    'primary_complete', (v_core->>'primary_complete')::boolean,
    'cancellable', (v_core->>'cancellable')::boolean,
    'strict_continuation_required',
      (v_core->>'strict_continuation_required')::boolean,
    'primary_current', (v_whole->>'primary_current')::boolean,
    'live_guard_current',
      (v_whole->>'audit_current')::boolean
      and (v_whole->>'source_guards_current')::boolean
      and (v_whole->>'support_guards_current')::boolean
      and (v_whole->>'target_guards_current')::boolean
      and (v_whole->>'protected_closure_current')::boolean
      and (v_whole->>'occurrence_closure_current')::boolean,
    'derivatives_current', case when v_live_drift then false
      else (v_whole->>'derivatives_current')::boolean end,
    'derivative_pending_count',
      (v_core->>'derivative_pending_count')::integer,
    'derivative_failed_count',
      (v_core->>'derivative_failed_count')::integer,
    'derivative_set_proof', v_whole_result->'derivative_set_proof',
    'derivative_proof_set_sha256',
      v_whole_result #>> '{derivative_set_proof,proof_sha256}',
    'compensation_required', v_compensation_required,
    'automatic_retry', false,
    'compensation_targets', case when v_compensation_required
      then v_core->'compensation_targets' else '[]'::jsonb end,
    'protected_closure_current',
      (v_whole->>'protected_closure_current')::boolean,
    'protected_closure_proof', v_core->'protected_closure_proof',
    'processes', v_processes,
    'terminal_proof_sha256', case when v_status = 'completed'
      then v_scope.terminal_proof_sha256 else null end,
    'completed_at', case when v_status = 'completed'
      then v_scope.completed_at else null end,
    'whole_scope_proof', v_whole,
    'whole_scope_proof_sha256',
      v_whole_result->>'whole_scope_proof_sha256'
  );
  if v_live_drift then
    v_result := v_result || jsonb_build_object(
      'code', case when v_terminal_conflict
        then 'FLOW_IDENTITY_SCOPE_TERMINAL_CONFLICT'
        else 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT' end
    );
  elsif v_compensation_required then
    v_result := v_result || jsonb_build_object(
      'code', 'FLOW_IDENTITY_DERIVATIVE_COMPENSATION_REQUIRED'
    );
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION public.cmd_dataset_flow_identity_scope_read(p_scope_id uuid) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_recover_guarded(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_flow_identity_scope_recover_guarded(p_scope_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_recover_guarded';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_wire_request_sha256 text;
  v_approved_at timestamp with time zone;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_existing util.dataset_flow_identity_wrapper_invocations%rowtype;
  v_invocation_id uuid;
  v_whole_result jsonb;
  v_completed_count integer;
  v_next_ordinal integer;
  v_remaining_count integer;
  v_mode text;
  v_token text;
  v_audit_id bigint;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'approved_at_utc',
      'environment', 'project_ref', 'actor', 'target_visibility',
      'user_state_claim', 'operation_id', 'plan_sha256', 'freeze_sha256',
      'original_execution_approval_identity_sha256', 'scope_proof_sha256',
      'observed_scope_status', 'observed_completed_process_count',
      'observed_next_ordinal', 'observed_whole_scope_proof_sha256',
      'recovery_mode', 'recovery_reason', 'toolchain_evidence_sha256',
      'maximum_wrapper_invocations', 'maximum_process_posts',
      'maximum_finalize_posts', 'maximum_cli_apply_spawns',
      'approval_reusable', 'automatic_retry',
      'recovery_approval_request_sha256',
      'recovery_approval_text_sha256',
      'recovery_approval_identity_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-recovery.v1'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or v_request->>'user_state_claim'
      <> 'authenticated_actor_state_100_plus_own_state_0'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}')) is distinct from v_actor_email
    or v_request->>'observed_scope_status' not in (
      'sealed', 'running', 'primary_complete', 'derivatives_pending'
    )
    or v_request->>'recovery_mode' not in (
      'resume_and_finalize', 'finalize_only'
    )
    or v_request->>'recovery_reason' not in (
      'wrapper_exited_without_permit', 'process_response_ambiguous',
      'process_domain_rejected', 'finalize_response_ambiguous',
      'derivatives_became_ready_after_wrapper_exit'
    )
    or jsonb_typeof(v_request->'observed_completed_process_count') <> 'number'
    or (v_request->>'observed_completed_process_count')::numeric < 0
    or (v_request->>'observed_completed_process_count')::numeric > 2147483647
    or jsonb_typeof(v_request->'observed_next_ordinal') <> 'number'
    or (v_request->>'observed_next_ordinal')::numeric < 1
    or (v_request->>'observed_next_ordinal')::numeric > 2147483647
    or (v_request->>'observed_next_ordinal')::numeric <>
      trunc((v_request->>'observed_next_ordinal')::numeric)
    or jsonb_typeof(v_request->'maximum_wrapper_invocations') <> 'number'
    or (v_request->>'maximum_wrapper_invocations')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_process_posts') <> 'number'
    or (v_request->>'maximum_process_posts')::numeric < 0
    or (v_request->>'maximum_process_posts')::numeric > 2147483647
    or jsonb_typeof(v_request->'maximum_finalize_posts') <> 'number'
    or (v_request->>'maximum_finalize_posts')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_cli_apply_spawns') <> 'number'
    or (v_request->>'maximum_cli_apply_spawns')::numeric <> 1
    or v_request->'approval_reusable' is distinct from 'false'::jsonb
    or v_request->'automatic_retry' is distinct from 'false'::jsonb
    or exists (
      select 1 from unnest(array[
        'plan_sha256', 'freeze_sha256',
        'original_execution_approval_identity_sha256', 'scope_proof_sha256',
        'observed_whole_scope_proof_sha256', 'toolchain_evidence_sha256',
        'recovery_approval_request_sha256',
        'recovery_approval_text_sha256',
        'recovery_approval_identity_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_INVALID_REQUEST', 'status', 400,
      'message', 'Recovery approval request schema mismatch'
    );
  end if;
  begin
    v_approved_at := (v_request->>'approved_at_utc')::timestamp with time zone;
  exception when others then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_INVALID_APPROVAL_TIME', 'status', 400,
      'message', 'Recovery approval timestamp is invalid'
    );
  end;
  v_wire_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);
  if cardinality(array[
      v_request->>'recovery_approval_request_sha256',
      v_request->>'recovery_approval_text_sha256',
      v_request->>'recovery_approval_identity_sha256'
    ]) <> (
      select count(distinct value)
      from unnest(array[
        v_request->>'recovery_approval_request_sha256',
        v_request->>'recovery_approval_text_sha256',
        v_request->>'recovery_approval_identity_sha256'
      ]) as approval(value)
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_APPROVAL_HASH_MISMATCH', 'status', 409,
      'message', 'Recovery approval artifact hashes must be distinct'
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_SCOPE_BUSY', 'status', 409,
      'message', 'Another transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  if v_scope.status in ('completed', 'failed', 'cancelled')
    or v_scope.scope_proof_sha256 is distinct from
      v_request->>'scope_proof_sha256'
    or v_scope.environment is distinct from v_request->>'environment'
    or v_scope.project_ref is distinct from v_request->>'project_ref'
    or v_scope.target_visibility is distinct from
      v_request->>'target_visibility'
    or v_scope.user_state_claim is distinct from
      v_request->>'user_state_claim'
    or v_scope.operation_id is distinct from v_request->>'operation_id'
    or v_scope.plan_sha256 is distinct from v_request->>'plan_sha256'
    or v_scope.freeze_sha256 is distinct from v_request->>'freeze_sha256'
    or v_scope.approval_identity_sha256 is distinct from
      v_request->>'original_execution_approval_identity_sha256'
    or v_approved_at < v_scope.sealed_at
    or exists (
      select 1 from unnest(array[
        v_request->>'recovery_approval_request_sha256',
        v_request->>'recovery_approval_text_sha256',
        v_request->>'recovery_approval_identity_sha256'
      ]) as recovery(value)
      where recovery.value = any(array[
        v_scope.policy_approval_text_sha256,
        v_scope.execution_approval_request_sha256,
        v_scope.approval_text_sha256,
        v_scope.approval_identity_sha256
      ])
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_SCOPE_BINDING_MISMATCH', 'status', 409,
      'message', 'Recovery approval does not bind this active scope'
    );
  end if;

  select invocation.* into v_existing
  from util.dataset_flow_identity_wrapper_invocations as invocation
  where invocation.actor_user_id = v_actor
    and array[
      v_request->>'recovery_approval_request_sha256',
      v_request->>'recovery_approval_text_sha256',
      v_request->>'recovery_approval_identity_sha256'
    ] && array[
      invocation.approval_request_sha256,
      invocation.approval_text_sha256,
      invocation.approval_identity_sha256
    ]
  order by invocation.admitted_at, invocation.id
  limit 1;
  if v_existing.id is not null then
    if v_existing.scope_id is distinct from v_scope.id
      or v_existing.approval_kind <> 'recovery'
      or v_existing.approval_request_sha256 is distinct from
        v_request->>'recovery_approval_request_sha256'
      or v_existing.approval_text_sha256 is distinct from
        v_request->>'recovery_approval_text_sha256'
      or v_existing.approval_identity_sha256 is distinct from
        v_request->>'recovery_approval_identity_sha256'
      or v_existing.admission_request_sha256 is distinct from
        v_wire_request_sha256
      or v_existing.baseline_whole_scope_proof_sha256 is distinct from
        v_request->>'observed_whole_scope_proof_sha256' then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_RECOVERY_APPROVAL_REUSE_MISMATCH',
        'status', 409,
        'message', 'Recovery approval was already consumed differently'
      );
    end if;
    select audit.id, audit.payload into v_audit_id, v_audit_payload
    from public.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
      and audit.payload->>'recovery_approval_identity_sha256'
        = v_existing.approval_identity_sha256;
    if v_audit_id is null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_RECOVERY_REPLAY_AUDIT_MISSING';
    end if;
    v_expected_audit_payload := jsonb_build_object(
      'record_type', 'scope_recovery_admission',
      'schema_version', 'dataset-flow-identity-scope-recovery.v1',
      'scope_id', v_scope.id,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'freeze_sha256', v_scope.freeze_sha256,
      'original_execution_approval_identity_sha256',
        v_scope.approval_identity_sha256,
      'observed_whole_scope_proof_sha256',
        v_request->>'observed_whole_scope_proof_sha256',
      'observed_scope_status', v_request->>'observed_scope_status',
      'observed_completed_process_count',
        (v_request->>'observed_completed_process_count')::integer,
      'observed_next_ordinal',
        (v_request->>'observed_next_ordinal')::integer,
      'recovery_mode', v_request->>'recovery_mode',
      'recovery_reason', v_request->>'recovery_reason',
      'toolchain_evidence_sha256', v_request->>'toolchain_evidence_sha256',
      'recovery_approval_request_sha256',
        v_request->>'recovery_approval_request_sha256',
      'recovery_approval_text_sha256',
        v_request->>'recovery_approval_text_sha256',
      'recovery_approval_identity_sha256',
        v_request->>'recovery_approval_identity_sha256',
      'recovery_wire_request_sha256', v_wire_request_sha256,
      'invocation_id', v_existing.id,
      'maximum_wrapper_invocations', 1,
      'maximum_process_posts',
        (v_request->>'maximum_process_posts')::integer,
      'maximum_finalize_posts', 1,
      'maximum_cli_apply_spawns', 1,
      'approval_reusable', false,
      'automatic_retry', false,
      'hash_algorithm', 'restricted-safe-json-v2-sha256'
    );
    if v_audit_payload is distinct from v_expected_audit_payload then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_RECOVERY_AUDIT_DRIFT', 'status', 409,
        'message', 'Authoritative recovery admission audit drifted'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', 'dataset-flow-identity-scope-recovery-result.v1',
      'scope_id', v_scope.id,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'status', v_audit_payload->>'observed_scope_status',
      'completed_process_count',
        (v_audit_payload->>'observed_completed_process_count')::integer,
      'next_ordinal', (v_audit_payload->>'observed_next_ordinal')::integer,
      'whole_scope_proof_sha256',
        v_existing.baseline_whole_scope_proof_sha256,
      'recovery_wire_request_sha256',
        v_existing.admission_request_sha256,
      'recovery_approval_identity_sha256',
        v_existing.approval_identity_sha256,
      'invocation_id', v_existing.id,
      'audit_id', case when v_audit_id is null then null else v_audit_id::text end,
      'replay', true,
      'execution_permit', null
    );
  end if;

  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing'
    );
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, true
  );
  if coalesce((v_whole_result->>'ok')::boolean, false) is false
    or v_whole_result->>'whole_scope_proof_sha256' is distinct from
      v_request->>'observed_whole_scope_proof_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_LIVE_PROOF_MISMATCH', 'status', 409,
      'message', 'Current whole-scope proof does not match the approval'
    );
  end if;
  select count(*) filter (where ledger.status = 'completed')::integer,
    coalesce(
      min(ledger.ordinal) filter (where ledger.status = 'pending')::integer,
      v_scope.process_count + 1
    )
  into v_completed_count, v_next_ordinal
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  v_remaining_count := v_scope.process_count - v_completed_count;
  v_mode := case when v_remaining_count = 0
    then 'finalize_only' else 'resume_and_finalize' end;
  if v_scope.status is distinct from v_request->>'observed_scope_status'
    or v_completed_count is distinct from
      (v_request->>'observed_completed_process_count')::integer
    or (v_request->>'observed_next_ordinal')::integer <> v_next_ordinal
    or v_mode is distinct from v_request->>'recovery_mode'
    or v_remaining_count is distinct from
      (v_request->>'maximum_process_posts')::integer then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_PROGRESS_MISMATCH', 'status', 409,
      'message', 'Recovery approval does not match current durable progress'
    );
  end if;

  update util.dataset_flow_identity_wrapper_invocations
  set status = 'superseded', generation = generation + 1,
    token_sha256 = private.dataset_flow_identity_permit_token_sha256_v1(
      pg_catalog.encode(extensions.gen_random_bytes(32), 'hex')
    ),
    updated_at = clock_timestamp(), closed_at = clock_timestamp()
  where scope_id = v_scope.id and status = 'active';
  v_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  insert into util.dataset_flow_identity_wrapper_invocations (
    scope_id, actor_user_id, approval_kind,
    approval_request_sha256, approval_text_sha256,
    approval_identity_sha256, admission_request_sha256,
    baseline_whole_scope_proof_sha256,
    token_sha256, maximum_process_posts, maximum_finalize_posts
  ) values (
    v_scope.id, v_actor, 'recovery',
    v_request->>'recovery_approval_request_sha256',
    v_request->>'recovery_approval_text_sha256',
    v_request->>'recovery_approval_identity_sha256',
    v_wire_request_sha256,
    v_request->>'observed_whole_scope_proof_sha256',
    private.dataset_flow_identity_permit_token_sha256_v1(v_token),
    v_remaining_count, 1
  ) returning id into v_invocation_id;
  v_audit_payload := jsonb_build_object(
    'record_type', 'scope_recovery_admission',
    'schema_version', 'dataset-flow-identity-scope-recovery.v1',
    'scope_id', v_scope.id,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'freeze_sha256', v_scope.freeze_sha256,
    'original_execution_approval_identity_sha256',
      v_scope.approval_identity_sha256,
    'observed_whole_scope_proof_sha256',
      v_request->>'observed_whole_scope_proof_sha256',
    'observed_scope_status', v_scope.status,
    'observed_completed_process_count', v_completed_count,
    'observed_next_ordinal', v_next_ordinal,
    'recovery_mode', v_mode,
    'recovery_reason', v_request->>'recovery_reason',
    'toolchain_evidence_sha256', v_request->>'toolchain_evidence_sha256',
    'recovery_approval_request_sha256',
      v_request->>'recovery_approval_request_sha256',
    'recovery_approval_text_sha256',
      v_request->>'recovery_approval_text_sha256',
    'recovery_approval_identity_sha256',
      v_request->>'recovery_approval_identity_sha256',
    'recovery_wire_request_sha256', v_wire_request_sha256,
    'invocation_id', v_invocation_id,
    'maximum_wrapper_invocations', 1,
    'maximum_process_posts', v_remaining_count,
    'maximum_finalize_posts', 1,
    'maximum_cli_apply_spawns', 1,
    'approval_reusable', false,
    'automatic_retry', false,
    'hash_algorithm', 'restricted-safe-json-v2-sha256'
  );
  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    v_command, v_actor, null, null, null, v_audit_payload
  ) returning id into v_audit_id;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-recovery-result.v1',
    'scope_id', v_scope.id,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_scope.status,
    'completed_process_count', v_completed_count,
    'next_ordinal', v_next_ordinal,
    'whole_scope_proof_sha256',
      v_request->>'observed_whole_scope_proof_sha256',
    'recovery_wire_request_sha256', v_wire_request_sha256,
    'recovery_approval_identity_sha256',
      v_request->>'recovery_approval_identity_sha256',
    'invocation_id', v_invocation_id,
    'audit_id', v_audit_id::text,
    'replay', false,
    'execution_permit', jsonb_build_object(
      'schema_version', 'dataset-flow-identity-execution-permit.v1',
      'invocation_id', v_invocation_id,
      'generation', 0,
      'token', v_token
    )
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_RECOVERY_LOCK_BUSY', 'status', 409,
    'message', 'Recovery could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_flow_identity_scope_recover_guarded(p_scope_id uuid, p_request jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_publish(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_publish(p_table text, p_id uuid, p_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_root jsonb;
  v_assertion jsonb;
begin
  if v_actor is null
    or p_table not in ('processes', 'lifecyclemodels') then
    return public.cmd_dataset_publish_issue304_legacy(
      p_table,
      p_id,
      p_version,
      p_audit
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('review-publication-lifecycle-closure', 0)
  );

  v_root := public.cmd_review_get_dataset_row(
    p_table,
    p_id,
    p_version,
    true
  );

  if v_root is null
    or nullif(v_root->>'user_id', '')::uuid is distinct from v_actor
    or coalesce((v_root->>'state_code')::integer, 0) >= 100 then
    return public.cmd_dataset_publish_issue304_legacy(
      p_table,
      p_id,
      p_version,
      p_audit
    );
  end if;

  if p_table = 'processes' then
    lock table public.lifecyclemodels in share row exclusive mode;
  end if;

  v_assertion := public.cmd_review_assert_lifecycle_closure(
    jsonb_build_array(jsonb_build_object(
      'table', p_table,
      'id', p_id,
      'version', p_version
    )),
    'publish',
    v_actor
  );

  if v_assertion is not null then
    return v_assertion;
  end if;

  return public.cmd_dataset_publish_issue304_legacy(
    p_table,
    p_id,
    p_version,
    p_audit
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_publish(p_table text, p_id uuid, p_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_publish_issue304_legacy(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_publish_issue304_legacy(p_table text, p_id uuid, p_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can publish the dataset'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 403,
      'message', 'Dataset is already published',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 403,
      'message', 'Data is under review and cannot be published directly',
      'details', jsonb_build_object(
        'state_code', 20,
        'review_state_code', v_state_code
      )
    );
  end if;

  execute format(
    'update public.%I as t
        set state_code = 100,
            modified_at = now()
      where t.id = $1
        and t.version = $2
    returning to_jsonb(t)',
    p_table
  )
    into v_updated_row
    using p_id, p_version;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_publish',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_publish_issue304_legacy(p_table text, p_id uuid, p_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_gate(text, uuid, text, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_gate(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text DEFAULT 'review_submit_fast.v1'::text, p_report_schema_version text DEFAULT 'review_submit_gate_report.v1'::text, p_action text DEFAULT 'ensure'::text, p_gate_run_id uuid DEFAULT NULL::uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_dataset_row jsonb;
  v_owner_id uuid;
  v_action text := lower(trim(coalesce(p_action, 'ensure')));
  v_run public.dataset_review_submit_gate_runs%rowtype;
  v_existing public.dataset_review_submit_gate_runs%rowtype;
  v_supersedes uuid;
  v_link_result jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in ('processes', 'lifecyclemodels') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table for review-submit gate'
    );
  end if;

  if coalesce(p_revision_checksum, '') !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVISION_CHECKSUM_REQUIRED',
      'status', 400,
      'message', 'revisionChecksum must be a lowercase SHA-256 hex digest'
    );
  end if;

  if coalesce(p_policy_profile, '') <> 'review_submit_fast.v1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_POLICY_UNSUPPORTED',
      'status', 400,
      'message', 'Unsupported review-submit gate policy profile',
      'details', jsonb_build_object('policy_profile', p_policy_profile)
    );
  end if;

  if coalesce(p_report_schema_version, '') <> 'review_submit_gate_report.v1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_SCHEMA_UNSUPPORTED',
      'status', 400,
      'message', 'Unsupported review-submit gate report schema version',
      'details', jsonb_build_object('report_schema_version', p_report_schema_version)
    );
  end if;

  if v_action not in ('ensure', 'read', 'rerun') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_GATE_ACTION',
      'status', 400,
      'message', 'action must be ensure, read, or rerun'
    );
  end if;

  v_dataset_row := public.cmd_review_get_dataset_row(p_table, p_id, p_version, false);

  if v_dataset_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_dataset_row->>'user_id', '')::uuid;

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can run or read the review-submit gate'
    );
  end if;

  if p_gate_run_id is not null then
    select *
      into v_existing
    from public.dataset_review_submit_gate_runs
    where id = p_gate_run_id
    for update;

    if v_existing.id is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
        'status', 404,
        'message', 'Review-submit gate run not found'
      );
    end if;

    if v_existing.dataset_table <> p_table
      or v_existing.dataset_id <> p_id
      or v_existing.dataset_version <> p_version then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_DATASET_MISMATCH',
        'status', 409,
        'message', 'Review-submit gate run belongs to a different dataset revision'
      );
    end if;

    if v_action = 'read' then
      return jsonb_build_object(
        'ok', true,
        'data', public.cmd_dataset_review_submit_gate_payload(
          v_existing,
          case
            when v_existing.revision_checksum <> p_revision_checksum then 'stale'
            else null
          end
        )
      );
    end if;

    if v_action = 'ensure' and v_existing.revision_checksum = p_revision_checksum then
      return public.cmd_dataset_review_submit_gate_link_worker_job(v_existing.id, 'ensure');
    end if;

    v_supersedes := v_existing.id;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(
        ':',
        'review_submit_gate',
        p_table,
        p_id::text,
        p_version,
        p_revision_checksum,
        p_policy_profile,
        p_report_schema_version,
        v_actor::text
      ),
      0
    )
  );

  if v_action in ('ensure', 'read') and p_gate_run_id is null then
    select *
      into v_run
    from public.dataset_review_submit_gate_runs
    where dataset_table = p_table
      and dataset_id = p_id
      and dataset_version = p_version
      and revision_checksum = p_revision_checksum
      and policy_profile = p_policy_profile
      and report_schema_version = p_report_schema_version
      and requested_by = v_actor
    order by created_at desc
    limit 1
    for update;

    if v_run.id is not null then
      if v_action = 'ensure' then
        return public.cmd_dataset_review_submit_gate_link_worker_job(v_run.id, 'ensure');
      end if;

      return jsonb_build_object(
        'ok', true,
        'data', public.cmd_dataset_review_submit_gate_payload(v_run)
      );
    end if;

    if v_action = 'read' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
        'status', 404,
        'message', 'Review-submit gate run not found'
      );
    end if;
  end if;

  if v_action = 'rerun' and p_gate_run_id is null then
    select id
      into v_supersedes
    from public.dataset_review_submit_gate_runs
    where dataset_table = p_table
      and dataset_id = p_id
      and dataset_version = p_version
      and policy_profile = p_policy_profile
      and report_schema_version = p_report_schema_version
      and requested_by = v_actor
    order by created_at desc
    limit 1;
  end if;

  insert into public.dataset_review_submit_gate_runs (
    dataset_table,
    dataset_id,
    dataset_version,
    revision_checksum,
    policy_profile,
    report_schema_version,
    status,
    requested_by,
    supersedes_gate_run_id
  )
  values (
    p_table,
    p_id,
    p_version,
    p_revision_checksum,
    p_policy_profile,
    p_report_schema_version,
    'queued',
    v_actor,
    v_supersedes
  )
  returning *
    into v_run;

  v_link_result := public.cmd_dataset_review_submit_gate_link_worker_job(v_run.id, v_action);

  if coalesce((v_link_result->>'ok')::boolean, false) is false then
    return v_link_result;
  end if;

  select *
    into v_run
  from public.dataset_review_submit_gate_runs
  where id = v_run.id;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_review_submit_gate',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'action', v_action,
      'gate_run_id', v_run.id,
      'worker_job_id', v_run.worker_job_id,
      'revision_checksum', p_revision_checksum,
      'policy_profile', p_policy_profile,
      'report_schema_version', p_report_schema_version,
      'supersedes_gate_run_id', v_supersedes
    )
  );

  return v_link_result;
end;
$_$;


ALTER FUNCTION public.cmd_dataset_review_submit_gate(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text, p_report_schema_version text, p_action text, p_gate_run_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_review_submit_gate(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text, p_report_schema_version text, p_action text, p_gate_run_id uuid, p_audit jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_review_submit_gate(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text, p_report_schema_version text, p_action text, p_gate_run_id uuid, p_audit jsonb) IS 'User-facing review-submit gate RPC. Standalone ensure/rerun now creates or reuses review_submit.gate worker_jobs and links them to retained gate history rows.';


--
-- Name: cmd_dataset_review_submit_gate_enqueue_worker_job(text, uuid, text, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_gate_enqueue_worker_job(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text, p_report_schema_version text, p_requested_by uuid, p_gate_run_id uuid DEFAULT NULL::uuid, p_action text DEFAULT 'ensure'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_action text := lower(trim(coalesce(p_action, 'ensure')));
  v_kind public.worker_job_kinds%rowtype;
  v_worker_existing public.worker_jobs%rowtype;
  v_worker_job public.worker_jobs%rowtype;
  v_worker_payload jsonb;
  v_idempotency_key text;
  v_concurrency_key text;
begin
  if p_requested_by is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_REQUESTED_BY_REQUIRED',
      'status', 400,
      'message', 'requestedBy is required for review-submit gate worker jobs'
    );
  end if;

  select *
    into v_kind
  from public.worker_job_kinds
  where job_kind = 'review_submit.gate';

  if v_kind.job_kind is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_KIND_UNSUPPORTED',
      'status', 500,
      'message', 'review_submit.gate worker job kind is not registered'
    );
  end if;

  v_worker_payload := jsonb_strip_nulls(
    jsonb_build_object(
      'datasetRevision', jsonb_build_object(
        'table', p_table,
        'id', p_id,
        'version', p_version,
        'revisionChecksum', p_revision_checksum
      ),
      'policy', jsonb_build_object(
        'profile', p_policy_profile,
        'reportSchemaVersion', p_report_schema_version
      ),
      'requestedBy', p_requested_by,
      'gateRunId', p_gate_run_id
    )
  );

  v_idempotency_key := case
    when v_action = 'rerun' and p_gate_run_id is not null then concat_ws(
      ':',
      'review_submit.gate.rerun',
      p_gate_run_id::text
    )
    else concat_ws(
      ':',
      'review_submit.gate',
      p_table,
      p_id::text,
      p_version,
      p_revision_checksum,
      p_policy_profile,
      p_report_schema_version,
      p_requested_by::text
    )
  end;

  v_concurrency_key := concat_ws(
    ':',
    'review_submit.gate',
    p_table,
    p_id::text,
    p_version,
    p_requested_by::text
  );

  if v_action = 'rerun' then
    select *
      into v_worker_existing
    from public.worker_jobs
    where worker_runtime = v_kind.worker_runtime
      and job_kind = v_kind.job_kind
      and requested_by is not distinct from p_requested_by
      and idempotency_key = v_idempotency_key
      and status in ('queued', 'running', 'waiting', 'stale')
    order by created_at desc
    limit 1
    for update;
  else
    select *
      into v_worker_existing
    from public.worker_jobs
    where worker_runtime = v_kind.worker_runtime
      and job_kind = v_kind.job_kind
      and requested_by is not distinct from p_requested_by
      and idempotency_key = v_idempotency_key
      and status in ('queued', 'running', 'waiting', 'stale', 'blocked', 'completed')
    order by created_at desc
    limit 1
    for update;
  end if;

  if v_worker_existing.id is not null then
    return jsonb_build_object(
      'ok', true,
      'data', public.worker_job_payload(v_worker_existing, true),
      'reused', true
    );
  end if;

  select *
    into v_worker_existing
  from public.worker_jobs
  where worker_runtime = v_kind.worker_runtime
    and worker_queue = v_kind.worker_queue
    and concurrency_key = v_concurrency_key
    and status in ('queued', 'running', 'waiting', 'stale')
  order by created_at desc
  limit 1
  for update;

  if v_worker_existing.id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_CONCURRENCY_CONFLICT',
      'status', 409,
      'message', 'A conflicting review-submit gate job is already active',
      'details', public.worker_job_payload(v_worker_existing, false)
    );
  end if;

  insert into public.worker_jobs (
    job_kind,
    worker_runtime,
    worker_queue,
    priority,
    subject_type,
    subject_id,
    subject_version,
    requester_type,
    requested_by,
    idempotency_key,
    concurrency_key,
    visibility,
    max_attempts,
    payload_schema_version,
    payload_json,
    result_schema_version
  ) values (
    v_kind.job_kind,
    v_kind.worker_runtime,
    v_kind.worker_queue,
    v_kind.default_priority,
    p_table,
    p_id,
    p_version,
    'user',
    p_requested_by,
    v_idempotency_key,
    v_concurrency_key,
    v_kind.default_visibility,
    greatest(1, coalesce(v_kind.default_max_attempts, 3)),
    v_kind.payload_schema_version,
    v_worker_payload,
    v_kind.result_schema_version
  )
  returning *
    into v_worker_job;

  insert into public.worker_job_events (
    job_id,
    event_type,
    status,
    details
  ) values (
    v_worker_job.id,
    'enqueued',
    v_worker_job.status,
    jsonb_build_object(
      'jobKind', v_worker_job.job_kind,
      'workerQueue', v_worker_job.worker_queue,
      'idempotencyKey', v_worker_job.idempotency_key,
      'concurrencyKey', v_worker_job.concurrency_key,
      'gateRunId', p_gate_run_id,
      'source', 'cmd_dataset_review_submit_gate'
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_worker_job, true),
    'reused', false
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_gate_enqueue_worker_job(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text, p_report_schema_version text, p_requested_by uuid, p_gate_run_id uuid, p_action text) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_gate_link_worker_job(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_gate_link_worker_job(p_gate_run_id uuid, p_action text DEFAULT 'ensure'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_run public.dataset_review_submit_gate_runs%rowtype;
  v_worker_result jsonb;
  v_worker_job public.worker_jobs%rowtype;
  v_worker_job_id uuid;
  v_status text;
  v_calculator_report jsonb;
  v_blocking_reasons jsonb;
begin
  select *
    into v_run
  from public.dataset_review_submit_gate_runs
  where id = p_gate_run_id
  for update;

  if v_run.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
      'status', 404,
      'message', 'Review-submit gate run not found'
    );
  end if;

  if v_run.worker_job_id is null and v_run.status in ('queued', 'running') then
    v_worker_result := public.cmd_dataset_review_submit_gate_enqueue_worker_job(
      v_run.dataset_table,
      v_run.dataset_id,
      v_run.dataset_version,
      v_run.revision_checksum,
      v_run.policy_profile,
      v_run.report_schema_version,
      v_run.requested_by,
      v_run.id,
      p_action
    );

    if coalesce((v_worker_result->>'ok')::boolean, false) is false then
      return v_worker_result;
    end if;

    v_worker_job_id := nullif(v_worker_result->'data'->>'id', '')::uuid;

    select *
      into v_worker_job
    from public.worker_jobs
    where id = v_worker_job_id;

    v_status := case
      when v_worker_job.status in ('queued', 'waiting', 'stale') then 'queued'
      when v_worker_job.status = 'running' then 'running'
      when v_worker_job.status = 'blocked' then 'blocked'
      when v_worker_job.status = 'completed'
        and coalesce(v_worker_job.result_json->>'status', '') = 'passed'
        then 'passed'
      when v_worker_job.status = 'completed'
        and coalesce(v_worker_job.result_json->>'status', '') = 'blocked'
        then 'blocked'
      when v_worker_job.status in ('completed', 'failed', 'cancelled') then 'error'
      else v_run.status
    end;

    v_calculator_report := case
      when jsonb_typeof(v_worker_job.result_json->'calculatorReport') = 'object'
        then v_worker_job.result_json->'calculatorReport'
      else v_run.calculator_report
    end;

    v_blocking_reasons := coalesce(
      case
        when jsonb_typeof(v_worker_job.result_json->'blockingReasons') = 'array'
          then v_worker_job.result_json->'blockingReasons'
        else null::jsonb
      end,
      v_run.blocking_reasons,
      '[]'::jsonb
    );

    update public.dataset_review_submit_gate_runs
      set worker_job_id = v_worker_job.id,
          status = v_status,
          calculator_report = v_calculator_report,
          blocking_reasons = v_blocking_reasons,
          modified_at = now(),
          completed_at = case
            when v_status in ('passed', 'blocked', 'error') then coalesce(v_worker_job.finished_at, now())
            else completed_at
          end
    where id = v_run.id
    returning *
      into v_run;
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', public.cmd_dataset_review_submit_gate_payload(v_run)
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_gate_link_worker_job(p_gate_run_id uuid, p_action text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: dataset_review_submit_gate_runs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dataset_review_submit_gate_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    dataset_table text NOT NULL,
    dataset_id uuid NOT NULL,
    dataset_version text NOT NULL,
    revision_checksum text NOT NULL,
    policy_profile text DEFAULT 'review_submit_fast.v1'::text NOT NULL,
    report_schema_version text DEFAULT 'review_submit_gate_report.v1'::text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    requested_by uuid NOT NULL,
    supersedes_gate_run_id uuid,
    calculator_report jsonb,
    blocking_reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    modified_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    worker_job_id uuid,
    CONSTRAINT dataset_review_submit_gate_runs_blocking_reasons_check CHECK ((jsonb_typeof(blocking_reasons) = 'array'::text)),
    CONSTRAINT dataset_review_submit_gate_runs_calculator_report_check CHECK (((calculator_report IS NULL) OR (jsonb_typeof(calculator_report) = 'object'::text))),
    CONSTRAINT dataset_review_submit_gate_runs_checksum_check CHECK ((revision_checksum ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT dataset_review_submit_gate_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'passed'::text, 'blocked'::text, 'error'::text, 'stale'::text]))),
    CONSTRAINT dataset_review_submit_gate_runs_table_check CHECK ((dataset_table = ANY (ARRAY['processes'::text, 'lifecyclemodels'::text])))
);


ALTER TABLE public.dataset_review_submit_gate_runs OWNER TO postgres;

--
-- Name: TABLE dataset_review_submit_gate_runs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dataset_review_submit_gate_runs IS 'Review-submit gate report/history table. This is retained domain report state; canonical gate execution lifecycle is public.worker_jobs.';


--
-- Name: COLUMN dataset_review_submit_gate_runs.worker_job_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.dataset_review_submit_gate_runs.worker_job_id IS 'Canonical review_submit.gate worker_jobs execution that produced or owns this retained gate report row.';


--
-- Name: cmd_dataset_review_submit_gate_payload(public.dataset_review_submit_gate_runs, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_gate_payload(p_run public.dataset_review_submit_gate_runs, p_status_override text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with worker as (
    select w.*
    from public.worker_jobs as w
    where w.id = (p_run).worker_job_id
    limit 1
  ),
  shaped as (
    select
      worker.id as worker_job_id,
      case
        when p_status_override is not null then p_status_override
        when worker.id is null then (p_run).status
        when worker.status in ('queued', 'waiting', 'stale') then 'queued'
        when worker.status = 'running' then 'running'
        when worker.status = 'blocked' then 'blocked'
        when worker.status = 'completed'
          and coalesce(worker.result_json->>'status', '') = 'passed'
          then 'passed'
        when worker.status = 'completed'
          and coalesce(worker.result_json->>'status', '') = 'blocked'
          then 'blocked'
        when worker.status in ('completed', 'failed', 'cancelled') then 'error'
        else (p_run).status
      end as effective_status,
      case
        when (p_run).calculator_report is not null then
          jsonb_build_object(
            'schemaVersion',
            coalesce((p_run).report_schema_version, worker.result_schema_version)
          ) || (p_run).calculator_report
        when worker.id is not null
          and jsonb_typeof(worker.result_json->'calculatorReport') = 'object'
          then jsonb_build_object(
            'schemaVersion',
            coalesce(
              worker.result_json #>> '{calculatorReport,schemaVersion}',
              (p_run).report_schema_version,
              worker.result_schema_version
            )
          ) || (worker.result_json->'calculatorReport')
        else null::jsonb
      end as effective_calculator_report,
      coalesce(
        case
          when jsonb_typeof(worker.result_json->'blockingReasons') = 'array'
            then worker.result_json->'blockingReasons'
          else null::jsonb
        end,
        case
          when cardinality(worker.blocker_codes) > 0 then (
            select jsonb_agg(jsonb_build_object('code', code) order by code)
            from unnest(worker.blocker_codes) as code
          )
          else null::jsonb
        end,
        (p_run).blocking_reasons,
        '[]'::jsonb
      ) as effective_blocking_reasons,
      greatest(
        (p_run).modified_at,
        coalesce(worker.updated_at, (p_run).modified_at)
      ) as effective_modified_at,
      coalesce(
        (p_run).completed_at,
        case
          when worker.status in ('completed', 'blocked', 'failed', 'cancelled')
            then worker.finished_at
          else null::timestamptz
        end
      ) as effective_completed_at
    from (select 1) as seed
    left join worker on true
  )
  select jsonb_strip_nulls(
    jsonb_build_object(
      'status', shaped.effective_status,
      'gateRunId', (p_run).id,
      'workerJobId', shaped.worker_job_id,
      'workerJob',
        case
          when shaped.worker_job_id is null then null
          else (
            select public.worker_job_payload(worker, false)
            from worker
          )
        end,
      'datasetRevision', jsonb_build_object(
        'table', (p_run).dataset_table,
        'id', (p_run).dataset_id,
        'version', (p_run).dataset_version,
        'revisionChecksum', (p_run).revision_checksum
      ),
      'policy', jsonb_build_object(
        'profile', (p_run).policy_profile,
        'reportSchemaVersion', (p_run).report_schema_version
      ),
      'calculatorReport', shaped.effective_calculator_report,
      'blockingReasons', shaped.effective_blocking_reasons,
      'createdAt', to_jsonb((p_run).created_at),
      'modifiedAt', to_jsonb(shaped.effective_modified_at),
      'completedAt', to_jsonb(shaped.effective_completed_at)
    )
  )
  from shaped
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_gate_payload(p_run public.dataset_review_submit_gate_runs, p_status_override text) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_gate_record_result(uuid, text, jsonb, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_gate_record_result(p_gate_run_id uuid, p_status text, p_calculator_report jsonb DEFAULT NULL::jsonb, p_blocking_reasons jsonb DEFAULT '[]'::jsonb, p_report_schema_version text DEFAULT 'review_submit_gate_report.v1'::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_status text := lower(trim(coalesce(p_status, '')));
  v_run public.dataset_review_submit_gate_runs%rowtype;
  v_worker_status text;
  v_worker_result jsonb;
  v_blocker_codes text[];
begin
  if v_status not in ('passed', 'blocked', 'error') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_GATE_RESULT_STATUS',
      'status', 400,
      'message', 'result status must be passed, blocked, or error'
    );
  end if;

  if coalesce(p_report_schema_version, '') <> 'review_submit_gate_report.v1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_SCHEMA_UNSUPPORTED',
      'status', 400,
      'message', 'Unsupported review-submit gate report schema version',
      'details', jsonb_build_object('report_schema_version', p_report_schema_version)
    );
  end if;

  if p_calculator_report is not null and jsonb_typeof(p_calculator_report) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_GATE_REPORT',
      'status', 400,
      'message', 'calculator report must be a JSON object'
    );
  end if;

  if jsonb_typeof(coalesce(p_blocking_reasons, '[]'::jsonb)) <> 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_GATE_BLOCKING_REASONS',
      'status', 400,
      'message', 'blockingReasons must be a JSON array'
    );
  end if;

  if v_status = 'passed' and jsonb_array_length(coalesce(p_blocking_reasons, '[]'::jsonb)) > 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_GATE_RESULT',
      'status', 400,
      'message', 'passed gate results cannot include blockingReasons'
    );
  end if;

  select *
    into v_run
  from public.dataset_review_submit_gate_runs
  where id = p_gate_run_id
  for update;

  if v_run.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
      'status', 404,
      'message', 'Review-submit gate run not found'
    );
  end if;

  update public.dataset_review_submit_gate_runs
    set status = v_status,
        calculator_report = p_calculator_report,
        blocking_reasons = coalesce(p_blocking_reasons, '[]'::jsonb),
        report_schema_version = p_report_schema_version,
        modified_at = now(),
        completed_at = now()
  where id = p_gate_run_id
  returning *
    into v_run;

  if v_run.worker_job_id is not null then
    v_worker_status := case
      when v_status = 'passed' then 'completed'
      when v_status = 'blocked' then 'blocked'
      else 'failed'
    end;

    select coalesce(
      array_agg(distinct nullif(reason->>'code', '')) filter (where nullif(reason->>'code', '') is not null),
      '{}'::text[]
    )
      into v_blocker_codes
    from jsonb_array_elements(coalesce(p_blocking_reasons, '[]'::jsonb)) as reason;

    if v_worker_status = 'blocked' and cardinality(v_blocker_codes) = 0 then
      v_blocker_codes := array['review_submit_gate_blocked'];
    end if;

    v_worker_result := jsonb_strip_nulls(
      jsonb_build_object(
        'status', v_status,
        'datasetRevision', jsonb_build_object(
          'table', v_run.dataset_table,
          'id', v_run.dataset_id,
          'version', v_run.dataset_version,
          'revisionChecksum', v_run.revision_checksum
        ),
        'policy', jsonb_build_object(
          'profile', v_run.policy_profile,
          'reportSchemaVersion', p_report_schema_version
        ),
        'calculatorReport', p_calculator_report,
        'blockingReasons', coalesce(p_blocking_reasons, '[]'::jsonb),
        'gateRunId', v_run.id,
        'recordedBy', 'cmd_dataset_review_submit_gate_record_result'
      )
    );

    update public.worker_jobs
      set status = v_worker_status,
          result_json = case
            when v_worker_status in ('completed', 'blocked') then v_worker_result
            else result_json
          end,
          result_schema_version = coalesce(result_schema_version, 'review_submit.gate.result.v1'),
          error_code = case
            when v_worker_status = 'failed' then 'REVIEW_SUBMIT_GATE_ERROR'
            else null
          end,
          error_message = case
            when v_worker_status = 'failed' then 'Review-submit gate failed before review submission'
            else null
          end,
          blocker_codes = case
            when v_worker_status = 'blocked' then v_blocker_codes
            else '{}'::text[]
          end,
          resolution_scope = case
            when v_worker_status = 'blocked' then 'user'
            else null
          end,
          retryable = case
            when v_worker_status = 'failed' then true
            when v_worker_status in ('completed', 'blocked') then false
            else retryable
          end,
          updated_at = now(),
          finished_at = now()
    where id = v_run.worker_job_id;

    insert into public.worker_job_events (
      job_id,
      event_type,
      status,
      details
    ) values (
      v_run.worker_job_id,
      'legacy_gate_result_recorded',
      v_worker_status,
      jsonb_build_object(
        'gateRunId', v_run.id,
        'gateStatus', v_status,
        'source', 'cmd_dataset_review_submit_gate_record_result'
      )
    );
  end if;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_review_submit_gate_record_result',
    coalesce(v_actor, v_run.requested_by),
    v_run.dataset_table,
    v_run.dataset_id,
    v_run.dataset_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'gate_run_id', v_run.id,
      'worker_job_id', v_run.worker_job_id,
      'status', v_status,
      'report_schema_version', p_report_schema_version
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.cmd_dataset_review_submit_gate_payload(v_run)
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_gate_record_result(p_gate_run_id uuid, p_status text, p_calculator_report jsonb, p_blocking_reasons jsonb, p_report_schema_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_job_claim(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_job_claim(p_qty integer DEFAULT 10, p_stale_submitting_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_qty integer := greatest(1, least(coalesce(p_qty, 10), 50));
  v_stale_seconds integer := greatest(30, coalesce(p_stale_submitting_seconds, 300));
  v_jobs jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to claim review-submit jobs'
    );
  end if;

  with claimed as (
    select id
    from public.dataset_review_submit_requests
    where status in ('queued', 'waiting_gate')
      or (
        status = 'submitting'
        and modified_at < now() - make_interval(secs => v_stale_seconds)
      )
    order by
      case status
        when 'queued' then 0
        when 'waiting_gate' then 1
        else 2
      end,
      created_at asc
    for update skip locked
    limit v_qty
  ),
  updated as (
    update public.dataset_review_submit_requests as request
      set status = 'submitting',
          attempt_count = request.attempt_count + 1,
          modified_at = now()
    from claimed
    where request.id = claimed.id
    returning request.*
  )
  select coalesce(jsonb_agg(public.cmd_dataset_review_submit_job_payload(updated)), '[]'::jsonb)
    into v_jobs
  from updated;

  return jsonb_build_object(
    'ok', true,
    'data', v_jobs
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_job_claim(p_qty integer, p_stale_submitting_seconds integer) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_job_enqueue(text, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_job_enqueue(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text DEFAULT 'review_submit_fast.v1'::text, p_report_schema_version text DEFAULT 'review_submit_gate_report.v1'::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_dataset_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_kind public.worker_job_kinds%rowtype;
  v_worker_existing public.worker_jobs%rowtype;
  v_worker_job public.worker_jobs%rowtype;
  v_worker_payload jsonb;
  v_idempotency_key text;
  v_concurrency_key text;
  v_worker_status text;
  v_job_status text := 'waiting_gate';
  v_last_error_code text;
  v_last_error_message text;
  v_last_error_details jsonb;
  v_completed_at timestamptz;
  v_existing public.dataset_review_submit_requests%rowtype;
  v_job public.dataset_review_submit_requests%rowtype;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table <> 'processes' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Review-submit jobs currently support process datasets only'
    );
  end if;

  if coalesce(p_revision_checksum, '') !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVISION_CHECKSUM_REQUIRED',
      'status', 400,
      'message', 'revisionChecksum must be a lowercase SHA-256 hex digest'
    );
  end if;

  if coalesce(p_policy_profile, '') <> 'review_submit_fast.v1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_POLICY_UNSUPPORTED',
      'status', 400,
      'message', 'Unsupported review-submit gate policy profile',
      'details', jsonb_build_object('policy_profile', p_policy_profile)
    );
  end if;

  if coalesce(p_report_schema_version, '') <> 'review_submit_gate_report.v1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_GATE_SCHEMA_UNSUPPORTED',
      'status', 400,
      'message', 'Unsupported review-submit gate report schema version',
      'details', jsonb_build_object('report_schema_version', p_report_schema_version)
    );
  end if;

  v_dataset_row := public.cmd_review_get_dataset_row(p_table, p_id, p_version, false);

  if v_dataset_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_dataset_row->>'user_id', '')::uuid;
  v_state_code := coalesce(nullif(v_dataset_row->>'state_code', '')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can enqueue review submission'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 409,
      'message', 'Published datasets cannot be submitted for review again'
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 409,
      'message', 'Dataset is already under review'
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(
        ':',
        'review_submit_request',
        p_table,
        p_id::text,
        p_version,
        p_revision_checksum,
        p_policy_profile,
        p_report_schema_version,
        v_actor::text
      ),
      0
    )
  );

  select *
    into v_existing
  from public.dataset_review_submit_requests
  where dataset_table = p_table
    and dataset_id = p_id
    and dataset_version = p_version
    and revision_checksum = p_revision_checksum
    and policy_profile = p_policy_profile
    and report_schema_version = p_report_schema_version
    and requested_by = v_actor
    and status in ('queued', 'waiting_gate', 'submitting', 'submitted')
  order by created_at desc
  limit 1
  for update;

  if v_existing.id is not null then
    return jsonb_build_object(
      'ok', true,
      'data', public.cmd_dataset_review_submit_job_payload(v_existing)
    );
  end if;

  select *
    into v_kind
  from public.worker_job_kinds
  where job_kind = 'review_submit.gate';

  if v_kind.job_kind is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_KIND_UNSUPPORTED',
      'status', 500,
      'message', 'review_submit.gate worker job kind is not registered'
    );
  end if;

  v_worker_payload := jsonb_build_object(
    'datasetRevision', jsonb_build_object(
      'table', p_table,
      'id', p_id,
      'version', p_version,
      'revisionChecksum', p_revision_checksum
    ),
    'policy', jsonb_build_object(
      'profile', p_policy_profile,
      'reportSchemaVersion', p_report_schema_version
    ),
    'requestedBy', v_actor
  );
  v_idempotency_key := concat_ws(
    ':',
    'review_submit.gate',
    p_table,
    p_id::text,
    p_version,
    p_revision_checksum,
    p_policy_profile,
    p_report_schema_version,
    v_actor::text
  );
  v_concurrency_key := concat_ws(
    ':',
    'review_submit.gate',
    p_table,
    p_id::text,
    p_version,
    v_actor::text
  );

  select *
    into v_worker_existing
  from public.worker_jobs
  where worker_runtime = 'calculator'
    and job_kind = 'review_submit.gate'
    and requested_by is not distinct from v_actor
    and idempotency_key = v_idempotency_key
    and status in ('queued', 'running', 'waiting', 'stale', 'blocked')
  order by created_at desc
  limit 1
  for update;

  if v_worker_existing.id is not null then
    v_worker_job := v_worker_existing;
  else
    select *
      into v_worker_existing
    from public.worker_jobs
    where worker_runtime = 'calculator'
      and worker_queue = 'review_submit_gate'
      and concurrency_key = v_concurrency_key
      and status in ('queued', 'running', 'waiting', 'stale')
    order by created_at desc
    limit 1
    for update;

    if v_worker_existing.id is not null then
      return jsonb_build_object(
        'ok', false,
        'code', 'WORKER_JOB_CONCURRENCY_CONFLICT',
        'status', 409,
        'message', 'A conflicting review-submit gate job is already active',
        'details', public.worker_job_payload(v_worker_existing, false)
      );
    end if;

    insert into public.worker_jobs (
      job_kind,
      worker_runtime,
      worker_queue,
      priority,
      subject_type,
      subject_id,
      subject_version,
      requester_type,
      requested_by,
      idempotency_key,
      concurrency_key,
      visibility,
      max_attempts,
      payload_schema_version,
      payload_json,
      result_schema_version
    ) values (
      v_kind.job_kind,
      v_kind.worker_runtime,
      v_kind.worker_queue,
      v_kind.default_priority,
      p_table,
      p_id,
      p_version,
      'user',
      v_actor,
      v_idempotency_key,
      v_concurrency_key,
      v_kind.default_visibility,
      v_kind.default_max_attempts,
      v_kind.payload_schema_version,
      v_worker_payload,
      v_kind.result_schema_version
    )
    returning *
      into v_worker_job;

    insert into public.worker_job_events (
      job_id,
      event_type,
      status,
      details
    ) values (
      v_worker_job.id,
      'enqueued',
      v_worker_job.status,
      jsonb_build_object(
        'jobKind', v_worker_job.job_kind,
        'workerQueue', v_worker_job.worker_queue,
        'idempotencyKey', v_worker_job.idempotency_key,
        'concurrencyKey', v_worker_job.concurrency_key,
        'source', 'cmd_dataset_review_submit_job_enqueue'
      )
    );
  end if;

  v_worker_status := v_worker_job.status;
  v_job_status := case
    when v_worker_status = 'completed' then 'queued'
    when v_worker_status in ('queued', 'running', 'waiting', 'stale') then 'waiting_gate'
    when v_worker_status = 'blocked' then 'blocked'
    when v_worker_status = 'cancelled' then 'cancelled'
    else 'error'
  end;

  if v_job_status = 'blocked' then
    v_last_error_code := 'REVIEW_SUBMIT_GATE_BLOCKED';
    v_last_error_message := 'Review-submit gate blocked this dataset revision';
    v_last_error_details := public.worker_job_payload(v_worker_job, false);
  elsif v_job_status = 'stale' then
    v_last_error_code := 'REVIEW_SUBMIT_GATE_STALE';
    v_last_error_message := 'Review-submit gate run is stale for the submitted dataset revision';
    v_last_error_details := public.worker_job_payload(v_worker_job, false);
  elsif v_job_status = 'error' then
    v_last_error_code := coalesce(v_worker_job.error_code, 'REVIEW_SUBMIT_GATE_ERROR');
    v_last_error_message := coalesce(v_worker_job.error_message, 'Review-submit gate failed before review submission');
    v_last_error_details := public.worker_job_payload(v_worker_job, false);
  elsif v_job_status = 'cancelled' then
    v_last_error_code := 'REVIEW_SUBMIT_JOB_CANCELLED';
    v_last_error_message := 'Review-submit job was cancelled';
    v_last_error_details := public.worker_job_payload(v_worker_job, false);
  end if;

  if v_job_status in ('submitted', 'blocked', 'stale', 'error', 'cancelled') then
    v_completed_at := now();
  end if;

  insert into public.dataset_review_submit_requests (
    dataset_table,
    dataset_id,
    dataset_version,
    revision_checksum,
    policy_profile,
    report_schema_version,
    status,
    requested_by,
    gate_worker_job_id,
    last_error_code,
    last_error_message,
    last_error_details,
    completed_at
  )
  values (
    p_table,
    p_id,
    p_version,
    p_revision_checksum,
    p_policy_profile,
    p_report_schema_version,
    v_job_status,
    v_actor,
    v_worker_job.id,
    v_last_error_code,
    v_last_error_message,
    v_last_error_details,
    v_completed_at
  )
  returning *
    into v_job;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_review_submit_job_enqueue',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'review_submit_job_id', v_job.id,
      'review_submit_request_id', v_job.id,
      'gate_worker_job_id', v_worker_job.id,
      'gate_worker_job_status', v_worker_status,
      'revision_checksum', p_revision_checksum,
      'policy_profile', p_policy_profile,
      'report_schema_version', p_report_schema_version
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.cmd_dataset_review_submit_job_payload(v_job)
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_review_submit_job_enqueue(p_table text, p_id uuid, p_version text, p_revision_checksum text, p_policy_profile text, p_report_schema_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_job_payload(anyelement); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_job_payload(p_job anyelement) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with job as (
    select to_jsonb(p_job) as row_json
  )
  select jsonb_strip_nulls(
    jsonb_build_object(
      'status', row_json->>'status',
      'reviewSubmitJobId', row_json->'id',
      'submitWorkerJobId', row_json->'submit_worker_job_id',
      'gateRunId', row_json->'gate_run_id',
      'gateWorkerJobId', row_json->'gate_worker_job_id',
      'datasetRevision', jsonb_build_object(
        'table', row_json->>'dataset_table',
        'id', row_json->'dataset_id',
        'version', row_json->>'dataset_version',
        'revisionChecksum', row_json->>'revision_checksum'
      ),
      'policy', jsonb_build_object(
        'profile', row_json->>'policy_profile',
        'reportSchemaVersion', row_json->>'report_schema_version'
      ),
      'requestedBy', row_json->'requested_by',
      'attemptCount', row_json->'attempt_count',
      'error',
        case
          when row_json->>'last_error_code' is null
            and row_json->>'last_error_message' is null
            and row_json->'last_error_details' is null then null
          else jsonb_strip_nulls(
            jsonb_build_object(
              'code', row_json->>'last_error_code',
              'message', row_json->>'last_error_message',
              'details', row_json->'last_error_details'
            )
          )
        end,
      'result', row_json->'result',
      'submitWorkerJob',
        (
          select public.worker_job_payload(w, false)
          from public.worker_jobs as w
          where w.id = nullif(row_json->>'submit_worker_job_id', '')::uuid
        ),
      'gate',
        (
          select public.cmd_dataset_review_submit_gate_payload(g)
          from public.dataset_review_submit_gate_runs as g
          where g.id = nullif(row_json->>'gate_run_id', '')::uuid
        ),
      'gateWorkerJob',
        (
          select public.worker_job_payload(w, false)
          from public.worker_jobs as w
          where w.id = nullif(row_json->>'gate_worker_job_id', '')::uuid
        ),
      'createdAt', row_json->'created_at',
      'modifiedAt', row_json->'modified_at',
      'completedAt', row_json->'completed_at'
    )
  )
  from job
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_job_payload(p_job anyelement) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_job_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_job_read(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_is_service boolean := coalesce(util.is_service_request(), false);
  v_job public.dataset_review_submit_requests%rowtype;
begin
  if p_job_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_JOB_ID_REQUIRED',
      'status', 400,
      'message', 'reviewSubmitJobId is required'
    );
  end if;

  if v_actor is null and not v_is_service then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  select *
    into v_job
  from public.dataset_review_submit_requests
  where id = p_job_id;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Review-submit job not found'
    );
  end if;

  if not v_is_service and v_job.requested_by is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the job requester can read this review-submit job'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', public.cmd_dataset_review_submit_job_payload(v_job)
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_job_read(p_job_id uuid) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_job_read_latest(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_job_read_latest(p_table text, p_id uuid, p_version text, p_revision_checksum text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_dataset_row jsonb;
  v_owner_id uuid;
  v_job public.dataset_review_submit_requests%rowtype;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table <> 'processes' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Review-submit jobs currently support process datasets only'
    );
  end if;

  if p_revision_checksum is not null
    and p_revision_checksum !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVISION_CHECKSUM_REQUIRED',
      'status', 400,
      'message', 'revisionChecksum must be a lowercase SHA-256 hex digest'
    );
  end if;

  v_dataset_row := public.cmd_review_get_dataset_row(p_table, p_id, p_version, false);

  if v_dataset_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_dataset_row->>'user_id', '')::uuid;

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can read review-submit jobs'
    );
  end if;

  select *
    into v_job
  from public.dataset_review_submit_requests
  where dataset_table = p_table
    and dataset_id = p_id
    and dataset_version = p_version
    and requested_by = v_actor
    and (p_revision_checksum is null or revision_checksum = p_revision_checksum)
  order by created_at desc
  limit 1;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Review-submit job not found'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', public.cmd_dataset_review_submit_job_payload(v_job)
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_review_submit_job_read_latest(p_table text, p_id uuid, p_version text, p_revision_checksum text) OWNER TO postgres;

--
-- Name: cmd_dataset_review_submit_job_record_result(uuid, text, uuid, jsonb, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_review_submit_job_record_result(p_job_id uuid, p_status text, p_gate_run_id uuid DEFAULT NULL::uuid, p_result jsonb DEFAULT NULL::jsonb, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_error_details jsonb DEFAULT NULL::jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text := lower(trim(coalesce(p_status, '')));
  v_job public.dataset_review_submit_requests%rowtype;
  v_gate public.dataset_review_submit_gate_runs%rowtype;
  v_completed_at timestamptz;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to record review-submit job results'
    );
  end if;

  if v_status not in ('waiting_gate', 'blocked', 'stale', 'error', 'cancelled') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_JOB_STATUS',
      'status', 400,
      'message', 'status must be waiting_gate, blocked, stale, error, or cancelled'
    );
  end if;

  if p_result is not null and jsonb_typeof(p_result) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_JOB_RESULT',
      'status', 400,
      'message', 'result must be a JSON object'
    );
  end if;

  if p_error_details is not null and jsonb_typeof(p_error_details) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_SUBMIT_JOB_ERROR_DETAILS',
      'status', 400,
      'message', 'error details must be a JSON object'
    );
  end if;

  select *
    into v_job
  from public.dataset_review_submit_requests
  where id = p_job_id
  for update;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_SUBMIT_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Review-submit job not found'
    );
  end if;

  if p_gate_run_id is not null then
    select *
      into v_gate
    from public.dataset_review_submit_gate_runs
    where id = p_gate_run_id;

    if v_gate.id is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_NOT_FOUND',
        'status', 404,
        'message', 'Review-submit gate run not found'
      );
    end if;

    if v_gate.dataset_table <> v_job.dataset_table
      or v_gate.dataset_id <> v_job.dataset_id
      or v_gate.dataset_version <> v_job.dataset_version
      or v_gate.revision_checksum <> v_job.revision_checksum
      or v_gate.policy_profile <> v_job.policy_profile
      or v_gate.report_schema_version <> v_job.report_schema_version then
      return jsonb_build_object(
        'ok', false,
        'code', 'REVIEW_SUBMIT_GATE_DATASET_MISMATCH',
        'status', 409,
        'message', 'Review-submit gate run does not match this review-submit job'
      );
    end if;
  end if;

  if v_status in ('blocked', 'stale', 'error', 'cancelled') then
    v_completed_at := now();
  end if;

  update public.dataset_review_submit_requests
    set status = v_status,
        gate_run_id = coalesce(p_gate_run_id, gate_run_id),
        result = p_result,
        last_error_code =
          case when v_status = 'waiting_gate' then null else p_error_code end,
        last_error_message =
          case when v_status = 'waiting_gate' then null else p_error_message end,
        last_error_details =
          case when v_status = 'waiting_gate' then null else p_error_details end,
        modified_at = now(),
        completed_at = v_completed_at
  where id = v_job.id
  returning *
    into v_job;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_review_submit_job_record_result',
    v_job.requested_by,
    v_job.dataset_table,
    v_job.dataset_id,
    v_job.dataset_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'review_submit_job_id', v_job.id,
      'review_submit_request_id', v_job.id,
      'gate_run_id', v_job.gate_run_id,
      'status', v_status,
      'error_code', p_error_code
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.cmd_dataset_review_submit_job_payload(v_job)
  );
end;
$$;


ALTER FUNCTION public.cmd_dataset_review_submit_job_record_result(p_job_id uuid, p_status text, p_gate_run_id uuid, p_result jsonb, p_error_code text, p_error_message text, p_error_details jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_save_draft(text, uuid, text, jsonb, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_save_draft(p_table text, p_id uuid, p_version text, p_json_ordered jsonb, p_model_id uuid DEFAULT NULL::uuid, p_rule_verification boolean DEFAULT NULL::boolean, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  if p_json_ordered is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'JSON_ORDERED_REQUIRED',
      'status', 400,
      'message', 'jsonOrdered is required'
    );
  end if;

  if p_table <> 'processes' and p_model_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_NOT_ALLOWED',
      'status', 400,
      'message', 'modelId is only allowed for process dataset drafts'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can save draft changes'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 403,
      'message', 'Published data cannot be edited through draft save',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 403,
      'message', 'Data is under review and cannot be modified',
      'details', jsonb_build_object(
        'state_code', 20,
        'review_state_code', v_state_code
      )
    );
  end if;

  if p_table = 'processes' then
    execute format(
      'update public.%I as t
          set json_ordered = $1::json,
              model_id = coalesce($2, t.model_id),
              rule_verification = $3,
              modified_at = now()
        where t.id = $4
          and t.version = $5
      returning to_jsonb(t)',
      p_table
    )
      into v_updated_row
      using p_json_ordered, p_model_id, p_rule_verification, p_id, p_version;
  else
    execute format(
      'update public.%I as t
          set json_ordered = $1::json,
              rule_verification = $2,
              modified_at = now()
        where t.id = $3
          and t.version = $4
      returning to_jsonb(t)',
      p_table
    )
      into v_updated_row
      using p_json_ordered, p_rule_verification, p_id, p_version;
  end if;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_save_draft',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_save_draft(p_table text, p_id uuid, p_version text, p_json_ordered jsonb, p_model_id uuid, p_rule_verification boolean, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_semantic_backfill(text, integer, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_semantic_backfill(p_table text, p_batch_size integer DEFAULT 100, p_after_id uuid DEFAULT NULL::uuid, p_after_version text DEFAULT NULL::text, p_force_extraction boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_table text := lower(btrim(coalesce(p_table, '')));
  v_entity_kind text;
  v_content_function text;
  v_batch_size integer := least(greatest(coalesce(p_batch_size, 100), 1), 500);
  v_row_id uuid;
  v_row_version text;
  v_needs_extraction boolean;
  v_needs_embedding boolean;
  v_scanned_count integer := 0;
  v_extraction_enqueued integer := 0;
  v_embedding_enqueued integer := 0;
  v_already_queued integer := 0;
  v_last_id uuid;
  v_last_version text;
  v_job_exists boolean;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  v_entity_kind := case v_table
    when 'contacts' then 'contact'
    when 'flowproperties' then 'flowproperty'
    when 'sources' then 'source'
    when 'unitgroups' then 'unitgroup'
    else null
  end;

  if v_entity_kind is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'UNSUPPORTED_DATASET_TABLE',
      'status', 400,
      'message', format('Unsupported semantic backfill table: %s', coalesce(p_table, '<null>'))
    );
  end if;

  v_content_function := v_table || '_embedding_ft_input';

  for v_row_id, v_row_version, v_needs_extraction, v_needs_embedding in execute format(
    $sql$
      select
        dataset.id,
        btrim(dataset.version::text) as version,
        dataset.extracted_md is null or $4 as needs_extraction,
        dataset.embedding_ft is null as needs_embedding
      from public.%I dataset
      where dataset.json is not null
        and nullif(btrim(dataset.version::text), '') is not null
        and ($4 or dataset.extracted_md is null or dataset.embedding_ft is null)
        and (
          $1 is null
          or (dataset.id, btrim(dataset.version::text)) > ($1, coalesce($2, ''))
        )
      order by dataset.id, btrim(dataset.version::text)
      limit $3
    $sql$,
    v_table
  ) using p_after_id, p_after_version, v_batch_size, coalesce(p_force_extraction, false)
  loop
    v_scanned_count := v_scanned_count + 1;
    v_last_id := v_row_id;
    v_last_version := v_row_version;

    if v_needs_extraction then
      select exists (
        select 1
        from pgmq.q_dataset_extraction_jobs queued
        where queued.message->>'schema' = 'public'
          and queued.message->>'table' = v_table
          and queued.message->>'id' = v_row_id::text
          and queued.message->>'version' = v_row_version
          and queued.message->>'extraction_kind' = 'extracted_md'
      ) into v_job_exists;

      if v_job_exists then
        v_already_queued := v_already_queued + 1;
      else
        perform pgmq.send(
          queue_name => 'dataset_extraction_jobs',
          msg => jsonb_build_object(
            'schema', 'public',
            'table', v_table,
            'id', v_row_id,
            'version', v_row_version,
            'entity_kind', v_entity_kind,
            'extraction_kind', 'extracted_md',
            'created_at', clock_timestamp(),
            'backfill', true
          )
        );
        v_extraction_enqueued := v_extraction_enqueued + 1;
      end if;
    elsif v_needs_embedding then
      select exists (
        select 1
        from pgmq.q_embedding_jobs queued
        where queued.message->>'schema' = 'public'
          and queued.message->>'table' = v_table
          and queued.message->>'id' = v_row_id::text
          and queued.message->>'version' = v_row_version
          and queued.message->>'embeddingColumn' = 'embedding_ft'
          and queued.message->>'edgeFunction' = 'embedding_ft'
      ) or exists (
        select 1
        from util.pending_embedding_jobs pending
        where pending.schema_name = 'public'
          and pending.table_name = v_table
          and pending.record_id = v_row_id::text
          and pending.record_version = v_row_version
          and pending.embedding_column = 'embedding_ft'
          and pending.edge_function = 'embedding_ft'
          and pending.status in ('pending', 'enqueued')
      ) into v_job_exists;

      if v_job_exists then
        v_already_queued := v_already_queued + 1;
      else
        perform pgmq.send(
          queue_name => 'embedding_jobs',
          msg => jsonb_build_object(
            'id', v_row_id,
            'version', v_row_version,
            'schema', 'public',
            'table', v_table,
            'contentFunction', v_content_function,
            'embeddingColumn', 'embedding_ft',
            'edgeFunction', 'embedding_ft',
            'backfill', true
          )
        );
        v_embedding_enqueued := v_embedding_enqueued + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'table', v_table,
    'scanned_count', v_scanned_count,
    'extraction_enqueued_count', v_extraction_enqueued,
    'embedding_enqueued_count', v_embedding_enqueued,
    'already_queued_count', v_already_queued,
    'last_id', v_last_id,
    'last_version', v_last_version,
    'has_more', v_scanned_count = v_batch_size
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_semantic_backfill(p_table text, p_batch_size integer, p_after_id uuid, p_after_version text, p_force_extraction boolean) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_semantic_backfill(p_table text, p_batch_size integer, p_after_id uuid, p_after_version text, p_force_extraction boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_semantic_backfill(p_table text, p_batch_size integer, p_after_id uuid, p_after_version text, p_force_extraction boolean) IS 'Service-only bounded cursor RPC that enqueues missing foundation-dataset derivatives and skips rows without a stable nonblank id/version worker identity.';


--
-- Name: cmd_dataset_withdraw(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in ('sources', 'flows', 'processes') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Only sources, flows, and processes can be withdrawn'
    );
  end if;

  if v_reason = '' or length(v_reason) > 4000 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WITHDRAW_REASON',
      'status', 400,
      'message', 'A non-empty withdrawal reason of at most 4000 characters is required'
    );
  end if;

  if jsonb_typeof(coalesce(p_audit, '{}'::jsonb)) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_AUDIT_PAYLOAD',
      'status', 400,
      'message', 'Audit payload must be a JSON object'
    );
  end if;

  execute format(
    'select to_jsonb(t)
       from public.%I as t
      where t.id = $1
        and t.version = $2
      for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can withdraw this dataset'
    );
  end if;

  if v_state_code = 0 then
    return jsonb_build_object(
      'ok', true,
      'changed', false,
      'code', 'DATASET_ALREADY_DRAFT',
      'data', v_current_row
    );
  end if;

  if v_state_code < 100 or v_state_code >= 200 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_WITHDRAW_REQUIRES_PUBLISHED_STATE',
      'status', 403,
      'message', 'Only public datasets in state 100 through 199 can be withdrawn',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  execute format(
    'update public.%I as t
        set state_code = 0,
            rule_verification = false,
            modified_at = now()
      where t.id = $1
        and t.version = $2
    returning to_jsonb(t)',
    p_table
  )
    into v_updated_row
    using p_id, p_version;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_withdraw',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
      || jsonb_build_object(
        'reason', v_reason,
        'from_state_code', v_state_code,
        'to_state_code', 0
      )
  );

  return jsonb_build_object(
    'ok', true,
    'changed', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION public.cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb) IS 'Owner-authenticated, audited withdrawal of public source, flow, or process datasets to draft state without changing dataset JSON.';


--
-- Name: cmd_lca_release_approve(uuid, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lca_release_approve(p_release_run_id uuid, p_publish_plan_hash text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_run public.lca_release_runs%rowtype;
  v_approval public.lca_release_approvals%rowtype;
  v_now timestamptz := clock_timestamp();
  v_expires_at timestamptz;
  v_approval_hash text;
begin
  if v_actor is null then
    return public.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lca_release_is_manager() then
    return public.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$' then
    return public.lca_release_error('invalid_publish_plan_hash', 400, 'publishPlanHash must be SHA-256');
  end if;

  select * into v_run
  from public.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return public.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  if v_run.publish_plan_hash <> p_publish_plan_hash then
    return public.lca_release_error('publish_plan_hash_mismatch', 409, 'Approval must bind the exact immutable publish plan');
  end if;
  if v_run.status not in ('ready_for_approval', 'approved') then
    return public.lca_release_error('release_not_ready_for_approval', 409, 'Release run is not ready for approval');
  end if;
  if v_run.release_manifest_hash is null
     or (select count(*) from public.lca_release_artifacts where release_run_id = v_run.id) <> 4 then
    return public.lca_release_error('release_artifacts_incomplete', 409, 'Four verified release artifacts are required before approval');
  end if;

  update public.lca_release_approvals
  set status = 'expired'
  where release_run_id = v_run.id
    and status = 'approved'
    and expires_at <= v_now;

  select * into v_approval
  from public.lca_release_approvals
  where release_run_id = v_run.id
    and status = 'approved'
  for update;

  if v_approval.id is not null then
    if v_approval.publish_plan_hash = p_publish_plan_hash then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'approvalId', v_approval.id,
          'approvalHash', v_approval.approval_hash,
          'publishPlanHash', v_approval.publish_plan_hash,
          'approvedBy', v_approval.approved_by,
          'approvedAt', v_approval.approved_at,
          'expiresAt', v_approval.expires_at
        )
      );
    end if;
    return public.lca_release_error('active_approval_conflict', 409, 'An active approval exists for different content');
  end if;

  v_expires_at := coalesce(p_expires_at, v_now + interval '24 hours');
  if v_expires_at <= v_now then
    return public.lca_release_error('approval_expiry_invalid', 400, 'Approval expiry must be in the future');
  end if;
  v_approval_hash := encode(
    extensions.digest(
      convert_to(
        concat_ws('|', v_run.id::text, p_publish_plan_hash, v_actor::text, v_now::text),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  insert into public.lca_release_approvals (
    release_run_id, publish_plan_hash, approval_hash, status,
    approved_by, approved_at, expires_at, reason, audit_correlation
  ) values (
    v_run.id, p_publish_plan_hash, v_approval_hash, 'approved',
    v_actor, v_now, v_expires_at, nullif(trim(coalesce(p_reason, '')), ''),
    coalesce(p_audit, '{}'::jsonb)
  )
  returning * into v_approval;

  update public.lca_release_runs
  set status = 'approved', approved_at = v_now, updated_at = v_now
  where id = v_run.id;

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_approve', v_actor, 'lca_release_approvals', v_approval.id,
    v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'releaseRunId', v_run.id,
      'publishPlanHash', p_publish_plan_hash,
      'approvalHash', v_approval_hash,
      'expiresAt', v_expires_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'approvalId', v_approval.id,
      'approvalHash', v_approval.approval_hash,
      'publishPlanHash', v_approval.publish_plan_hash,
      'approvedBy', v_approval.approved_by,
      'approvedAt', v_approval.approved_at,
      'expiresAt', v_approval.expires_at
    )
  );
end;
$_$;


ALTER FUNCTION public.cmd_lca_release_approve(p_release_run_id uuid, p_publish_plan_hash text, p_expires_at timestamp with time zone, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_artifacts_finalize_service(uuid, text, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lca_release_artifacts_finalize_service(p_release_run_id uuid, p_publish_plan_hash text, p_release_manifest jsonb, p_release_manifest_hash text, p_artifacts jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_run public.lca_release_runs%rowtype;
  v_invalid_count integer;
  v_dataset_count integer;
  v_artifact_count integer;
begin
  if not public.lca_release_is_service_request() then
    return public.lca_release_error('service_role_required', 403, 'Internal service identity is required to finalize artifacts');
  end if;
  if jsonb_typeof(coalesce(p_release_manifest, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_artifacts, 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_audit, 'null'::jsonb)) <> 'object' then
    return public.lca_release_error('invalid_payload', 400, 'Release manifest, artifacts, and audit have invalid JSON shapes');
  end if;
  if coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_release_manifest_hash, '') !~ '^[0-9a-f]{64}$' then
    return public.lca_release_error('invalid_hash', 400, 'Plan and release manifest hashes must be lowercase SHA-256 values');
  end if;

  select * into v_run
  from public.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return public.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  if v_run.publish_plan_hash <> p_publish_plan_hash then
    return public.lca_release_error('publish_plan_hash_mismatch', 409, 'Artifact finalize plan hash does not match the prepared run');
  end if;
  if v_run.status <> 'prepared' then
    if v_run.status in ('ready_for_approval', 'approved', 'published', 'readback_verified')
       and v_run.release_manifest_hash = p_release_manifest_hash then
      with existing as (
        select profile_id, artifact_format, storage_bucket, object_key, sha256, byte_size, media_type
        from public.lca_release_artifacts
        where release_run_id = v_run.id
      ),
      supplied as (
        select
          artifact.value->>'profileId' as profile_id,
          artifact.value->>'format' as artifact_format,
          artifact.value->>'storageBucket' as storage_bucket,
          artifact.value->>'objectKey' as object_key,
          artifact.value->>'sha256' as sha256,
          (artifact.value->>'byteSize')::bigint as byte_size,
          artifact.value->>'mediaType' as media_type
        from jsonb_array_elements(p_artifacts) as artifact(value)
      )
      select count(*) into v_invalid_count
      from existing
      full join supplied using (profile_id, artifact_format)
      where existing.profile_id is null
         or supplied.profile_id is null
         or existing.storage_bucket is distinct from supplied.storage_bucket
         or existing.object_key is distinct from supplied.object_key
         or existing.sha256 is distinct from supplied.sha256
         or existing.byte_size is distinct from supplied.byte_size
         or existing.media_type is distinct from supplied.media_type;

      if v_invalid_count = 0 and jsonb_array_length(p_artifacts) = 4 then
        return jsonb_build_object(
          'ok', true,
          'reused', true,
          'data', jsonb_build_object(
            'releaseRunId', v_run.id,
            'status', v_run.status,
            'releaseManifestHash', v_run.release_manifest_hash
          )
        );
      end if;
      return public.lca_release_error('release_finalize_conflict', 409, 'Finalize retry artifact refs differ from durable content');
    end if;
    return public.lca_release_error('release_state_conflict', 409, 'Release run is not in prepared state');
  end if;

  if p_release_manifest->>'schemaVersion' is distinct from 'tiangong.release-manifest.v1'
     or p_release_manifest->>'releaseRunId' is distinct from v_run.id::text
     or p_release_manifest->>'releaseVersion' is distinct from v_run.release_version
     or p_release_manifest->>'profileLockHash' is distinct from v_run.profile_lock_hash
     or p_release_manifest->>'publishPlanHash' is distinct from v_run.publish_plan_hash
     or p_release_manifest->>'artifactSetHash' is distinct from v_run.artifact_set_hash
     or p_release_manifest->'scope'->>'coverageMode' is distinct from 'global_eligible'
     or p_release_manifest->'scope'->>'selectionManifestHash' is distinct from v_run.selection_manifest_hash
     or p_release_manifest->'calculationBundle'->>'bundleContentHash' is distinct from v_run.calculation_bundle_hash then
    return public.lca_release_error('release_manifest_mismatch', 409, 'Release manifest does not match the prepared run and exact hashes');
  end if;
  if jsonb_typeof(p_release_manifest->'datasets') is distinct from 'array'
     or jsonb_array_length(p_release_manifest->'datasets') = 0
     or jsonb_typeof(p_release_manifest->'packages') is distinct from 'array'
     or jsonb_array_length(p_release_manifest->'packages') <> 4
     or jsonb_array_length(p_artifacts) <> 4 then
    return public.lca_release_error('release_manifest_incomplete', 400, 'Release manifest requires datasets and four uploaded package artifacts');
  end if;
  if coalesce(
    p_release_manifest->'validation'->'tidas'->>'status' = 'passed'
    and p_release_manifest->'validation'->'ilcd'->>'status' = 'passed'
    and p_release_manifest->'validation'->'semanticRoundtrip'->>'status' = 'passed'
    and p_release_manifest->'validation'->'referenceClosure'->>'status' = 'passed'
    and p_release_manifest->'validation'->'numericParity'->>'status' = 'passed',
    false
  ) is not true then
    return public.lca_release_error('validation_not_passed', 400, 'All release validation gates must pass before artifact finalization');
  end if;

  with expected as (
    select
      package.value->>'profileId' as profile_id,
      package.value->>'format' as artifact_format,
      package.value->>'closureHash' as closure_hash,
      package.value->'artifact'->>'sha256' as sha256,
      (package.value->'artifact'->>'byteSize')::bigint as byte_size,
      package.value->'artifact'->>'mediaType' as media_type
    from jsonb_array_elements(p_release_manifest->'packages') as package(value)
  ),
  uploaded as (
    select
      artifact.value->>'profileId' as profile_id,
      artifact.value->>'format' as artifact_format,
      artifact.value->>'storageBucket' as storage_bucket,
      artifact.value->>'objectKey' as object_key,
      artifact.value->>'sha256' as sha256,
      (artifact.value->>'byteSize')::bigint as byte_size,
      artifact.value->>'mediaType' as media_type
    from jsonb_array_elements(p_artifacts) as artifact(value)
  )
  select count(*) into v_invalid_count
  from expected
  full join uploaded using (profile_id, artifact_format)
  where expected.profile_id is null
     or uploaded.profile_id is null
     or expected.profile_id not in (
          'unit-process-full-closure.v1',
          'standalone-lifecyclemodel-result-full-closure.v1'
        )
     or expected.artifact_format not in ('tidas', 'ilcd')
     or expected.sha256 !~ '^[0-9a-f]{64}$'
     or expected.closure_hash !~ '^[0-9a-f]{64}$'
     or expected.sha256 is distinct from uploaded.sha256
     or expected.byte_size is distinct from uploaded.byte_size
     or expected.media_type is distinct from uploaded.media_type
     or coalesce(length(trim(uploaded.storage_bucket)), 0) = 0
     or coalesce(length(trim(uploaded.object_key)), 0) = 0;

  if v_invalid_count <> 0 then
    return public.lca_release_error('artifact_set_mismatch', 409, 'Uploaded artifact refs do not exactly match the release manifest');
  end if;

  with dataset_rows as (
    select dataset.value
    from jsonb_array_elements(p_release_manifest->'datasets') as dataset(value)
  )
  select count(*) into v_invalid_count
  from dataset_rows
  where value->>'datasetType' not in (
          'process', 'lifecyclemodel', 'flow', 'flowproperty', 'unitgroup',
          'lciamethod', 'source', 'contact'
        )
     or value->>'role' not in ('unit_process', 'result_process', 'lifecycle_model', 'support')
     or (value->>'role' in ('unit_process', 'result_process') and value->>'datasetType' <> 'process')
     or (value->>'role' = 'lifecycle_model' and value->>'datasetType' <> 'lifecyclemodel')
     or value->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
     or (
       value->>'role' in ('unit_process', 'result_process', 'lifecycle_model')
       and (
         jsonb_typeof(value->'sourceProcess') is distinct from 'object'
         or coalesce(value->'sourceProcess'->>'id', '') = ''
         or value->'sourceProcess'->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
       )
     )
     or (
       value->>'role' = 'unit_process'
       and (
         value->'sourceProcess'->>'id' is distinct from value->>'uuid'
         or value->'sourceProcess'->>'version' is distinct from value->>'version'
       )
     )
     or (
       value->>'role' = 'support'
       and value ? 'sourceProcess'
     )
     or value->>'versionSignificantHash' !~ '^[0-9a-f]{64}$'
     or value->>'semanticHash' !~ '^[0-9a-f]{64}$'
     or value->>'canonicalContentHash' !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(value->'artifact') is distinct from 'object';

  if v_invalid_count <> 0 then
    return public.lca_release_error('dataset_index_invalid', 400, 'Release dataset index contains invalid identities, versions, or hashes');
  end if;

  with process_datasets as (
    select
      dataset.value->>'role' as dataset_role,
      dataset.value->'sourceProcess'->>'id' as source_process_uuid,
      dataset.value->'sourceProcess'->>'version' as source_process_version
    from jsonb_array_elements(p_release_manifest->'datasets') as dataset(value)
    where dataset.value->>'role' in ('unit_process', 'lifecycle_model', 'result_process')
  ),
  invalid_source_sets as (
    select source_process_uuid, source_process_version
    from process_datasets
    group by source_process_uuid, source_process_version
    having count(*) filter (where dataset_role = 'unit_process') <> 1
       or count(*) filter (where dataset_role = 'lifecycle_model') <> 1
       or count(*) filter (where dataset_role = 'result_process') <> 1
  )
  select count(*) into v_invalid_count
  from invalid_source_sets;

  if v_invalid_count <> 0 then
    return public.lca_release_error(
      'dataset_source_process_set_invalid', 400,
      'Each source Process requires exactly one Unit Process, LifecycleModel, and Result Process identity'
    );
  end if;

  insert into public.lca_release_dataset_versions (
    release_run_id, dataset_type, dataset_role, dataset_uuid, dataset_version,
    source_process_uuid, source_process_version,
    version_significant_hash, semantic_hash, canonical_content_hash, artifact_ref
  )
  select
    v_run.id,
    dataset.value->>'datasetType',
    dataset.value->>'role',
    (dataset.value->>'uuid')::uuid,
    dataset.value->>'version',
    (dataset.value->'sourceProcess'->>'id')::uuid,
    dataset.value->'sourceProcess'->>'version',
    dataset.value->>'versionSignificantHash',
    dataset.value->>'semanticHash',
    dataset.value->>'canonicalContentHash',
    dataset.value->'artifact'
  from jsonb_array_elements(p_release_manifest->'datasets') as dataset(value);
  get diagnostics v_dataset_count = row_count;

  insert into public.lca_release_artifacts (
    release_run_id, profile_id, artifact_format, storage_bucket, object_key,
    sha256, byte_size, media_type, closure_hash, verified_at
  )
  select
    v_run.id,
    package.value->>'profileId',
    package.value->>'format',
    artifact.value->>'storageBucket',
    artifact.value->>'objectKey',
    artifact.value->>'sha256',
    (artifact.value->>'byteSize')::bigint,
    artifact.value->>'mediaType',
    package.value->>'closureHash',
    now()
  from jsonb_array_elements(p_release_manifest->'packages') as package(value)
  join jsonb_array_elements(p_artifacts) as artifact(value)
    on artifact.value->>'profileId' = package.value->>'profileId'
   and artifact.value->>'format' = package.value->>'format';
  get diagnostics v_artifact_count = row_count;

  update public.lca_release_runs
  set release_manifest = p_release_manifest,
      release_manifest_hash = p_release_manifest_hash,
      status = 'ready_for_approval',
      artifacts_finalized_at = now(),
      updated_at = now()
  where id = v_run.id;

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_artifacts_finalize_service', v_run.created_by,
    'lca_release_runs', v_run.id, v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'serviceCallback', true,
      'publishPlanHash', p_publish_plan_hash,
      'releaseManifestHash', p_release_manifest_hash,
      'artifactSetHash', v_run.artifact_set_hash,
      'artifactCount', v_artifact_count,
      'datasetCount', v_dataset_count
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'releaseRunId', v_run.id,
      'status', 'ready_for_approval',
      'releaseManifestHash', p_release_manifest_hash,
      'artifactCount', v_artifact_count,
      'datasetCount', v_dataset_count
    )
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return public.lca_release_error('release_manifest_invalid', 400, 'Release manifest contains invalid UUID or byte-size values');
  when unique_violation then
    return public.lca_release_error('release_artifact_conflict', 409, 'Release dataset or artifact identity already exists with conflicting content');
end;
$_$;


ALTER FUNCTION public.cmd_lca_release_artifacts_finalize_service(p_release_run_id uuid, p_publish_plan_hash text, p_release_manifest jsonb, p_release_manifest_hash text, p_artifacts jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_prepare(uuid, text, text, text, jsonb, text, text, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lca_release_prepare(p_release_run_id uuid, p_release_version text, p_selection_manifest_hash text, p_input_manifest_hash text, p_calculation_bundle_ref jsonb, p_calculation_bundle_hash text, p_profile_lock_hash text, p_publish_plan jsonb, p_publish_plan_hash text, p_idempotency_key text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_existing public.lca_release_runs%rowtype;
  v_request_hash text;
  v_artifact_set_hash text;
  v_pair_count integer;
begin
  if v_actor is null then
    return public.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lca_release_is_manager() then
    return public.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if p_release_run_id is null then
    return public.lca_release_error('release_run_id_required', 400, 'releaseRunId is required');
  end if;
  if coalesce(p_release_version, '') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return public.lca_release_error('invalid_release_version', 400, 'releaseVersion must use NN.NN.NNN');
  end if;
  if coalesce(p_selection_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_input_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_calculation_bundle_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_profile_lock_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$' then
    return public.lca_release_error('invalid_hash', 400, 'Release hashes must be lowercase SHA-256 values');
  end if;
  if jsonb_typeof(coalesce(p_calculation_bundle_ref, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_publish_plan, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_audit, 'null'::jsonb)) <> 'object' then
    return public.lca_release_error('invalid_payload', 400, 'Bundle ref, publish plan, and audit must be JSON objects');
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    return public.lca_release_error('idempotency_key_required', 400, 'idempotencyKey is required');
  end if;
  if p_publish_plan->>'schemaVersion' is distinct from 'tiangong.release.publish-plan.v1'
     or p_publish_plan->>'releaseRunId' is distinct from p_release_run_id::text
     or p_publish_plan->>'releaseVersion' is distinct from p_release_version
     or p_publish_plan->>'calculationBundleHash' is distinct from p_calculation_bundle_hash
     or p_publish_plan->>'profileLockHash' is distinct from p_profile_lock_hash
     or p_publish_plan->>'planHash' is distinct from p_publish_plan_hash then
    return public.lca_release_error('publish_plan_mismatch', 400, 'Publish plan identity or exact hashes do not match the request');
  end if;
  v_artifact_set_hash := p_publish_plan->>'artifactSetHash';
  if coalesce(v_artifact_set_hash, '') !~ '^[0-9a-f]{64}$' then
    return public.lca_release_error('invalid_artifact_set_hash', 400, 'Publish plan artifactSetHash must be SHA-256');
  end if;
  if jsonb_typeof(p_publish_plan->'datasets') is distinct from 'array'
     or jsonb_array_length(p_publish_plan->'datasets') = 0
     or jsonb_typeof(p_publish_plan->'packages') is distinct from 'array'
     or jsonb_array_length(p_publish_plan->'packages') <> 4 then
    return public.lca_release_error('publish_plan_incomplete', 400, 'Publish plan must contain datasets and exactly four packages');
  end if;

  select count(distinct (package.value->>'profileId') || ':' || (package.value->>'format'))
    into v_pair_count
  from jsonb_array_elements(p_publish_plan->'packages') as package(value)
  where package.value->>'profileId' in (
          'unit-process-full-closure.v1',
          'standalone-lifecyclemodel-result-full-closure.v1'
        )
    and package.value->>'format' in ('tidas', 'ilcd')
    and package.value->>'sha256' ~ '^[0-9a-f]{64}$';

  if v_pair_count <> 4 then
    return public.lca_release_error('publish_plan_profiles_invalid', 400, 'Publish plan must contain both profiles in TIDAS and ILCD formats');
  end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(
        concat_ws(
          '|', p_release_run_id::text, p_release_version,
          p_selection_manifest_hash, p_input_manifest_hash,
          p_calculation_bundle_hash, p_profile_lock_hash,
          p_publish_plan_hash, v_artifact_set_hash
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  select * into v_existing
  from public.lca_release_runs
  where id = p_release_run_id
     or (created_by = v_actor and idempotency_key = trim(p_idempotency_key))
  order by (id = p_release_run_id) desc
  limit 1
  for update;

  if v_existing.id is not null then
    if v_existing.id = p_release_run_id
       and v_existing.created_by = v_actor
       and v_existing.request_hash = v_request_hash
       and v_existing.calculation_bundle_ref = p_calculation_bundle_ref
       and v_existing.publish_plan = p_publish_plan then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'releaseRunId', v_existing.id,
          'releaseVersion', v_existing.release_version,
          'status', v_existing.status,
          'publishPlanHash', v_existing.publish_plan_hash
        )
      );
    end if;
    return public.lca_release_error('release_prepare_conflict', 409, 'Release run id or idempotency key is already bound to different content');
  end if;

  insert into public.lca_release_runs (
    id, release_version, scope_mode, selection_manifest_hash,
    input_manifest_hash, calculation_bundle_hash, calculation_bundle_ref,
    profile_lock_hash, publish_plan_hash, publish_plan, artifact_set_hash,
    status, idempotency_key, request_hash, created_by
  ) values (
    p_release_run_id, p_release_version, 'global_eligible', p_selection_manifest_hash,
    p_input_manifest_hash, p_calculation_bundle_hash, p_calculation_bundle_ref,
    p_profile_lock_hash, p_publish_plan_hash, p_publish_plan, v_artifact_set_hash,
    'prepared', trim(p_idempotency_key), v_request_hash, v_actor
  );

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_prepare', v_actor, 'lca_release_runs', p_release_run_id,
    p_release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'publishPlanHash', p_publish_plan_hash,
      'calculationBundleHash', p_calculation_bundle_hash,
      'inputManifestHash', p_input_manifest_hash,
      'artifactSetHash', v_artifact_set_hash
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'releaseRunId', p_release_run_id,
      'releaseVersion', p_release_version,
      'status', 'prepared',
      'publishPlanHash', p_publish_plan_hash
    )
  );
exception
  when unique_violation then
    return public.lca_release_error('release_prepare_conflict', 409, 'Release version, run id, or idempotency key already exists');
end;
$_$;


ALTER FUNCTION public.cmd_lca_release_prepare(p_release_run_id uuid, p_release_version text, p_selection_manifest_hash text, p_input_manifest_hash text, p_calculation_bundle_ref jsonb, p_calculation_bundle_hash text, p_profile_lock_hash text, p_publish_plan jsonb, p_publish_plan_hash text, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_publish(uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lca_release_publish(p_release_run_id uuid, p_approval_id uuid, p_approval_hash text, p_publish_plan_hash text, p_idempotency_key text, p_credential_fingerprint text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_run public.lca_release_runs%rowtype;
  v_approval public.lca_release_approvals%rowtype;
  v_existing public.lca_release_publications%rowtype;
  v_publication public.lca_release_publications%rowtype;
  v_previous public.lca_release_publications%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return public.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lca_release_is_manager() then
    return public.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if coalesce(p_approval_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_credential_fingerprint, '') !~ '^[0-9a-f]{64}$' then
    return public.lca_release_error('invalid_publish_hash', 400, 'Approval, plan, and credential fingerprint must be lowercase SHA-256 values');
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    return public.lca_release_error('idempotency_key_required', 400, 'idempotencyKey is required');
  end if;

  select * into v_run
  from public.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return public.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;

  select * into v_existing
  from public.lca_release_publications
  where release_run_id = v_run.id
     or (executed_by = v_actor and idempotency_key = trim(p_idempotency_key))
  order by (release_run_id = v_run.id) desc
  limit 1;

  if v_existing.id is not null then
    if v_existing.release_run_id = v_run.id
       and v_existing.executed_by = v_actor
       and v_existing.approval_id = p_approval_id
       and v_existing.approval_hash = p_approval_hash
       and v_existing.publish_plan_hash = p_publish_plan_hash
       and v_existing.idempotency_key = trim(p_idempotency_key)
       and v_existing.credential_fingerprint = p_credential_fingerprint then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'publicationId', v_existing.id,
          'releaseRunId', v_existing.release_run_id,
          'releaseVersion', v_existing.release_version,
          'status', v_existing.status,
          'publishedAt', v_existing.published_at
        )
      );
    end if;
    return public.lca_release_error('publish_idempotency_conflict', 409, 'Publish idempotency key is bound to different content');
  end if;

  if v_run.status <> 'approved' then
    return public.lca_release_error('release_not_approved', 409, 'Release run must have a durable active approval before publish');
  end if;
  if v_run.publish_plan_hash <> p_publish_plan_hash then
    return public.lca_release_error('publish_plan_hash_mismatch', 409, 'Publish plan hash differs from the prepared release');
  end if;

  select * into v_approval
  from public.lca_release_approvals
  where id = p_approval_id
    and release_run_id = v_run.id
  for update;

  if v_approval.id is null
     or v_approval.status <> 'approved'
     or v_approval.publish_plan_hash <> p_publish_plan_hash
     or v_approval.approval_hash <> p_approval_hash
     or v_approval.expires_at <= v_now then
    return public.lca_release_error('approval_invalid', 409, 'Approval is missing, expired, consumed, or does not bind the exact plan');
  end if;
  if v_run.release_manifest_hash is null
     or v_run.release_manifest->>'publishPlanHash' <> p_publish_plan_hash
     or v_run.release_manifest->>'artifactSetHash' <> v_run.artifact_set_hash
     or (select count(*) from public.lca_release_artifacts where release_run_id = v_run.id and verified_at is not null) <> 4 then
    return public.lca_release_error('release_artifacts_incomplete', 409, 'Verified manifest and all four artifacts are required before publish');
  end if;

  lock table public.lca_release_publications in exclusive mode;

  select * into v_previous
  from public.lca_release_publications
  where publication_series_key = 'global'
    and publication_channel = 'public'
    and visibility_scope = 'public'
    and is_current = true
  for update;

  if v_previous.id is not null then
    update public.lca_release_publications
    set is_current = false,
        status = 'superseded',
        superseded_at = v_now,
        updated_at = v_now
    where id = v_previous.id;
  end if;

  insert into public.lca_release_publications (
    release_run_id, release_version, publication_series_key,
    publication_channel, visibility_scope, status, is_current,
    approval_id, approval_hash, publish_plan_hash, release_manifest_hash,
    artifact_set_hash, approved_by, executed_by, credential_fingerprint,
    idempotency_key, published_at, reason
  ) values (
    v_run.id, v_run.release_version, 'global', 'public', 'public', 'current', true,
    v_approval.id, v_approval.approval_hash, v_run.publish_plan_hash,
    v_run.release_manifest_hash, v_run.artifact_set_hash,
    v_approval.approved_by, v_actor, p_credential_fingerprint,
    trim(p_idempotency_key), v_now, nullif(trim(coalesce(p_reason, '')), '')
  )
  returning * into v_publication;

  if v_previous.id is not null then
    update public.lca_release_publications
    set superseded_by = v_publication.id,
        updated_at = v_now
    where id = v_previous.id;
  end if;

  update public.lca_release_approvals
  set status = 'consumed', consumed_by = v_actor, consumed_at = v_now
  where id = v_approval.id;

  update public.lca_release_artifacts
  set pinned = true, published_at = v_now
  where release_run_id = v_run.id;

  update public.lca_release_runs
  set status = 'published', published_at = v_now, updated_at = v_now
  where id = v_run.id;

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_publish', v_actor, 'lca_release_publications', v_publication.id,
    v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'releaseRunId', v_run.id,
      'approvalId', v_approval.id,
      'approvalHash', v_approval.approval_hash,
      'publishPlanHash', v_run.publish_plan_hash,
      'releaseManifestHash', v_run.release_manifest_hash,
      'artifactSetHash', v_run.artifact_set_hash,
      'approvedBy', v_approval.approved_by,
      'executedBy', v_actor,
      'credentialFingerprint', p_credential_fingerprint,
      'previousPublicationId', v_previous.id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'publicationId', v_publication.id,
      'releaseRunId', v_run.id,
      'releaseVersion', v_run.release_version,
      'status', 'current',
      'approvedBy', v_approval.approved_by,
      'executedBy', v_actor,
      'publishedAt', v_now
    )
  );
exception
  when unique_violation then
    return public.lca_release_error('publication_conflict', 409, 'Release version or publish idempotency key already has a publication');
end;
$_$;


ALTER FUNCTION public.cmd_lca_release_publish(p_release_run_id uuid, p_approval_id uuid, p_approval_hash text, p_publish_plan_hash text, p_idempotency_key text, p_credential_fingerprint text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_readback_verify(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lca_release_readback_verify(p_release_run_id uuid, p_release_manifest_hash text, p_artifact_hashes jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_run public.lca_release_runs%rowtype;
  v_mismatch_count integer;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return public.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lca_release_is_manager() then
    return public.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if jsonb_typeof(coalesce(p_artifact_hashes, 'null'::jsonb)) <> 'array' then
    return public.lca_release_error('invalid_readback_payload', 400, 'artifactHashes must be a JSON array');
  end if;

  select * into v_run
  from public.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return public.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  if v_run.status not in ('published', 'readback_verified') then
    return public.lca_release_error('release_not_published', 409, 'Release must be published before readback verification');
  end if;
  if v_run.release_manifest_hash <> p_release_manifest_hash then
    return public.lca_release_error('readback_manifest_hash_mismatch', 409, 'Readback release manifest hash differs from the published value');
  end if;
  if jsonb_array_length(p_artifact_hashes) <> 4 then
    return public.lca_release_error('readback_artifacts_incomplete', 409, 'Readback must verify all four release artifacts');
  end if;

  with expected as (
    select id::text as artifact_id, sha256
    from public.lca_release_artifacts
    where release_run_id = v_run.id
  ),
  observed as (
    select value->>'artifactId' as artifact_id, value->>'sha256' as sha256
    from jsonb_array_elements(p_artifact_hashes)
  )
  select count(*) into v_mismatch_count
  from expected
  full join observed using (artifact_id)
  where expected.artifact_id is null
     or observed.artifact_id is null
     or expected.sha256 is distinct from observed.sha256;

  if v_mismatch_count <> 0 then
    return public.lca_release_error('readback_artifact_hash_mismatch', 409, 'Readback artifact hashes differ from published immutable refs');
  end if;

  update public.lca_release_runs
  set status = 'readback_verified',
      readback_verified_at = coalesce(readback_verified_at, v_now),
      readback_receipt = jsonb_build_object(
        'releaseManifestHash', p_release_manifest_hash,
        'artifactHashes', p_artifact_hashes,
        'verifiedBy', v_actor,
        'verifiedAt', v_now
      ),
      updated_at = v_now
  where id = v_run.id;

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_readback_verify', v_actor, 'lca_release_runs', v_run.id,
    v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'releaseManifestHash', p_release_manifest_hash,
      'artifactCount', jsonb_array_length(p_artifact_hashes)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'releaseRunId', v_run.id,
      'status', 'readback_verified',
      'releaseManifestHash', p_release_manifest_hash,
      'verifiedAt', v_now
    )
  );
end;
$$;


ALTER FUNCTION public.cmd_lca_release_readback_verify(p_release_run_id uuid, p_release_manifest_hash text, p_artifact_hashes jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_unpublish(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lca_release_unpublish(p_publication_id uuid, p_reason text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_publication public.lca_release_publications%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return public.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lca_release_is_manager() then
    return public.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    return public.lca_release_error('reason_required', 400, 'Unpublish requires an audit reason');
  end if;

  select * into v_publication
  from public.lca_release_publications
  where id = p_publication_id
  for update;

  if v_publication.id is null then
    return public.lca_release_error('publication_not_found', 404, 'Publication not found');
  end if;
  if v_publication.status = 'unpublished' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', jsonb_build_object('publicationId', v_publication.id, 'status', 'unpublished')
    );
  end if;
  if not v_publication.is_current or v_publication.status <> 'current' then
    return public.lca_release_error('publication_not_current', 409, 'Only the current publication can be unpublished');
  end if;

  update public.lca_release_publications
  set status = 'unpublished', is_current = false, unpublished_by = v_actor,
      unpublished_at = v_now, reason = p_reason, updated_at = v_now
  where id = v_publication.id;

  update public.lca_release_runs
  set status = 'unpublished', updated_at = v_now
  where id = v_publication.release_run_id;

  insert into public.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_unpublish', v_actor, 'lca_release_publications',
    v_publication.id, v_publication.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('reason', p_reason)
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object('publicationId', v_publication.id, 'status', 'unpublished')
  );
end;
$$;


ALTER FUNCTION public.cmd_lca_release_unpublish(p_publication_id uuid, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request(text, jsonb, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_build_request(p_name text, p_processes jsonb DEFAULT NULL::jsonb, p_coverage_mode text DEFAULT 'global_eligible'::text, p_default_impact_category text DEFAULT NULL::text, p_lcia_method_set jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce((select require_certificate_for_builds from public.lcia_scope_closure_config where singleton), false) then
    return public.lcia_scope_closure_error('closure_check_required', 409, 'A valid scope-closure certificate is required');
  end if;
  return public.cmd_lcia_result_build_request_legacy(p_name, p_processes, p_coverage_mode, p_default_impact_category, p_lcia_method_set, p_idempotency_key, p_audit);
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_build_request(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_legacy(text, jsonb, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_build_request_legacy(p_name text, p_processes jsonb DEFAULT NULL::jsonb, p_coverage_mode text DEFAULT 'global_eligible'::text, p_default_impact_category text DEFAULT NULL::text, p_lcia_method_set jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_coverage_mode text := lower(trim(coalesce(p_coverage_mode, 'global_eligible')));
  v_build_id uuid;
  v_idempotency_key text;
  v_current_manifest jsonb;
  v_input_manifest jsonb;
  v_input_manifest_hash text;
  v_eligible_input_count integer;
  v_included_input_count integer;
  v_invalid_count integer := 0;
  v_duplicate_count integer := 0;
  v_request_hash text;
  v_worker_payload jsonb;
  v_worker_job jsonb;
begin
  if v_actor is null then
    return public.lcia_result_error('auth_required', 401, 'Authentication required');
  end if;

  if not public.lcia_result_is_manager() then
    return public.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  if v_coverage_mode not in ('subset', 'global_eligible') then
    return public.lcia_result_error('invalid_coverage_mode', 400, 'coverage_mode must be subset or global_eligible');
  end if;

  if v_coverage_mode = 'global_eligible'
     and p_processes is not null
     and jsonb_array_length(p_processes) > 0 then
    return public.lcia_result_error('invalid_coverage_mode', 400, 'global_eligible builds are resolved from the current published input predicate');
  end if;

  if jsonb_typeof(coalesce(p_lcia_method_set, '[]'::jsonb)) <> 'array' then
    return public.lcia_result_error('invalid_lcia_method_set', 400, 'lcia_method_set must be a JSON array');
  end if;

  if p_processes is not null and jsonb_typeof(p_processes) <> 'array' then
    return public.lcia_result_error('invalid_process_selection', 400, 'process selection must be a JSON array');
  end if;

  v_current_manifest := public.lcia_result_current_eligible_manifest();
  v_eligible_input_count := (v_current_manifest->>'eligibleInputCount')::integer;

  if v_coverage_mode = 'global_eligible' then
    v_input_manifest := v_current_manifest->'inputManifest';
    v_input_manifest_hash := v_current_manifest->>'inputManifestHash';
    v_included_input_count := v_eligible_input_count;
  else
    with requested as (
      select
        (item.value->>'id')::uuid as process_id,
        coalesce(item.value->>'version', item.value->>'process_version')::character(9) as process_version,
        item.ordinality::integer as ordinal
      from jsonb_array_elements(coalesce(p_processes, '[]'::jsonb)) with ordinality as item(value, ordinality)
    ),
    duplicate_rows as (
      select process_id, process_version, count(*)::integer as duplicate_count
      from requested
      group by process_id, process_version
      having count(*) > 1
    ),
    resolved as (
      select
        r.process_id,
        r.process_version,
        r.ordinal,
        p.state_code
      from requested as r
      left join public.processes as p
        on p.id = r.process_id
       and p.version = r.process_version
    ),
    aggregated as (
      select
        count(*) filter (where state_code between 100 and 199)::integer as included_count,
        count(*) filter (where state_code is null or state_code not between 100 and 199)::integer as invalid_count,
        coalesce((select sum(duplicate_count - 1)::integer from duplicate_rows), 0) as duplicate_count,
        md5(
          coalesce(
            string_agg(
              process_id::text || ':' || process_version,
              ','
              order by process_id, process_version
            ) filter (where state_code between 100 and 199),
            ''
          ) || '|published:100-199:v1'
        ) as manifest_hash,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', process_id,
              'version', process_version,
              'stateCode', state_code
            )
            order by ordinal
          ) filter (where state_code between 100 and 199),
          '[]'::jsonb
        ) as selected_processes
      from resolved
    )
    select
      included_count,
      invalid_count,
      duplicate_count,
      manifest_hash,
      jsonb_build_object(
        'predicateVersion', 'published-state-code-100-199:v1',
        'selectionMode', 'manual',
        'processes', selected_processes
      )
    into
      v_included_input_count,
      v_invalid_count,
      v_duplicate_count,
      v_input_manifest_hash,
      v_input_manifest
    from aggregated;

    if v_duplicate_count > 0 then
      return public.lcia_result_error('invalid_process_selection', 400, 'process selection contains duplicate inputs');
    end if;

    if v_invalid_count > 0 then
      return public.lcia_result_error('input_not_eligible', 400, 'All LCIA result package inputs must be published process rows');
    end if;
  end if;

  if coalesce(v_included_input_count, 0) = 0 then
    return public.lcia_result_error('input_empty', 400, 'LCIA result package build requires at least one eligible process');
  end if;

  v_idempotency_key := 'lcia_result.package_build:' || coalesce(
    nullif(trim(coalesce(p_idempotency_key, '')), ''),
    gen_random_uuid()::text
  );

  if nullif(trim(coalesce(p_idempotency_key, '')), '') is not null then
    v_build_id := (
      substr(md5(v_actor::text || ':' || p_idempotency_key), 1, 8) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 9, 4) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 13, 4) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 17, 4) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 21, 12)
    )::uuid;
  else
    v_build_id := gen_random_uuid();
  end if;

  v_request_hash := md5(
    v_input_manifest_hash || '|' ||
    coalesce(p_default_impact_category, '') || '|' ||
    coalesce(p_lcia_method_set::text, '[]')
  );

  v_worker_payload := jsonb_build_object(
    'type', 'lcia_result_package_build',
    'build_id', v_build_id,
    'requested_by', v_actor,
    'name', nullif(trim(coalesce(p_name, '')), ''),
    'coverage_mode', v_coverage_mode,
    'input_status_filter', v_current_manifest->'inputStatusFilter',
    'eligibility_definition', v_current_manifest - 'eligibleInputCount' - 'includedInputCount' - 'inputManifestHash' - 'inputManifest',
    'eligibility_resolved_at', now(),
    'eligible_input_count', v_eligible_input_count,
    'included_input_count', v_included_input_count,
    'input_manifest_hash', v_input_manifest_hash,
    'input_manifest', v_input_manifest,
    'lcia_method_set', coalesce(p_lcia_method_set, '[]'::jsonb),
    'default_impact_category', nullif(trim(coalesce(p_default_impact_category, '')), ''),
    'postprocess_manifest', jsonb_build_object(
      'postprocess_mode', 'skipped',
      'postprocess_reason', 'MVP does not aggregate process results'
    )
  );

  v_worker_job := jsonb_build_object(
    'jobKind', 'lcia_result.package_build',
    'payload', v_worker_payload,
    'payloadSchemaVersion', 'lcia_result.package_build.request.v1',
    'subjectType', 'lcia_result_build',
    'subjectId', v_build_id,
    'subjectVersion', null,
    'requestedBy', v_actor,
    'requesterType', 'operator',
    'idempotencyKey', v_idempotency_key,
    'requestHash', v_request_hash,
    'queueKey', v_build_id,
    'visibility', 'operator'
  );

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_lcia_result_build_request',
    v_actor,
    'worker_jobs',
    v_build_id,
    null,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'coverageMode', v_coverage_mode,
      'eligibleInputCount', v_eligible_input_count,
      'includedInputCount', v_included_input_count,
      'inputManifestHash', v_input_manifest_hash
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'buildId', v_build_id,
      'coverageMode', v_coverage_mode,
      'eligibleInputCount', v_eligible_input_count,
      'includedInputCount', v_included_input_count,
      'inputManifestHash', v_input_manifest_hash,
      'workerJob', v_worker_job
    ),
    'reused', false
  );
exception
  when invalid_text_representation then
    return public.lcia_result_error('invalid_process_selection', 400, 'process ids and versions must be valid');
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_build_request_legacy(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v2(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_build_request_v2(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_check public.lcia_scope_closure_checks%rowtype;
begin
  if v_actor is null then
    return public.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  select * into v_check
  from public.lcia_scope_closure_checks
  where id = p_closure_check_id
    and requested_by = v_actor;
  if v_check.id is null then
    return public.lcia_scope_closure_error(
      'closure_check_not_found', 404, 'Closure check not found'
    );
  end if;
  if v_check.valid_until <= now()
     or exists (
       select 1
       from public.worker_job_artifacts artifact
       where artifact.id in (
         v_check.report_artifact_id,
         v_check.complete_machine_result_artifact_id,
         v_check.closure_bundle_artifact_id
       )
         and (
           artifact.lifecycle_state in ('expired', 'deleted')
           or artifact.expires_at <= now()
         )
     ) then
    return public.lcia_scope_closure_error(
      'closure_certificate_expired', 410, 'Closure certificate evidence has expired'
    );
  end if;
  if not public.lcia_scope_closure_evidence_usable(v_check) then
    return public.lcia_scope_closure_error(
      'closure_check_not_usable', 409, 'Closure certificate evidence is not usable'
    );
  end if;

  return public.cmd_lcia_result_build_request_v2_without_expiry(
    p_name,
    p_processes,
    p_coverage_mode,
    p_default_impact_category,
    p_lcia_method_set,
    p_idempotency_key,
    p_closure_check_id,
    p_requested_scope_hash,
    p_policy_fingerprint,
    p_audit
  );
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_build_request_v2(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v2_envelope(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_build_request_v2_envelope(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_check public.lcia_scope_closure_checks%rowtype; v_result jsonb; v_effective jsonb; v_payload jsonb;
begin
  if v_actor is null then return public.lcia_scope_closure_error('auth_required',401,'Authentication required'); end if;
  select * into v_check from public.lcia_scope_closure_checks where id=p_closure_check_id and requested_by=v_actor;
  if v_check.id is null then return public.lcia_scope_closure_error('closure_check_not_found',404,'Closure check not found'); end if;
  if v_check.certificate_status='stale' then return public.lcia_scope_closure_error('closure_check_stale',409,'Closure certificate is stale'); end if;
  if v_check.certificate_status='revoked' then return public.lcia_scope_closure_error('closure_check_revoked',409,'Closure certificate is revoked'); end if;
  if v_check.status<>'passed' or v_check.scan_completeness<>'complete' or v_check.certificate_status<>'valid' or v_check.certificate_hash is null then return public.lcia_scope_closure_error('closure_check_not_usable',409,'A valid complete closure certificate is required'); end if;
  if v_check.requested_scope_hash<>trim(coalesce(p_requested_scope_hash,'')) then return public.lcia_scope_closure_error('closure_check_scope_mismatch',409,'Requested scope does not match the closure certificate'); end if;
  if v_check.policy_fingerprint<>trim(coalesce(p_policy_fingerprint,'')) then return public.lcia_scope_closure_error('closure_check_policy_mismatch',409,'Policy does not match the closure certificate'); end if;
  v_effective:=coalesce(v_check.effective_scope_manifest,v_check.requested_scope_manifest);
  v_result:=public.cmd_lcia_result_build_request_legacy(p_name,v_effective->'processes','subset',p_default_impact_category,v_effective->'lciaMethods',p_idempotency_key,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('closureCheckId',v_check.id,'requestedScopeHash',v_check.requested_scope_hash,'policyFingerprint',v_check.policy_fingerprint,'certificateHash',v_check.certificate_hash));
  v_payload:=(v_result->'data'->'workerJob'->'payload') || jsonb_build_object('coverage_mode',v_effective->>'coverageMode','input_manifest',jsonb_build_object('predicateVersion',v_effective->>'eligibilityPredicateVersion','selectionMode','closure_certificate','processes',v_effective->'processes'),'input_manifest_hash',public.lcia_scope_closure_sha256(jsonb_build_object('processes',v_effective->'processes')),'lcia_method_set',v_effective->'lciaMethods','closure_check_id',v_check.id,'closure_certificate_hash',v_check.certificate_hash,'effective_scope_hash',v_check.effective_scope_hash,'data_snapshot_token',v_check.data_snapshot_token,'snapshot_id',v_check.snapshot_id,'snapshot_hash',v_check.snapshot_hash,'closure_bundle_hash',v_check.closure_bundle_hash,'report_artifact_manifest_hash',v_check.report_artifact_manifest_hash);
  return jsonb_set(v_result,'{data,workerJob,payload}',v_payload,true) || jsonb_build_object('closureCheckId',v_check.id,'effectiveScopeHash',v_check.effective_scope_hash,'certificateHash',v_check.certificate_hash);
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_build_request_v2_envelope(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v2_without_expiry(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_build_request_v2_without_expiry(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_check public.lcia_scope_closure_checks%rowtype;
  v_snapshot public.lca_network_snapshots%rowtype;
  v_artifact public.lca_snapshot_artifacts%rowtype;
  v_bundle public.worker_job_artifacts%rowtype;
  v_report public.worker_job_artifacts%rowtype;
  v_result jsonb;
  v_kind public.worker_job_kinds%rowtype;
  v_job public.worker_jobs%rowtype;
  v_build_id uuid;
  v_payload jsonb;
  v_input_manifest jsonb;
  v_report_manifest_hash text;
  v_idempotency_key text;
begin
  if v_actor is null then
    return public.lcia_scope_closure_error('auth_required', 401, 'Authentication required');
  end if;
  select * into v_check
  from public.lcia_scope_closure_checks
  where id = p_closure_check_id and requested_by = v_actor
  for share;
  if v_check.id is null then
    return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if v_check.certificate_status = 'stale' then
    return public.lcia_scope_closure_error('closure_check_stale', 409, 'Closure certificate is stale');
  end if;
  if v_check.certificate_status = 'revoked' then
    return public.lcia_scope_closure_error('closure_check_revoked', 409, 'Closure certificate is revoked');
  end if;
  if v_check.status <> 'passed'
     or v_check.scan_completeness <> 'complete'
     or v_check.certificate_status <> 'valid'
     or v_check.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
     or v_check.certificate_hash is null then
    return public.lcia_scope_closure_error('closure_check_not_usable', 409, 'A valid complete numerical snapshot certificate is required');
  end if;
  if v_check.requested_scope_hash <> trim(coalesce(p_requested_scope_hash, '')) then
    return public.lcia_scope_closure_error('closure_check_scope_mismatch', 409, 'Requested scope does not match the closure certificate');
  end if;
  if v_check.policy_fingerprint <> trim(coalesce(p_policy_fingerprint, '')) then
    return public.lcia_scope_closure_error('closure_check_policy_mismatch', 409, 'Policy does not match the closure certificate');
  end if;
  if v_check.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
     and not public.lcia_scope_closure_current_release_matches(v_check.data_snapshot_token) then
    return public.lcia_scope_closure_error('closure_check_stale', 409, 'Closure certificate was created against an earlier public release');
  end if;

  select * into v_snapshot
  from public.lca_network_snapshots
  where id = v_check.snapshot_id;
  select * into v_artifact
  from public.lca_snapshot_artifacts
  where id = v_check.snapshot_artifact_id;
  select * into v_bundle
  from public.worker_job_artifacts
  where id = v_check.closure_bundle_artifact_id;
  select * into v_report
  from public.worker_job_artifacts
  where id = v_check.report_artifact_id;
  v_report_manifest_hash := public.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_artifact.id is null
     or v_artifact.snapshot_id <> v_snapshot.id
     or v_artifact.status <> 'ready'
     or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_artifact.artifact_sha256 <> v_check.snapshot_hash
     or v_artifact.snapshot_index_sha256 <> v_check.snapshot_index_sha256
     or v_artifact.snapshot_build_contract_hash <> v_check.snapshot_build_contract_hash
     or v_artifact.effective_scope_hash <> v_check.effective_scope_hash
     or v_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_artifact.closure_bundle_hash <> v_check.closure_bundle_hash
     or v_bundle.id is null
     or v_bundle.job_id <> v_check.worker_job_id
     or v_bundle.artifact_type <> 'closure_bundle'
     or v_bundle.checksum_sha256 <> v_check.closure_bundle_hash
     or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_check.id::text
     or v_report.id is null
     or v_report.job_id <> v_check.worker_job_id
     or v_report.artifact_type <> 'closure_report_xlsx'
     or v_report_manifest_hash <> v_check.report_artifact_manifest_hash then
    return public.lcia_scope_closure_error('closure_snapshot_binding_invalid', 409, 'Numerical snapshot certificate binding is not ready');
  end if;

  v_result := public.cmd_lcia_result_build_request_v2_envelope(
    p_name, p_processes, p_coverage_mode, p_default_impact_category,
    p_lcia_method_set, p_idempotency_key, p_closure_check_id,
    p_requested_scope_hash, p_policy_fingerprint, p_audit
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then return v_result; end if;
  v_build_id := nullif(v_result->'data'->>'buildId', '')::uuid;
  select * into v_kind
  from public.worker_job_kinds
  where job_kind = 'lcia_result.package_build';
  if v_build_id is null or v_kind.job_kind is null then
    return public.lcia_scope_closure_error('build_enqueue_unavailable', 503, 'Build queue configuration is unavailable');
  end if;

  v_input_manifest := jsonb_build_object(
    'predicateVersion', v_check.effective_scope_manifest->>'eligibilityPredicateVersion',
    'selectionMode', 'closure_certificate',
    'processes', v_check.effective_scope_manifest->'processes'
  );
  v_payload := coalesce(v_result->'data'->'workerJob'->'payload', '{}'::jsonb)
    || jsonb_build_object(
      'coverage_mode', v_check.effective_scope_manifest->>'coverageMode',
      'input_manifest', v_input_manifest,
      'input_manifest_hash', public.lcia_scope_closure_sha256(v_input_manifest),
      'lcia_method_set', v_check.effective_scope_manifest->'lciaMethods',
      'closure_check_id', v_check.id,
      'closure_certificate_hash', v_check.certificate_hash,
      'requested_scope_hash', v_check.requested_scope_hash,
      'policy_fingerprint', v_check.policy_fingerprint,
      'effective_scope_hash', v_check.effective_scope_hash,
      'data_snapshot_token', v_check.data_snapshot_token,
      'snapshot_id', v_check.snapshot_id,
      'snapshot_hash', v_check.snapshot_hash,
      'closure_bundle_artifact_id', v_check.closure_bundle_artifact_id,
      'closure_bundle_hash', v_check.closure_bundle_hash,
      'report_artifact_manifest_hash', v_check.report_artifact_manifest_hash,
      'snapshot_artifact_id', v_check.snapshot_artifact_id,
      'snapshot_index_sha256', v_check.snapshot_index_sha256,
      'snapshot_build_contract_hash', v_check.snapshot_build_contract_hash,
      'effective_scope', v_check.effective_scope_manifest
    );
  v_idempotency_key := nullif(v_result->'data'->'workerJob'->>'idempotencyKey', '');
  select * into v_job
  from public.worker_jobs
  where worker_runtime = v_kind.worker_runtime
    and job_kind = v_kind.job_kind
    and requested_by = v_actor
    and idempotency_key is not distinct from v_idempotency_key
    and status in ('queued', 'running', 'waiting', 'stale', 'blocked')
  order by created_at desc limit 1
  for update;
  if v_job.id is null then
    insert into public.worker_jobs(
      job_kind, worker_runtime, worker_queue, priority, queue_key,
      subject_type, subject_id, requester_type, requested_by,
      idempotency_key, request_hash, concurrency_key, visibility,
      max_attempts, payload_schema_version, payload_json, payload_ref,
      result_schema_version
    ) values (
      v_kind.job_kind, v_kind.worker_runtime, v_kind.worker_queue,
      v_kind.default_priority, nullif(v_result->'data'->'workerJob'->>'queueKey', ''),
      'lcia_result_build', v_build_id, 'operator', v_actor,
      v_idempotency_key, nullif(v_result->'data'->'workerJob'->>'requestHash', ''),
      nullif(v_result->'data'->'workerJob'->>'queueKey', ''), 'operator',
      v_kind.default_max_attempts, 'lcia_result.package_build.request.v2',
      v_payload,
      jsonb_build_object('closureCertificate', jsonb_build_object(
        'closureCheckId', v_check.id,
        'certificateHash', v_check.certificate_hash,
        'requestedScopeHash', v_check.requested_scope_hash,
        'policyFingerprint', v_check.policy_fingerprint,
        'effectiveScopeHash', v_check.effective_scope_hash,
        'dataSnapshotToken', v_check.data_snapshot_token,
        'snapshotId', v_check.snapshot_id,
        'snapshotHash', v_check.snapshot_hash,
        'closureBundleArtifactId', v_check.closure_bundle_artifact_id,
        'closureBundleHash', v_check.closure_bundle_hash,
        'reportArtifactManifestHash', v_check.report_artifact_manifest_hash,
        'snapshotArtifactId', v_check.snapshot_artifact_id,
        'snapshotIndexSha256', v_check.snapshot_index_sha256,
        'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
        'effectiveScope', v_check.effective_scope_manifest
      )),
      v_kind.result_schema_version
    ) returning * into v_job;
    insert into public.worker_job_events(job_id, event_type, status, details)
    values(v_job.id, 'enqueued', v_job.status, jsonb_build_object(
      'jobKind', v_job.job_kind,
      'closureCheckId', v_check.id,
      'certificateHash', v_check.certificate_hash,
      'snapshotId', v_check.snapshot_id
    ));
  elsif v_job.payload_schema_version <> 'lcia_result.package_build.request.v2'
        or v_job.payload_json <> v_payload then
    return public.lcia_scope_closure_error('build_enqueue_conflict', 409, 'Existing active build does not match the certificate-bound V2 payload');
  end if;
  return jsonb_set(
    jsonb_set(v_result, '{data,workerJob}', public.worker_job_payload(v_job, false), true),
    '{data,workerJobId}', to_jsonb(v_job.id), true
  );
exception
  when unique_violation then
    return public.lcia_scope_closure_error('build_enqueue_conflict', 409, 'A conflicting certificate-bound build is already active');
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_build_request_v2_without_expiry(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_package_mark_ready(uuid, text, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_package_mark_ready(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid DEFAULT NULL::uuid, p_result_artifact_ref jsonb DEFAULT '{}'::jsonb, p_query_artifact_ref jsonb DEFAULT '{}'::jsonb, p_artifact_manifest jsonb DEFAULT '{}'::jsonb, p_available_impact_categories jsonb DEFAULT '[]'::jsonb, p_default_impact_category text DEFAULT NULL::text, p_package_result_hash text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_check public.lcia_scope_closure_checks%rowtype;
  v_snapshot public.lca_network_snapshots%rowtype;
  v_artifact public.lca_snapshot_artifacts%rowtype;
  v_closure_check_id uuid;
  v_binding jsonb;
begin
  if not public.lcia_result_is_service_request() then
    return public.lcia_result_error('service_role_required', 403, 'Service role is required to mark LCIA result packages ready');
  end if;
  select * into v_job
  from public.worker_jobs
  where id = p_build_worker_job_id
  for update;
  if v_job.id is null or v_job.job_kind <> 'lcia_result.package_build' then
    return public.lcia_result_error('build_worker_job_not_found', 404, 'LCIA result package build worker job not found');
  end if;
  if v_job.payload_schema_version <> 'lcia_result.package_build.request.v2' then
    return public.cmd_lcia_result_package_mark_ready_without_closure_recheck(
      p_build_worker_job_id, p_package_version, p_snapshot_id, p_result_id,
      p_latest_all_unit_result_id, p_result_artifact_ref, p_query_artifact_ref,
      p_artifact_manifest, p_available_impact_categories,
      p_default_impact_category, p_package_result_hash, p_audit
    );
  end if;
  if v_job.status <> 'running'
     or v_job.lease_token is null
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return public.lcia_result_error('build_worker_job_lease_invalid', 409, 'Build job does not hold a current running lease');
  end if;
  begin
    v_closure_check_id := nullif(v_job.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    return public.lcia_result_error('closure_certificate_binding_mismatch', 409, 'Build payload contains an invalid closure check identity');
  end;
  select * into v_check
  from public.lcia_scope_closure_checks
  where id = v_closure_check_id
  for share;
  if v_check.id is null then
    return public.lcia_result_error('closure_check_not_usable', 409, 'Closure certificate is not available');
  end if;
  if v_check.certificate_status = 'revoked' then
    return public.lcia_result_error('closure_check_revoked', 409, 'Closure certificate was revoked before package readiness');
  end if;
  if v_check.certificate_status = 'stale' then
    return public.lcia_result_error('closure_check_stale', 409, 'Closure certificate became stale before package readiness');
  end if;
  if v_check.status <> 'passed'
     or v_check.scan_completeness <> 'complete'
     or v_check.certificate_status <> 'valid'
     or v_check.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
     or v_check.requested_by <> v_job.requested_by then
    return public.lcia_result_error('closure_check_not_usable', 409, 'Closure certificate is no longer usable');
  end if;
  if v_check.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
     and not public.lcia_scope_closure_current_release_matches(v_check.data_snapshot_token) then
    return public.lcia_result_error('closure_check_stale', 409, 'Closure certificate was created against an earlier public release');
  end if;
  v_binding := public.svc_lcia_scope_closure_build_binding(p_build_worker_job_id);
  if coalesce((v_binding->>'ok')::boolean, false) is not true then
    return public.lcia_result_error('closure_certificate_binding_mismatch', 409, 'Build payload or persisted evidence no longer matches the numerical snapshot certificate');
  end if;
  select * into v_snapshot
  from public.lca_network_snapshots
  where id = v_check.snapshot_id;
  select * into v_artifact
  from public.lca_snapshot_artifacts
  where id = v_check.snapshot_artifact_id;
  if p_snapshot_id <> v_check.snapshot_id
     or v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_artifact.id is null
     or v_artifact.snapshot_id <> v_snapshot.id
     or v_artifact.status <> 'ready'
     or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_artifact.artifact_sha256 <> v_check.snapshot_hash
     or v_artifact.snapshot_index_sha256 <> v_check.snapshot_index_sha256
     or v_artifact.snapshot_build_contract_hash <> v_check.snapshot_build_contract_hash
     or v_artifact.effective_scope_hash <> v_check.effective_scope_hash
     or v_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_artifact.closure_bundle_hash <> v_check.closure_bundle_hash
     or coalesce(v_job.payload_json->>'closure_certificate_hash', '') <> v_check.certificate_hash
     or coalesce(v_job.payload_json->>'snapshot_id', '') <> v_check.snapshot_id::text
     or coalesce(v_job.payload_json->>'snapshot_hash', '') <> v_check.snapshot_hash
     or coalesce(v_job.payload_json->>'snapshot_artifact_id', '') <> v_check.snapshot_artifact_id::text
     or coalesce(v_job.payload_json->>'snapshot_index_sha256', '') <> v_check.snapshot_index_sha256
     or coalesce(v_job.payload_json->>'snapshot_build_contract_hash', '') <> v_check.snapshot_build_contract_hash
     or coalesce(v_job.payload_json->'effective_scope', 'null'::jsonb) <> v_check.effective_scope_manifest
     or coalesce(v_job.payload_json->'input_manifest'->'processes', 'null'::jsonb)
          <> coalesce(v_check.effective_scope_manifest->'processes', 'null'::jsonb) then
    return public.lcia_result_error('closure_certificate_binding_mismatch', 409, 'Build result does not match the current numerical snapshot certificate');
  end if;
  return public.cmd_lcia_result_package_mark_ready_without_closure_recheck(
    p_build_worker_job_id, p_package_version, p_snapshot_id, p_result_id,
    p_latest_all_unit_result_id, p_result_artifact_ref, p_query_artifact_ref,
    p_artifact_manifest, p_available_impact_categories,
    p_default_impact_category, p_package_result_hash, p_audit
  );
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_package_mark_ready(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid, p_result_artifact_ref jsonb, p_query_artifact_ref jsonb, p_artifact_manifest jsonb, p_available_impact_categories jsonb, p_default_impact_category text, p_package_result_hash text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_package_mark_ready_without_closure_recheck(uuid, text, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_package_mark_ready_without_closure_recheck(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid DEFAULT NULL::uuid, p_result_artifact_ref jsonb DEFAULT '{}'::jsonb, p_query_artifact_ref jsonb DEFAULT '{}'::jsonb, p_artifact_manifest jsonb DEFAULT '{}'::jsonb, p_available_impact_categories jsonb DEFAULT '[]'::jsonb, p_default_impact_category text DEFAULT NULL::text, p_package_result_hash text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_result public.lca_results%rowtype;
  v_latest public.lca_latest_all_unit_results%rowtype;
  v_package public.lcia_result_packages%rowtype;
  v_result_artifact_ref jsonb;
  v_query_artifact_ref jsonb;
  v_default_impact text;
begin
  if not public.lcia_result_is_service_request() then
    return public.lcia_result_error('service_role_required', 403, 'Service role is required to mark LCIA result packages ready');
  end if;

  if jsonb_typeof(coalesce(p_result_artifact_ref, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_query_artifact_ref, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_artifact_manifest, '{}'::jsonb)) <> 'object' then
    return public.lcia_result_error('invalid_artifact_payload', 400, 'artifact payloads must be JSON objects');
  end if;

  if jsonb_typeof(coalesce(p_available_impact_categories, '[]'::jsonb)) <> 'array' then
    return public.lcia_result_error('invalid_available_impact_categories', 400, 'available impact categories must be a JSON array');
  end if;

  select *
    into v_job
  from public.worker_jobs
  where id = p_build_worker_job_id
  for update;

  if v_job.id is null or v_job.job_kind <> 'lcia_result.package_build' then
    return public.lcia_result_error('build_worker_job_not_found', 404, 'LCIA result package build worker job not found');
  end if;

  select *
    into v_result
  from public.lca_results
  where id = p_result_id;

  if v_result.id is null then
    return public.lcia_result_error('result_not_found', 404, 'LCIA result artifact row not found');
  end if;

  if p_latest_all_unit_result_id is not null then
    select *
      into v_latest
    from public.lca_latest_all_unit_results
    where id = p_latest_all_unit_result_id;

    if v_latest.id is null then
      return public.lcia_result_error('latest_all_unit_result_not_found', 404, 'Latest all-unit LCIA result row not found');
    end if;
  end if;

  v_result_artifact_ref := case
    when coalesce(p_result_artifact_ref, '{}'::jsonb) <> '{}'::jsonb then p_result_artifact_ref
    else jsonb_strip_nulls(
      jsonb_build_object(
        'artifactUrl', v_result.artifact_url,
        'artifactSha256', v_result.artifact_sha256,
        'artifactByteSize', v_result.artifact_byte_size,
        'artifactFormat', v_result.artifact_format
      )
    )
  end;

  v_query_artifact_ref := case
    when coalesce(p_query_artifact_ref, '{}'::jsonb) <> '{}'::jsonb then p_query_artifact_ref
    when v_latest.id is not null then jsonb_strip_nulls(
      jsonb_build_object(
        'artifactUrl', v_latest.query_artifact_url,
        'artifactSha256', v_latest.query_artifact_sha256,
        'artifactByteSize', v_latest.query_artifact_byte_size,
        'artifactFormat', v_latest.query_artifact_format
      )
    )
    else '{}'::jsonb
  end;

  if v_result_artifact_ref = '{}'::jsonb then
    return public.lcia_result_error('result_artifact_missing', 400, 'LCIA result package requires a persisted result artifact reference');
  end if;

  v_default_impact := coalesce(
    nullif(trim(coalesce(p_default_impact_category, '')), ''),
    nullif(trim(coalesce(v_job.payload_json->>'default_impact_category', '')), '')
  );

  insert into public.lcia_result_packages (
    build_id,
    build_worker_job_id,
    package_version,
    coverage_mode,
    input_status_filter,
    eligibility_definition,
    eligibility_resolved_at,
    eligible_input_count,
    included_input_count,
    input_manifest_hash,
    input_manifest,
    snapshot_id,
    result_id,
    latest_all_unit_result_id,
    result_artifact_ref,
    query_artifact_ref,
    artifact_manifest,
    package_result_hash,
    lcia_method_set,
    available_impact_categories,
    postprocess_manifest,
    default_impact_category,
    status,
    created_by
  )
  values (
    (v_job.payload_json->>'build_id')::uuid,
    v_job.id,
    nullif(trim(coalesce(p_package_version, '')), ''),
    v_job.payload_json->>'coverage_mode',
    coalesce(v_job.payload_json->'input_status_filter', '{"state_code":{"between":[100,199]}}'::jsonb),
    coalesce(v_job.payload_json->'eligibility_definition', '{}'::jsonb),
    coalesce((v_job.payload_json->>'eligibility_resolved_at')::timestamptz, now()),
    coalesce((v_job.payload_json->>'eligible_input_count')::integer, 0),
    coalesce((v_job.payload_json->>'included_input_count')::integer, 0),
    nullif(v_job.payload_json->>'input_manifest_hash', ''),
    coalesce(v_job.payload_json->'input_manifest', '{}'::jsonb),
    p_snapshot_id,
    v_result.id,
    v_latest.id,
    v_result_artifact_ref,
    v_query_artifact_ref,
    coalesce(p_artifact_manifest, '{}'::jsonb),
    nullif(trim(coalesce(p_package_result_hash, '')), ''),
    coalesce(v_job.payload_json->'lcia_method_set', '[]'::jsonb),
    coalesce(p_available_impact_categories, '[]'::jsonb),
    coalesce(v_job.payload_json->'postprocess_manifest', '{"postprocess_mode":"skipped"}'::jsonb),
    v_default_impact,
    'preview_ready',
    v_job.requested_by
  )
  returning *
    into v_package;

  if v_job.status in ('queued', 'running', 'waiting', 'stale') then
    update public.worker_jobs
      set result_ref = coalesce(result_ref, '{}'::jsonb) || jsonb_build_object(
            'packageId', v_package.id,
            'packageVersion', v_package.package_version
          ),
          updated_at = now()
    where id = v_job.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'packageId', v_package.id,
      'packageVersion', v_package.package_version,
      'status', v_package.status,
      'buildWorkerJobId', v_package.build_worker_job_id,
      'includedInputCount', v_package.included_input_count
    )
  );
exception
  when unique_violation then
    return public.lcia_result_error('package_conflict', 409, 'LCIA result package already exists for this build or package version');
  when foreign_key_violation then
    return public.lcia_result_error('package_reference_invalid', 400, 'LCIA result package references invalid worker, snapshot, or result rows');
  when invalid_text_representation then
    return public.lcia_result_error('invalid_package_payload', 400, 'LCIA result package payload contains invalid ids or numeric values');
  when not_null_violation then
    return public.lcia_result_error('invalid_package_payload', 400, 'LCIA result package payload is missing required fields');
  when check_violation then
    return public.lcia_result_error('invalid_package_payload', 400, 'LCIA result package payload violates schema constraints');
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_package_mark_ready_without_closure_recheck(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid, p_result_artifact_ref jsonb, p_query_artifact_ref jsonb, p_artifact_manifest jsonb, p_available_impact_categories jsonb, p_default_impact_category text, p_package_result_hash text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_package_publish(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_package_publish(p_package_id uuid, p_display_default_impact_category text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_package public.lcia_result_packages%rowtype;
  v_current_manifest jsonb;
  v_default_impact text;
  v_previous_id uuid;
  v_publication public.lcia_result_publications%rowtype;
begin
  if v_actor is null then
    return public.lcia_result_error('auth_required', 401, 'Authentication required');
  end if;

  if not public.lcia_result_is_manager() then
    return public.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  select *
    into v_package
  from public.lcia_result_packages
  where id = p_package_id
  for update;

  if v_package.id is null or v_package.status <> 'preview_ready' then
    return public.lcia_result_error('package_not_ready', 400, 'Package must be preview_ready before publish');
  end if;

  if v_package.coverage_mode <> 'global_eligible'
     or v_package.included_input_count <> v_package.eligible_input_count then
    return public.lcia_result_error('package_not_global_eligible', 400, 'Only full global eligible packages can publish as global latest');
  end if;

  v_current_manifest := public.lcia_result_current_eligible_manifest();

  if v_package.eligible_input_count <> (v_current_manifest->>'eligibleInputCount')::integer
     or v_package.input_manifest_hash <> v_current_manifest->>'inputManifestHash' then
    return public.lcia_result_error('package_stale_eligibility', 409, 'Eligible process set changed after package creation');
  end if;

  v_default_impact := coalesce(
    nullif(trim(p_display_default_impact_category), ''),
    v_package.default_impact_category
  );

  if v_default_impact is null then
    return public.lcia_result_error('default_impact_missing', 400, 'Default impact category is required before publication');
  end if;

  if jsonb_array_length(v_package.available_impact_categories) > 0
     and not exists (
       select 1
       from jsonb_array_elements_text(v_package.available_impact_categories) as impact(value)
       where impact.value = v_default_impact
     ) then
    return public.lcia_result_error('default_impact_missing', 400, 'Default impact category is not present in the package impact category list');
  end if;

  if v_package.result_artifact_ref = '{}'::jsonb then
    return public.lcia_result_error('result_artifact_missing', 400, 'Package result artifact is required before publication');
  end if;

  lock table public.lcia_result_publications in exclusive mode;

  update public.lcia_result_publications
    set is_current = false,
        status = 'superseded',
        updated_at = now()
  where publication_series_key = 'global'
    and publication_channel = 'public'
    and visibility_scope = 'public'
    and is_current = true
  returning id
    into v_previous_id;

  insert into public.lcia_result_publications (
    package_id,
    publication_series_key,
    publication_channel,
    visibility_scope,
    is_current,
    status,
    display_default_impact_category,
    published_by,
    published_at,
    reason
  )
  values (
    v_package.id,
    'global',
    'public',
    'public',
    true,
    'current',
    v_default_impact,
    v_actor,
    now(),
    nullif(trim(coalesce(p_reason, '')), '')
  )
  returning *
    into v_publication;

  update public.lca_results
    set is_pinned = true
  where id = v_package.result_id;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_lcia_result_package_publish',
    v_actor,
    'lcia_result_publications',
    v_publication.id,
    v_package.package_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'packageId', v_package.id,
      'previousPublicationId', v_previous_id,
      'displayDefaultImpactCategory', v_default_impact
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'publicationId', v_publication.id,
      'packageId', v_package.id,
      'previousPublicationId', v_previous_id,
      'isCurrent', v_publication.is_current
    )
  );
exception
  when unique_violation then
    return public.lcia_result_error('latest_conflict', 409, 'Another current publication already exists');
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_package_publish(p_package_id uuid, p_display_default_impact_category text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_publication_unpublish(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_result_publication_unpublish(p_publication_id uuid, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_publication public.lcia_result_publications%rowtype;
begin
  if v_actor is null then
    return public.lcia_result_error('auth_required', 401, 'Authentication required');
  end if;

  if not public.lcia_result_is_manager() then
    return public.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  update public.lcia_result_publications
    set is_current = false,
        status = 'unpublished',
        unpublished_by = v_actor,
        unpublished_at = now(),
        reason = coalesce(nullif(trim(p_reason), ''), reason),
        updated_at = now()
  where id = p_publication_id
  returning *
    into v_publication;

  if v_publication.id is null then
    return public.lcia_result_error('publication_not_found', 404, 'Publication not found');
  end if;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_lcia_result_publication_unpublish',
    v_actor,
    'lcia_result_publications',
    v_publication.id,
    null,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('reason', p_reason)
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'publicationId', v_publication.id,
      'packageId', v_publication.package_id,
      'status', v_publication.status
    )
  );
end;
$$;


ALTER FUNCTION public.cmd_lcia_result_publication_unpublish(p_publication_id uuid, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_scope_closure_check_request(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_scope_closure_check_request(p_requested_scope_hash text, p_policy_fingerprint text, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request_key text; v_current_manifest jsonb; v_data_snapshot_token text; v_expected_validator_scanner_fingerprint text;
  v_request_fingerprint text;
  v_check public.lcia_scope_closure_checks%rowtype;
  v_job public.worker_jobs%rowtype;
begin
  if v_actor is null then
    return public.lcia_scope_closure_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lcia_scope_closure_is_manager() then
    return public.lcia_scope_closure_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if coalesce(nullif(trim(p_requested_scope_hash), ''), '') = ''
    or coalesce(nullif(trim(p_policy_fingerprint), ''), '') = ''
    or coalesce(nullif(trim(p_request_idempotency_token), ''), '') = '' then
    return public.lcia_scope_closure_error('invalid_closure_request', 400, 'Closure scope, policy, and idempotency token are required');
  end if;
  select expected_validator_scanner_fingerprint into v_expected_validator_scanner_fingerprint
  from public.lcia_scope_closure_config where singleton;
  if v_expected_validator_scanner_fingerprint is null then
    return public.lcia_scope_closure_error('closure_evidence_unavailable', 503, 'Closure validator configuration is unavailable');
  end if;
  v_current_manifest := public.lcia_result_current_eligible_manifest();
  v_data_snapshot_token := v_current_manifest->>'inputManifestHash';

  v_request_fingerprint := encode(digest(
    trim(p_requested_scope_hash) || '|' || trim(p_policy_fingerprint) || '|' ||
    v_expected_validator_scanner_fingerprint || '|' || v_data_snapshot_token, 'sha256'), 'hex');
  v_request_key := encode(digest(v_actor::text || '|' || trim(p_request_idempotency_token) || '|' || v_request_fingerprint, 'sha256'), 'hex');

  select * into v_check
  from public.lcia_scope_closure_checks
  where requested_by = v_actor and request_key = v_request_key
  for update;
  if v_check.id is not null then
    select * into v_job from public.worker_jobs where id = v_check.worker_job_id;
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'closureCheckId', v_check.id, 'workerJob', public.worker_job_payload(v_job, false),
      'requestFingerprint', v_request_fingerprint, 'reused', true));
  end if;

  insert into public.worker_jobs (
    job_kind, worker_runtime, worker_queue, priority, subject_type, requester_type,
    requested_by, idempotency_key, request_hash, concurrency_key, visibility,
    max_attempts, payload_schema_version, payload_json, result_schema_version
  ) values (
    'lcia.scope_closure_check', 'calculator', 'solver', 10, 'lcia_scope_closure_check', 'user',
    v_actor, trim(p_request_idempotency_token), v_request_fingerprint, v_request_key, 'operator',
    3, 'lcia.scope_closure_check.request.v1', jsonb_build_object(
      'closure_check_id', null, 'requested_by', v_actor, 'requested_scope_hash', trim(p_requested_scope_hash),
      'policy_fingerprint', trim(p_policy_fingerprint), 'data_snapshot_token', v_data_snapshot_token,
      'expected_validator_scanner_fingerprint', v_expected_validator_scanner_fingerprint,
      'request_fingerprint', v_request_fingerprint, 'request_key', v_request_key),
    'lcia.scope_closure_check.result.v1'
  ) returning * into v_job;

  insert into public.lcia_scope_closure_checks (
    worker_job_id, requested_by, request_idempotency_token, request_key, request_fingerprint,
    requested_scope_hash, policy_fingerprint, data_snapshot_token, expected_validator_scanner_fingerprint
  ) values (
    v_job.id, v_actor, trim(p_request_idempotency_token), v_request_key, v_request_fingerprint,
    trim(p_requested_scope_hash), trim(p_policy_fingerprint), v_data_snapshot_token, v_expected_validator_scanner_fingerprint
  ) returning * into v_check;

  update public.worker_jobs
  set subject_id = v_check.id,
      payload_json = payload_json || jsonb_build_object('closure_check_id', v_check.id),
      updated_at = now()
  where id = v_job.id
  returning * into v_job;

  insert into public.worker_job_events (job_id, event_type, status, details)
  values (v_job.id, 'enqueued', 'queued', jsonb_build_object('closureCheckId', v_check.id, 'requestFingerprint', v_request_fingerprint));

  insert into public.command_audit_log (command, actor_user_id, target_table, target_id, payload)
  values ('cmd_lcia_scope_closure_check_request', v_actor, 'lcia_scope_closure_checks', v_check.id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('requestFingerprint', v_request_fingerprint));

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id, 'workerJob', public.worker_job_payload(v_job, false),
    'requestFingerprint', v_request_fingerprint, 'reused', false));
end;
$$;


ALTER FUNCTION public.cmd_lcia_scope_closure_check_request(p_requested_scope_hash text, p_policy_fingerprint text, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_scope_closure_check_request_v2(jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_scope jsonb;
  v_policy jsonb;
  v_requested_scope_hash text;
  v_policy_fingerprint text;
  v_expected_validator text;
  v_snapshot_manifest jsonb;
  v_snapshot_token text;
  v_request_fingerprint text;
  v_request_key text;
  v_result jsonb;
  v_check public.lcia_scope_closure_checks%rowtype;
  v_job public.worker_jobs%rowtype;
  v_execution public.lcia_scope_closure_scan_executions%rowtype;
  v_publication public.lca_release_publications%rowtype;
  v_run public.lca_release_runs%rowtype;
  v_dataset_manifest jsonb;
  v_candidate_manifest_hash text;
  v_publication_epoch bigint := 0;
  v_missing_root_count integer;
begin
  if v_actor is null then
    return public.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if not public.lcia_scope_closure_is_manager() then
    return public.lcia_scope_closure_error(
      'not_data_product_manager', 403, 'Data product manager role is required'
    );
  end if;
  if coalesce(nullif(trim(p_request_idempotency_token), ''), '') = '' then
    return public.lcia_scope_closure_error(
      'invalid_closure_request', 400, 'Idempotency token is required'
    );
  end if;

  v_scope := public.lcia_scope_closure_normalize_request(p_requested_scope);

  if v_scope->>'eligibilityPredicateVersion' = 'current-public-release-manifest:v2' then
    select *
    into v_publication
    from public.lca_release_publications
    where is_current = true and status = 'current'
    order by published_at desc
    limit 1;

    if v_publication.id is null then
      return public.lcia_scope_closure_error(
        'closure_snapshot_source_changed',
        409,
        'The current release changed while the closure snapshot was being frozen; retry the check'
      );
    end if;
    select *
    into v_run
    from public.lca_release_runs
    where id = v_publication.release_run_id;
    if v_run.id is null or v_run.release_manifest_hash is null then
      return public.lcia_scope_closure_error(
        'closure_evidence_unavailable',
        503,
        'Current public release manifest is unavailable'
      );
    end if;
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'datasetType', d.dataset_type,
        'datasetId', d.dataset_uuid,
        'datasetVersion', d.dataset_version,
        'role', d.dataset_role,
        'sourceProcessId', d.source_process_uuid,
        'sourceProcessVersion', d.source_process_version,
        'versionSignificantHash', d.version_significant_hash,
        'semanticHash', d.semantic_hash,
        'canonicalContentHash', d.canonical_content_hash
      )
      order by d.dataset_type, d.dataset_uuid, d.dataset_version, d.dataset_role
    ), '[]'::jsonb)
    into v_dataset_manifest
    from public.lca_release_dataset_versions d
    where d.release_run_id = v_run.id;

    if jsonb_array_length(v_dataset_manifest) = 0 then
      return public.lcia_scope_closure_error(
        'closure_evidence_unavailable',
        503,
        'Current public release dataset manifest is empty'
      );
    end if;

    v_snapshot_manifest := jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-data-snapshot.v2',
      'requestedScope', v_scope,
      'currentPublicRelease', jsonb_build_object(
        'publicationId', v_publication.id,
        'releaseRunId', v_run.id,
        'releaseVersion', v_run.release_version,
        'publishedAt', v_publication.published_at,
        'releaseManifestHash', v_run.release_manifest_hash
      ),
      'datasets', v_dataset_manifest
    );
    v_publication_epoch := extract(epoch from v_publication.published_at)::bigint;
  else
    if v_scope->>'certificateFreshnessPolicy' = 'current-membership-required-v1' then
      return public.lcia_scope_closure_error(
        'current_release_required',
        409,
        'Current-membership freshness requires a current formal release'
      );
    end if;

    v_dataset_manifest :=
      private.lcia_scope_closure_candidate_dataset_manifest();
    if jsonb_array_length(v_dataset_manifest) = 0 then
      return public.lcia_scope_closure_error(
        'closure_evidence_unavailable',
        503,
        'Candidate public-state dataset manifest is empty'
      );
    end if;

    with roots as (
      select 'processes'::text as dataset_type,
        (item.value->>'id')::uuid as dataset_id,
        item.value->>'version' as dataset_version
      from jsonb_array_elements(v_scope->'processes') item(value)
      union all
      select 'lciamethods',
        (item.value->>'id')::uuid,
        item.value->>'version'
      from jsonb_array_elements(v_scope->'lciaMethods') item(value)
    ),
    frozen as (
      select item.value->>'datasetType' as dataset_type,
        (item.value->>'datasetId')::uuid as dataset_id,
        item.value->>'datasetVersion' as dataset_version
      from jsonb_array_elements(v_dataset_manifest) item(value)
    )
    select count(*)
    into v_missing_root_count
    from roots r
    left join frozen f using (dataset_type, dataset_id, dataset_version)
    where f.dataset_id is null;

    if v_missing_root_count <> 0 then
      return public.lcia_scope_closure_error(
        'closure_snapshot_source_changed',
        409,
        'Candidate data changed while the closure snapshot was being frozen; retry the check'
      );
    end if;

    v_candidate_manifest_hash := public.lcia_scope_closure_sha256(
      jsonb_build_object(
        'eligibilityPredicateVersion',
          v_scope->>'eligibilityPredicateVersion',
        'datasets', v_dataset_manifest
      )
    );
    v_snapshot_manifest := jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-data-snapshot.v2',
      'requestedScope', v_scope,
      -- Required only for deployed Worker v2 compatibility.  candidateData
      -- below is the authoritative source description.
      'currentPublicRelease', jsonb_build_object(
        'publicationId', '00000000-0000-0000-0000-000000000000',
        'releaseRunId', '00000000-0000-0000-0000-000000000000',
        'releaseVersion', 'candidate-public-state-v1',
        'publishedAt', '1970-01-01T00:00:00Z',
        'releaseManifestHash', v_candidate_manifest_hash
      ),
      'candidateData', jsonb_build_object(
        'sourceKind', 'candidate-public-state',
        'eligibilityPredicateVersion',
          v_scope->>'eligibilityPredicateVersion',
        'datasetManifestHash', v_candidate_manifest_hash,
        'workerV2CompatibilityProjection', true
      ),
      'datasets', v_dataset_manifest
    );
  end if;

  v_snapshot_token := public.lcia_scope_closure_sha256(v_snapshot_manifest);
  v_requested_scope_hash := public.lcia_scope_closure_sha256(v_scope);
  v_policy := jsonb_build_object(
    'scopePolicy', v_scope - 'processes' - 'lciaMethods' - 'processManifestHash',
    'visibilityScope', 'data_product_manager.v1'
  );
  v_policy_fingerprint := public.lcia_scope_closure_sha256(v_policy);
  select expected_validator_scanner_fingerprint
  into v_expected_validator
  from public.lcia_scope_closure_config
  where singleton;
  if v_expected_validator is null then
    return public.lcia_scope_closure_error(
      'closure_evidence_unavailable',
      503,
      'Closure validator configuration is unavailable'
    );
  end if;

  v_request_fingerprint := encode(extensions.digest(
    v_requested_scope_hash || '|' || v_policy_fingerprint || '|'
      || v_expected_validator || '|' || v_snapshot_token,
    'sha256'
  ), 'hex');
  v_request_key := encode(extensions.digest(
    v_actor::text || '|' || trim(p_request_idempotency_token) || '|'
      || v_request_fingerprint,
    'sha256'
  ), 'hex');

  select *
  into v_check
  from public.lcia_scope_closure_checks
  where requested_by = v_actor and request_key = v_request_key
  for update;
  if v_check.id is not null then
    select * into v_job from public.worker_jobs where id = v_check.worker_job_id;
    return jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object(
        'closureCheckId', v_check.id,
        'requestedScopeHash', v_check.requested_scope_hash,
        'policyFingerprint', v_check.policy_fingerprint,
        'dataSnapshotToken', v_check.data_snapshot_token,
        'scanExecutionId', v_check.scan_execution_id,
        'workerJob', public.worker_job_payload(v_job, false),
        'reused', true
      )
    );
  end if;

  v_result := public.cmd_lcia_scope_closure_check_request_v2_untracked(
    p_requested_scope,
    p_request_idempotency_token,
    p_audit
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    return v_result;
  end if;
  select *
  into v_check
  from public.lcia_scope_closure_checks
  where id = nullif(v_result->'data'->>'closureCheckId', '')::uuid
  for update;
  if v_check.id is null then
    return public.lcia_scope_closure_error(
      'closure_check_not_found', 404, 'Closure check not found'
    );
  end if;
  if coalesce((v_result->'data'->>'reused')::boolean, false)
     and v_check.request_key <> v_request_key
     and v_check.data_snapshot_token <> v_snapshot_token then
    return public.lcia_scope_closure_error(
      'idempotency_token_bound_to_different_snapshot',
      409,
      'Idempotency token is already bound to a different data snapshot'
    );
  end if;

  insert into public.lcia_scope_closure_data_snapshots(
    data_snapshot_token,
    root_manifest,
    root_manifest_hash,
    publication_epoch
  ) values (
    v_snapshot_token,
    v_snapshot_manifest,
    public.lcia_scope_closure_sha256(v_snapshot_manifest),
    v_publication_epoch
  )
  on conflict (data_snapshot_token) do nothing;

  update public.lcia_scope_closure_checks
  set data_snapshot_token = v_snapshot_token,
      requested_scope_manifest = v_scope,
      requested_scope_hash = v_requested_scope_hash,
      policy_fingerprint = v_policy_fingerprint,
      request_fingerprint = v_request_fingerprint,
      request_key = v_request_key,
      updated_at = now()
  where id = v_check.id
  returning * into v_check;

  select *
  into v_execution
  from public.lcia_scope_closure_scan_executions
  where request_fingerprint = v_request_fingerprint
  for update;
  if v_execution.id is null then
    insert into public.lcia_scope_closure_scan_executions(
      request_fingerprint,
      requested_scope_hash,
      policy_fingerprint,
      data_snapshot_token,
      validator_scanner_fingerprint
    ) values (
      v_request_fingerprint,
      v_requested_scope_hash,
      v_policy_fingerprint,
      v_snapshot_token,
      v_expected_validator
    )
    returning * into v_execution;
  end if;

  update public.lcia_scope_closure_checks
  set scan_execution_id = v_execution.id,
      updated_at = now()
  where id = v_check.id
  returning * into v_check;

  update public.worker_jobs
  set request_hash = v_request_fingerprint,
      concurrency_key = v_request_key,
      payload_json = payload_json || jsonb_build_object(
        'coverage_mode', v_scope->>'coverageMode',
        'input_manifest', jsonb_build_object(
          'predicateVersion', v_scope->>'eligibilityPredicateVersion',
          'selectionMode', 'closure_certificate',
          'processes', v_scope->'processes'
        ),
        'input_manifest_hash',
          public.lcia_scope_closure_sha256(
            jsonb_build_object('processes', v_scope->'processes')
          ),
        'lcia_method_set', v_scope->'lciaMethods',
        'request_fingerprint', v_request_fingerprint,
        'scan_execution_id', v_execution.id,
        'data_snapshot_token', v_snapshot_token
      ),
      updated_at = now()
  where id = v_check.worker_job_id
  returning * into v_job;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'closureCheckId', v_check.id,
      'requestedScopeHash', v_check.requested_scope_hash,
      'policyFingerprint', v_check.policy_fingerprint,
      'dataSnapshotToken', v_snapshot_token,
      'scanExecutionId', v_execution.id,
      'workerJob', public.worker_job_payload(v_job, false),
      'reused', false
    )
  );
exception
  when sqlstate '22023' then
    return public.lcia_scope_closure_error(
      'invalid_closure_scope', 400, sqlerrm
    );
end;
$$;


ALTER FUNCTION public.cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) IS 'Creates a release-bound closure preflight when a formal release exists, or a deterministic candidate-public-state preflight for initial release bootstrap.';


--
-- Name: cmd_lcia_scope_closure_check_request_v2_untracked(jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_lcia_scope_closure_check_request_v2_untracked(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_scope jsonb; v_policy jsonb; v_requested_scope_hash text;
  v_policy_fingerprint text; v_data_snapshot_token text; v_expected_validator_scanner_fingerprint text;
  v_request_fingerprint text; v_request_key text; v_check public.lcia_scope_closure_checks%rowtype; v_job public.worker_jobs%rowtype;
begin
  if v_actor is null then return public.lcia_scope_closure_error('auth_required', 401, 'Authentication required'); end if;
  if not public.lcia_scope_closure_is_manager() then return public.lcia_scope_closure_error('not_data_product_manager', 403, 'Data product manager role is required'); end if;
  if coalesce(nullif(trim(p_request_idempotency_token), ''), '') = '' then return public.lcia_scope_closure_error('invalid_closure_request', 400, 'Idempotency token is required'); end if;
  v_scope := public.lcia_scope_closure_normalize_request(p_requested_scope);
  v_requested_scope_hash := public.lcia_scope_closure_sha256(v_scope);
  v_policy := jsonb_build_object('scopePolicy', v_scope - 'processes' - 'lciaMethods' - 'processManifestHash', 'visibilityScope', 'data_product_manager.v1');
  v_policy_fingerprint := public.lcia_scope_closure_sha256(v_policy);
  v_data_snapshot_token := public.lcia_scope_closure_sha256(jsonb_build_object('processes', v_scope->'processes', 'lciaMethods', v_scope->'lciaMethods'));
  select expected_validator_scanner_fingerprint into v_expected_validator_scanner_fingerprint from public.lcia_scope_closure_config where singleton;
  if v_expected_validator_scanner_fingerprint is null then return public.lcia_scope_closure_error('closure_evidence_unavailable', 503, 'Closure validator configuration is unavailable'); end if;
  v_request_fingerprint := encode(extensions.digest(v_requested_scope_hash || '|' || v_policy_fingerprint || '|' || v_expected_validator_scanner_fingerprint || '|' || v_data_snapshot_token, 'sha256'), 'hex');
  v_request_key := encode(extensions.digest(v_actor::text || '|' || trim(p_request_idempotency_token) || '|' || v_request_fingerprint, 'sha256'), 'hex');
  select * into v_check from public.lcia_scope_closure_checks where requested_by = v_actor and request_key = v_request_key for update;
  if v_check.id is not null then
    select * into v_job from public.worker_jobs where id = v_check.worker_job_id;
    return jsonb_build_object('ok', true, 'data', jsonb_build_object('closureCheckId', v_check.id, 'requestedScopeHash', v_check.requested_scope_hash, 'policyFingerprint', v_check.policy_fingerprint, 'workerJob', public.worker_job_payload(v_job, false), 'reused', true));
  end if;
  insert into public.worker_jobs (job_kind, worker_runtime, worker_queue, priority, subject_type, requester_type, requested_by, idempotency_key, request_hash, concurrency_key, visibility, max_attempts, payload_schema_version, payload_json, result_schema_version)
  values ('lcia.scope_closure_check','calculator','solver',10,'lcia_scope_closure_check','user',v_actor,trim(p_request_idempotency_token),v_request_fingerprint,v_request_key,'operator',3,'lcia.scope_closure_check.request.v1',jsonb_build_object('closure_check_id', null, 'request_fingerprint', v_request_fingerprint),'lcia.scope_closure_check.result.v1') returning * into v_job;
  insert into public.lcia_scope_closure_checks (worker_job_id,requested_by,request_idempotency_token,request_key,request_fingerprint,requested_scope_hash,requested_scope_manifest,policy_fingerprint,data_snapshot_token,expected_validator_scanner_fingerprint)
  values (v_job.id,v_actor,trim(p_request_idempotency_token),v_request_key,v_request_fingerprint,v_requested_scope_hash,v_scope,v_policy_fingerprint,v_data_snapshot_token,v_expected_validator_scanner_fingerprint) returning * into v_check;
  update public.worker_jobs set subject_id = v_check.id, payload_json = payload_json || jsonb_build_object('closure_check_id', v_check.id), updated_at = now() where id = v_job.id returning * into v_job;
  insert into public.worker_job_events(job_id,event_type,status,details) values(v_job.id,'enqueued','queued',jsonb_build_object('closureCheckId',v_check.id,'requestFingerprint',v_request_fingerprint));
  insert into public.command_audit_log(command,actor_user_id,target_table,target_id,payload) values ('cmd_lcia_scope_closure_check_request_v2',v_actor,'lcia_scope_closure_checks',v_check.id,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('requestFingerprint',v_request_fingerprint,'requestedScopeHash',v_requested_scope_hash,'policyFingerprint',v_policy_fingerprint));
  return jsonb_build_object('ok',true,'data',jsonb_build_object('closureCheckId',v_check.id,'requestedScopeHash',v_requested_scope_hash,'policyFingerprint',v_policy_fingerprint,'workerJob',public.worker_job_payload(v_job,false),'reused',false));
exception when sqlstate '22023' then
  return public.lcia_scope_closure_error('invalid_closure_scope',400,sqlerrm);
end;
$$;


ALTER FUNCTION public.cmd_lcia_scope_closure_check_request_v2_untracked(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

