--
-- Name: cmd_membership_resolve_member_order_by(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_membership_resolve_member_order_by(p_sort_by text, p_allow_workload boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  case lower(coalesce(p_sort_by, ''))
    when 'role' then
      return 'm.role';
    when 'email' then
      return 'm.email';
    when 'display_name' then
      return 'm.display_name';
    when 'modified_at' then
      return 'm.modified_at';
    when 'pendingcount' then
      if p_allow_workload then
        return 'm.pending_count';
      end if;
    when 'pending_count' then
      if p_allow_workload then
        return 'm.pending_count';
      end if;
    when 'reviewedcount' then
      if p_allow_workload then
        return 'm.reviewed_count';
      end if;
    when 'reviewed_count' then
      if p_allow_workload then
        return 'm.reviewed_count';
      end if;
    else
      return 'm.created_at';
  end case;

  return 'm.created_at';
end;
$$;


ALTER FUNCTION public.cmd_membership_resolve_member_order_by(p_sort_by text, p_allow_workload boolean) OWNER TO postgres;

--
-- Name: cmd_membership_resolve_sort_direction(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_membership_resolve_sort_direction(p_sort_order text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  case lower(coalesce(p_sort_order, ''))
    when 'asc' then
      return 'asc';
    when 'ascend' then
      return 'asc';
    else
      return 'desc';
  end case;
end;
$$;


ALTER FUNCTION public.cmd_membership_resolve_sort_direction(p_sort_order text) OWNER TO postgres;

--
-- Name: cmd_notification_normalize_text_array(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_notification_normalize_text_array(p_values text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with normalized as (
    select
      min(item.ordinality) as first_ordinality,
      nullif(btrim(item.value), '') as normalized_value
    from unnest(coalesce(p_values, array[]::text[])) with ordinality as item(value, ordinality)
    group by nullif(btrim(item.value), '')
  )
  select coalesce(
    array(
      select normalized_value
      from normalized
      where normalized_value is not null
      order by first_ordinality
    ),
    array[]::text[]
  );
$$;


ALTER FUNCTION public.cmd_notification_normalize_text_array(p_values text[]) OWNER TO postgres;

--
-- Name: cmd_notification_send_validation_issue(uuid, text, uuid, text, text, text[], text[], integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_notification_send_validation_issue(p_recipient_user_id uuid, p_dataset_type text, p_dataset_id uuid, p_dataset_version text, p_link text DEFAULT NULL::text, p_issue_codes text[] DEFAULT ARRAY[]::text[], p_tab_names text[] DEFAULT ARRAY[]::text[], p_issue_count integer DEFAULT 0, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_dataset_type text := nullif(btrim(coalesce(p_dataset_type, '')), '');
  v_dataset_version text := nullif(btrim(coalesce(p_dataset_version, '')), '');
  v_target_table text;
  v_target_row jsonb;
  v_issue_codes text[];
  v_tab_names text[];
  v_sender_name text;
  v_notification_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_recipient_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'RECIPIENT_REQUIRED',
      'status', 400,
      'message', 'recipientUserId is required'
    );
  end if;

  if v_actor = p_recipient_user_id then
    return jsonb_build_object(
      'ok', false,
      'code', 'NOTIFICATION_SELF_TARGET',
      'status', 409,
      'message', 'The recipient must differ from the actor'
    );
  end if;

  if v_dataset_type is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_TYPE_REQUIRED',
      'status', 400,
      'message', 'datasetType is required'
    );
  end if;

  if p_dataset_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_ID_REQUIRED',
      'status', 400,
      'message', 'datasetId is required'
    );
  end if;

  if v_dataset_version is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_VERSION_REQUIRED',
      'status', 400,
      'message', 'datasetVersion is required'
    );
  end if;

  if not exists (
    select 1
    from public.users
    where id = p_recipient_user_id
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'RECIPIENT_NOT_FOUND',
      'status', 404,
      'message', 'The recipient user does not exist'
    );
  end if;

  v_target_table := public.cmd_review_ref_type_to_table(v_dataset_type);
  if v_target_table is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_TYPE_INVALID',
      'status', 400,
      'message', 'datasetType is not supported'
    );
  end if;

  v_target_row := public.cmd_review_get_dataset_row(
    v_target_table,
    p_dataset_id,
    v_dataset_version,
    false
  );
  if v_target_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'The target dataset does not exist'
    );
  end if;

  if ((v_target_row ->> 'user_id')::uuid is distinct from p_recipient_user_id) then
    return jsonb_build_object(
      'ok', false,
      'code', 'RECIPIENT_NOT_TARGET_OWNER',
      'status', 403,
      'message', 'The recipient must own the target dataset'
    );
  end if;

  v_issue_codes := public.cmd_notification_normalize_text_array(p_issue_codes);
  v_tab_names := public.cmd_notification_normalize_text_array(p_tab_names);

  select coalesce(
    nullif(btrim(u.raw_user_meta_data ->> 'display_name'), ''),
    nullif(btrim(u.raw_user_meta_data ->> 'name'), ''),
    nullif(btrim(u.raw_user_meta_data ->> 'email'), ''),
    '-'
  )
  into v_sender_name
  from public.users as u
  where u.id = v_actor;

  v_sender_name := coalesce(v_sender_name, '-');

  insert into public.notifications (
    recipient_user_id,
    sender_user_id,
    type,
    dataset_type,
    dataset_id,
    dataset_version,
    json,
    modified_at
  )
  values (
    p_recipient_user_id,
    v_actor,
    'validation_issue',
    v_dataset_type,
    p_dataset_id,
    v_dataset_version,
    jsonb_build_object(
      'issueCodes', to_jsonb(v_issue_codes),
      'issueCount', greatest(coalesce(p_issue_count, 0), 0),
      'link', nullif(btrim(coalesce(p_link, '')), ''),
      'senderName', v_sender_name,
      'tabNames', to_jsonb(v_tab_names)
    ),
    now()
  )
  on conflict (
    recipient_user_id,
    sender_user_id,
    type,
    dataset_type,
    dataset_id,
    dataset_version
  ) do update
  set json = excluded.json,
      modified_at = excluded.modified_at
  returning to_jsonb(notifications.*)
    into v_notification_row;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_notification_send_validation_issue',
    v_actor,
    'notifications',
    (v_notification_row ->> 'id')::uuid,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'recipientUserId', p_recipient_user_id,
      'datasetType', v_dataset_type,
      'datasetId', p_dataset_id,
      'datasetVersion', v_dataset_version,
      'issueCount', greatest(coalesce(p_issue_count, 0), 0)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_notification_row
  );
end;
$$;


ALTER FUNCTION public.cmd_notification_send_validation_issue(p_recipient_user_id uuid, p_dataset_type text, p_dataset_id uuid, p_dataset_version text, p_link text, p_issue_codes text[], p_tab_names text[], p_issue_count integer, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_append_log(jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_append_log(p_review_json jsonb, p_action text, p_actor uuid, p_extra jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_review_json jsonb := coalesce(p_review_json, '{}'::jsonb);
  v_logs jsonb := public.cmd_review_json_array(v_review_json->'logs');
  v_actor_meta jsonb := public.cmd_review_get_actor_meta(p_actor);
  v_log_entry jsonb;
begin
  v_log_entry := jsonb_build_object(
    'action', p_action,
    'time', to_jsonb(now()),
    'user', v_actor_meta
  ) || coalesce(p_extra, '{}'::jsonb);

  return jsonb_set(
    v_review_json,
    '{logs}',
    v_logs || jsonb_build_array(v_log_entry),
    true
  );
end;
$$;


ALTER FUNCTION public.cmd_review_append_log(p_review_json jsonb, p_action text, p_actor uuid, p_extra jsonb) OWNER TO postgres;

--
-- Name: cmd_review_append_review_ref(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_append_review_ref(p_existing_reviews jsonb, p_review_id uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_reviews jsonb := case
    when jsonb_typeof(p_existing_reviews) = 'array' then p_existing_reviews
    else '[]'::jsonb
  end;
begin
  if exists (
    select 1
    from jsonb_array_elements(v_reviews) as review_item(value)
    where review_item.value->>'id' = p_review_id::text
  ) then
    return v_reviews;
  end if;

  return v_reviews || jsonb_build_array(
    jsonb_build_object(
      'key', jsonb_array_length(v_reviews),
      'id', p_review_id
    )
  );
end;
$$;


ALTER FUNCTION public.cmd_review_append_review_ref(p_existing_reviews jsonb, p_review_id uuid) OWNER TO postgres;

--
-- Name: cmd_review_apply_model_validation_to_process_json(jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_apply_model_validation_to_process_json(p_process_json jsonb, p_model_json jsonb, p_comment_review jsonb DEFAULT '[]'::jsonb, p_comment_compliance jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with base as (
    select
      coalesce(p_process_json, '{}'::jsonb) as process_json,
      public.cmd_review_json_array(
        coalesce(
          p_process_json #> '{processDataSet,modellingAndValidation,validation,review}',
          '[]'::jsonb
        )
      ) as existing_review_items,
      public.cmd_review_json_array(
        coalesce(
          p_process_json #> '{processDataSet,modellingAndValidation,complianceDeclarations,compliance}',
          '[]'::jsonb
        )
      ) as existing_compliance_items,
      public.cmd_review_json_array(coalesce(p_comment_review, '[]'::jsonb)) as comment_review_items,
      public.cmd_review_json_array(coalesce(p_comment_compliance, '[]'::jsonb))
        as comment_compliance_items
  ),
  prepared as (
    select
      jsonb_set(
        jsonb_set(
          jsonb_set(
            jsonb_set(
              base.process_json,
              '{processDataSet}',
              case
                when jsonb_typeof(base.process_json->'processDataSet') = 'object'
                  then base.process_json->'processDataSet'
                else '{}'::jsonb
              end,
              true
            ),
            '{processDataSet,modellingAndValidation}',
            case
              when jsonb_typeof(
                base.process_json #> '{processDataSet,modellingAndValidation}'
              ) = 'object'
                then base.process_json #> '{processDataSet,modellingAndValidation}'
              else '{}'::jsonb
            end,
            true
          ),
          '{processDataSet,modellingAndValidation,validation}',
          case
            when jsonb_typeof(
              base.process_json #> '{processDataSet,modellingAndValidation,validation}'
            ) = 'object'
              then base.process_json #> '{processDataSet,modellingAndValidation,validation}'
            else '{}'::jsonb
          end,
          true
        ),
        '{processDataSet,modellingAndValidation,complianceDeclarations}',
        case
          when jsonb_typeof(
            base.process_json #> '{processDataSet,modellingAndValidation,complianceDeclarations}'
          ) = 'object'
            then base.process_json #> '{processDataSet,modellingAndValidation,complianceDeclarations}'
          else '{}'::jsonb
        end,
        true
      ) as prepared_process_json,
      base.existing_review_items,
      base.existing_compliance_items,
      base.comment_review_items,
      base.comment_compliance_items
    from base
  )
  select jsonb_set(
    jsonb_set(
      prepared.prepared_process_json,
      '{processDataSet,modellingAndValidation,validation,review}',
      prepared.existing_review_items || prepared.comment_review_items,
      true
    ),
    '{processDataSet,modellingAndValidation,complianceDeclarations,compliance}',
    prepared.existing_compliance_items || prepared.comment_compliance_items,
    true
  )
  from prepared
$$;


ALTER FUNCTION public.cmd_review_apply_model_validation_to_process_json(p_process_json jsonb, p_model_json jsonb, p_comment_review jsonb, p_comment_compliance jsonb) OWNER TO postgres;

--
-- Name: cmd_review_apply_mv_payload(text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_apply_mv_payload(p_table text, p_id uuid, p_version text, p_review_items jsonb DEFAULT '[]'::jsonb, p_compliance_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_row jsonb;
  v_doc jsonb;
  v_dataset_path text[];
  v_mv_path text[];
  v_validation_object_path text[];
  v_compliance_object_path text[];
  v_review_path text[];
  v_compliance_path text[];
  v_review_items jsonb := coalesce(p_review_items, '[]'::jsonb);
  v_compliance_items jsonb := coalesce(p_compliance_items, '[]'::jsonb);
begin
  if p_table not in ('processes', 'lifecyclemodels') then
    return public.cmd_review_get_dataset_row(p_table, p_id, p_version, false);
  end if;

  v_row := public.cmd_review_get_dataset_row(p_table, p_id, p_version, true);

  if v_row is null then
    return null;
  end if;

  if p_table = 'processes' then
    v_dataset_path := array['processDataSet'];
    v_mv_path := array['processDataSet', 'modellingAndValidation'];
    v_validation_object_path := array[
      'processDataSet',
      'modellingAndValidation',
      'validation'
    ];
    v_compliance_object_path := array[
      'processDataSet',
      'modellingAndValidation',
      'complianceDeclarations'
    ];
    v_review_path := array['processDataSet', 'modellingAndValidation', 'validation', 'review'];
    v_compliance_path := array[
      'processDataSet',
      'modellingAndValidation',
      'complianceDeclarations',
      'compliance'
    ];
  else
    v_dataset_path := array['lifeCycleModelDataSet'];
    v_mv_path := array['lifeCycleModelDataSet', 'modellingAndValidation'];
    v_validation_object_path := array[
      'lifeCycleModelDataSet',
      'modellingAndValidation',
      'validation'
    ];
    v_compliance_object_path := array[
      'lifeCycleModelDataSet',
      'modellingAndValidation',
      'complianceDeclarations'
    ];
    v_review_path := array[
      'lifeCycleModelDataSet',
      'modellingAndValidation',
      'validation',
      'review'
    ];
    v_compliance_path := array[
      'lifeCycleModelDataSet',
      'modellingAndValidation',
      'complianceDeclarations',
      'compliance'
    ];
  end if;

  v_doc := coalesce(v_row->'json_ordered', v_row->'json', '{}'::jsonb);
  v_doc := jsonb_set(
    v_doc,
    v_dataset_path,
    case
      when jsonb_typeof(v_doc #> v_dataset_path) = 'object'
        then v_doc #> v_dataset_path
      else '{}'::jsonb
    end,
    true
  );
  v_doc := jsonb_set(
    v_doc,
    v_mv_path,
    case
      when jsonb_typeof(v_doc #> v_mv_path) = 'object'
        then v_doc #> v_mv_path
      else '{}'::jsonb
    end,
    true
  );
  v_doc := jsonb_set(
    v_doc,
    v_validation_object_path,
    case
      when jsonb_typeof(v_doc #> v_validation_object_path) = 'object'
        then v_doc #> v_validation_object_path
      else '{}'::jsonb
    end,
    true
  );
  v_doc := jsonb_set(
    v_doc,
    v_compliance_object_path,
    case
      when jsonb_typeof(v_doc #> v_compliance_object_path) = 'object'
        then v_doc #> v_compliance_object_path
      else '{}'::jsonb
    end,
    true
  );

  if jsonb_array_length(v_review_items) > 0 then
    v_doc := jsonb_set(
      v_doc,
      v_review_path,
      public.cmd_review_json_array(v_doc #> v_review_path) || v_review_items,
      true
    );
  end if;

  if jsonb_array_length(v_compliance_items) > 0 then
    v_doc := jsonb_set(
      v_doc,
      v_compliance_path,
      public.cmd_review_json_array(v_doc #> v_compliance_path) || v_compliance_items,
      true
    );
  end if;

  execute format(
    'update public.%I
        set json_ordered = $1::json,
            json = $1::jsonb,
            modified_at = now()
      where id = $2
        and version = $3',
    p_table
  )
    using v_doc, p_id, p_version;

  return public.cmd_review_get_dataset_row(p_table, p_id, p_version, false);
end;
$_$;


ALTER FUNCTION public.cmd_review_apply_mv_payload(p_table text, p_id uuid, p_version text, p_review_items jsonb, p_compliance_items jsonb) OWNER TO postgres;

--
-- Name: cmd_review_approve(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_approve(p_table text, p_review_id uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_review public.reviews%rowtype;
  v_root jsonb;
  v_assertion jsonb;
  v_comment_ref record;
begin
  if v_actor is null
    or not public.cmd_review_is_review_admin(v_actor)
    or lower(coalesce(p_table, '')) not in ('processes', 'lifecyclemodels') then
    return public.cmd_review_approve_issue304_legacy(
      p_table,
      p_review_id,
      p_audit
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('review-publication-lifecycle-closure', 0)
  );

  select review_row.*
  into v_review
  from public.reviews as review_row
  where review_row.id = p_review_id
  for update;

  if not found or v_review.state_code <> 1 then
    return public.cmd_review_approve_issue304_legacy(
      p_table,
      p_review_id,
      p_audit
    );
  end if;

  v_root := public.cmd_review_get_dataset_row(
    lower(p_table),
    v_review.data_id,
    v_review.data_version,
    true
  );

  if v_root is null then
    return public.cmd_review_approve_issue304_legacy(
      p_table,
      p_review_id,
      p_audit
    );
  end if;

  if lower(p_table) = 'processes' then
    lock table public.lifecyclemodels in share row exclusive mode;
  end if;

  perform 1
  from public.comments as comment_row
  where comment_row.review_id = p_review_id
  order by comment_row.reviewer_id, comment_row.created_at
  for update;

  for v_comment_ref in
    select role_ref.*
    from public.comments as comment_row
    cross join lateral public.cmd_review_reference_roles(
      'comments',
      'comment',
      coalesce(to_jsonb(comment_row.json), '{}'::jsonb)
    ) as role_ref
    where comment_row.review_id = p_review_id
      and comment_row.state_code = 1
    order by
      role_ref.reference_path,
      role_ref.ref_table,
      role_ref.ref_object_id,
      role_ref.ref_version
  loop
    if v_comment_ref.lifecycle_role = 'PolicyGap' then
      return public.cmd_review_lifecycle_error(
        'REFERENCE_ROLE_POLICY_GAP',
        v_comment_ref.reference_path,
        v_comment_ref.ref_table,
        v_comment_ref.ref_object_id,
        v_comment_ref.ref_version
      );
    end if;
  end loop;

  v_assertion := public.cmd_review_assert_lifecycle_closure(
    jsonb_build_array(jsonb_build_object(
      'table', lower(p_table),
      'id', v_review.data_id,
      'version', v_review.data_version
    )),
    'approve',
    v_actor
  );

  if v_assertion is not null then
    return v_assertion;
  end if;

  return public.cmd_review_approve_issue304_legacy(
    p_table,
    p_review_id,
    p_audit
  );
end;
$$;


ALTER FUNCTION public.cmd_review_approve(p_table text, p_review_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_approve_issue304_legacy(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_approve_issue304_legacy(p_table text, p_review_id uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review public.reviews%rowtype;
  v_root_table text;
  v_root_targets jsonb;
  v_comment_ref_roots jsonb := '[]'::jsonb;
  v_target record;
  v_comment_ref record;
  v_review_items jsonb := '[]'::jsonb;
  v_compliance_items jsonb := '[]'::jsonb;
  v_root_row jsonb;
  v_updated_root_row jsonb;
  v_submodel_ids uuid[] := array[]::uuid[];
  v_submodel_id uuid;
  v_submodel_doc jsonb;
  v_affected_datasets jsonb := '[]'::jsonb;
  v_review_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not public.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can approve reviews'
    );
  end if;

  v_root_table := lower(coalesce(p_table, ''));
  if v_root_table not in ('processes', 'lifecyclemodels') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_TABLE',
      'status', 400,
      'message', 'table must be processes or lifecyclemodels'
    );
  end if;

  select *
    into v_review
  from public.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Only assigned reviews can be approved',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  v_root_targets := jsonb_build_array(
    jsonb_build_object(
      'table', v_root_table,
      'id', v_review.data_id,
      'version', v_review.data_version,
      'is_root', true
    )
  );

  create temporary table if not exists cmd_review_approve_targets (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    state_code integer not null,
    reviews jsonb,
    dataset_row jsonb not null,
    is_root boolean not null default false,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  truncate table cmd_review_approve_targets;

  insert into cmd_review_approve_targets (
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  )
  select
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  from public.cmd_review_collect_dataset_targets(v_root_targets, true);

  select coalesce(
    jsonb_agg(review_items.value),
    '[]'::jsonb
  )
    into v_review_items
  from public.comments as c
  cross join lateral jsonb_array_elements(
    public.cmd_review_json_array(to_jsonb(c.json)#>'{modellingAndValidation,validation,review}')
  ) as review_items(value)
  where c.review_id = p_review_id
    and c.state_code = 1;

  select coalesce(
    jsonb_agg(compliance_items.value),
    '[]'::jsonb
  )
    into v_compliance_items
  from public.comments as c
  cross join lateral jsonb_array_elements(
    public.cmd_review_json_array(
      to_jsonb(c.json)#>'{modellingAndValidation,complianceDeclarations,compliance}'
    )
  ) as compliance_items(value)
  where c.review_id = p_review_id
    and c.state_code = 1;

  for v_comment_ref in
    select distinct
      ref.ref_type,
      ref.ref_object_id,
      ref.ref_version
    from public.comments as c
    cross join lateral public.cmd_review_extract_refs(coalesce(to_jsonb(c.json), '{}'::jsonb)) as ref
    where c.review_id = p_review_id
      and c.state_code = 1
  loop
    v_comment_ref_roots := v_comment_ref_roots || jsonb_build_array(
      jsonb_build_object(
        'table', public.cmd_review_ref_type_to_table(v_comment_ref.ref_type),
        'id', v_comment_ref.ref_object_id,
        'version', v_comment_ref.ref_version,
        'is_root', false
      )
    );
  end loop;

  insert into cmd_review_approve_targets (
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  )
  select
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  from public.cmd_review_collect_dataset_targets(v_comment_ref_roots, true)
  on conflict (table_name, dataset_id, dataset_version) do nothing;

  select dataset_row
    into v_root_row
  from cmd_review_approve_targets
  where is_root
    and table_name = v_root_table
    and dataset_id = v_review.data_id
    and dataset_version = v_review.data_version
  limit 1;

  if v_root_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_TARGET_NOT_FOUND',
      'status', 404,
      'message', 'Review target dataset not found'
    );
  end if;

  if v_root_table = 'processes' then
    v_updated_root_row := public.cmd_review_apply_mv_payload(
      'processes',
      v_review.data_id,
      v_review.data_version,
      v_review_items,
      v_compliance_items
    );
  elsif v_root_table = 'lifecyclemodels' then
    select coalesce(
      array_agg((submodel.value->>'id')::uuid),
      array[]::uuid[]
    )
      into v_submodel_ids
    from jsonb_array_elements(coalesce(v_root_row->'json_tg'->'submodels', '[]'::jsonb))
         as submodel(value)
    where lower(coalesce(submodel.value->>'type', '')) = 'secondary'
      and (submodel.value->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    foreach v_submodel_id in array v_submodel_ids
    loop
      if not exists (
        select 1
        from cmd_review_approve_targets as t
        where t.table_name = 'processes'
          and t.dataset_id = v_submodel_id
          and t.dataset_version = v_review.data_version
      ) then
        return jsonb_build_object(
          'ok', false,
          'code', 'INVALID_PAYLOAD',
          'status', 400,
          'message', format(
            'Missing current process snapshot for submodel %s',
            v_submodel_id
          )
        );
      end if;
    end loop;

    v_updated_root_row := public.cmd_review_apply_mv_payload(
      'lifecyclemodels',
      v_review.data_id,
      v_review.data_version,
      v_review_items,
      v_compliance_items
    );

    foreach v_submodel_id in array v_submodel_ids
    loop
      select public.cmd_review_apply_model_validation_to_process_json(
        coalesce(t.dataset_row->'json_ordered', t.dataset_row->'json', '{}'::jsonb),
        coalesce(v_updated_root_row->'json_ordered', v_updated_root_row->'json', '{}'::jsonb),
        v_review_items,
        v_compliance_items
      )
        into v_submodel_doc
      from cmd_review_approve_targets as t
      where t.table_name = 'processes'
        and t.dataset_id = v_submodel_id
        and t.dataset_version = v_review.data_version
      limit 1;

      update public.processes
        set json_ordered = v_submodel_doc::json,
            json = v_submodel_doc,
            modified_at = now()
      where id = v_submodel_id
        and version = v_review.data_version;
    end loop;

    for v_target in
      select *
      from cmd_review_approve_targets
      where table_name = 'processes'
        and not (dataset_id = any(v_submodel_ids))
      order by dataset_id, dataset_version
    loop
      perform public.cmd_review_apply_mv_payload(
        'processes',
        v_target.dataset_id,
        v_target.dataset_version,
        v_review_items,
        v_compliance_items
      );
    end loop;
  end if;

  for v_target in
    select *
    from cmd_review_approve_targets
    where state_code < 100
      and state_code <> 200
    order by table_name, dataset_id, dataset_version
  loop
    execute format(
      'update public.%I
          set state_code = 100,
              modified_at = now()
        where id = $1
          and version = $2',
      v_target.table_name
    )
      using v_target.dataset_id, v_target.dataset_version;
  end loop;

  update public.comments
    set state_code = 2,
        modified_at = now()
  where review_id = p_review_id
    and state_code <> -2;

  v_review_json := public.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'approved',
    v_actor
  );

  update public.reviews
    set state_code = 2,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'table', table_name,
        'id', dataset_id,
        'version', dataset_version,
        'state_code', 100
      )
      order by table_name, dataset_id, dataset_version
    ),
    '[]'::jsonb
  )
    into v_affected_datasets
  from cmd_review_approve_targets
  where state_code < 100
    and state_code <> 200;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_approve',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'root_table', v_root_table,
      'affected_datasets', v_affected_datasets
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review),
      'affected_datasets', v_affected_datasets
    )
  );
end;
$_$;


ALTER FUNCTION public.cmd_review_approve_issue304_legacy(p_table text, p_review_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_assert_lifecycle_closure(jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_assert_lifecycle_closure(p_roots jsonb, p_action text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_root jsonb;
  v_current record;
  v_row jsonb;
  v_doc jsonb;
  v_root_owner uuid;
  v_ref record;
  v_submodel record;
  v_dependency jsonb;
  v_paired jsonb;
  v_has_mismatch boolean;
  v_json_tg_submodels jsonb;
  v_publish_root_table text;
  v_publish_root_id uuid;
  v_publish_root_version text;
begin
  create temporary table if not exists pg_temp.cmd_review_policy_queue (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    is_root boolean not null default false,
    dependency_role text not null,
    reference_path text not null,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  create temporary table if not exists pg_temp.cmd_review_policy_seen (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  create temporary table if not exists pg_temp.cmd_review_policy_ilcd (
    dataset_id uuid not null,
    dataset_version text not null,
    reference_path text not null,
    primary key (dataset_id, dataset_version)
  ) on commit drop;

  create temporary table if not exists pg_temp.cmd_review_policy_tg (
    dataset_id uuid not null,
    dataset_version text not null,
    reference_path text not null,
    primary key (dataset_id, dataset_version)
  ) on commit drop;

  truncate table pg_temp.cmd_review_policy_queue;
  truncate table pg_temp.cmd_review_policy_seen;
  truncate table pg_temp.cmd_review_policy_ilcd;
  truncate table pg_temp.cmd_review_policy_tg;

  if p_actor is null
    or pg_catalog.jsonb_typeof(p_roots) <> 'array'
    or p_action not in ('submit', 'approve', 'publish') then
    return public.cmd_review_lifecycle_error(
      'REFERENCE_ROLE_POLICY_GAP',
      'request'
    );
  end if;

  for v_root in
    select root_item.value
    from pg_catalog.jsonb_array_elements(p_roots) as root_item(value)
  loop
    if lower(coalesce(v_root->>'table', ''))
      not in ('processes', 'lifecyclemodels')
      or coalesce(v_root->>'id', '')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or nullif(v_root->>'version', '') is null then
      return public.cmd_review_lifecycle_error(
        'REFERENCE_ROLE_POLICY_GAP',
        'request.root'
      );
    end if;

    insert into pg_temp.cmd_review_policy_queue (
      table_name,
      dataset_id,
      dataset_version,
      is_root,
      dependency_role,
      reference_path
    )
    values (
      lower(v_root->>'table'),
      (v_root->>'id')::uuid,
      v_root->>'version',
      true,
      'Root',
      'request.root'
    )
    on conflict do nothing;

    if v_publish_root_table is null then
      v_publish_root_table := lower(v_root->>'table');
      v_publish_root_id := (v_root->>'id')::uuid;
      v_publish_root_version := v_root->>'version';
    end if;
  end loop;

  while exists (select 1 from pg_temp.cmd_review_policy_queue) loop
    select
      queue.table_name,
      queue.dataset_id,
      queue.dataset_version,
      queue.is_root,
      queue.dependency_role,
      queue.reference_path
    into v_current
    from pg_temp.cmd_review_policy_queue as queue
    order by
      queue.is_root desc,
      queue.table_name,
      queue.dataset_id,
      queue.dataset_version
    limit 1;

    delete from pg_temp.cmd_review_policy_queue as queue
    where queue.table_name = v_current.table_name
      and queue.dataset_id = v_current.dataset_id
      and queue.dataset_version = v_current.dataset_version;

    if exists (
      select 1
      from pg_temp.cmd_review_policy_seen as seen
      where seen.table_name = v_current.table_name
        and seen.dataset_id = v_current.dataset_id
        and seen.dataset_version = v_current.dataset_version
    ) then
      continue;
    end if;

    v_row := public.cmd_review_get_dataset_row(
      v_current.table_name,
      v_current.dataset_id,
      v_current.dataset_version,
      true
    );

    if v_row is null then
      if v_current.dependency_role in ('ModelComposition', 'Paired') then
        return public.cmd_review_lifecycle_error(
          'MODEL_DEPENDENCY_NOT_PUBLIC',
          v_current.reference_path,
          v_current.table_name,
          v_current.dataset_id,
          v_current.dataset_version
        );
      end if;
      continue;
    end if;

    if v_current.is_root then
      v_root_owner := nullif(v_row->>'user_id', '')::uuid;
    elsif v_current.dependency_role in ('ModelComposition', 'Paired') then
      if p_action = 'publish' then
        if coalesce((v_row->>'state_code')::integer, 0) < 100
          and not (
            v_current.table_name = v_publish_root_table
            and v_current.dataset_id = v_publish_root_id
            and v_current.dataset_version = v_publish_root_version
          ) then
          return public.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            v_current.reference_path,
            v_current.table_name,
            v_current.dataset_id,
            v_current.dataset_version
          );
        end if;
      elsif coalesce((v_row->>'state_code')::integer, 0) < 100
        and nullif(v_row->>'user_id', '')::uuid is distinct from v_root_owner then
        return public.cmd_review_lifecycle_error(
          'MODEL_DEPENDENCY_NOT_PUBLIC',
          v_current.reference_path,
          v_current.table_name,
          v_current.dataset_id,
          v_current.dataset_version
        );
      end if;
    end if;

    insert into pg_temp.cmd_review_policy_seen (
      table_name,
      dataset_id,
      dataset_version
    )
    values (
      v_current.table_name,
      v_current.dataset_id,
      v_current.dataset_version
    );

    v_doc := case
      when coalesce(v_row->'json_ordered', 'null'::jsonb)
        not in ('null'::jsonb, '{}'::jsonb)
        then v_row->'json_ordered'
      else coalesce(v_row->'json', '{}'::jsonb)
    end;

    for v_ref in
      select *
      from public.cmd_review_reference_roles(
        v_current.table_name,
        'json',
        v_doc
      )
      order by reference_path, ref_table, ref_object_id, ref_version
    loop
      if v_ref.lifecycle_role = 'PolicyGap' then
        return public.cmd_review_lifecycle_error(
          'REFERENCE_ROLE_POLICY_GAP',
          v_ref.reference_path,
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version
        );
      elsif v_ref.lifecycle_role = 'RequiredSupport'
        and p_action in ('submit', 'approve') then
        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version,
          false,
          'RequiredSupport',
          v_ref.reference_path
        )
        on conflict do nothing;
      elsif v_ref.lifecycle_role = 'ModelComposition'
        and v_current.table_name <> 'lifecyclemodels' then
        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version,
          false,
          'ModelComposition',
          v_ref.reference_path
        )
        on conflict do nothing;
      end if;
    end loop;

    for v_ref in
      select *
      from public.cmd_review_reference_roles(
        v_current.table_name,
        'json_tg',
        coalesce(v_row->'json_tg', '{}'::jsonb)
      )
      order by reference_path, ref_table, ref_object_id, ref_version
    loop
      if v_ref.lifecycle_role = 'PolicyGap' then
        return public.cmd_review_lifecycle_error(
          'REFERENCE_ROLE_POLICY_GAP',
          v_ref.reference_path,
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version
        );
      elsif v_ref.lifecycle_role = 'RequiredSupport'
        and p_action in ('submit', 'approve') then
        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version,
          false,
          'RequiredSupport',
          v_ref.reference_path
        )
        on conflict do nothing;
      elsif v_ref.lifecycle_role = 'ModelComposition'
        and v_current.table_name <> 'lifecyclemodels' then
        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version,
          false,
          'ModelComposition',
          v_ref.reference_path
        )
        on conflict do nothing;
      end if;
    end loop;

    if v_current.table_name = 'lifecyclemodels' then
      truncate table pg_temp.cmd_review_policy_ilcd;
      truncate table pg_temp.cmd_review_policy_tg;

      insert into pg_temp.cmd_review_policy_ilcd (
        dataset_id,
        dataset_version,
        reference_path
      )
      select
        role_ref.ref_object_id,
        role_ref.ref_version,
        role_ref.reference_path
      from public.cmd_review_reference_roles(
        'lifecyclemodels',
        'json',
        v_doc
      ) as role_ref
      where role_ref.lifecycle_role = 'ModelComposition'
      on conflict do nothing;

      v_json_tg_submodels := coalesce(v_row#>'{json_tg,submodels}', '[]'::jsonb);
      if pg_catalog.jsonb_typeof(v_json_tg_submodels) <> 'array' then
        return public.cmd_review_lifecycle_error(
          'MODEL_COMPOSITION_POLICY_GAP',
          'json_tg.submodels'
        );
      end if;

      for v_submodel in
        select
          submodel.value,
          submodel.ordinality - 1 as item_index
        from pg_catalog.jsonb_array_elements(v_json_tg_submodels)
          with ordinality as submodel(value, ordinality)
        where lower(coalesce(submodel.value->>'type', '')) = 'secondary'
        order by submodel.ordinality
      loop
        if coalesce(v_submodel.value->>'id', '')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then
          return public.cmd_review_lifecycle_error(
            'MODEL_COMPOSITION_POLICY_GAP',
            'json_tg.submodels[' || v_submodel.item_index || ']'
          );
        end if;

        insert into pg_temp.cmd_review_policy_tg (
          dataset_id,
          dataset_version,
          reference_path
        )
        values (
          (v_submodel.value->>'id')::uuid,
          coalesce(
            nullif(v_submodel.value->>'version', ''),
            v_current.dataset_version
          ),
          'json_tg.submodels[' || v_submodel.item_index || ']'
        )
        on conflict do nothing;
      end loop;

      select exists (
        (
          select ilcd.dataset_id, ilcd.dataset_version
          from pg_temp.cmd_review_policy_ilcd as ilcd
          except
          select tg.dataset_id, tg.dataset_version
          from pg_temp.cmd_review_policy_tg as tg
        )
        union all
        (
          select tg.dataset_id, tg.dataset_version
          from pg_temp.cmd_review_policy_tg as tg
          except
          select ilcd.dataset_id, ilcd.dataset_version
          from pg_temp.cmd_review_policy_ilcd as ilcd
        )
      )
      into v_has_mismatch;

      if v_has_mismatch then
        return public.cmd_review_lifecycle_error(
          'MODEL_COMPOSITION_POLICY_GAP',
          'json_tg.submodels'
        );
      end if;

      for v_submodel in
        select
          tg.dataset_id,
          tg.dataset_version,
          tg.reference_path
        from pg_temp.cmd_review_policy_tg as tg
        order by tg.dataset_id, tg.dataset_version
      loop
        v_dependency := public.cmd_review_get_dataset_row(
          'processes',
          v_submodel.dataset_id,
          v_submodel.dataset_version,
          true
        );

        if v_dependency is null
          or (
            p_action = 'publish'
            and coalesce((v_dependency->>'state_code')::integer, 0) < 100
            and not (
              v_publish_root_table = 'processes'
              and v_submodel.dataset_id = v_publish_root_id
              and v_submodel.dataset_version = v_publish_root_version
            )
          )
          or (
            p_action in ('submit', 'approve')
            and coalesce((v_dependency->>'state_code')::integer, 0) < 100
            and nullif(v_dependency->>'user_id', '')::uuid
              is distinct from v_root_owner
          ) then
          return public.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            v_submodel.reference_path,
            'processes',
            v_submodel.dataset_id,
            v_submodel.dataset_version
          );
        end if;

        if p_action in ('submit', 'approve') then
          insert into pg_temp.cmd_review_policy_queue (
            table_name,
            dataset_id,
            dataset_version,
            is_root,
            dependency_role,
            reference_path
          )
          values (
            'processes',
            v_submodel.dataset_id,
            v_submodel.dataset_version,
            false,
            'ModelComposition',
            v_submodel.reference_path
          )
          on conflict do nothing;
        end if;
      end loop;
    end if;

    if v_current.table_name = 'processes' then
      v_paired := public.cmd_review_get_dataset_row(
        'lifecyclemodels',
        v_current.dataset_id,
        v_current.dataset_version,
        true
      );

      if v_paired is not null then
        if (
          p_action = 'publish'
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
        ) or (
          p_action in ('submit', 'approve')
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
          and (
            v_current.is_root
            or nullif(v_paired->>'user_id', '')::uuid
              is distinct from v_root_owner
          )
        ) then
          return public.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            'pairedLifecycleModel',
            'lifecyclemodels',
            v_current.dataset_id,
            v_current.dataset_version
          );
        end if;

        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          'lifecyclemodels',
          v_current.dataset_id,
          v_current.dataset_version,
          false,
          'Paired',
          'pairedLifecycleModel'
        )
        on conflict do nothing;
      end if;
    elsif v_current.table_name = 'lifecyclemodels'
      and v_current.is_root then
      v_paired := public.cmd_review_get_dataset_row(
        'processes',
        v_current.dataset_id,
        v_current.dataset_version,
        true
      );

      if v_paired is not null then
        if (
          p_action = 'publish'
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
        ) or (
          p_action in ('submit', 'approve')
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
          and nullif(v_paired->>'user_id', '')::uuid is distinct from v_root_owner
        ) then
          return public.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            'pairedProcess',
            'processes',
            v_current.dataset_id,
            v_current.dataset_version
          );
        end if;

        if p_action in ('submit', 'approve') then
          insert into pg_temp.cmd_review_policy_queue (
            table_name,
            dataset_id,
            dataset_version,
            is_root,
            dependency_role,
            reference_path
          )
          values (
            'processes',
            v_current.dataset_id,
            v_current.dataset_version,
            false,
            'Paired',
            'pairedProcess'
          )
          on conflict do nothing;
        end if;
      end if;
    end if;
  end loop;

  truncate table pg_temp.cmd_review_policy_queue;
  truncate table pg_temp.cmd_review_policy_seen;
  truncate table pg_temp.cmd_review_policy_ilcd;
  truncate table pg_temp.cmd_review_policy_tg;
  return null;
end;
$_$;


ALTER FUNCTION public.cmd_review_assert_lifecycle_closure(p_roots jsonb, p_action text, p_actor uuid) OWNER TO postgres;

--
-- Name: cmd_review_assign_reviewers(uuid, jsonb, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_assign_reviewers(p_review_id uuid, p_reviewer_ids jsonb, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review public.reviews%rowtype;
  v_reviewer_ids jsonb;
  v_review_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not public.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can assign reviewers'
    );
  end if;

  if coalesce(jsonb_typeof(p_reviewer_ids), 'null') <> 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEWER_IDS',
      'status', 400,
      'message', 'reviewerIds must be an array of UUID strings'
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements_text(p_reviewer_ids) as reviewer_ids(value)
    where reviewer_ids.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEWER_IDS',
      'status', 400,
      'message', 'reviewerIds must contain valid UUID strings only'
    );
  end if;

  v_reviewer_ids := public.cmd_review_normalize_reviewer_ids(p_reviewer_ids);

  if jsonb_array_length(v_reviewer_ids) = 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 400,
      'message', 'At least one reviewer is required'
    );
  end if;

  select *
    into v_review
  from public.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code not in (-1, 0, 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Reviewers can only be assigned for pending or rejected reviews',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  create temporary table if not exists cmd_review_assignment_active_reviewers (
    reviewer_id uuid primary key
  ) on commit drop;

  truncate table cmd_review_assignment_active_reviewers;

  insert into cmd_review_assignment_active_reviewers (reviewer_id)
  select value::uuid
  from jsonb_array_elements_text(v_reviewer_ids) as reviewer_ids(value);

  update public.comments
    set state_code = -2,
        modified_at = now()
  where review_id = p_review_id
    and reviewer_id not in (
      select reviewer_id
      from cmd_review_assignment_active_reviewers
    )
    and state_code = 0;

  insert into public.comments (
    review_id,
    reviewer_id,
    state_code
  )
  select
    p_review_id,
    reviewer_id,
    0
  from cmd_review_assignment_active_reviewers
  on conflict (review_id, reviewer_id) do update
    set state_code = case
      when public.comments.state_code in (-2, -1) then 0
      else public.comments.state_code
    end,
        modified_at = now();

  v_review_json := public.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'assign_reviewers',
    v_actor,
    jsonb_strip_nulls(
      jsonb_build_object(
        'reviewer_ids', v_reviewer_ids,
        'deadline', case
          when p_deadline is null then null
          else to_jsonb(p_deadline)
        end
      )
    )
  );

  update public.reviews
    set reviewer_id = v_reviewer_ids,
        state_code = 1,
        deadline = p_deadline,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_assign_reviewers',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_strip_nulls(
      jsonb_build_object(
        'reviewer_ids', v_reviewer_ids,
        'deadline', case
          when p_deadline is null then null
          else to_jsonb(p_deadline)
        end
      )
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review)
    )
  );
end;
$_$;


ALTER FUNCTION public.cmd_review_assign_reviewers(p_review_id uuid, p_reviewer_ids jsonb, p_deadline timestamp with time zone, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_change_member_role(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_change_member_role(p_user_id uuid, p_role text DEFAULT NULL::text, p_action text DEFAULT 'set'::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_action text := lower(coalesce(p_action, 'set'));
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_existing_role text;
  v_role_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'USER_ID_REQUIRED',
      'status', 400,
      'message', 'userId is required'
    );
  end if;

  if not public.cmd_membership_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FORBIDDEN',
      'status', 403,
      'message', 'Only a review admin can manage review members'
    );
  end if;

  select role
    into v_existing_role
  from public.roles
  where user_id = p_user_id
    and team_id = v_team_id
  for update;

  if v_action = 'remove' then
    if v_existing_role is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'ROLE_NOT_FOUND',
        'status', 404,
        'message', 'Role not found'
      );
    end if;

    if p_user_id = v_actor or v_existing_role <> 'review-member' then
      return jsonb_build_object(
        'ok', false,
        'code', 'FORBIDDEN',
        'status', 403,
        'message', 'Only review-member rows can be removed'
      );
    end if;

    delete from public.roles
    where user_id = p_user_id
      and team_id = v_team_id;

    insert into public.command_audit_log (
      command,
      actor_user_id,
      target_table,
      target_id,
      target_version,
      payload
    )
    values (
      'cmd_review_change_member_role',
      v_actor,
      'roles',
      p_user_id,
      v_team_id::text,
      coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
        'action', 'remove'
      )
    );

    return jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object(
        'removed', true,
        'user_id', p_user_id,
        'team_id', v_team_id
      )
    );
  end if;

  if v_action <> 'set' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_ACTION',
      'status', 400,
      'message', 'Unsupported action'
    );
  end if;

  if p_role not in ('review-member', 'review-admin') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_ROLE',
      'status', 400,
      'message', 'Unsupported review role transition'
    );
  end if;

  if v_existing_role is null then
    if p_role <> 'review-member' then
      return jsonb_build_object(
        'ok', false,
        'code', 'INVALID_ROLE_STATE',
        'status', 409,
        'message', 'A new review member must start as review-member'
      );
    end if;

    insert into public.roles (
      user_id,
      team_id,
      role,
      modified_at
    )
    values (
      p_user_id,
      v_team_id,
      p_role,
      now()
    )
    returning to_jsonb(roles.*)
      into v_role_row;
  elsif v_existing_role in ('review-member', 'review-admin') then
    update public.roles
      set role = p_role,
          modified_at = now()
    where user_id = p_user_id
      and team_id = v_team_id
    returning to_jsonb(roles.*)
      into v_role_row;
  else
    return jsonb_build_object(
      'ok', false,
      'code', 'ROLE_CONFLICT',
      'status', 409,
      'message', 'The existing zero-team role belongs to another scope'
    );
  end if;

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_review_change_member_role',
    v_actor,
    'roles',
    p_user_id,
    v_team_id::text,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'action', 'set',
      'role', p_role
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_role_row
  );
exception
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ROLE_CONFLICT',
      'status', 409,
      'message', 'The existing zero-team role belongs to another scope'
    );
end;
$$;


ALTER FUNCTION public.cmd_review_change_member_role(p_user_id uuid, p_role text, p_action text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_collect_dataset_targets(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_collect_dataset_targets(p_roots jsonb, p_lock boolean DEFAULT false) RETURNS TABLE(table_name text, dataset_id uuid, dataset_version text, state_code integer, reviews jsonb, dataset_row jsonb, is_root boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_root jsonb;
  v_current record;
  v_current_row jsonb;
  v_current_state_code integer;
  v_ref record;
  v_ref_table text;
  v_submodel jsonb;
  v_paired_model_exists boolean;
  v_paired_process_exists boolean;
begin
  create temporary table if not exists cmd_review_collect_queue (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    is_root boolean not null default false,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  create temporary table if not exists cmd_review_collect_targets (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    state_code integer not null,
    reviews jsonb,
    dataset_row jsonb not null,
    is_root boolean not null default false,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  truncate table cmd_review_collect_queue;
  truncate table cmd_review_collect_targets;

  if jsonb_typeof(p_roots) <> 'array' then
    return;
  end if;

  for v_root in
    select value
    from jsonb_array_elements(p_roots)
  loop
    if lower(coalesce(v_root->>'table', '')) not in (
      'contacts',
      'sources',
      'unitgroups',
      'flowproperties',
      'flows',
      'processes',
      'lifecyclemodels'
    ) then
      continue;
    end if;

    if not (coalesce(v_root->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
      continue;
    end if;

    if nullif(v_root->>'version', '') is null then
      continue;
    end if;

    insert into cmd_review_collect_queue (
      table_name,
      dataset_id,
      dataset_version,
      is_root
    )
    values (
      lower(v_root->>'table'),
      (v_root->>'id')::uuid,
      v_root->>'version',
      coalesce((v_root->>'is_root')::boolean, false)
    )
    on conflict do nothing;
  end loop;

  while exists (select 1 from cmd_review_collect_queue) loop
    select
      q.table_name,
      q.dataset_id,
      q.dataset_version,
      q.is_root
    into v_current
    from cmd_review_collect_queue as q
    order by q.is_root desc, q.table_name, q.dataset_id, q.dataset_version
    limit 1;

    delete from cmd_review_collect_queue as q
    where q.table_name = v_current.table_name
      and q.dataset_id = v_current.dataset_id
      and q.dataset_version = v_current.dataset_version;

    if exists (
      select 1
      from cmd_review_collect_targets as t
      where t.table_name = v_current.table_name
        and t.dataset_id = v_current.dataset_id
        and t.dataset_version = v_current.dataset_version
    ) then
      continue;
    end if;

    v_current_row := public.cmd_review_get_dataset_row(
      v_current.table_name,
      v_current.dataset_id,
      v_current.dataset_version,
      p_lock
    );

    if v_current_row is null then
      continue;
    end if;

    v_current_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

    insert into cmd_review_collect_targets (
      table_name,
      dataset_id,
      dataset_version,
      state_code,
      reviews,
      dataset_row,
      is_root
    )
    values (
      v_current.table_name,
      v_current.dataset_id,
      v_current.dataset_version,
      v_current_state_code,
      v_current_row->'reviews',
      v_current_row,
      v_current.is_root
    )
    on conflict do nothing;

    if v_current_state_code >= 100 and not v_current.is_root then
      if v_current.table_name = 'processes' then
        v_paired_model_exists := public.cmd_review_get_dataset_row(
          'lifecyclemodels',
          v_current.dataset_id,
          v_current.dataset_version,
          false
        ) is not null;

        if v_paired_model_exists then
          insert into cmd_review_collect_queue (
            table_name,
            dataset_id,
            dataset_version,
            is_root
          )
          values (
            'lifecyclemodels',
            v_current.dataset_id,
            v_current.dataset_version,
            false
          )
          on conflict do nothing;
        end if;
      end if;

      continue;
    end if;

    for v_ref in (
      select *
      from public.cmd_review_extract_refs(coalesce(v_current_row->'json_ordered', '{}'::jsonb))
      union
      select *
      from public.cmd_review_extract_refs(coalesce(v_current_row->'json', '{}'::jsonb))
      union
      select *
      from public.cmd_review_extract_refs(coalesce(v_current_row->'json_tg', '{}'::jsonb))
    ) loop
      v_ref_table := public.cmd_review_ref_type_to_table(v_ref.ref_type);

      if v_ref_table is null then
        continue;
      end if;

      if v_ref_table = v_current.table_name
         and v_ref.ref_object_id = v_current.dataset_id
         and v_ref.ref_version = v_current.dataset_version then
        continue;
      end if;

      insert into cmd_review_collect_queue (
        table_name,
        dataset_id,
        dataset_version,
        is_root
      )
      values (
        v_ref_table,
        v_ref.ref_object_id,
        v_ref.ref_version,
        false
      )
      on conflict do nothing;
    end loop;

    if v_current.table_name = 'processes' and not v_current.is_root then
      v_paired_model_exists := public.cmd_review_get_dataset_row(
        'lifecyclemodels',
        v_current.dataset_id,
        v_current.dataset_version,
        false
      ) is not null;

      if v_paired_model_exists then
        insert into cmd_review_collect_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root
        )
        values (
          'lifecyclemodels',
          v_current.dataset_id,
          v_current.dataset_version,
          false
        )
        on conflict do nothing;
      end if;
    end if;

    if v_current.table_name = 'lifecyclemodels' then
      if v_current.is_root then
        v_paired_process_exists := public.cmd_review_get_dataset_row(
          'processes',
          v_current.dataset_id,
          v_current.dataset_version,
          false
        ) is not null;

        if v_paired_process_exists then
          insert into cmd_review_collect_queue (
            table_name,
            dataset_id,
            dataset_version,
            is_root
          )
          values (
            'processes',
            v_current.dataset_id,
            v_current.dataset_version,
            false
          )
          on conflict do nothing;
        end if;
      end if;

      for v_submodel in
        select value
        from jsonb_array_elements(coalesce(v_current_row->'json_tg'->'submodels', '[]'::jsonb))
      loop
        if lower(coalesce(v_submodel->>'type', '')) <> 'secondary' then
          continue;
        end if;

        if not ((v_submodel->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
          continue;
        end if;

        insert into cmd_review_collect_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root
        )
        values (
          'processes',
          (v_submodel->>'id')::uuid,
          coalesce(nullif(v_submodel->>'version', ''), v_current.dataset_version),
          false
        )
        on conflict do nothing;
      end loop;
    end if;
  end loop;

  return query
  select
    t.table_name,
    t.dataset_id,
    t.dataset_version,
    t.state_code,
    t.reviews,
    t.dataset_row,
    t.is_root
  from cmd_review_collect_targets as t
  order by t.is_root desc, t.table_name, t.dataset_id, t.dataset_version;
end;
$_$;


ALTER FUNCTION public.cmd_review_collect_dataset_targets(p_roots jsonb, p_lock boolean) OWNER TO postgres;

--
-- Name: cmd_review_extract_refs(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_extract_refs(p_json jsonb) RETURNS TABLE(ref_type text, ref_object_id uuid, ref_version text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct
    role_ref.ref_type,
    role_ref.ref_object_id,
    role_ref.ref_version
  from public.cmd_review_reference_roles(
    case
      when coalesce(p_json, '{}'::jsonb) ? 'processDataSet' then 'processes'
      when coalesce(p_json, '{}'::jsonb) ? 'lifeCycleModelDataSet'
        then 'lifecyclemodels'
      when coalesce(p_json, '{}'::jsonb) ? 'flowDataSet' then 'flows'
      when coalesce(p_json, '{}'::jsonb) ? 'flowPropertyDataSet'
        then 'flowproperties'
      when coalesce(p_json, '{}'::jsonb) ? 'unitGroupDataSet'
        then 'unitgroups'
      when coalesce(p_json, '{}'::jsonb) ? 'sourceDataSet' then 'sources'
      when coalesce(p_json, '{}'::jsonb) ? 'contactDataSet' then 'contacts'
      else 'comments'
    end,
    'json',
    p_json
  ) as role_ref
  where role_ref.lifecycle_role in ('RequiredSupport', 'ModelComposition')
$$;


ALTER FUNCTION public.cmd_review_extract_refs(p_json jsonb) OWNER TO postgres;

--
-- Name: cmd_review_get_actor_meta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_get_actor_meta(p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_meta jsonb;
  v_display_name text;
  v_email text;
begin
  select u.raw_user_meta_data
    into v_meta
  from public.users as u
  where u.id = p_actor;

  v_display_name := coalesce(nullif(v_meta->>'display_name', ''), nullif(v_meta->>'email', ''));
  v_email := nullif(v_meta->>'email', '');

  return jsonb_strip_nulls(
    jsonb_build_object(
      'id', p_actor,
      'display_name', v_display_name,
      'email', v_email
    )
  );
end;
$$;


ALTER FUNCTION public.cmd_review_get_actor_meta(p_actor uuid) OWNER TO postgres;

--
-- Name: cmd_review_get_dataset_name(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_get_dataset_name(p_table text, p_row jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_table
    when 'contacts' then coalesce(
      p_row#>'{json,contactDataSet,contactInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,contactDataSet,contactInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'sources' then coalesce(
      p_row#>'{json,sourceDataSet,sourceInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,sourceDataSet,sourceInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'unitgroups' then coalesce(
      p_row#>'{json,unitGroupDataSet,unitGroupInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,unitGroupDataSet,unitGroupInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'flowproperties' then coalesce(
      p_row#>'{json,flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'flows' then coalesce(
      p_row#>'{json,flowDataSet,flowInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,flowDataSet,flowInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'processes' then coalesce(
      p_row#>'{json,processDataSet,processInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,processDataSet,processInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'lifecyclemodels' then coalesce(
      p_row#>'{json,lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    else '{}'::jsonb
  end
$$;


ALTER FUNCTION public.cmd_review_get_dataset_name(p_table text, p_row jsonb) OWNER TO postgres;

--
-- Name: cmd_review_get_dataset_row(text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_get_dataset_row(p_table text, p_id uuid, p_version text, p_lock boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_row jsonb;
begin
  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return null;
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 %s',
    p_table,
    case when p_lock then 'for update of t' else '' end
  )
    into v_row
    using p_id, p_version;

  return v_row;
end;
$_$;


ALTER FUNCTION public.cmd_review_get_dataset_row(p_table text, p_id uuid, p_version text, p_lock boolean) OWNER TO postgres;

--
-- Name: cmd_review_get_root_table(jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_get_root_table(p_review_json jsonb, p_data_id uuid, p_data_version text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_explicit text := lower(nullif(p_review_json#>>'{data,table}', ''));
  v_process_row jsonb;
  v_model_row jsonb;
  v_expected_name jsonb := coalesce(p_review_json#>'{data,name}', '{}'::jsonb);
begin
  if v_explicit in ('processes', 'lifecyclemodels') then
    return v_explicit;
  end if;

  v_process_row := public.cmd_review_get_dataset_row('processes', p_data_id, p_data_version, false);
  v_model_row := public.cmd_review_get_dataset_row(
    'lifecyclemodels',
    p_data_id,
    p_data_version,
    false
  );

  if v_model_row is not null
     and public.cmd_review_get_dataset_name('lifecyclemodels', v_model_row) = v_expected_name then
    return 'lifecyclemodels';
  end if;

  if v_process_row is not null
     and public.cmd_review_get_dataset_name('processes', v_process_row) = v_expected_name then
    return 'processes';
  end if;

  if v_model_row is not null and v_process_row is null then
    return 'lifecyclemodels';
  end if;

  if v_process_row is not null then
    return 'processes';
  end if;

  return null;
end;
$$;


ALTER FUNCTION public.cmd_review_get_root_table(p_review_json jsonb, p_data_id uuid, p_data_version text) OWNER TO postgres;

--
-- Name: cmd_review_is_review_admin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cmd_review_is_review_admin(p_actor uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.roles
    where user_id = coalesce(p_actor, auth.uid())
      and team_id = '00000000-0000-0000-0000-000000000000'::uuid
      and role = 'review-admin'
  )
$$;


