-- Name: get_lcia_scope_closure_report_download(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_lcia_scope_closure_report_download(p_closure_check_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
