-- Name: COLUMN worker_job_artifacts.expires_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_job_artifacts.expires_at IS 'Trusted retention deadline. Scope-closure evidence expires no later than seven days after creation.';


--
-- Name: COLUMN worker_job_artifacts.artifact_role; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_job_artifacts.artifact_role IS 'Authoritative role for seven-day scope-closure evidence artifacts.';


--
-- Name: COLUMN worker_job_artifacts.gc_cleanup_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_job_artifacts.gc_cleanup_state IS 'DB-owned bounded detail-cleanup state: pending rows remain service-claimable after Storage object deletion.';


--
-- Name: lcia_scope_closure_artifact_lineage_eligible(public.lcia_scope_closure_checks, public.worker_job_artifacts, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lcia_scope_closure_artifact_lineage_eligible(p_check public.lcia_scope_closure_checks, p_artifact public.worker_job_artifacts, p_public_artifact_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_public_artifact_role
    when 'closure_report_xlsx' then
      (p_artifact).id = (p_check).report_artifact_id
      and (p_artifact).job_id = (p_check).worker_job_id
      and (p_artifact).artifact_role = 'closure_report'
      and (p_artifact).artifact_type = 'closure_report_xlsx'
    when 'closure_issue_manifest' then
      (p_artifact).id = (p_check).complete_machine_result_artifact_id
      and (p_artifact).artifact_role = 'complete_machine_result'
      and (p_artifact).artifact_type = 'closure_complete_machine_result'
      and (
        (p_artifact).job_id = (p_check).worker_job_id
        or exists (
          select 1
          from public.lcia_scope_closure_checks source_check
          where source_check.id = (p_check).reused_from_check_id
            and source_check.worker_job_id = (p_artifact).job_id
        )
      )
    else false
  end
$$;


ALTER FUNCTION public.lcia_scope_closure_artifact_lineage_eligible(p_check public.lcia_scope_closure_checks, p_artifact public.worker_job_artifacts, p_public_artifact_role text) OWNER TO postgres;

--
-- Name: lcia_scope_closure_artifact_write_set_json(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lcia_scope_closure_artifact_write_set_json(p_write_set_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'writeSetId', write_set.id,
    'closureCheckId', write_set.closure_check_id,
    'workerJobId', write_set.worker_job_id,
    'requestedBy', write_set.requested_by,
    'publicationMode', write_set.publication_mode,
    'reusedFromCheckId', write_set.reused_from_check_id,
    'status', write_set.status,
    'writeToken', write_set.write_token,
    'stagingExpiresAt', write_set.staging_expires_at,
    'reconcileToken', write_set.reconcile_token,
    'reconcileLeaseExpiresAt', write_set.reconcile_expires_at,
    'failureReason', write_set.failure_reason,
    'createdAt', write_set.created_at,
    'updatedAt', write_set.updated_at,
    'finalizedAt', write_set.finalized_at,
    'cleanedAt', write_set.cleaned_at,
    'artifactMap', coalesce((
      select jsonb_object_agg(item.client_key, item.id order by item.client_key)
      from public.lcia_scope_closure_artifact_write_set_items item
      where item.write_set_id = write_set.id
    ), '{}'::jsonb),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'artifactId', item.id,
        'ordinal', item.ordinal,
        'clientKey', item.client_key,
        'artifactType', item.artifact_type,
        'artifactRole', item.artifact_role,
        'bucket', item.storage_bucket,
        'objectPath', item.storage_path,
        'mediaType', item.content_type,
        'size', item.byte_size,
        'checksumSha256', item.checksum_sha256,
        'metadata', item.metadata
      ) order by item.ordinal)
      from public.lcia_scope_closure_artifact_write_set_items item
      where item.write_set_id = write_set.id
    ), '[]'::jsonb)
  )
  from public.lcia_scope_closure_artifact_write_sets write_set
  where write_set.id = p_write_set_id
$$;


ALTER FUNCTION public.lcia_scope_closure_artifact_write_set_json(p_write_set_id uuid) OWNER TO postgres;

--
-- Name: lcia_scope_closure_build_admission_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lcia_scope_closure_build_admission_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_check public.lcia_scope_closure_checks%rowtype;
  v_check_id uuid;
begin
  if new.job_kind <> 'lcia_result.package_build'
     or new.payload_schema_version <> 'lcia_result.package_build.request.v2' then
    return new;
  end if;

  begin
    v_check_id := nullif(new.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'closure_certificate_expired_or_unavailable'
      using errcode = '23514';
  end;

  select * into v_check
  from public.lcia_scope_closure_checks
  where id = v_check_id
    and requested_by = new.requested_by;
  if v_check.id is null
     or not public.lcia_scope_closure_evidence_usable(v_check) then
    raise exception 'closure_certificate_expired_or_unavailable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.lcia_scope_closure_build_admission_guard() OWNER TO postgres;

