--
-- Name: list_lcia_scope_closure_issues(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_lcia_scope_closure_issues(p_closure_check_id uuid, p_after_issue_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));
begin
  if v_actor is null then
    return public.lcia_scope_closure_error('auth_required', 401, 'Authentication required');
  end if;
  if not public.lcia_scope_closure_is_manager()
     or not exists (
       select 1
       from public.lcia_scope_closure_checks c
       where c.id = p_closure_check_id
         and c.requested_by = v_actor
     ) then
    return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;

  return jsonb_build_object('ok', true, 'data', (
    with page as (
      select i.*
      from public.lcia_scope_closure_issues i
      where i.closure_check_id = p_closure_check_id
        and (p_after_issue_id is null or i.id > p_after_issue_id)
      order by i.id
      limit v_limit + 1
    ), shown as (
      select * from page order by id limit v_limit
    )
    select jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-issues-page.v1',
      'closureCheckId', p_closure_check_id,
      'issues', coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'issueId', id,
        'severity', severity,
        'blocking', blocking,
        'code', issue_code,
        'title', issue_code,
        'summary', message,
        'suggestedAction', suggested_action,
        'occurrenceCount', occurrence_count,
        'affectedRootCount', affected_root_count
      )) order by id), '[]'::jsonb),
      'totalCount', (
        select count(*)
        from public.lcia_scope_closure_issues
        where closure_check_id = p_closure_check_id
      ),
      'nextCursor', case when exists (select 1 from page offset v_limit)
        then (select id from shown order by id desc limit 1)
        else null
      end
    )
    from shown
  ));
end;
$$;


ALTER FUNCTION public.list_lcia_scope_closure_issues(p_closure_check_id uuid, p_after_issue_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: pgroonga_search_contacts(text, text, bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgroonga_search_contacts(query_text text, filter_condition text DEFAULT ''::text, page_size bigint DEFAULT 10, page_current bigint DEFAULT 1, data_source text DEFAULT 'tg'::text, this_user_id text DEFAULT ''::text) RETURNS TABLE(rank bigint, id uuid, "json" jsonb, version character, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    filter_condition_jsonb JSONB;
BEGIN
	filter_condition_jsonb := filter_condition::JSONB;
  RETURN QUERY
		SELECT 
			RANK () OVER (ORDER BY pgroonga_score(f.tableoid, f.ctid) DESC) AS rank, 
			f.id, 
			f.json,
			f.version,
			f.modified_at,
			COUNT(*) OVER() AS total_count
		FROM contacts f
		WHERE f.json @> filter_condition_jsonb AND f.json &@~ query_text AND ((data_source = 'tg' AND state_code = 100) or (data_source = 'my' AND user_id::text = this_user_id))
		ORDER BY pgroonga_score(tableoid, ctid) DESC
		LIMIT page_size
		OFFSET (page_current -1) * page_size;
END;
$$;


ALTER FUNCTION public.pgroonga_search_contacts(query_text text, filter_condition text, page_size bigint, page_current bigint, data_source text, this_user_id text) OWNER TO postgres;

