    json_ordered json,
    user_id uuid DEFAULT auth.uid(),
    state_code integer DEFAULT 0,
    version character(9) NOT NULL,
    modified_at timestamp with time zone DEFAULT now(),
    team_id uuid,
    review_id uuid,
    rule_verification boolean,
    reviews jsonb,
    model_id uuid,
    embedding_ft_at timestamp with time zone,
    embedding_ft extensions.vector(1024),
    extracted_md text,
    CONSTRAINT processes_state_code_check CHECK ((state_code = ANY (ARRAY[0, 20, 100, 200])))
);


ALTER TABLE public.processes OWNER TO postgres;

--
-- Name: processes_derivative_rebuild_embedding_input(public.processes); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.processes_derivative_rebuild_embedding_input(p_process public.processes) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select proposal.extracted_md
  from util.dataset_derivative_rebuild_requests as request
  join util.dataset_derivative_rebuild_proposals as proposal
    on proposal.id = request.markdown_proposal_id
   and proposal.request_id = request.id
   and proposal.proposal_kind = 'markdown'
   and proposal.status = 'accepted'
  where request.target_table = 'processes'
    and request.target_id = p_process.id
    and request.target_version = btrim(p_process.version::text)
    and request.status = 'embedding_pending'
    and request.accepted_extracted_md_sha256 = proposal.extracted_md_sha256
  limit 1
$$;


ALTER FUNCTION public.processes_derivative_rebuild_embedding_input(p_process public.processes) OWNER TO postgres;

