--
-- Name: qry_review_get_admin_queue_items(text, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_review_get_admin_queue_items(p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, state_code integer, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_codes jsonb, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := public.cmd_review_resolve_queue_order_by(p_sort_by, false);
  v_order_dir text := public.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := lower(coalesce(p_status, ''));
  v_state_code integer;
begin
  if v_actor is null then
    return;
  end if;

  if not public.cmd_review_is_review_admin(v_actor) then
    return;
  end if;

  case v_status
    when '', 'all' then
      v_state_code := null;
    when 'unassigned' then
      v_state_code := 0;
    when 'assigned' then
      v_state_code := 1;
    when 'admin-rejected' then
      v_state_code := -1;
    else
      return;
  end case;

  return query execute format(
    $sql$
      with q as (
        select
          r.id,
          r.data_id,
          r.data_version::text as data_version,
          r.state_code,
          coalesce(r.reviewer_id, '[]'::jsonb) as reviewer_id,
          coalesce(r.json, '{}'::jsonb) as json,
          r.deadline,
          r.created_at,
          r.modified_at,
          coalesce(
            jsonb_agg(to_jsonb(c.state_code) order by c.created_at asc, c.reviewer_id asc)
              filter (where c.reviewer_id is not null),
            '[]'::jsonb
          ) as comment_state_codes
        from public.reviews as r
        left join public.comments as c
          on c.review_id = r.id
        where ($1::integer is null or r.state_code = $1::integer)
        group by
          r.id,
          r.data_id,
          r.data_version,
          r.state_code,
          r.reviewer_id,
          r.json,
          r.deadline,
          r.created_at,
          r.modified_at
      )
      select
        q.id,
        q.data_id,
        q.data_version,
        q.state_code,
        q.reviewer_id,
        q.json,
        q.deadline,
        q.created_at,
        q.modified_at,
        q.comment_state_codes,
        count(*) over() as total_count
      from q
      order by %s %s nulls last, q.id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_state_code, v_limit, v_offset;
end;
$_$;


ALTER FUNCTION public.qry_review_get_admin_queue_items(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: qry_review_get_comment_items(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_review_get_comment_items(p_review_id uuid, p_scope text DEFAULT 'auto'::text) RETURNS TABLE(review_id uuid, reviewer_id uuid, state_code integer, "json" jsonb, created_at timestamp with time zone, modified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with actor as (
    select
      auth.uid() as actor_id,
      public.cmd_review_is_review_admin(auth.uid()) as is_review_admin,
      exists (
        select 1
        from public.reviews as r
        where r.id = p_review_id
          and ((r.json -> 'user' ->> 'id')::uuid = auth.uid())
      ) as is_owner
  )
  select
    c.review_id,
    c.reviewer_id,
    c.state_code,
    coalesce(c.json::jsonb, '{}'::jsonb) as json,
    c.created_at,
    c.modified_at
  from public.comments as c
  cross join actor as a
  where c.review_id = p_review_id
    and public.policy_review_can_read(p_review_id, a.actor_id)
    and (
      a.is_review_admin
      or a.is_owner
      or c.reviewer_id = a.actor_id
    )
    and (
      lower(coalesce(p_scope, 'auto')) not in ('mine', 'self')
      or c.reviewer_id = a.actor_id
    )
  order by c.created_at asc, c.reviewer_id asc
$$;


ALTER FUNCTION public.qry_review_get_comment_items(p_review_id uuid, p_scope text) OWNER TO postgres;

--
-- Name: qry_review_get_items(uuid[], uuid, text, integer[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_review_get_items(p_review_ids uuid[] DEFAULT NULL::uuid[], p_data_id uuid DEFAULT NULL::uuid, p_data_version text DEFAULT NULL::text, p_state_codes integer[] DEFAULT NULL::integer[]) RETURNS TABLE(id uuid, data_id uuid, data_version text, state_code integer, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    r.id,
    r.data_id,
    r.data_version::text as data_version,
    r.state_code,
    coalesce(r.reviewer_id, '[]'::jsonb) as reviewer_id,
    coalesce(r.json, '{}'::jsonb) as json,
    r.deadline,
    r.created_at,
    r.modified_at
  from public.reviews as r
  where (p_review_ids is null or r.id = any (p_review_ids))
    and (
      p_data_id is null
      or r.data_id = p_data_id
      or coalesce(r.json -> 'data' ->> 'id', '') = p_data_id::text
    )
    and (
      p_data_version is null
      or r.data_version = p_data_version
      or coalesce(r.json -> 'data' ->> 'version', '') = p_data_version
    )
    and (p_state_codes is null or r.state_code = any (p_state_codes))
    and public.policy_review_can_read(r.id, auth.uid())
  order by r.modified_at desc, r.id desc
$$;


ALTER FUNCTION public.qry_review_get_items(p_review_ids uuid[], p_data_id uuid, p_data_version text, p_state_codes integer[]) OWNER TO postgres;

--
-- Name: qry_review_get_member_list(integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_review_get_member_list(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text, p_role text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, team_id uuid, role text, email text, display_name text, created_at timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := public.cmd_membership_resolve_member_order_by(p_sort_by, false);
  v_order_dir text := public.cmd_membership_resolve_sort_direction(p_sort_order);
begin
  if v_actor is null then
    return;
  end if;

  if not public.cmd_membership_is_review_admin(v_actor) then
    return;
  end if;

  return query execute format(
    $sql$
      with members as (
        select
          r.user_id,
          r.team_id,
          r.role::text as role,
          coalesce(u.raw_user_meta_data->>'email', '') as email,
          coalesce(
            nullif(u.raw_user_meta_data->>'display_name', ''),
            u.raw_user_meta_data->>'email',
            '-'
          ) as display_name,
          r.created_at,
          r.modified_at
        from public.roles as r
        left join public.users as u
          on u.id = r.user_id
        where r.team_id = $1
          and r.role in ('review-admin', 'review-member')
          and ($4::text is null or r.role = $4::text)
      )
      select
        m.user_id,
        m.team_id,
        m.role,
        m.email,
        m.display_name,
        m.created_at,
        m.modified_at,
        count(*) over() as total_count
      from members as m
      order by %s %s nulls last, m.user_id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_team_id, v_limit, v_offset, p_role;
end;
$_$;


ALTER FUNCTION public.qry_review_get_member_list(p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_role text) OWNER TO postgres;

--
-- Name: qry_review_get_member_queue_items(text, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_review_get_member_queue_items(p_status text DEFAULT 'pending'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, review_state_code integer, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_code integer, comment_json jsonb, comment_created_at timestamp with time zone, comment_modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := public.cmd_review_resolve_queue_order_by(p_sort_by, true);
  v_order_dir text := public.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := lower(coalesce(p_status, 'pending'));
begin
  if v_actor is null then
    return;
  end if;

  if not public.cmd_review_is_review_member(v_actor) then
    return;
  end if;

  if v_status not in ('pending', 'reviewed', 'reviewer-rejected') then
    return;
  end if;

  return query execute format(
    $sql$
      with q as (
        select
          r.id,
          r.data_id,
          r.data_version::text as data_version,
          r.state_code as review_state_code,
          coalesce(r.reviewer_id, '[]'::jsonb) as reviewer_id,
          coalesce(r.json, '{}'::jsonb) as json,
          r.deadline,
          r.created_at,
          r.modified_at,
          c.state_code as comment_state_code,
          coalesce(c.json::jsonb, '{}'::jsonb) as comment_json,
          c.created_at as comment_created_at,
          c.modified_at as comment_modified_at
        from public.comments as c
        join public.reviews as r
          on r.id = c.review_id
        where c.reviewer_id = $1
          and public.policy_review_can_read(r.id, $1)
          and (
            ($4::text = 'pending' and c.state_code = 0 and r.state_code > 0)
            or ($4::text = 'reviewed' and c.state_code = any (array[1, 2, -3]) and r.state_code > 0)
            or ($4::text = 'reviewer-rejected' and c.state_code = -1 and r.state_code = -1)
          )
      )
      select
        q.id,
        q.data_id,
        q.data_version,
        q.review_state_code,
        q.reviewer_id,
        q.json,
        q.deadline,
        q.created_at,
        q.modified_at,
        q.comment_state_code,
        q.comment_json,
        q.comment_created_at,
        q.comment_modified_at,
        count(*) over() as total_count
      from q
      order by %s %s nulls last, q.id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_actor, v_limit, v_offset, v_status;
end;
$_$;


ALTER FUNCTION public.qry_review_get_member_queue_items(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: qry_review_get_member_workload(integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_review_get_member_workload(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text, p_role text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, team_id uuid, role text, email text, display_name text, pending_count bigint, reviewed_count bigint, created_at timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := public.cmd_membership_resolve_member_order_by(p_sort_by, true);
  v_order_dir text := public.cmd_membership_resolve_sort_direction(p_sort_order);
begin
  if v_actor is null then
    return;
  end if;

  if not public.cmd_membership_is_review_admin(v_actor) then
    return;
  end if;

  return query execute format(
    $sql$
      with members as (
        select
          r.user_id,
          r.team_id,
          r.role::text as role,
          coalesce(u.raw_user_meta_data->>'email', '') as email,
          coalesce(
            nullif(u.raw_user_meta_data->>'display_name', ''),
            u.raw_user_meta_data->>'email',
            '-'
          ) as display_name,
          coalesce(w.pending_count, 0) as pending_count,
          coalesce(w.reviewed_count, 0) as reviewed_count,
          r.created_at,
          r.modified_at
        from public.roles as r
        left join public.users as u
          on u.id = r.user_id
        left join lateral (
          select
            count(*) filter (
              where c.state_code = 0
                and rv.state_code > 0
            ) as pending_count,
            count(*) filter (
              where c.state_code in (1, 2)
                and rv.state_code > 0
            ) as reviewed_count
          from public.comments as c
          join public.reviews as rv
            on rv.id = c.review_id
          where c.reviewer_id = r.user_id
            and c.state_code in (0, 1, 2)
        ) as w on true
        where r.team_id = $1
          and r.role in ('review-admin', 'review-member')
          and ($4::text is null or r.role = $4::text)
      )
      select
        m.user_id,
        m.team_id,
        m.role,
        m.email,
        m.display_name,
        m.pending_count,
        m.reviewed_count,
        m.created_at,
        m.modified_at,
        count(*) over() as total_count
      from members as m
      order by %s %s nulls last, m.user_id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_team_id, v_limit, v_offset, p_role;
end;
$_$;


ALTER FUNCTION public.qry_review_get_member_workload(p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_role text) OWNER TO postgres;

--
-- Name: qry_system_get_member_list(integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_system_get_member_list(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(user_id uuid, team_id uuid, role text, email text, display_name text, created_at timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := public.cmd_membership_resolve_member_order_by(p_sort_by, false);
  v_order_dir text := public.cmd_membership_resolve_sort_direction(p_sort_order);
begin
  if v_actor is null then
    return;
  end if;

  if not public.cmd_membership_is_system_manager(v_actor) then
    return;
  end if;

  return query execute format(
    $sql$
      with members as (
        select
          r.user_id,
          r.team_id,
          r.role::text as role,
          coalesce(u.raw_user_meta_data->>'email', '') as email,
          coalesce(
            nullif(u.raw_user_meta_data->>'display_name', ''),
            u.raw_user_meta_data->>'email',
            '-'
          ) as display_name,
          r.created_at,
          r.modified_at
        from public.roles as r
        left join public.users as u
          on u.id = r.user_id
        where r.team_id = $1
          and r.role in ('owner', 'admin', 'member')
      )
      select
        m.user_id,
        m.team_id,
        m.role,
        m.email,
        m.display_name,
        m.created_at,
        m.modified_at,
        count(*) over() as total_count
      from members as m
      order by %s %s nulls last, m.user_id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_team_id, v_limit, v_offset;
end;
$_$;


ALTER FUNCTION public.qry_system_get_member_list(p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: qry_team_find_invitable_user_by_email(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.qry_team_find_invitable_user_by_email(p_team_id uuid, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_user_id uuid;
  v_user_email text;
  v_user_meta jsonb := '{}'::jsonb;
  v_requested_team_role text;
  v_other_team_role text;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_team_id is null or v_email = '' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_PAYLOAD',
      'status', 400,
      'message', 'teamId and email are required'
    );
  end if;

  if p_team_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_TEAM_SCOPE',
      'status', 400,
      'message', 'Use system or review member commands for the zero team scope'
    );
  end if;

  if not public.cmd_membership_is_team_manager(v_actor, p_team_id) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FORBIDDEN',
      'status', 403,
      'message', 'Only team owners and admins can look up invitees'
    );
  end if;

  select
    au.id,
    coalesce(nullif(btrim(au.email), ''), nullif(btrim(u.raw_user_meta_data ->> 'email'), '')),
    coalesce(u.raw_user_meta_data, '{}'::jsonb)
  into v_user_id, v_user_email, v_user_meta
  from auth.users as au
  left join public.users as u
    on u.id = au.id
  where lower(btrim(coalesce(au.email, u.raw_user_meta_data ->> 'email', ''))) = v_email
  order by au.created_at desc, au.id
  limit 1;

  if v_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'USER_NOT_FOUND',
      'status', 404,
      'message', 'No registered user was found for this email'
    );
  end if;

  select role
    into v_requested_team_role
  from public.roles
  where user_id = v_user_id
    and team_id = p_team_id;

  if v_requested_team_role = 'rejected' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REINVITE_REQUIRED',
      'status', 409,
      'message', 'Use the reinvite command for rejected members',
      'data', jsonb_build_object(
        'id', v_user_id,
        'user_id', v_user_id,
        'email', coalesce(v_user_email, v_email)
      )
    );
  end if;

  if v_requested_team_role is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'TEAM_MEMBER_ALREADY_EXISTS',
      'status', 409,
      'message', 'The team membership already exists',
      'data', jsonb_build_object(
        'id', v_user_id,
        'user_id', v_user_id,
        'email', coalesce(v_user_email, v_email)
      )
    );
  end if;

  select role
    into v_other_team_role
  from public.roles
  where user_id = v_user_id
    and team_id <> '00000000-0000-0000-0000-000000000000'::uuid
    and team_id <> p_team_id
    and role <> 'rejected'
  order by
    case when role = 'is_invited' then 0 else 1 end,
    modified_at desc nulls last,
    created_at desc nulls last
  limit 1;

  if v_other_team_role = 'is_invited' then
    return jsonb_build_object(
      'ok', false,
      'code', 'USER_ALREADY_INVITED_TO_TEAM',
      'status', 409,
      'message', 'This user already has a pending invitation to another team'
    );
  end if;

  if v_other_team_role is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'USER_ALREADY_IN_TEAM',
      'status', 409,
      'message', 'This user already belongs to another team'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'id', v_user_id,
      'user_id', v_user_id,
      'email', coalesce(v_user_email, v_email),
      'display_name', coalesce(
        nullif(btrim(v_user_meta ->> 'display_name'), ''),
        nullif(btrim(v_user_meta ->> 'name'), ''),
        nullif(btrim(v_user_email), ''),
        v_email
      )
    )
  );
end;
$$;


ALTER FUNCTION public.qry_team_find_invitable_user_by_email(p_team_id uuid, p_email text) OWNER TO postgres;

--
-- Name: qry_team_get_member_list(uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
