--
-- Name: svc_lcia_document_validation_evidence_lookup(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_document_validation_evidence_lookup(p_cache_keys jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not coalesce(util.is_service_request(), false) then return public.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  if jsonb_typeof(coalesce(p_cache_keys,'null'::jsonb)) <> 'array' then return public.lcia_scope_closure_error('invalid_document_evidence_keys',400,'Cache keys must be an array'); end if;
  return jsonb_build_object('ok',true,'data',coalesce((
    with requested as (
      select (value->>'datasetType') dataset_type, nullif(value->>'datasetId','')::uuid dataset_id,
        value->>'datasetVersion' dataset_version, value->>'canonicalContentHash' canonical_content_hash,
        value->>'documentValidatorVersion' document_validator_version,
        value->>'documentValidationProfile' document_validation_profile,
        value->>'validationReportSchemaVersion' validation_report_schema_version,
        value->>'validatorEngineFingerprint' validator_engine_fingerprint,
        value->>'tidasSchemaLockSha256' tidas_schema_lock_sha256
      from jsonb_array_elements(p_cache_keys)
    )
    select jsonb_agg(jsonb_build_object('datasetType',e.dataset_type,'datasetId',e.dataset_id,'datasetVersion',e.dataset_version,'canonicalContentHash',e.canonical_content_hash,'documentValidatorVersion',e.document_validator_version,'documentValidationProfile',e.document_validation_profile,'validationReportSchemaVersion',e.validation_report_schema_version,'validatorEngineFingerprint',e.validator_engine_fingerprint,'tidasSchemaLockSha256',e.tidas_schema_lock_sha256,'status',e.status,'summary',e.summary,'issueArtifactRef',e.issue_artifact_ref,'issueArtifactHash',e.issue_artifact_hash) order by e.dataset_type,e.dataset_id,e.dataset_version)
    from requested r join public.lcia_document_validation_evidence e on (e.dataset_type,e.dataset_id,e.dataset_version,e.canonical_content_hash,e.document_validator_version,e.document_validation_profile,e.validation_report_schema_version,e.validator_engine_fingerprint,e.tidas_schema_lock_sha256)=(r.dataset_type,r.dataset_id,r.dataset_version,r.canonical_content_hash,r.document_validator_version,r.document_validation_profile,r.validation_report_schema_version,r.validator_engine_fingerprint,r.tidas_schema_lock_sha256)
  ),'[]'::jsonb));
exception when invalid_text_representation then return public.lcia_scope_closure_error('invalid_document_evidence_keys',400,'Cache key contains invalid identity values');
end;
$$;


ALTER FUNCTION public.svc_lcia_document_validation_evidence_lookup(p_cache_keys jsonb) OWNER TO postgres;

--
-- Name: svc_lcia_document_validation_evidence_record(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_document_validation_evidence_record(p_records jsonb, p_source_worker_job_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_record jsonb; v_inserted integer:=0;
begin
  if not coalesce(util.is_service_request(), false) then return public.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  if jsonb_typeof(coalesce(p_records,'null'::jsonb)) <> 'array' then return public.lcia_scope_closure_error('invalid_document_evidence_records',400,'Evidence records must be an array'); end if;
  for v_record in select value from jsonb_array_elements(p_records) loop
    insert into public.lcia_document_validation_evidence(dataset_type,dataset_id,dataset_version,canonical_content_hash,document_validator_version,document_validation_profile,validation_report_schema_version,validator_engine_fingerprint,tidas_schema_lock_sha256,status,summary,issue_artifact_ref,issue_artifact_hash,source_worker_job_id)
    values(nullif(v_record->>'datasetType',''),nullif(v_record->>'datasetId','')::uuid,nullif(v_record->>'datasetVersion',''),nullif(v_record->>'canonicalContentHash',''),nullif(v_record->>'documentValidatorVersion',''),nullif(v_record->>'documentValidationProfile',''),nullif(v_record->>'validationReportSchemaVersion',''),nullif(v_record->>'validatorEngineFingerprint',''),nullif(v_record->>'tidasSchemaLockSha256',''),nullif(v_record->>'status',''),coalesce(v_record->'summary','{}'::jsonb),coalesce(v_record->'issueArtifactRef','{}'::jsonb),nullif(v_record->>'issueArtifactHash',''),p_source_worker_job_id)
    on conflict (dataset_type,dataset_id,dataset_version,canonical_content_hash,document_validator_version,document_validation_profile,validation_report_schema_version,validator_engine_fingerprint,tidas_schema_lock_sha256) do nothing;
    if found then v_inserted:=v_inserted+1; end if;
  end loop;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('insertedCount',v_inserted));
exception when not_null_violation or invalid_text_representation or check_violation then return public.lcia_scope_closure_error('invalid_document_evidence_records',400,'Evidence record violates the cache contract');
end;
$$;


ALTER FUNCTION public.svc_lcia_document_validation_evidence_record(p_records jsonb, p_source_worker_job_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_result_build_bind_closure(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_result_build_bind_closure(p_worker_job_id uuid, p_closure_check_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_job public.worker_jobs%rowtype; v_check public.lcia_scope_closure_checks%rowtype; v_binding jsonb;
begin
  if not coalesce(util.is_service_request(), false) then return public.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  select * into v_job from public.worker_jobs where id=p_worker_job_id for update;
  select * into v_check from public.lcia_scope_closure_checks where id=p_closure_check_id;
  if v_job.id is null or v_job.job_kind<>'lcia_result.package_build' or v_check.id is null then return public.lcia_scope_closure_error('build_binding_not_found',404,'Build job or closure certificate not found'); end if;
  if v_check.status<>'passed' or v_check.scan_completeness<>'complete' or v_check.certificate_status<>'valid' then return public.lcia_scope_closure_error('closure_check_not_usable',409,'Closure certificate is not usable'); end if;
  v_binding:=jsonb_strip_nulls(jsonb_build_object('closure_check_id',v_check.id,'closure_certificate_hash',v_check.certificate_hash,'effective_scope_hash',v_check.effective_scope_hash,'data_snapshot_token',v_check.data_snapshot_token,'snapshot_id',v_check.snapshot_id,'snapshot_hash',v_check.snapshot_hash,'closure_bundle_hash',v_check.closure_bundle_hash,'report_artifact_manifest_hash',v_check.report_artifact_manifest_hash));
  update public.worker_jobs set payload_json=payload_json||v_binding,payload_ref=coalesce(payload_ref,'{}'::jsonb)||jsonb_build_object('closureCertificate',v_binding),updated_at=now() where id=v_job.id returning * into v_job;
  insert into public.worker_job_events(job_id,event_type,status,details) values(v_job.id,'closure_certificate_bound',v_job.status,jsonb_build_object('closureCheckId',v_check.id,'certificateHash',v_check.certificate_hash));
  return jsonb_build_object('ok',true,'data',jsonb_build_object('workerJobId',v_job.id,'closureCheckId',v_check.id));
end;
$$;


ALTER FUNCTION public.svc_lcia_result_build_bind_closure(p_worker_job_id uuid, p_closure_check_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_claim(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_gc_claim(p_limit integer DEFAULT 100, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_claim_token uuid := gen_random_uuid();
  v_lease_expires_at timestamptz :=
    now() + make_interval(secs => p_lease_seconds);
  v_items jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_limit is null
     or p_limit not between 1 and 500
     or p_lease_seconds is null
     or p_lease_seconds not between 1 and 3600 then
    return public.lcia_scope_closure_error(
      'invalid_gc_claim', 400, 'Invalid GC claim bounds'
    );
  end if;
  with candidates as (
    select id
    from public.worker_job_artifacts
    where artifact_role is not null
      and (
        (
          lifecycle_state in ('ready', 'expired')
          and expires_at <= now()
        )
        or (
          lifecycle_state = 'deleted'
          and gc_cleanup_state = 'pending'
        )
      )
      and (
        gc_claim_token is null
        or gc_claim_expires_at is null
        or gc_claim_expires_at <= now()
      )
    order by
      case
        when lifecycle_state = 'deleted'
             and gc_cleanup_state = 'pending' then 0
        else 1
      end,
      expires_at,
      created_at,
      id
    for update skip locked
    limit p_limit
  ), claimed as (
    update public.worker_job_artifacts artifact
    set lifecycle_state = case
          when artifact.lifecycle_state = 'deleted' then 'deleted'
          else 'expired'
        end,
        gc_claim_token = v_claim_token,
        gc_claimed_at = now(),
        gc_claim_expires_at = v_lease_expires_at,
        gc_last_error = null
    from candidates
    where artifact.id = candidates.id
    returning artifact.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'artifactId', id,
    'artifactRole', artifact_role,
    'lifecycleState', lifecycle_state,
    'gcPhase', case
      when lifecycle_state = 'deleted' then 'detail_cleanup'
      else 'object_delete'
    end,
    'objectDeleteRequired', lifecycle_state <> 'deleted',
    'bucket', storage_bucket,
    'objectPath', storage_path,
    'checksumSha256', checksum_sha256,
    'artifactExpiresAt', expires_at
  ) order by
    case when lifecycle_state = 'deleted' then 0 else 1 end,
    expires_at,
    created_at,
    id
  ), '[]'::jsonb)
  into v_items
  from claimed;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'claimToken', v_claim_token,
    'leaseExpiresAt', v_lease_expires_at,
    'items', v_items
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_gc_claim(p_limit integer, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_complete(uuid, uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_gc_complete(p_artifact_id uuid, p_claim_token uuid, p_object_missing boolean DEFAULT false, p_detail_limit integer DEFAULT 10000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_artifact public.worker_job_artifacts%rowtype;
  v_check public.lcia_scope_closure_checks%rowtype;
  v_deleted_occurrences integer := 0;
  v_deleted_roots integer := 0;
  v_deleted_issues integer := 0;
  v_remaining bigint := 0;
  v_gc_phase text;
  v_object_delete_required boolean;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_detail_limit is null
     or p_detail_limit not between 1 and 50000 then
    return public.lcia_scope_closure_error(
      'invalid_gc_completion', 400, 'Invalid detail cleanup bound'
    );
  end if;

  select * into v_artifact
  from public.worker_job_artifacts
  where id = p_artifact_id
  for update;
  if v_artifact.id is null then
    return public.lcia_scope_closure_error(
      'artifact_not_found', 404, 'Artifact not found'
    );
  end if;

  if v_artifact.lifecycle_state = 'deleted'
     and v_artifact.gc_cleanup_state = 'complete'
     and v_artifact.gc_claim_token = p_claim_token then
    return jsonb_build_object('ok', true, 'reused', true, 'data',
      jsonb_build_object(
        'artifactId', v_artifact.id,
        'state', 'deleted',
        'lifecycleState', 'deleted',
        'gcPhase', 'detail_cleanup',
        'objectDeleteRequired', false,
        'objectMissing', p_object_missing,
        'detailsRemaining', 0,
        'cleanupPending', false,
        'cleanupComplete', true
      )
    );
  end if;

  if v_artifact.gc_claim_token is distinct from p_claim_token
     or v_artifact.gc_claim_expires_at is null
     or v_artifact.gc_claim_expires_at < now()
     or not (
       v_artifact.lifecycle_state = 'expired'
       or (
         v_artifact.lifecycle_state = 'deleted'
         and v_artifact.gc_cleanup_state = 'pending'
       )
     ) then
    return public.lcia_scope_closure_error(
      'gc_claim_invalid', 409, 'GC claim is not current'
    );
  end if;

  v_object_delete_required := v_artifact.lifecycle_state = 'expired';
  v_gc_phase := case
    when v_object_delete_required then 'object_delete'
    else 'detail_cleanup'
  end;

  select * into v_check
  from public.lcia_scope_closure_checks
  where report_artifact_id = v_artifact.id
     or complete_machine_result_artifact_id = v_artifact.id
     or closure_bundle_artifact_id = v_artifact.id
  order by finished_at nulls last, id
  limit 1
  for update;

  if v_check.id is not null then
    insert into public.lcia_scope_closure_retention_summaries (
      closure_check_id,
      issue_count,
      occurrence_count,
      affected_root_count,
      issue_content_hash,
      compact_result_summary
    )
    select
      v_check.id,
      (
        select count(*)
        from public.lcia_scope_closure_issues issue
        where issue.closure_check_id = v_check.id
      ),
      (
        select count(*)
        from public.lcia_scope_closure_issue_occurrences occurrence
        join public.lcia_scope_closure_issues issue
          on issue.id = occurrence.closure_issue_id
        where issue.closure_check_id = v_check.id
      ),
      (
        select count(*)
        from public.lcia_scope_closure_issue_roots root
        join public.lcia_scope_closure_issues issue
          on issue.id = root.closure_issue_id
        where issue.closure_check_id = v_check.id
      ),
      public.lcia_scope_closure_sha256(coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'issueKey', issue.issue_key,
            'issueCode', issue.issue_code,
            'severity', issue.severity,
            'blocking', issue.blocking,
            'occurrenceCount', issue.occurrence_count,
            'affectedRootCount', issue.affected_root_count
          )
          order by issue.issue_key, issue.id
        )
        from public.lcia_scope_closure_issues issue
        where issue.closure_check_id = v_check.id
      ), '[]'::jsonb)),
      v_check.result_summary
    on conflict (closure_check_id) do nothing;

    with doomed as (
      select occurrence.ctid
      from public.lcia_scope_closure_issue_occurrences occurrence
      join public.lcia_scope_closure_issues issue
        on issue.id = occurrence.closure_issue_id
      where issue.closure_check_id = v_check.id
      limit p_detail_limit
    )
    delete from public.lcia_scope_closure_issue_occurrences occurrence
    using doomed
    where occurrence.ctid = doomed.ctid;
    get diagnostics v_deleted_occurrences = row_count;

    with doomed as (
      select root.ctid
      from public.lcia_scope_closure_issue_roots root
      join public.lcia_scope_closure_issues issue
        on issue.id = root.closure_issue_id
      where issue.closure_check_id = v_check.id
      limit p_detail_limit
    )
    delete from public.lcia_scope_closure_issue_roots root
    using doomed
    where root.ctid = doomed.ctid;
    get diagnostics v_deleted_roots = row_count;

    if not exists (
      select 1
      from public.lcia_scope_closure_issue_occurrences occurrence
      join public.lcia_scope_closure_issues issue
        on issue.id = occurrence.closure_issue_id
      where issue.closure_check_id = v_check.id
    ) and not exists (
      select 1
      from public.lcia_scope_closure_issue_roots root
      join public.lcia_scope_closure_issues issue
        on issue.id = root.closure_issue_id
      where issue.closure_check_id = v_check.id
    ) then
      with doomed as (
        select ctid
        from public.lcia_scope_closure_issues
        where closure_check_id = v_check.id
        limit p_detail_limit
      )
      delete from public.lcia_scope_closure_issues issue
      using doomed
      where issue.ctid = doomed.ctid;
      get diagnostics v_deleted_issues = row_count;
    end if;

    select
      (select count(*)
       from public.lcia_scope_closure_issues
       where closure_check_id = v_check.id)
      + (
        select count(*)
        from public.lcia_scope_closure_issue_occurrences occurrence
        join public.lcia_scope_closure_issues issue
          on issue.id = occurrence.closure_issue_id
        where issue.closure_check_id = v_check.id
      )
      + (
        select count(*)
        from public.lcia_scope_closure_issue_roots root
        join public.lcia_scope_closure_issues issue
          on issue.id = root.closure_issue_id
        where issue.closure_check_id = v_check.id
      )
    into v_remaining;
  end if;

  update public.worker_job_artifacts
  set lifecycle_state = 'deleted',
      deleted_at = coalesce(deleted_at, now()),
      gc_cleanup_state = case
        when v_remaining > 0 then 'pending'
        else 'complete'
      end,
      gc_claim_expires_at = case
        when v_remaining > 0 then gc_claim_expires_at
        else null
      end,
      gc_last_error = null
  where id = v_artifact.id
  returning * into v_artifact;

  return jsonb_build_object('ok', true, 'reused', false, 'data',
    jsonb_build_object(
      'artifactId', v_artifact.id,
      'state', v_artifact.lifecycle_state,
      'lifecycleState', v_artifact.lifecycle_state,
      'gcPhase', v_gc_phase,
      'objectDeleteRequired', v_object_delete_required,
      'objectMissing', p_object_missing,
      'deletedOccurrences', v_deleted_occurrences,
      'deletedAffectedRoots', v_deleted_roots,
      'deletedIssues', v_deleted_issues,
      'detailsRemaining', v_remaining,
      'cleanupPending', v_remaining > 0,
      'cleanupComplete', v_remaining = 0
    )
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_gc_complete(p_artifact_id uuid, p_claim_token uuid, p_object_missing boolean, p_detail_limit integer) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_fail(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_gc_fail(p_artifact_id uuid, p_claim_token uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_artifact public.worker_job_artifacts%rowtype;
  v_gc_phase text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if nullif(trim(coalesce(p_error, '')), '') is null then
    return public.lcia_scope_closure_error(
      'invalid_gc_failure', 400, 'GC failure reason is required'
    );
  end if;

  select * into v_artifact
  from public.worker_job_artifacts
  where id = p_artifact_id
  for update;
  if v_artifact.id is null then
    return public.lcia_scope_closure_error(
      'artifact_not_found', 404, 'Artifact not found'
    );
  end if;
  if v_artifact.lifecycle_state = 'deleted'
     and v_artifact.gc_cleanup_state = 'complete'
     and v_artifact.gc_claim_token = p_claim_token then
    return jsonb_build_object('ok', true, 'reused', true);
  end if;
  if v_artifact.gc_claim_token is distinct from p_claim_token
     or v_artifact.gc_claim_expires_at is null
     or v_artifact.gc_claim_expires_at < now()
     or not (
       v_artifact.lifecycle_state = 'expired'
       or (
         v_artifact.lifecycle_state = 'deleted'
         and v_artifact.gc_cleanup_state = 'pending'
       )
     ) then
    return public.lcia_scope_closure_error(
      'gc_claim_invalid', 409, 'GC claim is not current'
    );
  end if;

  v_gc_phase := case
    when v_artifact.lifecycle_state = 'deleted' then 'detail_cleanup'
    else 'object_delete'
  end;

  update public.worker_job_artifacts
  set gc_claim_token = null,
      gc_claimed_at = null,
      gc_claim_expires_at = null,
      gc_failure_count = gc_failure_count + 1,
      gc_last_error = left(trim(p_error), 1000)
  where id = v_artifact.id
  returning * into v_artifact;

  return jsonb_build_object('ok', true, 'reused', false, 'data',
    jsonb_build_object(
      'artifactId', v_artifact.id,
      'state', v_artifact.lifecycle_state,
      'lifecycleState', v_artifact.lifecycle_state,
      'gcPhase', v_gc_phase,
      'objectDeleteRequired', v_gc_phase = 'object_delete',
      'failureCount', v_artifact.gc_failure_count
    )
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_gc_fail(p_artifact_id uuid, p_claim_token uuid, p_error text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_preview(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_gc_preview(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_items jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_limit is null or p_limit not between 1 and 500 then
    return public.lcia_scope_closure_error(
      'invalid_gc_preview', 400, 'Invalid GC preview bound'
    );
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'artifactId', artifact.id,
    'artifactRole', artifact.artifact_role,
    'lifecycleState', artifact.lifecycle_state,
    'gcPhase', case
      when artifact.lifecycle_state = 'deleted' then 'detail_cleanup'
      else 'object_delete'
    end,
    'objectDeleteRequired', artifact.lifecycle_state <> 'deleted',
    'bucket', artifact.storage_bucket,
    'objectPath', artifact.storage_path,
    'checksumSha256', artifact.checksum_sha256,
    'artifactExpiresAt', artifact.expires_at
  ) order by
    case when artifact.lifecycle_state = 'deleted' then 0 else 1 end,
    artifact.expires_at,
    artifact.created_at,
    artifact.id
  ), '[]'::jsonb)
  into v_items
  from (
    select *
    from public.worker_job_artifacts
    where artifact_role is not null
      and (
        (
          lifecycle_state in ('ready', 'expired')
          and expires_at <= now()
        )
        or (
          lifecycle_state = 'deleted'
          and gc_cleanup_state = 'pending'
        )
      )
      and (
        gc_claim_token is null
        or gc_claim_expires_at is null
        or gc_claim_expires_at <= now()
      )
    order by
      case
        when lifecycle_state = 'deleted'
             and gc_cleanup_state = 'pending' then 0
        else 1
      end,
      expires_at,
      created_at,
      id
    limit p_limit
  ) artifact;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'items', v_items
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_gc_preview(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_gc_preview(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_gc_preview(p_limit integer) IS 'Service-only, strictly non-mutating ordered preview of immediately claimable scope-closure GC candidates.';


--
-- Name: svc_lcia_scope_closure_artifact_gc_renew(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_gc_renew(p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_lease_expires_at timestamptz :=
    now() + make_interval(secs => p_lease_seconds);
  v_artifact_ids jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_claim_token is null
     or p_lease_seconds is null
     or p_lease_seconds not between 1 and 3600 then
    return public.lcia_scope_closure_error(
      'invalid_gc_renewal', 400, 'Invalid GC renewal request'
    );
  end if;
  with renewed as (
    update public.worker_job_artifacts artifact
    set gc_claim_expires_at = v_lease_expires_at
    where artifact.gc_claim_token = p_claim_token
      and artifact.gc_claim_expires_at >= now()
      and (
        artifact.lifecycle_state = 'expired'
        or (
          artifact.lifecycle_state = 'deleted'
          and artifact.gc_cleanup_state = 'pending'
        )
      )
    returning artifact.id
  )
  select jsonb_agg(id order by id)
  into v_artifact_ids
  from renewed;
  if v_artifact_ids is null then
    return public.lcia_scope_closure_error(
      'gc_claim_invalid', 409, 'GC claim is not current'
    );
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'claimToken', p_claim_token,
    'leaseExpiresAt', v_lease_expires_at,
    'artifactIds', v_artifact_ids
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_gc_renew(p_claim_token uuid, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_gc_renew(p_claim_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_gc_renew(p_claim_token uuid, p_lease_seconds integer) IS 'Service-only fenced heartbeat that extends only a current unexpired GC claim token.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_create(uuid, text, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_create(p_closure_check_id uuid, p_idempotency_key text, p_items jsonb, p_staging_seconds integer DEFAULT 900, p_reused_from_check_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_check public.lcia_scope_closure_checks%rowtype;
  v_source_check public.lcia_scope_closure_checks%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_request_sha256 text;
  v_item_count integer;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null
     or length(trim(p_idempotency_key)) > 200
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) not between 1 and 500
     or p_staging_seconds is null
     or p_staging_seconds not between 1 and 86400 then
    return public.lcia_scope_closure_error(
      'artifact_write_set_invalid', 400, 'Invalid artifact write-set request'
    );
  end if;

  select * into v_check
  from public.lcia_scope_closure_checks
  where id = p_closure_check_id
  for update;
  if v_check.id is null then
    return public.lcia_scope_closure_error(
      'closure_check_not_found', 404, 'Closure check not found'
    );
  end if;
  if v_check.status in ('failed', 'cancelled') then
    return public.lcia_scope_closure_error(
      'artifact_write_set_unavailable', 409, 'Closure check cannot publish artifacts'
    );
  end if;

  v_request_sha256 := public.lcia_scope_closure_sha256(
    jsonb_build_object(
      'items', p_items,
      'publicationMode',
        case when p_reused_from_check_id is null then 'fresh' else 'reused' end,
      'reusedFromCheckId', p_reused_from_check_id
    )
  );
  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where closure_check_id = p_closure_check_id
    and idempotency_key = trim(p_idempotency_key);
  if v_write_set.id is not null then
    if v_write_set.request_sha256 <> v_request_sha256 then
      return public.lcia_scope_closure_error(
        'artifact_write_set_idempotency_conflict',
        409,
        'Artifact write-set idempotency key conflicts'
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', public.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    where jsonb_typeof(item) <> 'object'
       or nullif(trim(item->>'clientKey'), '') is null
       or nullif(trim(item->>'artifactType'), '') is null
       or nullif(trim(item->>'artifactRole'), '') is null
       or nullif(trim(item->>'bucket'), '') is null
       or nullif(trim(item->>'objectPath'), '') is null
       or nullif(trim(item->>'mediaType'), '') is null
       or coalesce(item->>'checksumSha256', '') !~ '^[a-f0-9]{64}$'
       or coalesce(item->>'size', '') !~ '^[0-9]+$'
       or coalesce(item->'metadata', '{}'::jsonb) is null
       or jsonb_typeof(coalesce(item->'metadata', '{}'::jsonb)) <> 'object'
       or public.lcia_scope_closure_artifact_role(
            item->>'artifactType'
          ) is distinct from item->>'artifactRole'
  ) then
    return public.lcia_scope_closure_error(
      'artifact_write_set_invalid', 400, 'Artifact write-set item is invalid'
    );
  end if;

  select count(*) into v_item_count
  from (
    select item->>'clientKey'
    from jsonb_array_elements(p_items) item
    group by item->>'clientKey'
  ) distinct_client_keys;
  if v_item_count <> jsonb_array_length(p_items)
     or (
       select count(*)
       from (
         select item->>'bucket', item->>'objectPath'
         from jsonb_array_elements(p_items) item
         group by item->>'bucket', item->>'objectPath'
       ) distinct_locators
     ) <> jsonb_array_length(p_items)
  then
    return public.lcia_scope_closure_error(
      'artifact_write_set_invalid', 400, 'Artifact write-set keys or locators are invalid'
    );
  end if;

  if p_reused_from_check_id is null then
    if (
      select count(*)
      from jsonb_array_elements(p_items) item
      where item->>'artifactRole' = 'closure_report'
    ) <> 1
       or (
         select count(*)
         from jsonb_array_elements(p_items) item
         where item->>'artifactRole' = 'closure_bundle'
       ) <> 1
       or (
         select count(*)
         from jsonb_array_elements(p_items) item
         where item->>'artifactRole' = 'complete_machine_result'
           and item->>'mediaType' =
             'application/vnd.tiangong.scope-closure-manifest+json'
       ) <> 1
       or not exists (
         select 1
         from jsonb_array_elements(p_items) bundle
         join jsonb_array_elements(p_items) manifest
           on manifest->>'clientKey' =
             bundle #>> '{metadata,completeMachineResultClientKey}'
         where bundle->>'artifactRole' = 'closure_bundle'
           and manifest->>'artifactRole' = 'complete_machine_result'
           and manifest->>'mediaType' =
             'application/vnd.tiangong.scope-closure-manifest+json'
       ) then
      return public.lcia_scope_closure_error(
        'artifact_write_set_invalid',
        400,
        'Fresh publication requires report, manifest, and bundle roles'
      );
    end if;
  else
    if jsonb_array_length(p_items) <> 1
       or p_items #>> '{0,artifactRole}' <> 'closure_report'
       or p_items #>> '{0,artifactType}' <> 'closure_report_xlsx' then
      return public.lcia_scope_closure_error(
        'artifact_write_set_invalid',
        400,
        'Reused publication accepts exactly one XLSX report'
      );
    end if;
    select * into v_source_check
    from public.lcia_scope_closure_checks
    where id = p_reused_from_check_id;
    if v_source_check.id is null
       or v_source_check.status not in ('passed', 'blocked')
       or v_source_check.scan_completeness <> 'complete'
       or v_source_check.requested_scope_hash <> v_check.requested_scope_hash
       or v_source_check.policy_fingerprint <> v_check.policy_fingerprint
       or v_source_check.data_snapshot_token <> v_check.data_snapshot_token
       or v_source_check.complete_machine_result_artifact_id is null
       or v_source_check.closure_bundle_artifact_id is null then
      return public.lcia_scope_closure_error(
        'artifact_write_set_reuse_invalid',
        409,
        'Reusable source evidence does not match the closure check'
      );
    end if;
    update public.lcia_scope_closure_checks
    set reused_from_check_id = v_source_check.id,
        complete_machine_result_artifact_id =
          v_source_check.complete_machine_result_artifact_id,
        closure_bundle_artifact_id = v_source_check.closure_bundle_artifact_id,
        updated_at = now()
    where id = v_check.id;
  end if;

  insert into public.lcia_scope_closure_artifact_write_sets (
    closure_check_id,
    worker_job_id,
    requested_by,
    publication_mode,
    reused_from_check_id,
    idempotency_key,
    request_sha256,
    staging_expires_at
  ) values (
    v_check.id,
    v_check.worker_job_id,
    v_check.requested_by,
    case when p_reused_from_check_id is null then 'fresh' else 'reused' end,
    p_reused_from_check_id,
    trim(p_idempotency_key),
    v_request_sha256,
    now() + make_interval(secs => p_staging_seconds)
  ) returning * into v_write_set;

  insert into public.lcia_scope_closure_artifact_write_set_items (
    write_set_id,
    ordinal,
    client_key,
    artifact_type,
    artifact_role,
    storage_bucket,
    storage_path,
    content_type,
    byte_size,
    checksum_sha256,
    metadata
  )
  select
    v_write_set.id,
    item.ordinality::integer,
    trim(item.value->>'clientKey'),
    item.value->>'artifactType',
    item.value->>'artifactRole',
    trim(item.value->>'bucket'),
    trim(item.value->>'objectPath'),
    item.value->>'mediaType',
    (item.value->>'size')::bigint,
    item.value->>'checksumSha256',
    coalesce(item.value->'metadata', '{}'::jsonb)
  from jsonb_array_elements(p_items) with ordinality item(value, ordinality);

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', public.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
  );
end;
$_$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_create(p_closure_check_id uuid, p_idempotency_key text, p_items jsonb, p_staging_seconds integer, p_reused_from_check_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_create(p_closure_check_id uuid, p_idempotency_key text, p_items jsonb, p_staging_seconds integer, p_reused_from_check_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_create(p_closure_check_id uuid, p_idempotency_key text, p_items jsonb, p_staging_seconds integer, p_reused_from_check_id uuid) IS 'Service-only DB-first publication create. NULL reused source requires the full fresh shape; a source check UUID requires exactly one XLSX report, freezes source manifest/bundle lineage, and returns artifactMap as the authoritative clientKey-to-artifactId mapping.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_create_v2(uuid, uuid, uuid, uuid, text, integer, text, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_create_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid, p_contract_version text, p_expected_descriptor_count integer, p_descriptor_set_sha256 text, p_required_primary_roles jsonb, p_staging_seconds integer DEFAULT 900, p_reused_from_check_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_check public.lcia_scope_closure_checks%rowtype;
  v_source_check public.lcia_scope_closure_checks%rowtype;
  v_job public.worker_jobs%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_publication_mode text := case
    when p_reused_from_check_id is null then 'fresh'
    else 'reused'
  end;
  v_required_roles jsonb;
  v_lease_sha256 text;
  v_request_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;

  v_required_roles :=
    private.lcia_scope_closure_artifact_v2_required_roles(v_publication_mode);
  if p_closure_check_id is null
     or p_worker_job_id is null
     or p_worker_lease_token is null
     or p_request_id is null
     or p_contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2'
     or p_expected_descriptor_count is null
     or p_expected_descriptor_count not between 1 and 100000
     or (
       v_publication_mode = 'fresh'
       and p_expected_descriptor_count < 3
     )
     or (
       v_publication_mode = 'reused'
       and p_expected_descriptor_count <> 1
     )
     or coalesce(p_descriptor_set_sha256, '') !~ '^[a-f0-9]{64}$'
     or p_required_primary_roles is distinct from v_required_roles
     or p_staging_seconds is null
     or p_staging_seconds not between 1 and 86400 then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set header'
    );
  end if;

  select * into v_job
  from public.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  select * into v_check
  from public.lcia_scope_closure_checks
  where id = p_closure_check_id
  for update;
  if v_check.id is null then
    return public.lcia_scope_closure_error(
      'closure_check_not_found', 404, 'Closure check not found'
    );
  end if;
  if v_check.worker_job_id is distinct from v_job.id then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is not bound to the closure check'
    );
  end if;
  if v_check.status in ('failed', 'cancelled') then
    return public.lcia_scope_closure_error(
      'artifact_write_set_unavailable',
      409,
      'Closure check cannot publish artifacts'
    );
  end if;

  if v_publication_mode = 'reused' then
    select * into v_source_check
    from public.lcia_scope_closure_checks
    where id = p_reused_from_check_id;
    if v_source_check.id is null
       or v_source_check.status not in ('passed', 'blocked')
       or v_source_check.scan_completeness <> 'complete'
       or v_source_check.requested_scope_hash <> v_check.requested_scope_hash
       or v_source_check.policy_fingerprint <> v_check.policy_fingerprint
       or v_source_check.data_snapshot_token <> v_check.data_snapshot_token
       or v_source_check.complete_machine_result_artifact_id is null
       or v_source_check.closure_bundle_artifact_id is null then
      return public.lcia_scope_closure_error(
        'artifact_write_set_reuse_invalid',
        409,
        'Reusable source evidence does not match the closure check'
      );
    end if;
  end if;

  v_lease_sha256 :=
    private.lcia_scope_closure_artifact_v2_lease_sha256(
      p_worker_lease_token
    );
  v_request_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(jsonb_build_object(
      'closureCheckId', p_closure_check_id,
      'workerJobId', p_worker_job_id,
      'workerLeaseTokenSha256', v_lease_sha256,
      'requestId', p_request_id,
      'contractVersion', p_contract_version,
      'expectedDescriptorCount', p_expected_descriptor_count,
      'descriptorSetSha256', p_descriptor_set_sha256,
      'requiredPrimaryRoles', p_required_primary_roles,
      'stagingSeconds', p_staging_seconds,
      'publicationMode', v_publication_mode,
      'reusedFromCheckId', p_reused_from_check_id
    ));

  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where closure_check_id = p_closure_check_id
    and request_id = p_request_id;
  if v_write_set.id is not null then
    if v_write_set.request_sha256 is distinct from v_request_sha256
       or v_write_set.worker_job_id is distinct from p_worker_job_id
       or v_write_set.worker_lease_token_sha256 is distinct from
         v_lease_sha256 then
      return public.lcia_scope_closure_error(
        'artifact_write_set_v2_request_conflict',
        409,
        'Staged artifact write-set request identity conflicts'
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;

  if exists (
    select 1
    from public.lcia_scope_closure_artifact_write_sets active
    where active.closure_check_id = p_closure_check_id
      and active.status in ('registration_open', 'staging', 'ready')
  ) then
    return public.lcia_scope_closure_error(
      'artifact_write_set_unavailable',
      409,
      'Closure check already has an active artifact write-set'
    );
  end if;

  if v_publication_mode = 'reused' then
    update public.lcia_scope_closure_checks
    set reused_from_check_id = v_source_check.id,
        complete_machine_result_artifact_id =
          v_source_check.complete_machine_result_artifact_id,
        closure_bundle_artifact_id =
          v_source_check.closure_bundle_artifact_id,
        updated_at = now()
    where id = v_check.id;
  end if;

  insert into public.lcia_scope_closure_artifact_write_sets (
    closure_check_id,
    worker_job_id,
    requested_by,
    publication_mode,
    reused_from_check_id,
    idempotency_key,
    request_sha256,
    status,
    staging_expires_at,
    contract_version,
    request_id,
    expected_descriptor_count,
    descriptor_set_sha256,
    required_primary_roles,
    worker_lease_token_sha256
  ) values (
    v_check.id,
    v_job.id,
    v_check.requested_by,
    v_publication_mode,
    p_reused_from_check_id,
    'v2:' || p_request_id::text,
    v_request_sha256,
    'registration_open',
    least(
      now() + make_interval(secs => p_staging_seconds),
      v_job.lease_expires_at
    ),
    p_contract_version,
    p_request_id,
    p_expected_descriptor_count,
    p_descriptor_set_sha256,
    p_required_primary_roles,
    v_lease_sha256
  ) returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$_$;


