-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_create_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid, p_contract_version text, p_expected_descriptor_count integer, p_descriptor_set_sha256 text, p_required_primary_roles jsonb, p_staging_seconds integer, p_reused_from_check_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_create_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid, p_contract_version text, p_expected_descriptor_count integer, p_descriptor_set_sha256 text, p_required_primary_roles jsonb, p_staging_seconds integer, p_reused_from_check_id uuid) IS 'Service-only v2 header create. Binds closure check, Worker job/current lease generation, request UUID, exact count, canonical descriptor digest, required primary roles, and write-set fence while remaining upload-ineligible.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_fail(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_fail(p_write_set_id uuid, p_write_token uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if nullif(trim(coalesce(p_error, '')), '') is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_failure_invalid', 400, 'Failure reason is required'
    );
  end if;
  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.contract_version is not null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_fence_required',
      409,
      'Use the worker-lease-fenced v2 failure RPC'
    );
  end if;
  if v_write_set.status <> 'staging' then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  update public.lcia_scope_closure_artifact_write_sets
  set status = 'cleanup_pending',
      failure_reason = left(trim(p_error), 1000),
      updated_at = now()
  where id = v_write_set.id;
  return jsonb_build_object(
    'ok', true,
    'data', public.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_fail(p_write_set_id uuid, p_write_token uuid, p_error text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_write_set_fail_v2(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_fail_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if nullif(trim(coalesce(p_error, '')), '') is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_failure_invalid', 400, 'Failure reason is required'
    );
  end if;

  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from public.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  if v_write_set.status = 'cleanup_pending' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;
  if v_write_set.status not in ('registration_open', 'staging') then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_finalizable',
      409,
      'Artifact write-set cannot be failed from its current state'
    );
  end if;

  update public.lcia_scope_closure_artifact_write_sets
  set status = 'cleanup_pending',
      failure_reason = left(trim(p_error), 1000),
      updated_at = now()
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_fail_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_error text) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_fail_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_error text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_fail_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_error text) IS 'Service-only current-lease failure transition from registration_open or sealed staging into the existing fenced reconciliation/GC lifecycle.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_finalize(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_report_id uuid;
  v_manifest_id uuid;
  v_bundle_id uuid;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.contract_version is not null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_fence_required',
      409,
      'Use the worker-lease-fenced v2 finalize RPC'
    );
  end if;
  if v_write_set.status = 'ready' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', public.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
    );
  end if;
  if v_write_set.status <> 'staging'
     or v_write_set.staging_expires_at <= now() then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_finalizable',
      409,
      'Artifact write-set is not finalizable'
    );
  end if;

  select id into v_report_id
  from public.lcia_scope_closure_artifact_write_set_items
  where write_set_id = v_write_set.id
    and artifact_role = 'closure_report';
  if v_write_set.publication_mode = 'fresh' then
    select id into v_manifest_id
    from public.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'complete_machine_result'
      and content_type =
        'application/vnd.tiangong.scope-closure-manifest+json';
    select id into v_bundle_id
    from public.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'closure_bundle';
  end if;

  insert into public.worker_job_artifacts (
    id,
    job_id,
    artifact_type,
    artifact_role,
    lifecycle_state,
    storage_bucket,
    storage_path,
    content_type,
    byte_size,
    checksum_sha256,
    metadata,
    visibility,
    created_at,
    expires_at
  )
  select
    item.id,
    v_write_set.worker_job_id,
    item.artifact_type,
    item.artifact_role,
    'ready',
    item.storage_bucket,
    item.storage_path,
    item.content_type,
    item.byte_size,
    item.checksum_sha256,
    case
      when item.artifact_role = 'closure_bundle' then
        (item.metadata - 'completeMachineResultClientKey')
        || jsonb_build_object(
          'completeMachineResultArtifactId', v_manifest_id
        )
      else item.metadata
    end || jsonb_build_object(
      'writeSetId', v_write_set.id,
      'closureCheckId', v_write_set.closure_check_id,
      'clientKey', item.client_key
    ),
    'operator',
    now(),
    now() + interval '7 days'
  from public.lcia_scope_closure_artifact_write_set_items item
  where item.write_set_id = v_write_set.id
  order by item.ordinal;

  if v_write_set.publication_mode = 'fresh' then
    update public.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        complete_machine_result_artifact_id = v_manifest_id,
        closure_bundle_artifact_id = v_bundle_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id is null;
  else
    update public.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id = v_write_set.reused_from_check_id
      and complete_machine_result_artifact_id is not null
      and closure_bundle_artifact_id is not null;
  end if;
  if not found then
    raise exception 'artifact_write_set_closure_binding_changed'
      using errcode = '23514';
  end if;

  update public.lcia_scope_closure_artifact_write_sets
  set status = 'ready',
      finalized_at = now(),
      updated_at = now(),
      failure_reason = null
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', public.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid) IS 'Service-only fenced atomic finalize. Fresh mode resolves completeMachineResultClientKey to completeMachineResultArtifactId and publishes all items; reused mode publishes only the new report and preserves source evidence bindings.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_finalize_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_report_id uuid;
  v_manifest_id uuid;
  v_bundle_id uuid;
  v_actual_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_write_set_id is null
     or p_write_token is null
     or p_worker_job_id is null
     or p_worker_lease_token is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set finalize request'
    );
  end if;

  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from public.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  if v_write_set.status = 'ready' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;
  if v_write_set.status <> 'staging'
     or v_write_set.sealed_at is null
     or v_write_set.staging_expires_at <= now() then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_finalizable',
      409,
      'Artifact write-set is not finalizable'
    );
  end if;

  v_actual_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(
      private.lcia_scope_closure_artifact_v2_descriptor_set(v_write_set.id)
    );
  if v_actual_sha256 is distinct from v_write_set.descriptor_set_sha256 then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_digest_mismatch',
      409,
      'Sealed artifact descriptor-set digest changed'
    );
  end if;

  select id into v_report_id
  from public.lcia_scope_closure_artifact_write_set_items
  where write_set_id = v_write_set.id
    and artifact_role = 'closure_report';
  if v_write_set.publication_mode = 'fresh' then
    select id into v_manifest_id
    from public.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'complete_machine_result'
      and content_type =
        'application/vnd.tiangong.scope-closure-manifest+json';
    select id into v_bundle_id
    from public.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'closure_bundle';
  end if;

  insert into public.worker_job_artifacts (
    id,
    job_id,
    artifact_type,
    artifact_role,
    lifecycle_state,
    storage_bucket,
    storage_path,
    content_type,
    byte_size,
    checksum_sha256,
    metadata,
    visibility,
    created_at,
    expires_at
  )
  select
    item.id,
    v_write_set.worker_job_id,
    item.artifact_type,
    item.artifact_role,
    'ready',
    item.storage_bucket,
    item.storage_path,
    item.content_type,
    item.byte_size,
    item.checksum_sha256,
    case
      when item.artifact_role = 'closure_bundle' then
        (item.metadata - 'completeMachineResultClientKey')
        || jsonb_build_object(
          'completeMachineResultArtifactId', v_manifest_id
        )
      else item.metadata
    end || jsonb_build_object(
      'writeSetId', v_write_set.id,
      'closureCheckId', v_write_set.closure_check_id,
      'clientKey', item.client_key
    ),
    'operator',
    now(),
    now() + interval '7 days'
  from public.lcia_scope_closure_artifact_write_set_items item
  where item.write_set_id = v_write_set.id
  order by item.ordinal;

  if v_write_set.publication_mode = 'fresh' then
    update public.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        complete_machine_result_artifact_id = v_manifest_id,
        closure_bundle_artifact_id = v_bundle_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id is null;
  else
    update public.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id = v_write_set.reused_from_check_id
      and complete_machine_result_artifact_id is not null
      and closure_bundle_artifact_id is not null;
  end if;
  if not found then
    raise exception 'artifact_write_set_closure_binding_changed'
      using errcode = '23514';
  end if;

  update public.lcia_scope_closure_artifact_write_sets
  set status = 'ready',
      finalized_at = now(),
      updated_at = now(),
      failure_reason = null
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) IS 'Service-only current-lease atomic finalize after object upload. Inserts every registered artifact as ready and updates the closure projection in the same transaction.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_inspect(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_inspect(p_write_set_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_data jsonb;
  v_contract_version text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select contract_version into v_contract_version
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id;
  if not found then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_contract_version is not null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_status_required',
      409,
      'Use the lease-fenced v2 status RPC'
    );
  end if;
  v_data := public.lcia_scope_closure_artifact_write_set_json(p_write_set_id);
  return jsonb_build_object('ok', true, 'data', v_data);
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_inspect(p_write_set_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_write_set_reconcile(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer DEFAULT 100, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_token uuid := gen_random_uuid();
  v_lease_expires_at timestamptz :=
    now() + make_interval(secs => p_lease_seconds);
  v_claimed_ids uuid[] := array[]::uuid[];
  v_items jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_limit is null
     or p_limit not between 1 and 500
     or p_lease_seconds is null
     or p_lease_seconds not between 1 and 3600 then
    return public.lcia_scope_closure_error(
      'artifact_write_set_reconcile_invalid', 400, 'Invalid reconcile bounds'
    );
  end if;
  with candidates as (
    select id
    from public.lcia_scope_closure_artifact_write_sets
    where (
      status = 'cleanup_pending'
      or (
        status in ('registration_open', 'staging')
        and staging_expires_at <= now()
      )
    )
      and (
        reconcile_token is null
        or reconcile_expires_at is null
        or reconcile_expires_at <= now()
      )
    order by staging_expires_at, created_at, id
    for update skip locked
    limit p_limit
  ), claimed as (
    update public.lcia_scope_closure_artifact_write_sets write_set
    set status = 'cleanup_pending',
        reconcile_token = v_token,
        reconcile_claimed_at = now(),
        reconcile_expires_at = v_lease_expires_at,
        updated_at = now()
    from candidates
    where write_set.id = candidates.id
    returning write_set.id
  )
  select coalesce(array_agg(claimed.id order by claimed.id), array[]::uuid[])
  into v_claimed_ids
  from claimed;

  select coalesce(jsonb_agg(
    public.lcia_scope_closure_artifact_write_set_json(claimed_id)
    order by claimed_id
  ), '[]'::jsonb)
  into v_items
  from unnest(v_claimed_ids) claimed_id;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'reconcileToken', v_token,
    'leaseExpiresAt', v_lease_expires_at,
    'writeSets', v_items
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer, p_lease_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer, p_lease_seconds integer) IS 'Service-only fenced stale-publication claim. Returns cleanup_pending write-set projections from a post-update statement so status, reconcileToken, and reconcileLeaseExpiresAt exactly match persisted claim state.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_reconcile_complete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_reconcile_complete(p_write_set_id uuid, p_reconcile_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.status = 'cleaned'
     and v_write_set.reconcile_token = p_reconcile_token then
    return jsonb_build_object('ok', true, 'reused', true);
  end if;
  if v_write_set.status <> 'cleanup_pending'
     or v_write_set.reconcile_token is distinct from p_reconcile_token
     or v_write_set.reconcile_expires_at is null
     or v_write_set.reconcile_expires_at < now() then
    return public.lcia_scope_closure_error(
      'artifact_write_set_reconcile_invalid',
      409,
      'Artifact write-set reconcile claim is not current'
    );
  end if;
  update public.lcia_scope_closure_artifact_write_sets
  set status = 'cleaned',
      cleaned_at = now(),
      updated_at = now(),
      reconcile_expires_at = null
  where id = v_write_set.id;
  return jsonb_build_object('ok', true, 'reused', false, 'data',
    public.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_reconcile_complete(p_write_set_id uuid, p_reconcile_token uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_write_set_register_batch_v2(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_job public.worker_jobs%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_batch public.lcia_scope_closure_artifact_write_set_batches%rowtype;
  v_items jsonb;
  v_request_sha256 text;
  v_first_ordinal integer;
  v_last_ordinal integer;
  v_item_count integer;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_write_set_id is null
     or p_write_token is null
     or p_worker_job_id is null
     or p_worker_lease_token is null
     or p_batch_id is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) not between 1 and 500 then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact descriptor batch'
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    where jsonb_typeof(item) <> 'object'
       or (
         select count(*)
         from jsonb_object_keys(item) key
       ) <> 10
       or exists (
         select 1
         from jsonb_object_keys(item) key
         where key not in (
           'ordinal',
           'clientKey',
           'artifactType',
           'artifactRole',
           'bucket',
           'objectPath',
           'mediaType',
           'size',
           'checksumSha256',
           'metadata'
         )
       )
       or jsonb_typeof(item->'ordinal') <> 'number'
       or coalesce(item->>'ordinal', '') !~ '^[1-9][0-9]*$'
       or length(item->>'ordinal') > 6
       or nullif(item->>'clientKey', '') is null
       or item->>'clientKey' <> trim(item->>'clientKey')
       or length(item->>'clientKey') > 500
       or nullif(item->>'artifactType', '') is null
       or item->>'artifactType' <> trim(item->>'artifactType')
       or length(item->>'artifactType') > 200
       or nullif(item->>'artifactRole', '') is null
       or item->>'artifactRole' <> trim(item->>'artifactRole')
       or length(item->>'artifactRole') > 200
       or nullif(item->>'bucket', '') is null
       or item->>'bucket' <> trim(item->>'bucket')
       or length(item->>'bucket') > 255
       or nullif(item->>'objectPath', '') is null
       or item->>'objectPath' <> trim(item->>'objectPath')
       or length(item->>'objectPath') > 2048
       or nullif(item->>'mediaType', '') is null
       or item->>'mediaType' <> trim(item->>'mediaType')
       or length(item->>'mediaType') > 255
       or jsonb_typeof(item->'size') <> 'number'
       or coalesce(item->>'size', '') !~ '^(0|[1-9][0-9]*)$'
       or length(item->>'size') > 19
       or (
         length(item->>'size') = 19
         and item->>'size' > '9223372036854775807'
       )
       or coalesce(item->>'checksumSha256', '') !~ '^[a-f0-9]{64}$'
       or jsonb_typeof(item->'metadata') <> 'object'
       or octet_length((item->'metadata')::text) > 65536
       or public.lcia_scope_closure_artifact_role(
            item->>'artifactType'
          ) is distinct from item->>'artifactRole'
       or item->>'clientKey' like '/%'
       or item->>'clientKey' like '%//%'
       or item->>'clientKey' ~ '(^|/)\.\.?(/|$)'
       or item->>'clientKey' ~ '[[:cntrl:]\\]'
       or item->>'objectPath' like '/%'
       or item->>'objectPath' like '%//%'
       or item->>'objectPath' ~ '(^|/)\.\.?(/|$)'
       or item->>'objectPath' ~ '[[:cntrl:]\\]'
       or item->>'bucket' ~ '[[:cntrl:]/\\]'
  ) then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Staged artifact descriptor is invalid'
    );
  end if;

  if exists (
    select 1
    from (
      select
        (item.value->>'ordinal')::integer as ordinal,
        item.ordinality,
        lag((item.value->>'ordinal')::integer)
          over (order by item.ordinality) as previous_ordinal
      from jsonb_array_elements(p_items)
        with ordinality item(value, ordinality)
    ) ordered
    where (
      ordered.ordinality > 1
      and ordered.ordinal <> ordered.previous_ordinal + 1
    )
  ) then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Batch ordinals must be strictly ascending and contiguous'
    );
  end if;

  select jsonb_agg(jsonb_build_object(
    'ordinal', (item.value->>'ordinal')::integer,
    'clientKey', item.value->>'clientKey',
    'artifactType', item.value->>'artifactType',
    'artifactRole', item.value->>'artifactRole',
    'bucket', item.value->>'bucket',
    'objectPath', item.value->>'objectPath',
    'mediaType', item.value->>'mediaType',
    'size', (item.value->>'size')::bigint,
    'checksumSha256', item.value->>'checksumSha256',
    'metadata', item.value->'metadata'
  ) order by item.ordinality)
  into v_items
  from jsonb_array_elements(p_items)
    with ordinality item(value, ordinality);

  v_item_count := jsonb_array_length(v_items);
  v_first_ordinal := (v_items #>> '{0,ordinal}')::integer;
  v_last_ordinal :=
    (v_items #>> array[(v_item_count - 1)::text, 'ordinal'])::integer;
  v_request_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(jsonb_build_object(
      'contractVersion',
        'lcia.scope-closure-artifact-write-set.v2',
      'batchId', p_batch_id,
      'items', v_items
    ));

  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from public.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  select * into v_batch
  from public.lcia_scope_closure_artifact_write_set_batches
  where write_set_id = v_write_set.id
    and batch_id = p_batch_id;
  if v_batch.write_set_id is not null then
    if v_batch.request_sha256 is distinct from v_request_sha256 then
      return public.lcia_scope_closure_error(
        'artifact_write_set_v2_batch_conflict',
        409,
        'Artifact descriptor batch identity conflicts'
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;

  if v_write_set.status <> 'registration_open'
     or v_write_set.staging_expires_at <= now() then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_registration_closed',
      409,
      'Artifact descriptor registration is closed'
    );
  end if;
  if v_first_ordinal < 1
     or v_last_ordinal > v_write_set.expected_descriptor_count then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Artifact descriptor ordinal is outside the expected range'
    );
  end if;

  begin
    insert into public.lcia_scope_closure_artifact_write_set_items (
      write_set_id,
      ordinal,
      client_key,
      artifact_type,
      artifact_role,
      storage_bucket,
      storage_path,
      content_type,
      byte_size,
      checksum_sha256,
      metadata
    )
    select
      v_write_set.id,
      (item->>'ordinal')::integer,
      item->>'clientKey',
      item->>'artifactType',
      item->>'artifactRole',
      item->>'bucket',
      item->>'objectPath',
      item->>'mediaType',
      (item->>'size')::bigint,
      item->>'checksumSha256',
      item->'metadata'
    from jsonb_array_elements(v_items) item
    order by (item->>'ordinal')::integer;

    insert into public.lcia_scope_closure_artifact_write_set_batches (
      write_set_id,
      batch_id,
      request_sha256,
      item_count,
      first_ordinal,
      last_ordinal
    ) values (
      v_write_set.id,
      p_batch_id,
      v_request_sha256,
      v_item_count,
      v_first_ordinal,
      v_last_ordinal
    );
  exception
    when unique_violation then
      return public.lcia_scope_closure_error(
        'artifact_write_set_v2_descriptor_conflict',
        409,
        'Artifact descriptor ordinal, client key, or locator conflicts'
      );
  end;

  update public.lcia_scope_closure_artifact_write_sets
  set updated_at = now()
  where id = v_write_set.id;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$_$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb) IS 'Service-only bounded registration of 1..500 exact descriptors. Batch UUID plus canonical bytes is idempotent; conflicting ordinal, client key, locator, or retry fails without partial insertion.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_seal_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_job public.worker_jobs%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_item_count integer;
  v_min_ordinal integer;
  v_max_ordinal integer;
  v_actual_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_write_set_id is null
     or p_write_token is null
     or p_worker_job_id is null
     or p_worker_lease_token is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set seal request'
    );
  end if;

  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return public.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from public.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  if v_write_set.status in ('staging', 'ready')
     and v_write_set.sealed_at is not null then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;
  if v_write_set.status <> 'registration_open'
     or v_write_set.staging_expires_at <= now() then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_registration_closed',
      409,
      'Artifact descriptor registration is closed'
    );
  end if;

  select count(*), min(ordinal), max(ordinal)
  into v_item_count, v_min_ordinal, v_max_ordinal
  from public.lcia_scope_closure_artifact_write_set_items
  where write_set_id = v_write_set.id;
  if v_item_count <> v_write_set.expected_descriptor_count
     or v_min_ordinal is distinct from 1
     or v_max_ordinal is distinct from
       v_write_set.expected_descriptor_count then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_incomplete',
      409,
      'Artifact descriptor set is incomplete'
    );
  end if;

  v_actual_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(
      private.lcia_scope_closure_artifact_v2_descriptor_set(v_write_set.id)
    );
  if v_actual_sha256 is distinct from v_write_set.descriptor_set_sha256 then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_digest_mismatch',
      409,
      'Artifact descriptor-set digest does not match'
    );
  end if;

  if v_write_set.required_primary_roles is distinct from
       private.lcia_scope_closure_artifact_v2_required_roles(
         v_write_set.publication_mode
       )
     or exists (
       select 1
       from public.lcia_scope_closure_artifact_write_set_items item
       where item.write_set_id = v_write_set.id
         and (
           item.metadata->>'schemaVersion' is distinct from
             'lcia.scope-closure-artifact.v2'
           or item.metadata->>'closureCheckId' is distinct from
             v_write_set.closure_check_id::text
           or item.metadata->>'fileName' is distinct from item.client_key
           or item.metadata->>'artifactRole' is distinct from
             item.artifact_role
           or item.metadata->>'retentionSeconds' is distinct from '604800'
           or coalesce(
             item.metadata->>'contentArtifactManifestHash',
             ''
           ) !~ '^[a-f0-9]{64}$'
           or position(
             'scope-closure/' || v_write_set.closure_check_id::text || '/'
             in item.storage_path
           ) = 0
           or right(
             item.storage_path,
             length(item.client_key) + 1
           ) <> '/' || item.client_key
         )
     ) then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_primary_roles_invalid',
      409,
      'Artifact descriptor invariants are invalid'
    );
  end if;

  if v_write_set.publication_mode = 'fresh' then
    if (
      select count(*)
      from public.lcia_scope_closure_artifact_write_set_items item
      where item.write_set_id = v_write_set.id
        and item.artifact_role = 'closure_report'
        and item.artifact_type = 'closure_report_xlsx'
        and item.content_type =
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    ) <> 1
       or (
         select count(*)
         from public.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'closure_report'
       ) <> 1
       or (
         select count(*)
         from public.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'closure_bundle'
           and item.artifact_type = 'closure_bundle'
           and item.content_type = 'application/json'
       ) <> 1
       or (
         select count(*)
         from public.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'closure_bundle'
       ) <> 1
       or (
         select count(*)
         from public.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'complete_machine_result'
           and item.artifact_type = 'closure_complete_machine_result'
           and item.content_type =
             'application/vnd.tiangong.scope-closure-manifest+json'
       ) <> 1
       or not exists (
         select 1
         from public.lcia_scope_closure_artifact_write_set_items bundle
         join public.lcia_scope_closure_artifact_write_set_items manifest
           on manifest.write_set_id = bundle.write_set_id
          and manifest.client_key =
            bundle.metadata->>'completeMachineResultClientKey'
         where bundle.write_set_id = v_write_set.id
           and bundle.artifact_role = 'closure_bundle'
           and manifest.artifact_role = 'complete_machine_result'
           and manifest.artifact_type =
             'closure_complete_machine_result'
           and manifest.content_type =
             'application/vnd.tiangong.scope-closure-manifest+json'
       ) then
      return public.lcia_scope_closure_error(
        'artifact_write_set_v2_primary_roles_invalid',
        409,
        'Fresh publication primary artifact roles are invalid'
      );
    end if;
  elsif v_item_count <> 1
     or not exists (
       select 1
       from public.lcia_scope_closure_artifact_write_set_items item
       where item.write_set_id = v_write_set.id
         and item.artifact_role = 'closure_report'
         and item.artifact_type = 'closure_report_xlsx'
         and item.content_type =
           'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
     ) then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_primary_roles_invalid',
      409,
      'Reused publication primary artifact role is invalid'
    );
  end if;

  update public.lcia_scope_closure_artifact_write_sets
  set status = 'staging',
      sealed_at = now(),
      updated_at = now()
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$_$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) IS 'Service-only atomic seal. Under one write-set lock it verifies exact contiguous cardinality, canonical digest, primary roles, metadata and locator invariants, and current fences before the single registration_open-to-staging upload authorization.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_status_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_write_set public.lcia_scope_closure_artifact_write_sets%rowtype;
  v_lease_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_closure_check_id is null
     or p_worker_job_id is null
     or p_worker_lease_token is null
     or p_request_id is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set status request'
    );
  end if;

  select * into v_job
  from public.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  select * into v_write_set
  from public.lcia_scope_closure_artifact_write_sets
  where closure_check_id = p_closure_check_id
    and worker_job_id = p_worker_job_id
    and request_id = p_request_id
    and contract_version =
      'lcia.scope-closure-artifact-write-set.v2';
  if v_write_set.id is null then
    return public.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;

  v_lease_sha256 :=
    private.lcia_scope_closure_artifact_v2_lease_sha256(
      p_worker_lease_token
    );
  if v_write_set.worker_lease_token_sha256 is distinct from v_lease_sha256 then
    return public.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is not bound to the artifact write-set'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid) IS 'Service-only current-lease status/readback for ambiguous responses. Returns fences, counts, batch ranges, and post-seal artifact IDs without owner identity, object locators, raw lease authority, or service credentials.';


--
-- Name: svc_lcia_scope_closure_build_binding(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_build_binding(build_worker_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_check public.lcia_scope_closure_checks%rowtype;
  v_check_id uuid;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select * into v_job
  from public.worker_jobs
  where id = build_worker_job_id;
  if v_job.id is null
     or v_job.job_kind <> 'lcia_result.package_build' then
    return public.lcia_scope_closure_error(
      'build_binding_not_found', 404, 'Build job not found'
    );
  end if;
  begin
    v_check_id := nullif(v_job.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    return public.lcia_scope_closure_error(
      'build_binding_invalid', 409, 'Build payload contains an invalid closure check identity'
    );
  end;
  select * into v_check
  from public.lcia_scope_closure_checks
  where id = v_check_id
    and requested_by = v_job.requested_by;
  if v_check.id is null then
    return public.lcia_scope_closure_error(
      'closure_check_not_usable', 409, 'Closure certificate is not valid for this build owner'
    );
  end if;
  if v_check.valid_until <= now()
     or not public.lcia_scope_closure_evidence_usable(v_check) then
    return public.lcia_scope_closure_error(
      'closure_certificate_expired', 410, 'Closure certificate evidence has expired'
    );
  end if;
  return public.svc_lcia_scope_closure_build_binding_without_expiry(
    build_worker_job_id
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_build_binding(build_worker_job_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_build_binding_without_expiry(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_build_binding_without_expiry(build_worker_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_check public.lcia_scope_closure_checks%rowtype;
  v_snapshot public.lca_network_snapshots%rowtype;
  v_artifact public.lca_snapshot_artifacts%rowtype;
  v_bundle public.worker_job_artifacts%rowtype;
  v_report public.worker_job_artifacts%rowtype;
  v_closure_check_id uuid;
  v_input_manifest jsonb;
  v_input_manifest_hash text;
  v_report_manifest_hash text;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  select * into v_job
  from public.worker_jobs
  where id = build_worker_job_id
  for update;
  if v_job.id is null or v_job.job_kind <> 'lcia_result.package_build' then
    return public.lcia_scope_closure_error('build_binding_not_found', 404, 'Build job not found');
  end if;
  if v_job.payload_schema_version <> 'lcia_result.package_build.request.v2'
     or v_job.status <> 'running'
     or v_job.lease_token is null
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return public.lcia_scope_closure_error('build_worker_job_lease_invalid', 409, 'Build job does not hold a current running lease');
  end if;
  begin
    v_closure_check_id := nullif(v_job.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    return public.lcia_scope_closure_error('build_binding_invalid', 409, 'Build payload contains an invalid closure check identity');
  end;
  select * into v_check
  from public.lcia_scope_closure_checks
  where id = v_closure_check_id
  for share;
  if v_check.id is null
     or v_check.requested_by <> v_job.requested_by
     or v_check.status <> 'passed'
     or v_check.scan_completeness <> 'complete'
     or v_check.certificate_status <> 'valid'
     or v_check.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
     or v_check.certificate_hash is null then
    return public.lcia_scope_closure_error('closure_check_not_usable', 409, 'Closure certificate is not valid for this build owner');
  end if;
  if v_check.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
     and not public.lcia_scope_closure_current_release_matches(v_check.data_snapshot_token) then
    return public.lcia_scope_closure_error('closure_check_stale', 409, 'Closure certificate was created against an earlier public release');
  end if;

  select * into v_snapshot
  from public.lca_network_snapshots
  where id = v_check.snapshot_id;
  select * into v_artifact
  from public.lca_snapshot_artifacts
  where id = v_check.snapshot_artifact_id;
  select * into v_bundle
  from public.worker_job_artifacts
  where id = v_check.closure_bundle_artifact_id;
  select * into v_report
  from public.worker_job_artifacts
  where id = v_check.report_artifact_id;
  v_input_manifest := jsonb_build_object(
    'predicateVersion', v_check.effective_scope_manifest->>'eligibilityPredicateVersion',
    'selectionMode', 'closure_certificate',
    'processes', v_check.effective_scope_manifest->'processes'
  );
  v_input_manifest_hash := public.lcia_scope_closure_sha256(v_input_manifest);
  v_report_manifest_hash := public.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_artifact.id is null
     or v_artifact.snapshot_id <> v_snapshot.id
     or v_artifact.status <> 'ready'
     or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_artifact.artifact_sha256 <> v_check.snapshot_hash
     or v_artifact.snapshot_index_sha256 <> v_check.snapshot_index_sha256
     or v_artifact.snapshot_build_contract_hash <> v_check.snapshot_build_contract_hash
     or v_artifact.effective_scope_hash <> v_check.effective_scope_hash
     or v_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_artifact.closure_bundle_hash <> v_check.closure_bundle_hash
     or v_bundle.id is null
     or v_bundle.job_id <> v_check.worker_job_id
     or v_bundle.artifact_type <> 'closure_bundle'
     or v_bundle.checksum_sha256 <> v_check.closure_bundle_hash
     or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_check.id::text
     or v_report.id is null
     or v_report.job_id <> v_check.worker_job_id
     or v_report.artifact_type <> 'closure_report_xlsx'
     or v_report_manifest_hash <> v_check.report_artifact_manifest_hash then
    return public.lcia_scope_closure_error('closure_snapshot_binding_invalid', 409, 'Persisted closure snapshot evidence is no longer usable');
  end if;

  if coalesce(v_job.payload_json->>'closure_check_id', '') <> v_check.id::text
     or coalesce(v_job.payload_json->>'closure_certificate_hash', '') <> v_check.certificate_hash
     or coalesce(v_job.payload_json->>'requested_scope_hash', '') <> v_check.requested_scope_hash
     or coalesce(v_job.payload_json->>'policy_fingerprint', '') <> v_check.policy_fingerprint
     or coalesce(v_job.payload_json->>'effective_scope_hash', '') <> v_check.effective_scope_hash
     or coalesce(v_job.payload_json->>'data_snapshot_token', '') <> v_check.data_snapshot_token
     or coalesce(v_job.payload_json->>'snapshot_id', '') <> v_check.snapshot_id::text
     or coalesce(v_job.payload_json->>'snapshot_hash', '') <> v_check.snapshot_hash
     or coalesce(v_job.payload_json->>'closure_bundle_artifact_id', '') <> v_check.closure_bundle_artifact_id::text
     or coalesce(v_job.payload_json->>'closure_bundle_hash', '') <> v_check.closure_bundle_hash
     or coalesce(v_job.payload_json->>'report_artifact_manifest_hash', '') <> v_check.report_artifact_manifest_hash
     or coalesce(v_job.payload_json->>'snapshot_artifact_id', '') <> v_check.snapshot_artifact_id::text
     or coalesce(v_job.payload_json->>'snapshot_index_sha256', '') <> v_check.snapshot_index_sha256
     or coalesce(v_job.payload_json->>'snapshot_build_contract_hash', '') <> v_check.snapshot_build_contract_hash
     or coalesce(v_job.payload_json->'effective_scope', 'null'::jsonb) <> v_check.effective_scope_manifest
     or coalesce(v_job.payload_json->>'coverage_mode', '') <> v_check.effective_scope_manifest->>'coverageMode'
     or coalesce(v_job.payload_json->'lcia_method_set', 'null'::jsonb)
          <> coalesce(v_check.effective_scope_manifest->'lciaMethods', 'null'::jsonb)
     or coalesce(v_job.payload_json->'input_manifest', 'null'::jsonb) <> v_input_manifest
     or coalesce(v_job.payload_json->>'input_manifest_hash', '') <> v_input_manifest_hash then
    return public.lcia_scope_closure_error('build_binding_mismatch', 409, 'Build payload does not exactly match the database-owned certificate');
  end if;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id,
    'certificateHash', v_check.certificate_hash,
    'requestedScopeHash', v_check.requested_scope_hash,
    'policyFingerprint', v_check.policy_fingerprint,
    'effectiveScopeHash', v_check.effective_scope_hash,
    'dataSnapshotToken', v_check.data_snapshot_token,
    'snapshotId', v_check.snapshot_id,
    'snapshotHash', v_check.snapshot_hash,
    'closureBundleArtifactId', v_check.closure_bundle_artifact_id,
    'closureBundleHash', v_check.closure_bundle_hash,
    'snapshotArtifactId', v_check.snapshot_artifact_id,
    'snapshotIndexSha256', v_check.snapshot_index_sha256,
    'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
    'coverageMode', v_check.effective_scope_manifest->>'coverageMode',
    'lciaMethodSet', v_check.effective_scope_manifest->'lciaMethods',
    'inputManifest', v_input_manifest,
    'inputManifestHash', v_input_manifest_hash,
    'effectiveScope', v_check.effective_scope_manifest
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_build_binding_without_expiry(build_worker_job_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_certificate_event(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_certificate_event(p_closure_check_id uuid, p_certificate_status text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_check public.lcia_scope_closure_checks%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if p_certificate_status not in ('stale', 'revoked')
     or coalesce(nullif(trim(p_reason), ''), '') = '' then
    return public.lcia_scope_closure_error('invalid_certificate_event', 400, 'Certificate event status and reason are required');
  end if;

  select *
    into v_check
  from public.lcia_scope_closure_checks
  where id = p_closure_check_id
  for update;

  if v_check.id is null then
    return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if not (
    (v_check.certificate_status = 'valid' and p_certificate_status in ('stale', 'revoked'))
    or (v_check.certificate_status = 'stale' and p_certificate_status = 'revoked')
  ) then
    return public.lcia_scope_closure_error('invalid_certificate_transition', 409, 'Certificate validity transition is not allowed');
  end if;

  insert into public.lcia_scope_closure_certificate_events (
    closure_check_id,
    certificate_status,
    reason
  ) values (
    v_check.id,
    p_certificate_status,
    trim(p_reason)
  );

  update public.lcia_scope_closure_checks
  set certificate_status = p_certificate_status,
      updated_at = clock_timestamp()
  where id = v_check.id;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'closureCheckId', v_check.id,
      'certificateStatus', p_certificate_status
    )
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_certificate_event(p_closure_check_id uuid, p_certificate_status text, p_reason text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_get_worker_input(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_check_get_worker_input(p_closure_check_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_check public.lcia_scope_closure_checks%rowtype;
  v_data_snapshot public.lcia_scope_closure_data_snapshots%rowtype;
  v_execution public.lcia_scope_closure_scan_executions%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  select * into v_check
  from public.lcia_scope_closure_checks
  where id = p_closure_check_id;
  select * into v_data_snapshot
  from public.lcia_scope_closure_data_snapshots
  where data_snapshot_token = v_check.data_snapshot_token;
  select * into v_execution
  from public.lcia_scope_closure_scan_executions
  where id = v_check.scan_execution_id;
  if v_check.id is null
     or v_check.requested_scope_manifest is null
     or v_data_snapshot.data_snapshot_token is null
     or v_execution.id is null
     or v_execution.numerical_snapshot_id is null then
    return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check or preallocated numerical snapshot not found');
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id,
    'scanExecutionId', v_check.scan_execution_id,
    'numericalSnapshotId', v_execution.numerical_snapshot_id,
    'requestedScope', v_check.requested_scope_manifest,
    'requestedScopeHash', v_check.requested_scope_hash,
    'policyFingerprint', v_check.policy_fingerprint,
    'dataSnapshotToken', v_check.data_snapshot_token,
    'dataSnapshotManifest', v_data_snapshot.root_manifest,
    'dataSnapshotManifestHash', v_data_snapshot.root_manifest_hash,
    'publicationEpoch', v_data_snapshot.publication_epoch,
    'expectedValidatorScannerFingerprint', v_check.expected_validator_scanner_fingerprint,
    'requestFingerprint', v_check.request_fingerprint
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_check_get_worker_input(p_closure_check_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result(uuid, text, text, text, text, jsonb, text[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_check_record_result(p_closure_check_id uuid, p_status text, p_scan_completeness text, p_effective_scope_hash text, p_certificate_hash text DEFAULT NULL::text, p_result_summary jsonb DEFAULT '{}'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_check public.lcia_scope_closure_checks%rowtype; v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if p_status not in ('passed', 'blocked', 'failed', 'cancelled')
    or p_scan_completeness not in ('complete', 'incomplete')
    or jsonb_typeof(coalesce(p_result_summary, '{}'::jsonb)) <> 'object' then
    return public.lcia_scope_closure_error('invalid_closure_result', 400, 'Invalid closure result payload');
  end if;
  select * into v_check from public.lcia_scope_closure_checks where id = p_closure_check_id for update;
  if v_check.id is null then return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found'); end if;
  if p_report_artifact_id is not null and not exists (
    select 1 from public.worker_job_artifacts a where a.id = p_report_artifact_id and a.job_id = v_check.worker_job_id
  ) then return public.lcia_scope_closure_error('closure_report_unavailable', 409, 'Report artifact does not belong to the closure job'); end if;
  if p_status = 'blocked' and p_report_artifact_id is null then
    return public.lcia_scope_closure_error('closure_report_unavailable', 409, 'Blocked closure checks require a report artifact');
  end if;
  if p_status = 'passed' and p_scan_completeness <> 'complete' then
    return public.lcia_scope_closure_error('closure_check_incomplete', 409, 'A passed closure check must be complete');
  end if;
  if p_status = 'passed' and (coalesce(nullif(trim(p_effective_scope_hash), ''), '') = '' or coalesce(nullif(trim(p_certificate_hash), ''), '') = '') then
    return public.lcia_scope_closure_error('closure_evidence_unavailable', 409, 'Passed closure checks require effective scope and certificate evidence');
  end if;
  if p_status = 'passed' and coalesce(p_result_summary->>'evidenceHash', '') <> coalesce(nullif(trim(p_certificate_hash), ''), '') then
    return public.lcia_scope_closure_error('closure_evidence_hash_mismatch', 409, 'Certificate hash must match the worker evidence hash');
  end if;
  update public.lcia_scope_closure_checks
  set status = p_status, scan_completeness = p_scan_completeness,
      effective_scope_hash = nullif(trim(p_effective_scope_hash), ''), certificate_status = case when p_status = 'passed' then 'valid' else 'unavailable' end,
      certificate_hash = nullif(trim(p_certificate_hash), ''), result_summary = coalesce(p_result_summary, '{}'::jsonb),
      blocker_codes = coalesce(p_blocker_codes, '{}'::text[]), report_artifact_id = p_report_artifact_id,
      updated_at = now(), finished_at = now()
  where id = v_check.id returning * into v_check;
  update public.worker_jobs set status = case when p_status = 'passed' then 'completed' else p_status end,
      result_json = jsonb_build_object('closureCheckId', v_check.id, 'status', p_status,
        'scanCompleteness', p_scan_completeness, 'certificateStatus', case when p_status = 'passed' then 'valid' else 'unavailable' end,
        'effectiveScopeHash', v_check.effective_scope_hash, 'certificateHash', v_check.certificate_hash),
      blocker_codes = case when p_status = 'blocked' then coalesce(p_blocker_codes, '{}'::text[]) else blocker_codes end,
      resolution_scope = case when p_status = 'blocked' then 'operator' else resolution_scope end,
      finished_at = now(), updated_at = now()
  where id = v_check.worker_job_id returning * into v_job;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object('closureCheckId', v_check.id, 'workerJob', public.worker_job_payload(v_job, true)));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_check_record_result(p_closure_check_id uuid, p_status text, p_scan_completeness text, p_effective_scope_hash text, p_certificate_hash text, p_result_summary jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v2(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_check_record_result_v2(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb DEFAULT '{}'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if lower(trim(coalesce(p_status, ''))) = 'passed' then
    return public.lcia_scope_closure_error(
      'closure_snapshot_evidence_v3_required', 409,
      'Passed closure checks require database-verified numerical snapshot evidence through record_result_v3'
    );
  end if;
  return public.svc_lcia_scope_closure_check_record_result_v2_legacy(
    p_closure_check_id,
    p_job_id,
    p_lease_token,
    p_status,
    p_scan_completeness,
    p_effective_scope_manifest,
    coalesce(p_evidence, '{}'::jsonb)
      - array['snapshotId', 'snapshotHash', 'snapshotArtifactId',
              'snapshotIndexSha256', 'snapshotBuildContractHash'],
    p_result_summary,
    p_issues,
    p_blocker_codes,
    p_report_artifact_id
  );
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_check_record_result_v2(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb, p_issues jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v2_legacy(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_check_record_result_v2_legacy(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb DEFAULT '{}'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_result jsonb; v_check public.lcia_scope_closure_checks%rowtype; v_execution public.lcia_scope_closure_scan_executions%rowtype; v_scan_key text; v_existing_execution uuid;
begin
  select * into v_check from public.lcia_scope_closure_checks where id=p_closure_check_id;
  if v_check.id is null then return public.lcia_scope_closure_error('closure_check_not_found',404,'Closure check not found'); end if;
  if v_check.scan_execution_id is not null then
    select * into v_execution from public.lcia_scope_closure_scan_executions where id=v_check.scan_execution_id for update;
    if v_execution.status<>'running' or v_execution.leased_by_job_id<>p_job_id or v_execution.lease_token is distinct from p_lease_token then return public.lcia_scope_closure_error('scan_execution_lease_invalid',409,'Scan execution is not held by this worker job'); end if;
  end if;
  v_result:=public.svc_lcia_scope_closure_check_record_result_v2_untracked(p_closure_check_id,p_job_id,p_lease_token,p_status,p_scan_completeness,p_effective_scope_manifest,p_evidence,p_result_summary,p_issues,p_blocker_codes,p_report_artifact_id);
  if coalesce((v_result->>'ok')::boolean,false) is not true then return v_result; end if;
  if v_execution.id is not null then
    select * into v_check from public.lcia_scope_closure_checks where id=p_closure_check_id;
    v_scan_key:=public.lcia_scope_closure_sha256(jsonb_build_object('effectiveScopeHash',v_check.effective_scope_hash,'policyFingerprint',v_check.policy_fingerprint,'validatorScannerFingerprint',v_check.expected_validator_scanner_fingerprint,'dataSnapshotToken',v_check.data_snapshot_token));
    select id into v_existing_execution from public.lcia_scope_closure_scan_executions where scan_key=v_scan_key and id<>v_execution.id limit 1;
    if v_existing_execution is not null then v_scan_key:=null; end if;
    update public.lcia_scope_closure_scan_executions set scan_key=v_scan_key,status=case when lower(trim(p_status))='passed' or (lower(trim(p_status))='blocked' and p_scan_completeness='complete') then 'completed' else 'failed' end,lease_token=null,leased_by_job_id=null,lease_expires_at=null,completed_check_id=case when lower(trim(p_status))='passed' or (lower(trim(p_status))='blocked' and p_scan_completeness='complete') then p_closure_check_id else null end,source_fingerprint=nullif(p_evidence->>'sourceFingerprint',''),evidence_hash=nullif(p_evidence->>'evidenceHash',''),updated_at=now(),completed_at=now() where id=v_execution.id;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_check_record_result_v2_legacy(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb, p_issues jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v2_untracked(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_check_record_result_v2_untracked(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb DEFAULT '{}'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_check public.lcia_scope_closure_checks%rowtype; v_job public.worker_jobs%rowtype; v_status text := lower(trim(p_status));
  v_effective_hash text; v_certificate_bindings jsonb; v_certificate_hash text; v_worker_status text; v_issue jsonb; v_worker_result jsonb;
  v_closure_issue public.lcia_scope_closure_issues%rowtype; v_occurrence jsonb; v_root jsonb;
  v_artifact public.worker_job_artifacts%rowtype; v_report_artifact_manifest_hash text; v_worker_record jsonb;
begin
  if not coalesce(util.is_service_request(), false) then return public.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  if v_status not in ('passed','blocked','failed') or p_scan_completeness not in ('complete','incomplete','unknown')
     or jsonb_typeof(coalesce(p_effective_scope_manifest,'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_evidence,'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_result_summary,'{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_issues,'[]'::jsonb)) <> 'array' then return public.lcia_scope_closure_error('invalid_closure_result',400,'Invalid closure result payload'); end if;
  select * into v_check from public.lcia_scope_closure_checks where id = p_closure_check_id for update;
  if v_check.id is null or v_check.worker_job_id <> p_job_id then return public.lcia_scope_closure_error('closure_check_not_found',404,'Closure check not found'); end if;
  if v_check.status not in ('queued','running') then return public.lcia_scope_closure_error('closure_check_already_terminal',409,'Closure check is already terminal'); end if;
  select * into v_job from public.worker_jobs where id = p_job_id for update;
  if v_job.status <> 'running' or v_job.lease_token is distinct from p_lease_token or v_job.lease_expires_at < now() then return public.lcia_scope_closure_error('worker_job_lease_invalid',409,'Worker job lease is no longer valid'); end if;
  select * into v_artifact from public.worker_job_artifacts where id = p_report_artifact_id and job_id = v_job.id;
  if p_report_artifact_id is not null and v_artifact.id is null then return public.lcia_scope_closure_error('closure_report_unavailable',409,'Report artifact does not belong to the closure job'); end if;
  if v_status in ('passed','blocked') and p_report_artifact_id is null then return public.lcia_scope_closure_error('closure_report_unavailable',409,'Completed closure checks require a report artifact'); end if;
  if v_status = 'passed' and (p_scan_completeness <> 'complete' or exists (
    select 1 from jsonb_array_elements(p_issues) issue(value)
    where coalesce((issue.value->>'blocking')::boolean, false)
  )) then return public.lcia_scope_closure_error('closure_check_incomplete',409,'Passed closure checks must be complete and free of blocking issues'); end if;
  if v_status = 'blocked' and (cardinality(coalesce(p_blocker_codes,'{}'::text[])) = 0 or jsonb_array_length(p_issues) = 0) then return public.lcia_scope_closure_error('closure_blocker_details_required',409,'Blocked closure checks require issues and blocker codes'); end if;
  if v_status = 'passed' and not (p_evidence ?& array['schemaVersion','sourceFingerprint','resolutionMapHash','closureBundleHash','snapshotId','snapshotHash','reportArtifactManifestHash','evidenceHash']) then return public.lcia_scope_closure_error('closure_evidence_unavailable',409,'Passed closure checks require complete evidence'); end if;
  if p_report_artifact_id is not null then
    v_report_artifact_manifest_hash := public.lcia_scope_closure_sha256(jsonb_build_object('artifactId',v_artifact.id,'bucket',v_artifact.storage_bucket,'objectPath',v_artifact.storage_path,'mediaType',v_artifact.content_type,'byteSize',v_artifact.byte_size,'checksumSha256',v_artifact.checksum_sha256));
  end if;
  if v_status = 'passed' and coalesce(p_evidence->>'reportArtifactManifestHash','') <> coalesce(v_report_artifact_manifest_hash,'') then return public.lcia_scope_closure_error('closure_report_hash_mismatch',409,'Report artifact manifest hash does not match persisted artifact metadata'); end if;
  v_effective_hash := public.lcia_scope_closure_sha256(p_effective_scope_manifest);
  if v_status = 'passed' then
    v_certificate_bindings := jsonb_build_object('certificateSchemaVersion','lcia.scope-closure-certificate.v1','requestedScopeHash',v_check.requested_scope_hash,'scopeHash',v_effective_hash,'policyFingerprint',v_check.policy_fingerprint,'dataSnapshotToken',v_check.data_snapshot_token,'validatorScannerFingerprint',v_check.expected_validator_scanner_fingerprint,'sourceFingerprint',p_evidence->>'sourceFingerprint','resolutionMapHash',p_evidence->>'resolutionMapHash','closureBundleHash',p_evidence->>'closureBundleHash','snapshotId',p_evidence->>'snapshotId','snapshotHash',p_evidence->>'snapshotHash','reportArtifactManifestHash',p_evidence->>'reportArtifactManifestHash','evidenceHash',p_evidence->>'evidenceHash');
    v_certificate_hash := public.lcia_scope_closure_sha256(v_certificate_bindings);
  end if;
  delete from public.lcia_scope_closure_issues where closure_check_id = v_check.id;
  for v_issue in select value from jsonb_array_elements(p_issues) loop
    insert into public.lcia_scope_closure_issues(closure_check_id,issue_key,severity,blocking,issue_code,source_dataset_type,source_dataset_id,source_dataset_version,json_path,reference_role,requested_target_type,requested_target_id,requested_target_version,message,suggested_action,occurrence_count,affected_root_count,details)
    values(v_check.id,coalesce(nullif(trim(v_issue->>'issueKey'),''),public.lcia_scope_closure_sha256(v_issue)),coalesce(v_issue->>'severity','blocker'),coalesce((v_issue->>'blocking')::boolean,false),coalesce(nullif(trim(v_issue->>'issueCode'),''),'closure_issue'),nullif(v_issue->>'sourceDatasetType',''),nullif(v_issue->>'sourceDatasetId','')::uuid,nullif(v_issue->>'sourceDatasetVersion',''),nullif(v_issue->>'jsonPath',''),nullif(v_issue->>'referenceRole',''),nullif(v_issue->>'requestedTargetType',''),nullif(v_issue->>'requestedTargetId','')::uuid,nullif(v_issue->>'requestedTargetVersion',''),coalesce(nullif(v_issue->>'message',''),'Closure validation issue'),nullif(v_issue->>'suggestedAction',''),greatest(1,coalesce((v_issue->>'occurrenceCount')::integer,1)),greatest(0,coalesce((v_issue->>'affectedRootCount')::integer,0)),coalesce(v_issue->'details','{}'::jsonb)) returning * into v_closure_issue;
    for v_occurrence in select value from jsonb_array_elements(coalesce(v_issue->'occurrences','[]'::jsonb)) loop
      insert into public.lcia_scope_closure_issue_occurrences(closure_issue_id,occurrence_key,source_dataset_type,source_dataset_id,source_dataset_version,json_path,reference_role,details)
      values(v_closure_issue.id,coalesce(nullif(v_occurrence->>'occurrenceKey',''),public.lcia_scope_closure_sha256(v_occurrence)),nullif(v_occurrence->>'sourceDatasetType',''),nullif(v_occurrence->>'sourceDatasetId','')::uuid,nullif(v_occurrence->>'sourceDatasetVersion',''),nullif(v_occurrence->>'jsonPath',''),nullif(v_occurrence->>'referenceRole',''),coalesce(v_occurrence->'details','{}'::jsonb));
    end loop;
    for v_root in select value from jsonb_array_elements(coalesce(v_issue->'affectedRoots','[]'::jsonb)) loop
      insert into public.lcia_scope_closure_issue_roots(closure_issue_id,root_dataset_type,root_dataset_id,root_dataset_version,impact_role,witness_path)
      values(v_closure_issue.id,coalesce(nullif(v_root->>'datasetType',''),'process'),(v_root->>'id')::uuid,coalesce(nullif(v_root->>'version',''),'00.00.000'),coalesce(nullif(v_root->>'impactRole',''),'root'),coalesce(v_root->'witnessPath','[]'::jsonb));
    end loop;
  end loop;
  update public.lcia_scope_closure_checks set status=v_status,scan_completeness=p_scan_completeness,effective_scope_manifest=p_effective_scope_manifest,effective_scope_hash=v_effective_hash,certificate_schema_version=case when v_status='passed' then 'lcia.scope-closure-certificate.v1' else null end,certificate_status=case when v_status='passed' then 'valid' else 'unavailable' end,certificate_hash=v_certificate_hash,source_fingerprint=nullif(p_evidence->>'sourceFingerprint',''),resolution_map_hash=nullif(p_evidence->>'resolutionMapHash',''),closure_bundle_hash=nullif(p_evidence->>'closureBundleHash',''),snapshot_id=nullif(p_evidence->>'snapshotId','')::uuid,snapshot_hash=nullif(p_evidence->>'snapshotHash',''),report_artifact_manifest_hash=nullif(p_evidence->>'reportArtifactManifestHash',''),evidence_hash=nullif(p_evidence->>'evidenceHash',''),result_summary=p_result_summary,blocker_codes=coalesce(p_blocker_codes,'{}'::text[]),report_artifact_id=p_report_artifact_id,updated_at=now(),finished_at=now() where id=v_check.id returning * into v_check;
  v_worker_status := case v_status when 'passed' then 'completed' else v_status end;
  v_worker_result := jsonb_strip_nulls(jsonb_build_object('closureCheckId',v_check.id,'status',v_status,'scanCompleteness',p_scan_completeness,'certificateStatus',v_check.certificate_status,'effectiveScopeHash',v_check.effective_scope_hash,'certificateHash',v_check.certificate_hash));
  select public.worker_record_job_result(v_job.id,p_lease_token,v_worker_status,v_worker_result,'lcia.scope_closure_check.result.v1',null,jsonb_build_object('progressCounters',coalesce(p_result_summary->'progressCounters','{}'::jsonb)),case when v_status='failed' then coalesce(p_result_summary->>'errorCode','closure_check_failed') else null end,case when v_status='failed' then 'Scope closure check failed' else null end,null,case when v_status='blocked' then coalesce(p_blocker_codes,'{}'::text[]) else null end,case when v_status='blocked' then 'operator' else null end,case when v_status='failed' then true else false end) into v_worker_record;
  if coalesce((v_worker_record->>'ok')::boolean,false) is not true then raise exception using errcode='P0001',message='worker_job_result_rejected'; end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('closureCheckId',v_check.id,'certificateHash',v_certificate_hash,'workerJobId',v_job.id));
exception when invalid_text_representation then return public.lcia_scope_closure_error('invalid_closure_result',400,'Closure result contains invalid identity values');
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_check_record_result_v2_untracked(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb, p_issues jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v3(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_check_record_result_v3(check_id uuid, worker_job_id uuid, lease_token uuid, status text, scan_completeness text, effective_scope jsonb, evidence jsonb, result_summary jsonb, issues jsonb, blocker_codes text[], report_artifact_id uuid, closure_bundle_artifact_id uuid, snapshot_artifact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text := lower(trim(coalesce(status, '')));
  v_check public.lcia_scope_closure_checks%rowtype;
  v_job public.worker_jobs%rowtype;
  v_execution public.lcia_scope_closure_scan_executions%rowtype;
  v_snapshot public.lca_network_snapshots%rowtype;
  v_snapshot_artifact public.lca_snapshot_artifacts%rowtype;
  v_report public.worker_job_artifacts%rowtype;
  v_bundle public.worker_job_artifacts%rowtype;
  v_effective_scope_hash text;
  v_report_manifest_hash text;
  v_evidence_hash text;
  v_build_contract_hash text;
  v_certificate_hash text;
  v_certificate_bindings jsonb;
  v_issue jsonb;
  v_occurrence jsonb;
  v_root jsonb;
  v_closure_issue public.lcia_scope_closure_issues%rowtype;
  v_worker_result jsonb;
  v_scan_key text;
  v_existing_execution uuid;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if v_status not in ('passed', 'blocked', 'failed')
     or scan_completeness not in ('complete', 'incomplete', 'unknown')
     or jsonb_typeof(coalesce(effective_scope, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(evidence, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(result_summary, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(issues, 'null'::jsonb)) <> 'array' then
    return public.lcia_scope_closure_error('invalid_closure_result', 400, 'Invalid closure result payload');
  end if;

  -- Blocked and failed checks intentionally do not acquire or persist a
  -- numerical snapshot binding.  V2 remains the compatibility path for those
  -- non-certificate terminal states.
  if v_status <> 'passed' then
    return public.svc_lcia_scope_closure_check_record_result_v2_legacy(
      check_id, worker_job_id, lease_token, v_status, scan_completeness,
      effective_scope,
      coalesce(evidence, '{}'::jsonb)
        - array['snapshotId', 'snapshotHash', 'snapshotArtifactId',
                'snapshotIndexSha256', 'snapshotBuildContractHash'],
      result_summary, issues, blocker_codes, report_artifact_id
    );
  end if;

  if scan_completeness <> 'complete'
     or exists (
       select 1 from jsonb_array_elements(issues) issue(value)
       where coalesce((issue.value->>'blocking')::boolean, false)
     ) then
    return public.lcia_scope_closure_error('closure_check_incomplete', 409, 'Passed closure checks must be complete and free of blocking issues');
  end if;
  if evidence->>'schemaVersion' is distinct from 'lcia.scope-closure-evidence.v2'
     or result_summary->>'schemaVersion' is distinct from 'lcia.scope-closure-summary.v1'
     or not (evidence ?& array[
    'sourceFingerprint', 'resolutionMapHash', 'closureBundleHash',
    'closureBundleArtifactId', 'snapshotId', 'snapshotHash', 'snapshotArtifactId',
    'snapshotIndexSha256', 'snapshotBuildContractHash', 'evidenceHash'
  ]) or not (result_summary ? 'evidenceHash') then
    return public.lcia_scope_closure_error('closure_evidence_unavailable', 409, 'Passed closure checks require complete numerical snapshot evidence');
  end if;

  select * into v_check
  from public.lcia_scope_closure_checks
  where id = check_id
  for update;
  if v_check.id is null or v_check.worker_job_id <> worker_job_id then
    return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if v_check.status not in ('queued', 'running') then
    return public.lcia_scope_closure_error('closure_check_already_terminal', 409, 'Closure check is already terminal');
  end if;

  select * into v_job
  from public.worker_jobs
  where id = worker_job_id
  for update;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from lease_token
     or v_job.lease_expires_at < now() then
    return public.lcia_scope_closure_error('worker_job_lease_invalid', 409, 'Worker job lease is no longer valid');
  end if;

  select * into v_execution
  from public.lcia_scope_closure_scan_executions
  where id = v_check.scan_execution_id
  for update;
  if v_execution.id is null
     or v_execution.status <> 'running'
     or v_execution.leased_by_job_id <> worker_job_id
     or v_execution.lease_token is distinct from lease_token then
    return public.lcia_scope_closure_error('scan_execution_lease_invalid', 409, 'Scan execution is not held by this worker job');
  end if;

  select * into v_report
  from public.worker_job_artifacts
  where id = report_artifact_id
    and job_id = v_job.id
    and artifact_type = 'closure_report_xlsx';
  if v_report.id is null then
    return public.lcia_scope_closure_error('closure_report_unavailable', 409, 'Report artifact does not belong to the closure job or has the wrong type');
  end if;

  select * into v_bundle
  from public.worker_job_artifacts
  where id = closure_bundle_artifact_id
    and job_id = v_job.id
    and artifact_type = 'closure_bundle';
  if v_bundle.id is null
     or v_bundle.checksum_sha256 is null
     or v_bundle.id::text <> evidence->>'closureBundleArtifactId'
     or v_bundle.checksum_sha256 <> evidence->>'closureBundleHash'
     or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_check.id::text then
    return public.lcia_scope_closure_error('closure_bundle_binding_invalid', 409, 'Closure bundle does not belong to this check or its hash does not match');
  end if;

  select * into v_snapshot
  from public.lca_network_snapshots
  where id = v_execution.numerical_snapshot_id
  for update;
  select * into v_snapshot_artifact
  from public.lca_snapshot_artifacts
  where id = snapshot_artifact_id;

  v_effective_scope_hash := public.lcia_scope_closure_sha256(effective_scope);
  v_build_contract_hash := public.lcia_scope_closure_sha256_text(
    'lcia.numerical-snapshot-build-contract.v1' || chr(10)
    || v_effective_scope_hash || chr(10)
    || v_check.data_snapshot_token || chr(10)
    || v_bundle.checksum_sha256 || chr(10)
    || v_execution.numerical_snapshot_id::text || chr(10)
    || coalesce(v_snapshot_artifact.artifact_format, '')
  );

  if v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_snapshot.scope <> 'data_product'
     or v_snapshot.provider_matching_rule <> 'split_by_process_volume'
     or v_snapshot.id::text <> evidence->>'snapshotId'
     or v_snapshot_artifact.id is null
     or v_snapshot_artifact.id::text <> evidence->>'snapshotArtifactId'
     or v_snapshot_artifact.snapshot_id <> v_snapshot.id
     or v_snapshot_artifact.status <> 'ready'
     or v_snapshot_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_snapshot_artifact.artifact_sha256 <> evidence->>'snapshotHash'
     or v_snapshot_artifact.snapshot_index_sha256 <> evidence->>'snapshotIndexSha256'
     or v_snapshot_artifact.snapshot_build_contract_hash <> evidence->>'snapshotBuildContractHash'
     or v_snapshot_artifact.snapshot_build_contract_hash <> v_build_contract_hash
     or v_snapshot_artifact.effective_scope_hash <> v_effective_scope_hash
     or v_snapshot_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_snapshot_artifact.closure_bundle_hash <> v_bundle.checksum_sha256 then
    return public.lcia_scope_closure_error('numerical_snapshot_binding_invalid', 409, 'Numerical snapshot or artifact does not satisfy the closure certificate contract');
  end if;

  v_report_manifest_hash := public.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if coalesce(evidence->>'reportArtifactManifestHash', '') <> v_report_manifest_hash then
    return public.lcia_scope_closure_error('closure_report_hash_mismatch', 409, 'Report artifact manifest hash does not match persisted artifact metadata');
  end if;

  v_evidence_hash := public.lcia_scope_closure_sha256_text(
    'lcia.scope-closure-evidence.v2' || chr(10)
    || (evidence->>'sourceFingerprint') || chr(10)
    || (evidence->>'resolutionMapHash') || chr(10)
    || v_bundle.checksum_sha256 || chr(10)
    || v_bundle.id::text || chr(10)
    || v_snapshot.id::text || chr(10)
    || v_snapshot_artifact.artifact_sha256 || chr(10)
    || v_snapshot_artifact.id::text || chr(10)
    || v_snapshot_artifact.snapshot_index_sha256 || chr(10)
    || v_snapshot_artifact.snapshot_build_contract_hash
  );
  if evidence->>'evidenceHash' <> v_evidence_hash
     or result_summary->>'evidenceHash' <> v_evidence_hash then
    return public.lcia_scope_closure_error('closure_evidence_hash_mismatch', 409, 'Closure evidence hash does not match database-owned snapshot evidence');
  end if;

  v_certificate_bindings := jsonb_build_object(
    'certificateSchemaVersion', 'lcia.scope-closure-certificate.v2',
    'closureCheckId', v_check.id,
    'requestedScopeHash', v_check.requested_scope_hash,
    'effectiveScopeHash', v_effective_scope_hash,
    'effectiveScope', effective_scope,
    'policyFingerprint', v_check.policy_fingerprint,
    'dataSnapshotToken', v_check.data_snapshot_token,
    'validatorScannerFingerprint', v_check.expected_validator_scanner_fingerprint,
    'sourceFingerprint', evidence->>'sourceFingerprint',
    'resolutionMapHash', evidence->>'resolutionMapHash',
    'closureBundleArtifactId', v_bundle.id,
    'closureBundleHash', v_bundle.checksum_sha256,
    'snapshotId', v_snapshot.id,
    'snapshotHash', v_snapshot_artifact.artifact_sha256,
    'snapshotArtifactId', v_snapshot_artifact.id,
    'snapshotIndexSha256', v_snapshot_artifact.snapshot_index_sha256,
    'snapshotBuildContractHash', v_snapshot_artifact.snapshot_build_contract_hash,
    'reportArtifactManifestHash', v_report_manifest_hash,
    'evidenceHash', v_evidence_hash
  );
  v_certificate_hash := public.lcia_scope_closure_sha256(v_certificate_bindings);

  delete from public.lcia_scope_closure_issues where closure_check_id = v_check.id;
  for v_issue in select value from jsonb_array_elements(issues) loop
    insert into public.lcia_scope_closure_issues(
      closure_check_id, issue_key, severity, blocking, issue_code,
      source_dataset_type, source_dataset_id, source_dataset_version,
      json_path, reference_role, requested_target_type, requested_target_id,
      requested_target_version, message, suggested_action,
      occurrence_count, affected_root_count, details
    ) values (
      v_check.id,
      coalesce(nullif(trim(v_issue->>'issueKey'), ''), public.lcia_scope_closure_sha256(v_issue)),
      coalesce(v_issue->>'severity', 'blocker'),
      coalesce((v_issue->>'blocking')::boolean, false),
      coalesce(nullif(trim(v_issue->>'issueCode'), ''), 'closure_issue'),
      nullif(v_issue->>'sourceDatasetType', ''),
      nullif(v_issue->>'sourceDatasetId', '')::uuid,
      nullif(v_issue->>'sourceDatasetVersion', ''),
      nullif(v_issue->>'jsonPath', ''),
      nullif(v_issue->>'referenceRole', ''),
      nullif(v_issue->>'requestedTargetType', ''),
      nullif(v_issue->>'requestedTargetId', '')::uuid,
      nullif(v_issue->>'requestedTargetVersion', ''),
      coalesce(nullif(v_issue->>'message', ''), 'Closure validation issue'),
      nullif(v_issue->>'suggestedAction', ''),
      greatest(1, coalesce((v_issue->>'occurrenceCount')::integer, 1)),
      greatest(0, coalesce((v_issue->>'affectedRootCount')::integer, 0)),
      coalesce(v_issue->'details', '{}'::jsonb)
    ) returning * into v_closure_issue;
    for v_occurrence in
      select value from jsonb_array_elements(coalesce(v_issue->'occurrences', '[]'::jsonb))
    loop
      insert into public.lcia_scope_closure_issue_occurrences(
        closure_issue_id, occurrence_key, source_dataset_type,
        source_dataset_id, source_dataset_version, json_path, reference_role, details
      ) values (
        v_closure_issue.id,
        coalesce(nullif(v_occurrence->>'occurrenceKey', ''), public.lcia_scope_closure_sha256(v_occurrence)),
        nullif(v_occurrence->>'sourceDatasetType', ''),
        nullif(v_occurrence->>'sourceDatasetId', '')::uuid,
        nullif(v_occurrence->>'sourceDatasetVersion', ''),
        nullif(v_occurrence->>'jsonPath', ''),
        nullif(v_occurrence->>'referenceRole', ''),
        coalesce(v_occurrence->'details', '{}'::jsonb)
      );
    end loop;
    for v_root in
      select value from jsonb_array_elements(coalesce(v_issue->'affectedRoots', '[]'::jsonb))
    loop
      insert into public.lcia_scope_closure_issue_roots(
        closure_issue_id, root_dataset_type, root_dataset_id,
        root_dataset_version, impact_role, witness_path
      ) values (
        v_closure_issue.id,
        coalesce(nullif(v_root->>'datasetType', ''), 'process'),
        (v_root->>'id')::uuid,
        coalesce(nullif(v_root->>'version', ''), '00.00.000'),
        coalesce(nullif(v_root->>'impactRole', ''), 'root'),
        coalesce(v_root->'witnessPath', '[]'::jsonb)
      );
    end loop;
  end loop;

  update public.lcia_scope_closure_checks set
    status = 'passed',
    scan_completeness = 'complete',
    effective_scope_manifest = effective_scope,
    effective_scope_hash = v_effective_scope_hash,
    certificate_schema_version = 'lcia.scope-closure-certificate.v2',
    certificate_status = 'valid',
    certificate_hash = v_certificate_hash,
    source_fingerprint = nullif(evidence->>'sourceFingerprint', ''),
    resolution_map_hash = nullif(evidence->>'resolutionMapHash', ''),
    closure_bundle_hash = v_bundle.checksum_sha256,
    closure_bundle_artifact_id = v_bundle.id,
    snapshot_id = v_snapshot.id,
    snapshot_hash = v_snapshot_artifact.artifact_sha256,
    snapshot_artifact_id = v_snapshot_artifact.id,
    snapshot_index_sha256 = v_snapshot_artifact.snapshot_index_sha256,
    snapshot_build_contract_hash = v_snapshot_artifact.snapshot_build_contract_hash,
    report_artifact_manifest_hash = v_report_manifest_hash,
    evidence_hash = v_evidence_hash,
    result_summary = svc_lcia_scope_closure_check_record_result_v3.result_summary,
    blocker_codes = coalesce(svc_lcia_scope_closure_check_record_result_v3.blocker_codes, '{}'::text[]),
    report_artifact_id = v_report.id,
    updated_at = now(),
    finished_at = now()
  where id = v_check.id
  returning * into v_check;

  v_scan_key := public.lcia_scope_closure_sha256(jsonb_build_object(
    'effectiveScopeHash', v_check.effective_scope_hash,
    'policyFingerprint', v_check.policy_fingerprint,
    'validatorScannerFingerprint', v_check.expected_validator_scanner_fingerprint,
    'dataSnapshotToken', v_check.data_snapshot_token
  ));
  select id into v_existing_execution
  from public.lcia_scope_closure_scan_executions
  where scan_key = v_scan_key and id <> v_execution.id
  limit 1;
  if v_existing_execution is not null then v_scan_key := null; end if;
  update public.lcia_scope_closure_scan_executions set
    scan_key = v_scan_key,
    status = 'completed',
    lease_token = null,
    leased_by_job_id = null,
    lease_expires_at = null,
    completed_check_id = v_check.id,
    source_fingerprint = v_check.source_fingerprint,
    evidence_hash = v_check.evidence_hash,
    updated_at = now(),
    completed_at = now()
  where id = v_execution.id;

  select public.worker_record_job_result(
    v_job.id,
    lease_token,
    'completed',
    jsonb_build_object(
      'closureCheckId', v_check.id,
      'status', v_check.status,
      'scanCompleteness', v_check.scan_completeness,
      'certificateStatus', v_check.certificate_status,
      'certificateHash', v_check.certificate_hash,
      'effectiveScopeHash', v_check.effective_scope_hash,
      'snapshotId', v_check.snapshot_id,
      'snapshotHash', v_check.snapshot_hash,
      'snapshotArtifactId', v_check.snapshot_artifact_id,
      'snapshotIndexSha256', v_check.snapshot_index_sha256,
      'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
      'evidenceHash', v_check.evidence_hash
    ),
    'lcia.scope_closure_check.result.v2',
    jsonb_build_object(
      'reportArtifactId', v_report.id,
      'closureBundleArtifactId', v_bundle.id,
      'snapshotArtifactId', v_snapshot_artifact.id
    ),
    jsonb_build_object('progressCounters', coalesce(result_summary->'progressCounters', '{}'::jsonb)),
    null, null, null, null, null, false
  ) into v_worker_result;
  if coalesce((v_worker_result->>'ok')::boolean, false) is not true then
    raise exception using errcode = 'P0001', message = 'worker_job_result_rejected';
  end if;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id,
    'status', v_check.status,
    'scanCompleteness', v_check.scan_completeness,
    'certificateStatus', v_check.certificate_status,
    'certificateHash', v_check.certificate_hash,
    'effectiveScopeHash', v_check.effective_scope_hash,
    'snapshotId', v_check.snapshot_id,
    'snapshotHash', v_check.snapshot_hash,
    'snapshotArtifactId', v_check.snapshot_artifact_id,
    'snapshotIndexSha256', v_check.snapshot_index_sha256,
    'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
    'evidenceHash', v_check.evidence_hash
  ));
exception
  when invalid_text_representation then
    return public.lcia_scope_closure_error('invalid_closure_result', 400, 'Closure result contains invalid identity values');
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_check_record_result_v3(check_id uuid, worker_job_id uuid, lease_token uuid, status text, scan_completeness text, effective_scope jsonb, evidence jsonb, result_summary jsonb, issues jsonb, blocker_codes text[], report_artifact_id uuid, closure_bundle_artifact_id uuid, snapshot_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_claim_scan_execution(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_claim_scan_execution(p_scan_execution_id uuid, p_worker_job_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_execution public.lcia_scope_closure_scan_executions%rowtype; v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then return public.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  select * into v_job from public.worker_jobs where id=p_worker_job_id;
  if v_job.id is null or v_job.status<>'running' or v_job.lease_token is distinct from p_lease_token or v_job.lease_expires_at<now() then return public.lcia_scope_closure_error('worker_job_lease_invalid',409,'Worker job lease is no longer valid'); end if;
  select * into v_execution from public.lcia_scope_closure_scan_executions where id=p_scan_execution_id for update;
  if v_execution.id is null or not exists (select 1 from public.lcia_scope_closure_checks c where c.scan_execution_id=v_execution.id and c.worker_job_id=v_job.id and c.request_fingerprint=v_execution.request_fingerprint) then return public.lcia_scope_closure_error('scan_execution_not_found',404,'Scan execution not found'); end if;
  if v_execution.status='completed' then return jsonb_build_object('ok',true,'data',jsonb_build_object('acquired',false,'completed',true,'completedCheckId',v_execution.completed_check_id)); end if;
  if v_execution.status='running' and v_execution.lease_expires_at>=now() and v_execution.leased_by_job_id<>v_job.id then return jsonb_build_object('ok',true,'data',jsonb_build_object('acquired',false,'completed',false)); end if;
  update public.lcia_scope_closure_scan_executions set status='running',lease_token=p_lease_token,leased_by_job_id=v_job.id,lease_expires_at=v_job.lease_expires_at,updated_at=now() where id=v_execution.id;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('acquired',true,'completed',false));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_claim_scan_execution(p_scan_execution_id uuid, p_worker_job_id uuid, p_lease_token uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_fail_before_scan(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_fail_before_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c public.lcia_scope_closure_checks%rowtype; j public.worker_jobs%rowtype; e public.lcia_scope_closure_scan_executions%rowtype; wr jsonb;
begin
  if not coalesce(util.is_service_request(),false) then return public.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  select * into c from public.lcia_scope_closure_checks where id=p_closure_check_id for update; select * into j from public.worker_jobs where id=p_worker_job_id for update;
  if c.id is null or c.worker_job_id<>j.id or c.status not in ('queued','running') or j.status<>'running' or j.lease_token is distinct from p_lease_token or j.lease_expires_at<now() then return public.lcia_scope_closure_error('worker_job_lease_invalid',409,'Worker job lease is no longer valid'); end if;
  select * into e from public.lcia_scope_closure_scan_executions where id=c.scan_execution_id for update;
  update public.lcia_scope_closure_checks set status='failed',scan_completeness='unknown',certificate_status='unavailable',result_summary=jsonb_build_object('errorCode',coalesce(nullif(trim(p_error_code),''),'closure_check_failed')),updated_at=now(),finished_at=now() where id=c.id;
  if e.id is not null and e.status='running' and e.leased_by_job_id=j.id and e.lease_token is not distinct from p_lease_token then update public.lcia_scope_closure_scan_executions set status='failed',lease_token=null,leased_by_job_id=null,lease_expires_at=null,updated_at=now(),completed_at=now() where id=e.id; end if;
  select public.worker_record_job_result(j.id,p_lease_token,'failed',jsonb_build_object('closureCheckId',c.id,'status','failed'),'lcia.scope_closure_check.result.v1',null,null,coalesce(nullif(trim(p_error_code),''),'closure_check_failed'),'Scope closure check failed',null,null,null,true) into wr;
  if coalesce((wr->>'ok')::boolean,false) is not true then raise exception using errcode='P0001',message='worker_job_result_rejected'; end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('closureCheckId',c.id,'workerJobId',j.id,'status','failed'));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_fail_before_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_error_code text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_finalize_reused_scan(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_finalize_reused_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid, p_report_artifact_id uuid, p_result_summary jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_target public.lcia_scope_closure_checks%rowtype;
  v_source public.lcia_scope_closure_checks%rowtype;
  v_execution public.lcia_scope_closure_scan_executions%rowtype;
  v_job public.worker_jobs%rowtype;
  v_report public.worker_job_artifacts%rowtype;
  v_snapshot public.lca_network_snapshots%rowtype;
  v_artifact public.lca_snapshot_artifacts%rowtype;
  v_bundle public.worker_job_artifacts%rowtype;
  v_old_issue public.lcia_scope_closure_issues%rowtype;
  v_new_issue public.lcia_scope_closure_issues%rowtype;
  v_report_hash text;
  v_certificate_hash text;
  v_worker_status text;
  v_worker_record jsonb;
  v_summary jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if jsonb_typeof(coalesce(p_result_summary, 'null'::jsonb)) <> 'object'
     or p_result_summary->>'schemaVersion' is distinct from 'lcia.scope-closure-summary.v1' then
    return public.lcia_scope_closure_error('invalid_closure_result', 400, 'Reused closure result summary must be an object');
  end if;
  select * into v_target from public.lcia_scope_closure_checks where id = p_closure_check_id for update;
  select * into v_source
  from public.lcia_scope_closure_checks
  where id = p_completed_check_id
  for share;
  select * into v_job from public.worker_jobs where id = p_worker_job_id for update;
  select * into v_execution from public.lcia_scope_closure_scan_executions where id = v_target.scan_execution_id for update;
  select * into v_report from public.worker_job_artifacts
  where id = p_report_artifact_id
    and job_id = p_worker_job_id
    and artifact_type = 'closure_report_xlsx';
  if v_target.id is null or v_source.id is null
     or v_target.worker_job_id <> v_job.id
     or v_target.status not in ('queued', 'running')
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at < now()
     or v_execution.id is null
     or v_execution.status <> 'completed'
     or v_execution.completed_check_id <> v_source.id
     or v_report.id is null
     or v_source.status not in ('passed', 'blocked')
     or v_source.scan_completeness <> 'complete'
     or v_source.requested_scope_hash <> v_target.requested_scope_hash
     or v_source.policy_fingerprint <> v_target.policy_fingerprint
     or v_source.data_snapshot_token <> v_target.data_snapshot_token then
    return public.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Reusable scan evidence or new report artifact is invalid');
  end if;
  if coalesce(v_report.metadata->>'closureCheckId', v_target.id::text) <> v_target.id::text then
    return public.lcia_scope_closure_error('closure_report_unavailable', 409, 'New report does not belong to this closure run');
  end if;
  if v_source.status = 'passed' then
    select * into v_snapshot from public.lca_network_snapshots where id = v_source.snapshot_id;
    select * into v_artifact from public.lca_snapshot_artifacts where id = v_source.snapshot_artifact_id;
    select * into v_bundle from public.worker_job_artifacts where id = v_source.closure_bundle_artifact_id;
    if v_source.certificate_status <> 'valid'
       or v_source.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
       or (
         v_source.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
         and not public.lcia_scope_closure_current_release_matches(v_source.data_snapshot_token)
       )
       or v_execution.numerical_snapshot_id is distinct from v_source.snapshot_id
       or v_snapshot.id is null or v_snapshot.status <> 'ready'
       or v_artifact.id is null or v_artifact.snapshot_id <> v_snapshot.id
       or v_artifact.status <> 'ready'
       or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
       or v_artifact.artifact_sha256 <> v_source.snapshot_hash
       or v_artifact.snapshot_index_sha256 <> v_source.snapshot_index_sha256
       or v_artifact.snapshot_build_contract_hash <> v_source.snapshot_build_contract_hash
       or v_artifact.effective_scope_hash <> v_source.effective_scope_hash
       or v_artifact.data_snapshot_token <> v_source.data_snapshot_token
       or v_artifact.closure_bundle_hash <> v_source.closure_bundle_hash
       or v_bundle.id is null
       or v_bundle.job_id <> v_source.worker_job_id
       or v_bundle.artifact_type <> 'closure_bundle'
       or v_bundle.checksum_sha256 <> v_source.closure_bundle_hash
       or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_source.id::text then
      return public.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Source numerical snapshot certificate is not reusable');
    end if;
  end if;

  v_report_hash := public.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if v_source.status = 'passed' then
    v_certificate_hash := public.lcia_scope_closure_sha256(jsonb_build_object(
      'certificateSchemaVersion', 'lcia.scope-closure-certificate.v2',
      'closureCheckId', v_target.id,
      'requestedScopeHash', v_target.requested_scope_hash,
      'effectiveScopeHash', v_source.effective_scope_hash,
      'effectiveScope', v_source.effective_scope_manifest,
      'policyFingerprint', v_target.policy_fingerprint,
      'dataSnapshotToken', v_target.data_snapshot_token,
      'validatorScannerFingerprint', v_target.expected_validator_scanner_fingerprint,
      'sourceFingerprint', v_source.source_fingerprint,
      'resolutionMapHash', v_source.resolution_map_hash,
      'closureBundleArtifactId', v_source.closure_bundle_artifact_id,
      'closureBundleHash', v_source.closure_bundle_hash,
      'snapshotId', v_source.snapshot_id,
      'snapshotHash', v_source.snapshot_hash,
      'snapshotArtifactId', v_source.snapshot_artifact_id,
      'snapshotIndexSha256', v_source.snapshot_index_sha256,
      'snapshotBuildContractHash', v_source.snapshot_build_contract_hash,
      'reportArtifactManifestHash', v_report_hash,
      'evidenceHash', v_source.evidence_hash
    ));
  end if;

  for v_old_issue in
    select * from public.lcia_scope_closure_issues
    where closure_check_id = v_source.id order by id
  loop
    insert into public.lcia_scope_closure_issues(
      closure_check_id, issue_key, severity, blocking, issue_code,
      source_dataset_type, source_dataset_id, source_dataset_version,
      json_path, reference_role, requested_target_type, requested_target_id,
      requested_target_version, message, suggested_action,
      occurrence_count, affected_root_count, details
    ) values (
      v_target.id, v_old_issue.issue_key, v_old_issue.severity,
      v_old_issue.blocking, v_old_issue.issue_code,
      v_old_issue.source_dataset_type, v_old_issue.source_dataset_id,
      v_old_issue.source_dataset_version, v_old_issue.json_path,
      v_old_issue.reference_role, v_old_issue.requested_target_type,
      v_old_issue.requested_target_id, v_old_issue.requested_target_version,
      v_old_issue.message, v_old_issue.suggested_action,
      v_old_issue.occurrence_count, v_old_issue.affected_root_count,
      v_old_issue.details
    ) returning * into v_new_issue;
    insert into public.lcia_scope_closure_issue_occurrences(
      closure_issue_id, occurrence_key, source_dataset_type,
      source_dataset_id, source_dataset_version, json_path, reference_role, details
    ) select
      v_new_issue.id, occurrence_key, source_dataset_type,
      source_dataset_id, source_dataset_version, json_path, reference_role, details
    from public.lcia_scope_closure_issue_occurrences
    where closure_issue_id = v_old_issue.id;
    insert into public.lcia_scope_closure_issue_roots(
      closure_issue_id, root_dataset_type, root_dataset_id,
      root_dataset_version, impact_role, witness_path
    ) select
      v_new_issue.id, root_dataset_type, root_dataset_id,
      root_dataset_version, impact_role, witness_path
    from public.lcia_scope_closure_issue_roots
    where closure_issue_id = v_old_issue.id;
  end loop;

  v_summary := jsonb_strip_nulls(p_result_summary || jsonb_build_object(
    'reusedFromCheckId', v_source.id,
    'reportArtifactId', v_report.id,
    'reportArtifactManifestHash', v_report_hash,
    'evidenceHash', v_source.evidence_hash
  ));
  update public.lcia_scope_closure_checks set
    status = v_source.status,
    scan_completeness = v_source.scan_completeness,
    effective_scope_manifest = v_source.effective_scope_manifest,
    effective_scope_hash = v_source.effective_scope_hash,
    certificate_schema_version = case when v_source.status = 'passed' then 'lcia.scope-closure-certificate.v2' else null end,
    certificate_status = case when v_source.status = 'passed' then 'valid' else 'unavailable' end,
    certificate_hash = v_certificate_hash,
    source_fingerprint = v_source.source_fingerprint,
    resolution_map_hash = v_source.resolution_map_hash,
    closure_bundle_hash = case when v_source.status = 'passed' then v_source.closure_bundle_hash else null end,
    closure_bundle_artifact_id = case when v_source.status = 'passed' then v_source.closure_bundle_artifact_id else null end,
    snapshot_id = case when v_source.status = 'passed' then v_source.snapshot_id else null end,
    snapshot_hash = case when v_source.status = 'passed' then v_source.snapshot_hash else null end,
    snapshot_artifact_id = case when v_source.status = 'passed' then v_source.snapshot_artifact_id else null end,
    snapshot_index_sha256 = case when v_source.status = 'passed' then v_source.snapshot_index_sha256 else null end,
    snapshot_build_contract_hash = case when v_source.status = 'passed' then v_source.snapshot_build_contract_hash else null end,
    report_artifact_manifest_hash = v_report_hash,
    evidence_hash = case when v_source.status = 'passed' then v_source.evidence_hash else null end,
    result_summary = v_summary,
    blocker_codes = v_source.blocker_codes,
    report_artifact_id = v_report.id,
    reused_from_check_id = v_source.id,
    updated_at = now(),
    finished_at = now()
  where id = v_target.id
  returning * into v_target;

  v_worker_status := case when v_target.status = 'passed' then 'completed' else 'blocked' end;
  select public.worker_record_job_result(
    v_job.id, p_lease_token, v_worker_status,
    jsonb_build_object(
      'closureCheckId', v_target.id,
      'status', v_target.status,
      'scanCompleteness', v_target.scan_completeness,
      'certificateStatus', v_target.certificate_status,
      'certificateHash', v_target.certificate_hash,
      'snapshotId', v_target.snapshot_id,
      'snapshotHash', v_target.snapshot_hash,
      'snapshotArtifactId', v_target.snapshot_artifact_id,
      'snapshotIndexSha256', v_target.snapshot_index_sha256,
      'snapshotBuildContractHash', v_target.snapshot_build_contract_hash,
      'evidenceHash', v_target.evidence_hash,
      'reusedFromCheckId', v_source.id
    ),
    'lcia.scope_closure_check.result.v2',
    jsonb_build_object('reportArtifactId', v_report.id, 'reportArtifactManifestHash', v_report_hash),
    jsonb_build_object('progressCounters', coalesce(v_target.result_summary->'progressCounters', '{}'::jsonb)),
    null, null, null,
    case when v_worker_status = 'blocked' then v_target.blocker_codes else null end,
    case when v_worker_status = 'blocked' then 'operator' else null end,
    false
  ) into v_worker_record;
  if coalesce((v_worker_record->>'ok')::boolean, false) is not true then
    raise exception using errcode = 'P0001', message = 'worker_job_result_rejected';
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_target.id,
    'workerJobId', v_job.id,
    'status', v_target.status,
    'scanCompleteness', v_target.scan_completeness,
    'certificateStatus', v_target.certificate_status,
    'certificateHash', v_target.certificate_hash,
    'effectiveScopeHash', v_target.effective_scope_hash,
    'snapshotId', v_target.snapshot_id,
    'snapshotHash', v_target.snapshot_hash,
    'snapshotArtifactId', v_target.snapshot_artifact_id,
    'snapshotIndexSha256', v_target.snapshot_index_sha256,
    'snapshotBuildContractHash', v_target.snapshot_build_contract_hash,
    'evidenceHash', v_target.evidence_hash,
    'reportArtifactId', v_report.id,
    'reusedFromCheckId', v_source.id
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_finalize_reused_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid, p_report_artifact_id uuid, p_result_summary jsonb) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_reuse_completed_scan(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.svc_lcia_scope_closure_reuse_completed_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_target public.lcia_scope_closure_checks%rowtype;
  v_source public.lcia_scope_closure_checks%rowtype;
  v_execution public.lcia_scope_closure_scan_executions%rowtype;
  v_job public.worker_jobs%rowtype;
  v_snapshot public.lca_network_snapshots%rowtype;
  v_artifact public.lca_snapshot_artifacts%rowtype;
  v_bundle public.worker_job_artifacts%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return public.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  select * into v_target from public.lcia_scope_closure_checks where id = p_closure_check_id for update;
  select * into v_source
  from public.lcia_scope_closure_checks
  where id = p_completed_check_id
  for share;
  select * into v_job from public.worker_jobs where id = p_worker_job_id for update;
  if v_target.id is null or v_source.id is null
     or v_target.worker_job_id <> p_worker_job_id
     or v_target.status not in ('queued', 'running') then
    return public.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if v_job.status <> 'running'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at < now() then
    return public.lcia_scope_closure_error('worker_job_lease_invalid', 409, 'Worker job lease is no longer valid');
  end if;
  select * into v_execution
  from public.lcia_scope_closure_scan_executions
  where id = v_target.scan_execution_id
  for update;
  if v_execution.id is null
     or v_execution.status <> 'completed'
     or v_execution.completed_check_id <> v_source.id
     or v_execution.numerical_snapshot_id is distinct from v_source.snapshot_id
     or v_source.status not in ('passed', 'blocked')
     or v_source.scan_completeness <> 'complete'
     or v_source.requested_scope_hash <> v_target.requested_scope_hash
     or v_source.policy_fingerprint <> v_target.policy_fingerprint
     or v_source.data_snapshot_token <> v_target.data_snapshot_token then
    return public.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Completed scan evidence does not match this closure run');
  end if;
  if v_source.status = 'passed' then
    select * into v_snapshot from public.lca_network_snapshots where id = v_source.snapshot_id;
    select * into v_artifact from public.lca_snapshot_artifacts where id = v_source.snapshot_artifact_id;
    select * into v_bundle from public.worker_job_artifacts where id = v_source.closure_bundle_artifact_id;
    if v_source.certificate_status <> 'valid'
       or v_source.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
       or (
         v_source.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
         and not public.lcia_scope_closure_current_release_matches(v_source.data_snapshot_token)
       )
       or v_snapshot.id is null
       or v_snapshot.status <> 'ready'
       or v_artifact.id is null
       or v_artifact.snapshot_id <> v_snapshot.id
       or v_artifact.status <> 'ready'
       or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
       or v_artifact.artifact_sha256 <> v_source.snapshot_hash
       or v_artifact.snapshot_index_sha256 <> v_source.snapshot_index_sha256
       or v_artifact.snapshot_build_contract_hash <> v_source.snapshot_build_contract_hash
       or v_artifact.effective_scope_hash <> v_source.effective_scope_hash
       or v_artifact.data_snapshot_token <> v_source.data_snapshot_token
       or v_artifact.closure_bundle_hash <> v_source.closure_bundle_hash
       or v_bundle.id is null
       or v_bundle.job_id <> v_source.worker_job_id
       or v_bundle.artifact_type <> 'closure_bundle'
       or v_bundle.checksum_sha256 <> v_source.closure_bundle_hash
       or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_source.id::text then
      return public.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Source numerical snapshot certificate is not reusable');
    end if;
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'reuseAvailable', true,
    'closureCheckId', v_target.id,
    'workerJobId', v_job.id,
    'completedCheckId', v_source.id,
    'status', v_source.status,
    'scanCompleteness', v_source.scan_completeness,
    'evidence', jsonb_strip_nulls(jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-evidence.v2',
      'sourceFingerprint', v_source.source_fingerprint,
      'resolutionMapHash', v_source.resolution_map_hash,
      'closureBundleHash', v_source.closure_bundle_hash,
      'closureBundleArtifactId', v_source.closure_bundle_artifact_id,
      'snapshotId', v_source.snapshot_id,
      'snapshotHash', v_source.snapshot_hash,
      'snapshotArtifactId', v_source.snapshot_artifact_id,
      'snapshotIndexSha256', v_source.snapshot_index_sha256,
      'snapshotBuildContractHash', v_source.snapshot_build_contract_hash,
      'evidenceHash', v_source.evidence_hash
    )),
    'blockerCodes', to_jsonb(v_source.blocker_codes)
  ));
end;
$$;


ALTER FUNCTION public.svc_lcia_scope_closure_reuse_completed_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid) OWNER TO postgres;

--
-- Name: sync_auth_users_to_public_users(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_auth_users_to_public_users() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- 处理插入操作
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.users (id, raw_user_meta_data)
        VALUES (NEW.id, NEW.raw_user_meta_data);
    -- 处理更新操作
    ELSIF TG_OP = 'UPDATE' THEN
		IF NEW.raw_user_meta_data != OLD.raw_user_meta_data THEN
			UPDATE public.users
			SET raw_user_meta_data = NEW.raw_user_meta_data
			WHERE id = NEW.id;
    	END IF;
    -- 处理删除操作
    ELSIF TG_OP = 'DELETE' THEN
        DELETE FROM public.users
        WHERE id = OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_auth_users_to_public_users() OWNER TO postgres;

--
-- Name: sync_json_to_jsonb(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_json_to_jsonb() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$BEGIN
    IF NEW.json_ordered::jsonb IS DISTINCT FROM OLD.json_ordered::jsonb
    THEN
        NEW.json := NEW.json_ordered;
    END IF;
    RETURN NEW;
END;$$;


ALTER FUNCTION public.sync_json_to_jsonb() OWNER TO postgres;

--
-- Name: unitgroups; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.unitgroups (
    id uuid NOT NULL,
    "json" jsonb,
    created_at timestamp with time zone DEFAULT now(),
    json_ordered json,
    user_id uuid DEFAULT auth.uid(),
    state_code integer DEFAULT 0,
    version character(9) NOT NULL,
    modified_at timestamp with time zone DEFAULT now(),
    team_id uuid,
    review_id uuid,
    rule_verification boolean,
    reviews jsonb,
    extracted_md text,
    embedding_ft_at timestamp with time zone,
    embedding_ft extensions.vector(1024),
    CONSTRAINT unitgroups_state_code_check CHECK ((state_code = ANY (ARRAY[0, 20, 100, 200])))
);


ALTER TABLE public.unitgroups OWNER TO postgres;

--
-- Name: unitgroups_embedding_ft_input(public.unitgroups); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unitgroups_embedding_ft_input(proc public.unitgroups) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select proc.extracted_md;
$$;


ALTER FUNCTION public.unitgroups_embedding_ft_input(proc public.unitgroups) OWNER TO postgres;

--
-- Name: unitgroups_sync_jsonb_version(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unitgroups_sync_jsonb_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.json_ordered::jsonb IS DISTINCT FROM OLD.json_ordered::jsonb THEN
        NEW.json := NEW.json_ordered;
        NEW.version :=  COALESCE(NEW.json->'unitGroupDataSet'->'administrativeInformation'->'publicationAndOwnership'->>'common:dataSetVersion'
		,
					''
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.unitgroups_sync_jsonb_version() OWNER TO postgres;

--
-- Name: update_modified_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_modified_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.modified_at = now();
  return new;
end;
$$;


ALTER FUNCTION public.update_modified_at() OWNER TO postgres;

--
-- Name: worker_cancel_job(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_cancel_job(p_job_id uuid, p_cancelled_by uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to cancel worker jobs'
    );
  end if;

  select *
    into v_job
  from public.worker_jobs
  where id = p_job_id
  for update;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Worker job not found'
    );
  end if;

  if v_job.status in ('completed', 'blocked', 'failed') then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_TERMINAL',
      'status', 409,
      'message', 'Completed, blocked, and failed worker jobs cannot be cancelled'
    );
  end if;

  if v_job.status = 'cancelled' then
    return jsonb_build_object(
      'ok', true,
      'data', public.worker_job_payload(v_job, true)
    );
  end if;

  update public.worker_jobs
    set status = 'cancelled',
        cancelled_at = now(),
        cancelled_by = p_cancelled_by,
        leased_by = null,
        lease_token = null,
        lease_expires_at = null,
        error_code = 'worker_job_cancelled',
        error_message = coalesce(nullif(trim(p_reason), ''), 'Worker job was cancelled'),
        updated_at = now(),
        finished_at = now()
  where id = v_job.id
  returning *
    into v_job;

  insert into public.worker_job_events (
    job_id,
    event_type,
    status,
    message,
    details
  ) values (
    v_job.id,
    'cancelled',
    v_job.status,
    p_reason,
    jsonb_build_object('cancelledBy', p_cancelled_by)
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_job, true)
  );
end;
$$;


ALTER FUNCTION public.worker_cancel_job(p_job_id uuid, p_cancelled_by uuid, p_reason text) OWNER TO postgres;

--
-- Name: worker_claim_jobs(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_claim_jobs(p_worker_queue text, p_worker_id text DEFAULT NULL::text, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_worker_queue text := lower(trim(coalesce(p_worker_queue, '')));
  v_worker_id text := nullif(trim(p_worker_id), '');
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 50));
  v_lease_seconds integer := greatest(1, least(coalesce(p_lease_seconds, 300), 86400));
  v_jobs jsonb := '[]'::jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to claim worker jobs'
    );
  end if;

  if v_worker_queue not in ('solver', 'review_submit', 'review_submit_gate', 'package', 'maintenance') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_QUEUE',
      'status', 400,
      'message', 'workerQueue must be solver, review_submit, review_submit_gate, package, or maintenance'
    );
  end if;

  with expired as (
    update public.worker_jobs as j
      set status = 'failed',
          error_code = coalesce(j.error_code, 'lease_expired_max_attempts'),
          error_message = coalesce(j.error_message, 'Worker job lease expired after the maximum attempt count'),
          error_details = coalesce(j.error_details, '{}'::jsonb) || jsonb_build_object(
            'leasedBy', j.leased_by,
            'leaseExpiresAt', j.lease_expires_at,
            'attemptCount', j.attempt_count,
            'maxAttempts', j.max_attempts
          ),
          leased_by = null,
          lease_token = null,
          lease_expires_at = null,
          heartbeat_at = coalesce(j.heartbeat_at, now()),
          updated_at = now(),
          finished_at = now()
    where j.worker_runtime = 'calculator'
      and j.worker_queue = v_worker_queue
      and j.status = 'running'
      and j.lease_expires_at < now()
      and j.attempt_count >= j.max_attempts
    returning j.*
  ),
  expired_events as (
    insert into public.worker_job_events (
      job_id,
      event_type,
      status,
      worker_id,
      message,
      details
    )
    select
      expired.id,
      'failed',
      expired.status,
      expired.leased_by,
      'Worker job lease expired after the maximum attempt count',
      jsonb_build_object(
        'errorCode', expired.error_code,
        'attemptCount', expired.attempt_count,
        'maxAttempts', expired.max_attempts
      )
    from expired
    returning id
  ),
  candidate as (
    select id
    from public.worker_jobs
    where worker_runtime = 'calculator'
      and worker_queue = v_worker_queue
      and run_after <= now()
      and attempt_count < max_attempts
      and (
        status in ('queued', 'stale')
        or (status = 'running' and lease_expires_at < now())
      )
    order by priority desc, run_after asc, created_at asc
    limit v_limit
    for update skip locked
  ),
  updated as (
    update public.worker_jobs as j
      set status = 'running',
          attempt_count = j.attempt_count + 1,
          leased_by = v_worker_id,
          lease_token = gen_random_uuid(),
          lease_expires_at = now() + make_interval(secs => v_lease_seconds),
          heartbeat_at = now(),
          started_at = coalesce(j.started_at, now()),
          updated_at = now(),
          error_code = null,
          error_message = null,
          error_details = null
    from candidate
    where j.id = candidate.id
    returning j.*
  ),
  claim_events as (
    insert into public.worker_job_events (
      job_id,
      event_type,
      status,
      phase,
      progress,
      worker_id,
      lease_token,
      details
    )
    select
      updated.id,
      'claimed',
      updated.status,
      updated.phase,
      updated.progress,
      updated.leased_by,
      updated.lease_token,
      jsonb_build_object(
        'attemptCount', updated.attempt_count,
        'leaseExpiresAt', updated.lease_expires_at
      )
    from updated
    returning id
  )
  select coalesce(jsonb_agg(public.worker_job_payload(updated, true)), '[]'::jsonb)
    into v_jobs
  from updated;

  return jsonb_build_object(
    'ok', true,
    'data', v_jobs
  );
end;
$$;


ALTER FUNCTION public.worker_claim_jobs(p_worker_queue text, p_worker_id text, p_limit integer, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: worker_enqueue_job(text, jsonb, text, text, uuid, text, uuid, text, uuid, text, text, text, integer, text, timestamp with time zone, text, integer, timestamp with time zone, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_enqueue_job(p_job_kind text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_payload_schema_version text DEFAULT NULL::text, p_subject_type text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_subject_version text DEFAULT NULL::text, p_requested_by uuid DEFAULT NULL::uuid, p_requester_type text DEFAULT 'user'::text, p_team_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_request_hash text DEFAULT NULL::text, p_concurrency_key text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_queue_key text DEFAULT NULL::text, p_run_after timestamp with time zone DEFAULT NULL::timestamp with time zone, p_visibility text DEFAULT NULL::text, p_max_attempts integer DEFAULT NULL::integer, p_timeout_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_payload_ref jsonb DEFAULT NULL::jsonb, p_parent_job_id uuid DEFAULT NULL::uuid, p_root_job_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job_kind text := lower(trim(coalesce(p_job_kind, '')));
  v_requester_type text := lower(trim(coalesce(p_requester_type, 'user')));
  v_kind public.worker_job_kinds%rowtype;
  v_existing public.worker_jobs%rowtype;
  v_job public.worker_jobs%rowtype;
  v_payload jsonb := coalesce(p_payload_json, '{}'::jsonb);
  v_payload_ref jsonb := p_payload_ref;
  v_visibility text;
  v_payload_schema_version text;
  v_priority integer;
  v_max_attempts integer;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to enqueue worker jobs'
    );
  end if;

  select *
    into v_kind
  from public.worker_job_kinds
  where job_kind = v_job_kind;

  if v_kind.job_kind is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_KIND_UNSUPPORTED',
      'status', 400,
      'message', 'Unsupported worker job kind'
    );
  end if;

  if jsonb_typeof(v_payload) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_PAYLOAD',
      'status', 400,
      'message', 'worker job payload must be a JSON object'
    );
  end if;

  if v_payload_ref is not null and jsonb_typeof(v_payload_ref) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_PAYLOAD_REF',
      'status', 400,
      'message', 'worker job payloadRef must be a JSON object'
    );
  end if;

  if v_requester_type not in ('user', 'system', 'service', 'operator') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_REQUESTER_TYPE',
      'status', 400,
      'message', 'requesterType must be user, system, service, or operator'
    );
  end if;

  if v_requester_type = 'user' and p_requested_by is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_REQUESTED_BY_REQUIRED',
      'status', 400,
      'message', 'requestedBy is required for user-requested worker jobs'
    );
  end if;

  v_visibility := lower(trim(coalesce(p_visibility, v_kind.default_visibility)));
  if v_visibility not in ('user', 'operator', 'system') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_VISIBILITY',
      'status', 400,
      'message', 'visibility must be user, operator, or system'
    );
  end if;

  v_payload_schema_version := coalesce(nullif(trim(p_payload_schema_version), ''), v_kind.payload_schema_version);
  v_priority := coalesce(p_priority, v_kind.default_priority);
  v_max_attempts := greatest(1, coalesce(p_max_attempts, v_kind.default_max_attempts, 3));

  if p_idempotency_key is not null then
    select *
      into v_existing
    from public.worker_jobs
    where worker_runtime = v_kind.worker_runtime
      and job_kind = v_kind.job_kind
      and requested_by is not distinct from p_requested_by
      and idempotency_key = p_idempotency_key
      and status in ('queued', 'running', 'waiting', 'stale', 'blocked')
    order by created_at desc
    limit 1;

    if v_existing.id is not null then
      return jsonb_build_object(
        'ok', true,
        'data', public.worker_job_payload(v_existing, true),
        'reused', true
      );
    end if;
  end if;

  if p_concurrency_key is not null then
    select *
      into v_existing
    from public.worker_jobs
    where worker_runtime = v_kind.worker_runtime
      and worker_queue = v_kind.worker_queue
      and concurrency_key = p_concurrency_key
      and status in ('queued', 'running', 'waiting', 'stale')
    order by created_at desc
    limit 1;

    if v_existing.id is not null then
      return jsonb_build_object(
        'ok', false,
        'code', 'WORKER_JOB_CONCURRENCY_CONFLICT',
        'status', 409,
        'message', 'A conflicting worker job is already active',
        'details', public.worker_job_payload(v_existing, false)
      );
    end if;
  end if;

  insert into public.worker_jobs (
    job_kind,
    worker_runtime,
    worker_queue,
    priority,
    queue_key,
    root_job_id,
    parent_job_id,
    subject_type,
    subject_id,
    subject_version,
    requester_type,
    requested_by,
    team_id,
    idempotency_key,
    request_hash,
    concurrency_key,
    visibility,
    run_after,
    max_attempts,
    timeout_at,
    payload_schema_version,
    payload_json,
    payload_ref,
    result_schema_version
  ) values (
    v_kind.job_kind,
    v_kind.worker_runtime,
    v_kind.worker_queue,
    v_priority,
    nullif(trim(p_queue_key), ''),
    p_root_job_id,
    p_parent_job_id,
    nullif(trim(p_subject_type), ''),
    p_subject_id,
    nullif(trim(p_subject_version), ''),
    v_requester_type,
    p_requested_by,
    p_team_id,
    nullif(trim(p_idempotency_key), ''),
    nullif(trim(p_request_hash), ''),
    nullif(trim(p_concurrency_key), ''),
    v_visibility,
    coalesce(p_run_after, now()),
    v_max_attempts,
    p_timeout_at,
    v_payload_schema_version,
    v_payload,
    v_payload_ref,
    v_kind.result_schema_version
  )
  returning *
    into v_job;

  insert into public.worker_job_events (
    job_id,
    event_type,
    status,
    details
  ) values (
    v_job.id,
    'enqueued',
    v_job.status,
    jsonb_build_object(
      'jobKind', v_job.job_kind,
      'workerQueue', v_job.worker_queue,
      'idempotencyKey', v_job.idempotency_key,
      'concurrencyKey', v_job.concurrency_key
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_job, true),
    'reused', false
  );
exception
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_UNIQUE_CONFLICT',
      'status', 409,
      'message', 'A worker job with the same idempotency or concurrency key already exists'
    );
end;
$$;


ALTER FUNCTION public.worker_enqueue_job(p_job_kind text, p_payload_json jsonb, p_payload_schema_version text, p_subject_type text, p_subject_id uuid, p_subject_version text, p_requested_by uuid, p_requester_type text, p_team_id uuid, p_idempotency_key text, p_request_hash text, p_concurrency_key text, p_priority integer, p_queue_key text, p_run_after timestamp with time zone, p_visibility text, p_max_attempts integer, p_timeout_at timestamp with time zone, p_payload_ref jsonb, p_parent_job_id uuid, p_root_job_id uuid) OWNER TO postgres;

--
-- Name: worker_heartbeat_job(uuid, uuid, text, numeric, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_heartbeat_job(p_job_id uuid, p_lease_token uuid, p_phase text DEFAULT NULL::text, p_progress numeric DEFAULT NULL::numeric, p_diagnostics jsonb DEFAULT NULL::jsonb, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
  v_lease_seconds integer := greatest(1, least(coalesce(p_lease_seconds, 300), 86400));
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to heartbeat worker jobs'
    );
  end if;

  if p_progress is not null and (p_progress < 0 or p_progress > 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_PROGRESS',
      'status', 400,
      'message', 'progress must be between 0 and 1'
    );
  end if;

  if p_diagnostics is not null and jsonb_typeof(p_diagnostics) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_DIAGNOSTICS',
      'status', 400,
      'message', 'diagnostics must be a JSON object'
    );
  end if;

  select *
    into v_job
  from public.worker_jobs
  where id = p_job_id
  for update;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Worker job not found'
    );
  end if;

  if v_job.status <> 'running' then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_RUNNING',
      'status', 409,
      'message', 'Worker job is not running'
    );
  end if;

  if v_job.lease_token is distinct from p_lease_token then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_LEASE_TOKEN_MISMATCH',
      'status', 409,
      'message', 'Worker job lease token does not match'
    );
  end if;

  if v_job.lease_expires_at < now() then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_LEASE_EXPIRED',
      'status', 409,
      'message', 'Worker job lease has expired'
    );
  end if;

  update public.worker_jobs
    set phase = coalesce(nullif(trim(p_phase), ''), phase),
        progress = coalesce(p_progress, progress),
        diagnostics = diagnostics || coalesce(p_diagnostics, '{}'::jsonb),
        heartbeat_at = now(),
        lease_expires_at = now() + make_interval(secs => v_lease_seconds),
        updated_at = now()
  where id = v_job.id
  returning *
    into v_job;

  insert into public.worker_job_events (
    job_id,
    event_type,
    status,
    phase,
    progress,
    worker_id,
    lease_token,
    details
  ) values (
    v_job.id,
    'heartbeat',
    v_job.status,
    v_job.phase,
    v_job.progress,
    v_job.leased_by,
    v_job.lease_token,
    jsonb_build_object(
      'leaseExpiresAt', v_job.lease_expires_at,
      'diagnostics', coalesce(p_diagnostics, '{}'::jsonb)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_job, true)
  );
end;
$$;


ALTER FUNCTION public.worker_heartbeat_job(p_job_id uuid, p_lease_token uuid, p_phase text, p_progress numeric, p_diagnostics jsonb, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: worker_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.worker_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_kind text NOT NULL,
    worker_runtime text DEFAULT 'calculator'::text NOT NULL,
    worker_queue text NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    queue_key text,
    root_job_id uuid,
    parent_job_id uuid,
    subject_type text,
    subject_id uuid,
    subject_version text,
    requester_type text DEFAULT 'user'::text NOT NULL,
    requested_by uuid,
    team_id uuid,
    idempotency_key text,
    request_hash text,
    concurrency_key text,
    status text DEFAULT 'queued'::text NOT NULL,
    phase text,
    progress numeric,
    visibility text DEFAULT 'user'::text NOT NULL,
    run_after timestamp with time zone DEFAULT now() NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    leased_by text,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    timeout_at timestamp with time zone,
    payload_schema_version text NOT NULL,
    payload_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_ref jsonb,
    result_schema_version text,
    result_json jsonb,
    result_ref jsonb,
    diagnostics jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_code text,
    error_message text,
    error_details jsonb,
    blocker_codes text[] DEFAULT '{}'::text[] NOT NULL,
    resolution_scope text,
    retryable boolean,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    expires_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    CONSTRAINT worker_jobs_attempt_check CHECK (((attempt_count >= 0) AND (max_attempts >= 0) AND (attempt_count <= max_attempts))),
    CONSTRAINT worker_jobs_blocked_explanation_check CHECK (((status <> 'blocked'::text) OR ((cardinality(blocker_codes) > 0) AND (resolution_scope IS NOT NULL)))),
    CONSTRAINT worker_jobs_diagnostics_object_check CHECK ((jsonb_typeof(diagnostics) = 'object'::text)),
    CONSTRAINT worker_jobs_error_details_object_check CHECK (((error_details IS NULL) OR (jsonb_typeof(error_details) = 'object'::text))),
    CONSTRAINT worker_jobs_payload_object_check CHECK ((jsonb_typeof(payload_json) = 'object'::text)),
    CONSTRAINT worker_jobs_payload_ref_object_check CHECK (((payload_ref IS NULL) OR (jsonb_typeof(payload_ref) = 'object'::text))),
    CONSTRAINT worker_jobs_progress_check CHECK (((progress IS NULL) OR ((progress >= (0)::numeric) AND (progress <= (1)::numeric)))),
    CONSTRAINT worker_jobs_queue_check CHECK ((worker_queue = ANY (ARRAY['solver'::text, 'review_submit'::text, 'review_submit_gate'::text, 'package'::text, 'maintenance'::text]))),
    CONSTRAINT worker_jobs_requester_check CHECK ((((requester_type = 'user'::text) AND (requested_by IS NOT NULL)) OR (requester_type = ANY (ARRAY['system'::text, 'service'::text, 'operator'::text])))),
    CONSTRAINT worker_jobs_resolution_scope_check CHECK (((resolution_scope IS NULL) OR (resolution_scope = ANY (ARRAY['user'::text, 'operator'::text, 'system'::text])))),
    CONSTRAINT worker_jobs_result_object_check CHECK (((result_json IS NULL) OR (jsonb_typeof(result_json) = 'object'::text))),
    CONSTRAINT worker_jobs_result_ref_object_check CHECK (((result_ref IS NULL) OR (jsonb_typeof(result_ref) = 'object'::text))),
    CONSTRAINT worker_jobs_runtime_check CHECK ((worker_runtime = 'calculator'::text)),
    CONSTRAINT worker_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting'::text, 'completed'::text, 'blocked'::text, 'stale'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT worker_jobs_visibility_check CHECK ((visibility = ANY (ARRAY['user'::text, 'operator'::text, 'system'::text])))
);


ALTER TABLE public.worker_jobs OWNER TO postgres;

--
-- Name: TABLE worker_jobs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.worker_jobs IS 'Canonical task fact table for work executed or coordinated by tiangong-lca-worker. Legacy job tables may remain only as domain artifact/cache/history compatibility surfaces.';


--
-- Name: COLUMN worker_jobs.worker_runtime; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.worker_runtime IS 'Compatibility runtime discriminator; calculator is the existing compute-runtime key, not the repository identity.';


--
-- Name: COLUMN worker_jobs.root_job_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.root_job_id IS 'Optional root worker job for multi-step flows such as review_submit.submit -> review_submit.gate.';


--
-- Name: COLUMN worker_jobs.parent_job_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.parent_job_id IS 'Immediate parent worker job for child execution records.';


--
-- Name: COLUMN worker_jobs.subject_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.subject_type IS 'Domain subject table or logical entity name used for latest/read/list projections.';


--
-- Name: COLUMN worker_jobs.subject_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.subject_id IS 'Domain subject UUID used with subject_type and subject_version.';


--
-- Name: COLUMN worker_jobs.subject_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.subject_version IS 'Domain subject version used with subject_type and subject_id.';


--
-- Name: COLUMN worker_jobs.payload_ref; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.payload_ref IS 'Internal reference to request payload artifacts or legacy compatibility rows. Exposed only through internal worker projections.';


--
-- Name: COLUMN worker_jobs.result_ref; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.worker_jobs.result_ref IS 'Internal reference to result/artifact/cache rows. Exposed only through internal worker projections.';


--
-- Name: worker_job_payload(public.worker_jobs, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_job_payload(p_job public.worker_jobs, p_include_internal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    jsonb_object_agg(entry.key, entry.value)
      filter (where entry.value <> 'null'::jsonb),
    '{}'::jsonb
  )
  from jsonb_each(
    jsonb_build_object(
      'id', (p_job).id,
      'jobKind', (p_job).job_kind,
      'workerRuntime', (p_job).worker_runtime,
      'workerQueue', (p_job).worker_queue,
      'priority', (p_job).priority,
      'queueKey', (p_job).queue_key,
      'rootJobId', (p_job).root_job_id,
      'parentJobId', (p_job).parent_job_id,
      'subjectType', (p_job).subject_type,
      'subjectId', (p_job).subject_id,
      'subjectVersion', (p_job).subject_version,
      'requesterType', (p_job).requester_type,
      'requestedBy', (p_job).requested_by,
      'teamId', (p_job).team_id,
      'idempotencyKey', (p_job).idempotency_key,
      'requestHash', (p_job).request_hash,
      'concurrencyKey', (p_job).concurrency_key,
      'status', (p_job).status,
      'phase', (p_job).phase,
      'progress', (p_job).progress,
      'visibility', (p_job).visibility,
      'runAfter', to_jsonb((p_job).run_after),
      'attemptCount', (p_job).attempt_count,
      'maxAttempts', (p_job).max_attempts,
      'leasedBy', case when p_include_internal then (p_job).leased_by else null end,
      'leaseToken', case when p_include_internal then (p_job).lease_token else null end,
      'leaseExpiresAt', case when p_include_internal then to_jsonb((p_job).lease_expires_at) else null end,
      'heartbeatAt', to_jsonb((p_job).heartbeat_at),
      'timeoutAt', to_jsonb((p_job).timeout_at),
      'payloadSchemaVersion', (p_job).payload_schema_version,
      'payload', case when p_include_internal then (p_job).payload_json else null end,
      'payloadRef', case when p_include_internal then (p_job).payload_ref else null end,
      'resultSchemaVersion', (p_job).result_schema_version,
      'result', (p_job).result_json,
      'resultRef', case when p_include_internal then (p_job).result_ref else null end,
      'diagnostics', case when p_include_internal then (p_job).diagnostics else null end,
      'errorCode', (p_job).error_code,
      'errorMessage', (p_job).error_message,
      'errorDetails', case when p_include_internal then (p_job).error_details else null end,
      'blockerCodes', to_jsonb((p_job).blocker_codes),
      'resolutionScope', (p_job).resolution_scope,
      'retryable', (p_job).retryable,
      'createdAt', to_jsonb((p_job).created_at),
      'updatedAt', to_jsonb((p_job).updated_at),
      'startedAt', to_jsonb((p_job).started_at),
      'finishedAt', to_jsonb((p_job).finished_at),
      'expiresAt', to_jsonb((p_job).expires_at),
      'cancelledAt', to_jsonb((p_job).cancelled_at),
      'cancelledBy', (p_job).cancelled_by
    )
  ) as entry(key, value)
$$;


ALTER FUNCTION public.worker_job_payload(p_job public.worker_jobs, p_include_internal boolean) OWNER TO postgres;

--
-- Name: worker_list_jobs(uuid, text, uuid, text[], text, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_list_jobs(p_requested_by uuid DEFAULT NULL::uuid, p_subject_type text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_statuses text[] DEFAULT NULL::text[], p_visibility text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_include_internal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 200));
  v_jobs jsonb := '[]'::jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to list worker jobs'
    );
  end if;

  if p_visibility is not null and p_visibility not in ('user', 'operator', 'system') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_VISIBILITY',
      'status', 400,
      'message', 'visibility must be user, operator, or system'
    );
  end if;

  select coalesce(jsonb_agg(public.worker_job_payload(j, p_include_internal) order by j.updated_at desc), '[]'::jsonb)
    into v_jobs
  from (
    select *
    from public.worker_jobs
    where (p_requested_by is null or requested_by = p_requested_by)
      and (p_subject_type is null or subject_type = p_subject_type)
      and (p_subject_id is null or subject_id = p_subject_id)
      and (p_visibility is null or visibility = p_visibility)
      and (p_statuses is null or status = any(p_statuses))
    order by updated_at desc
    limit v_limit
  ) as j;

  return jsonb_build_object(
    'ok', true,
    'data', v_jobs
  );
end;
$$;


ALTER FUNCTION public.worker_list_jobs(p_requested_by uuid, p_subject_type text, p_subject_id uuid, p_statuses text[], p_visibility text, p_limit integer, p_include_internal boolean) OWNER TO postgres;

--
-- Name: worker_read_job(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_read_job(p_job_id uuid, p_include_internal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to read worker jobs'
    );
  end if;

  select *
    into v_job
  from public.worker_jobs
  where id = p_job_id;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Worker job not found'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_job, p_include_internal)
  );
end;
$$;


ALTER FUNCTION public.worker_read_job(p_job_id uuid, p_include_internal boolean) OWNER TO postgres;

--
-- Name: worker_read_latest_job(uuid, text, uuid, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_read_latest_job(p_requested_by uuid DEFAULT NULL::uuid, p_subject_type text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_subject_version text DEFAULT NULL::text, p_job_kind text DEFAULT NULL::text, p_statuses text[] DEFAULT NULL::text[], p_include_internal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_subject_type text := nullif(trim(p_subject_type), '');
  v_subject_version text := nullif(trim(p_subject_version), '');
  v_job_kind text := nullif(lower(trim(p_job_kind)), '');
  v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to read worker jobs'
    );
  end if;

  if p_statuses is not null
    and exists (
      select 1
      from unnest(p_statuses) as status_value
      where status_value not in (
        'queued',
        'running',
        'waiting',
        'completed',
        'blocked',
        'stale',
        'failed',
        'cancelled'
      )
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_STATUS',
      'status', 400,
      'message', 'statuses contains an unsupported worker job status'
    );
  end if;

  select *
    into v_job
  from public.worker_jobs
  where (p_requested_by is null or requested_by = p_requested_by)
    and (v_subject_type is null or subject_type = v_subject_type)
    and (p_subject_id is null or subject_id = p_subject_id)
    and (v_subject_version is null or subject_version = v_subject_version)
    and (v_job_kind is null or job_kind = v_job_kind)
    and (p_statuses is null or status = any(p_statuses))
  order by updated_at desc, created_at desc
  limit 1;

  return jsonb_build_object(
    'ok', true,
    'data', case
      when v_job.id is null then null
      else public.worker_job_payload(v_job, p_include_internal)
    end
  );
end;
$$;


ALTER FUNCTION public.worker_read_latest_job(p_requested_by uuid, p_subject_type text, p_subject_id uuid, p_subject_version text, p_job_kind text, p_statuses text[], p_include_internal boolean) OWNER TO postgres;

--
-- Name: worker_record_job_result(uuid, uuid, text, jsonb, text, jsonb, jsonb, text, text, jsonb, text[], text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_record_job_result(p_job_id uuid, p_lease_token uuid, p_status text, p_result_json jsonb DEFAULT NULL::jsonb, p_result_schema_version text DEFAULT NULL::text, p_result_ref jsonb DEFAULT NULL::jsonb, p_diagnostics jsonb DEFAULT NULL::jsonb, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_error_details jsonb DEFAULT NULL::jsonb, p_blocker_codes text[] DEFAULT NULL::text[], p_resolution_scope text DEFAULT NULL::text, p_retryable boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text := lower(trim(coalesce(p_status, '')));
  v_resolution_scope text := lower(trim(coalesce(p_resolution_scope, '')));
  v_blocker_codes text[] := coalesce(p_blocker_codes, '{}'::text[]);
  v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to record worker job results'
    );
  end if;

  if v_status not in ('completed', 'blocked', 'failed', 'waiting') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_RESULT_STATUS',
      'status', 400,
      'message', 'status must be completed, blocked, failed, or waiting'
    );
  end if;

  if p_result_json is not null and jsonb_typeof(p_result_json) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_RESULT',
      'status', 400,
      'message', 'result must be a JSON object'
    );
  end if;

  if p_result_ref is not null and jsonb_typeof(p_result_ref) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_RESULT_REF',
      'status', 400,
      'message', 'resultRef must be a JSON object'
    );
  end if;

  if p_diagnostics is not null and jsonb_typeof(p_diagnostics) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_DIAGNOSTICS',
      'status', 400,
      'message', 'diagnostics must be a JSON object'
    );
  end if;

  if p_error_details is not null and jsonb_typeof(p_error_details) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_ERROR_DETAILS',
      'status', 400,
      'message', 'error details must be a JSON object'
    );
  end if;

  if v_status = 'blocked' and (cardinality(v_blocker_codes) = 0 or v_resolution_scope = '') then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_BLOCKER_DETAILS_REQUIRED',
      'status', 400,
      'message', 'blocked worker jobs require blockerCodes and resolutionScope'
    );
  end if;

  if v_status = 'blocked' and v_resolution_scope not in ('user', 'operator', 'system') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WORKER_JOB_RESOLUTION_SCOPE',
      'status', 400,
      'message', 'resolutionScope must be user, operator, or system'
    );
  end if;

  if v_status = 'failed' and nullif(trim(p_error_code), '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_ERROR_CODE_REQUIRED',
      'status', 400,
      'message', 'failed worker jobs require an errorCode'
    );
  end if;

  select *
    into v_job
  from public.worker_jobs
  where id = p_job_id
  for update;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Worker job not found'
    );
  end if;

  if v_job.status <> 'running' then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_RUNNING',
      'status', 409,
      'message', 'Worker job is not running'
    );
  end if;

  if v_job.lease_token is distinct from p_lease_token then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_LEASE_TOKEN_MISMATCH',
      'status', 409,
      'message', 'Worker job lease token does not match'
    );
  end if;

  if v_job.lease_expires_at < now() then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_LEASE_EXPIRED',
      'status', 409,
      'message', 'Worker job lease has expired'
    );
  end if;

  update public.worker_jobs
    set status = v_status,
        result_schema_version = coalesce(nullif(trim(p_result_schema_version), ''), result_schema_version),
        result_json = p_result_json,
        result_ref = p_result_ref,
        diagnostics = diagnostics || coalesce(p_diagnostics, '{}'::jsonb),
        error_code = nullif(trim(p_error_code), ''),
        error_message = nullif(trim(p_error_message), ''),
        error_details = p_error_details,
        blocker_codes = case
          when v_status = 'blocked' then v_blocker_codes
          else '{}'::text[]
        end,
        resolution_scope = case
          when v_status = 'blocked' then v_resolution_scope
          else null
        end,
        retryable = p_retryable,
        leased_by = null,
        lease_token = null,
        lease_expires_at = null,
        heartbeat_at = coalesce(heartbeat_at, now()),
        updated_at = now(),
        finished_at = case
          when v_status in ('completed', 'blocked', 'failed') then now()
          else null
        end
  where id = v_job.id
  returning *
    into v_job;

  insert into public.worker_job_events (
    job_id,
    event_type,
    status,
    phase,
    progress,
    worker_id,
    lease_token,
    message,
    details
  ) values (
    v_job.id,
    v_status,
    v_job.status,
    v_job.phase,
    v_job.progress,
    null,
    p_lease_token,
    coalesce(p_error_message, null),
    jsonb_strip_nulls(
      jsonb_build_object(
        'errorCode', v_job.error_code,
        'blockerCodes', to_jsonb(v_job.blocker_codes),
        'resolutionScope', v_job.resolution_scope,
        'retryable', v_job.retryable
      )
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_job, true)
  );
end;
$$;


ALTER FUNCTION public.worker_record_job_result(p_job_id uuid, p_lease_token uuid, p_status text, p_result_json jsonb, p_result_schema_version text, p_result_ref jsonb, p_diagnostics jsonb, p_error_code text, p_error_message text, p_error_details jsonb, p_blocker_codes text[], p_resolution_scope text, p_retryable boolean) OWNER TO postgres;

--
-- Name: worker_retry_job(uuid, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.worker_retry_job(p_job_id uuid, p_run_after timestamp with time zone DEFAULT NULL::timestamp with time zone, p_max_attempts integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to retry worker jobs'
    );
  end if;

  select *
    into v_job
  from public.worker_jobs
  where id = p_job_id
  for update;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_FOUND',
      'status', 404,
      'message', 'Worker job not found'
    );
  end if;

  if v_job.status not in ('failed', 'blocked', 'stale', 'waiting', 'cancelled') then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_NOT_RETRYABLE',
      'status', 409,
      'message', 'Worker job is not in a retryable status'
    );
  end if;

  update public.worker_jobs
    set status = 'queued',
        run_after = coalesce(p_run_after, now()),
        attempt_count = 0,
        max_attempts = greatest(1, coalesce(p_max_attempts, max_attempts)),
        leased_by = null,
        lease_token = null,
        lease_expires_at = null,
        error_code = null,
        error_message = null,
        error_details = null,
        blocker_codes = '{}'::text[],
        resolution_scope = null,
        retryable = null,
        cancelled_at = null,
        cancelled_by = null,
        finished_at = null,
        updated_at = now()
  where id = v_job.id
  returning *
    into v_job;

  insert into public.worker_job_events (
    job_id,
    event_type,
    status,
    message,
    details
  ) values (
    v_job.id,
    'retried',
    v_job.status,
    p_reason,
    jsonb_build_object('runAfter', v_job.run_after)
  );

  return jsonb_build_object(
    'ok', true,
    'data', public.worker_job_payload(v_job, true)
  );
end;
$$;


ALTER FUNCTION public.worker_retry_job(p_job_id uuid, p_run_after timestamp with time zone, p_max_attempts integer, p_reason text) OWNER TO postgres;

--
-- Name: admit_dataset_derivative_rebuild_batch(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.admit_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid, p_plan_sha256 text, p_operation_id text, p_reason_code text, p_targets jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $_$
declare
  v_command constant text := 'cmd_dataset_derivative_rebuild_plan_guarded';
  v_schema_version constant text := 'dataset-derivative-rebuild-batch.v1';
  v_target jsonb;
  v_snapshot jsonb;
  v_quarantine jsonb;
  v_action jsonb;
  v_table text;
  v_id uuid;
  v_version text;
  v_expected_json_ordered_sha256 text;
  v_baseline_snapshot_sha256 text;
  v_target_count integer;
  v_flow_count integer;
  v_process_count integer;
  v_ordinal integer;
  v_action_id text;
  v_action_request_sha256 text;
  v_plan_request_sha256 text;
  v_summary_audit_id bigint;
  v_action_audit_id bigint;
  v_request_id uuid;
  v_now timestamp with time zone := pg_catalog.clock_timestamp();
  v_child_ids jsonb := '[]'::jsonb;
  v_normalized_targets jsonb;
  v_flow public.flows%rowtype;
  v_process public.processes%rowtype;
begin
  if p_actor_user_id is null
    or p_batch_id is null
    or p_plan_sha256 is null
    or p_plan_sha256 !~ '^[a-f0-9]{64}$'
    or nullif(btrim(p_operation_id), '') is null
    or octet_length(p_operation_id) > 512
    or nullif(btrim(p_reason_code), '') is null
    or octet_length(p_reason_code) > 512
    or jsonb_typeof(p_targets) is distinct from 'array'
    or jsonb_array_length(p_targets) not between 1 and 50
    or pg_column_size(p_targets) > 131072 then
    raise exception using
      errcode = '22023',
      message = 'Invalid bounded derivative rebuild batch request';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_targets) as target(value)
    where jsonb_typeof(target.value) is distinct from 'object'
      or not (target.value ?& array[
        'table',
        'id',
        'version',
        'expected_json_ordered_sha256',
        'baseline_snapshot_sha256'
      ])
      or exists (
        select 1
        from jsonb_object_keys(target.value) as target_key(key)
        where target_key.key <> all (array[
          'table',
          'id',
          'version',
          'expected_json_ordered_sha256',
          'baseline_snapshot_sha256'
        ])
      )
      or jsonb_typeof(target.value->'table') is distinct from 'string'
      or target.value->>'table' not in ('flows', 'processes')
      or jsonb_typeof(target.value->'id') is distinct from 'string'
      or (target.value->>'id')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(target.value->'version') is distinct from 'string'
      or (target.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
      or jsonb_typeof(target.value->'expected_json_ordered_sha256')
        is distinct from 'string'
      or (target.value->>'expected_json_ordered_sha256')
        !~ '^[a-f0-9]{64}$'
      or jsonb_typeof(target.value->'baseline_snapshot_sha256')
        is distinct from 'string'
      or (target.value->>'baseline_snapshot_sha256')
        !~ '^[a-f0-9]{64}$'
  ) then
    raise exception using
      errcode = '22023',
      message = 'Derivative rebuild batch targets must match the exact schema';
  end if;

  select
    count(*)::integer,
    count(*) filter (where target.value->>'table' = 'flows')::integer,
    count(*) filter (where target.value->>'table' = 'processes')::integer
  into v_target_count, v_flow_count, v_process_count
  from jsonb_array_elements(p_targets) as target(value);

  if (
    select count(*)
    from (
      select distinct
        target.value->>'table' as target_table,
        (target.value->>'id')::uuid as target_id,
        btrim(target.value->>'version') as target_version
      from jsonb_array_elements(p_targets) as target(value)
    ) as unique_target
  ) <> v_target_count then
    raise exception using
      errcode = '22023',
      message = 'Derivative rebuild batch targets must be unique';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_batch_id::text,
      0
    )
  );

  if exists (
    select 1
    from util.dataset_derivative_rebuild_requests as request
    where request.batch_id = p_batch_id
  ) then
    raise exception using
      errcode = '23505',
      message = 'Derivative rebuild batch id has already been admitted';
  end if;

  -- Full validation pass.  No quarantine, audit, proposal, request, or queue
  -- effect happens until every target has passed this loop.  Stable ordered
  -- row locks below avoid adding a database-wide write lock; the protected
  -- alias caller already owns any stronger closure locks required by its own
  -- primary mutation transaction.
  for v_target in
    select target.value || jsonb_build_object('ordinal', target.ordinality)
    from jsonb_array_elements(p_targets) with ordinality as target(value, ordinality)
    order by
      target.value->>'table',
      (target.value->>'id')::uuid,
      btrim(target.value->>'version')
  loop
    v_table := v_target->>'table';
    v_id := (v_target->>'id')::uuid;
    v_version := btrim(v_target->>'version');
    v_expected_json_ordered_sha256 :=
      v_target->>'expected_json_ordered_sha256';

    if v_table = 'flows' then
      v_flow := null;
      select flow.*
      into v_flow
      from public.flows as flow
      where flow.id = v_id
        and btrim(flow.version::text) = v_version
        and flow.user_id = p_actor_user_id
        and flow.state_code = 0
      for update;
      if v_flow.id is not null then
        v_snapshot := util.dataset_derivative_rebuild_snapshot(v_flow);
      else
        v_snapshot := null;
      end if;
    else
      v_process := null;
      select process.*
      into v_process
      from public.processes as process
      where process.id = v_id
        and btrim(process.version::text) = v_version
        and process.user_id = p_actor_user_id
        and process.state_code = 0
      for update;
      if v_process.id is not null then
        v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
      else
        v_snapshot := null;
      end if;
    end if;

    if v_snapshot is null then
      raise exception using
        errcode = 'P0002',
        message = 'Derivative rebuild batch target is not an owner draft',
        detail = v_table || ':' || v_id::text || '@' || v_version;
    end if;

    if v_snapshot->>'json_sha256'
        is distinct from v_snapshot->>'json_ordered_sha256'
      or v_snapshot->>'json_ordered_sha256'
        is distinct from v_expected_json_ordered_sha256 then
      raise exception using
        errcode = '40001',
        message = 'Derivative rebuild batch desired primary hash drifted',
        detail = v_table || ':' || v_id::text || '@' || v_version;
    end if;

    if exists (
      select 1
      from util.dataset_derivative_rebuild_requests as request
      where request.target_table = v_table
        and request.target_id = v_id
        and request.target_version = v_version
        and request.status not in ('completed', 'stale', 'failed')
    ) then
      raise exception using
        errcode = '55006',
        message = 'Derivative rebuild batch target already has an active fence',
        detail = v_table || ':' || v_id::text || '@' || v_version;
    end if;
  end loop;

  select jsonb_agg(
    jsonb_build_object(
      'table', target.value->>'table',
      'id', (target.value->>'id')::uuid,
      'version', btrim(target.value->>'version'),
      'expected_json_ordered_sha256',
        target.value->>'expected_json_ordered_sha256',
      'baseline_snapshot_sha256',
        target.value->>'baseline_snapshot_sha256'
    )
    order by
      target.value->>'table',
      (target.value->>'id')::uuid,
      btrim(target.value->>'version')
  )
  into v_normalized_targets
  from jsonb_array_elements(p_targets) as target(value);

  v_plan_request_sha256 := util.dataset_derivative_rebuild_sha256(
    jsonb_build_object(
      'schema_version', v_schema_version,
      'batch_id', p_batch_id,
      'plan_sha256', p_plan_sha256,
      'operation_id', btrim(p_operation_id),
      'reason_code', btrim(p_reason_code),
      'targets', v_normalized_targets
    )::text
  );

  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  ) values (
    v_command,
    p_actor_user_id,
    null,
    null,
    null,
    jsonb_build_object(
      'record_type', 'plan_summary',
      'schema_version', v_schema_version,
      'batch_id', p_batch_id,
      'plan_sha256', p_plan_sha256,
      'operation_id', btrim(p_operation_id),
      'target_visibility', 'owner_draft',
      'plan_request_sha256', v_plan_request_sha256,
      'action_count', v_target_count,
      'accepted_count', v_target_count,
      'flows', v_flow_count,
      'processes', v_process_count,
      'reason_code', btrim(p_reason_code),
      'hash_algorithm', 'postgres-jsonb-text-sha256'
    )
  )
  returning id into v_summary_audit_id;

  for v_target in
    select target.value || jsonb_build_object('ordinal', target.ordinality)
    from jsonb_array_elements(p_targets) with ordinality as target(value, ordinality)
    order by target.ordinality
  loop
    v_table := v_target->>'table';
    v_id := (v_target->>'id')::uuid;
    v_version := btrim(v_target->>'version');
    v_ordinal := (v_target->>'ordinal')::integer;
    v_expected_json_ordered_sha256 :=
      v_target->>'expected_json_ordered_sha256';
    v_baseline_snapshot_sha256 := v_target->>'baseline_snapshot_sha256';
    v_snapshot := util.dataset_derivative_rebuild_snapshot(
      v_table,
      v_id,
      v_version
    );

    if v_snapshot is null
      or v_snapshot->>'user_id' is distinct from p_actor_user_id::text
      or v_snapshot->>'state_code' is distinct from '0'
      or v_snapshot->>'json_sha256'
        is distinct from v_expected_json_ordered_sha256
      or v_snapshot->>'json_ordered_sha256'
        is distinct from v_expected_json_ordered_sha256 then
      raise exception using
        errcode = '40001',
        message = 'Derivative rebuild batch primary changed after validation';
    end if;

    v_quarantine := util.quarantine_dataset_derivative_rebuild_target(
      v_table,
      v_id,
      v_version
    );
    v_request_id := pg_catalog.gen_random_uuid();
    v_action_id := 'batch:' || v_ordinal::text || ':'
      || v_table || ':' || v_id::text || '@' || v_version;
    v_action := jsonb_build_object(
      'schema_version', 'dataset-derivative-rebuild-batch-action.v1',
      'batch_id', p_batch_id,
      'batch_ordinal', v_ordinal,
      'action_id', v_action_id,
      'action', 'rebuild_derivatives',
      'table', v_table,
      'id', v_id,
      'version', v_version,
      'expected_state_code', 0,
      'expected_json_ordered_sha256', v_expected_json_ordered_sha256,
      'baseline_snapshot_sha256', v_baseline_snapshot_sha256,
      'post_write_snapshot_sha256', v_snapshot->>'snapshot_sha256',
      'components', jsonb_build_array('extracted_md', 'embedding_ft'),
      'reason_code', btrim(p_reason_code)
    );
    v_action_request_sha256 := util.dataset_derivative_rebuild_sha256(
      v_action::text
    );

    insert into public.command_audit_log (
      command,
      actor_user_id,
      target_table,
      target_id,
      target_version,
      payload
    ) values (
      v_command,
      p_actor_user_id,
      v_table,
      v_id,
      v_version,
      jsonb_build_object(
        'record_type', 'action',
        'schema_version', v_schema_version,
        'batch_id', p_batch_id,
        'batch_ordinal', v_ordinal,
        'batch_target_count', v_target_count,
        'request_id', v_request_id,
        'plan_sha256', p_plan_sha256,
        'operation_id', btrim(p_operation_id),
        'action_id', v_action_id,
        'target_visibility', 'owner_draft',
        'expected_snapshot_sha256', v_snapshot->>'snapshot_sha256',
        'expected_json_ordered_sha256', v_expected_json_ordered_sha256,
        'baseline_snapshot_sha256', v_baseline_snapshot_sha256,
        'plan_request_sha256', v_plan_request_sha256,
        'action_request_sha256', v_action_request_sha256,
        'reason_code', btrim(p_reason_code),
        'components', jsonb_build_array('extracted_md', 'embedding_ft'),
        'hash_algorithm', 'postgres-jsonb-text-sha256'
      )
    )
    returning id into v_action_audit_id;

    insert into util.dataset_derivative_rebuild_requests (
      id,
      actor_user_id,
      plan_sha256,
      operation_id,
      action_id,
      target_table,
      target_id,
      target_version,
      expected_snapshot_sha256,
      expected_modified_at,
      expected_json_sha256,
      expected_json_ordered_sha256,
      before_extracted_md_sha256,
      before_embedding_ft_sha256,
      before_embedding_ft_at,
      plan_request_sha256,
      action_request_sha256,
      reason_code,
      status,
      phase,
      admitted_at,
      drain_not_before,
      action_audit_id,
      summary_audit_id,
      quarantined_http_requests,
      quarantined_embedding_jobs,
      quarantined_pending_jobs,
      batch_id,
      batch_ordinal,
      batch_target_count,
      source_baseline_snapshot_sha256
    ) values (
      v_request_id,
      p_actor_user_id,
      p_plan_sha256,
      btrim(p_operation_id),
      v_action_id,
      v_table,
      v_id,
      v_version,
      v_snapshot->>'snapshot_sha256',
      (v_snapshot->>'modified_at')::timestamp with time zone,
      v_snapshot->>'json_sha256',
      v_snapshot->>'json_ordered_sha256',
      v_snapshot->>'extracted_md_sha256',
      v_snapshot->>'embedding_ft_sha256',
      (v_snapshot->>'embedding_ft_at')::timestamp with time zone,
      v_plan_request_sha256,
      v_action_request_sha256,
      btrim(p_reason_code),
      'queued',
      'admitted',
      v_now,
      v_now + interval '420 seconds',
      v_action_audit_id,
      v_summary_audit_id,
      coalesce((v_quarantine->>'http_requests')::integer, 0),
      coalesce((v_quarantine->>'embedding_jobs')::integer, 0),
      coalesce((v_quarantine->>'pending_jobs')::integer, 0),
      p_batch_id,
      v_ordinal,
      v_target_count,
      v_baseline_snapshot_sha256
    );

    v_child_ids := v_child_ids || jsonb_build_array(
      jsonb_build_object(
        'ordinal', v_ordinal,
        'table', v_table,
        'id', v_id,
        'version', v_version,
        'request_id', v_request_id,
        'expected_snapshot_sha256', v_snapshot->>'snapshot_sha256'
      )
    );
  end loop;

  return jsonb_build_object(
    'ok', true,
    'schema_version', v_schema_version,
    'batch_id', p_batch_id,
    'plan_sha256', p_plan_sha256,
    'operation_id', btrim(p_operation_id),
    'plan_request_sha256', v_plan_request_sha256,
    'target_count', v_target_count,
    'flow_count', v_flow_count,
    'process_count', v_process_count,
    'flows', v_flow_count,
    'processes', v_process_count,
    'summary_audit_id', v_summary_audit_id::text,
    'child_request_ids', v_child_ids
  );
exception
  when lock_not_available then
    raise exception using
      errcode = '55P03',
      message = 'Derivative rebuild batch write fence could not be acquired';
end;
$_$;


ALTER FUNCTION util.admit_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid, p_plan_sha256 text, p_operation_id text, p_reason_code text, p_targets jsonb) OWNER TO postgres;

--
-- Name: FUNCTION admit_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid, p_plan_sha256 text, p_operation_id text, p_reason_code text, p_targets jsonb); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.admit_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid, p_plan_sha256 text, p_operation_id text, p_reason_code text, p_targets jsonb) IS 'Private atomic admission for 1..50 unique owner-draft flow/process derivative children. Every target is validated before any quarantine/audit/request write; batch ids are non-replayable.';


--
-- Name: apply_lca_package_retention(interval, interval, timestamp with time zone, integer, boolean); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.apply_lca_package_retention(p_job_retention_window interval DEFAULT '30 days'::interval, p_request_cache_retention_window interval DEFAULT '30 days'::interval, p_as_of timestamp with time zone DEFAULT now(), p_max_rows integer DEFAULT 1000, p_dry_run boolean DEFAULT true) RETURNS TABLE(retention_area text, retention_action text, dry_run boolean, affected_count bigint)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_count bigint;
begin
  if p_as_of is null then
    raise exception using
      errcode = '22023',
      message = 'package retention apply as_of timestamp must not be null';
  end if;

  if p_job_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'package job retention window must be at least 1 day';
  end if;

  if p_request_cache_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'package request-cache retention window must be at least 1 day';
  end if;

  if coalesce(p_max_rows, 0) <= 0 then
    raise exception using
      errcode = '22023',
      message = 'package retention max rows must be greater than zero';
  end if;

  if p_dry_run then
    return query
    with artifact_candidates as (
      select artifacts.id
      from public.lca_package_artifacts as artifacts
      join public.worker_jobs as jobs
        on jobs.id = artifacts.worker_job_id
      where jobs.job_kind in ('tidas.export_package', 'tidas.import_package')
        and jobs.status not in ('queued', 'running', 'waiting')
        and artifacts.status not in ('deleted', 'pending')
        and not artifacts.is_pinned
        and artifacts.expires_at is not null
        and artifacts.expires_at <= p_as_of
        and not exists (
          select 1
          from public.lca_package_request_cache as request_cache
          where (
              request_cache.export_artifact_id = artifacts.id
              or request_cache.report_artifact_id = artifacts.id
            )
            and request_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window
        )
      order by artifacts.expires_at, artifacts.created_at, artifacts.id
      limit p_max_rows
    ),
    request_cache_candidates as (
      select request_cache.id
      from public.lca_package_request_cache as request_cache
      left join public.worker_jobs as jobs
        on jobs.id = request_cache.worker_job_id
      where request_cache.status not in ('pending', 'running')
        and request_cache.last_accessed_at < p_as_of - p_request_cache_retention_window
        and coalesce(jobs.status not in ('queued', 'running', 'waiting'), true)
      order by request_cache.last_accessed_at, request_cache.created_at, request_cache.id
      limit p_max_rows
    ),
    export_item_candidates as (
      select export_items.id
      from public.lca_package_export_items as export_items
      join public.worker_jobs as jobs
        on jobs.id = export_items.worker_job_id
      where jobs.job_kind in ('tidas.export_package', 'tidas.import_package')
        and jobs.status not in ('queued', 'running', 'waiting')
        and coalesce(jobs.finished_at, jobs.updated_at, jobs.created_at) < p_as_of - p_job_retention_window
        and not exists (
          select 1
          from public.lca_package_artifacts as artifacts
          where artifacts.worker_job_id = export_items.worker_job_id
            and artifacts.status <> 'deleted'
        )
        and not exists (
          select 1
          from public.lca_package_request_cache as request_cache
          where request_cache.worker_job_id = export_items.worker_job_id
            and request_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window
        )
      order by export_items.created_at, export_items.id
      limit p_max_rows
    )
    select
      'lca_package_artifacts'::text,
      'mark_expired_unpinned_artifacts_deleted'::text,
      true,
      count(*)::bigint
    from artifact_candidates
    union all
    select
      'lca_package_request_cache'::text,
      'delete_stale_request_cache_rows'::text,
      true,
      count(*)::bigint
    from request_cache_candidates
    union all
    select
      'lca_package_export_items'::text,
      'delete_export_items_after_artifact_gc'::text,
      true,
      count(*)::bigint
    from export_item_candidates;

    return;
  end if;

  with artifact_candidates as (
    select artifacts.id
    from public.lca_package_artifacts as artifacts
    join public.worker_jobs as jobs
      on jobs.id = artifacts.worker_job_id
    where jobs.job_kind in ('tidas.export_package', 'tidas.import_package')
      and jobs.status not in ('queued', 'running', 'waiting')
      and artifacts.status not in ('deleted', 'pending')
      and not artifacts.is_pinned
      and artifacts.expires_at is not null
      and artifacts.expires_at <= p_as_of
      and not exists (
        select 1
        from public.lca_package_request_cache as request_cache
        where (
            request_cache.export_artifact_id = artifacts.id
            or request_cache.report_artifact_id = artifacts.id
          )
          and request_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window
      )
    order by artifacts.expires_at, artifacts.created_at, artifacts.id
    limit p_max_rows
  )
  update public.lca_package_artifacts as artifacts
     set status = 'deleted',
         metadata = artifacts.metadata || jsonb_build_object(
           'retentionDeletedAt', p_as_of,
           'retentionAction', 'package_metadata_retention_gc'
         ),
         updated_at = p_as_of
  from artifact_candidates
  where artifacts.id = artifact_candidates.id;

  get diagnostics v_count = row_count;
  return query select
    'lca_package_artifacts'::text,
    'mark_expired_unpinned_artifacts_deleted'::text,
    false,
    v_count;

  with request_cache_candidates as (
    select request_cache.id
    from public.lca_package_request_cache as request_cache
    left join public.worker_jobs as jobs
      on jobs.id = request_cache.worker_job_id
    where request_cache.status not in ('pending', 'running')
      and request_cache.last_accessed_at < p_as_of - p_request_cache_retention_window
      and coalesce(jobs.status not in ('queued', 'running', 'waiting'), true)
    order by request_cache.last_accessed_at, request_cache.created_at, request_cache.id
    limit p_max_rows
  )
  delete from public.lca_package_request_cache as request_cache
  using request_cache_candidates
  where request_cache.id = request_cache_candidates.id;

  get diagnostics v_count = row_count;
  return query select
    'lca_package_request_cache'::text,
    'delete_stale_request_cache_rows'::text,
    false,
    v_count;

  with export_item_candidates as (
    select export_items.id
    from public.lca_package_export_items as export_items
    join public.worker_jobs as jobs
      on jobs.id = export_items.worker_job_id
    where jobs.job_kind in ('tidas.export_package', 'tidas.import_package')
      and jobs.status not in ('queued', 'running', 'waiting')
      and coalesce(jobs.finished_at, jobs.updated_at, jobs.created_at) < p_as_of - p_job_retention_window
      and not exists (
        select 1
        from public.lca_package_artifacts as artifacts
        where artifacts.worker_job_id = export_items.worker_job_id
          and artifacts.status <> 'deleted'
      )
      and not exists (
        select 1
        from public.lca_package_request_cache as request_cache
        where request_cache.worker_job_id = export_items.worker_job_id
          and request_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window
      )
    order by export_items.created_at, export_items.id
    limit p_max_rows
  )
  delete from public.lca_package_export_items as export_items
  using export_item_candidates
  where export_items.id = export_item_candidates.id;

  get diagnostics v_count = row_count;
  return query select
    'lca_package_export_items'::text,
    'delete_export_items_after_artifact_gc'::text,
    false,
    v_count;
end;
$$;


ALTER FUNCTION util.apply_lca_package_retention(p_job_retention_window interval, p_request_cache_retention_window interval, p_as_of timestamp with time zone, p_max_rows integer, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION apply_lca_package_retention(p_job_retention_window interval, p_request_cache_retention_window interval, p_as_of timestamp with time zone, p_max_rows integer, p_dry_run boolean); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.apply_lca_package_retention(p_job_retention_window interval, p_request_cache_retention_window interval, p_as_of timestamp with time zone, p_max_rows integer, p_dry_run boolean) IS 'Operator/service-role helper for package domain retention. Dry-run counts candidates by default; apply mode marks expired unpinned package artifacts deleted and removes stale package request-cache/export-item metadata rows. Storage object deletion remains a worker/operator responsibility before or around metadata GC.';


--
-- Name: clear_column(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.clear_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
    clear_column text := TG_ARGV[0];
begin
    NEW := NEW #= public.hstore(clear_column, NULL);
    return NEW;
end;
$$;


ALTER FUNCTION util.clear_column() OWNER TO postgres;

--
-- Name: commit_dataset_derivative_rebuild_proposal(uuid, bigint, bigint); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.commit_dataset_derivative_rebuild_proposal(p_request_id uuid, p_markdown_proposal_id bigint, p_embedding_proposal_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_markdown util.dataset_derivative_rebuild_proposals%rowtype;
  v_embedding util.dataset_derivative_rebuild_proposals%rowtype;
  v_flow public.flows%rowtype;
  v_process public.processes%rowtype;
  v_primary_matches boolean := false;
begin
  select request.*
  into v_request
  from util.dataset_derivative_rebuild_requests as request
  where request.id = p_request_id
    and request.status not in ('completed', 'stale', 'failed')
  for update;

  if v_request.id is null then
    raise exception using
      errcode = 'P0002',
      message = 'Active derivative rebuild request not found';
  end if;

  select proposal.*
  into v_markdown
  from util.dataset_derivative_rebuild_proposals as proposal
  where proposal.id = p_markdown_proposal_id
    and proposal.request_id = p_request_id
    and proposal.proposal_kind = 'markdown'
    and proposal.status = 'accepted'
  for update;

  select proposal.*
  into v_embedding
  from util.dataset_derivative_rebuild_proposals as proposal
  where proposal.id = p_embedding_proposal_id
    and proposal.request_id = p_request_id
    and proposal.proposal_kind = 'embedding'
    and proposal.status = 'captured'
  for update;

  if v_markdown.id is null or v_embedding.id is null then
    raise exception using
      errcode = 'P0002',
      message = 'Accepted Markdown and captured embedding proposals are required';
  end if;

  if v_request.target_table = 'flows' then
    select flow.*
    into v_flow
    from public.flows as flow
    where flow.id = v_request.target_id
      and btrim(flow.version::text) = v_request.target_version
    for update;
    v_primary_matches := util.dataset_derivative_rebuild_primary_matches(
      v_request,
      v_flow
    );
  elsif v_request.target_table = 'processes' then
    select process.*
    into v_process
    from public.processes as process
    where process.id = v_request.target_id
      and btrim(process.version::text) = v_request.target_version
    for update;
    v_primary_matches := util.dataset_derivative_rebuild_primary_matches(
      v_request,
      v_process
    );
  end if;

  if not v_primary_matches then
    raise exception using
      errcode = '40001',
      message = 'Derivative rebuild primary changed before proposal commit';
  end if;

  if v_request.markdown_proposal_id is distinct from v_markdown.id
    or v_request.accepted_extracted_md_sha256
      is distinct from v_markdown.extracted_md_sha256
    or v_embedding.source_extracted_md_sha256
      is distinct from v_markdown.extracted_md_sha256 then
    raise exception using
      errcode = '40001',
      message = 'Embedding proposal is not bound to the accepted Markdown';
  end if;

  if v_embedding.embedding_ft_at
    <= coalesce(
      v_request.before_embedding_ft_at,
      '-infinity'::timestamp with time zone
    ) then
    raise exception using
      errcode = '22023',
      message = 'Embedding proposal is not newer than the frozen derivative baseline';
  end if;

  insert into util.dataset_derivative_rebuild_permits (
    request_id,
    proposal_id,
    permit_kind,
    backend_pid,
    transaction_id
  ) values
    (
      v_request.id,
      v_markdown.id,
      'markdown',
      pg_catalog.pg_backend_pid(),
      pg_catalog.txid_current()
    ),
    (
      v_request.id,
      v_embedding.id,
      'embedding',
      pg_catalog.pg_backend_pid(),
      pg_catalog.txid_current()
    );

  if v_request.target_table = 'flows' then
    update public.flows as flow
    set
      extracted_md = v_markdown.extracted_md,
      embedding_ft = v_embedding.embedding_ft,
      embedding_ft_at = v_embedding.embedding_ft_at
    where flow.id = v_request.target_id
      and btrim(flow.version::text) = v_request.target_version;
  else
    update public.processes as process
    set
      extracted_md = v_markdown.extracted_md,
      embedding_ft = v_embedding.embedding_ft,
      embedding_ft_at = v_embedding.embedding_ft_at
    where process.id = v_request.target_id
      and btrim(process.version::text) = v_request.target_version;
  end if;

  update util.dataset_derivative_rebuild_requests
  set
    embedding_proposal_id = v_embedding.id,
    updated_at = pg_catalog.clock_timestamp()
  where id = v_request.id;

  delete from util.dataset_derivative_rebuild_permits
  where request_id = v_request.id
    and proposal_id in (v_markdown.id, v_embedding.id);

  update util.dataset_derivative_rebuild_proposals
  set
    status = 'committed',
    committed_at = pg_catalog.clock_timestamp()
  where id in (v_markdown.id, v_embedding.id);
end;
$$;


