--
-- Name: dataset_derivative_rebuild_snapshot(text, uuid, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_flow public.flows%rowtype;
  v_process public.processes%rowtype;
begin
  if p_table = 'flows' then
    select flow.*
    into v_flow
    from public.flows as flow
    where flow.id = p_id
      and btrim(flow.version::text) = p_version;
    if v_flow.id is null then
      return null;
    end if;
    return util.dataset_derivative_rebuild_snapshot(v_flow);
  elsif p_table = 'processes' then
    select process.*
    into v_process
    from public.processes as process
    where process.id = p_id
      and btrim(process.version::text) = p_version;
    if v_process.id is null then
      return null;
    end if;
    return util.dataset_derivative_rebuild_snapshot(v_process);
  end if;

  raise exception using
    errcode = '22023',
    message = 'Derivative rebuild target table must be flows or processes';
end;
$$;


ALTER FUNCTION util.dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) OWNER TO postgres;

--
-- Name: dataset_flow_identity_dry_validate_process(uuid, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_dry_validate_process(p_actor uuid, p_manifest jsonb, p_mappings jsonb, p_policy jsonb, p_support_snapshots jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_rewrite_keys constant text[] := array[
    'ordinal', 'exchange_index', 'internal_id', 'direction', 'mapping_id',
    'source_reference', 'target_reference', 'before_reference_sha256',
    'after_reference_sha256'
  ];
  v_reference_keys constant text[] := array[
    '@refObjectId', '@type', '@uri', '@version',
    'common:shortDescription'
  ];
  v_process_validation jsonb;
  v_mapping_validation jsonb;
  v_process public.processes%rowtype;
  v_mapping jsonb;
  v_rewrite jsonb;
  v_before_payload jsonb;
  v_before_exchanges jsonb;
  v_after_exchanges jsonb;
  v_before_exchange jsonb;
  v_after_exchange jsonb;
  v_before_reference jsonb;
  v_after_reference jsonb;
  v_collision jsonb;
  v_desired_payload jsonb;
  v_after_payload_sha256 text;
  v_after_exchange_sha256 text;
  v_mapping_array jsonb;
  v_mapping_by_id jsonb;
  v_mapping_by_source jsonb;
  v_indexed boolean := false;
begin
  if jsonb_typeof(p_mappings) = 'array' then
    v_mapping_array := p_mappings;
  elsif jsonb_typeof(p_mappings) = 'object'
    and private.dataset_flow_identity_exact_keys(p_mappings, array[
      'schema_version', 'mapping_count', 'mapping_guard_set_sha256',
      'mappings', 'by_ordinal', 'by_id', 'by_source'
    ])
    and p_mappings->>'schema_version'
      = 'dataset-flow-identity-mapping-index.v2'
    and jsonb_typeof(p_mappings->'mapping_count') = 'number'
    and (p_mappings->>'mapping_count')::integer
      = jsonb_array_length(p_mappings->'mappings')
    and p_mappings->>'mapping_guard_set_sha256' ~ '^[a-f0-9]{64}$'
    and jsonb_typeof(p_mappings->'mappings') = 'array'
    and jsonb_typeof(p_mappings->'by_ordinal') = 'object'
    and jsonb_typeof(p_mappings->'by_id') = 'object'
    and jsonb_typeof(p_mappings->'by_source') = 'object' then
    v_mapping_array := p_mappings->'mappings';
    v_mapping_by_id := p_mappings->'by_id';
    v_mapping_by_source := p_mappings->'by_source';
    v_indexed := true;
  end if;
  if p_actor is null
    or v_mapping_array is null
    or jsonb_typeof(p_support_snapshots) <> 'array' then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_DRY_PROCESS_INVALID_REQUEST'
    );
  end if;
  v_process_validation := util.dataset_flow_identity_validate_process_guard(
    p_actor, p_manifest
  );
  if coalesce((v_process_validation->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_DRY_PROCESS_BASELINE_REJECTED',
      'details', v_process_validation
    );
  end if;
  if (
    select count(*) = (p_manifest->>'rewrite_count')::integer
      and min((rewrite.value->>'ordinal')::integer) = 1
      and max((rewrite.value->>'ordinal')::integer)
        = (p_manifest->>'rewrite_count')::integer
      and count(distinct (rewrite.value->>'ordinal')::integer)
        = (p_manifest->>'rewrite_count')::integer
      and count(distinct (rewrite.value->>'exchange_index')::integer)
        = (p_manifest->>'rewrite_count')::integer
      and bool_and(
        (rewrite.value->>'ordinal')::integer = rewrite.ordinality::integer
      )
    from jsonb_array_elements(p_manifest->'rewrites')
      with ordinality as rewrite(value, ordinality)
  ) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_DRY_REWRITE_ORDINAL_MISMATCH'
    );
  end if;

  select process.*
  into v_process
  from public.processes as process
  where process.id = (p_manifest->>'id')::uuid
    and btrim(process.version::text) = p_manifest->>'version'
    and process.user_id = p_actor and process.state_code = 0;
  v_before_payload := v_process.json_ordered::jsonb;
  v_before_exchanges := private.dataset_flow_identity_exchanges(v_before_payload);
  v_after_exchanges := v_before_exchanges;

  for v_rewrite in
    select rewrite.value
    from jsonb_array_elements(p_manifest->'rewrites')
      with ordinality as rewrite(value, ordinality)
    order by rewrite.ordinality
  loop
    if not private.dataset_flow_identity_exact_keys(v_rewrite, v_rewrite_keys)
      or v_rewrite->>'ordinal' !~ '^[1-9][0-9]*$'
      or v_rewrite->>'exchange_index' !~ '^(0|[1-9][0-9]*)$'
      or (v_rewrite->>'exchange_index')::integer
        >= jsonb_array_length(v_before_exchanges)
      or nullif(v_rewrite->>'internal_id', '') is null
      or v_rewrite->>'direction' not in ('Input', 'Output')
      or v_rewrite->>'mapping_id' !~ '^[a-f0-9]{64}$'
      or v_rewrite->>'before_reference_sha256' !~ '^[a-f0-9]{64}$'
      or v_rewrite->>'after_reference_sha256' !~ '^[a-f0-9]{64}$'
      or not private.dataset_flow_identity_exact_keys(
        v_rewrite->'source_reference', v_reference_keys
      )
      or not private.dataset_flow_identity_exact_keys(
        v_rewrite->'target_reference', v_reference_keys
      ) then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_DRY_REWRITE_SCHEMA_MISMATCH'
      );
    end if;

    if v_indexed then
      v_mapping := v_mapping_by_id->(v_rewrite->>'mapping_id');
    else
      select mapping.value
      into v_mapping
      from jsonb_array_elements(v_mapping_array) as mapping(value)
      where mapping.value->>'mapping_id' = v_rewrite->>'mapping_id';
    end if;
    if v_mapping is null then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_DRY_MAPPING_NOT_SEALED'
      );
    end if;
    if not v_indexed then
      v_mapping_validation := util.dataset_flow_identity_validate_mapping(
        p_actor, v_mapping, p_policy, p_support_snapshots,
        (v_mapping->>'ordinal')::integer
      );
      if coalesce((v_mapping_validation->>'ok')::boolean, false) is false then
        return jsonb_build_object(
          'ok', false, 'code', 'FLOW_IDENTITY_DRY_MAPPING_REJECTED',
          'details', v_mapping_validation
        );
      end if;
    end if;

    v_before_exchange := v_after_exchanges ->
      (v_rewrite->>'exchange_index')::integer;
    v_before_reference := private.dataset_flow_identity_reference(
      v_before_exchange
    );
    if v_before_exchange->>'@dataSetInternalID'
        is distinct from v_rewrite->>'internal_id'
      or v_before_exchange->>'exchangeDirection'
        is distinct from v_rewrite->>'direction'
      or v_before_reference is distinct from v_rewrite->'source_reference'
      or util.dataset_flow_identity_sha256(v_before_reference)
        is distinct from v_rewrite->>'before_reference_sha256'
      or v_before_reference->>'@refObjectId'
        is distinct from v_mapping #>> '{source,id}'
      or v_before_reference->>'@version'
        is distinct from v_mapping #>> '{source,version}'
      or v_rewrite->'target_reference'
        is distinct from v_mapping #> '{target,reference}'
      or util.dataset_flow_identity_sha256(v_rewrite->'target_reference')
        is distinct from v_rewrite->>'after_reference_sha256' then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_DRY_EXCHANGE_LOCATOR_DRIFT'
      );
    end if;

    v_after_exchange := jsonb_set(
      v_before_exchange,
      '{referenceToFlowDataSet}',
      (v_before_exchange->'referenceToFlowDataSet')
        || v_rewrite->'target_reference',
      false
    );
    v_after_reference := private.dataset_flow_identity_reference(v_after_exchange);
    if v_after_reference is distinct from v_rewrite->'target_reference'
      or v_after_exchange - 'referenceToFlowDataSet'
        is distinct from v_before_exchange - 'referenceToFlowDataSet'
      or (v_after_exchange->'referenceToFlowDataSet')
          - '@refObjectId' - '@type' - '@uri' - '@version'
          - 'common:shortDescription'
        is distinct from
        (v_before_exchange->'referenceToFlowDataSet')
          - '@refObjectId' - '@type' - '@uri' - '@version'
          - 'common:shortDescription' then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_DRY_FIVE_FIELD_BOUNDARY_FAILED'
      );
    end if;
    v_after_exchanges := jsonb_set(
      v_after_exchanges,
      array[(v_rewrite->>'exchange_index')::integer::text],
      v_after_exchange,
      false
    );
  end loop;

  v_collision := private.dataset_flow_identity_collision_ledger(
    v_after_exchanges, p_manifest->'rewrites'
  );
  v_desired_payload := private.dataset_flow_identity_replace_exchanges(
    v_before_payload, v_after_exchanges
  );
  v_after_payload_sha256 := util.dataset_flow_identity_sha256(v_desired_payload);
  v_after_exchange_sha256 := util.dataset_flow_identity_sha256(v_after_exchanges);
  if v_collision is distinct from p_manifest->'collision_ledger'
    or v_after_payload_sha256
      is distinct from p_manifest->>'desired_payload_sha256'
    or v_after_exchange_sha256
      is distinct from p_manifest->>'desired_exchange_set_sha256'
    or jsonb_array_length(v_after_exchanges)
      <> jsonb_array_length(v_before_exchanges) then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_DRY_DESIRED_CLOSURE_MISMATCH'
    );
  end if;
  if v_indexed then
    if exists (
      select 1
      from jsonb_array_elements(v_after_exchanges) as exchange(value)
      where v_mapping_by_source ? (
        (exchange.value #>> '{referenceToFlowDataSet,@refObjectId}') || '@'
          || (exchange.value #>> '{referenceToFlowDataSet,@version}')
      )
    ) then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_DRY_DESIRED_CLOSURE_MISMATCH'
      );
    end if;
  elsif exists (
    select 1
    from jsonb_array_elements(v_mapping_array) as mapping(value)
    join lateral jsonb_array_elements(v_after_exchanges) as exchange(value)
      on exchange.value #>> '{referenceToFlowDataSet,@refObjectId}'
        = mapping.value #>> '{source,id}'
      and exchange.value #>> '{referenceToFlowDataSet,@version}'
        = mapping.value #>> '{source,version}'
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_DRY_DESIRED_CLOSURE_MISMATCH'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'before_payload_sha256', p_manifest->>'before_payload_sha256',
    'after_payload_sha256', v_after_payload_sha256,
    'after_exchange_set_sha256', v_after_exchange_sha256,
    'desired_payload', v_desired_payload,
    'desired_exchanges', v_after_exchanges,
    'collision_ledger', v_collision
  );
exception when others then
  return jsonb_build_object(
    'ok', false, 'code', 'FLOW_IDENTITY_DRY_PROCESS_INVALID',
    'sqlstate', sqlstate, 'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_dry_validate_process(p_actor uuid, p_manifest jsonb, p_mappings jsonb, p_policy jsonb, p_support_snapshots jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_protected_closure(uuid, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_protected_closure(p_actor uuid, p_closure jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_keys constant text[] := array[
    'schema_version', 'pending', 'blockers', 'orphans',
    'pending_set_sha256', 'blocker_set_sha256', 'orphan_set_sha256',
    'total_expected_reference_count'
  ];
  v_entries jsonb;
  v_observed jsonb;
  v_invalid integer;
  v_expected_total bigint;
  v_observed_total bigint;
begin
  if p_actor is null
    or not private.dataset_flow_identity_exact_keys(p_closure, v_keys)
    or p_closure->>'schema_version'
      <> 'dataset-flow-identity-protected-closure.v1'
    or jsonb_typeof(p_closure->'pending') <> 'array'
    or jsonb_typeof(p_closure->'blockers') <> 'array'
    or jsonb_typeof(p_closure->'orphans') <> 'array'
    or p_closure->>'pending_set_sha256' !~ '^[a-f0-9]{64}$'
    or p_closure->>'blocker_set_sha256' !~ '^[a-f0-9]{64}$'
    or p_closure->>'orphan_set_sha256' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_closure->'total_expected_reference_count')
      <> 'number'
    or util.dataset_flow_identity_sha256(p_closure->'pending')
      is distinct from p_closure->>'pending_set_sha256'
    or util.dataset_flow_identity_sha256(p_closure->'blockers')
      is distinct from p_closure->>'blocker_set_sha256'
    or util.dataset_flow_identity_sha256(p_closure->'orphans')
      is distinct from p_closure->>'orphan_set_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROTECTED_CLOSURE_SCHEMA_MISMATCH'
    );
  end if;

  select coalesce(jsonb_agg(entry order by partition_ordinal, ordinal), '[]'::jsonb)
  into v_entries
  from (
    select
      1 as partition_ordinal,
      item.ordinality::integer as ordinal,
      item.value || jsonb_build_object('partition', 'pending') as entry
    from jsonb_array_elements(p_closure->'pending')
      with ordinality as item(value, ordinality)
    union all
    select
      2,
      item.ordinality::integer,
      item.value || jsonb_build_object('partition', 'blockers')
    from jsonb_array_elements(p_closure->'blockers')
      with ordinality as item(value, ordinality)
    union all
    select
      3,
      item.ordinality::integer,
      item.value || jsonb_build_object(
        'partition', 'orphans',
        'expected_reference_count', 0,
        'occurrences', '[]'::jsonb,
        'occurrence_set_sha256',
          util.dataset_flow_identity_sha256('[]'::jsonb)
      )
    from jsonb_array_elements(p_closure->'orphans')
      with ordinality as item(value, ordinality)
  ) as combined;

  select count(*)::integer
  into v_invalid
  from jsonb_array_elements(v_entries) as entry(value)
  where not private.dataset_flow_identity_exact_keys(entry.value, array[
      'source_id', 'source_version', 'expected_reference_count',
      'occurrences', 'occurrence_set_sha256', 'evidence_sha256', 'partition'
    ])
    or entry.value->>'source_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or entry.value->>'source_version'
      !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or jsonb_typeof(entry.value->'expected_reference_count') <> 'number'
    or (entry.value->>'expected_reference_count')::integer < 0
    or jsonb_typeof(entry.value->'occurrences') <> 'array'
    or jsonb_array_length(entry.value->'occurrences')
      <> (entry.value->>'expected_reference_count')::integer
    or entry.value->>'occurrence_set_sha256' !~ '^[a-f0-9]{64}$'
    or util.dataset_flow_identity_sha256(entry.value->'occurrences')
      is distinct from entry.value->>'occurrence_set_sha256'
    or entry.value->>'evidence_sha256' !~ '^[a-f0-9]{64}$'
    or entry.value->>'partition' not in ('pending', 'blockers', 'orphans')
    or exists (
      select 1
      from jsonb_array_elements(entry.value->'occurrences')
        with ordinality as occurrence(value, ordinality)
      where not private.dataset_flow_identity_exact_keys(
          occurrence.value,
          array[
            'process_id', 'process_version', 'exchange_index', 'internal_id',
            'direction', 'reference_sha256'
          ]
        )
        or occurrence.value->>'process_id'
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or occurrence.value->>'process_version'
          !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or jsonb_typeof(occurrence.value->'exchange_index') <> 'number'
        or (occurrence.value->>'exchange_index')::integer < 0
        or nullif(occurrence.value->>'internal_id', '') is null
        or occurrence.value->>'direction' not in ('Input', 'Output')
        or occurrence.value->>'reference_sha256' !~ '^[a-f0-9]{64}$'
    );

  if v_invalid > 0 or (
    select count(*)
    from (
      select distinct
        entry.value->>'source_id' as id,
        entry.value->>'source_version' as version
      from jsonb_array_elements(v_entries) as entry(value)
    ) as unique_entry
  ) <> jsonb_array_length(v_entries) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROTECTED_CLOSURE_ENTRY_MISMATCH'
    );
  end if;

  with wanted as (
    select
      entry.ordinality::integer as ordinal,
      (entry.value->>'source_id')::uuid as source_id,
      entry.value->>'source_version' as source_version,
      (entry.value->>'expected_reference_count')::integer
        as expected_reference_count,
      entry.value->'occurrences' as expected_occurrences,
      entry.value->>'occurrence_set_sha256' as occurrence_set_sha256,
      entry.value->>'evidence_sha256' as evidence_sha256,
      entry.value->>'partition' as partition
    from jsonb_array_elements(v_entries)
      with ordinality as entry(value, ordinality)
  ), live_occurrence as (
    select
      wanted.source_id,
      wanted.source_version,
      process.id as process_id,
      btrim(process.version::text) as process_version,
      (exchange.ordinality - 1)::integer as exchange_index,
      exchange.value->>'@dataSetInternalID' as internal_id,
      exchange.value->>'exchangeDirection' as direction,
      util.dataset_flow_identity_sha256(
        private.dataset_flow_identity_reference(exchange.value)
      ) as reference_sha256
    from public.processes as process
    cross join lateral jsonb_array_elements(
      private.dataset_flow_identity_exchanges(process.json_ordered::jsonb)
    ) with ordinality as exchange(value, ordinality)
    join wanted
      on wanted.source_id::text = exchange.value #>>
          '{referenceToFlowDataSet,@refObjectId}'
      and wanted.source_version = exchange.value #>>
          '{referenceToFlowDataSet,@version}'
    where process.user_id = p_actor
      and process.state_code = 0
  ), live as (
    select
      wanted.source_id,
      wanted.source_version,
      coalesce(jsonb_agg(jsonb_build_object(
        'process_id', live_occurrence.process_id,
        'process_version', live_occurrence.process_version,
        'exchange_index', live_occurrence.exchange_index,
        'internal_id', live_occurrence.internal_id,
        'direction', live_occurrence.direction,
        'reference_sha256', live_occurrence.reference_sha256
      ) order by
        live_occurrence.process_id,
        live_occurrence.process_version,
        live_occurrence.exchange_index
      ) filter (where live_occurrence.process_id is not null), '[]'::jsonb)
        as observed_occurrences
    from wanted
    left join live_occurrence using (source_id, source_version)
    group by wanted.source_id, wanted.source_version
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', wanted.ordinal,
      'partition', wanted.partition,
      'source_id', wanted.source_id,
      'source_version', wanted.source_version,
      'expected_reference_count', wanted.expected_reference_count,
      'observed_reference_count',
        jsonb_array_length(live.observed_occurrences),
      'evidence_sha256', wanted.evidence_sha256,
      'expected_occurrence_set_sha256', wanted.occurrence_set_sha256,
      'observed_occurrence_set_sha256',
        util.dataset_flow_identity_sha256(live.observed_occurrences),
      'matches', wanted.expected_occurrences = live.observed_occurrences
    ) order by wanted.ordinal), '[]'::jsonb),
    coalesce(sum(wanted.expected_reference_count), 0)::bigint,
    coalesce(sum(jsonb_array_length(live.observed_occurrences)), 0)::bigint
  into v_observed, v_expected_total, v_observed_total
  from wanted
  left join live using (source_id, source_version);

  return jsonb_build_object(
    'ok', v_expected_total = v_observed_total
      and not exists (
        select 1
        from jsonb_array_elements(v_observed) as observed(value)
        where coalesce((observed.value->>'matches')::boolean, false) is false
      )
      and v_expected_total =
        (p_closure->>'total_expected_reference_count')::bigint,
    'schema_version', 'dataset-flow-identity-protected-closure-proof.v1',
    'expected_total_reference_count', v_expected_total,
    'observed_total_reference_count', v_observed_total,
    'entries', v_observed,
    'observed_sha256', util.dataset_flow_identity_sha256(v_observed)
  );
exception when others then
  return jsonb_build_object(
    'ok', false,
    'code', 'FLOW_IDENTITY_PROTECTED_CLOSURE_INVALID',
    'sqlstate', sqlstate,
    'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_protected_closure(p_actor uuid, p_closure jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_restricted_sha256_v2(jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_restricted_sha256_v2(p_value jsonb) RETURNS text
    LANGUAGE plpgsql STABLE STRICT
    SET search_path TO ''
    AS $$
declare
  v_normalized jsonb;
begin
  v_normalized := private.dataset_flow_identity_safe_json_v2(p_value);
  if v_normalized is null then return null; end if;
  return encode(
    extensions.digest(
      convert_to(private.dataset_alias_canonical_jsonb_v1(v_normalized), 'UTF8'),
      'sha256'
    ),
    'hex'
  );
end;
$$;


ALTER FUNCTION util.dataset_flow_identity_restricted_sha256_v2(p_value jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_sha256(jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_sha256(p_value jsonb) RETURNS text
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
  select encode(
    extensions.digest(
      convert_to(private.dataset_alias_canonical_jsonb_v1(p_value), 'UTF8'),
      'sha256'
    ),
    'hex'
  )
$$;


ALTER FUNCTION util.dataset_flow_identity_sha256(p_value jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_source_universe(uuid, jsonb, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_source_universe(p_actor uuid, p_expected_universe jsonb, p_expected_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_live jsonb;
  v_invalid_count integer;
  v_live_sha256 text;
begin
  if p_actor is null
    or jsonb_typeof(p_expected_universe) <> 'array'
    or jsonb_array_length(p_expected_universe) <> 305
    or p_expected_sha256 !~ '^[a-f0-9]{64}$'
    or util.dataset_flow_identity_sha256(p_expected_universe)
      is distinct from p_expected_sha256
    or exists (
      select 1
      from jsonb_array_elements(p_expected_universe)
        with ordinality as item(value, ordinality)
      where not private.dataset_flow_identity_exact_keys(
          item.value,
          array['id', 'version', 'user_id', 'state_code', 'flow_type']
        )
        or item.value->>'id'
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or item.value->>'version'
          !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or item.value->>'user_id' <> p_actor::text
        or item.value->>'state_code' <> '0'
        or item.value->>'flow_type' <> 'Elementary flow'
    ) then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_SOURCE_UNIVERSE_SCHEMA_MISMATCH'
    );
  end if;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', flow.id,
      'version', btrim(flow.version::text),
      'user_id', flow.user_id,
      'state_code', flow.state_code,
      'flow_type', flow.json_ordered #>>
        '{flowDataSet,modellingAndValidation,LCIMethod,typeOfDataSet}'
    ) order by flow.id, btrim(flow.version::text)), '[]'::jsonb),
    count(*) filter (
      where flow.json is null
        or flow.json_ordered is null
        or flow.json::jsonb is distinct from flow.json_ordered::jsonb
        or flow.json_ordered #>>
          '{flowDataSet,flowInformation,dataSetInformation,common:UUID}'
          is distinct from flow.id::text
        or flow.json_ordered #>>
          '{flowDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
          is distinct from btrim(flow.version::text)
    )::integer
  into v_live, v_invalid_count
  from public.flows as flow
  where flow.user_id = p_actor
    and flow.state_code = 0
    and flow.json_ordered #>>
      '{flowDataSet,modellingAndValidation,LCIMethod,typeOfDataSet}'
      = 'Elementary flow';

  v_live_sha256 := util.dataset_flow_identity_sha256(v_live);
  return jsonb_build_object(
    'ok', v_invalid_count = 0
      and jsonb_array_length(v_live) = 305
      and v_live is not distinct from p_expected_universe
      and v_live_sha256 is not distinct from p_expected_sha256,
    'schema_version', 'dataset-flow-identity-source-universe-proof.v1',
    'expected_count', 305,
    'observed_count', jsonb_array_length(v_live),
    'expected_sha256', p_expected_sha256,
    'observed_sha256', v_live_sha256,
    'invalid_live_row_count', v_invalid_count
  );
exception when others then
  return jsonb_build_object(
    'ok', false, 'code', 'FLOW_IDENTITY_SOURCE_UNIVERSE_INVALID',
    'sqlstate', sqlstate, 'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_source_universe(p_actor uuid, p_expected_universe jsonb, p_expected_sha256 text) OWNER TO postgres;

--
-- Name: dataset_flow_identity_validate_flow_guard(uuid, jsonb, boolean, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_validate_flow_guard(p_actor uuid, p_guard jsonb, p_target boolean, p_support_snapshots jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_source_keys constant text[] := array[
    'id', 'version', 'user_id', 'state_code', 'modified_at',
    'payload_sha256', 'row_sha256', 'flow_type', 'flow_property_id',
    'flow_property_version', 'unit_group_id', 'unit_group_version',
    'category_path_sha256', 'source_trace_sha256'
  ];
  v_target_keys constant text[] := array[
    'id', 'version', 'user_id', 'state_code', 'modified_at',
    'payload_sha256', 'row_sha256', 'flow_type', 'flow_property_id',
    'flow_property_version', 'unit_group_id', 'unit_group_version',
    'category_path_sha256', 'reference'
  ];
  v_reference_keys constant text[] := array[
    '@refObjectId', '@type', '@uri', '@version',
    'common:shortDescription'
  ];
  v_flow public.flows%rowtype;
  v_flowproperty public.flowproperties%rowtype;
  v_unitgroup public.unitgroups%rowtype;
  v_payload_sha256 text;
  v_row_sha256 text;
  v_category_sha256 text;
  v_flow_properties jsonb;
  v_reference_flow_property_internal_id text;
  v_reference_unit_internal_id text;
  v_claimed_fp_id uuid;
  v_claimed_fp_version text;
  v_claimed_ug_id uuid;
  v_claimed_ug_version text;
  v_fp_snapshot jsonb;
  v_ug_snapshot jsonb;
  v_support_validation jsonb;
begin
  if p_actor is null
    or jsonb_typeof(p_support_snapshots) <> 'array'
    or not private.dataset_flow_identity_exact_keys(
      p_guard,
      case when p_target then v_target_keys else v_source_keys end
    )
    or p_guard->>'id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_guard->>'user_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_guard->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or p_guard->>'flow_property_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_guard->>'unit_group_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_guard->>'flow_property_version'
      !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or p_guard->>'unit_group_version'
      !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or p_guard->>'payload_sha256' !~ '^[a-f0-9]{64}$'
    or p_guard->>'row_sha256' !~ '^[a-f0-9]{64}$'
    or p_guard->>'category_path_sha256' !~ '^[a-f0-9]{64}$'
    or (not p_target
      and p_guard->>'source_trace_sha256' !~ '^[a-f0-9]{64}$')
    or p_guard->>'flow_type' <> 'Elementary flow'
    or jsonb_typeof(p_guard->'state_code') <> 'number'
    or (p_guard->>'state_code')::integer
      <> (case when p_target then 100 else 0 end)
    or (p_target and not private.dataset_flow_identity_exact_keys(
      p_guard->'reference', v_reference_keys
    )) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_FLOW_GUARD_SCHEMA_MISMATCH'
    );
  end if;

  begin
    perform (p_guard->>'modified_at')::timestamp with time zone;
    v_claimed_fp_id := (p_guard->>'flow_property_id')::uuid;
    v_claimed_fp_version := p_guard->>'flow_property_version';
    v_claimed_ug_id := (p_guard->>'unit_group_id')::uuid;
    v_claimed_ug_version := p_guard->>'unit_group_version';
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_FLOW_GUARD_VALUE_MISMATCH'
    );
  end;

  select flow.*
  into v_flow
  from public.flows as flow
  where flow.id = (p_guard->>'id')::uuid
    and btrim(flow.version::text) = p_guard->>'version';

  if v_flow.id is null
    or v_flow.json_ordered is null
    or v_flow.json is null
    or v_flow.json::jsonb is distinct from v_flow.json_ordered::jsonb
    or v_flow.user_id::text is distinct from p_guard->>'user_id'
    or v_flow.state_code is distinct from (p_guard->>'state_code')::integer
    or v_flow.modified_at is distinct from
      (p_guard->>'modified_at')::timestamp with time zone
    or (not p_target and v_flow.user_id is distinct from p_actor)
    or (p_target and (v_flow.user_id is null or v_flow.user_id = p_actor))
    or v_flow.json #>>
      '{flowDataSet,flowInformation,dataSetInformation,common:UUID}'
      is distinct from p_guard->>'id'
    or v_flow.json #>>
      '{flowDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from p_guard->>'version'
    or v_flow.json #>>
      '{flowDataSet,modellingAndValidation,LCIMethod,typeOfDataSet}'
      is distinct from 'Elementary flow' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_FLOW_GUARD_LIVE_MISMATCH'
    );
  end if;

  v_payload_sha256 := util.dataset_flow_identity_sha256(
    v_flow.json_ordered::jsonb
  );
  v_row_sha256 := private.dataset_flow_identity_row_sha256(
    v_flow.id,
    btrim(v_flow.version::text),
    v_flow.user_id,
    v_flow.state_code,
    v_flow.modified_at,
    v_payload_sha256
  );
  v_category_sha256 := util.dataset_flow_identity_sha256(coalesce(
    v_flow.json #>
      '{flowDataSet,flowInformation,dataSetInformation,classificationInformation}',
    'null'::jsonb
  ));

  if v_payload_sha256 is distinct from p_guard->>'payload_sha256'
    or v_row_sha256 is distinct from p_guard->>'row_sha256'
    or v_category_sha256 is distinct from p_guard->>'category_path_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_FLOW_GUARD_HASH_DRIFT'
    );
  end if;

  v_flow_properties := v_flow.json #>
    '{flowDataSet,flowProperties,flowProperty}';
  if jsonb_typeof(v_flow_properties) = 'object' then
    v_flow_properties := jsonb_build_array(v_flow_properties);
  end if;
  v_reference_flow_property_internal_id := v_flow.json #>>
    '{flowDataSet,flowInformation,quantitativeReference,referenceToReferenceFlowProperty}';
  if nullif(v_reference_flow_property_internal_id, '') is null
    or jsonb_typeof(v_flow_properties) <> 'array'
    or not exists (
      select 1
      from jsonb_array_elements(v_flow_properties) as fp(value)
      where fp.value->>'@dataSetInternalID'
          = v_reference_flow_property_internal_id
        and fp.value #>>
        '{referenceToFlowPropertyDataSet,@refObjectId}'
          = v_claimed_fp_id::text
        and fp.value #>>
          '{referenceToFlowPropertyDataSet,@version}'
          = v_claimed_fp_version
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_REFERENCE_FLOW_PROPERTY_MISMATCH'
    );
  end if;

  select flowproperty.*
  into v_flowproperty
  from public.flowproperties as flowproperty
  where flowproperty.id = v_claimed_fp_id
    and btrim(flowproperty.version::text) = v_claimed_fp_version
    and (
      flowproperty.state_code = 100
      or (flowproperty.user_id = p_actor and flowproperty.state_code = 0)
    );

  if v_flowproperty.id is null
    or v_flowproperty.json #>>
      '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@refObjectId}'
      is distinct from v_claimed_ug_id::text
    or v_flowproperty.json #>>
      '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@version}'
      is distinct from v_claimed_ug_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_REFERENCE_UNIT_GROUP_MISMATCH'
    );
  end if;

  select snapshot.value
  into v_fp_snapshot
  from jsonb_array_elements(p_support_snapshots) as snapshot(value)
  where snapshot.value->>'table' = 'flowproperties'
    and snapshot.value->>'id' = v_claimed_fp_id::text
    and snapshot.value->>'version' = v_claimed_fp_version;
  v_support_validation := util.dataset_flow_identity_validate_support_snapshot(
    p_actor, v_fp_snapshot
  );
  if v_fp_snapshot is null
    or coalesce((v_support_validation->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_FLOW_PROPERTY_SNAPSHOT_MISMATCH',
      'details', v_support_validation
    );
  end if;

  select unitgroup.*
  into v_unitgroup
  from public.unitgroups as unitgroup
  where unitgroup.id = v_claimed_ug_id
    and btrim(unitgroup.version::text) = v_claimed_ug_version
    and (
      unitgroup.state_code = 100
      or (unitgroup.user_id = p_actor and unitgroup.state_code = 0)
    );
  v_reference_unit_internal_id := v_unitgroup.json #>>
    '{unitGroupDataSet,unitGroupInformation,quantitativeReference,referenceToReferenceUnit}';

  if v_unitgroup.id is null
    or v_unitgroup.json #>>
      '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:UUID}'
      is distinct from v_claimed_ug_id::text
    or v_unitgroup.json #>>
      '{unitGroupDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_claimed_ug_version
    or nullif(v_reference_unit_internal_id, '') is null
    or not exists (
      select 1
      from jsonb_array_elements(
        case jsonb_typeof(v_unitgroup.json #>
          '{unitGroupDataSet,units,unit}')
          when 'array' then v_unitgroup.json #>
            '{unitGroupDataSet,units,unit}'
          when 'object' then jsonb_build_array(v_unitgroup.json #>
            '{unitGroupDataSet,units,unit}')
          else '[]'::jsonb
        end
      ) as unit_item(value)
      where unit_item.value->>'@dataSetInternalID'
          = v_reference_unit_internal_id
        and (unit_item.value->>'meanValue')::numeric = 1
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_REFERENCE_UNIT_MISMATCH'
    );
  end if;

  select snapshot.value
  into v_ug_snapshot
  from jsonb_array_elements(p_support_snapshots) as snapshot(value)
  where snapshot.value->>'table' = 'unitgroups'
    and snapshot.value->>'id' = v_claimed_ug_id::text
    and snapshot.value->>'version' = v_claimed_ug_version;
  v_support_validation := util.dataset_flow_identity_validate_support_snapshot(
    p_actor, v_ug_snapshot
  );
  if v_ug_snapshot is null
    or coalesce((v_support_validation->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_UNIT_GROUP_SNAPSHOT_MISMATCH',
      'details', v_support_validation
    );
  end if;

  if p_target and (
    p_guard #>> '{reference,@refObjectId}' is distinct from v_flow.id::text
    or p_guard #>> '{reference,@version}'
      is distinct from btrim(v_flow.version::text)
    or p_guard #>> '{reference,@type}' is distinct from 'flow data set'
    or p_guard #>> '{reference,@uri}' is distinct from
      '../flows/' || v_flow.id::text || '_'
        || btrim(v_flow.version::text) || '.xml'
    or jsonb_typeof(p_guard #> '{reference,common:shortDescription}')
      not in ('string', 'object', 'array')
    or not (
      private.dataset_flow_identity_text_values(
        p_guard #> '{reference,common:shortDescription}'
      ) && private.dataset_flow_identity_text_values(
        v_flow.json #>
          '{flowDataSet,flowInformation,dataSetInformation,name,baseName}'
      )
    )
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_TARGET_REFERENCE_MISMATCH'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'payload_sha256', v_payload_sha256,
    'row_sha256', v_row_sha256,
    'category_path_sha256', v_category_sha256
  );
exception when others then
  return jsonb_build_object(
    'ok', false,
    'code', 'FLOW_IDENTITY_FLOW_GUARD_INVALID',
    'sqlstate', sqlstate,
    'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_validate_flow_guard(p_actor uuid, p_guard jsonb, p_target boolean, p_support_snapshots jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_validate_mapping(uuid, jsonb, jsonb, jsonb, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_validate_mapping(p_actor uuid, p_mapping jsonb, p_policy jsonb, p_support_snapshots jsonb, p_expected_ordinal integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_mapping_keys constant text[] := array[
    'ordinal', 'mapping_id', 'source', 'target', 'compatibility'
  ];
  v_compatibility_keys constant text[] := array[
    'policy_sha256', 'mode', 'confidence', 'flow_property_compatible',
    'unit_group_compatible', 'direction_compatible',
    'compartment_compatible', 'conversion_factor', 'evidence_sha256',
    'flow_schema', 'process_schema_required'
  ];
  v_flow_schema_keys constant text[] := array[
    'status', 'warning_set_sha256'
  ];
  v_mapping_id text;
  v_source_result jsonb;
  v_target_result jsonb;
begin
  if p_actor is null
    or not private.dataset_flow_identity_exact_keys(
      p_mapping, v_mapping_keys
    )
    or jsonb_typeof(p_mapping->'ordinal') <> 'number'
    or (p_mapping->>'ordinal')::integer <> p_expected_ordinal
    or p_mapping->>'mapping_id' !~ '^[a-f0-9]{64}$'
    or not private.dataset_flow_identity_exact_keys(
      p_mapping->'compatibility', v_compatibility_keys
    )
    or not private.dataset_flow_identity_exact_keys(
      p_mapping #> '{compatibility,flow_schema}', v_flow_schema_keys
    )
    or p_mapping #>> '{compatibility,policy_sha256}'
      is distinct from p_policy->>'policy_sha256'
    or p_mapping #>> '{compatibility,mode}' <> 'identity'
    or p_mapping #>> '{compatibility,confidence}' <> 'approved'
    or p_mapping #>> '{compatibility,conversion_factor}' <> '1'
    or p_mapping #>> '{compatibility,evidence_sha256}'
      !~ '^[a-f0-9]{64}$'
    or p_mapping #>> '{compatibility,flow_schema,status}'
      not in ('pass', 'legacy_warning')
    or p_mapping #>> '{compatibility,flow_schema,warning_set_sha256}'
      !~ '^[a-f0-9]{64}$'
    or p_mapping #>> '{compatibility,process_schema_required}' <> 'pass'
    or exists (
      select 1
      from unnest(array[
        'flow_property_compatible', 'unit_group_compatible',
        'direction_compatible', 'compartment_compatible'
      ]) as boolean_field(name)
      where jsonb_typeof(
          p_mapping->'compatibility'->boolean_field.name
        ) <> 'boolean'
        or coalesce((
          p_mapping->'compatibility'->>boolean_field.name
        )::boolean, false) is false
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_MAPPING_SCHEMA_MISMATCH'
    );
  end if;

  v_mapping_id := util.dataset_flow_identity_restricted_sha256_v2(
    p_mapping - 'ordinal' - 'mapping_id'
  );
  if v_mapping_id is distinct from p_mapping->>'mapping_id' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_MAPPING_HASH_MISMATCH'
    );
  end if;

  v_source_result := util.dataset_flow_identity_validate_flow_guard(
    p_actor, p_mapping->'source', false, p_support_snapshots
  );
  if coalesce((v_source_result->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_MAPPING_SOURCE_REJECTED',
      'details', v_source_result
    );
  end if;

  v_target_result := util.dataset_flow_identity_validate_flow_guard(
    p_actor, p_mapping->'target', true, p_support_snapshots
  );
  if coalesce((v_target_result->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_MAPPING_TARGET_REJECTED',
      'details', v_target_result
    );
  end if;

  if p_mapping #>> '{source,id}' = p_mapping #>> '{target,id}'
    and p_mapping #>> '{source,version}'
      = p_mapping #>> '{target,version}' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_MAPPING_NOOP'
    );
  end if;

  if p_mapping #>> '{source,flow_property_id}'
      is distinct from p_mapping #>> '{target,flow_property_id}'
    or p_mapping #>> '{source,flow_property_version}'
      is distinct from p_mapping #>> '{target,flow_property_version}'
    or p_mapping #>> '{source,unit_group_id}'
      is distinct from p_mapping #>> '{target,unit_group_id}'
    or p_mapping #>> '{source,unit_group_version}'
      is distinct from p_mapping #>> '{target,unit_group_version}' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_MAPPING_NOT_IDENTITY_ONLY'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'mapping_id', v_mapping_id,
    'source', v_source_result,
    'target', v_target_result
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_validate_mapping(p_actor uuid, p_mapping jsonb, p_policy jsonb, p_support_snapshots jsonb, p_expected_ordinal integer) OWNER TO postgres;

--
-- Name: dataset_flow_identity_validate_process_guard(uuid, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_validate_process_guard(p_actor uuid, p_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_keys constant text[] := array[
    'ordinal', 'id', 'version', 'user_id', 'state_code', 'modified_at',
    'model_id', 'rule_verification',
    'before_row_sha256', 'before_payload_sha256',
    'before_exchange_set_sha256', 'before_exchange_count',
    'desired_payload_sha256', 'desired_exchange_set_sha256',
    'rewrite_count', 'process_template_sha256', 'rewrite_set_sha256',
    'rewrites', 'collision_ledger', 'collision_ledger_sha256',
    'derivative_baseline_snapshot_sha256',
    'process_schema', 'pending_blocker_closure_sha256'
  ];
  v_process public.processes%rowtype;
  v_payload jsonb;
  v_exchanges jsonb;
  v_payload_sha256 text;
  v_exchange_sha256 text;
  v_row_sha256 text;
  v_snapshot jsonb;
  v_template_sha256 text;
begin
  if p_actor is null
    or not private.dataset_flow_identity_exact_keys(p_manifest, v_keys)
    or jsonb_typeof(p_manifest->'ordinal') <> 'number'
    or (p_manifest->>'ordinal')::integer <= 0
    or p_manifest->>'id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_manifest->>'user_id' is distinct from p_actor::text
    or p_manifest->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or jsonb_typeof(p_manifest->'state_code') <> 'number'
    or (p_manifest->>'state_code')::integer <> 0
    or jsonb_typeof(p_manifest->'before_exchange_count') <> 'number'
    or jsonb_typeof(p_manifest->'rewrite_count') <> 'number'
    or (p_manifest->>'rewrite_count')::integer <= 0
    or jsonb_typeof(p_manifest->'rewrites') <> 'array'
    or jsonb_array_length(p_manifest->'rewrites')
      <> (p_manifest->>'rewrite_count')::integer
    or jsonb_typeof(p_manifest->'collision_ledger') <> 'object'
    or util.dataset_flow_identity_restricted_sha256_v2(p_manifest->'rewrites')
      is distinct from p_manifest->>'rewrite_set_sha256'
    or util.dataset_flow_identity_restricted_sha256_v2(
      p_manifest->'collision_ledger'
    )
      is distinct from p_manifest->>'collision_ledger_sha256'
    or not private.dataset_flow_identity_exact_keys(
      p_manifest->'process_schema', array['status', 'evidence_sha256']
    )
    or p_manifest #>> '{process_schema,status}' <> 'pass'
    or exists (
      select 1
      from unnest(array[
        'before_row_sha256', 'before_payload_sha256',
        'before_exchange_set_sha256', 'desired_payload_sha256',
        'desired_exchange_set_sha256', 'process_template_sha256',
        'rewrite_set_sha256', 'collision_ledger_sha256',
        'derivative_baseline_snapshot_sha256',
        'pending_blocker_closure_sha256'
      ]) as hash_field(name)
      where p_manifest->>hash_field.name !~ '^[a-f0-9]{64}$'
    )
    or p_manifest #>> '{process_schema,evidence_sha256}'
      !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_MANIFEST_SCHEMA_MISMATCH'
    );
  end if;

  if jsonb_typeof(p_manifest->'model_id') not in ('string', 'null')
    or (
      jsonb_typeof(p_manifest->'model_id') = 'string'
      and p_manifest->>'model_id'
        !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    or jsonb_typeof(p_manifest->'rule_verification')
      not in ('boolean', 'null') then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_METADATA_SCHEMA_MISMATCH'
    );
  end if;

  begin
    perform (p_manifest->>'modified_at')::timestamp with time zone;
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_MANIFEST_VALUE_MISMATCH'
    );
  end;

  v_template_sha256 := util.dataset_flow_identity_restricted_sha256_v2(
    p_manifest - 'process_template_sha256'
  );
  if v_template_sha256 is distinct from
    p_manifest->>'process_template_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_TEMPLATE_HASH_MISMATCH'
    );
  end if;

  select process.*
  into v_process
  from public.processes as process
  where process.id = (p_manifest->>'id')::uuid
    and btrim(process.version::text) = p_manifest->>'version'
    and process.user_id = p_actor
    and process.state_code = 0;

  if v_process.id is null
    or v_process.json is null
    or v_process.json_ordered is null
    or v_process.json::jsonb is distinct from v_process.json_ordered::jsonb
    or v_process.modified_at is distinct from
      (p_manifest->>'modified_at')::timestamp with time zone
    or coalesce(to_jsonb(v_process.model_id), 'null'::jsonb)
      is distinct from p_manifest->'model_id'
    or coalesce(to_jsonb(v_process.rule_verification), 'null'::jsonb)
      is distinct from p_manifest->'rule_verification' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_SCOPE_MISMATCH'
    );
  end if;

  v_payload := v_process.json_ordered::jsonb;
  v_exchanges := private.dataset_flow_identity_exchanges(v_payload);
  if v_exchanges is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_EXCHANGES_INVALID'
    );
  end if;

  v_payload_sha256 := util.dataset_flow_identity_sha256(v_payload);
  v_exchange_sha256 := util.dataset_flow_identity_sha256(v_exchanges);
  v_row_sha256 := util.dataset_flow_identity_sha256(jsonb_build_object(
    'id', v_process.id,
    'version', btrim(v_process.version::text),
    'user_id', v_process.user_id,
    'state_code', v_process.state_code,
    'modified_at', v_process.modified_at,
    'model_id', v_process.model_id,
    'rule_verification', v_process.rule_verification,
    'payload_sha256', v_payload_sha256
  ));
  begin
    v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
  exception when others then
    v_snapshot := null;
  end;

  if v_payload_sha256 is distinct from
      p_manifest->>'before_payload_sha256'
    or v_exchange_sha256 is distinct from
      p_manifest->>'before_exchange_set_sha256'
    or v_row_sha256 is distinct from p_manifest->>'before_row_sha256'
    or jsonb_array_length(v_exchanges) is distinct from
      (p_manifest->>'before_exchange_count')::integer
    or v_snapshot is null
    or v_snapshot->>'snapshot_sha256' is distinct from
      p_manifest->>'derivative_baseline_snapshot_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'FLOW_IDENTITY_PROCESS_BASELINE_DRIFT'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'payload_sha256', v_payload_sha256,
    'exchange_set_sha256', v_exchange_sha256,
    'row_sha256', v_row_sha256,
    'derivative_snapshot_sha256', v_snapshot->>'snapshot_sha256'
  );
exception when others then
  return jsonb_build_object(
    'ok', false,
    'code', 'FLOW_IDENTITY_PROCESS_MANIFEST_INVALID',
    'sqlstate', sqlstate,
    'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_validate_process_guard(p_actor uuid, p_manifest jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_validate_support_set(uuid, jsonb, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_validate_support_set(p_actor uuid, p_snapshots jsonb, p_expected_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_snapshot jsonb;
  v_validation jsonb;
  v_count integer;
begin
  if p_actor is null
    or jsonb_typeof(p_snapshots) <> 'array'
    or jsonb_array_length(p_snapshots) not between 2 and 100
    or p_expected_sha256 !~ '^[a-f0-9]{64}$'
    or util.dataset_flow_identity_sha256(p_snapshots)
      is distinct from p_expected_sha256 then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SET_SCHEMA_MISMATCH'
    );
  end if;
  v_count := jsonb_array_length(p_snapshots);
  if (
    select count(distinct (
      (item.value->>'table') || ':' || (item.value->>'id') || '@'
        || (item.value->>'version')
    )) = v_count
      and min((item.value->>'ordinal')::integer) = 1
      and max((item.value->>'ordinal')::integer) = v_count
      and bool_and(
        (item.value->>'ordinal')::integer = item.ordinality::integer
      )
    from jsonb_array_elements(p_snapshots)
      with ordinality as item(value, ordinality)
  ) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SET_IDENTITY_MISMATCH'
    );
  end if;
  for v_snapshot in
    select item.value
    from jsonb_array_elements(p_snapshots)
      with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    v_validation := util.dataset_flow_identity_validate_support_snapshot(
      p_actor, v_snapshot
    );
    if coalesce((v_validation->>'ok')::boolean, false) is false then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SET_LIVE_MISMATCH',
        'details', v_validation
      );
    end if;
  end loop;
  return jsonb_build_object(
    'ok', true, 'support_count', v_count,
    'support_snapshot_set_sha256', p_expected_sha256
  );
exception when others then
  return jsonb_build_object(
    'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SET_INVALID',
    'sqlstate', sqlstate, 'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_validate_support_set(p_actor uuid, p_snapshots jsonb, p_expected_sha256 text) OWNER TO postgres;

--
-- Name: dataset_flow_identity_validate_support_snapshot(uuid, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.dataset_flow_identity_validate_support_snapshot(p_actor uuid, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_keys constant text[] := array[
    'ordinal', 'table', 'id', 'version', 'user_id', 'state_code',
    'modified_at', 'payload_sha256', 'row_sha256'
  ];
  v_flowproperty public.flowproperties%rowtype;
  v_unitgroup public.unitgroups%rowtype;
  v_payload jsonb;
  v_payload_sha256 text;
  v_row_sha256 text;
  v_live_user_id uuid;
  v_live_state_code integer;
  v_live_modified_at timestamp with time zone;
  v_embedded_id text;
  v_embedded_version text;
begin
  if p_actor is null
    or not private.dataset_flow_identity_exact_keys(p_snapshot, v_keys)
    or p_snapshot->>'ordinal' !~ '^[1-9][0-9]*$'
    or p_snapshot->>'table' not in ('flowproperties', 'unitgroups')
    or p_snapshot->>'id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_snapshot->>'user_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_snapshot->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or p_snapshot->>'state_code' not in ('0', '100')
    or p_snapshot->>'payload_sha256' !~ '^[a-f0-9]{64}$'
    or p_snapshot->>'row_sha256' !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SNAPSHOT_SCHEMA_MISMATCH'
    );
  end if;

  begin
    perform (p_snapshot->>'modified_at')::timestamp with time zone;
  exception when others then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SNAPSHOT_VALUE_MISMATCH'
    );
  end;

  if p_snapshot->>'table' = 'flowproperties' then
    select support.*
    into v_flowproperty
    from public.flowproperties as support
    where support.id = (p_snapshot->>'id')::uuid
      and btrim(support.version::text) = p_snapshot->>'version';
    if v_flowproperty.id is null
      or v_flowproperty.json is null or v_flowproperty.json_ordered is null
      or v_flowproperty.json::jsonb
        is distinct from v_flowproperty.json_ordered::jsonb then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_JSON_PARITY_MISMATCH'
      );
    end if;
    v_payload := v_flowproperty.json_ordered::jsonb;
    v_live_user_id := v_flowproperty.user_id;
    v_live_state_code := v_flowproperty.state_code;
    v_live_modified_at := v_flowproperty.modified_at;
    v_embedded_id := v_payload #>>
      '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:UUID}';
    v_embedded_version := v_payload #>>
      '{flowPropertyDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}';
  else
    select support.*
    into v_unitgroup
    from public.unitgroups as support
    where support.id = (p_snapshot->>'id')::uuid
      and btrim(support.version::text) = p_snapshot->>'version';
    if v_unitgroup.id is null
      or v_unitgroup.json is null or v_unitgroup.json_ordered is null
      or v_unitgroup.json::jsonb
        is distinct from v_unitgroup.json_ordered::jsonb then
      return jsonb_build_object(
        'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_JSON_PARITY_MISMATCH'
      );
    end if;
    v_payload := v_unitgroup.json_ordered::jsonb;
    v_live_user_id := v_unitgroup.user_id;
    v_live_state_code := v_unitgroup.state_code;
    v_live_modified_at := v_unitgroup.modified_at;
    v_embedded_id := v_payload #>>
      '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:UUID}';
    v_embedded_version := v_payload #>>
      '{unitGroupDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}';
  end if;

  v_payload_sha256 := util.dataset_flow_identity_sha256(v_payload);
  v_row_sha256 := private.dataset_flow_identity_row_sha256(
    (p_snapshot->>'id')::uuid,
    p_snapshot->>'version',
    v_live_user_id,
    v_live_state_code,
    v_live_modified_at,
    v_payload_sha256
  );
  if v_live_user_id::text is distinct from p_snapshot->>'user_id'
    or v_live_state_code::text is distinct from p_snapshot->>'state_code'
    or v_live_modified_at is distinct from
      (p_snapshot->>'modified_at')::timestamp with time zone
    or (v_live_state_code = 0 and v_live_user_id is distinct from p_actor)
    or v_live_state_code not in (0, 100)
    or v_embedded_id is distinct from p_snapshot->>'id'
    or v_embedded_version is distinct from p_snapshot->>'version'
    or v_payload_sha256 is distinct from p_snapshot->>'payload_sha256'
    or v_row_sha256 is distinct from p_snapshot->>'row_sha256' then
    return jsonb_build_object(
      'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SNAPSHOT_LIVE_MISMATCH'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'table', p_snapshot->>'table',
    'id', p_snapshot->>'id',
    'version', p_snapshot->>'version',
    'payload_sha256', v_payload_sha256,
    'row_sha256', v_row_sha256
  );
exception when others then
  return jsonb_build_object(
    'ok', false, 'code', 'FLOW_IDENTITY_SUPPORT_SNAPSHOT_INVALID',
    'sqlstate', sqlstate, 'message', sqlerrm
  );
end;
$_$;


ALTER FUNCTION util.dataset_flow_identity_validate_support_snapshot(p_actor uuid, p_snapshot jsonb) OWNER TO postgres;

--
-- Name: embedding_queue_policy_for(text, text, text, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.embedding_queue_policy_for(p_schema_name text, p_table_name text, p_edge_function text, p_embedding_column text) RETURNS TABLE(mode text, max_in_flight integer, max_read_count integer, retry_backoff_seconds integer)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select
    p.mode,
    p.max_in_flight,
    p.max_read_count,
    p.retry_backoff_seconds
  from util.embedding_queue_policy p
  where p.scope_schema in ('*', coalesce(p_schema_name, ''))
    and p.scope_table in ('*', coalesce(p_table_name, ''))
    and p.scope_edge_function in ('*', coalesce(p_edge_function, 'embedding'))
    and p.scope_embedding_column in ('*', coalesce(p_embedding_column, ''))
  order by
    (
      (p.scope_schema <> '*')::integer
      + (p.scope_table <> '*')::integer
      + (p.scope_edge_function <> '*')::integer
      + (p.scope_embedding_column <> '*')::integer
    ) desc,
    p.updated_at desc,
    p.id desc
  limit 1
$$;


ALTER FUNCTION util.embedding_queue_policy_for(p_schema_name text, p_table_name text, p_edge_function text, p_embedding_column text) OWNER TO postgres;

--
-- Name: enqueue_pending_embeddings(integer, text, text, text, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.enqueue_pending_embeddings(p_limit integer DEFAULT 100, p_schema_name text DEFAULT NULL::text, p_table_name text DEFAULT NULL::text, p_edge_function text DEFAULT NULL::text, p_embedding_column text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pending_job record;
  sent_count integer := 0;
  sent_msg_id bigint;
begin
  if p_limit <= 0 then
    return 0;
  end if;

  if not pg_try_advisory_xact_lock(hashtext('util.enqueue_pending_embeddings')) then
    return 0;
  end if;

  for pending_job in
    select pending.*
    from util.pending_embedding_jobs pending
    cross join lateral util.embedding_queue_policy_for(
      pending.schema_name,
      pending.table_name,
      pending.edge_function,
      pending.embedding_column
    ) p
    where pending.status = 'pending'
      and p.mode <> 'paused'
      and (p_schema_name is null or pending.schema_name = p_schema_name)
      and (p_table_name is null or pending.table_name = p_table_name)
      and (p_edge_function is null or pending.edge_function = p_edge_function)
      and (p_embedding_column is null or pending.embedding_column = p_embedding_column)
    order by pending.created_at, pending.id
    limit p_limit
    for update skip locked
  loop
    select pgmq.send(
      queue_name => 'embedding_jobs',
      msg => pending_job.message
    )
    into sent_msg_id;

    update util.pending_embedding_jobs
    set
      status = 'enqueued',
      queue_msg_id = sent_msg_id,
      enqueued_at = now(),
      updated_at = now()
    where id = pending_job.id;

    sent_count := sent_count + 1;
  end loop;

  return sent_count;
end;
$$;


ALTER FUNCTION util.enqueue_pending_embeddings(p_limit integer, p_schema_name text, p_table_name text, p_edge_function text, p_embedding_column text) OWNER TO postgres;

--
-- Name: FUNCTION enqueue_pending_embeddings(p_limit integer, p_schema_name text, p_table_name text, p_edge_function text, p_embedding_column text); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.enqueue_pending_embeddings(p_limit integer, p_schema_name text, p_table_name text, p_edge_function text, p_embedding_column text) IS 'Enqueues pending embedding jobs in bounded batches; paused policies are not enqueued.';


--
-- Name: fail_dataset_derivative_rebuild_after_drain(uuid, text, text, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.fail_dataset_derivative_rebuild_after_drain(p_request_id uuid, p_code text, p_message text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_quarantine jsonb;
  v_now timestamp with time zone := pg_catalog.clock_timestamp();
begin
  select request.*
  into v_request
  from util.dataset_derivative_rebuild_requests as request
  where request.id = p_request_id
    and request.status not in ('completed', 'stale', 'failed')
  for update;

  if v_request.id is null then
    return;
  end if;

  v_quarantine := util.quarantine_dataset_derivative_rebuild_target(
    v_request.target_table,
    v_request.target_id,
    v_request.target_version
  );

  update util.dataset_derivative_rebuild_proposals
  set
    status = 'discarded',
    discarded_at = v_now
  where request_id = v_request.id
    and status in ('captured', 'accepted');

  update util.dataset_derivative_rebuild_requests
  set
    status = 'dispatching',
    phase = 'failure_draining',
    failure_release_not_before = coalesce(
      v_request.failure_release_not_before,
      v_now + interval '420 seconds'
    ),
    last_error = coalesce(
      v_request.last_error,
      jsonb_build_object(
        'code', p_code,
        'message', p_message,
        'details', coalesce(p_details, '{}'::jsonb)
      )
    ),
    quarantined_http_requests = quarantined_http_requests
      + coalesce((v_quarantine->>'http_requests')::integer, 0),
    quarantined_embedding_jobs = quarantined_embedding_jobs
      + coalesce((v_quarantine->>'embedding_jobs')::integer, 0),
    quarantined_pending_jobs = quarantined_pending_jobs
      + coalesce((v_quarantine->>'pending_jobs')::integer, 0),
    updated_at = v_now
  where id = p_request_id
    and status not in ('completed', 'stale', 'failed');
end;
$$;


ALTER FUNCTION util.fail_dataset_derivative_rebuild_after_drain(p_request_id uuid, p_code text, p_message text, p_details jsonb) OWNER TO postgres;

--
-- Name: guard_dataset_derivative_rebuild_embedding_visibility(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.guard_dataset_derivative_rebuild_embedding_visibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from util.dataset_derivative_rebuild_requests as request
    where request.id::text = new.message->>'requestId'
      and request.target_table = new.message->>'table'
      and request.target_table in ('flows', 'processes')
      and request.target_id::text = new.message->>'id'
      and request.target_version = btrim(new.message->>'version')
      and new.message->>'schema' = 'public'
      and new.message->>'embeddingColumn' = 'embedding_ft'
      and request.status not in ('completed', 'stale', 'failed')
  ) then
    new.vt := greatest(
      new.vt,
      pg_catalog.clock_timestamp() + interval '420 seconds'
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION util.guard_dataset_derivative_rebuild_embedding_visibility() OWNER TO postgres;

--
-- Name: guard_dataset_derivative_rebuild_primary(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.guard_dataset_derivative_rebuild_primary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id uuid;
begin
  if tg_table_schema <> 'public'
    or tg_table_name not in ('flows', 'processes') then
    raise exception using
      errcode = '22023',
      message = 'Unsupported derivative rebuild fence target';
  end if;

  select request.id
  into v_request_id
  from util.dataset_derivative_rebuild_requests as request
  where request.target_table = tg_table_name
    and request.target_id = old.id
    and request.target_version = btrim(old.version::text)
    and request.status not in ('completed', 'stale', 'failed')
  limit 1;

  if v_request_id is not null then
    raise exception using
      errcode = '55006',
      message = case tg_table_name
        when 'processes'
          then 'Process primary row is fenced by an active derivative rebuild'
        else 'Flow primary row is fenced by an active derivative rebuild'
      end,
      detail = v_request_id::text;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION util.guard_dataset_derivative_rebuild_primary() OWNER TO postgres;

--
-- Name: invoke_edge_function(text, jsonb, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.invoke_edge_function(name text, body jsonb, timeout_milliseconds integer DEFAULT ((5 * 60) * 1000)) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  service_key text;
begin
  service_key := util.project_secret_key();

  perform net.http_post(
    url => util.project_url() || '/functions/v1/' || name,
    headers => jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_key,
      'apikey', service_key,
      'x_region', 'us-east-1'
    ),
    body => body,
    timeout_milliseconds => timeout_milliseconds
  );
end;
$$;


ALTER FUNCTION util.invoke_edge_function(name text, body jsonb, timeout_milliseconds integer) OWNER TO postgres;

--
-- Name: invoke_edge_webhook(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.invoke_edge_webhook() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  edge_function text := TG_ARGV[0];
  timeout_milliseconds integer := coalesce(nullif(TG_ARGV[1], '')::integer, 1000);
  payload jsonb;
begin
  if edge_function is null or edge_function = '' then
    raise exception 'Missing webhook edge function name';
  end if;

  payload := jsonb_build_object(
    'type', TG_OP,
    'schema', TG_TABLE_SCHEMA,
    'table', TG_TABLE_NAME,
    'record', case when TG_OP = 'DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end,
    'old_record', case when TG_OP = 'INSERT' then null else to_jsonb(OLD) end
  );

  perform util.invoke_edge_function(
    name => edge_function,
    body => payload,
    timeout_milliseconds => timeout_milliseconds
  );

  if TG_OP = 'DELETE' then
    return OLD;
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION util.invoke_edge_webhook() OWNER TO postgres;

--
-- Name: is_service_request(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.is_service_request() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text;
  v_claims jsonb;
  v_headers jsonb;
  v_api_key text;
  v_authorization text;
  v_bearer_token text;
  v_project_secret_key text;
begin
  v_role := nullif(current_setting('request.jwt.claim.role', true), '');

  if v_role = 'service_role' then
    return true;
  end if;

  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  exception when others then
    v_claims := null;
  end;

  if v_claims->>'role' = 'service_role' then
    return true;
  end if;

  begin
    v_headers := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    v_headers := null;
  end;

  if v_headers is null then
    return false;
  end if;

  select h.value #>> '{}'
  into v_api_key
  from jsonb_each(v_headers) as h(key, value)
  where lower(h.key) = 'apikey'
  limit 1;

  select h.value #>> '{}'
  into v_authorization
  from jsonb_each(v_headers) as h(key, value)
  where lower(h.key) = 'authorization'
  limit 1;

  if v_authorization ~* '^bearer[[:space:]]+' then
    v_bearer_token := regexp_replace(v_authorization, '^bearer[[:space:]]+', '', 'i');
  end if;

  if nullif(v_api_key, '') is null and nullif(v_bearer_token, '') is null then
    return false;
  end if;

  begin
    v_project_secret_key := util.project_secret_key();
  exception when others then
    return false;
  end;

  return nullif(v_project_secret_key, '') is not null
    and (
      coalesce(v_api_key = v_project_secret_key, false)
      or coalesce(v_bearer_token = v_project_secret_key, false)
    );
end;
$$;


ALTER FUNCTION util.is_service_request() OWNER TO postgres;

--
-- Name: FUNCTION is_service_request(); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.is_service_request() IS 'Returns true for service-role Data API requests, including legacy JWT claim GUCs, request.jwt.claims, and branch-local project_secret_key headers.';


--
-- Name: list_lca_snapshot_gc_candidates(interval, interval, timestamp with time zone, integer, integer, bigint); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.list_lca_snapshot_gc_candidates(p_preview_retention interval DEFAULT '30 days'::interval, p_draft_retention interval DEFAULT '7 days'::interval, p_as_of timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 500, p_keep_latest_per_scope integer DEFAULT 1, p_max_total_bytes bigint DEFAULT NULL::bigint) RETURNS TABLE(candidate_type text, snapshot_id uuid, snapshot_directory text, bucket_id text, object_name text, storage_bytes bigint, reason text, delete_db_snapshot boolean, snapshot_status text, snapshot_created_at timestamp with time zone, snapshot_updated_at timestamp with time zone, effective_expires_at timestamp with time zone, object_count bigint, snapshot_storage_bytes bigint, downstream_active_count bigint, downstream_job_count bigint, downstream_result_count bigint, downstream_cache_count bigint, downstream_latest_count bigint, downstream_factorization_count bigint, downstream_artifact_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select candidate.*
  from util.list_lca_snapshot_gc_candidates_without_closure_protection(
    p_preview_retention,
    p_draft_retention,
    p_as_of,
    p_limit,
    p_keep_latest_per_scope,
    p_max_total_bytes
  ) candidate
  where not exists (
    select 1
    from public.lcia_scope_closure_checks closure_check
    where closure_check.snapshot_id = candidate.snapshot_id
      and closure_check.status = 'passed'
      and closure_check.scan_completeness = 'complete'
      and closure_check.certificate_status = 'valid'
  )
  and not exists (
    select 1
    from public.lcia_result_packages package
    where package.snapshot_id = candidate.snapshot_id
  )
  and not exists (
    select 1
    from public.lca_results result
    where result.snapshot_id = candidate.snapshot_id
  )
$$;


ALTER FUNCTION util.list_lca_snapshot_gc_candidates(p_preview_retention interval, p_draft_retention interval, p_as_of timestamp with time zone, p_limit integer, p_keep_latest_per_scope integer, p_max_total_bytes bigint) OWNER TO postgres;

--
-- Name: list_lca_snapshot_gc_candidates_without_closure_protection(interval, interval, timestamp with time zone, integer, integer, bigint); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.list_lca_snapshot_gc_candidates_without_closure_protection(p_snapshot_retention_window interval DEFAULT '30 days'::interval, p_orphan_retention_window interval DEFAULT '30 days'::interval, p_as_of timestamp with time zone DEFAULT now(), p_max_snapshots integer DEFAULT 100, p_max_orphan_dirs integer DEFAULT 200, p_max_bytes bigint DEFAULT '2147483648'::bigint) RETURNS TABLE(candidate_type text, snapshot_id uuid, snapshot_directory text, bucket_id text, object_name text, storage_bytes bigint, reason text, delete_db_snapshot boolean, snapshot_status text, snapshot_created_at timestamp with time zone, snapshot_updated_at timestamp with time zone, effective_expires_at timestamp with time zone, object_count bigint, snapshot_storage_bytes bigint, downstream_active_count bigint, downstream_job_count bigint, downstream_result_count bigint, downstream_cache_count bigint, downstream_latest_count bigint, downstream_factorization_count bigint, downstream_artifact_count bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
begin
  if p_as_of is null then
    raise exception using
      errcode = '22023',
      message = 'snapshot GC candidate as_of timestamp must not be null';
  end if;

  if p_snapshot_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'snapshot retention window must be at least 1 day';
  end if;

  if p_orphan_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'orphan snapshot storage retention window must be at least 1 day';
  end if;

  if p_max_snapshots <= 0 then
    raise exception using
      errcode = '22023',
      message = 'snapshot GC max_snapshots must be greater than zero';
  end if;

  if p_max_orphan_dirs <= 0 then
    raise exception using
      errcode = '22023',
      message = 'snapshot GC max_orphan_dirs must be greater than zero';
  end if;

  if p_max_bytes <= 0 then
    raise exception using
      errcode = '22023',
      message = 'snapshot GC max_bytes must be greater than zero';
  end if;

  return query
  with storage_objects as (
    select
      objects.bucket_id,
      objects.name as object_name,
      case
        when objects.name ~ '^lca-results/snapshots/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/'
          then substring(objects.name from '^lca-results/snapshots/([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/')::uuid
        else null::uuid
      end as parsed_snapshot_id,
      nullif(split_part(objects.name, '/', 3), '') as snapshot_directory,
      coalesce(
        case
          when jsonb_typeof(objects.metadata -> 'size') = 'number'
            or coalesce(objects.metadata ->> 'size', '') ~ '^[0-9]+$'
            then (objects.metadata ->> 'size')::bigint
          else null::bigint
        end,
        0
      ) as storage_bytes,
      coalesce(objects.created_at, objects.updated_at) as object_created_at,
      coalesce(objects.updated_at, objects.created_at) as object_updated_at
    from storage.objects as objects
    where objects.bucket_id = 'lca_results'
      and objects.name like 'lca-results/snapshots/%'
  ),
  storage_directories as (
    select
      storage_objects.bucket_id,
      storage_objects.parsed_snapshot_id,
      storage_objects.snapshot_directory,
      count(*)::bigint as object_count,
      coalesce(sum(storage_objects.storage_bytes), 0)::bigint as total_storage_bytes,
      min(coalesce(storage_objects.object_created_at, storage_objects.object_updated_at)) as oldest_object_at,
      max(coalesce(storage_objects.object_created_at, storage_objects.object_updated_at)) as newest_object_at
    from storage_objects
    group by
      storage_objects.bucket_id,
      storage_objects.parsed_snapshot_id,
      storage_objects.snapshot_directory
  ),
  active_refs as (
    select lca_active_snapshots.snapshot_id, count(*)::bigint as active_ref_count
    from public.lca_active_snapshots
    group by lca_active_snapshots.snapshot_id
  ),
  worker_job_ref_candidates as (
    select distinct
      jobs.id as worker_job_id,
      case
        when refs.snapshot_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then refs.snapshot_text::uuid
        else null::uuid
      end as snapshot_id
    from public.worker_jobs as jobs
    cross join lateral (
      values
        (jobs.payload_json #>> '{snapshot,id}'),
        (jobs.payload_json #>> '{snapshotId}'),
        (jobs.payload_json #>> '{snapshot_id}'),
        (jobs.result_json #>> '{snapshot,id}'),
        (jobs.result_json #>> '{snapshotId}'),
        (jobs.result_json #>> '{snapshot_id}')
    ) as refs(snapshot_text)
    where jobs.job_kind like 'lca.%'
  ),
  job_refs as (
    select
      worker_job_ref_candidates.snapshot_id,
      count(distinct worker_job_ref_candidates.worker_job_id)::bigint as job_ref_count
    from worker_job_ref_candidates
    where worker_job_ref_candidates.snapshot_id is not null
    group by worker_job_ref_candidates.snapshot_id
  ),
  result_refs as (
    select lca_results.snapshot_id, count(*)::bigint as result_ref_count
    from public.lca_results
    group by lca_results.snapshot_id
  ),
  cache_refs as (
    select lca_result_cache.snapshot_id, count(*)::bigint as cache_ref_count
    from public.lca_result_cache
    group by lca_result_cache.snapshot_id
  ),
  latest_refs as (
    select lca_latest_all_unit_results.snapshot_id, count(*)::bigint as latest_ref_count
    from public.lca_latest_all_unit_results
    group by lca_latest_all_unit_results.snapshot_id
  ),
  factorization_refs as (
    select lca_factorization_registry.snapshot_id, count(*)::bigint as factorization_ref_count
    from public.lca_factorization_registry
    group by lca_factorization_registry.snapshot_id
  ),
  artifact_refs as (
    select lca_snapshot_artifacts.snapshot_id, count(*)::bigint as artifact_ref_count
    from public.lca_snapshot_artifacts
    group by lca_snapshot_artifacts.snapshot_id
  ),
  classified as (
    select
      storage_directories.bucket_id,
      storage_directories.parsed_snapshot_id,
      storage_directories.snapshot_directory,
      snapshots.id as snapshot_id,
      snapshots.status as snapshot_status,
      snapshots.created_at as snapshot_created_at,
      snapshots.updated_at as snapshot_updated_at,
      snapshot_ttl.expires_at_utc as effective_expires_at,
      storage_directories.object_count,
      storage_directories.total_storage_bytes,
      coalesce(active_refs.active_ref_count, 0)::bigint as active_ref_count,
      coalesce(job_refs.job_ref_count, 0)::bigint as job_ref_count,
      coalesce(result_refs.result_ref_count, 0)::bigint as result_ref_count,
      coalesce(cache_refs.cache_ref_count, 0)::bigint as cache_ref_count,
      coalesce(latest_refs.latest_ref_count, 0)::bigint as latest_ref_count,
      coalesce(factorization_refs.factorization_ref_count, 0)::bigint as factorization_ref_count,
      coalesce(artifact_refs.artifact_ref_count, 0)::bigint as artifact_ref_count,
      coalesce(snapshots.updated_at, snapshots.created_at, storage_directories.oldest_object_at) as oldest_observed_at,
      coalesce(snapshots.updated_at, snapshots.created_at, storage_directories.newest_object_at) as newest_observed_at,
      case
        when storage_directories.parsed_snapshot_id is null then 'protected_unparsed_storage_path'
        when snapshots.id is null
          and storage_directories.newest_object_at >= p_as_of - p_orphan_retention_window
          then 'protected_inside_retention_window'
        when snapshots.id is null then 'eligible_orphan_storage_directory'
        when coalesce(active_refs.active_ref_count, 0) > 0 then 'protected_active_snapshot'
        when snapshot_ttl.expires_at_utc is not null
          and snapshot_ttl.expires_at_utc > p_as_of
          then 'protected_ttl_future'
        when snapshot_ttl.expires_at_utc is not null then 'eligible_ttl_expired_snapshot'
        when coalesce(snapshots.updated_at, snapshots.created_at) >= p_as_of - p_snapshot_retention_window
          then 'protected_inside_retention_window'
        else 'eligible_default_30d_snapshot'
      end as reason
    from storage_directories
    left join public.lca_network_snapshots as snapshots
      on snapshots.id = storage_directories.parsed_snapshot_id
    left join lateral (
      select case
        when coalesce(snapshots.process_filter #>> '{artifact_lifecycle,expires_at_utc}', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T]'
          then (snapshots.process_filter #>> '{artifact_lifecycle,expires_at_utc}')::timestamp with time zone
        else null::timestamp with time zone
      end as expires_at_utc
    ) as snapshot_ttl on true
    left join active_refs
      on active_refs.snapshot_id = snapshots.id
    left join job_refs
      on job_refs.snapshot_id = snapshots.id
    left join result_refs
      on result_refs.snapshot_id = snapshots.id
    left join cache_refs
      on cache_refs.snapshot_id = snapshots.id
    left join latest_refs
      on latest_refs.snapshot_id = snapshots.id
    left join factorization_refs
      on factorization_refs.snapshot_id = snapshots.id
    left join artifact_refs
      on artifact_refs.snapshot_id = snapshots.id
  ),
  selected_snapshot_directories as (
    select classified.*
    from classified
    where classified.snapshot_id is not null
      and classified.reason in ('eligible_ttl_expired_snapshot', 'eligible_default_30d_snapshot')
    order by classified.newest_observed_at asc, classified.snapshot_id
    limit p_max_snapshots
  ),
  selected_orphan_directories as (
    select classified.*
    from classified
    where classified.snapshot_id is null
      and classified.parsed_snapshot_id is not null
      and classified.reason = 'eligible_orphan_storage_directory'
    order by classified.newest_observed_at asc, classified.snapshot_directory
    limit p_max_orphan_dirs
  ),
  selected_directories as (
    select
      'snapshot_directory'::text as candidate_type,
      true as delete_db_snapshot,
      selected_snapshot_directories.*
    from selected_snapshot_directories
    union all
    select
      'orphan_storage_directory'::text as candidate_type,
      false as delete_db_snapshot,
      selected_orphan_directories.*
    from selected_orphan_directories
  ),
  candidate_objects as (
    select
      selected_directories.candidate_type,
      coalesce(selected_directories.snapshot_id, selected_directories.parsed_snapshot_id) as snapshot_id,
      selected_directories.snapshot_directory,
      selected_directories.bucket_id,
      storage_objects.object_name,
      storage_objects.storage_bytes,
      selected_directories.reason,
      selected_directories.delete_db_snapshot,
      selected_directories.snapshot_status,
      selected_directories.snapshot_created_at,
      selected_directories.snapshot_updated_at,
      selected_directories.effective_expires_at,
      selected_directories.object_count,
      selected_directories.total_storage_bytes as snapshot_storage_bytes,
      selected_directories.active_ref_count,
      selected_directories.job_ref_count,
      selected_directories.result_ref_count,
      selected_directories.cache_ref_count,
      selected_directories.latest_ref_count,
      selected_directories.factorization_ref_count,
      selected_directories.artifact_ref_count,
      selected_directories.newest_observed_at
    from selected_directories
    join storage_objects
      on storage_objects.bucket_id = selected_directories.bucket_id
     and storage_objects.snapshot_directory = selected_directories.snapshot_directory
  ),
  budgeted as (
    select
      candidate_objects.*,
      sum(candidate_objects.storage_bytes) over (
        order by
          candidate_objects.candidate_type,
          candidate_objects.newest_observed_at asc,
          candidate_objects.object_name asc
      ) as cumulative_storage_bytes
    from candidate_objects
  )
  select
    budgeted.candidate_type,
    budgeted.snapshot_id,
    budgeted.snapshot_directory,
    budgeted.bucket_id,
    budgeted.object_name,
    budgeted.storage_bytes,
    budgeted.reason,
    budgeted.delete_db_snapshot,
    budgeted.snapshot_status,
    budgeted.snapshot_created_at,
    budgeted.snapshot_updated_at,
    budgeted.effective_expires_at,
    budgeted.object_count,
    budgeted.snapshot_storage_bytes,
    budgeted.active_ref_count as downstream_active_count,
    budgeted.job_ref_count as downstream_job_count,
    budgeted.result_ref_count as downstream_result_count,
    budgeted.cache_ref_count as downstream_cache_count,
    budgeted.latest_ref_count as downstream_latest_count,
    budgeted.factorization_ref_count as downstream_factorization_count,
    budgeted.artifact_ref_count as downstream_artifact_count
  from budgeted
  where budgeted.cumulative_storage_bytes <= p_max_bytes
  order by
    budgeted.candidate_type,
    budgeted.newest_observed_at asc,
    budgeted.object_name asc;
end;
$_$;


ALTER FUNCTION util.list_lca_snapshot_gc_candidates_without_closure_protection(p_snapshot_retention_window interval, p_orphan_retention_window interval, p_as_of timestamp with time zone, p_max_snapshots integer, p_max_orphan_dirs integer, p_max_bytes bigint) OWNER TO postgres;

--
-- Name: FUNCTION list_lca_snapshot_gc_candidates_without_closure_protection(p_snapshot_retention_window interval, p_orphan_retention_window interval, p_as_of timestamp with time zone, p_max_snapshots integer, p_max_orphan_dirs integer, p_max_bytes bigint); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.list_lca_snapshot_gc_candidates_without_closure_protection(p_snapshot_retention_window interval, p_orphan_retention_window interval, p_as_of timestamp with time zone, p_max_snapshots integer, p_max_orphan_dirs integer, p_max_bytes bigint) IS 'Operator snapshot GC candidate helper. Job references are counted from worker_jobs after public.lca_jobs retirement.';


--
-- Name: preview_cron_job_run_details_retention(interval); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.preview_cron_job_run_details_retention(p_retention_window interval DEFAULT '14 days'::interval) RETURNS TABLE(retention_window interval, cutoff_time timestamp with time zone, eligible_rows bigint, protected_open_or_running_rows bigint, oldest_eligible_end_time timestamp with time zone, newest_eligible_end_time timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'cron job run details retention window must be at least 1 day';
  end if;

  return query
  select
    p_retention_window as retention_window,
    pg_catalog.now() - p_retention_window as cutoff_time,
    count(*) filter (
      where details.end_time is not null
        and details.end_time < pg_catalog.now() - p_retention_window
        and coalesce(details.status, '') <> 'running'
    )::bigint as eligible_rows,
    count(*) filter (
      where details.end_time is null
        or coalesce(details.status, '') = 'running'
    )::bigint as protected_open_or_running_rows,
    min(details.end_time) filter (
      where details.end_time is not null
        and details.end_time < pg_catalog.now() - p_retention_window
        and coalesce(details.status, '') <> 'running'
    ) as oldest_eligible_end_time,
    max(details.end_time) filter (
      where details.end_time is not null
        and details.end_time < pg_catalog.now() - p_retention_window
        and coalesce(details.status, '') <> 'running'
    ) as newest_eligible_end_time
  from cron.job_run_details as details;
end;
$$;


ALTER FUNCTION util.preview_cron_job_run_details_retention(p_retention_window interval) OWNER TO postgres;

--
-- Name: FUNCTION preview_cron_job_run_details_retention(p_retention_window interval); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.preview_cron_job_run_details_retention(p_retention_window interval) IS 'Operator dry-run helper for pg_cron run-detail retention; reports rows older than the retention window while protecting open or running records.';


--
-- Name: preview_lca_package_retention(interval, interval, timestamp with time zone); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.preview_lca_package_retention(p_job_retention_window interval DEFAULT '30 days'::interval, p_request_cache_retention_window interval DEFAULT '30 days'::interval, p_as_of timestamp with time zone DEFAULT now()) RETURNS TABLE(retention_area text, retention_action text, is_eligible boolean, reason text, retention_window interval, cutoff_time timestamp with time zone, row_count bigint, total_artifact_bytes bigint, total_hit_count bigint, oldest_observed_at timestamp with time zone, newest_observed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_as_of is null then
    raise exception using
      errcode = '22023',
      message = 'package retention dry-run as_of timestamp must not be null';
  end if;

  if p_job_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'package job retention window must be at least 1 day';
  end if;

  if p_request_cache_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'package request-cache retention window must be at least 1 day';
  end if;

  return query
  with package_worker_jobs as (
    select
      jobs.id,
      jobs.status,
      coalesce(jobs.finished_at, jobs.updated_at, jobs.created_at) as lifecycle_at
    from public.worker_jobs as jobs
    where jobs.job_kind in ('tidas.export_package', 'tidas.import_package')
  ),
  job_rollup as (
    select
      jobs.id,
      jobs.status,
      jobs.lifecycle_at,
      coalesce(
        bool_or(artifacts.id is not null and artifacts.status <> 'deleted'),
        false
      ) as has_object_not_deleted,
      exists (
        select 1
        from public.lca_package_artifacts as recent_artifact
        join public.lca_package_request_cache as recent_cache
          on recent_cache.export_artifact_id = recent_artifact.id
          or recent_cache.report_artifact_id = recent_artifact.id
        where recent_artifact.worker_job_id = jobs.id
          and recent_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window
      ) as has_recent_artifact_cache,
      coalesce(
        sum(coalesce(artifacts.artifact_byte_size, 0))
          filter (where artifacts.status <> 'deleted'),
        0
      )::bigint as artifact_bytes
    from package_worker_jobs as jobs
    left join public.lca_package_artifacts as artifacts
      on artifacts.worker_job_id = jobs.id
    group by jobs.id, jobs.status, jobs.lifecycle_at
  ),
  job_classified as (
    select
      'worker_jobs'::text as retention_area,
      'delete_package_worker_metadata_after_artifact_gc'::text as retention_action,
      (classified.reason = 'eligible_terminal_job_older_than_window') as is_eligible,
      classified.reason,
      p_job_retention_window as retention_window,
      p_as_of - p_job_retention_window as cutoff_time,
      1::bigint as row_count,
      classified.artifact_bytes as total_artifact_bytes,
      0::bigint as total_hit_count,
      classified.lifecycle_at as observed_at
    from (
      select
        job_rollup.*,
        case
          when job_rollup.status in ('queued', 'running', 'waiting') then 'protected_active_job'
          when job_rollup.lifecycle_at >= p_as_of - p_job_retention_window then 'protected_inside_job_retention_window'
          when job_rollup.has_object_not_deleted then 'protected_object_not_deleted'
          when job_rollup.has_recent_artifact_cache then 'protected_recent_request_cache_reference'
          else 'eligible_terminal_job_older_than_window'
        end as reason
      from job_rollup
    ) as classified
  ),
  artifact_classified as (
    select
      'lca_package_artifacts'::text as retention_area,
      'delete_object_then_mark_deleted'::text as retention_action,
      (classified.reason = 'eligible_expired_unpinned_artifact') as is_eligible,
      classified.reason,
      null::interval as retention_window,
      p_as_of as cutoff_time,
      1::bigint as row_count,
      coalesce(classified.artifact_byte_size, 0)::bigint as total_artifact_bytes,
      0::bigint as total_hit_count,
      coalesce(classified.expires_at, classified.updated_at, classified.created_at) as observed_at
    from (
      select
        artifacts.*,
        jobs.status as parent_job_status,
        coalesce(recent_cache.recent_cache_rows, 0) as recent_cache_rows,
        case
          when artifacts.is_pinned then 'protected_pinned_artifact'
          when artifacts.status = 'deleted' then 'protected_already_deleted'
          when artifacts.status = 'pending' then 'protected_artifact_not_ready'
          when jobs.id is null then 'protected_missing_worker_job'
          when jobs.status in ('queued', 'running', 'waiting') then 'protected_active_parent_job'
          when artifacts.expires_at is null then 'protected_missing_expires_at'
          when artifacts.expires_at > p_as_of then 'protected_expires_at_in_future'
          when coalesce(recent_cache.recent_cache_rows, 0) > 0 then 'protected_recent_request_cache_reference'
          else 'eligible_expired_unpinned_artifact'
        end as reason
      from public.lca_package_artifacts as artifacts
      left join package_worker_jobs as jobs
        on jobs.id = artifacts.worker_job_id
      left join lateral (
        select count(*)::bigint as recent_cache_rows
        from public.lca_package_request_cache as request_cache
        where (
            request_cache.export_artifact_id = artifacts.id
            or request_cache.report_artifact_id = artifacts.id
          )
          and request_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window
      ) as recent_cache on true
    ) as classified
  ),
  request_cache_classified as (
    select
      'lca_package_request_cache'::text as retention_area,
      'delete_stale_request_cache_row'::text as retention_action,
      (classified.reason = 'eligible_stale_request_cache') as is_eligible,
      classified.reason,
      p_request_cache_retention_window as retention_window,
      p_as_of - p_request_cache_retention_window as cutoff_time,
      1::bigint as row_count,
      0::bigint as total_artifact_bytes,
      classified.hit_count::bigint as total_hit_count,
      classified.last_accessed_at as observed_at
    from (
      select
        request_cache.*,
        jobs.status as parent_job_status,
        case
          when request_cache.status in ('pending', 'running') then 'protected_active_request_cache'
          when request_cache.last_accessed_at >= p_as_of - p_request_cache_retention_window then 'protected_recent_request_cache_access'
          when jobs.status in ('queued', 'running', 'waiting') then 'protected_active_parent_job'
          else 'eligible_stale_request_cache'
        end as reason
      from public.lca_package_request_cache as request_cache
      left join package_worker_jobs as jobs
        on jobs.id = request_cache.worker_job_id
    ) as classified
  ),
  export_item_classified as (
    select
      'lca_package_export_items'::text as retention_area,
      'delete_export_items_with_parent_job'::text as retention_action,
      (classified.reason = 'eligible_parent_job_cascade') as is_eligible,
      classified.reason,
      p_job_retention_window as retention_window,
      p_as_of - p_job_retention_window as cutoff_time,
      1::bigint as row_count,
      0::bigint as total_artifact_bytes,
      0::bigint as total_hit_count,
      classified.created_at as observed_at
    from (
      select
        export_items.*,
        case
          when export_items.worker_job_id is null or job_rollup.id is null then 'protected_missing_worker_job'
          when job_rollup.status in ('queued', 'running', 'waiting') then 'protected_active_parent_job'
          when job_rollup.lifecycle_at >= p_as_of - p_job_retention_window then 'protected_parent_inside_job_retention_window'
          when job_rollup.has_object_not_deleted then 'protected_object_not_deleted'
          when job_rollup.has_recent_artifact_cache then 'protected_recent_request_cache_reference'
          else 'eligible_parent_job_cascade'
        end as reason
      from public.lca_package_export_items as export_items
      left join job_rollup
        on job_rollup.id = export_items.worker_job_id
    ) as classified
  ),
  classified as (
    select * from job_classified
    union all
    select * from artifact_classified
    union all
    select * from request_cache_classified
    union all
    select * from export_item_classified
  )
  select
    classified.retention_area,
    classified.retention_action,
    classified.is_eligible,
    classified.reason,
    classified.retention_window,
    classified.cutoff_time,
    sum(classified.row_count)::bigint as row_count,
    coalesce(sum(classified.total_artifact_bytes), 0)::bigint as total_artifact_bytes,
    coalesce(sum(classified.total_hit_count), 0)::bigint as total_hit_count,
    min(classified.observed_at) as oldest_observed_at,
    max(classified.observed_at) as newest_observed_at
  from classified
  group by
    classified.retention_area,
    classified.retention_action,
    classified.is_eligible,
    classified.reason,
    classified.retention_window,
    classified.cutoff_time
  order by
    classified.retention_area,
    classified.is_eligible desc,
    classified.reason;
end;
$$;


ALTER FUNCTION util.preview_lca_package_retention(p_job_retention_window interval, p_request_cache_retention_window interval, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION preview_lca_package_retention(p_job_retention_window interval, p_request_cache_retention_window interval, p_as_of timestamp with time zone); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.preview_lca_package_retention(p_job_retention_window interval, p_request_cache_retention_window interval, p_as_of timestamp with time zone) IS 'Operator dry-run helper for package metadata retention; reports aggregate eligible/protected counts for package worker jobs, artifacts, request cache, and export items without deleting or updating business rows.';


--
-- Name: preview_lca_snapshot_retention(interval, interval, timestamp with time zone); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.preview_lca_snapshot_retention(p_snapshot_retention_window interval DEFAULT '30 days'::interval, p_orphan_retention_window interval DEFAULT '30 days'::interval, p_as_of timestamp with time zone DEFAULT now()) RETURNS TABLE(retention_area text, retention_action text, is_eligible boolean, reason text, retention_window interval, cutoff_time timestamp with time zone, snapshot_count bigint, object_count bigint, total_storage_bytes bigint, downstream_active_count bigint, downstream_job_count bigint, downstream_result_count bigint, downstream_cache_count bigint, downstream_latest_count bigint, downstream_factorization_count bigint, downstream_artifact_count bigint, oldest_observed_at timestamp with time zone, newest_observed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
begin
  if p_as_of is null then
    raise exception using
      errcode = '22023',
      message = 'snapshot retention preview as_of timestamp must not be null';
  end if;

  if p_snapshot_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'snapshot retention window must be at least 1 day';
  end if;

  if p_orphan_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'orphan snapshot storage retention window must be at least 1 day';
  end if;

  return query
  with storage_objects as (
    select
      objects.bucket_id,
      objects.name as object_name,
      case
        when objects.name ~ '^lca-results/snapshots/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/'
          then substring(objects.name from '^lca-results/snapshots/([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/')::uuid
        else null::uuid
      end as parsed_snapshot_id,
      nullif(split_part(objects.name, '/', 3), '') as snapshot_directory,
      coalesce(
        case
          when jsonb_typeof(objects.metadata -> 'size') = 'number'
            or coalesce(objects.metadata ->> 'size', '') ~ '^[0-9]+$'
            then (objects.metadata ->> 'size')::bigint
          else null::bigint
        end,
        0
      ) as storage_bytes,
      coalesce(objects.created_at, objects.updated_at) as object_created_at,
      coalesce(objects.updated_at, objects.created_at) as object_updated_at
    from storage.objects as objects
    where objects.bucket_id = 'lca_results'
      and objects.name like 'lca-results/snapshots/%'
  ),
  storage_directories as (
    select
      storage_objects.bucket_id,
      storage_objects.parsed_snapshot_id,
      storage_objects.snapshot_directory,
      count(*)::bigint as object_count,
      coalesce(sum(storage_objects.storage_bytes), 0)::bigint as total_storage_bytes,
      min(coalesce(storage_objects.object_created_at, storage_objects.object_updated_at)) as oldest_object_at,
      max(coalesce(storage_objects.object_created_at, storage_objects.object_updated_at)) as newest_object_at
    from storage_objects
    group by
      storage_objects.bucket_id,
      storage_objects.parsed_snapshot_id,
      storage_objects.snapshot_directory
  ),
  active_refs as (
    select lca_active_snapshots.snapshot_id, count(*)::bigint as active_ref_count
    from public.lca_active_snapshots
    group by lca_active_snapshots.snapshot_id
  ),
  worker_job_ref_candidates as (
    select distinct
      jobs.id as worker_job_id,
      case
        when refs.snapshot_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then refs.snapshot_text::uuid
        else null::uuid
      end as snapshot_id
    from public.worker_jobs as jobs
    cross join lateral (
      values
        (jobs.payload_json #>> '{snapshot,id}'),
        (jobs.payload_json #>> '{snapshotId}'),
        (jobs.payload_json #>> '{snapshot_id}'),
        (jobs.result_json #>> '{snapshot,id}'),
        (jobs.result_json #>> '{snapshotId}'),
        (jobs.result_json #>> '{snapshot_id}')
    ) as refs(snapshot_text)
    where jobs.job_kind like 'lca.%'
  ),
  job_refs as (
    select
      worker_job_ref_candidates.snapshot_id,
      count(distinct worker_job_ref_candidates.worker_job_id)::bigint as job_ref_count
    from worker_job_ref_candidates
    where worker_job_ref_candidates.snapshot_id is not null
    group by worker_job_ref_candidates.snapshot_id
  ),
  result_refs as (
    select lca_results.snapshot_id, count(*)::bigint as result_ref_count
    from public.lca_results
    group by lca_results.snapshot_id
  ),
  cache_refs as (
    select lca_result_cache.snapshot_id, count(*)::bigint as cache_ref_count
    from public.lca_result_cache
    group by lca_result_cache.snapshot_id
  ),
  latest_refs as (
    select lca_latest_all_unit_results.snapshot_id, count(*)::bigint as latest_ref_count
    from public.lca_latest_all_unit_results
    group by lca_latest_all_unit_results.snapshot_id
  ),
  factorization_refs as (
    select lca_factorization_registry.snapshot_id, count(*)::bigint as factorization_ref_count
    from public.lca_factorization_registry
    group by lca_factorization_registry.snapshot_id
  ),
  artifact_refs as (
    select lca_snapshot_artifacts.snapshot_id, count(*)::bigint as artifact_ref_count
    from public.lca_snapshot_artifacts
    group by lca_snapshot_artifacts.snapshot_id
  ),
  classified as (
    select
      case
        when storage_directories.parsed_snapshot_id is null then 'lca_snapshot_storage_unparsed_paths'
        when snapshots.id is null then 'lca_snapshot_storage_orphan_directories'
        else 'lca_snapshot_storage_directories'
      end as retention_area,
      case
        when storage_directories.parsed_snapshot_id is null then 'report_only'
        when snapshots.id is null then 'delete_storage_objects_only'
        else 'delete_storage_objects_then_snapshot_row'
      end as retention_action,
      case
        when storage_directories.parsed_snapshot_id is null then 'protected_unparsed_storage_path'
        when snapshots.id is null
          and storage_directories.newest_object_at >= p_as_of - p_orphan_retention_window
          then 'protected_inside_retention_window'
        when snapshots.id is null then 'eligible_orphan_storage_directory'
        when coalesce(active_refs.active_ref_count, 0) > 0 then 'protected_active_snapshot'
        when snapshot_ttl.expires_at_utc is not null
          and snapshot_ttl.expires_at_utc > p_as_of
          then 'protected_ttl_future'
        when snapshot_ttl.expires_at_utc is not null then 'eligible_ttl_expired_snapshot'
        when coalesce(snapshots.updated_at, snapshots.created_at) >= p_as_of - p_snapshot_retention_window
          then 'protected_inside_retention_window'
        else 'eligible_default_30d_snapshot'
      end as reason,
      case
        when snapshots.id is null then p_orphan_retention_window
        when snapshot_ttl.expires_at_utc is not null then null::interval
        else p_snapshot_retention_window
      end as retention_window,
      case
        when snapshots.id is null then p_as_of - p_orphan_retention_window
        when snapshot_ttl.expires_at_utc is not null then p_as_of
        else p_as_of - p_snapshot_retention_window
      end as cutoff_time,
      1::bigint as snapshot_count,
      storage_directories.object_count,
      storage_directories.total_storage_bytes,
      coalesce(active_refs.active_ref_count, 0)::bigint as active_ref_count,
      coalesce(job_refs.job_ref_count, 0)::bigint as job_ref_count,
      coalesce(result_refs.result_ref_count, 0)::bigint as result_ref_count,
      coalesce(cache_refs.cache_ref_count, 0)::bigint as cache_ref_count,
      coalesce(latest_refs.latest_ref_count, 0)::bigint as latest_ref_count,
      coalesce(factorization_refs.factorization_ref_count, 0)::bigint as factorization_ref_count,
      coalesce(artifact_refs.artifact_ref_count, 0)::bigint as artifact_ref_count,
      coalesce(snapshots.updated_at, snapshots.created_at, storage_directories.oldest_object_at) as oldest_observed_at,
      coalesce(snapshots.updated_at, snapshots.created_at, storage_directories.newest_object_at) as newest_observed_at
    from storage_directories
    left join public.lca_network_snapshots as snapshots
      on snapshots.id = storage_directories.parsed_snapshot_id
    left join lateral (
      select case
        when coalesce(snapshots.process_filter #>> '{artifact_lifecycle,expires_at_utc}', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T]'
          then (snapshots.process_filter #>> '{artifact_lifecycle,expires_at_utc}')::timestamp with time zone
        else null::timestamp with time zone
      end as expires_at_utc
    ) as snapshot_ttl on true
    left join active_refs
      on active_refs.snapshot_id = snapshots.id
    left join job_refs
      on job_refs.snapshot_id = snapshots.id
    left join result_refs
      on result_refs.snapshot_id = snapshots.id
    left join cache_refs
      on cache_refs.snapshot_id = snapshots.id
    left join latest_refs
      on latest_refs.snapshot_id = snapshots.id
    left join factorization_refs
      on factorization_refs.snapshot_id = snapshots.id
    left join artifact_refs
      on artifact_refs.snapshot_id = snapshots.id
  )
  select
    classified.retention_area,
    classified.retention_action,
    classified.reason in (
      'eligible_ttl_expired_snapshot',
      'eligible_default_30d_snapshot',
      'eligible_orphan_storage_directory'
    ) as is_eligible,
    classified.reason,
    classified.retention_window,
    classified.cutoff_time,
    sum(classified.snapshot_count)::bigint as snapshot_count,
    sum(classified.object_count)::bigint as object_count,
    coalesce(sum(classified.total_storage_bytes), 0)::bigint as total_storage_bytes,
    coalesce(sum(classified.active_ref_count), 0)::bigint as downstream_active_count,
    coalesce(sum(classified.job_ref_count), 0)::bigint as downstream_job_count,
    coalesce(sum(classified.result_ref_count), 0)::bigint as downstream_result_count,
    coalesce(sum(classified.cache_ref_count), 0)::bigint as downstream_cache_count,
    coalesce(sum(classified.latest_ref_count), 0)::bigint as downstream_latest_count,
    coalesce(sum(classified.factorization_ref_count), 0)::bigint as downstream_factorization_count,
    coalesce(sum(classified.artifact_ref_count), 0)::bigint as downstream_artifact_count,
    min(classified.oldest_observed_at) as oldest_observed_at,
    max(classified.newest_observed_at) as newest_observed_at
  from classified
  group by
    classified.retention_area,
    classified.retention_action,
    classified.reason,
    classified.retention_window,
    classified.cutoff_time
  order by
    classified.retention_area,
    is_eligible desc,
    classified.reason;
end;
$_$;


ALTER FUNCTION util.preview_lca_snapshot_retention(p_snapshot_retention_window interval, p_orphan_retention_window interval, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION preview_lca_snapshot_retention(p_snapshot_retention_window interval, p_orphan_retention_window interval, p_as_of timestamp with time zone); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.preview_lca_snapshot_retention(p_snapshot_retention_window interval, p_orphan_retention_window interval, p_as_of timestamp with time zone) IS 'Operator dry-run helper for lca-results/snapshots retention. Job references are counted from worker_jobs after public.lca_jobs retirement.';


--
-- Name: preview_supabase_functions_hooks_retention(interval, timestamp with time zone); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.preview_supabase_functions_hooks_retention(p_retention_window interval DEFAULT '14 days'::interval, p_as_of timestamp with time zone DEFAULT now()) RETURNS TABLE(retention_window interval, cutoff_time timestamp with time zone, total_rows bigint, eligible_rows bigint, protected_recent_rows bigint, protected_live_response_rows bigint, oldest_eligible_created_at timestamp with time zone, newest_eligible_created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_as_of is null then
    raise exception using
      errcode = '22023',
      message = 'supabase functions hooks retention as_of timestamp must not be null';
  end if;

  if p_retention_window is null or p_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'supabase functions hooks retention window must be at least 1 day';
  end if;

  if to_regclass('supabase_functions.hooks') is null then
    return query
    select
      p_retention_window as retention_window,
      p_as_of - p_retention_window as cutoff_time,
      0::bigint as total_rows,
      0::bigint as eligible_rows,
      0::bigint as protected_recent_rows,
      0::bigint as protected_live_response_rows,
      null::timestamp with time zone as oldest_eligible_created_at,
      null::timestamp with time zone as newest_eligible_created_at;
    return;
  end if;

  return query
  with live_responses as materialized (
    select response.id
    from net._http_response as response
  ), classified as (
    select
      hooks.created_at,
      hooks.created_at < p_as_of - p_retention_window as is_older_than_cutoff,
      live_responses.id is not null as has_live_pg_net_response
    from supabase_functions.hooks as hooks
    left join live_responses on live_responses.id = hooks.request_id
  )
  select
    p_retention_window as retention_window,
    p_as_of - p_retention_window as cutoff_time,
    count(*)::bigint as total_rows,
    count(*) filter (
      where classified.is_older_than_cutoff
        and not classified.has_live_pg_net_response
    )::bigint as eligible_rows,
    count(*) filter (
      where not classified.is_older_than_cutoff
    )::bigint as protected_recent_rows,
    count(*) filter (
      where classified.is_older_than_cutoff
        and classified.has_live_pg_net_response
    )::bigint as protected_live_response_rows,
    min(classified.created_at) filter (
      where classified.is_older_than_cutoff
        and not classified.has_live_pg_net_response
    ) as oldest_eligible_created_at,
    max(classified.created_at) filter (
      where classified.is_older_than_cutoff
        and not classified.has_live_pg_net_response
    ) as newest_eligible_created_at
  from classified;
end;
$$;


ALTER FUNCTION util.preview_supabase_functions_hooks_retention(p_retention_window interval, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION preview_supabase_functions_hooks_retention(p_retention_window interval, p_as_of timestamp with time zone); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.preview_supabase_functions_hooks_retention(p_retention_window interval, p_as_of timestamp with time zone) IS 'Operator dry-run helper for Supabase Functions webhook audit retention; reports rows older than the retention window while protecting recent rows and rows still linked to live pg_net responses.';


--
-- Name: process_dataset_derivative_rebuilds(integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.process_dataset_derivative_rebuilds(p_limit integer DEFAULT 5) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_json_ordered jsonb;
  v_response net._http_response%rowtype;
  v_snapshot jsonb;
  v_quarantine jsonb;
  v_service_key text;
  v_http_request_id bigint;
  v_proposal_count integer;
  v_proposal_id bigint;
  v_queue_mode text;
  v_queue_msg_id bigint;
  v_pending_job_id bigint;
  v_pending_status text;
  v_pending_msg_id bigint;
  v_pending_enqueued_at timestamp with time zone;
  v_embedding_failure jsonb;
  v_processed integer := 0;
  v_now timestamp with time zone;
  v_error_state text;
  v_error_message text;
  v_error_detail text;
begin
  if coalesce(p_limit, 0) <= 0 then
    return 0;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext('util.process_dataset_derivative_rebuilds')
  ) then
    return 0;
  end if;

  for v_request in
    select request.*
    from util.dataset_derivative_rebuild_requests as request
    where request.status not in ('completed', 'stale', 'failed')
    order by request.updated_at, request.admitted_at, request.id
    for update skip locked
    limit least(greatest(p_limit, 1), 25)
  loop
    v_processed := v_processed + 1;
    v_now := pg_catalog.clock_timestamp();
    begin

    if v_request.status = 'dispatching'
      and v_request.phase = 'failure_draining' then
      if v_request.failure_release_not_before is null
        or v_now < v_request.failure_release_not_before then
        update util.dataset_derivative_rebuild_requests
        set updated_at = v_now
        where id = v_request.id;
        continue;
      end if;

      v_quarantine := util.quarantine_dataset_derivative_rebuild_target(
        v_request.target_table,
        v_request.target_id,
        v_request.target_version
      );
      update util.dataset_derivative_rebuild_proposals
      set
        status = 'discarded',
        discarded_at = v_now
      where request_id = v_request.id
        and status in ('captured', 'accepted');

      update util.dataset_derivative_rebuild_requests
      set
        status = 'failed',
        phase = 'failed_drained',
        terminal_at = v_now,
        drained_at = v_now,
        quarantined_http_requests = quarantined_http_requests
          + coalesce((v_quarantine->>'http_requests')::integer, 0),
        quarantined_embedding_jobs = quarantined_embedding_jobs
          + coalesce((v_quarantine->>'embedding_jobs')::integer, 0),
        quarantined_pending_jobs = quarantined_pending_jobs
          + coalesce((v_quarantine->>'pending_jobs')::integer, 0),
        updated_at = v_now
      where id = v_request.id;
      perform util.record_dataset_derivative_rebuild_terminal(v_request.id);
      continue;
    end if;

    v_json_ordered := null;
    if v_request.target_table = 'flows' then
      select flow.json_ordered::jsonb
      into v_json_ordered
      from public.flows as flow
      where flow.id = v_request.target_id
        and btrim(flow.version::text) = v_request.target_version;
    elsif v_request.target_table = 'processes' then
      select process.json_ordered::jsonb
      into v_json_ordered
      from public.processes as process
      where process.id = v_request.target_id
        and btrim(process.version::text) = v_request.target_version;
    end if;

    if v_json_ordered is null
      or not util.dataset_derivative_rebuild_primary_matches(v_request) then
      perform util.fail_dataset_derivative_rebuild_after_drain(
        v_request.id,
        'DERIVATIVE_PRIMARY_DRIFT',
        'Frozen dataset primary fingerprint is no longer present',
        '{}'::jsonb
      );
      continue;
    end if;

    if v_request.status = 'queued' then
      update util.dataset_derivative_rebuild_requests
      set
        status = 'dispatching',
        phase = 'quarantining',
        updated_at = v_now
      where id = v_request.id;
      continue;
    end if;

    if v_request.status = 'dispatching'
      and v_request.phase = 'quarantining' then
      if v_now < v_request.drain_not_before then
        update util.dataset_derivative_rebuild_requests
        set updated_at = v_now
        where id = v_request.id;
        continue;
      end if;

      v_quarantine := util.quarantine_dataset_derivative_rebuild_target(
        v_request.target_table,
        v_request.target_id,
        v_request.target_version
      );
      update util.dataset_derivative_rebuild_proposals
      set
        status = 'discarded',
        discarded_at = v_now
      where request_id = v_request.id
        and status in ('captured', 'accepted');

      v_service_key := util.project_secret_key();
      v_http_request_id := net.http_post(
        url => util.project_url()
          || case v_request.target_table
            when 'flows' then '/functions/v1/webhook_flow_embedding_ft'
            else '/functions/v1/webhook_process_embedding_ft'
          end,
        headers => jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_key,
          'apikey', v_service_key,
          'x_region', 'us-east-1'
        ),
        body => jsonb_build_object(
          'type', 'UPDATE',
          'schema', 'public',
          'table', v_request.target_table,
          'record', jsonb_build_object(
            'id', v_request.target_id,
            'version', v_request.target_version,
            'json_ordered', v_json_ordered
          ),
          'old_record', jsonb_build_object(
            'id', v_request.target_id,
            'version', v_request.target_version,
            'json_ordered', v_json_ordered
          ),
          'derivativeRebuildRequestId', v_request.id
        ),
        timeout_milliseconds => 120000
      );

      update util.dataset_derivative_rebuild_requests
      set
        status = 'markdown_pending',
        phase = 'markdown_dispatched',
        markdown_request_id = v_http_request_id,
        markdown_dispatched_at = v_now,
        markdown_deadline_at = v_now + interval '10 minutes',
        quarantined_http_requests = quarantined_http_requests
          + coalesce((v_quarantine->>'http_requests')::integer, 0),
        quarantined_embedding_jobs = quarantined_embedding_jobs
          + coalesce((v_quarantine->>'embedding_jobs')::integer, 0),
        quarantined_pending_jobs = quarantined_pending_jobs
          + coalesce((v_quarantine->>'pending_jobs')::integer, 0),
        updated_at = v_now
      where id = v_request.id;
      continue;
    end if;

    if v_request.status = 'markdown_pending' then
      v_response := null;
      select response.*
      into v_response
      from net._http_response as response
      where response.id = v_request.markdown_request_id;

      if v_response.id is null then
        if v_request.markdown_deadline_at is not null
          and v_now >= v_request.markdown_deadline_at then
          delete from net.http_request_queue
          where id = v_request.markdown_request_id;
          perform util.fail_dataset_derivative_rebuild_after_drain(
            v_request.id,
            'DERIVATIVE_MARKDOWN_RESPONSE_TIMEOUT',
            'Markdown webhook did not produce a durable response before deadline',
            jsonb_build_object(
              'markdown_request_id',
              v_request.markdown_request_id::text
            )
          );
        end if;
        update util.dataset_derivative_rebuild_requests
        set updated_at = v_now
        where id = v_request.id;
        continue;
      end if;

      update util.dataset_derivative_rebuild_requests
      set
        markdown_response_status = v_response.status_code,
        markdown_response_received_at = v_response.created,
        updated_at = v_now
      where id = v_request.id;

      if coalesce(v_response.timed_out, false)
        or v_response.error_msg is not null
        or v_response.status_code not between 200 and 299
        or not util.dataset_derivative_rebuild_markdown_response_matches(
          v_response.content,
          v_request.target_table,
          v_request.target_id,
          v_request.target_version
        ) then
        perform util.fail_dataset_derivative_rebuild_after_drain(
          v_request.id,
          'DERIVATIVE_MARKDOWN_RESPONSE_INVALID',
          'Markdown webhook response was timed out, non-2xx, or malformed',
          jsonb_build_object(
            'markdown_request_id', v_request.markdown_request_id::text,
            'status_code', v_response.status_code,
            'timed_out', v_response.timed_out,
            'error_msg', v_response.error_msg
          )
        );
        continue;
      end if;

      select count(*), min(proposal.id)
      into v_proposal_count, v_proposal_id
      from util.dataset_derivative_rebuild_proposals as proposal
      where proposal.request_id = v_request.id
        and proposal.proposal_kind = 'markdown'
        and proposal.status = 'captured'
        and proposal.captured_at >= v_request.markdown_dispatched_at;

      if v_proposal_count <> 1 then
        perform util.fail_dataset_derivative_rebuild_after_drain(
          v_request.id,
          'DERIVATIVE_MARKDOWN_PROPOSAL_MISMATCH',
          'Markdown response did not correlate to exactly one staged proposal',
          jsonb_build_object('proposal_count', v_proposal_count)
        );
        continue;
      end if;

      update util.dataset_derivative_rebuild_proposals
      set status = 'accepted'
      where id = v_proposal_id
        and request_id = v_request.id
        and proposal_kind = 'markdown'
        and status = 'captured';

      update util.dataset_derivative_rebuild_requests
      set
        markdown_proposal_id = v_proposal_id,
        accepted_extracted_md_sha256 = (
          select proposal.extracted_md_sha256
          from util.dataset_derivative_rebuild_proposals as proposal
          where proposal.id = v_proposal_id
        ),
        updated_at = v_now
      where id = v_request.id;

      select policy.mode
      into v_queue_mode
      from util.embedding_queue_policy_for(
        'public',
        v_request.target_table,
        'embedding_ft',
        'embedding_ft'
      ) as policy;

      if v_queue_mode = 'normal' then
        select pgmq.send(
          queue_name => 'embedding_jobs',
          msg => jsonb_build_object(
            'id', v_request.target_id,
            'version', v_request.target_version,
            'schema', 'public',
            'table', v_request.target_table,
            'contentFunction',
              case v_request.target_table
                when 'flows'
                  then 'flows_derivative_rebuild_embedding_input'
                else 'processes_derivative_rebuild_embedding_input'
              end,
            'embeddingColumn', 'embedding_ft',
            'edgeFunction', 'embedding_ft',
            'requestId', v_request.id,
            'expectedPrimarySnapshotSha256',
              v_request.expected_snapshot_sha256,
            'expectedMarkdownSha256', (
              select proposal.extracted_md_sha256
              from util.dataset_derivative_rebuild_proposals as proposal
              where proposal.id = v_proposal_id
            )
          )
        ) into v_queue_msg_id;

        update util.dataset_derivative_rebuild_requests
        set
          status = 'embedding_pending',
          phase = 'embedding_queued',
          embedding_queue_msg_id = v_queue_msg_id,
          embedding_queued_at = v_now,
          embedding_deadline_at = v_now + interval '7 days',
          updated_at = v_now
        where id = v_request.id;
      else
        insert into util.pending_embedding_jobs (
          schema_name,
          table_name,
          record_id,
          record_version,
          content_function,
          embedding_column,
          edge_function,
          message
        ) values (
          'public',
          v_request.target_table,
          v_request.target_id::text,
          v_request.target_version,
          case v_request.target_table
                when 'flows'
                  then 'flows_derivative_rebuild_embedding_input'
                else 'processes_derivative_rebuild_embedding_input'
              end,
          'embedding_ft',
          'embedding_ft',
          jsonb_build_object(
            'id', v_request.target_id,
            'version', v_request.target_version,
            'schema', 'public',
            'table', v_request.target_table,
            'contentFunction',
              case v_request.target_table
                when 'flows'
                  then 'flows_derivative_rebuild_embedding_input'
                else 'processes_derivative_rebuild_embedding_input'
              end,
            'embeddingColumn', 'embedding_ft',
            'edgeFunction', 'embedding_ft',
            'requestId', v_request.id,
            'expectedPrimarySnapshotSha256',
              v_request.expected_snapshot_sha256,
            'expectedMarkdownSha256', (
              select proposal.extracted_md_sha256
              from util.dataset_derivative_rebuild_proposals as proposal
              where proposal.id = v_proposal_id
            )
          )
        )
        on conflict (
          schema_name,
          table_name,
          record_id,
          record_version,
          embedding_column,
          edge_function
        ) where status = 'pending'
        do update set
          message = excluded.message,
          updated_at = v_now
        returning id into v_pending_job_id;

        update util.dataset_derivative_rebuild_requests
        set
          status = 'embedding_pending',
          phase = case
            when v_queue_mode = 'paused'
              then 'embedding_policy_paused'
            else 'embedding_policy_deferred'
          end,
          embedding_pending_job_id = v_pending_job_id,
          embedding_queued_at = v_now,
          embedding_deadline_at = v_now + interval '7 days',
          updated_at = v_now
        where id = v_request.id;
      end if;
      continue;
    end if;

    if v_request.status = 'embedding_pending' then
      v_queue_msg_id := v_request.embedding_queue_msg_id;
      v_pending_status := null;
      v_pending_msg_id := null;
      v_pending_enqueued_at := null;
      v_embedding_failure := null;

      if v_queue_msg_id is null
        and v_request.embedding_pending_job_id is not null then
        select pending.status, pending.queue_msg_id, pending.enqueued_at
        into v_pending_status, v_pending_msg_id, v_pending_enqueued_at
        from util.pending_embedding_jobs as pending
        where pending.id = v_request.embedding_pending_job_id;

        if v_pending_status = 'pending' then
          if v_request.embedding_deadline_at is not null
            and v_now >= v_request.embedding_deadline_at then
            delete from util.pending_embedding_jobs
            where id = v_request.embedding_pending_job_id;
            perform util.fail_dataset_derivative_rebuild_after_drain(
              v_request.id,
              'DERIVATIVE_EMBEDDING_POLICY_TIMEOUT',
              'Embedding policy did not release the request before deadline',
              '{}'::jsonb
            );
          end if;
          update util.dataset_derivative_rebuild_requests
          set updated_at = v_now
          where id = v_request.id;
          continue;
        end if;

        if v_pending_status = 'enqueued'
          and v_pending_msg_id is not null
          and v_pending_enqueued_at is not null then
          v_queue_msg_id := v_pending_msg_id;
          update util.dataset_derivative_rebuild_requests
          set
            phase = 'embedding_queued',
            embedding_queue_msg_id = v_queue_msg_id,
            embedding_queued_at = v_pending_enqueued_at,
            updated_at = v_now
          where id = v_request.id;
        else
          perform util.fail_dataset_derivative_rebuild_after_drain(
            v_request.id,
            'DERIVATIVE_EMBEDDING_PENDING_JOB_LOST',
            'Request-specific pending embedding job is missing or discarded',
            '{}'::jsonb
          );
          continue;
        end if;
      end if;

      if v_queue_msg_id is null then
        perform util.fail_dataset_derivative_rebuild_after_drain(
          v_request.id,
          'DERIVATIVE_EMBEDDING_QUEUE_PROOF_MISSING',
          'Request-specific embedding queue id is missing',
          '{}'::jsonb
        );
        continue;
      end if;

      if exists (
        select 1
        from pgmq.q_embedding_jobs as job
        where job.msg_id = v_queue_msg_id
      ) then
        if v_request.embedding_deadline_at is not null
          and v_now >= v_request.embedding_deadline_at then
          delete from pgmq.q_embedding_jobs
          where msg_id = v_queue_msg_id;
          perform util.fail_dataset_derivative_rebuild_after_drain(
            v_request.id,
            'DERIVATIVE_EMBEDDING_QUEUE_TIMEOUT',
            'Embedding job did not finish before deadline',
            jsonb_build_object('queue_msg_id', v_queue_msg_id::text)
          );
        end if;
        update util.dataset_derivative_rebuild_requests
        set updated_at = v_now
        where id = v_request.id;
        continue;
      end if;

      select jsonb_build_object(
        'failure_id', failure.id::text,
        'reason', failure.reason,
        'failed_at', failure.failed_at
      )
      into v_embedding_failure
      from util.embedding_job_failures as failure
      where failure.msg_id = v_queue_msg_id
      order by failure.id desc
      limit 1;

      if v_embedding_failure is not null then
        perform util.fail_dataset_derivative_rebuild_after_drain(
          v_request.id,
          'DERIVATIVE_EMBEDDING_JOB_FAILED',
          'Request-specific embedding job reached the failure ledger',
          v_embedding_failure
        );
        continue;
      end if;

      select count(*), min(proposal.id)
      into v_proposal_count, v_proposal_id
      from util.dataset_derivative_rebuild_proposals as proposal
      where proposal.request_id = v_request.id
        and proposal.proposal_kind = 'embedding'
        and proposal.status = 'captured'
        and proposal.captured_at >= v_request.embedding_queued_at;

      if v_proposal_count <> 1 then
        perform util.fail_dataset_derivative_rebuild_after_drain(
          v_request.id,
          'DERIVATIVE_EMBEDDING_PROPOSAL_MISMATCH',
          'Embedding ACK did not correlate to exactly one staged proposal',
          jsonb_build_object(
            'queue_msg_id', v_queue_msg_id::text,
            'proposal_count', v_proposal_count
          )
        );
        continue;
      end if;

      perform util.commit_dataset_derivative_rebuild_proposal(
        v_request.id,
        v_request.markdown_proposal_id,
        v_proposal_id
      );

      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_request.target_table,
        v_request.target_id,
        v_request.target_version
      );

      if v_snapshot->>'embedding_ft_sha256' is null
        or v_snapshot->>'extracted_md_sha256' is null
        or (v_snapshot->>'embedding_ft_at')::timestamp with time zone
          <= coalesce(
            v_request.before_embedding_ft_at,
            '-infinity'::timestamp with time zone
          ) then
        raise exception using
          errcode = '40001',
          message = 'Committed derivative snapshot is not fresh and complete';
      end if;

      update util.dataset_derivative_rebuild_requests
      set
        status = 'completed',
        phase = 'completed',
        embedding_proposal_id = v_proposal_id,
        completed_snapshot_sha256 = v_snapshot->>'snapshot_sha256',
        completed_at = v_now,
        terminal_at = v_now,
        drained_at = v_now,
        updated_at = v_now
      where id = v_request.id;
      perform util.record_dataset_derivative_rebuild_terminal(v_request.id);
    end if;
    exception
      when others then
        get stacked diagnostics
          v_error_state = returned_sqlstate,
          v_error_message = message_text,
          v_error_detail = pg_exception_detail;
        perform util.fail_dataset_derivative_rebuild_after_drain(
          v_request.id,
          'DERIVATIVE_COORDINATOR_ERROR',
          'Unexpected request-scoped coordinator error',
          jsonb_build_object(
            'sqlstate', v_error_state,
            'message', v_error_message,
            'detail', v_error_detail
          )
        );
    end;
  end loop;

  return v_processed;
end;
$$;


ALTER FUNCTION util.process_dataset_derivative_rebuilds(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION process_dataset_derivative_rebuilds(p_limit integer); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.process_dataset_derivative_rebuilds(p_limit integer) IS 'Private bounded coordinator for fenced flow/process derivative rebuilds. It never waits on network calls in-transaction; pg_net/PGMQ work is correlated through durable ids and staged proposals.';


--
-- Name: process_dataset_extraction_jobs(integer, integer, integer, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.process_dataset_extraction_jobs(batch_size integer DEFAULT 5, visibility_timeout_seconds integer DEFAULT 300, max_read_count integer DEFAULT 5, timeout_milliseconds integer DEFAULT ((5 * 60) * 1000)) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if batch_size <= 0 then
    return;
  end if;

  if not pg_try_advisory_xact_lock(hashtext('util.process_dataset_extraction_jobs')) then
    return;
  end if;

  perform util.invoke_edge_function(
    name => 'process_dataset_extraction_jobs',
    body => jsonb_build_object(
      'batchSize', least(batch_size, 50),
      'visibilityTimeoutSeconds', least(greatest(visibility_timeout_seconds, 1), 3600),
      'maxReadCount', least(greatest(max_read_count, 1), 100)
    ),
    timeout_milliseconds => timeout_milliseconds
  );
end;
$$;


ALTER FUNCTION util.process_dataset_extraction_jobs(batch_size integer, visibility_timeout_seconds integer, max_read_count integer, timeout_milliseconds integer) OWNER TO postgres;

--
-- Name: FUNCTION process_dataset_extraction_jobs(batch_size integer, visibility_timeout_seconds integer, max_read_count integer, timeout_milliseconds integer); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.process_dataset_extraction_jobs(batch_size integer, visibility_timeout_seconds integer, max_read_count integer, timeout_milliseconds integer) IS 'Invokes the Edge dataset extraction worker that claims and acknowledges compact dataset extraction jobs.';


--
-- Name: process_dataset_review_submit_jobs(integer, integer, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.process_dataset_review_submit_jobs(batch_size integer DEFAULT 10, stale_submitting_seconds integer DEFAULT 300, timeout_milliseconds integer DEFAULT 60000) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(batch_size, 0) <= 0 then
    return;
  end if;

  if not pg_try_advisory_xact_lock(hashtext('util.process_dataset_review_submit_jobs')) then
    return;
  end if;

  perform util.invoke_edge_function(
    name => 'process_dataset_review_submit_jobs',
    body => jsonb_build_object(
      'batchSize', least(greatest(batch_size, 1), 50),
      'staleSubmittingSeconds', least(greatest(coalesce(stale_submitting_seconds, 300), 1), 3600)
    ),
    timeout_milliseconds => least(greatest(coalesce(timeout_milliseconds, 60000), 1000), 300000)
  );
end;
$$;


ALTER FUNCTION util.process_dataset_review_submit_jobs(batch_size integer, stale_submitting_seconds integer, timeout_milliseconds integer) OWNER TO postgres;

--
-- Name: FUNCTION process_dataset_review_submit_jobs(batch_size integer, stale_submitting_seconds integer, timeout_milliseconds integer); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.process_dataset_review_submit_jobs(batch_size integer, stale_submitting_seconds integer, timeout_milliseconds integer) IS 'Invokes the Edge review-submit coordinator that advances retained review-submit request rows after worker gate results are available. The function name is kept for scheduling compatibility.';


--
-- Name: process_embeddings(integer, integer, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.process_embeddings(batch_size integer DEFAULT 3, max_requests integer DEFAULT 3, timeout_milliseconds integer DEFAULT ((5 * 60) * 1000)) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  job_batches jsonb[];
  batch jsonb;
  edge_fn text;
  timeout_seconds integer;
  selector_time timestamp with time zone;
begin
  if batch_size <= 0 or max_requests <= 0 then
    return;
  end if;

  if not pg_try_advisory_xact_lock(hashtext('util.process_embeddings')) then
    return;
  end if;

  timeout_seconds := greatest(1, ceiling(timeout_milliseconds / 1000.0)::integer);
  selector_time := clock_timestamp();

  with expired_jobs as (
    select
      q.msg_id,
      q.message,
      q.read_ct,
      p.max_read_count
    from pgmq.q_embedding_jobs q
    cross join lateral util.embedding_queue_policy_for(
      coalesce(q.message->>'schema', ''),
      coalesce(q.message->>'table', ''),
      coalesce(q.message->>'edgeFunction', 'embedding'),
      coalesce(q.message->>'embeddingColumn', '')
    ) p
    where q.vt <= selector_time
      and q.read_ct >= p.max_read_count
    order by q.msg_id
    limit greatest(batch_size * max_requests, 100)
  ),
  recorded_failures as (
    insert into util.embedding_job_failures (
      queue_name,
      msg_id,
      read_count,
      reason,
      message
    )
    select
      'embedding_jobs',
      expired.msg_id,
      expired.read_ct,
      format('read_ct reached retry cap %s', expired.max_read_count),
      expired.message
    from expired_jobs expired
    returning msg_id
  )
  delete from pgmq.q_embedding_jobs queued
  using recorded_failures failure
  where queued.msg_id = failure.msg_id;

  selector_time := clock_timestamp();

  with visible_jobs as materialized (
    select
      queued.msg_id,
      queued.message,
      coalesce(queued.message->>'schema', '') as schema_name,
      coalesce(queued.message->>'table', '') as table_name,
      coalesce(queued.message->>'edgeFunction', 'embedding') as edge_function,
      coalesce(queued.message->>'embeddingColumn', '') as embedding_column
    from pgmq.q_embedding_jobs queued
    where queued.vt <= selector_time
  ),
  visible_scopes as materialized (
    select distinct
      visible.schema_name,
      visible.table_name,
      visible.edge_function,
      visible.embedding_column
    from visible_jobs visible
  ),
  scope_policies as materialized (
    select
      scope.schema_name,
      scope.table_name,
      scope.edge_function,
      scope.embedding_column,
      policy.max_in_flight
    from visible_scopes scope
    cross join lateral util.embedding_queue_policy_for(
      scope.schema_name,
      scope.table_name,
      scope.edge_function,
      scope.embedding_column
    ) policy
    where policy.mode = 'normal'
  ),
  active_counts as materialized (
    select
      coalesce(active.message->>'schema', '') as schema_name,
      coalesce(active.message->>'table', '') as table_name,
      coalesce(active.message->>'edgeFunction', 'embedding') as edge_function,
      coalesce(active.message->>'embeddingColumn', '') as embedding_column,
      count(*)::integer as active_count
    from pgmq.q_embedding_jobs active
    where active.vt > selector_time
    group by 1, 2, 3, 4
  ),
  scoped_jobs as (
    select
      visible.*,
      policy.max_in_flight,
      coalesce(active.active_count, 0) as active_count,
      row_number() over (
        partition by
          visible.schema_name,
          visible.table_name,
          visible.edge_function,
          visible.embedding_column
        order by visible.msg_id
      ) as scope_position
    from visible_jobs visible
    join scope_policies policy using (
      schema_name,
      table_name,
      edge_function,
      embedding_column
    )
    left join active_counts active using (
      schema_name,
      table_name,
      edge_function,
      embedding_column
    )
  ),
  selected_jobs as (
    select *
    from scoped_jobs
    where active_count < max_in_flight
      and scope_position <= (max_in_flight - active_count)
    order by msg_id
    limit (batch_size * max_requests)
  ),
  claimed_jobs as (
    update pgmq.q_embedding_jobs queued
    set
      vt = clock_timestamp() + timeout_seconds * interval '1 second',
      read_ct = queued.read_ct + 1
    from selected_jobs selected
    where queued.msg_id = selected.msg_id
    returning
      queued.msg_id,
      queued.message || jsonb_build_object('jobId', queued.msg_id) as job_info,
      coalesce(queued.message->>'edgeFunction', 'embedding') as edge_function
  ),
  numbered_jobs as (
    select
      claimed.msg_id,
      claimed.job_info,
      claimed.edge_function,
      ((row_number() over (
        partition by claimed.edge_function
        order by claimed.msg_id
      ) - 1) / batch_size) as batch_num
    from claimed_jobs claimed
  ),
  batched_jobs as (
    select
      jsonb_agg(numbered.job_info order by numbered.msg_id) as batch_array,
      numbered.edge_function,
      numbered.batch_num
    from numbered_jobs numbered
    group by numbered.edge_function, numbered.batch_num
    order by numbered.edge_function, numbered.batch_num
  )
  select array_agg(batched.batch_array)
  from batched_jobs batched
  into job_batches;

  if job_batches is null then
    return;
  end if;

  foreach batch in array job_batches loop
    edge_fn := batch->0->>'edgeFunction';

    perform util.invoke_edge_function(
      name => edge_fn,
      body => batch,
      timeout_milliseconds => timeout_milliseconds
    );
  end loop;
end;
$$;


ALTER FUNCTION util.process_embeddings(batch_size integer, max_requests integer, timeout_milliseconds integer) OWNER TO postgres;

--
-- Name: FUNCTION process_embeddings(batch_size integer, max_requests integer, timeout_milliseconds integer); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.process_embeddings(batch_size integer, max_requests integer, timeout_milliseconds integer) IS 'Claims embedding work under per-scope backpressure using one active-count aggregation per queue snapshot rather than one full queue scan per visible job.';


