--
-- Name: purge_cron_job_run_details(interval); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.purge_cron_job_run_details(p_retention_window interval DEFAULT '14 days'::interval) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  deleted_count bigint;
begin
  if p_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'cron job run details retention window must be at least 1 day';
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext('util.purge_cron_job_run_details')
  ) then
    return 0;
  end if;

  delete from cron.job_run_details as details
   where details.end_time is not null
     and details.end_time < pg_catalog.now() - p_retention_window
     and coalesce(details.status, '') <> 'running';

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION util.purge_cron_job_run_details(p_retention_window interval) OWNER TO postgres;

--
-- Name: FUNCTION purge_cron_job_run_details(p_retention_window interval); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.purge_cron_job_run_details(p_retention_window interval) IS 'Deletes completed pg_cron run details older than the retention window; open rows and status=running rows are protected.';


--
-- Name: purge_supabase_functions_hooks(interval, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.purge_supabase_functions_hooks(p_retention_window interval DEFAULT '14 days'::interval, p_batch_size integer DEFAULT 50000) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  deleted_count bigint;
begin
  if p_retention_window is null or p_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'supabase functions hooks retention window must be at least 1 day';
  end if;

  if p_batch_size is null or p_batch_size < 1 or p_batch_size > 100000 then
    raise exception using
      errcode = '22023',
      message = 'supabase functions hooks purge batch size must be between 1 and 100000';
  end if;

  if to_regclass('supabase_functions.hooks') is null then
    return 0;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext('util.purge_supabase_functions_hooks')
  ) then
    return 0;
  end if;

  with live_responses as materialized (
    select response.id
    from net._http_response as response
  ), candidates as (
    select hooks.id
    from supabase_functions.hooks as hooks
    left join live_responses on live_responses.id = hooks.request_id
    where hooks.created_at < pg_catalog.now() - p_retention_window
      and live_responses.id is null
    order by hooks.created_at, hooks.id
    limit p_batch_size
    for update of hooks skip locked
  )
  delete from supabase_functions.hooks as hooks
  using candidates
  where hooks.id = candidates.id;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION util.purge_supabase_functions_hooks(p_retention_window interval, p_batch_size integer) OWNER TO postgres;

--
-- Name: FUNCTION purge_supabase_functions_hooks(p_retention_window interval, p_batch_size integer); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.purge_supabase_functions_hooks(p_retention_window interval, p_batch_size integer) IS 'Deletes Supabase Functions webhook audit rows older than the retention window in bounded batches while protecting rows still linked to live pg_net responses.';


--
-- Name: quarantine_dataset_derivative_rebuild_target(uuid, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.quarantine_dataset_derivative_rebuild_target(p_id uuid, p_version text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select util.quarantine_dataset_derivative_rebuild_target(
    'processes',
    p_id,
    p_version
  )
$$;


ALTER FUNCTION util.quarantine_dataset_derivative_rebuild_target(p_id uuid, p_version text) OWNER TO postgres;

--
-- Name: quarantine_dataset_derivative_rebuild_target(text, uuid, text); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.quarantine_dataset_derivative_rebuild_target(p_table text, p_id uuid, p_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_http integer := 0;
  v_embedding integer := 0;
  v_pending integer := 0;
begin
  if p_table is null or p_table not in ('flows', 'processes') then
    raise exception using
      errcode = '22023',
      message = 'Derivative quarantine target table must be flows or processes';
  end if;

  delete from net.http_request_queue as request
  where (
      request.url like '%/functions/v1/webhook_process_embedding_ft'
      or request.url like '%/functions/v1/webhook_flow_embedding_ft'
      or request.url like '%/functions/v1/embedding_ft'
    )
    and util.dataset_derivative_rebuild_http_body_matches(
      request.body,
      p_table,
      p_id,
      p_version
    );
  get diagnostics v_http = row_count;

  delete from pgmq.q_embedding_jobs as job
  where job.message->>'id' = p_id::text
    and btrim(job.message->>'version') = p_version
    and job.message->>'schema' = 'public'
    and job.message->>'table' = p_table
    and job.message->>'embeddingColumn' = 'embedding_ft';
  get diagnostics v_embedding = row_count;

  delete from util.pending_embedding_jobs as pending
  where pending.schema_name = 'public'
    and pending.table_name = p_table
    and pending.record_id = p_id::text
    and btrim(pending.record_version) = p_version
    and pending.embedding_column = 'embedding_ft';
  get diagnostics v_pending = row_count;

  return jsonb_build_object(
    'http_requests', v_http,
    'embedding_jobs', v_embedding,
    'pending_jobs', v_pending
  );
end;
$$;


ALTER FUNCTION util.quarantine_dataset_derivative_rebuild_target(p_table text, p_id uuid, p_version text) OWNER TO postgres;

--
-- Name: queue_dataset_extraction_jobs(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.queue_dataset_extraction_jobs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entity_kind text;
  v_message jsonb;
begin
  if TG_TABLE_SCHEMA <> 'public' then
    raise exception 'dataset extraction jobs only support public schema, got %', TG_TABLE_SCHEMA;
  end if;

  v_entity_kind := case TG_TABLE_NAME
    when 'flows' then 'flow'
    when 'processes' then 'process'
    when 'contacts' then 'contact'
    when 'flowproperties' then 'flowproperty'
    when 'sources' then 'source'
    when 'unitgroups' then 'unitgroup'
    else null
  end;

  if v_entity_kind is null then
    raise exception 'unsupported dataset extraction table %', TG_TABLE_NAME;
  end if;

  v_message := jsonb_build_object(
    'schema', TG_TABLE_SCHEMA,
    'table', TG_TABLE_NAME,
    'id', NEW.id,
    'version', btrim(NEW.version::text),
    'entity_kind', v_entity_kind,
    'extraction_kind', 'extracted_md',
    'created_at', clock_timestamp()
  );

  perform pgmq.send(
    queue_name => 'dataset_extraction_jobs',
    msg => v_message
  );

  return NEW;
end;
$$;


ALTER FUNCTION util.queue_dataset_extraction_jobs() OWNER TO postgres;

--
-- Name: FUNCTION queue_dataset_extraction_jobs(); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.queue_dataset_extraction_jobs() IS 'Queues compact dataset extraction jobs for asynchronous extracted_md generation without carrying json/json_ordered in the transaction payload.';


--
-- Name: queue_embeddings(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.queue_embeddings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_content_function text = tg_argv[0];
  v_embedding_column text = tg_argv[1];
  v_edge_function text := coalesce(tg_argv[2], 'embedding');
  v_queue_mode text;
  v_message jsonb;
begin
  if tg_table_schema = 'public'
    and tg_table_name in ('flows', 'processes')
    and exists (
      select 1
      from util.dataset_derivative_rebuild_permits as permit
      join util.dataset_derivative_rebuild_requests as request
        on request.id = permit.request_id
      where permit.permit_kind = 'markdown'
        and permit.backend_pid = pg_catalog.pg_backend_pid()
        and permit.transaction_id = pg_catalog.txid_current()
        and request.target_table = tg_table_name
        and request.target_id = new.id
        and request.target_version = btrim(new.version::text)
    ) then
    return new;
  end if;

  v_message := jsonb_build_object(
    'id', new.id,
    'version', new.version,
    'schema', tg_table_schema,
    'table', tg_table_name,
    'contentFunction', v_content_function,
    'embeddingColumn', v_embedding_column,
    'edgeFunction', v_edge_function
  );

  select policy.mode
  into v_queue_mode
  from util.embedding_queue_policy_for(
    tg_table_schema,
    tg_table_name,
    v_edge_function,
    v_embedding_column
  ) as policy;

  if v_queue_mode in ('deferred', 'paused') then
    insert into util.pending_embedding_jobs (
      schema_name,
      table_name,
      record_id,
      record_version,
      content_function,
      embedding_column,
      edge_function,
      message
    ) values (
      tg_table_schema,
      tg_table_name,
      new.id::text,
      new.version::text,
      v_content_function,
      v_embedding_column,
      v_edge_function,
      v_message
    )
    on conflict (
      schema_name,
      table_name,
      record_id,
      record_version,
      embedding_column,
      edge_function
    ) where status = 'pending'
    do update set
      content_function = excluded.content_function,
      message = excluded.message,
      updated_at = pg_catalog.clock_timestamp();
    return new;
  end if;

  perform pgmq.send(
    queue_name => 'embedding_jobs',
    msg => v_message
  );
  return new;
end;
$$;


ALTER FUNCTION util.queue_embeddings() OWNER TO postgres;

--
-- Name: read_dataset_alias_execution_primary_closure(uuid, jsonb); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.read_dataset_alias_execution_primary_closure(p_actor uuid, p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_batch_count integer := 0;
  v_action_count integer := 0;
  v_distinct_action_count integer := 0;
  v_flowproperty_count integer := 0;
  v_flow_count integer := 0;
  v_process_count integer := 0;
  v_support_count integer := 0;
  v_flowproperty_support_count integer := 0;
  v_unitgroup_support_count integer := 0;
  v_source_unitgroup_support_count integer := 0;
  v_invalid_action_count integer := 0;
  v_invalid_support_count integer := 0;
  v_action_evidence jsonb := '[]'::jsonb;
  v_support_evidence jsonb := '[]'::jsonb;
  v_proof_material jsonb;
  v_live_closure boolean := false;
begin
  if p_actor is null
    or jsonb_typeof(p_plan) is distinct from 'object'
    or jsonb_typeof(p_plan->'batches') is distinct from 'array' then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-alias-primary-closure.v1',
      'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_INVALID_INPUT',
      'live_closure_proof', false
    );
  end if;

  select jsonb_array_length(p_plan->'batches')
  into v_batch_count;

  select
    count(*)::integer,
    count(distinct (
      action_item.value->>'table',
      action_item.value->>'id',
      action_item.value->>'version'
    ))::integer,
    count(*) filter (
      where action_item.value->>'table' = 'flowproperties'
    )::integer,
    count(*) filter (
      where action_item.value->>'table' = 'flows'
    )::integer,
    count(*) filter (
      where action_item.value->>'table' = 'processes'
    )::integer
  into
    v_action_count,
    v_distinct_action_count,
    v_flowproperty_count,
    v_flow_count,
    v_process_count
  from jsonb_array_elements(p_plan->'batches') as batch_item(value)
  cross join lateral jsonb_array_elements(
    batch_item.value->'actions'
  ) as action_item(value);

  if v_batch_count <> 2
    or v_action_count <> 52
    or v_distinct_action_count <> 52
    or v_flowproperty_count <> 2
    or v_flow_count <> 23
    or v_process_count <> 27
    or exists (
      select 1
      from jsonb_array_elements(p_plan->'batches') as batch_item(value)
      cross join lateral jsonb_array_elements(
        batch_item.value->'actions'
      ) as action_item(value)
      where jsonb_typeof(action_item.value) is distinct from 'object'
        or action_item.value->>'table' not in (
          'flowproperties', 'flows', 'processes'
        )
        or (action_item.value->>'id')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or (action_item.value->>'version')
          !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or jsonb_typeof(action_item.value->'desired_json_ordered')
          is distinct from 'object'
    ) then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-alias-primary-closure.v1',
      'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_PLAN_SHAPE_MISMATCH',
      'live_closure_proof', false,
      'batch_count', v_batch_count,
      'action_count', v_action_count,
      'distinct_action_count', v_distinct_action_count,
      'flowproperty_count', v_flowproperty_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count
    );
  end if;

  with actions as (
    select
      batch_item.ordinality::integer as batch_ordinality,
      action_item.ordinality::integer as action_ordinality,
      batch_item.value->>'dimension' as dimension,
      action_item.value->>'action_id' as action_id,
      action_item.value->>'table' as table_name,
      (action_item.value->>'id')::uuid as id,
      action_item.value->>'version' as version,
      action_item.value->'desired_json_ordered' as desired_json_ordered
    from jsonb_array_elements(p_plan->'batches') with ordinality
      as batch_item(value, ordinality)
    cross join lateral jsonb_array_elements(
      batch_item.value->'actions'
    ) with ordinality as action_item(value, ordinality)
  ),
  live as (
    select
      action.*,
      dataset_row.id is not null as row_found,
      dataset_row.user_id as live_user_id,
      dataset_row.state_code as live_state_code,
      dataset_row.json::jsonb as live_json,
      dataset_row.json_ordered::jsonb as live_json_ordered
    from actions as action
    left join public.flowproperties as dataset_row
      on dataset_row.id = action.id
     and dataset_row.version::text = action.version
    where action.table_name = 'flowproperties'

    union all

    select
      action.*,
      dataset_row.id is not null,
      dataset_row.user_id,
      dataset_row.state_code,
      dataset_row.json::jsonb,
      dataset_row.json_ordered::jsonb
    from actions as action
    left join public.flows as dataset_row
      on dataset_row.id = action.id
     and dataset_row.version::text = action.version
    where action.table_name = 'flows'

    union all

    select
      action.*,
      dataset_row.id is not null,
      dataset_row.user_id,
      dataset_row.state_code,
      dataset_row.json::jsonb,
      dataset_row.json_ordered::jsonb
    from actions as action
    left join public.processes as dataset_row
      on dataset_row.id = action.id
     and dataset_row.version::text = action.version
    where action.table_name = 'processes'
  ),
  evidence as (
    select
      live.*,
      (
        row_found
        and live_user_id = p_actor
        and live_state_code = 0
        and live_json is not distinct from desired_json_ordered
        and live_json_ordered is not distinct from desired_json_ordered
      ) as valid
    from live
  ),
  hashed_evidence as (
    select
      evidence.*,
      util.dataset_alias_execution_sha256(
        desired_json_ordered::text
      ) as desired_json_ordered_sha256
    from evidence
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'batch_ordinality', batch_ordinality,
          'action_ordinality', action_ordinality,
          'dimension', dimension,
          'action_id', action_id,
          'table', table_name,
          'id', id,
          'version', version,
          'row_found', row_found,
          'owner_matches', live_user_id = p_actor,
          'state_code_matches', live_state_code = 0,
          'json_matches', live_json is not distinct from desired_json_ordered,
          'json_ordered_matches',
            live_json_ordered is not distinct from desired_json_ordered,
          'desired_json_ordered_sha256', desired_json_ordered_sha256,
          'live_json_sha256', case
            when not row_found then null
            when live_json is not distinct from desired_json_ordered then
              desired_json_ordered_sha256
            else util.dataset_alias_execution_sha256(live_json::text)
          end,
          'live_json_ordered_sha256', case
            when not row_found then null
            when live_json_ordered is not distinct from desired_json_ordered then
              desired_json_ordered_sha256
            else util.dataset_alias_execution_sha256(
              live_json_ordered::text
            )
          end,
          'valid', valid
        ) order by batch_ordinality, action_ordinality
      ),
      '[]'::jsonb
    ),
    count(*) filter (where not valid)::integer
  into v_action_evidence, v_invalid_action_count
  from hashed_evidence;

  select
    count(*)::integer,
    count(*) filter (
      where support_item.role = 'flowproperty'
    )::integer,
    count(*) filter (
      where support_item.role = 'unitgroup'
    )::integer,
    count(*) filter (
      where support_item.role = 'source_unitgroup'
    )::integer
  into
    v_support_count,
    v_flowproperty_support_count,
    v_unitgroup_support_count,
    v_source_unitgroup_support_count
  from jsonb_array_elements(p_plan->'batches') as batch_item(value)
  cross join lateral (values
    ('flowproperty'::text, batch_item.value#>'{target,flowproperty}'),
    ('unitgroup'::text, batch_item.value#>'{target,unitgroup}'),
    ('source_unitgroup'::text,
      batch_item.value#>'{target,source_unitgroup}')
  ) as support_item(role, snapshot);

  if v_support_count <> 6
    or v_flowproperty_support_count <> 2
    or v_unitgroup_support_count <> 2
    or v_source_unitgroup_support_count <> 2
    or exists (
      select 1
      from jsonb_array_elements(p_plan->'batches') as batch_item(value)
      cross join lateral (values
        ('flowproperty'::text, batch_item.value#>'{target,flowproperty}'),
        ('unitgroup'::text, batch_item.value#>'{target,unitgroup}'),
        ('source_unitgroup'::text,
          batch_item.value#>'{target,source_unitgroup}')
      ) as support_item(role, snapshot)
      where jsonb_typeof(support_item.snapshot) is distinct from 'object'
        or not (support_item.snapshot ?& array[
          'id', 'version', 'expected_modified_at', 'expected_json_ordered'
        ])
        or exists (
          select 1
          from jsonb_object_keys(support_item.snapshot)
            as support_key(key)
          where support_key.key <> all (array[
            'id', 'version', 'expected_modified_at',
            'expected_json_ordered'
          ])
        )
        or (support_item.snapshot->>'id')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or (support_item.snapshot->>'version')
          !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or jsonb_typeof(support_item.snapshot->'expected_modified_at')
          is distinct from 'string'
        or jsonb_typeof(support_item.snapshot->'expected_json_ordered')
          is distinct from 'object'
    ) then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-alias-primary-closure.v1',
      'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_SUPPORT_SHAPE_MISMATCH',
      'live_closure_proof', false,
      'support_reference_count', v_support_count
    );
  end if;

  with supports as (
    select
      batch_item.ordinality::integer as batch_ordinality,
      batch_item.value->>'dimension' as dimension,
      support_item.role,
      case
        when support_item.role = 'flowproperty' then 'flowproperties'
        else 'unitgroups'
      end as table_name,
      (support_item.snapshot->>'id')::uuid as id,
      support_item.snapshot->>'version' as version,
      (support_item.snapshot->>'expected_modified_at')::timestamptz
        as expected_modified_at,
      support_item.snapshot->'expected_json_ordered'
        as expected_json_ordered
    from jsonb_array_elements(p_plan->'batches') with ordinality
      as batch_item(value, ordinality)
    cross join lateral (values
      ('flowproperty'::text, batch_item.value#>'{target,flowproperty}'),
      ('unitgroup'::text, batch_item.value#>'{target,unitgroup}'),
      ('source_unitgroup'::text,
        batch_item.value#>'{target,source_unitgroup}')
    ) as support_item(role, snapshot)
  ),
  live as (
    select
      support.*,
      dataset_row.id is not null as row_found,
      dataset_row.user_id as live_user_id,
      dataset_row.state_code as live_state_code,
      dataset_row.modified_at as live_modified_at,
      dataset_row.json::jsonb as live_json,
      dataset_row.json_ordered::jsonb as live_json_ordered
    from supports as support
    left join public.flowproperties as dataset_row
      on dataset_row.id = support.id
     and dataset_row.version::text = support.version
    where support.table_name = 'flowproperties'

    union all

    select
      support.*,
      dataset_row.id is not null,
      dataset_row.user_id,
      dataset_row.state_code,
      dataset_row.modified_at,
      dataset_row.json::jsonb,
      dataset_row.json_ordered::jsonb
    from supports as support
    left join public.unitgroups as dataset_row
      on dataset_row.id = support.id
     and dataset_row.version::text = support.version
    where support.table_name = 'unitgroups'
  ),
  evidence as (
    select
      live.*,
      (
        row_found
        and live_user_id = p_actor
        and live_state_code = 0
        and live_modified_at is not distinct from expected_modified_at
        and live_json is not distinct from expected_json_ordered
        and live_json_ordered is not distinct from expected_json_ordered
      ) as valid
    from live
  ),
  hashed_evidence as (
    select
      evidence.*,
      util.dataset_alias_execution_sha256(
        expected_json_ordered::text
      ) as expected_json_ordered_sha256
    from evidence
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'batch_ordinality', batch_ordinality,
          'dimension', dimension,
          'role', role,
          'table', table_name,
          'id', id,
          'version', version,
          'row_found', row_found,
          'owner_matches', live_user_id = p_actor,
          'state_code_matches', live_state_code = 0,
          'modified_at_matches',
            live_modified_at is not distinct from expected_modified_at,
          'json_matches', live_json is not distinct from expected_json_ordered,
          'json_ordered_matches',
            live_json_ordered is not distinct from expected_json_ordered,
          'expected_modified_at', expected_modified_at,
          'live_modified_at', live_modified_at,
          'expected_json_ordered_sha256', expected_json_ordered_sha256,
          'live_json_sha256', case
            when not row_found then null
            when live_json is not distinct from expected_json_ordered then
              expected_json_ordered_sha256
            else util.dataset_alias_execution_sha256(live_json::text)
          end,
          'live_json_ordered_sha256', case
            when not row_found then null
            when live_json_ordered is not distinct from expected_json_ordered then
              expected_json_ordered_sha256
            else util.dataset_alias_execution_sha256(
              live_json_ordered::text
            )
          end,
          'valid', valid
        ) order by
          batch_ordinality,
          case role
            when 'flowproperty' then 1
            when 'unitgroup' then 2
            else 3
          end
      ),
      '[]'::jsonb
    ),
    count(*) filter (where not valid)::integer
  into v_support_evidence, v_invalid_support_count
  from hashed_evidence;

  v_live_closure :=
    v_invalid_action_count = 0
    and v_invalid_support_count = 0;

  v_proof_material := jsonb_build_object(
    'schema_version', 'dataset-alias-primary-closure.v1',
    'actor_user_id', p_actor,
    'batch_count', v_batch_count,
    'action_count', v_action_count,
    'distinct_action_count', v_distinct_action_count,
    'flowproperty_count', v_flowproperty_count,
    'flow_count', v_flow_count,
    'process_count', v_process_count,
    'support_reference_count', v_support_count,
    'flowproperty_support_count', v_flowproperty_support_count,
    'unitgroup_support_count', v_unitgroup_support_count,
    'source_unitgroup_support_count', v_source_unitgroup_support_count,
    'invalid_action_count', v_invalid_action_count,
    'invalid_support_count', v_invalid_support_count,
    'action_evidence', v_action_evidence,
    'support_evidence', v_support_evidence,
    'live_closure_proof', v_live_closure
  );

  return v_proof_material || jsonb_build_object(
    'ok', v_live_closure,
    'row_count', case when v_live_closure then 52 else null end,
    'exchange_count', case when v_live_closure then 59 else null end,
    'live_closure_proof_sha256',
      util.dataset_alias_execution_artifact_sha256(v_proof_material)
  );
exception
  when others then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-alias-primary-closure.v1',
      'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_READ_FAILED',
      'live_closure_proof', false
    );
end;
$_$;


ALTER FUNCTION util.read_dataset_alias_execution_primary_closure(p_actor uuid, p_plan jsonb) OWNER TO postgres;

--
-- Name: FUNCTION read_dataset_alias_execution_primary_closure(p_actor uuid, p_plan jsonb); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.read_dataset_alias_execution_primary_closure(p_actor uuid, p_plan jsonb) IS 'Private live readback for the exact 52 desired owner-draft rows and all six unchanged support-snapshot occurrences. Full desired payload equality causally proves the frozen 59 exchange rewrites; malformed or drifting state fails closed.';


--
-- Name: read_dataset_derivative_rebuild_batch(uuid, uuid); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.read_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_snapshot jsonb;
  v_targets jsonb := '[]'::jsonb;
  v_target_count integer := 0;
  v_flow_count integer := 0;
  v_process_count integer := 0;
  v_completed_count integer := 0;
  v_nonterminal_count integer := 0;
  v_failed_count integer := 0;
  v_invalid_proof_count integer := 0;
  v_completed_invalid_proof_count integer := 0;
  v_distinct_ordinal_count integer := 0;
  v_distinct_target_count integer := 0;
  v_distinct_plan_count integer := 0;
  v_distinct_summary_count integer := 0;
  v_min_ordinal integer;
  v_max_ordinal integer;
  v_batch_sizes_ok boolean := false;
  v_primary_ok boolean;
  v_terminal_snapshot_ok boolean;
  v_proposals_ok boolean;
  v_terminal_audit_ok boolean;
  v_derivative_fresh boolean;
  v_lifecycle_ok boolean;
  v_http_residue integer;
  v_embedding_residue integer;
  v_pending_residue integer;
  v_failure_residue integer;
  v_fence_residue integer;
  v_target_ok boolean;
  v_batch_integrity_ok boolean;
  v_status text;
  v_code text;
begin
  if p_actor_user_id is null or p_batch_id is null then
    return jsonb_build_object(
      'ok', false,
      'status', 'failed',
      'code', 'DERIVATIVE_BATCH_READ_INVALID_REQUEST',
      'causal_terminal_proof', false
    );
  end if;

  select
    count(*)::integer,
    count(*) filter (where target_table = 'flows')::integer,
    count(*) filter (where target_table = 'processes')::integer,
    count(*) filter (where status = 'completed')::integer,
    count(*) filter (
      where status not in ('completed', 'stale', 'failed')
    )::integer,
    count(*) filter (where status in ('stale', 'failed'))::integer,
    count(distinct batch_ordinal)::integer,
    count(distinct (
      target_table || ':' || target_id::text || '@' || target_version
    ))::integer,
    count(distinct plan_request_sha256)::integer,
    count(distinct summary_audit_id)::integer,
    min(batch_ordinal)::integer,
    max(batch_ordinal)::integer,
    coalesce(bool_and(batch_target_count = 50), false)
  into
    v_target_count,
    v_flow_count,
    v_process_count,
    v_completed_count,
    v_nonterminal_count,
    v_failed_count,
    v_distinct_ordinal_count,
    v_distinct_target_count,
    v_distinct_plan_count,
    v_distinct_summary_count,
    v_min_ordinal,
    v_max_ordinal,
    v_batch_sizes_ok
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = p_actor_user_id
    and request.batch_id = p_batch_id;

  v_batch_integrity_ok := v_target_count = 50
    and v_flow_count = 23
    and v_process_count = 27
    and v_distinct_ordinal_count = 50
    and v_distinct_target_count = 50
    and v_distinct_plan_count = 1
    and v_distinct_summary_count = 1
    and v_min_ordinal = 1
    and v_max_ordinal = 50
    and v_batch_sizes_ok;

  if not v_batch_integrity_ok then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-derivative-rebuild-batch-status.v1',
      'batch_id', p_batch_id,
      'status', 'failed',
      'code', 'DERIVATIVE_BATCH_TARGET_SET_MISMATCH',
      'causal_terminal_proof', false,
      'target_count', v_target_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count,
      'completed_count', v_completed_count,
      'nonterminal_count', v_nonterminal_count,
      'failed_count', v_failed_count
    );
  end if;

  -- Polling must stay cheap while any child is still moving.  A causal proof
  -- is meaningful only after all 50 children are terminal; doing the full
  -- per-target snapshot/queue/proposal/audit closure on every pending poll
  -- would multiply hundreds of reads without improving the decision.
  if v_nonterminal_count > 0 or v_failed_count > 0 then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'ordinal', request.batch_ordinal,
          'request_id', request.id,
          'table', request.target_table,
          'id', request.target_id,
          'version', request.target_version,
          'status', request.status,
          'phase', request.phase,
          'error', request.last_error,
          'causal_terminal_proof', false
        ) order by request.batch_ordinal
      ),
      '[]'::jsonb
    )
    into v_targets
    from util.dataset_derivative_rebuild_requests as request
    where request.actor_user_id = p_actor_user_id
      and request.batch_id = p_batch_id;

    return jsonb_build_object(
      'ok', v_failed_count = 0,
      'schema_version', 'dataset-derivative-rebuild-batch-status.v1',
      'batch_id', p_batch_id,
      'status', case
        when v_failed_count > 0 then 'failed'
        else 'pending'
      end,
      'code', case
        when v_failed_count > 0 then 'DERIVATIVE_BATCH_CHILD_FAILED'
        else 'DERIVATIVE_BATCH_PENDING'
      end,
      'proof_level', 'status_only',
      'proof_deferred', v_failed_count = 0,
      'causal_terminal_proof', false,
      'target_count', v_target_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count,
      'completed_count', v_completed_count,
      'nonterminal_count', v_nonterminal_count,
      'failed_count', v_failed_count,
      'invalid_proof_count', null,
      'completed_invalid_proof_count', null,
      'targets', v_targets
    );
  end if;

  for v_request in
    select request.*
    from util.dataset_derivative_rebuild_requests as request
    where request.actor_user_id = p_actor_user_id
      and request.batch_id = p_batch_id
    order by request.batch_ordinal
  loop
    begin
      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_request.target_table,
        v_request.target_id,
        v_request.target_version
      );
    exception
      when others then
        v_snapshot := null;
    end;

    v_primary_ok := v_snapshot is not null
      and util.dataset_derivative_rebuild_primary_matches(v_request);
    v_terminal_snapshot_ok := coalesce(
      v_request.status = 'completed'
      and v_request.completed_snapshot_sha256 is not null
      and v_snapshot->>'snapshot_sha256'
        is not distinct from v_request.completed_snapshot_sha256,
      false
    );
    v_derivative_fresh := coalesce(
      v_snapshot->>'extracted_md_sha256' is not null
      and v_snapshot->>'embedding_ft_sha256' is not null
      and (v_snapshot->>'embedding_ft_at')::timestamp with time zone
        > coalesce(
          v_request.before_embedding_ft_at,
          '-infinity'::timestamp with time zone
        ),
      false
    );
    v_lifecycle_ok := coalesce(
      v_request.phase = 'completed'
      and v_request.markdown_request_id is not null
      and v_request.markdown_dispatched_at is not null
      and v_request.markdown_response_status between 200 and 299
      and v_request.markdown_response_received_at
        >= v_request.markdown_dispatched_at
      and v_request.markdown_proposal_id is not null
      and v_request.accepted_extracted_md_sha256 is not null
      and v_request.embedding_queue_msg_id is not null
      and v_request.embedding_queued_at
        >= v_request.markdown_response_received_at
      and v_request.embedding_proposal_id is not null
      and v_request.completed_at >= v_request.embedding_queued_at
      and v_request.terminal_at >= v_request.completed_at
      and v_request.drained_at >= v_request.completed_at,
      false
    );

    select
      (
        select count(*) = 2
        from util.dataset_derivative_rebuild_proposals as proposal
        where proposal.request_id = v_request.id
          and proposal.status <> 'discarded'
      )
      and exists (
        select 1
        from util.dataset_derivative_rebuild_proposals as proposal
        where proposal.id = v_request.markdown_proposal_id
          and proposal.request_id = v_request.id
          and proposal.proposal_kind = 'markdown'
          and proposal.status = 'committed'
          and proposal.captured_at >= v_request.markdown_dispatched_at
          and proposal.extracted_md_sha256
            = v_request.accepted_extracted_md_sha256
          and proposal.extracted_md_sha256
            = v_snapshot->>'extracted_md_sha256'
      )
      and exists (
        select 1
        from util.dataset_derivative_rebuild_proposals as proposal
        where proposal.id = v_request.embedding_proposal_id
          and proposal.request_id = v_request.id
          and proposal.proposal_kind = 'embedding'
          and proposal.status = 'committed'
          and proposal.captured_at >= v_request.embedding_queued_at
          and proposal.source_extracted_md_sha256
            = v_request.accepted_extracted_md_sha256
          and proposal.embedding_ft_sha256
            = v_snapshot->>'embedding_ft_sha256'
          and proposal.embedding_ft_at
            = (v_snapshot->>'embedding_ft_at')::timestamp with time zone
      )
    into v_proposals_ok;

    select count(*)::integer
    into v_http_residue
    from net.http_request_queue as request
    where util.dataset_derivative_rebuild_http_body_matches(
      request.body,
      v_request.target_table,
      v_request.target_id,
      v_request.target_version
    );

    select count(*)::integer
    into v_embedding_residue
    from pgmq.q_embedding_jobs as job
    where job.message->>'id' = v_request.target_id::text
      and btrim(job.message->>'version') = v_request.target_version
      and job.message->>'schema' = 'public'
      and job.message->>'table' = v_request.target_table
      and job.message->>'embeddingColumn' = 'embedding_ft';

    select count(*)::integer
    into v_pending_residue
    from util.pending_embedding_jobs as pending
    where pending.schema_name = 'public'
      and pending.table_name = v_request.target_table
      and pending.record_id = v_request.target_id::text
      and btrim(pending.record_version) = v_request.target_version
      and pending.embedding_column = 'embedding_ft'
      and pending.status = 'pending';

    select count(*)::integer
    into v_failure_residue
    from util.embedding_job_failures as failure
    where failure.msg_id = v_request.embedding_queue_msg_id;

    select count(*)::integer
    into v_fence_residue
    from util.dataset_derivative_rebuild_requests as active_request
    where active_request.id <> v_request.id
      and active_request.target_table = v_request.target_table
      and active_request.target_id = v_request.target_id
      and active_request.target_version = v_request.target_version
      and active_request.status not in ('completed', 'stale', 'failed');

    select count(*) = 1
    into v_terminal_audit_ok
    from public.command_audit_log as audit
    where audit.command = 'cmd_dataset_derivative_rebuild_terminal'
      and audit.actor_user_id = p_actor_user_id
      and audit.target_table = v_request.target_table
      and audit.target_id = v_request.target_id
      and audit.target_version = v_request.target_version
      and audit.payload->>'request_id' = v_request.id::text
      and audit.payload->>'status' = 'completed';

    v_target_ok := coalesce(v_primary_ok
      and v_terminal_snapshot_ok
      and v_derivative_fresh
      and v_lifecycle_ok
      and v_proposals_ok
      and v_terminal_audit_ok
      and v_http_residue = 0
      and v_embedding_residue = 0
      and v_pending_residue = 0
      and v_failure_residue = 0
      and v_fence_residue = 0, false);

    if not v_target_ok then
      v_invalid_proof_count := v_invalid_proof_count + 1;
      if v_request.status = 'completed' then
        v_completed_invalid_proof_count :=
          v_completed_invalid_proof_count + 1;
      end if;
    end if;

    v_targets := v_targets || jsonb_build_array(
      jsonb_build_object(
        'ordinal', v_request.batch_ordinal,
        'request_id', v_request.id,
        'table', v_request.target_table,
        'id', v_request.target_id,
        'version', v_request.target_version,
        'status', v_request.status,
        'phase', v_request.phase,
        'source_baseline_snapshot_sha256',
          v_request.source_baseline_snapshot_sha256,
        'expected_snapshot_sha256', v_request.expected_snapshot_sha256,
        'completed_snapshot_sha256',
          v_request.completed_snapshot_sha256,
        'primary_matches', v_primary_ok,
        'terminal_snapshot_matches', v_terminal_snapshot_ok,
        'proposals_committed', v_proposals_ok,
        'derivative_fresh', v_derivative_fresh,
        'lifecycle_complete', v_lifecycle_ok,
        'terminal_audit_present', v_terminal_audit_ok,
        'residue', jsonb_build_object(
          'http_requests', v_http_residue,
          'embedding_jobs', v_embedding_residue,
          'pending_jobs', v_pending_residue,
          'failure_rows', v_failure_residue,
          'other_active_fences', v_fence_residue
        ),
        'causal_terminal_proof', v_target_ok
      )
    );
  end loop;

  if v_failed_count > 0 then
    v_status := 'failed';
    v_code := 'DERIVATIVE_BATCH_CHILD_FAILED';
  elsif v_completed_invalid_proof_count > 0 then
    v_status := 'failed';
    v_code := 'DERIVATIVE_BATCH_CAUSAL_PROOF_MISMATCH';
  elsif v_nonterminal_count > 0 then
    v_status := 'pending';
    v_code := 'DERIVATIVE_BATCH_PENDING';
  elsif v_completed_count = 50 and v_invalid_proof_count = 0 then
    v_status := 'completed';
    v_code := 'DERIVATIVE_BATCH_COMPLETED';
  else
    v_status := 'failed';
    v_code := 'DERIVATIVE_BATCH_CAUSAL_PROOF_MISMATCH';
  end if;

  return jsonb_build_object(
    'ok', v_status <> 'failed',
    'schema_version', 'dataset-derivative-rebuild-batch-status.v1',
    'batch_id', p_batch_id,
    'status', v_status,
    'code', v_code,
    'proof_level', 'causal_terminal',
    'proof_deferred', false,
    'causal_terminal_proof',
      v_status = 'completed' and v_invalid_proof_count = 0,
    'target_count', v_target_count,
    'flow_count', v_flow_count,
    'process_count', v_process_count,
    'completed_count', v_completed_count,
    'nonterminal_count', v_nonterminal_count,
    'failed_count', v_failed_count,
    'invalid_proof_count', v_invalid_proof_count,
    'completed_invalid_proof_count', v_completed_invalid_proof_count,
    'targets', v_targets
  );
end;
$$;


ALTER FUNCTION util.read_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION read_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.read_dataset_derivative_rebuild_batch(p_actor_user_id uuid, p_batch_id uuid) IS 'Private fail-closed aggregate proof for the exact protected 23-flow + 27-process derivative batch. Pending/failed polls use one status-only aggregate; the expensive 50-target causal proof runs only after all children are terminal. It never advances or retries work.';


--
-- Name: read_dataset_derivative_rebuild_batch_any(uuid, uuid); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.read_dataset_derivative_rebuild_batch_any(p_actor_user_id uuid, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_snapshot jsonb;
  v_targets jsonb := '[]'::jsonb;
  v_target_count integer;
  v_flow_count integer;
  v_process_count integer;
  v_completed_count integer;
  v_nonterminal_count integer;
  v_failed_count integer;
  v_distinct_ordinal_count integer;
  v_distinct_target_count integer;
  v_distinct_plan_count integer;
  v_distinct_summary_count integer;
  v_distinct_declared_count integer;
  v_declared_count integer;
  v_min_ordinal integer;
  v_max_ordinal integer;
  v_invalid_proof_count integer := 0;
  v_primary_ok boolean;
  v_snapshot_ok boolean;
  v_derivative_fresh boolean;
  v_lifecycle_ok boolean;
  v_proposals_ok boolean;
  v_terminal_audit_ok boolean;
  v_residue jsonb;
  v_target_ok boolean;
  v_status text;
  v_code text;
  v_batch_rows integer;
  v_single_rows integer;
  v_is_batch boolean;
begin
  if p_actor_user_id is null or p_batch_id is null then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-derivative-rebuild-batch-status.v2',
      'status', 'failed',
      'code', 'DERIVATIVE_BATCH_READ_INVALID_REQUEST',
      'causal_terminal_proof', false
    );
  end if;

  -- A Step 3 primary transaction always records a protected batch id.  If
  -- that child later reaches a terminal failed/stale state, a separately
  -- frozen and approved derivative-only compensation is admitted through the
  -- retained single-target RPC and is identified by its request id.  This
  -- reader accepts either exact identity, never a loose target lookup.
  select
    count(*) filter (where request.batch_id = p_batch_id)::integer,
    count(*) filter (
      where request.batch_id is null and request.id = p_batch_id
    )::integer
  into v_batch_rows, v_single_rows
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = p_actor_user_id
    and (request.batch_id = p_batch_id or request.id = p_batch_id);

  if (v_batch_rows > 0 and v_single_rows > 0)
    or (v_batch_rows = 0 and v_single_rows <> 1) then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-derivative-rebuild-batch-status.v2',
      'reference_id', p_batch_id,
      'status', 'failed',
      'code', 'DERIVATIVE_BATCH_REFERENCE_AMBIGUOUS',
      'causal_terminal_proof', false
    );
  end if;
  v_is_batch := v_batch_rows > 0;

  select
    count(*)::integer,
    count(*) filter (where target_table = 'flows')::integer,
    count(*) filter (where target_table = 'processes')::integer,
    count(*) filter (where status = 'completed')::integer,
    count(*) filter (where status not in ('completed', 'stale', 'failed'))::integer,
    count(*) filter (where status in ('stale', 'failed'))::integer,
    count(distinct coalesce(batch_ordinal, 1))::integer,
    count(distinct (target_table || ':' || target_id::text || '@' || target_version))::integer,
    count(distinct plan_request_sha256)::integer,
    count(distinct summary_audit_id)::integer,
    count(distinct coalesce(batch_target_count, 1))::integer,
    min(coalesce(batch_target_count, 1))::integer,
    min(coalesce(batch_ordinal, 1))::integer,
    max(coalesce(batch_ordinal, 1))::integer
  into
    v_target_count, v_flow_count, v_process_count, v_completed_count,
    v_nonterminal_count, v_failed_count, v_distinct_ordinal_count,
    v_distinct_target_count, v_distinct_plan_count, v_distinct_summary_count,
    v_distinct_declared_count, v_declared_count, v_min_ordinal,
    v_max_ordinal
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = p_actor_user_id
    and (
      (v_is_batch and request.batch_id = p_batch_id)
      or (not v_is_batch and request.batch_id is null
        and request.id = p_batch_id)
    );

  if v_target_count not between 1 and 50
    or v_flow_count + v_process_count <> v_target_count
    or v_distinct_ordinal_count <> v_target_count
    or v_distinct_target_count <> v_target_count
    or v_distinct_plan_count <> 1
    or v_distinct_summary_count <> 1
    or v_distinct_declared_count <> 1
    or v_declared_count <> v_target_count
    or v_min_ordinal <> 1
    or v_max_ordinal <> v_target_count then
    return jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-derivative-rebuild-batch-status.v2',
      'reference_id', p_batch_id,
      'reference_kind', case when v_is_batch then 'batch' else 'request' end,
      'batch_id', case when v_is_batch then p_batch_id else null end,
      'request_id', case when v_is_batch then null else p_batch_id end,
      'status', 'failed',
      'code', 'DERIVATIVE_BATCH_TARGET_SET_MISMATCH',
      'causal_terminal_proof', false,
      'target_count', v_target_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count
    );
  end if;

  if v_nonterminal_count > 0 or v_failed_count > 0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', coalesce(request.batch_ordinal, 1),
      'request_id', request.id,
      'table', request.target_table,
      'id', request.target_id,
      'version', request.target_version,
      'status', request.status,
      'phase', request.phase,
      'error', request.last_error,
      'causal_terminal_proof', false
    ) order by request.batch_ordinal), '[]'::jsonb)
    into v_targets
    from util.dataset_derivative_rebuild_requests as request
    where request.actor_user_id = p_actor_user_id
      and (
        (v_is_batch and request.batch_id = p_batch_id)
        or (not v_is_batch and request.batch_id is null
          and request.id = p_batch_id)
      );

    return jsonb_build_object(
      'ok', v_failed_count = 0,
      'schema_version', 'dataset-derivative-rebuild-batch-status.v2',
      'reference_id', p_batch_id,
      'reference_kind', case when v_is_batch then 'batch' else 'request' end,
      'batch_id', case when v_is_batch then p_batch_id else null end,
      'request_id', case when v_is_batch then null else p_batch_id end,
      'status', case when v_failed_count > 0 then 'failed' else 'pending' end,
      'code', case when v_failed_count > 0
        then 'DERIVATIVE_BATCH_CHILD_FAILED'
        else 'DERIVATIVE_BATCH_PENDING' end,
      'proof_level', 'status_only',
      'causal_terminal_proof', false,
      'target_count', v_target_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count,
      'completed_count', v_completed_count,
      'nonterminal_count', v_nonterminal_count,
      'failed_count', v_failed_count,
      'targets', v_targets
    );
  end if;

  for v_request in
    select request.*
    from util.dataset_derivative_rebuild_requests as request
    where request.actor_user_id = p_actor_user_id
      and (
        (v_is_batch and request.batch_id = p_batch_id)
        or (not v_is_batch and request.batch_id is null
          and request.id = p_batch_id)
      )
    order by coalesce(request.batch_ordinal, 1)
  loop
    begin
      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_request.target_table,
        v_request.target_id,
        v_request.target_version
      );
    exception when others then
      v_snapshot := null;
    end;

    v_primary_ok := v_snapshot is not null
      and util.dataset_derivative_rebuild_primary_matches(v_request);
    v_snapshot_ok := coalesce(
      v_request.status = 'completed'
      and v_request.completed_snapshot_sha256 is not null
      and v_snapshot->>'snapshot_sha256'
        is not distinct from v_request.completed_snapshot_sha256,
      false
    );
    v_derivative_fresh := coalesce(
      v_snapshot->>'extracted_md_sha256' is not null
      and v_snapshot->>'embedding_ft_sha256' is not null
      and (v_snapshot->>'embedding_ft_at')::timestamp with time zone
        > coalesce(v_request.before_embedding_ft_at, '-infinity'::timestamp with time zone),
      false
    );
    v_lifecycle_ok := coalesce(
      v_request.phase = 'completed'
      and v_request.markdown_request_id is not null
      and v_request.markdown_dispatched_at is not null
      and v_request.markdown_response_status between 200 and 299
      and v_request.markdown_response_received_at >= v_request.markdown_dispatched_at
      and v_request.markdown_proposal_id is not null
      and v_request.accepted_extracted_md_sha256 is not null
      and v_request.embedding_queue_msg_id is not null
      and v_request.embedding_queued_at >= v_request.markdown_response_received_at
      and v_request.embedding_proposal_id is not null
      and v_request.completed_at >= v_request.embedding_queued_at
      and v_request.terminal_at >= v_request.completed_at
      and v_request.drained_at >= v_request.completed_at,
      false
    );

    select
      count(*) = 2
      and count(*) filter (
        where proposal.id = v_request.markdown_proposal_id
          and proposal.proposal_kind = 'markdown'
          and proposal.status = 'committed'
          and proposal.extracted_md_sha256
            = v_request.accepted_extracted_md_sha256
          and proposal.extracted_md_sha256
            = v_snapshot->>'extracted_md_sha256'
      ) = 1
      and count(*) filter (
        where proposal.id = v_request.embedding_proposal_id
          and proposal.proposal_kind = 'embedding'
          and proposal.status = 'committed'
          and proposal.source_extracted_md_sha256
            = v_request.accepted_extracted_md_sha256
          and proposal.embedding_ft_sha256
            = v_snapshot->>'embedding_ft_sha256'
          and proposal.embedding_ft_at
            = (v_snapshot->>'embedding_ft_at')::timestamp with time zone
      ) = 1
    into v_proposals_ok
    from util.dataset_derivative_rebuild_proposals as proposal
    where proposal.request_id = v_request.id
      and proposal.status <> 'discarded';

    select jsonb_build_object(
      'http_requests', (
        select count(*)
        from net.http_request_queue as request
        where util.dataset_derivative_rebuild_http_body_matches(
          request.body, v_request.target_table,
          v_request.target_id, v_request.target_version
        )
      ),
      'embedding_jobs', (
        select count(*)
        from pgmq.q_embedding_jobs as job
        where job.message->>'id' = v_request.target_id::text
          and btrim(job.message->>'version') = v_request.target_version
          and job.message->>'schema' = 'public'
          and job.message->>'table' = v_request.target_table
          and job.message->>'embeddingColumn' = 'embedding_ft'
      ),
      'pending_jobs', (
        select count(*)
        from util.pending_embedding_jobs as pending
        where pending.schema_name = 'public'
          and pending.table_name = v_request.target_table
          and pending.record_id = v_request.target_id::text
          and btrim(pending.record_version) = v_request.target_version
          and pending.embedding_column = 'embedding_ft'
          and pending.status = 'pending'
      ),
      'failure_rows', (
        select count(*)
        from util.embedding_job_failures as failure
        where failure.msg_id = v_request.embedding_queue_msg_id
      ),
      'other_active_fences', (
        select count(*)
        from util.dataset_derivative_rebuild_requests as active
        where active.id <> v_request.id
          and active.target_table = v_request.target_table
          and active.target_id = v_request.target_id
          and active.target_version = v_request.target_version
          and active.status not in ('completed', 'stale', 'failed')
      )
    ) into v_residue;

    select count(*) = 1
    into v_terminal_audit_ok
    from public.command_audit_log as audit
    where audit.command = 'cmd_dataset_derivative_rebuild_terminal'
      and audit.actor_user_id = p_actor_user_id
      and audit.target_table = v_request.target_table
      and audit.target_id = v_request.target_id
      and audit.target_version = v_request.target_version
      and audit.payload->>'request_id' = v_request.id::text
      and audit.payload->>'status' = 'completed';

    v_target_ok := coalesce(
      v_primary_ok and v_snapshot_ok and v_derivative_fresh
      and v_lifecycle_ok and v_proposals_ok and v_terminal_audit_ok
      and (v_residue->>'http_requests')::integer = 0
      and (v_residue->>'embedding_jobs')::integer = 0
      and (v_residue->>'pending_jobs')::integer = 0
      and (v_residue->>'failure_rows')::integer = 0
      and (v_residue->>'other_active_fences')::integer = 0,
      false
    );
    if not v_target_ok then
      v_invalid_proof_count := v_invalid_proof_count + 1;
    end if;

    v_targets := v_targets || jsonb_build_array(jsonb_build_object(
      'ordinal', coalesce(v_request.batch_ordinal, 1),
      'request_id', v_request.id,
      'table', v_request.target_table,
      'id', v_request.target_id,
      'version', v_request.target_version,
      'status', v_request.status,
      'phase', v_request.phase,
      'source_baseline_snapshot_sha256',
        v_request.source_baseline_snapshot_sha256,
      'expected_snapshot_sha256', v_request.expected_snapshot_sha256,
      'completed_snapshot_sha256', v_request.completed_snapshot_sha256,
      'primary_matches', v_primary_ok,
      'terminal_snapshot_matches', v_snapshot_ok,
      'proposals_committed', v_proposals_ok,
      'derivative_fresh', v_derivative_fresh,
      'lifecycle_complete', v_lifecycle_ok,
      'terminal_audit_present', v_terminal_audit_ok,
      'residue', v_residue,
      'causal_terminal_proof', v_target_ok
    ));
  end loop;

  if v_completed_count = v_target_count and v_invalid_proof_count = 0 then
    v_status := 'completed';
    v_code := 'DERIVATIVE_BATCH_COMPLETED';
  else
    v_status := 'failed';
    v_code := 'DERIVATIVE_BATCH_CAUSAL_PROOF_MISMATCH';
  end if;

  return jsonb_build_object(
    'ok', v_status = 'completed',
    'schema_version', 'dataset-derivative-rebuild-batch-status.v2',
    'reference_id', p_batch_id,
    'reference_kind', case when v_is_batch then 'batch' else 'request' end,
    'batch_id', case when v_is_batch then p_batch_id else null end,
    'request_id', case when v_is_batch then null else p_batch_id end,
    'status', v_status,
    'code', v_code,
    'proof_level', 'causal_terminal',
    'causal_terminal_proof', v_status = 'completed',
    'target_count', v_target_count,
    'flow_count', v_flow_count,
    'process_count', v_process_count,
    'completed_count', v_completed_count,
    'nonterminal_count', v_nonterminal_count,
    'failed_count', v_failed_count,
    'invalid_proof_count', v_invalid_proof_count,
    'targets', v_targets,
    'proof_sha256', util.dataset_flow_identity_sha256(v_targets)
  );
end;
$$;


ALTER FUNCTION util.read_dataset_derivative_rebuild_batch_any(p_actor_user_id uuid, p_batch_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION read_dataset_derivative_rebuild_batch_any(p_actor_user_id uuid, p_batch_id uuid); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.read_dataset_derivative_rebuild_batch_any(p_actor_user_id uuid, p_batch_id uuid) IS 'Private dynamic derivative proof for either an exact 1..50 batch id or one exact unbatched compensation request id. Unlike the retained Step 2 reader, cardinality comes from the durable admission; terminal success still requires exact primary, proposals, audit, freshness, lifecycle, and zero-residue causal proof.';


--
-- Name: read_dataset_flow_identity_derivative_set(uuid, uuid); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.read_dataset_flow_identity_derivative_set(p_actor_user_id uuid, p_scope_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  with scope_row as (
    select scope.*
    from util.dataset_flow_identity_scopes as scope
    where scope.id = p_scope_id
      and scope.actor_user_id = p_actor_user_id
  ), base as materialized (
    select
      ledger.ordinal,
      ledger.process_id,
      ledger.process_version,
      ledger.derivative_batch_id,
      ledger.after_payload_sha256,
      ledger.manifest,
      primary_audit.created_at as primary_audit_created_at,
      process.modified_at as current_modified_at,
      snapshot.value as current_snapshot,
      original as original_request,
      original_action.payload as original_action_payload,
      original_summary.payload as original_summary_payload,
      scope.plan_sha256 as scope_plan_sha256,
      scope.operation_id as scope_operation_id
    from scope_row as scope
    join util.dataset_flow_identity_process_ledger as ledger
      on ledger.scope_id = scope.id
    join public.processes as process
      on process.id = ledger.process_id
      and btrim(process.version::text) = ledger.process_version
      and process.user_id = p_actor_user_id
      and process.state_code = 0
    cross join lateral (
      select util.dataset_derivative_rebuild_snapshot(process) as value
    ) as snapshot
    join public.command_audit_log as primary_audit
      on primary_audit.id = ledger.audit_id
      and primary_audit.actor_user_id = p_actor_user_id
      and primary_audit.command
        = 'cmd_dataset_flow_identity_process_rewrite_guarded'
    left join util.dataset_derivative_rebuild_requests as original
      on original.actor_user_id = p_actor_user_id
      and original.batch_id = ledger.derivative_batch_id
      and original.target_table = 'processes'
      and original.target_id = ledger.process_id
      and original.target_version = ledger.process_version
    left join public.command_audit_log as original_action
      on original_action.id = original.action_audit_id
    left join public.command_audit_log as original_summary
      on original_summary.id = original.summary_audit_id
  ), compensation as materialized (
    select base.ordinal, candidate.request_row
    from base
    left join lateral (
      select request as request_row
      from util.dataset_derivative_rebuild_requests as request
      where request.actor_user_id = p_actor_user_id
        and request.batch_id is null
        and request.target_table = 'processes'
        and request.target_id = base.process_id
        and request.target_version = base.process_version
        and request.plan_sha256 <> base.scope_plan_sha256
        and request.expected_json_ordered_sha256
          = base.current_snapshot->>'json_ordered_sha256'
        and request.reason_code = 'FLOW_IDENTITY_SCOPE_COMPENSATION:'
          || p_scope_id::text || ':' || base.ordinal::text
        and request.operation_id = request.action_id
        and request.operation_id ~ (
          '^FLOW_IDENTITY_SCOPE_COMPENSATION:' || p_scope_id::text || ':'
          || base.ordinal::text
          || ':[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'
        )
        and request.admitted_at > base.primary_audit_created_at
        and exists (
          select 1
          from public.command_audit_log as action_audit
          where action_audit.id = request.action_audit_id
            and action_audit.actor_user_id = p_actor_user_id
            and action_audit.command
              = 'cmd_dataset_derivative_rebuild_plan_guarded'
            and action_audit.target_table = 'processes'
            and action_audit.target_id = base.process_id
            and action_audit.target_version = base.process_version
            and action_audit.payload->>'request_id' = request.id::text
            and action_audit.payload->>'plan_sha256' = request.plan_sha256
            and action_audit.payload->>'operation_id' = request.operation_id
            and action_audit.payload->>'action_id' = request.action_id
            and action_audit.payload->>'reason_code' = request.reason_code
            and action_audit.payload->>'expected_snapshot_sha256'
              = request.expected_snapshot_sha256
        )
        and exists (
          select 1
          from public.command_audit_log as summary_audit
          where summary_audit.id = request.summary_audit_id
            and summary_audit.actor_user_id = p_actor_user_id
            and summary_audit.command
              = 'cmd_dataset_derivative_rebuild_plan_guarded'
            and summary_audit.target_table is null
            and summary_audit.payload->>'request_id' = request.id::text
            and summary_audit.payload->>'plan_sha256' = request.plan_sha256
            and summary_audit.payload->>'operation_id' = request.operation_id
            and summary_audit.payload->>'action_count' = '1'
            and summary_audit.payload->>'accepted_count' = '1'
        )
      order by request.admitted_at desc, request.id desc
      limit 1
    ) as candidate on true
    where (candidate.request_row).id is not null
  ), candidate as materialized (
    select
      base.ordinal,
      base.process_id,
      base.process_version,
      base.derivative_batch_id,
      base.after_payload_sha256,
      base.current_modified_at,
      base.current_snapshot,
      'protected_batch'::text as reference_kind,
      base.original_request as request_row,
      coalesce(
        (base.original_request).id is not null
        and (base.original_request).batch_id = base.derivative_batch_id
        and (base.original_request).batch_ordinal = 1
        and (base.original_request).batch_target_count = 1
        and (base.original_request).plan_sha256 = base.scope_plan_sha256
        and (base.original_request).operation_id = base.scope_operation_id
        and (base.original_request).reason_code = 'FLOW_IDENTITY_SCOPE:'
          || p_scope_id::text || ':' || base.ordinal::text
        and (base.original_request).admitted_at
          > base.primary_audit_created_at
        and base.original_action_payload->>'batch_id'
          = base.derivative_batch_id::text
        and base.original_action_payload->>'request_id'
          = (base.original_request).id::text
        and base.original_summary_payload->>'batch_id'
          = base.derivative_batch_id::text,
        false
      ) as lineage_ok
    from base
    union all
    select
      base.ordinal,
      base.process_id,
      base.process_version,
      base.derivative_batch_id,
      base.after_payload_sha256,
      base.current_modified_at,
      base.current_snapshot,
      'separate_compensation',
      compensation.request_row,
      true
    from base
    join compensation using (ordinal)
  ), proposal_proof as (
    select
      candidate.ordinal,
      candidate.reference_kind,
      count(proposal.*) filter (
        where proposal.status <> 'discarded'
      ) = 2
      and count(proposal.*) filter (
        where proposal.status <> 'discarded'
          and proposal.id = (candidate.request_row).markdown_proposal_id
          and proposal.proposal_kind = 'markdown'
          and proposal.status = 'committed'
          and proposal.extracted_md_sha256
            = (candidate.request_row).accepted_extracted_md_sha256
          and proposal.extracted_md_sha256
            = candidate.current_snapshot->>'extracted_md_sha256'
      ) = 1
      and count(proposal.*) filter (
        where proposal.status <> 'discarded'
          and proposal.id = (candidate.request_row).embedding_proposal_id
          and proposal.proposal_kind = 'embedding'
          and proposal.status = 'committed'
          and proposal.source_extracted_md_sha256
            = (candidate.request_row).accepted_extracted_md_sha256
          and proposal.embedding_ft_sha256
            = candidate.current_snapshot->>'embedding_ft_sha256'
          and proposal.embedding_ft_at =
            (candidate.current_snapshot->>'embedding_ft_at')::timestamp with time zone
      ) = 1 as proposals_ok
    from candidate
    left join util.dataset_derivative_rebuild_proposals as proposal
      on proposal.request_id = (candidate.request_row).id
    group by candidate.ordinal, candidate.reference_kind,
      candidate.request_row, candidate.current_snapshot
  ), terminal_audit_proof as (
    select candidate.ordinal, candidate.reference_kind,
      count(audit.*) = 1 as terminal_audit_ok
    from candidate
    left join public.command_audit_log as audit
      on audit.command = 'cmd_dataset_derivative_rebuild_terminal'
      and audit.actor_user_id = p_actor_user_id
      and audit.target_table = 'processes'
      and audit.target_id = candidate.process_id
      and audit.target_version = candidate.process_version
      and audit.payload->>'request_id' = (candidate.request_row).id::text
      and audit.payload->>'status' = 'completed'
    group by candidate.ordinal, candidate.reference_kind
  ), http_residue as (
    select candidate.ordinal, candidate.reference_kind,
      count(request.*)::integer as residue_count
    from candidate
    left join net.http_request_queue as request
      on util.dataset_derivative_rebuild_http_body_matches(
        request.body, 'processes', candidate.process_id,
        candidate.process_version
      )
    group by candidate.ordinal, candidate.reference_kind
  ), embedding_residue as (
    select candidate.ordinal, candidate.reference_kind,
      count(job.*)::integer as residue_count
    from candidate
    left join pgmq.q_embedding_jobs as job
      on job.message->>'id' = candidate.process_id::text
      and btrim(job.message->>'version') = candidate.process_version
      and job.message->>'schema' = 'public'
      and job.message->>'table' = 'processes'
      and job.message->>'embeddingColumn' = 'embedding_ft'
    group by candidate.ordinal, candidate.reference_kind
  ), pending_residue as (
    select candidate.ordinal, candidate.reference_kind,
      count(pending.*)::integer as residue_count
    from candidate
    left join util.pending_embedding_jobs as pending
      on pending.schema_name = 'public'
      and pending.table_name = 'processes'
      and pending.record_id = candidate.process_id::text
      and btrim(pending.record_version) = candidate.process_version
      and pending.embedding_column = 'embedding_ft'
      and pending.status = 'pending'
    group by candidate.ordinal, candidate.reference_kind
  ), failure_residue as (
    select candidate.ordinal, candidate.reference_kind,
      count(failure.*)::integer as residue_count
    from candidate
    left join util.embedding_job_failures as failure
      on failure.msg_id = (candidate.request_row).embedding_queue_msg_id
    group by candidate.ordinal, candidate.reference_kind
  ), fence_residue as (
    select candidate.ordinal, candidate.reference_kind,
      count(active.*)::integer as residue_count
    from candidate
    left join util.dataset_derivative_rebuild_requests as active
      on active.id <> (candidate.request_row).id
      and active.target_table = 'processes'
      and active.target_id = candidate.process_id
      and active.target_version = candidate.process_version
      and active.status not in ('completed', 'stale', 'failed')
    group by candidate.ordinal, candidate.reference_kind
  ), evaluated as materialized (
    select
      candidate.*,
      coalesce(proposal_proof.proposals_ok, false) as proposals_ok,
      coalesce(terminal_audit_proof.terminal_audit_ok, false)
        as terminal_audit_ok,
      jsonb_build_object(
        'http_requests', coalesce(http_residue.residue_count, 0),
        'embedding_jobs', coalesce(embedding_residue.residue_count, 0),
        'pending_jobs', coalesce(pending_residue.residue_count, 0),
        'failure_rows', coalesce(failure_residue.residue_count, 0),
        'other_active_fences', coalesce(fence_residue.residue_count, 0)
      ) as residue,
      coalesce(
        candidate.lineage_ok
        and (candidate.request_row).status = 'completed'
        and candidate.current_snapshot->>'user_id' = p_actor_user_id::text
        and candidate.current_snapshot->>'state_code' = '0'
        and candidate.current_modified_at
          = (candidate.request_row).expected_modified_at
        and candidate.current_snapshot->>'json_sha256'
          = (candidate.request_row).expected_json_sha256
        and candidate.current_snapshot->>'json_ordered_sha256'
          = (candidate.request_row).expected_json_ordered_sha256
        and candidate.current_snapshot->>'snapshot_sha256'
          = (candidate.request_row).completed_snapshot_sha256
        and candidate.current_snapshot->>'extracted_md_sha256' is not null
        and candidate.current_snapshot->>'embedding_ft_sha256' is not null
        and (candidate.current_snapshot->>'embedding_ft_at')::timestamp with time zone
          > coalesce((candidate.request_row).before_embedding_ft_at,
            '-infinity'::timestamp with time zone)
        and (candidate.request_row).phase = 'completed'
        and (candidate.request_row).markdown_request_id is not null
        and (candidate.request_row).markdown_dispatched_at is not null
        and (candidate.request_row).markdown_response_status between 200 and 299
        and (candidate.request_row).markdown_response_received_at
          >= (candidate.request_row).markdown_dispatched_at
        and (candidate.request_row).markdown_proposal_id is not null
        and (candidate.request_row).accepted_extracted_md_sha256 is not null
        and (candidate.request_row).embedding_queue_msg_id is not null
        and (candidate.request_row).embedding_queued_at
          >= (candidate.request_row).markdown_response_received_at
        and (candidate.request_row).embedding_proposal_id is not null
        and (candidate.request_row).completed_at
          >= (candidate.request_row).embedding_queued_at
        and (candidate.request_row).terminal_at
          >= (candidate.request_row).completed_at
        and (candidate.request_row).drained_at
          >= (candidate.request_row).completed_at
        and coalesce(proposal_proof.proposals_ok, false)
        and coalesce(terminal_audit_proof.terminal_audit_ok, false)
        and coalesce(http_residue.residue_count, 0) = 0
        and coalesce(embedding_residue.residue_count, 0) = 0
        and coalesce(pending_residue.residue_count, 0) = 0
        and coalesce(failure_residue.residue_count, 0) = 0
        and coalesce(fence_residue.residue_count, 0) = 0,
        false
      ) as causal_terminal_proof
    from candidate
    left join proposal_proof using (ordinal, reference_kind)
    left join terminal_audit_proof using (ordinal, reference_kind)
    left join http_residue using (ordinal, reference_kind)
    left join embedding_residue using (ordinal, reference_kind)
    left join pending_residue using (ordinal, reference_kind)
    left join failure_residue using (ordinal, reference_kind)
    left join fence_residue using (ordinal, reference_kind)
  ), ranked as (
    select evaluated.*,
      case
        when evaluated.reference_kind = 'protected_batch'
          and (
            evaluated.causal_terminal_proof
            or (evaluated.request_row).status
              not in ('completed', 'stale', 'failed')
          ) then 0
        when evaluated.reference_kind = 'separate_compensation' then 1
        else 2
      end as proof_rank
    from evaluated
  ), effective as (
    select distinct on (ranked.ordinal) ranked.*
    from ranked
    order by ranked.ordinal, ranked.proof_rank
  ), target_payload as (
    select effective.ordinal,
      jsonb_build_object(
        'ordinal', effective.ordinal,
        'id', effective.process_id,
        'version', effective.process_version,
        'original_batch_id', effective.derivative_batch_id,
        'effective_reference_id', (effective.request_row).id,
        'effective_reference_kind', effective.reference_kind,
        'status', case
          when effective.causal_terminal_proof then 'completed'
          when (effective.request_row).status
            not in ('completed', 'stale', 'failed') then 'pending'
          else 'failed' end,
        'request_status', coalesce((effective.request_row).status, 'missing'),
        'phase', coalesce((effective.request_row).phase, 'missing'),
        'lineage_ok', effective.lineage_ok,
        'proposals_committed', effective.proposals_ok,
        'terminal_audit_present', effective.terminal_audit_ok,
        'residue', effective.residue,
        'current_snapshot_sha256',
          effective.current_snapshot->>'snapshot_sha256',
        'current_json_ordered_sha256',
          effective.current_snapshot->>'json_ordered_sha256',
        'causal_terminal_proof', effective.causal_terminal_proof
      ) as value,
      jsonb_build_object(
        'ordinal', effective.ordinal,
        'table', 'processes',
        'id', effective.process_id,
        'version', effective.process_version,
        'original_batch_id', effective.derivative_batch_id,
        'original_status', case
          when (base.original_request).id is null then 'missing'
          when (base.original_request).status = 'stale' then 'stale'
          else 'failed' end,
        'original_code', coalesce(
          nullif(btrim((base.original_request).last_error->>'code'), ''),
          case
            when (base.original_request).id is null
              then 'DERIVATIVE_BATCH_CHILD_MISSING'
            when (base.original_request).status = 'stale'
              then 'DERIVATIVE_BATCH_CHILD_STALE'
            when (base.original_request).status = 'failed'
              then 'DERIVATIVE_BATCH_CHILD_FAILED'
            else 'DERIVATIVE_CAUSAL_TERMINAL_PROOF_FAILED'
          end
        ),
        'latest_compensation_request_id', case
          when effective.reference_kind = 'separate_compensation'
            then (effective.request_row).id else null end,
        'latest_compensation_status', case
          when effective.reference_kind = 'separate_compensation'
            then (effective.request_row).status else null end,
        'latest_compensation_plan_sha256', case
          when effective.reference_kind = 'separate_compensation'
            then (effective.request_row).plan_sha256 else null end,
        'desired_payload_sha256', effective.after_payload_sha256,
        'current_json_ordered_sha256',
          effective.current_snapshot->>'json_ordered_sha256',
        'current_snapshot_sha256',
          effective.current_snapshot->>'snapshot_sha256',
        'current_modified_at', effective.current_snapshot->>'modified_at',
        'components', jsonb_build_array('extracted_md', 'embedding_ft'),
        'reason_code', 'FLOW_IDENTITY_SCOPE_COMPENSATION:'
          || p_scope_id::text || ':' || effective.ordinal::text,
        'operation_id_prefix', 'FLOW_IDENTITY_SCOPE_COMPENSATION:'
          || p_scope_id::text || ':' || effective.ordinal::text || ':',
        'requires_new_plan_freeze_approval', true,
        'automatic_retry', false
      ) as compensation_value,
      effective.causal_terminal_proof,
      coalesce(
        (effective.request_row).status
          not in ('completed', 'stale', 'failed'),
        false
      ) as is_pending
    from effective
    join base using (ordinal)
  ), aggregate_payload as (
    select
      count(*)::integer as target_count,
      count(*) filter (where causal_terminal_proof)::integer
        as completed_count,
      count(*) filter (
        where not causal_terminal_proof and is_pending
      )::integer as pending_count,
      count(*) filter (
        where not causal_terminal_proof and not is_pending
      )::integer as failed_count,
      coalesce(jsonb_agg(value order by ordinal), '[]'::jsonb) as targets,
      coalesce(jsonb_agg(compensation_value order by ordinal) filter (
        where not causal_terminal_proof and not is_pending
      ), '[]'::jsonb) as compensation_targets,
      coalesce((select process_count from scope_row), 0)::integer
        as expected_target_count
    from target_payload
  )
  select jsonb_build_object(
    'ok', aggregate_payload.target_count > 0
      and aggregate_payload.target_count
        = aggregate_payload.expected_target_count
      and aggregate_payload.completed_count
        + aggregate_payload.pending_count
        + aggregate_payload.failed_count
        = aggregate_payload.target_count
      and aggregate_payload.failed_count = 0,
    'schema_version', 'dataset-flow-identity-derivative-set-proof.v1',
    'scope_id', p_scope_id,
    'status', case
      when aggregate_payload.target_count = 0
        or aggregate_payload.target_count
          <> aggregate_payload.expected_target_count
        or aggregate_payload.completed_count
          + aggregate_payload.pending_count
          + aggregate_payload.failed_count
          <> aggregate_payload.target_count then 'failed'
      when aggregate_payload.failed_count > 0 then 'compensation_required'
      when aggregate_payload.pending_count > 0 then 'pending'
      else 'completed' end,
    'target_count', aggregate_payload.target_count,
    'completed_count', aggregate_payload.completed_count,
    'pending_count', aggregate_payload.pending_count,
    'failed_count', aggregate_payload.failed_count,
    'causal_terminal_proof', aggregate_payload.target_count > 0
      and aggregate_payload.target_count
        = aggregate_payload.expected_target_count
      and aggregate_payload.completed_count = aggregate_payload.target_count
      and aggregate_payload.pending_count = 0
      and aggregate_payload.failed_count = 0,
    'targets', aggregate_payload.targets,
    'compensation_targets', aggregate_payload.compensation_targets,
    'proof_sha256', util.dataset_flow_identity_sha256(
      aggregate_payload.targets
    )
  )
  from aggregate_payload
$_$;


ALTER FUNCTION util.read_dataset_flow_identity_derivative_set(p_actor_user_id uuid, p_scope_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION read_dataset_flow_identity_derivative_set(p_actor_user_id uuid, p_scope_id uuid); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.read_dataset_flow_identity_derivative_set(p_actor_user_id uuid, p_scope_id uuid) IS 'Private set-based Step 3 derivative proof. One relational pass evaluates all protected children and exact separately approved compensation requests, aggregates proposal/audit/queue/fence residue once, and emits ordered proof arrays without per-child reader calls or repeated JSON concatenation.';


--
-- Name: record_dataset_derivative_rebuild_terminal(uuid); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.record_dataset_derivative_rebuild_terminal(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  select
    'cmd_dataset_derivative_rebuild_terminal',
    request.actor_user_id,
    request.target_table,
    request.target_id,
    request.target_version,
    jsonb_build_object(
      'record_type', 'terminal',
      'schema_version', 'dataset-derivative-rebuild-status.v1',
      'request_id', request.id,
      'batch_id', request.batch_id,
      'batch_ordinal', request.batch_ordinal,
      'batch_target_count', request.batch_target_count,
      'source_baseline_snapshot_sha256',
        request.source_baseline_snapshot_sha256,
      'plan_sha256', request.plan_sha256,
      'operation_id', request.operation_id,
      'action_id', request.action_id,
      'status', request.status,
      'phase', request.phase,
      'plan_request_sha256', request.plan_request_sha256,
      'action_request_sha256', request.action_request_sha256,
      'completed_snapshot_sha256', request.completed_snapshot_sha256,
      'terminal_at', request.terminal_at,
      'drained_at', request.drained_at,
      'error', request.last_error,
      'quarantine', jsonb_build_object(
        'http_requests', request.quarantined_http_requests,
        'embedding_jobs', request.quarantined_embedding_jobs,
        'pending_jobs', request.quarantined_pending_jobs
      )
    )
  from util.dataset_derivative_rebuild_requests as request
  where request.id = p_request_id
    and request.status in ('completed', 'stale', 'failed')
  on conflict do nothing;
end;
$$;


ALTER FUNCTION util.record_dataset_derivative_rebuild_terminal(p_request_id uuid) OWNER TO postgres;

--
-- Name: stage_dataset_derivative_rebuild_write(); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.stage_dataset_derivative_rebuild_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind text := tg_argv[0];
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_proposal util.dataset_derivative_rebuild_proposals%rowtype;
  v_permitted boolean := false;
begin
  if tg_table_schema <> 'public'
    or tg_table_name not in ('flows', 'processes') then
    raise exception using
      errcode = '22023',
      message = 'Unsupported derivative rebuild staging target';
  end if;

  select request.*
  into v_request
  from util.dataset_derivative_rebuild_requests as request
  where request.target_table = tg_table_name
    and request.target_id = old.id
    and request.target_version = btrim(old.version::text)
    and request.status not in ('completed', 'stale', 'failed')
  limit 1;

  if v_request.id is null then
    return new;
  end if;

  if not util.dataset_derivative_rebuild_primary_matches(v_request) then
    raise exception using
      errcode = '40001',
      message = 'Derivative rebuild primary fingerprint drifted';
  end if;

  select proposal.*
  into v_proposal
  from util.dataset_derivative_rebuild_permits as permit
  join util.dataset_derivative_rebuild_proposals as proposal
    on proposal.id = permit.proposal_id
   and proposal.request_id = permit.request_id
  where permit.request_id = v_request.id
    and permit.permit_kind = v_kind
    and permit.backend_pid = pg_catalog.pg_backend_pid()
    and permit.transaction_id = pg_catalog.txid_current()
    and proposal.proposal_kind = v_kind
    and (
      (v_kind = 'markdown' and proposal.status = 'accepted')
      or (v_kind = 'embedding' and proposal.status = 'captured')
    )
  limit 1;

  if v_proposal.id is not null then
    if v_kind = 'markdown' then
      v_permitted := new.extracted_md is not null
        and util.dataset_derivative_rebuild_sha256(new.extracted_md)
          = v_proposal.extracted_md_sha256;
    elsif v_kind = 'embedding' then
      v_permitted := new.embedding_ft is not null
        and new.embedding_ft_at is not null
        and util.dataset_derivative_rebuild_sha256(new.embedding_ft::text)
          = v_proposal.embedding_ft_sha256
        and util.dataset_derivative_rebuild_sha256(new.extracted_md)
          = v_proposal.source_extracted_md_sha256;
    end if;

    if not v_permitted then
      raise exception using
        errcode = '22000',
        message = 'Derivative rebuild permit does not match staged proposal';
    end if;
    return new;
  end if;

  if v_kind = 'markdown' then
    if new.extracted_md is null then
      raise exception using
        errcode = '23502',
        message = 'Fenced Markdown proposal must be non-null';
    end if;

    insert into util.dataset_derivative_rebuild_proposals (
      request_id,
      proposal_kind,
      extracted_md,
      extracted_md_sha256
    ) values (
      v_request.id,
      'markdown',
      new.extracted_md,
      util.dataset_derivative_rebuild_sha256(new.extracted_md)
    );
    new.extracted_md := old.extracted_md;
  elsif v_kind = 'embedding' then
    if new.embedding_ft is null or new.embedding_ft_at is null then
      raise exception using
        errcode = '23502',
        message = 'Fenced embedding proposal must carry vector and timestamp';
    end if;

    insert into util.dataset_derivative_rebuild_proposals (
      request_id,
      proposal_kind,
      embedding_ft,
      embedding_ft_sha256,
      embedding_ft_at,
      source_extracted_md_sha256
    ) values (
      v_request.id,
      'embedding',
      new.embedding_ft,
      util.dataset_derivative_rebuild_sha256(new.embedding_ft::text),
      new.embedding_ft_at,
      coalesce(
        v_request.accepted_extracted_md_sha256,
        util.dataset_derivative_rebuild_sha256(old.extracted_md)
      )
    );
    new.embedding_ft := old.embedding_ft;
    new.embedding_ft_at := old.embedding_ft_at;
  else
    raise exception using
      errcode = '22023',
      message = 'Unsupported derivative staging kind';
  end if;

  return new;
end;
$$;


ALTER FUNCTION util.stage_dataset_derivative_rebuild_write() OWNER TO postgres;

--
-- Name: command_audit_log; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.command_audit_log (
    id bigint NOT NULL,
    command text NOT NULL,
    actor_user_id uuid NOT NULL,
    target_table text,
    target_id uuid,
    target_version text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.command_audit_log OWNER TO postgres;

--
-- Name: TABLE command_audit_log; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.command_audit_log IS 'Validation-only migration for database-engine preview branch cutover on 2026-04-14.';


--
-- Name: command_audit_log_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.command_audit_log ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.command_audit_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: comments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.comments (
    review_id uuid NOT NULL,
    reviewer_id uuid DEFAULT auth.uid() NOT NULL,
    "json" json,
    created_at timestamp with time zone DEFAULT now(),
    modified_at timestamp with time zone DEFAULT now(),
    state_code integer DEFAULT 0,
    CONSTRAINT comments_state_code_check CHECK ((state_code = ANY (ARRAY['-3'::integer, '-2'::integer, '-1'::integer, 0, 1, 2])))
);


ALTER TABLE public.comments OWNER TO postgres;

--
-- Name: dataset_review_submit_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dataset_review_submit_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    dataset_table text NOT NULL,
    dataset_id uuid NOT NULL,
    dataset_version text NOT NULL,
    revision_checksum text NOT NULL,
    policy_profile text DEFAULT 'review_submit_fast.v1'::text NOT NULL,
    report_schema_version text DEFAULT 'review_submit_gate_report.v1'::text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    requested_by uuid NOT NULL,
    gate_run_id uuid,
    gate_worker_job_id uuid,
    submit_worker_job_id uuid,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error_code text,
    last_error_message text,
    last_error_details jsonb,
    result jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    modified_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT dataset_review_submit_requests_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT dataset_review_submit_requests_checksum_check CHECK ((revision_checksum ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT dataset_review_submit_requests_last_error_details_check CHECK (((last_error_details IS NULL) OR (jsonb_typeof(last_error_details) = 'object'::text))),
    CONSTRAINT dataset_review_submit_requests_result_check CHECK (((result IS NULL) OR (jsonb_typeof(result) = 'object'::text))),
